window.LUMINA = {"generated":"2026-11-07","topics":[{"id":"gynecologie","label":"Gynécologie","short":"Gynécologie","color":"#c2185b","description":"Photobiomodulation en gynécologie et obstétrique : sécheresse et atrophie vulvovaginale (syndrome génito-urinaire de la ménopause), effets secondaires après cancer gynécologique ou mammaire, douleurs vulvaires et pelviennes, périnée et allaitement, fertilité.","cadence":"hebdomadaire","since":"2020-01-01","status":"actif","hero":"la gynécologie","exclusions_note":"lasers vaginaux ablatifs CO2 et Er:YAG (ce n'est pas de la photobiomodulation), lymphœdème du membre supérieur, études animales sans rapport gynécologique…","subgroups":["GSM","onco","vulve","pelvien","obstétrique","fertilité"],"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"low-intensity laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"light-emitting diode\"[tiab] OR \"laser acupuncture\"[tiab]) AND (\"vagina*\"[tiab] OR \"vulva*\"[tiab] OR \"vulvodynia\"[tiab] OR \"dyspareunia\"[tiab] OR \"genitourinary syndrome\"[tiab] OR \"menopaus*\"[tiab] OR \"lichen sclerosus\"[tiab] OR \"gynecolog*\"[tiab] OR \"gynaecolog*\"[tiab] OR \"cervical cancer\"[tiab] OR \"endometrial cancer\"[tiab] OR \"ovar*\"[tiab] OR \"uterine\"[tiab] OR \"dysmenorrh*\"[tiab] OR \"endometriosis\"[tiab] OR \"pelvic pain\"[tiab] OR \"perine*\"[tiab] OR \"episiotomy\"[tiab] OR \"nipple\"[tiab] OR \"breastfeeding\"[tiab] OR \"polycystic ovary\"[tiab] OR \"infertil*\"[tiab] OR \"urinary incontinence\"[tiab] OR \"Genital Diseases, Female\"[MeSH])","n_raw":213,"n_excluded":115},{"id":"mucite-orale","label":"Mucite buccale","short":"Mucite","color":"#d9480f","description":"Prévention et traitement des mucites induites par la chimiothérapie, la radiothérapie ou la greffe de cellules souches hématopoïétiques par photobiomodulation (PBM / LLLT).","cadence":"hebdomadaire","since":"2024-01-01","status":"actif","hero":"la mucite","exclusions_note":"aphtes récurrents, stomatites prothétiques, péri-implantite, laser haute intensité en rhumatologie…","subgroups":null,"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"laser therapy\"[tiab] OR \"PBMT\"[tiab]) AND (\"mucositis\"[tiab] OR \"Stomatitis\"[MeSH] OR \"Mucositis\"[MeSH]) NOT (\"peri-implant\"[tiab] OR \"periimplant\"[tiab] OR \"peri-implantitis\"[tiab])","n_raw":140,"n_excluded":30},{"id":"neuropathie-peripherique","label":"Neuropathies périphériques","short":"Neuropathies","color":"#2a78d6","description":"Prévention et traitement des neuropathies périphériques par photobiomodulation : neuropathie induite par la chimiothérapie (CIPN), neuropathie diabétique et autres atteintes nerveuses périphériques.","cadence":"hebdomadaire","since":"2024-01-01","status":"actif","hero":"les neuropathies périphériques","exclusions_note":"ulcères du pied diabétique, glaucome, lésions de la moelle épinière, radiculopathies (réservées au futur thème musculo-squelettique)…","subgroups":null,"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"laser therapy\"[tiab] OR \"light-emitting diode\"[tiab] OR \"high-intensity laser\"[tiab]) AND (\"peripheral neuropathy\"[tiab] OR \"polyneuropathy\"[tiab] OR \"Peripheral Nervous System Diseases\"[MeSH] OR \"neuropathic\"[tiab] OR \"neuropathy\"[tiab] OR \"CIPN\"[tiab]) NOT (\"trigeminal\"[ti] OR \"burning mouth\"[ti])","n_raw":108,"n_excluded":45},{"id":"dermatologie","label":"Dermatologie","short":"Dermatologie","description":"Radiodermite, cicatrisation, alopécie, acné et autres indications cutanées.","status":"à venir"},{"id":"musculo-squelettique","label":"Musculo-squelettique","short":"Musculo-squelettique","description":"Douleurs et pathologies de l'appareil locomoteur : tendinopathies, arthrose, lombalgies, troubles temporo-mandibulaires.","status":"à venir"}],"articles":[{"pmid":"42857478","title_fr":"Rééducation physique de la morbidité périnéale post-partum : méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Périnée post-partum","l1":"Neuf essais : la TENS réduit la douleur périnéale à court terme (DMS −1,19), pas le laser basse énergie (DMS −0,16).","l2":"Méta-analyse PRISMA 2020 (recherche jusqu'en avril 2026). Le refroidissement est favorable sur l'œdème et la douleur immédiate.","l3":{"points":["LLLT : DMS −0,16 (IC95 % −0,52 à 0,19)."],"limites":["Peu d'essais par modalité."],"pratique":"—"},"topic":"gynecologie","title":"Physical Rehabilitation for Postpartum Perineal Morbidity After Episiotomy and Childbirth-Related Perineal Trauma: A Systematic Review and Meta-analysis of Randomized Controlled Trials.","journal":"Orthopedic reviews","journal_abbr":"Orthop Rev (Pavia)","authors":["Alnashwan A","Alenezi YM","Alruwaili HM","et al."],"date":"2026-10-07","year":2026,"week":"2026-S41","doi":"10.52965/001c.171902","pmcid":"PMC13652543","license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Postpartum perineal trauma commonly causes pain and delayed maternal recovery, yet randomized evidence supporting rehabilitation interventions remains fragmented."},{"label":"OBJECTIVE","text":"To compare the effectiveness of physical and electrophysical rehabilitation modalities for postpartum perineal pain, wound healing, and oedema following episiotomy or childbirth-related perineal trauma."},{"label":"METHODS","text":"This systematic review and meta-analysis was conducted in accordance with PRISMA 2020. PubMed/MEDLINE, Embase, CENTRAL, CINAHL, ClinicalTrials.gov, and ICTRP were searched from inception to April 7, 2026. Randomized controlled trials evaluating rehabilitation modalities were included. Random-effects meta-analysis was performed where appropriate, and methodological quality was assessed using the Cochrane Risk of Bias 2 tool."},{"label":"RESULTS","text":"Nine randomized controlled trials were included, seven of which contributed to quantitative synthesis. TENS significantly reduced short-term postpartum perineal pain compared with control (SMD -1.19, 95% CI -1.83 to -0.55). LLLT showed no significant benefit (SMD -0.16, 95% CI -0.52 to 0.19), while therapeutic ultrasound demonstrated no significant reduction in persistent pain. Narrative evidence indicated favorable effects of cooling interventions on oedema, immediate pain relief, and maternal satisfaction. Two studies were judged at low risk of bias, five had some concerns, and two were at high risk of bias."},{"label":"CONCLUSIONS","text":"This review provides the first comparative synthesis of randomized evidence evaluating physical and electrophysical rehabilitation modalities for postpartum perineal morbidity. The strongest evidence currently supports TENS for short-term pain relief, whereas cooling interventions appear beneficial for local symptom management. Larger, rigorously designed randomized trials are required to establish evidence-based rehabilitation strategies for postpartum perineal recovery."}],"keywords":["Postpartum perineal trauma","Rehabilitation"]},{"pmid":"42889154","title_fr":"Paramètres et mécanisme de la photothérapie LED dans un modèle de vaginose bactérienne (rat)","type":"preclinical","level":5,"pop":"—","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[405,415,430,630,850],"n":null,"effect":"favorable","theme":"Infections vulvovaginales","l1":"La LED bleue 415 nm (50 mW/cm², 30 min) détruit Gardnerella vaginalis et E. coli sans toxicité pour les cellules vaginales, et réduit l'inflammation chez le rat.","l2":"Comparaison de cinq longueurs d'onde ; le 415 nm est le plus efficace. Mécanisme : production d'espèces réactives de l'oxygène dans les bactéries et fragmentation de leur ADN.","l3":{"points":["Dose optimale : 90 J/cm²."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"Parameter optimization and mechanism of action of Light‑Emitting Diode phototherapy in a rat model of bacterial vaginosis.","journal":"Frontiers in cellular and infection microbiology","journal_abbr":"Front Cell Infect Microbiol","authors":["Chen X","Qi X","Ma Y","et al."],"date":"2026-10-01","year":2026,"week":"2026-S40","doi":"10.3389/fcimb.2026.1836549","pmcid":"PMC13668606","license":"cc by","oa":false,"pdf":"pdfs/42889154.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"To investigate the antibacterial effects of LED phototherapy on Gardnerella vaginalis (Gv) and Escherichia coli (E. coli), optimize key irradiation conditions for LED phototherapy by establishing an in vivo infection model, and evaluate its feasibility for treating bacterial vaginosis."},{"label":"METHODS","text":"Bacterial colonies were irradiated with LEDs at different wavelengths (405 nm, 415 nm, 430 nm, 630 nm, 850 nm). Bacterial survival and morphology were assessed via colony counting, SYTO9/PI fluorescence staining, and scanning electron microscopy. Intracellular oxidative stress and antioxidant systems were quantitatively measured. Genomic DNA integrity was analyzed by agarose gel electrophoresis to validate the bactericidal mechanism. The effects on vaginal epithelial cell (VK2/E6E7). viability were assessed using CCK-8 assays, ROS detection, and SYTO9/PI live/dead staining. A rat model of bacterial vaginosis was established to optimize vaginal LED irradiation parameters, with inflammatory cell infiltration assessed by H&E staining, and expression levels of IL-1β and TNF-α in vaginal tissues evaluated by immunohistochemistry (IHC) with semi-quantitative image analysis."},{"label":"RESULTS","text":"Among the tested wavelengths, 415 nm LED demonstrated optimal antibacterial efficacy. At 50 mW/cm² intensity for 30 min, it exhibited the most significant bactericidal effect against Gv and E. coli. This condition induced substantial ROS production in bacteria, inhibited SOD and CAT activity, leading to bacterial cell membrane damage and genomic DNA fragmentation. This irradiation condition exhibited no significant toxicity to vaginal epithelial cells VK2/E6E7. In a rat model, LED treatment under these conditions significantly improved vaginal inflammation symptoms and pathological histological findings, while reducing IL- 1β and TNF-α expression."},{"label":"CONCLUSION","text":"This study established the optimal LED irradiation conditions for BV-associated pathogens as 415 nm wavelength, 50 mW/cm² power, and 30 min exposure (irradiation dose 90 J/cm²). These conditions exert significant antibacterial effects against Gv and E. coli by inducing bacterial ROS production, while maintaining excellent cellular safety. In rat cell models, it simultaneously demonstrated anti-inflammatory and tissue repair potential in both bacterial and in vivo settings, offering a novel therapeutic strategy for the clinical management of bacterial vaginosis."}],"keywords":["Escherichia coli","Gardnerella vaginalis","Light‑Emitting Diode","bacterial vaginitis","bactericidal mechanism"]},{"pmid":"42809639","title_fr":"Nouvelles interventions régénératives en médecine sexuelle : recommandations de l'ICSM 2024","type":"guideline","level":1,"pop":"mixte","ctx":["général"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Recommandations","key":true,"l1":"La 5e consultation internationale de médecine sexuelle juge les preuves de la PBM (et des autres techniques régénératives) insuffisantes pour une recommandation, malgré une bonne tolérance.","l2":"Comité d'experts : cellules souches, PRP, électrostimulation, PBM, radiofréquence, laser et ondes de choc. Les études souffrent de limites méthodologiques importantes. Les preuves les plus fortes concernent les ondes de choc dans la dysfonction érectile et le laser CO2 dans le syndrome génito-urinaire.","l3":{"points":["Pas de consensus pour recommander la PBM en médecine sexuelle."],"limites":["Avis d'experts."],"pratique":"Proposer la PBM comme option complémentaire, en expliquant le niveau de preuve encore limité."},"topic":"gynecologie","title":"New regenerative interventions and treatment targets in sexual medicine: recommendations from the Fifth International Consultation on Sexual Medicine (ICSM 2024).","journal":"Sexual medicine reviews","journal_abbr":"Sex Med Rev","authors":["Chubak BM","Chan CW","Feghali J","et al."],"date":"2026-09-29","year":2026,"week":"2026-S40","doi":"10.1093/sxmrev/qeag048","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"OBJECTIVES","text":"To describe the array of regenerative interventions seeking to reverse the causes and provide curative treatment for male and female sexual dysfunctions that have been studied and are available for purchase within the medical marketplace, including their treatment targets, mechanisms of action, and outcomes data, with particular attention to the context in which they are applied."},{"label":"METHODS","text":"A committee of experts conducted a comprehensive, review of the relevant literature, focusing on publications since the topic of novel treatment targets was last addressed by the International Consultation on Sexual Medicine."},{"label":"RESULTS","text":"Since the ICSM 2010, cell- and energy-based regenerative medical interventions have grown in popularity, with their therapeutic promise and availability in the medical marketplace outpacing the conduct of research to support their use as treatments for sexual dysfunction. While clinical trials and the test of time suggest they are generally safe and well-tolerated, the published studies that consider the efficacy of stem cell, platelet rich plasma, electrical stimulation, photobiomodulation, radiofrequency, laser, and shockwave therapies for sexual health problems suffer from significant methodological limitations. The evidence is strongest for low-intensity shockwave treatment of the penis for erectile dysfunction, followed by vaginal CO2 laser treatment for genitourinary syndrome of menopause, but is not sufficiently robust to reach consensus agreement regarding their clinical recommendation at this time."},{"label":"DISCUSSION","text":"Cell- and energy-based regenerative medical treatments have enormous popular appeal, but at present the scientific evidence for their use to treat sexual problems is insufficient to reach a consensus agreement regarding their clinical use. Future studies should not only consider clinical questions of indication, dosage, and efficacy, but also explore the practical bioethics of conducting translational research within the international medical marketplace."}],"keywords":["bioethics","extracorporeal shockwave","laser therapy","photobiomodulation","platelet-rich plasma","radiofrequency therapy","regenerative medicine","sexual dysfunction","stem cell"]},{"pmid":"42742785","title_fr":"PBM contre le traumatisme périnéal après accouchement : protocole d'essai randomisé","type":"protocol","level":0,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[808],"n":null,"effect":"—","theme":"Périnée post-partum","l1":"Protocole d'essai en double aveugle : une séance de laser 808 nm dans les 12 h suivant l'accouchement contre la douleur périnéale et l'œdème vulvaire.","l2":"Suivi jusqu'à 3 mois : douleur, œdème, fonctionnement maternel, incontinence, sexualité.","l3":{"points":["Analyse en intention de traiter, modèles mixtes."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Efficacy of photobiomodulation in perineal trauma after vaginal delivery: a protocol for a randomized, blinded clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Rodrigues A","Brilhante M","Lima E","et al."],"date":"2026-09-15","year":2026,"week":"2026-S38","doi":"10.1007/s10103-026-05036-7","pmcid":"PMC13577959","license":"cc by","oa":true,"pdf":"pdfs/42742785.pdf","cited_by":0,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"OBJECTIVE","text":"To evaluate the efficacy of photobiomodulation (PBM) in reducing perineal pain and obstetric vulvar edema, as well os its effects on maternal functioning during the immediate postpartum period."},{"label":"METHODS","text":"This randomized, controlled, double-blind clinical trial protocol will include women aged over 15 years, within 12 h after vaginal delivery, presenting with first- or second-degree perineal trauma and/or vulvar edema and pain ≥ 3 on the Numeric Rating Scale. Participants will be randomized in blocks of four to receive PBM or a sham intervention alongside usual postpartum care. A single PBM session will be performed using 808-nm infrared laser light at an output power of 100 mW. Assessments will be performed at baseline, immediately after the intervention, 12 h, 40 days, and three months postpartum. Outcomes will include pain, pressure pain threshold, vulvar edema area, maternal functioning, treatment satisfaction, urinary incontinence, and sexual function. Statistical analysis will follow the intention-to-treat principle using linear mixed-effects models, with group, time, and group × time interaction as fixed effects and participant as a random effect. Post-hoc comparisons will use Bonferroni correction, with a significance level of 5%."},{"label":"CONCLUSION","text":"PBM is expected to reduce perineal pain and vulvar edema and improve maternal functioning. The randomized design, sham control, blinded outcome assessment, and longitudinal analysis are expected to provide evidence regarding the efficacy and safety of PBM as a non-pharmacological strategy for postpartum care."},{"label":"TRIAL REGISTRATION","text":"Brazilian Clinical Trials Registry (REBEC), RBR9sgdsm2, approved on July 7, 2026."}],"keywords":["Laser","Pain","Perineal trauma.hi","Postpartum period","Postpartum women","Vaginal delivery"]},{"pmid":"42615775","title_fr":"PBM précoce contre la douleur et les lésions des mamelons : essai pilote randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"prévention","mode":["laser"],"nm":[],"n":58,"effect":"—","theme":"Allaitement","l1":"Essai pilote brésilien (58 accouchées, 4 bras dont ILIB) : un grand essai est faisable ; pas de résultat d'efficacité.","l2":"Les données ont servi à ajuster le protocole et le calcul d'effectif ; 20 % de perdues de vue.","l3":{"points":["Bras : PBM locale, ILIB, les deux, témoin."],"limites":["Pilote de faisabilité."],"pratique":"—"},"topic":"gynecologie","title":"Early photobiomodulation in nipple pain and injury during breastfeeding: pilot double-blind randomized clinical trial.","journal":"Revista gaucha de enfermagem","journal_abbr":"Rev Gaucha Enferm","authors":["Leite CCP","Rosseto EG","Castral TC"],"date":"2026-08-17","year":2026,"week":"2026-S34","doi":"10.1590/1983-1447.2026.20250247.en","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"To verify the feasibility of a randomized clinical trial to test the effects of early photobiomodulation on nipple pain and injury resulting from breastfeeding."},{"label":"METHOD","text":"External pilot study for a randomized clinical trial, conducted between June and December 2023. Postpartum women with a gestational age ≥ 37 weeks, admitted to the shared rooms of two maternity hospitals in Paraná, Brazil, were included. Participants were randomly allocated by lottery to Groups: A (local photobiomodulation); B (Intravenous Laser Irradiation of Blood - systemic); C (local and systemic photobiomodulation) or D (control group), received two sessions of the intervention, were followed up in the first month postpartum, and data were collected at five time points."},{"label":"RESULTS","text":"58 postpartum women started the study, with a loss to follow-up of 20%. The pilot study reinforced the feasibility of the large-scale clinical trial and allowed for the adaptation of the protocol, the adjustment of the sample estimate, and the standardization of guidelines."},{"label":"CONCLUSION","text":"Conducting a large-scale clinical trial is feasible and viable from a methodological and operational standpoint, with the potential to generate robust evidence on the role of photobiomodulation in the early management of nipple pain and injury, contributing to the reduction of maternal distress resulting from pain and injury, and preventing early weaning."}],"keywords":[]},{"pmid":"42566226","title_fr":"PBM et rééducation périnéale dans le syndrome génito-urinaire : résultats d'un essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[],"n":null,"effect":"mitigé","theme":"Syndrome génito-urinaire","l1":"Ajouter une PBM intravaginale active à la rééducation du plancher pelvien améliore la fonction sexuelle (FSFI +4,6 points) et l'incontinence (ICIQ-SF −3 points) par rapport à la PBM simulée, sans gain mesurable de force musculaire.","l2":"Essai à trois bras chez des femmes de 45 à 65 ans ménopausées depuis au moins un an : rééducation + PBM active, rééducation + PBM simulée, rééducation seule ; 16 séances de 50 minutes sur 8 semaines.\n\nLa manométrie ne montre pas de différence. Le score FSFI total (différence 4,55 ; IC95 % 0,57–8,52) et le sous-score orgasme sont meilleurs avec la PBM active. L'ICIQ-SF s'améliore de 3,06 points, un seuil cliniquement significatif. Résultats du protocole publié dans PeerJ en 2024.","l3":{"points":["FSFI : DM 4,55 (IC95 % 0,57–8,52 ; d = 1,05).","ICIQ-SF : −3,06 points en faveur de la PBM active.","Manométrie périnéale : pas de différence."],"limites":["Effectif non précisé dans le résumé."],"pratique":"La PBM peut compléter utilement la rééducation périnéale, surtout pour la sexualité et les fuites."},"topic":"gynecologie","title":"Photobiomodulation and pelvic floor training for genitourinary syndrome: RCT results.","journal":"Climacteric : the journal of the International Menopause Society","journal_abbr":"Climacteric","authors":["Oliveira Bezerra L","Silva-Filho E","Leticia Araújo Silva de Carvalho M","et al."],"date":"2026-08-07","year":2026,"week":"2026-S32","doi":"10.1080/13697137.2026.2702818","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"This study aimed to evaluate the effects of photobiomodulation (PBM) alone and in combination with pelvic floor muscle training (PFMT) on pelvic floor muscle (PFM) function, sexual and urinary function, and quality of life in women with genitourinary syndrome of menopause."},{"label":"METHOD","text":"The three-arm clinical trial included women aged 45-65 years who had experienced natural menopause for at least 1 year. Participants were randomized into three groups: PFMT + active PBM, PFMT + sham PBM and isolated PFMT. Interventions lasted 8 weeks, with participants attending two 50-min sessions per week. Outcomes were assessed before and after the 16th session."},{"label":"RESULTS","text":"Although manometry showed no significant differences between groups, the intervention group demonstrated greater numerical improvement. The Female Sexual Function Index (FSFI) total score differed significantly between the PFMT + active PBM and PFMT + sham PBM groups (mean difference = 4.55; 95% confidence interval: 0.57, 8.52; d = 1.05). Significant between-group differences were also observed in the orgasm subdomain in favor of the PFMT + active PBM group compared to the PFMT + sham PBM group. The International Consultation on Incontinence Questionnaire - short form (ICIQ-SF) indicated a clinically significant improvement of 3.06 points in the PFMT + active PBM group compared to the PFMT + sham PBM group following the intervention."},{"label":"CONCLUSION","text":"Active PBM combined with PFMT showed greater but non-significant improvements in PFM pressure, urinary function and quality of life, while significantly improving only sexual function."}],"keywords":["Photobiomodulation","genitourinary syndrome of menopause","manometry","pelvic floor muscle training","quality of life"]},{"pmid":"42446177","title_fr":"L'électrothérapie dans l'accompagnement de l'allaitement","type":"review","level":5,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Allaitement","l1":"Retour d'expérience irlandais : des consultantes en lactation utilisent la PBM pour les lésions du mamelon et les ultrasons pour l'engorgement, avec une forte satisfaction.","l2":"Article de pratique décrivant l'introduction de ces outils en santé communautaire.","l3":{"points":["Indication PBM : traumatismes du mamelon."],"limites":["Retour d'expérience."],"pratique":"—"},"topic":"gynecologie","title":"Electrotherapy in Lactation Care.","journal":"Journal of human lactation : official journal of International Lactation Consultant Association","journal_abbr":"J Hum Lact","authors":["McCahill-Riley M","Downey K","Clarke V"],"date":"2026-07-14","year":2026,"week":"2026-S29","doi":"10.1177/08903344261458656","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Electrotherapy in Lactation CareBreastfeeding offers significant health benefits but is often discontinued early due to inflammatory conditions of the lactating breast and nipple trauma. Common issues such as mastitis, engorgement, and nipple damage contribute to pain, infection, and reduced milk production, leading to early cessation. Effective management includes optimal positioning, strategies to maintain breastfeeding, and wound care. Emerging electrotherapies, such as Photobiomodulation Therapy and Therapeutic Ultrasound, may offer promising, non-invasive treatments to support lactation. Photobiomodulation therapy uses red and near-infrared light to stimulate cellular repair, reduce inflammation, and accelerate wound healing. It is safe, drug-free, and effective for nipple trauma. Therapeutic Ultrasound employs continuous ultrasound waves to relieve pain, reduce edema, and promote healing in inflammatory conditions of the lactating breast. Although the evidence base for these therapies is still developing, they may act as a complementary tool alongside conventional lactation care to provide enhanced support. In Ireland, where breastfeeding rates remain low, clinical innovation in two community care settings led to the introduction of electrotherapy by two Public Health Nurse Lactation Consultants who had trained in, and delivered, electrotherapy within their respective clinical sites. High levels of client satisfaction and symptom reduction were reported. This innovation has now spread to other Irish community and hospital settings where the development of a standardized practice protocol promotes consistency in practice, enhances patient safety and supports accountability. Electrotherapies can be successfully incorporated into lactation care, but priority should remain on optimal postpartum care to prevent breast inflammation, nipple pain, and damage."}],"keywords":["Breastfeeding","Lactation Disorders","Mastitis","Nipple Wounds","Pain Management","Photobiomodulation Therapy","Policy Making","Public Health Nursing","Ultrasonic Therapy","Wound Healing"]},{"pmid":"42329990","title_fr":"PBM 660 nm intravaginale dans le syndrome génito-urinaire de la ménopause : étude prospective","type":"nrct","level":4,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["LED","intravaginal"],"nm":[660],"n":27,"effect":"favorable","theme":"Syndrome génito-urinaire","l1":"Chez 27 femmes ménopausées, huit séances de PBM 660 nm par sonde vaginale ramènent toutes les patientes au-dessus du seuil d'atrophie (index de santé vaginale) à 3 mois, et améliorent les symptômes urinaires.","l2":"Étude taïwanaise monocentrique (NCT06074120) : PBM pulsée à 660 nm par sonde en silicone, 30 minutes par semaine pendant 8 semaines ; fluence de 29 J/cm² au fond vaginal et 12 J/cm² sur la paroi. L'index de santé vaginale s'améliore à chaque visite.\n\nLes questionnaires urinaires (UDI-6, IIQ-7, OABSS) s'améliorent durablement. Le FSFI progresse, mais seules 13,3 % des femmes atteignent le seuil de fonction sexuelle normale. Aucun effet indésirable.","l3":{"points":["Âge moyen 62,9 ans ; suivi à 3 mois.","100 % au-dessus du seuil non atrophique à 3 mois.","FSFI ≥ 26,5 chez 13,3 % seulement."],"limites":["Sans groupe témoin."],"pratique":"Option non hormonale intéressante chez les femmes âgées polymédiquées."},"topic":"gynecologie","title":"Evaluation of photobiomodulation therapy for genitourinary syndrome of menopause: A single-center prospective study.","journal":"PloS one","journal_abbr":"PLoS One","authors":["Wu PC","Lin HH","Chen CH","et al."],"date":"2026-06-22","year":2026,"week":"2026-S26","doi":"10.1371/journal.pone.0351765","pmcid":"PMC13286162","license":"cc by","oa":true,"pdf":"pdfs/42329990.pdf","cited_by":0,"pub_types":["Clinical Trial"],"abstract":[{"label":"BACKGROUND","text":"Genitourinary syndrome of menopause (GSM) is common, and non-hormonal treatment options are needed for women unsuitable for or reluctant to use estrogen therapy."},{"label":"OBJECTIVE","text":"To prospectively evaluate clinical outcomes and clinical improvement rates of photobiomodulation (PBM) for GSM."},{"label":"METHODS","text":"Twenty-seven postmenopausal women with GSM were enrolled in a prospective study conducted from January 2024 to July 2025. Participants received eight weekly 30-minute sessions of pulsed 660-nm PBM delivered through a stationary silicone vaginal light-guide probe. With the probe attached, target irradiance was 32.38mW/cm² at the probe tip and 13.38mW/cm² at the probe side, corresponding to per-session radiant exposures of 29.14J/cm² at the vaginal fornix and 12.04J/cm² at the vaginal wall. Assessments occurred at baseline (V1), pre-4th session (V2), pre-8th session (V3), and three months post-treatment (V4). The primary outcome was the Vaginal Health Index (VHI). Secondary outcomes included validated questionnaires for lower urinary tract symptoms (LUTS) and sexual function (FSFI). Clinical improvement was defined using established minimal clinically important differences (MCID), minimal detectable change (MDC), and cutoff scores as thresholds."},{"label":"RESULTS","text":"The mean age of participants was 62.9 ± 9.7 years. Total VHI scores were significantly higher at all follow-up time points compared to baseline (p < 0.05), with all participants reaching the non-atrophic VHI threshold at V4. UDI-6, IIQ-7, OABSS, and several KHQ domains improved significantly (p < 0.05) and persisted through the 3-month follow-up. Total FSFI scores improved significantly (p < 0.05), but only 13.3% reached the clinical cutoff (≥26.5) at V4 for functional recovery. No adverse events were observed during the study period."},{"label":"CONCLUSIONS","text":"Intravaginal 660-nm PBM is a well-tolerated, non-hormonal modality that may improve objective vaginal health and subjective symptoms in GSM. As an integrated therapeutic option, PBM may also improve GSM-related LUTS, suggesting potential relevance for geriatric patients with polypharmacy concerns."},{"label":"TRIAL REGISTRATION","text":"ClinicalTrials.gov NCT06074120."}],"keywords":[]},{"pmid":"42307744","title_fr":"PBM contre la douleur, pour la cicatrisation et la consommation d'antalgiques après déchirure périnéale : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[660],"n":59,"effect":"neutre","theme":"Périnée post-partum","key":true,"l1":"Chez 59 accouchées avec déchirure ou épisiotomie, la PBM 660 nm (4 J) n'améliore ni la douleur ni la cicatrisation par rapport au placebo, mais réduit un peu la consommation d'antalgiques.","l2":"Essai chilien en double aveugle, intention de traiter. Douleur et cicatrisation (REEDA) s'améliorent dans les deux groupes sans différence. Le groupe PBM prend moins d'antalgiques et les espace davantage.","l3":{"points":["Évaluation jusqu'à 7–15 jours post-partum."],"limites":["Dose faible (4 J)."],"pratique":"Résultat négatif cohérent avec les méta-analyses périnéales de 2025–2026."},"topic":"gynecologie","title":"Photobiomodulation for Pain, Healing, and Analgesic Use after Perineal Lacerations: A Double-Blind Randomized Controlled Trial.","journal":"International urogynecology journal","journal_abbr":"Int Urogynecol J","authors":["de Castro T","Viana LH","Botelho S","et al."],"date":"2026-06-17","year":2026,"week":"2026-S25","doi":"10.1007/s00192-026-06686-5","pmcid":"PMC13731456","license":"cc by","oa":true,"pdf":"pdfs/42307744.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"INTRODUCTION AND HYPOTHESIS","text":"Approximately 60% of women experience some degree of perineal laceration following vaginal delivery. Although there is evidence supporting the use of photobiomodulation (PBM) for pain relief and wound healing in various conditions, there is a lack of studies on its effect on these lacerations. Our hypothesis is that PBM aids in pain management and healing in perineal lacerations/episiotomies in hospitalized women."},{"label":"MATERIALS AND METHODS","text":"A randomized, controlled, double-blind clinical trial in women with grade I/II lacerations and/or episiotomy, assigned to the intervention group (660 nm; 4 J) or placebo group (device turned off). Primary outcome was perineal pain at rest and during movements, measured using the numeric rating scale. Secondary outcome was healing, measured using the REEDA (redness, edema, ecchymosis, discharge, approximation) scale. Additionally, in-hospital analgesic consumption, self-perception of perineal laceration healing, and satisfaction with the intervention were analyzed. Analysis performed pre-intervention (6-12 h postpartum), post-intervention 1 (6-12 h post-first intervention), post-intervention 2 (12-18 h post-first intervention), and follow-up (7-15 days postpartum). Analysis was performed on an intention-to-treat basis using the Mann-Whitney test."},{"label":"RESULTS","text":"A total of 59 women participated (intervention 30; placebo 29), most of whom were primiparous. The intragroup analysis shows a reduction in perineal pain during rest and movements, with improved healing in both groups. No difference was observed in intergroup analysis. The intervention group consumed fewer analgesics and had a longer interval between doses than the placebo group."},{"label":"CONCLUSION","text":"Photobiomodulation (660 nm; 4 J) applied within 24 h postpartum, did not result in clinical improvement in pain or healing in women with perineal lacerations/episiotomies."}],"keywords":["Episiotomy","Low-level laser therapy","Photobiomodulation","Puerperium"]},{"pmid":"42228167","title_fr":"PBM contre la dysfonction sexuelle induite par l'hormonothérapie chez les femmes atteintes de cancer du sein","type":"nrct","level":3,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":["LED","intravaginal"],"nm":[440,660],"n":32,"effect":"favorable","theme":"Après cancer","key":true,"metric":{"kind":"values","outcome":"Douleur vaginale (EVA 0–10)","a_label":"Avant PBM","a":9.46,"b_label":"Après 4 séances","b":1.04,"unit":"/10"},"l1":"Chez 24 femmes sous hormonothérapie pour un cancer du sein, quatre séances de PBM LED (bleu 440 nm + rouge 660 nm) font passer la douleur vaginale de 9,5 à 1/10 ; 79 % n'ont plus de douleur.","l2":"Étude brésilienne quasi expérimentale : PBM intra- et extracavitaire hebdomadaire (8 min de bleu, 20 min de rouge). Huit femmes éligibles qui ont refusé par gêne servent de groupe d'observation.\n\nLa fonction sexuelle (QS-F) passe de 23 à 87, et 95,8 % des femmes déclarent une fonction bonne à excellente. Le groupe non traité ne change pas. Aucun effet indésirable. Un résultat important car les œstrogènes locaux sont souvent évités dans cette population.","l3":{"points":["EVA : 9,46 ± 0,98 → 1,04 ± 2,17 (p < 0,0001).","QS-F : 23,25 → 87,21 (p < 0,0001).","Groupe observationnel non traité (n = 8) : pas d'évolution."],"limites":["Non randomisé ; groupe témoin auto-sélectionné et petit."],"pratique":"Piste non hormonale prioritaire pour la sécheresse et la dyspareunie sous inhibiteurs de l'aromatase ; à confirmer par essai randomisé."},"topic":"gynecologie","title":"Photobiomodulation for hormone therapy-induced sexual dysfunction in women with breast cancer: a prospective quasi-experimental clinical study with a parallel observational group.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Vieira LR","Rezende LF"],"date":"2026-06-02","year":2026,"week":"2026-S23","doi":"10.1007/s00520-026-10846-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Clinical Study","Observational Study"],"abstract":[{"label":"BACKGROUND","text":"Breast cancer survivors undergoing hormone therapy frequently experience vaginal pain and sexual dysfunction, which negatively affect quality of life. These symptoms are often undertreated, and new therapeutic approaches are needed."},{"label":"PURPOSE","text":"To evaluate the effects of photobiomodulation (PBM) on vaginal pain, sexual function, safety, and tolerability in women with breast cancer undergoing hormone therapy."},{"label":"METHODS","text":"A prospective, quasi-experimental clinical study was conducted with 24 women presenting hormone therapy-induced sexual dysfunction, who underwent four weekly intra- and extra-cavitary PBM sessions (blue LED-440 nm, 8 min; red LED-660 nm, 20 min). Eight eligible participants who declined the intervention due to embarrassment were followed as an untreated observational group. Assessments were performed before and after the intervention using the Female Sexual Quotient Questionnaire (QS-F) and the Visual Analog Scale (VAS) for vaginal pain."},{"label":"RESULTS","text":"At baseline, 82.6% of participants reported maximum vaginal pain (VAS = 10), and 78.2% presented absent or severely impaired sexual function. After four PBM sessions, 79.1% of the women reported complete absence of pain, with mean VAS scores decreasing from 9.46 ± 0.98 to 1.04 ± 2.17 (p < 0.0001). Sexual function also improved significantly, with mean QS-F scores increasing from 23.25 ± 23.47 to 87.21 ± 17.93 (p < 0.0001), and 95.8% of participants reporting good to excellent sexual function after treatment. The intervention was well tolerated, with no adverse events reported. The observational group showed no changes in the evaluated outcomes."},{"label":"CONCLUSION","text":"PBM proved to be safe, well tolerated, and clinically effective in reducing vaginal pain and improving sexual function in women with breast cancer undergoing hormone therapy, representing a promising therapeutic alternative."}],"keywords":["Breast cancer","Female sexual dysfunction","Genitopelvic pain","Hormone therapy","Non-hormonal therapies","Photobiomodulation"]},{"pmid":"42217018","title_fr":"Infrarouge et laser contre la douleur et pour la cicatrisation des lésions périnéales post-partum : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Périnée post-partum","l1":"Neuf études : ni l'infrarouge lointain ni le laser basse énergie ne font mieux que le placebo ou les soins habituels sur la douleur et la cicatrisation périnéales post-partum.","l2":"Revue enregistrée (PROSPERO). Deux essais laser contre placebo : pas de différence de douleur à 20–24 h ni à 40–48 h, ni de cicatrisation.","l3":{"points":["LLLT contre placebo : DM 0,12 (IC95 % −1,74 à 1,98) à 20–24 h."],"limites":["Très peu d'essais poolés."],"pratique":"—"},"topic":"gynecologie","title":"Infrared and Laser for Pain and Healing of Postpartum Perineal Injuries: A Systematic Review and Meta-Analysis.","journal":"International urogynecology journal","journal_abbr":"Int Urogynecol J","authors":["Santos Vanzella JS","Fitz FF","Aquino Castro R","et al."],"date":"2026-05-30","year":2026,"week":"2026-S22","doi":"10.1007/s00192-026-06601-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"INTRODUCTION AND HYPOTHESIS","text":"The effectiveness of far-infrared radiation (FIR) and low-level laser therapy (LLLT) for postpartum pelvic floor pain and healing remains unclear. The study proposes that FIR and LLLT may be more effective than no treatment or standard conservative approaches in relieving pain and enhancing tissue healing after childbirth-related perineal trauma."},{"label":"METHODS","text":"The review protocol was registered in PROSPERO. The systematic search was conducted between February and March 2024. Randomized and quasi-experimental trials for pain and healing of postpartum perineal injuries were included. PEDro scale and ROBINS-2 were used to evaluate the studies. Fixed or random effects models based on study heterogeneity were calculated using the I2 statistic from RevMan 5.4.1."},{"label":"RESULTS","text":"Nine studies met criteria and were included in the review. Five were included in the meta-analyses. Three investigated the effects of FIR compared to no treatment or sitz baths for pain relief without differences between the interventions [-0.54; 95% CI (-2.26, 1.18), p = 0.54]. Two studies compared LLLT and placebo/sham therapy with no differences between them on pain in two moments: at 20-24 h [0.12; 95% CI (-1.74, 1.98), p = 0.90] and at 40-48 h postpartum [-0.02; 95% CI (-1.89, 1.84), p = 0.98]; and no differences between the treatments on healing were evidenced at 20-24 h [0.30; 95% CI (-0.35, 0.95), p = 0.36], and at 40-48 h postpartum [-0.02; 95% CI (-1.89, 1.84), p = 0.98]."},{"label":"CONCLUSIONS","text":"FIR and LLLT showed no added benefit over conventional treatments for pain relief and wound healing in perineal injuries post-vaginal delivery."}],"keywords":["Infrared radiation","Laser therapy","Perineal trauma","Postpartum perineal healing","Postpartum perineal pain"]},{"pmid":"42207758","title_fr":"PBM contre la douleur de pose du stérilet au cuivre : protocole d'essai en double aveugle","type":"protocol","level":0,"pop":"adulte","ctx":["pelvien"],"aim":"prévention","mode":[],"nm":[],"n":72,"effect":"—","theme":"Douleurs pelviennes","l1":"Protocole brésilien (72 femmes) : la PBM peut-elle réduire la douleur lors de la pose d'un DIU au cuivre, un frein majeur à son utilisation ?","l2":"PBM active contre simulation, mesure par EVA. Pas encore de résultats.","l3":{"points":["Randomisation 36/36."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Photobiomodulation for pain management during placement of the copper T 380 intrauterine device: Protocol for a randomized, double-blind controlled trial.","journal":"PloS one","journal_abbr":"PLoS One","authors":["Ferraz ACN","Traverzim MA","Makabe S","et al."],"date":"2026-05-28","year":2026,"week":"2026-S22","doi":"10.1371/journal.pone.0349031","pmcid":"PMC13218537","license":"cc by","oa":true,"pdf":"pdfs/42207758.pdf","cited_by":0,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"INTRODUCTION","text":"Unplanned pregnancy remains a critical public health issue in Brazil that affects up to 65% of women in some regions and increases the incidence of both unsafe abortions and maternal mortality. Although the copper intrauterine device (IUD) is a highly effective, long-acting contraceptive method, its rate of use remains low in Brazil (only 4.4% of women of reproductive age). One of the primary barriers is the pain experienced during placement of the device, which discourages adherence. Although multiple social and cultural determinants influence IUD uptake, insertion-related pain constitutes a modifiable, procedure-specific factor that may directly affect both pain perception and anticipatory discomfort. Conventional pain management strategies, such as anti-inflammatories and local anesthetics, have produced inconsistent results. Photobiomodulation (PBM) is a non-invasive therapy with anti-inflammatory and analgesic properties that has shown promise in managing pelvic pain in contexts such as labor."},{"label":"METHODS AND ANALYSIS","text":"The proposed randomized, double-blind clinical trial will investigate the effectiveness of PBM at reducing pain during the placement of the copper T 380 IUD. Seventy-two women will be randomly allocated to either an active PBM group (n = 36) or sham PBM control group (n = 36). In all participants, the standard IUD placement protocol will follow the guidelines of the Brazilian Ministry of Health. Pain will be assessed using the Visual Analog Scale (VAS) at multiple time points: during each step of insertion (Pozzi clamp, hysterometry, IUD placement) as well as 5 min, 15 min, 24 hours, and 48 hours post-procedure. The secondary outcomes will be analgesic use, anxiety levels (GAD-7), quality of life (WHOQOL-100), satisfaction with the procedure, and adverse effects. Ethics and dissemination. This clinical trial received approval from the Research Ethics Committee of the Mandaqui Hospital Complex (process: 7.367.867) and was registered in ClinicalTrials.gov (NCT06984796). Statistical analyses will be conducted using SPSS v24.0, with a significance level of 5%. Either parametric or nonparametric tests will be applied, depending on the data distribution. Kaplan-Meier curves will be used to assess time to pain resolution. The results will be disseminated through peer-reviewed publications."}],"keywords":[]},{"pmid":"42239956","title_fr":"PBM sur points d'acupuncture locaux ou distaux dans la dysménorrhée primaire : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[],"n":60,"effect":"—","theme":"Dysménorrhée","l1":"Protocole d'essai pilote (60 femmes) comparant la photothérapie sur points locaux et distaux, 7 jours avant les règles pendant trois cycles.","l2":"Critère principal : EVA ; biosignaux multiples (ECG, EMG, conductance cutanée).","l3":{"points":["Pas encore de résultats."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Local versus distal acupoint low-level light therapy for pain relief in primary dysmenorrhea: protocol for a randomized, assessor- and statistician-blinded, pilot study.","journal":"Frontiers in medicine","journal_abbr":"Front Med (Lausanne)","authors":["Kim J","Kim M","Kim AR","et al."],"date":"2026-05-19","year":2026,"week":"2026-S21","doi":"10.3389/fmed.2026.1793534","pmcid":"PMC13226158","license":"cc by","oa":true,"pdf":"pdfs/42239956.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Primary dysmenorrhea (PD) is a common gynecological condition affecting a substantial proportion of women of reproductive age. Non-steroidal anti-inflammatory drugs often provide incomplete pain relief and may be associated with adverse effects (AEs), highlighting the need for low-risk, non-pharmacological alternatives. Low-level light therapy (LLLT) has emerged as a promising non-invasive modality for pain management; however, the comparative effects of LLLT applied to local versus distal acupoints remain unclear."},{"label":"METHOD","text":"This is a single-center, prospective, randomized, assessor- and statistician-blinded, parallel-group pilot study. A total of 60 women with moderate-to-severe PD will be randomized to receive LLLT at either local or distal acupoints. Interventions will be administered once daily for 7 consecutive days prior to menstruation across three menstrual cycles. Pain intensity will be assessed using the visual analog scale (VAS). Multimodal biosignals, such as electrocardiography, electromyography, electrodermal activity, photoplethysmography, respiration, and skin temperature, will be recorded to explore physiological responses to treatment. The primary outcome is the change from baseline in VAS measured at the scheduled post-menstrual visit occurring within 3 days after the onset of menstruation, assessed across three menstrual cycles. The secondary outcomes include biosignal changes, patient-reported outcomes, and the Patient Global Impression of Change."},{"label":"CONCLUSION","text":"To the best of our knowledge, this will be one of the first randomized studies to directly compare LLLT applied to local and distal acupoints in patients with PD. As a comparative pilot study, it is not designed to establish definitive efficacy but to explore differences between stimulation strategies and to generate preliminary data for future confirmatory studies."},{"label":"STUDY PROTOCOL REGISTRATION","text":"https://cris.nih.go.kr/cris/search/detailSearch.do?seq=30497&sea. This study has been registered with the Clinical Research Information Service, identifier KCT0010827 (registration date: 29 July 2025)."}],"keywords":["Korean medicine","acupoint phototherapy","low-level light therapy","multimodal biosignal","primary dysmenorrhea","randomized controlled trial"]},{"pmid":"42060269","title_fr":"PBM dans le syndrome génito-urinaire de la ménopause : essai en double aveugle contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[808],"n":null,"effect":"favorable","theme":"Syndrome génito-urinaire","key":true,"l1":"Chez des femmes ménopausées, quatre séances de laser 808 nm intravaginal réduisent les fuites urinaires et améliorent sécheresse et brûlures par rapport au placebo, sans effet sur la sexualité.","l2":"Essai brésilien randomisé en double aveugle chez des femmes de plus de 50 ans présentant au moins un symptôme du syndrome génito-urinaire. Laser 808 nm, 8 points vaginaux, 4 J par point, une séance par semaine pendant 4 semaines ; le groupe placebo suivait le même protocole, appareil éteint.\n\nLes pertes urinaires diminuent nettement et le score ICIQ-SF s'améliore sous PBM. La sécheresse et les brûlures vaginales sont améliorées. La pression pelvienne et la fonction sexuelle ne diffèrent pas du placebo. C'est la publication des résultats du protocole paru en 2024 (PLoS One).","l3":{"points":["Protocole : 808 nm, 4 J/point, 40 s, 8 points, 4 séances hebdomadaires.","Critère principal : fuites urinaires ; ICIQ-SF amélioré.","Fonction sexuelle et pression du plancher pelvien : pas de différence."],"limites":["Effectif non précisé dans le résumé ; suivi court."],"pratique":"Option non hormonale pour l'incontinence et la sécheresse de la ménopause, notamment quand les œstrogènes locaux sont contre-indiqués."},"topic":"gynecologie","title":"Photobiomodulation therapy in the treatment of genitourinary syndrome in postmenopausal women - a placebo-controlled double-blind clinical trial.","journal":"Climacteric : the journal of the International Menopause Society","journal_abbr":"Climacteric","authors":["Pereira SRDS","Lanzafame R","Mesquita-Ferrari RA","et al."],"date":"2026-04-30","year":2026,"week":"2026-S18","doi":"10.1080/13697137.2026.2658817","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Postmenopausal genitourinary syndrome of menopause (GSM) includes a range of genital, urinary and sexual symptoms caused by estrogen deficiency. As women spend about one-third of their lives postmenopause, effective, non-invasive treatments are needed. This study evaluated the clinical effects of photobiomodulation (PBM) therapy in postmenopausal women with urinary incontinence. A randomized, double-blind, placebo-controlled clinical trial was conducted with women over 50 years of age presenting one or more GSM symptoms. Participants were assigned to receive either PBM or placebo. The PBM group underwent four weekly sessions of 808 nm laser applied to eight vaginal points (4J per point, 40s each). The placebo group followed the same protocol with the device turned off. Results showed a significant reduction in urinary loss in the PBM group, with improved scores on the International Consultation on Incontinence Questionnaire - Short Form. While pelvic pressure and sexual function did not differ significantly, improvements in vaginal dryness and burning were reported. PBM appears to be a promising, non-invasive option for reducing urinary incontinence and enhancing aspects of vaginal health in postmenopausal women. Further studies are needed to confirm long-term effects and optimize treatment protocols."}],"keywords":["Vaginal atrophy","low-intensity laser irradiation","low-intensity light therapy","photobiomodulation","urinary incontinence"]},{"pmid":"42030720","title_fr":"PBM proche infrarouge et maturation in vitro d'ovocytes humains immatures","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[810],"n":260,"effect":"favorable","theme":"Fertilité","key":true,"l1":"Sur 260 ovocytes humains immatures, une minute de laser 810 nm accélère la maturation (deux fois plus rapide) et augmente l'ATP, sans stress oxydatif.","l2":"Ovocytes de 114 femmes en stimulation ovarienne, randomisés PBM ou témoin. L'activité de phosphorylation oxydative augmente de 194 à 240 %. Les auteurs demandent une évaluation de la sécurité embryonnaire avant usage clinique.","l3":{"points":["810 nm, 1 W, 60 J/cm², 1 min."],"limites":["In vitro ; sécurité embryonnaire non évaluée."],"pratique":"—"},"topic":"gynecologie","title":"The impact of near-infrared photobiomodulation therapy on human oocyte rescue in vitro maturation.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Stigliani S","Balbi M","Ravera S","et al."],"date":"2026-04-21","year":2026,"week":"2026-S17","doi":"10.1016/j.jphotobiol.2026.113452","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"This prospective study investigated the effects of photobiomodulation therapy (PBMT) at 810 nm on rescue in vitro maturation (rescue-IVM) of human immature oocytes following controlled ovarian stimulation (COS). A total of 260 immature oocytes (germinal vesicles (GV): 143; metaphase I (MI): 117) were collected from 114 women undergoing COS between December 2023 and July 2025, denuded, and randomized into control or PBMT groups; ten in vivo-matured MII oocytes served as references. PBMT was applied at 810 nm, 1.0 W, 60 J/cm2 for 1 min, and nuclear maturation and morphology were assessed up to 6 h of IVM. ATP content, mitochondrial oxidative phosphorylation (OxPhos) activity, and lipid peroxidation (MDA) were measured using luminometric, oximetric, and spectrophotometric assays. PBMT accelerated maturation, with GV and MI oocytes progressed to the next maturation stage 112.5% and 92.3% faster, respectively, within 1 h. ATP content increased markedly in PBMT-treated oocytes (P < 0.0001), with early-resuming MI oocytes exceeding levels of in vivo MII oocytes. OxPhos activity increased by 240% (GV) and 194% (MI) immediately after irradiation without mitochondrial uncoupling, while MDA levels remained stable. Collectively, these results demonstrated that PBMT accelerated cell cycle progression to GV and MI oocytes by enhancing mitochondrial OxPhos and ATP production without inducing oxidative stress. Limitations include the need for larger cohorts, evaluation of safety through assessment of potential DNA damage, and validation in poor-prognosis or advanced maternal age patients. This pioneering proof-of-concept study highlights the potential of PBMT to temporally accelerate rescue-IVM of immature oocytes - and possibly cumulus-oocyte complexes - in poor-responder patients undergoing IVF or fertility preservation."}],"keywords":["Immature oocytes","Mitochondrial metabolism","Oocyte maturation","Photobiomodulation therapy","Rescue in vitro maturation"]},{"pmid":"41975391","title_fr":"Traitements de la vulvodynie : revue systématique et méta-analyse en réseau","type":"ma","level":1,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":[],"nm":[],"n":1893,"effect":"favorable","theme":"Vulvodynie","key":true,"l1":"34 essais (1 893 femmes) : les thérapies « tissulaires » (PBM, laser basse énergie, TENS vaginale, ondes de choc) arrivent en tête contre placebo pour la douleur de la vulvodynie ; les médicaments ne font pas mieux que le placebo.","l2":"Méta-analyse bayésienne en réseau, risques de biais RoB 2, confiance évaluée par CINeMA. Douleur juste après traitement : les thérapies tissulaires réduisent la douleur de 16 points sur 100 contre placebo (IC95 % −24,1 à −7,9, confiance modérée) et sont classées premières (SUCRA 85 %).\n\nComparés à l'absence de traitement, la kinésithérapie multimodale, l'acupuncture et les approches psychologiques sont aussi efficaces. Limite : la PBM est regroupée avec d'autres techniques physiques.","l3":{"points":["Thérapies tissulaires : POMP −16,1 contre placebo ; SUCRA 85,2 %.","Médicaments : pas de supériorité sur le placebo."],"limites":["PBM regroupée avec TENS et ondes de choc."],"pratique":"Dans la vulvodynie, la PBM a sa place dans une prise en charge physique et multimodale."},"topic":"gynecologie","title":"Beyond the placebo effect: a systematic review and a network meta-analysis of treatment strategies for vulvodynia.","journal":"BMC women's health","journal_abbr":"BMC Womens Health","authors":["Spinillo A","Dominoni M","Tiranini L","et al."],"date":"2026-04-14","year":2026,"week":"2026-S16","doi":"10.1186/s12905-026-04469-0","pmcid":"PMC13214167","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41975391.pdf","cited_by":1,"pub_types":["Systematic Review","Network Meta-Analysis"],"abstract":[{"label":"","text":"BACKGROUND: To comprehensively evaluate the comparative and absolute effectiveness of available treatments for vulvodynia on pain and sexual function outcomes through network meta-analysis (NMA). METHODS: Systematic searches extracted data from randomized controlled trials (blinded or unblinded) evaluating pharmacological and non-pharmacological treatments in women with vulvodynia, from inception through September 2025. Of 40 studies assessed for eligibility, 34 studies involving 1,893 participants were included in the final analysis. Risk of bias was assessed using the Cochrane Risk of Bias 2 (RoB 2 tool.Confidence in network meta-analysis results was evaluated using the Confidence in Network Meta-analysis (CINeMA) framework. RESULTS: Pain and sexual function outcomes were rescaled to percentage of maximum possible score (POMP, 0–100 scale) to enable pooling across heterogeneous measurement instruments. Both relative treatment effects (comparing interventions to placebo/no treatment) and absolute effects (pre-post changes) were evaluated using Bayesian NMA. Ten treatment categories were analysed: acupuncture, botulinum toxin, topical anaesthetics, topical non-anaesthetics, multimodal/physical therapy, psychological approaches, surgery, tissue-based therapies (photobiomodulation, low-level laser, vaginal transcutaneous electrical nerve stimulation, shockwave therapy), placebo, and no treatment. For pain immediately post-therapy (33 studies, 1,873 women), tissue-based therapies demonstrated superior efficacy compared to placebo in both NMA (POMP difference: -16.1, 95% CI: -24.1, -7.9, mixed evidence, moderate confidence), and pairwise meta-analyses (POMP difference: -20.2, 95% CI: -28.6, -11.7, I2 = 77%) and ranking highest in surface under the cumulative ranking curve (SUCRA) analysis (85.2%). Pharmacological interventions showed no superiority over placebo. Compared to no treatment, multimodal-physical therapy (POMP: -25.3, 95% CI: -40.8, -9.7, mixed evidence, low confidence), acupuncture (POMP: -25.6, 95% CI: -43.4, -8.1, mixed evidence, moderate confidence), and psychological approaches (POMP -27.4, 95% CI: -44.6, -10.3, indirect evidence, low confidence) all demonstrated moderate-to-high pain reduction. At 3–6 months follow-up (16 studies, 1,106 women), tissue-based treatments remained the only therapy significantly superior to placebo (POMP: -24.5, 95% CI: -42.2, -6.7, mixed evidence, moderate confidence; SUCRA = 77.9%). In absolute effects analysis, placebo produced significant pain reduction (Absolute effect: -13.7, 95% CI: -18.3, -9.3 immediately; -11.7, 95% CI: -17.7, -6.0 at 3–6 months), with confidence intervals overlapping all treatments except tissue-based therapies (Absolute effect: -28, 95% CI: -33.4, -21.7 immediately; -31.6, 95% CI: -43.9, -19.1 at follow-up). Placebo had no effect on sexual function improvement (14 studies, 942 women), (Absolute effect: 2.5, 95% CI: -8., 12.9). At 3–6 months of follow-up (8 studies, 429 women), psychological-based treatments, when added to multimodal treatment (POMP = 9.0, 95% CI = 1.8, 16.7, I2 = 41.6%), improved modestly sexual functioning. CONCLUSIONS: In NMA, tissue-based therapies were the most effective treatment for vulvodynia-associated pain, achieving reductions that clearly exceeded placebo effects with moderate evidence quality. Commonly prescribed pharmacological interventions lack robust evidence of superiority over placebo. Multimodal approaches combined with psychological interventions show promise, particularly for sexual function recovery."}],"keywords":["Network meta-analysis","Placebo","Therapy","Vulvodynia"]},{"pmid":"41896860","title_fr":"Laser vaginal dans la prise en charge du syndrome douloureux vésical et de la vulvodynie","type":"review","level":5,"pop":"adulte","ctx":["vulve","pelvien"],"aim":"traitement","mode":["intravaginal"],"nm":[],"n":null,"effect":"favorable","theme":"Vulvodynie","l1":"Revue narrative : la PBM transvaginale émerge, avec les lasers non ablatifs Er:YAG et Nd:YAG, pour le syndrome douloureux vésical associé à la vulvodynie.","l2":"Les auteurs mettent en avant des mécanismes communs (épithélium, neuro-inflammation, hypertonie du plancher pelvien) et une prise en charge multidisciplinaire. Les données spécifiques restent limitées.","l3":{"points":["PBM transvaginale : effets mitochondriaux, anti-inflammatoires, neuromodulateurs."],"limites":["Revue narrative."],"pratique":"—"},"topic":"gynecologie","title":"Integrating vaginal laser therapy into multidisciplinary management of bladder pain syndrome and vulvodynia.","journal":"BMC urology","journal_abbr":"BMC Urol","authors":["Okui N"],"date":"2026-03-27","year":2026,"week":"2026-S13","doi":"10.1186/s12894-026-02114-4","pmcid":"PMC13147590","license":"cc by","oa":true,"pdf":"pdfs/41896860.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"BACKGROUND: Bladder pain syndrome/interstitial cystitis (BPS/IC) and vulvodynia frequently co-occur, forming overlapping pelvic pain syndromes that often evade organ-centered management. Shared mechanisms—urothelial/epithelial dysfunction, neuroinflammation, and pelvic floor hypertonicity—support multidisciplinary, mechanism-based care. Because high-quality clinical evidence specifically targeting the BPS/IC + vulvodynia overlap remains limited, this narrative review also evaluates laser-based therapies in clinically adjacent conditions with shared anatomy and pathophysiology (e.g., genitourinary syndrome of menopause and vulvar dermatoses) to contextualize plausibility and inform future study design. MAIN BODY: Non-ablative erbium-doped yttrium aluminum garnet (Er:YAG) and neodymium-doped yttrium aluminum garnet (Nd:YAG) vaginal/vulvar protocols have shown encouraging improvements in superficial vulvar pain, dyspareunia, sexual function, and—in selecte cohorts—bladder-related symptoms among patients with coexisting BPS/IC and vulvodynia. Transvaginal photobiomodulation (TV-PBM) is emerging as another non-ablative modality with putative mitochondrial, anti-inflammatory, and neuromodulatory effects. Across modalities, histological and imaging reports describe epithelial thickening, glycogen restoration, neovascularization, and collagen remodeling, consistent with tissue repair within the urogynecologic–pelvic floor unit. Proposed mechanisms include sublethal photothermal activation of heat-shock responses, modulation of microvascular tone, and attenuation of inflammatory mediators. Nevertheless, current evidence is dominated by small case series and non-controlled studies with heterogeneous parameters and short follow-up; long-term efficacy, safety, dose, targets, and schedules remain to be standardized. Recent clustering and phenotyping work highlights BPS/IC subtypes—including vulvodynia-predominant groups with distinct psychological and quality-of-life profiles—suggesting that responses to laser modalities are likely phenotype-dependent. In parallel, natural-language analyses reveal “semantic drift” between clinical terms and patients’ everyday symptom language, indicating a role for AI-assisted processing of diaries and free-text to refine phenotyping and endpoint selection. CONCLUSIONS: Vaginal/vulvar laser therapy and TV-PBM can be positioned as mechanism-specific modules within individualized, multidisciplinary care for BPS/IC and vulvodynia. Priority next steps include adaptive or stratified randomized trials, harmonized energy/targeting protocols, multidimensional patient-reported outcomes, and rational combinations with pelvic floor rehabilitation, hormonal or androgen-sparing approaches, and psychological interventions. Incorporating AI-based profiling and vocabulary mapping into clinical workflows may sharpen subtype recognition and treatment targeting, ultimately improving outcomes for patients with overlapping BPS/IC and vulvodynia."}],"keywords":["Bladder pain syndrome","Er:YAG","Interstitial cystitis","Laser therapy","Nd:YAG","Transvaginal photobiomodulation","Vulvodynia"]},{"pmid":"41892840","title_fr":"PBM et douleur et cicatrisation des épisiotomies et déchirures de grade 2–3 : cohorte prospective","type":"cohort","level":3,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[808],"n":183,"effect":"favorable","theme":"Périnée post-partum","l1":"Dans une maternité portugaise, la PBM 808 nm quotidienne réduit la douleur périnéale de 1,7 point par rapport aux femmes non traitées (appariement par score de propension), avec une tendance à mieux cicatriser.","l2":"149 femmes traitées et 34 non traitées. PBM routinière : 808 nm, 100 mW, 5 points périlésionnels, 4 J/cm² par jour pendant l'hospitalisation.","l3":{"points":["Différence de douleur : 1,68 point (p < 0,001)."],"limites":["Non randomisé, groupe témoin petit et auto-sélectionné."],"pratique":"Les lésions plus sévères (grade 2–3) pourraient mieux répondre que les petites déchirures."},"topic":"gynecologie","title":"Effects of Photobiomodulation Therapy on Pain and Healing of Episiotomies and Grade 2 and 3 Perineal Lacerations After Vaginal Delivery: A Prospective Observational Cohort Study.","journal":"Medical sciences (Basel, Switzerland)","journal_abbr":"Med Sci (Basel)","authors":["Filho LJR","Barcellos MV","Pesci FBP","et al."],"date":"2026-03-06","year":2026,"week":"2026-S10","doi":"10.3390/medsci14010125","pmcid":"PMC13027586","license":"cc by","oa":true,"pdf":"pdfs/41892840.pdf","cited_by":0,"pub_types":["Observational Study","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"","text":"Tissue trauma related to operative vaginal delivery or the use of episiotomy has been associated with complications such as pain and infection, and successful management is a key factor in promoting a faster and better recovery after delivery. Strategies that promote analgesia and tissue regeneration are especially relevant in obstetric care. Background/Objectives: To evaluate the effects of photobiomodulation (PBM) on pain and perineal healing in women who underwent episiotomy or sustained second- and third-degree lacerations after vaginal delivery. Methods: Observational cohort study. PBM is routinely offered postpartum as an adjuvant to standard hospital treatment daily throughout hospitalization for postpartum women who underwent episiotomy or second- and third-degree lacerations after vaginal delivery, recruited over a prospective 6-month period. The treatment protocol used an 808 nm laser at 100 mW, applied to five perilesional points at 4 J/cm2 daily during hospitalization. Propensity score matching (PSM) analysis and two-way ANOVA were used to compare subgroups of patients who agreed to receive adjuvant PBM and those who did not, in addition to conventional treatment. Daily pain was assessed using the numerical pain scale (NPS) before and after PBM and conventional treatment, and healing was evaluated using the REEDA scale. Results: Data from 149 PBM-treated women and 34 non-PBM-treated women were analyzed. After PSM matching, a mean difference in NPS scores of 1.6761 (standard error = 0.4379) was observed between the group submitted to two laser sessions and the no-laser group, indicating a statistically significant difference (F = 14.65; Pr = 0.000191). A significant decrease in NPS scores was observed with ANOVA before and after each PBM application (p < 0.05), over the three days of follow-up. Regarding the REEDA scale, the preliminary results indicate a trend toward lower scores (better outcomes) in the laser group, an effect that larger studies could confirm. Conclusions: PBM was associated with improvements in pain reduction and tissue healing."}],"keywords":["episiotomy","healing","implementation science","pain","perineal lacerations","photobiomodulation","vaginal delivery"]},{"pmid":"41939583","title_fr":"Mécanismes de la PBM dans la dysménorrhée primaire : revue narrative","type":"review","level":5,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":[],"nm":[610,630],"n":null,"effect":"—","theme":"Dysménorrhée","l1":"La lumière rouge (610–630 nm) agirait sur la dysménorrhée via les médiateurs inflammatoires et le métabolisme des lipides (prostaglandines).","l2":"Synthèse des études avec biomarqueurs et des travaux mécanistiques, utile pour choisir la longueur d'onde.","l3":{"points":["Cibles : prostaglandines, mitochondries, lipides."],"limites":["Revue narrative."],"pratique":"—"},"topic":"gynecologie","title":"Mechanistic Insights Into Photobiomodulation for Primary Dysmenorrhea: A Narrative Review.","journal":"Cureus","journal_abbr":"Cureus","authors":["Pelevin E","Pabian L","Auerbach S","et al."],"date":"2026-03-05","year":2026,"week":"2026-S10","doi":"10.7759/cureus.104721","pmcid":"PMC13050267","license":"cc by","oa":true,"pdf":"pdfs/41939583.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Primary dysmenorrhea is widely recognized as a prevalent source of menstrual pain among individuals of reproductive age, with some patients reporting limited symptom relief with commonly used pharmacologic treatments. Photobiomodulation (PBM), including low-level light therapy in the red-light spectrum (approximately 610-630 nm), has emerged as a nonpharmacologic modality that has been explored in clinical research settings for dysmenorrhea. However, the biological mechanisms potentially underlying PBM-associated symptom improvement in this context are not fully elucidated, which may limit optimization of treatment parameters and broader clinical application. This narrative review synthesizes existing literature describing proposed molecular and cellular mechanisms through which PBM may influence dysmenorrhea-related pathways, with particular attention to inflammatory mediators, lipid metabolism, and implications for wavelength-specific treatment design. A narrative synthesis approach was employed, integrating findings from clinical studies that included biomarker assessments with established experimental and theoretical literature on PBM mechanisms. Sources reviewed included controlled clinical studies reporting biochemical outcomes, metabolomic investigations, and foundational mechanistic research. No new human or animal data were generated for this review. Prior experimental and translational work suggests that red-light PBM may interact with mitochondrial components involved in cellular energy processes, including cytochrome c oxidase, with downstream effects on cellular signaling pathways. In clinical and laboratory contexts, PBM exposure has been associated with changes in inflammation-related biomarkers, including prostaglandin-associated measures. Metabolomic studies further describe alterations in lipid-related metabolic pathways implicated in inflammatory processes, such as glycerophospholipid, linoleic acid, and arachidonic acid metabolism, with some findings suggesting potential wavelength-dependent effects. Collectively, these observations are compatible with the current understanding of dysmenorrhea pathophysiology and provide a plausible biological framework for reported clinical observations. In summary, PBM may influence dysmenorrhea-related symptoms through interconnected effects on mitochondrial signaling, inflammatory mediator activity, and lipid metabolism. Treatment protocols utilizing red-light wavelengths applied to lower abdominal or sacral regions are biologically plausible based on known optical and tissue interaction principles. Future research may benefit from systematic evaluation of dose parameters, standardized biomarker outcomes, and mechanistically informed approaches to patient selection."}],"keywords":["cytochrome c oxidase","low-level light therapy (lllt)","mitochondrial function","non-pharmacological therapy","pain management","photobiomodulation","primary dysmenorrhea","prostaglandins"]},{"pmid":"41786091","title_fr":"Efficacité et critères prédictifs de succès de la PBM dans les douleurs vulvaires et vaginales","type":"cohort","level":4,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[],"n":52,"effect":"mitigé","theme":"Vulvodynie","l1":"Étude française sur 52 femmes : la PBM endovaginale réussit dans 52 % des douleurs vulvaires et vaginales, plutôt sans atrophie, sans brûlure et avant la ménopause, mais sans facteur prédictif confirmé.","l2":"Cohorte rétrospective monocentrique (6 à 8 séances par sonde endovaginale). Succès défini par un PGI-I de 1 ou 2. En analyse univariée, moins de brûlures (OR 0,13), absence d'atrophie et statut non ménopausé sont associés au succès ; aucun facteur ne résiste en multivarié.","l3":{"points":["Taux de succès 52 %."],"limites":["Rétrospectif, sans témoin."],"pratique":"Informer les patientes d'un taux de réponse d'environ une sur deux."},"topic":"gynecologie","title":"Efficacy and predictive criteria for success of photobiomodulation therapy in women presenting with vulvar and vaginal pain.","journal":"The French journal of urology","journal_abbr":"Fr J Urol","authors":["Plumasseau C","Lepelletier M","Vieillefosse S","et al."],"date":"2026-03-03","year":2026,"week":"2026-S10","doi":"10.1016/j.fjurol.2026.103095","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Observational Study"],"abstract":[{"label":"OBJECTIVE","text":"Vulvar and vaginal pain is a frequent complaint that may have psychological consequences. Treatments such as muscle relaxation physiotherapy, sophrology, and photobiomodulation (PBM)/low-intensity laser therapy (LLT) are used, but there are a few data concerning the efficacy of PBM/LLT. The objective of the current study was to assess the effectiveness and the predictive factors associated with the success of PBM/LLT in women presenting with vulvar and vaginal pain."},{"label":"METHOD","text":"Success was defined as a Patient Global Impression of Improvement (PGI-I) of 1 or 2. A single-center, retrospective, observational study (cohort study) was conducted on 52 women, 27 of whom were in the success group and 25 in the failure group. Patients had 6 to 8 PBM/LLT sessions with an endovaginal probe and completed pre- and post-therapy questionnaires. The analysis was carried out on the various recorded characteristics."},{"label":"RESULTS","text":"The overall success rate was 52%. The univariate analysis significantly revealed less burning pain in the success group (OR 0.13; 95% CI: 0.02, 0.62). There were also more patients without vaginal atrophy and non-menopausal women in the success group (OR 0.21; 95% CI: 0.04-0.82 for both). However, the multivariate analysis did not show any significant difference for any predictive factor."},{"label":"CONCLUSION","text":"We observed a moderate success rate associated with PBM/LLT in women presenting with vulvar and vaginal pain. Multivariate analysis revealed no predictive factor for success."}],"keywords":["LLT","Laser","PBM","Photobiomodulation","Vaginal pain","Vulvar pain","Vulvodynia"]},{"pmid":"41740971","title_fr":"Laser basse énergie et douleur des mamelons en post-partum précoce : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":60,"effect":"favorable","theme":"Allaitement","l1":"Chez 60 accouchées allaitantes, le laser (rouge sur le mamelon, infrarouge sur l'aréole) réduit la douleur dès 30 minutes et jusqu'à 7 jours par rapport à la simulation.","l2":"Essai multicentrique en double aveugle. Douleur plus faible à 1 h, 6 h, 12 h et 7 jours. Pas de différence de satisfaction ; aucun effet indésirable.","l3":{"points":["Protocole : 2 J rouge au centre du mamelon, 4 J infrarouge en croix sur l'aréole."],"limites":["Cicatrisation non différente dans le résumé."],"pratique":"Option utile pour éviter un sevrage précoce lié à la douleur."},"topic":"gynecologie","title":"Low-level laser therapy for breastfeeding women with nipple pain in the early postpartum period: a randomized controlled trial.","journal":"The journal of maternal-fetal & neonatal medicine : the official journal of the European Association of Perinatal Medicine, the Federation of Asia and Oceania Perinatal Societies, the International Society of Perinatal Obstetricians","journal_abbr":"J Matern Fetal Neonatal Med","authors":["Gaitero MV","Mira TA","Gondim EJ","et al."],"date":"2026-02-25","year":2026,"week":"2026-S09","doi":"10.1080/14767058.2026.2636360","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"During the immediate postpartum period, breastfeeding could be challenge for many women due nipple pain and trauma. Non-pharmacological therapeutic strategies that reduce pain and accelerate healing are essential to prevent early weaning and support successful lactation."},{"label":"OBJECTIVE","text":"This study aimed to evaluate the effectiveness of low-level laser therapy (LLLT) in reducing pain and promoting healing of nipple trauma in postpartum women, as well as to assess participants satisfaction with the intervention."},{"label":"METHODS","text":"This multicentric, controlled, randomized, double-blind clinical trial included 60 women equally divided into an experimental group (2 J of red light at the nipple's central point and 4 J of infrared light in a cross pattern over the areolar region) and a sham group. Pain intensity was measured using the Numeric Rating Scale before, during, and up to 7 days after the intervention, and healing was assessed using a validated instrument. Intention-to-treat analysis was conducted."},{"label":"RESULTS","text":"We found a significant reduction in pain in the experimental group, with relief observed 30 min (p = 0.0439) after the LLLT application. Pain diary analyses indicated that, compared to the sham group, the experimental group reported lower pain intensity at 1h (p = 0.0485), 6h (p = 0.0194), 12h (p = 0.0033), and 7 days after the intervention (p = 0.0085). There was no significant difference in the level of satisfaction between groups (p = 0.652), and no adverse effects were identified."},{"label":"CONCLUSION","text":"LLLT proved to be a safe, effective, and feasible approach for managing pain associated with nipple trauma in the early postpartum, providing maternal comfort and supporting the continuation of exclusive breastfeeding."}],"keywords":["Breastfeeding","low level laser therapy","nipple","pain","wound and injuries"]},{"pmid":"42272970","title_fr":"LED 630 nm, fonction ovarienne et fertilité chez la femme d'âge reproductif avancé","type":"preclinical","level":4,"pop":"adulte","ctx":["fertilité"],"aim":"traitement","mode":["LED"],"nm":[630],"n":null,"effect":"favorable","theme":"Fertilité","l1":"La LED 630 nm améliore la fonction mitochondriale des ovocytes chez la souris âgée ; dans un pilote clinique, un dispositif portable augmente le compte de follicules antraux (2 → 6).","l2":"Mécanisme : activation du complexe II mitochondrial (SDHB). Chez les femmes à réserve ovarienne diminuée, le nombre d'ovocytes recueillis tend à augmenter (2 → 5, NS).","l3":{"points":["AFC : médiane 2 → 6 (p = 0,011)."],"limites":["Pilote sans témoin."],"pratique":"—"},"topic":"gynecologie","title":"630 nm LED phototherapy enhances ovarian function and fertility potential in advanced reproductive age females.","journal":"Bioengineering & translational medicine","journal_abbr":"Bioeng Transl Med","authors":["Su T","Wan Y","Fang F","et al."],"date":"2026-02-20","year":2026,"week":"2026-S08","doi":"10.1002/btm2.70117","pmcid":"PMC13247421","license":"cc by","oa":true,"pdf":"pdfs/42272970.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Ovarian aging, a major contributor to declining fertility in women of advanced reproductive age (ARA), is strongly associated with impaired mitochondrial function within oocytes. Although current mitochondrial-targeted strategies can improve ovarian function, their clinical application remains limited by cost and side effects. In this study, 630 nm light-emitting diode (LED) phototherapy is shown to ameliorate ovarian aging phenotypes in ARA mice by enhancing mitochondrial complex II activity via upregulation of succinate dehydrogenase subunit B (SDHB). This intervention restores oocyte adenosine triphosphate (ATP) production, improves meiotic progression, and significantly increases blastocyst formation. To assess translational feasibility, a wearable 630 nm LED phototherapy device is developed and evaluated in a pilot clinical study in women with diminished ovarian reserve (DOR). After treatment, the antral follicle count (AFC) significantly increases from a median of 2 (IQR 1-5) to 6 (IQR 2-7; p = 0.011), and the number of oocytes retrieved showed a non-significant tendency to increase from 2 (IQR 1-5) to 5 (IQR 2-7; p = 0.083), indicating a potential improvement in ovarian reserve. These findings demonstrate that 630 nm LED phototherapy enhances mitochondrial function and oocyte competence, providing a promising non-invasive strategy to improve fertility in women affected by ovarian aging."}],"keywords":["630 nm LED phototherapy","SDHB","mitochondrial function","oocyte quality","ovarian aging"]},{"pmid":"41704470","title_fr":"PBM d'un phénomène de rappel radique déclenché par le cisplatine chez une patiente atteinte de cancer du col : cas et revue","type":"cases","level":4,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":["laser","LED"],"nm":[450,590,660,808],"n":1,"effect":"favorable","theme":"Après cancer","l1":"Une patiente avec réaction de rappel radique vulvaire, anale et inguinale après cisplatine s'améliore nettement en une semaine de PBM multi-longueurs d'onde (laser 660/808 nm, LED 450 et 590 nm).","l2":"Revue exploratoire (8 études : traitements surtout corticoïdes topiques et antihistaminiques) et cas clinique. La PBM associe réparation tissulaire (660/808 nm), traitement de la sténose vaginale (450 nm) et de l'hyperpigmentation (590 nm).","l3":{"points":["Sténose vaginale et fissures améliorées."],"limites":["Cas unique."],"pratique":"Option à connaître pour les toxicités cutanéomuqueuses pelviennes rares."},"topic":"gynecologie","title":"Photobiomodulation therapy approach to a rare phenomenon of radiation recall reaction triggered by cisplatin in a cervical cancer patient: a case report and scoping review.","journal":"Frontiers in oncology","journal_abbr":"Front Oncol","authors":["Gomes P","de Abreu WC","Dos Reis RG","et al."],"date":"2026-02-02","year":2026,"week":"2026-S06","doi":"10.3389/fonc.2025.1700942","pmcid":"PMC12907206","license":"cc by","oa":true,"pdf":"pdfs/41704470.pdf","cited_by":1,"pub_types":["Case Reports"],"abstract":[{"label":"PURPOSE","text":"Radiation recall reaction (RRR) is a rare and poorly understood phenomenon of tissue radiotoxicity. It is typically triggered by exposure to certain agents, most commonly cytotoxic drugs such as cisplatin. We conducted a scoping review following the methodology proposed by the JBI collaboration and PRISMA-ScR extension. It aimed to map the evidence concerning the treatment of RRR triggered by cisplatin."},{"label":"METHODS","text":"Searches were performed in PubMed/MEDLINE, EMBASE, Web of Science Core Collection, Cochrane Database, and ProQuest™ on March 9, 2025. Eligible studies included primary research, guidelines, and study protocols that addressed RRR as a primary or secondary outcome. A case report was also described."},{"label":"RESULTS","text":"Eight studies were included, and the main treatments for RRR were topical steroids and antihistamines. A 36-year-old woman with cervical cancer developed intense hyperpigmentation in the inguinal, vulvar, and anal areas, along with anal and labial fissures, dry desquamation in the inguinal region, and vaginal stenosis, 3 days after cisplatin. The diagnosis was RRR affecting mucosa and skin in the intimate region. Photobiomodulation therapy (PBMT) was initiated using lasers emitting wavelengths of 660 and 808 nm for tissue repair in the vulva, anus, and groin, and LEDs emitting 450 nm for vaginal stenosis and 590 nm for hyperpigmentation. Following the first PBMT session, the patient showed an excellent clinical response after 1 week, with a significant reduction in the severity of RRR."},{"label":"CONCLUSION","text":"PBMT appears to be a viable, non-invasive, and low-cost treatment option for RRR, with no reported side effects."}],"keywords":["antineoplastic agents","case reports","low-level light therapy","radiation recall reaction","scoping review","uterine cervical neoplasms"]},{"pmid":"41616809","title_fr":"Moyens électrophysiques contre la douleur périnéale aiguë après accouchement : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":1970,"effect":"neutre","theme":"Périnée post-partum","key":true,"l1":"17 essais (1 970 accouchées) : la cryothérapie est la mieux prouvée contre la douleur périnéale ; le laser basse énergie n'est pas plus efficace que le placebo (confiance modérée).","l2":"Méta-analyse avec GRADE. Cryothérapie : −1,57 point jusqu'à 4 h (confiance élevée). TENS : efficace associée aux soins de routine (confiance modérée). Laser : DM 0,03 contre placebo.","l3":{"points":["LLLT contre placebo : DM 0,03 (IC95 % −0,69 à 0,76)."],"limites":["Protocoles laser souvent à faible dose."],"pratique":"Préférer la cryothérapie en première intention pour la douleur périnéale immédiate."},"topic":"gynecologie","title":"Electrophysical resources for the treatment of acute perineal pain after vaginal delivery: A systematic review with meta-analysis.","journal":"The journal of pain","journal_abbr":"J Pain","authors":["Beleza ACS","Jorge CH","Liebano RE","et al."],"date":"2026-01-28","year":2026,"week":"2026-S05","doi":"10.1016/j.jpain.2026.106205","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"","text":"This systematic review aimed at synthesizing evidence regarding the effectiveness of electrophysical resources for perineal acute pain relief after vaginal delivery in the early post-partum period. It included randomized controlled trials comparing electrophysical resources with reference groups for acute pain relief on primiparous women. Search strategy was conducted in PubMed, Embase, Lilacs, Scopus, Cochrane and Web of Science. Meta-analysis was conducted to synthesize the results. The risk of bias was assessed using PEDro scale and certainty of evidence was assessed using the GRADE approach. Seventeen studies with 1970 postpartum women were included. The evidence synthesis demonstrated high confidence in the positive effects of cryotherapy for perineal pain relief up to 4 h after its application, compared to routine care (mean difference -1.57, 95% CI: -2.18 to -0.96). Low-level laser therapy (LLLT) was found to be ineffective when compared to a placebo, with evidence showing moderate confidence (0.03, 95% CI: -0.69-0.76). The evidence for Transcutaneous Electrical Nerve Stimulation (TENS) was less conclusive: very low confidence was found regarding its positive effects compared to a placebo (MD -2.63, 95% CI: -4.85 to -0.41). Moderate confidence was found regarding TENS compared to routine care (MD -1.49, 95% CI: -1.90 to -1.09). In conclusion, high-certainty evidence on the effectiveness of cryotherapy applied after 1-4 h postpartum and moderate-certainty evidence on the effectiveness of TENS when combined with routine care. Moderate-certainty evidence indicates a lack of evidence on LLLT for perineal pain control. PERSPECTIVE: Cryotherapy can be recommended for perineal pain relief based on high and moderate confidence evidence. Applications should be performed considering patient preferences. Perineal application of LLLT, TENS and US require further studies with stronger protocol and methodological design to provide more consistent conclusions about their clinical use in postpartum period."}],"keywords":["Electrophysical Agents","Pain Management","Parturition","Physical Therapy Modalities"]},{"pmid":"41682644","title_fr":"PBM et douleur et cicatrisation après épisiotomie : revue systématique et méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Périnée post-partum","l1":"Huit études : pas de bénéfice significatif de la PBM sur la douleur (DMS 0,04) ni la cicatrisation après épisiotomie ; certitude GRADE très faible.","l2":"Méta-analyse incluant essais randomisés et non randomisés. Hétérogénéité considérable (I² 91–94 %), plusieurs essais à risque de biais élevé.","l3":{"points":["Douleur : DMS 0,04 (IC95 % −0,60 à 0,68)."],"limites":["Hétérogénéité très forte."],"pratique":"—"},"topic":"gynecologie","title":"The Effectiveness of Photobiomodulation Therapy on Perineal Pain and Wound Healing After Episiotomy-A Systematic Review and Meta-Analysis.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Alayat MS","Sroge RA","Alshiakh FM","et al."],"date":"2026-01-25","year":2026,"week":"2026-S04","doi":"10.3390/jcm15030964","pmcid":"PMC12897679","license":"cc by","oa":true,"pdf":"pdfs/41682644.pdf","cited_by":1,"pub_types":["Review"],"abstract":[{"label":"","text":"Objective: the aim of this systematic review and meta-analysis was to evaluate the effectiveness of photobiomodulation therapy (PBM) on perineal pain and wound healing following episiotomy. Methods: Electronic databases were searched for randomized controlled trials (RCTs) and non-RCTs investigating PBM after episiotomy. Risk of bias was assessed using RoB 2 for RCTs and ROBINS-I for non-RCTs. The certainty of evidence was evaluated using the Grading of Recommendations Assessment, Development and Evaluation (GRADE) approach. Meta-analyses were performed using random-effects models. Results: Eight studies were included in the systematic review, and six studies were included in the meta-analysis. According to RoB 2, one trial was judged at low risk of bias, two trials raised some concerns, and three trials were at high risk of bias. ROBINS-I showed the serious risk of bias of two non-RCTs. GRADE for both pain and wound-healing outcomes was rated as very low. Meta-analysis of pain showed no significant difference between PBM and control groups (SMD = 0.04; 95% CI -0.60 to 0.68; p = 0.89), with considerable heterogeneity (I2 = 91%). For wound-healing outcomes, meta-analysis showed no significant difference (MD = 0.94; 95% CI -0.69 to 2.56; p = 0.26), with substantial heterogeneity (I2 = 94%). Conclusions: PBM therapy did not demonstrate a significant benefit for reducing perineal pain or improving wound healing after episiotomy compared with control interventions. Interpretation of these findings should be made cautiously due to small study numbers, substantial heterogeneity, and the inability to perform sensitivity or subgroup analyses, highlighting the need for high-quality RCT with standardized PBM protocols before clinical recommendations can be made."}],"keywords":["episiotomy","low-level laser therapy","perineal pain","photobiomodulation therapy","systematic review and meta-analysis","wound healing"]},{"pmid":"41567046","title_fr":"Gynécologie régénérative et fonctionnelle en 2025 : promesses, preuves et applications","type":"review","level":5,"pop":"adulte","ctx":["général"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Revue générale","l1":"Revue de la Revue médicale suisse : PRP, toxine, acide hyaluronique, lasers, radiofréquence et PBM sont prometteurs dans les pathologies vulvaires, la vulvodynie et le périnée post-partum, avec un niveau de preuve encore inégal.","l2":"Synthèse francophone récente. Ces techniques doivent compléter la prise en charge conventionnelle et être réalisées par des praticiens formés.","l3":{"points":["Article en français."],"limites":["Revue narrative."],"pratique":"Bonne introduction francophone."},"topic":"gynecologie","title":"[Regenerative and functional gynecology in 2025 Promises, evidence, and current clinical applications].","journal":"Revue medicale suisse","journal_abbr":"Rev Med Suisse","authors":["Azuaga Martinez A","Fernandez Perez M","Martinez de Tejada B"],"date":"2026-01-22","year":2026,"week":"2026-S04","doi":"10.53738/REVMED.2026.22.946.48146","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["English Abstract","Review"],"abstract":[{"label":"","text":"Regenerative and functional gynecology, which is rapidly expanding thanks to biotechnologies and energy-based devices, aims to restore the function and trophicity of tissues. It relies on biological approaches (platelet-rich plasma, botulinum toxin, hyaluronic acid) and physical modalities (lasers, radiofrequency, photobiomodulation), which show promise in the treatment of various vulvar pathologies, vulvodynia, as well as in postpartum perineal repair. Despite encouraging results, the level of evidence remains inconsistent. These techniques should complement conventional management and be performed by trained practitioners in accordance with regulatory standards. This article provides an updated synthesis of the current perspectives of regenerative medicine in gynecology."}],"keywords":[]},{"pmid":"41450164","title_fr":"Dispositifs énergétiques et douleur et cicatrisation de l'épisiotomie : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":1377,"effect":"neutre","theme":"Périnée post-partum","l1":"Treize études (1 377 femmes) : l'infrarouge réduit un peu la douleur d'épisiotomie, le laser basse énergie ne fait pas mieux que le placebo.","l2":"Laser contre placebo : douleur DMS −0,31 (NS), cicatrisation DMS 0,23 (NS).","l3":{"points":["Infrarouge : DMS −0,50."],"limites":["Hétérogénéité."],"pratique":"—"},"topic":"gynecologie","title":"Efficacy of energy-based devices on episiotomy pain and healing: A systematic review and meta-analysis.","journal":"International journal of gynaecology and obstetrics: the official organ of the International Federation of Gynaecology and Obstetrics","journal_abbr":"Int J Gynaecol Obstet","authors":["Regev-Sadeh S","Nahshon C","Cohen N","et al."],"date":"2025-12-26","year":2025,"week":"2025-S52","doi":"10.1002/ijgo.70764","pmcid":"PMC13173607","license":"cc by","oa":true,"pdf":"pdfs/41450164.pdf","cited_by":1,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"BACKGROUND","text":"Episiotomy is a common obstetric procedure often associated with significant postpartum pain and delayed wound healing. Conventional treatments provide limited relief and might not be suitable for all women. Energy-based therapies, including infrared irradiation and low-level laser therapy (LLLT), a non-thermal photo biomodulation technique, have shown potential for enhancing pain relief and tissue recovery, but their effectiveness in post-episiotomy care remains unclear."},{"label":"OBJECTIVE","text":"This study evaluates the efficacy of energy-based treatments on pain reduction and wound healing following episiotomy in postpartum women."},{"label":"METHOD","text":"A database search was performed using MEDLINE with Ovid and PubMed interfaces, The Cochrane Central Register of Controlled Trials (CENTRAL), Embase, ClinicalTrials.gov and Web of Science up to December 2024. Prospective randomized and non-randomized controlled trials were considered for inclusion. No restriction was imposed regarding the year or language of publication. Included studies compared one method of energy-based treatment to placebo, standard of care, no treatment or another intervention. Data were synthesized using RevMan Web (Version 8.14.0) with a random-effects model to account for interstudy heterogeneity. Pooled results were expressed as standardized mean differences (SMDs) with 95% confidence intervals. Evidence certainty was assessed using the GRADE approach."},{"label":"RESULTS","text":"A total of 173 studies were identified through database searches, of which 13 studies were included in the final analysis, encompassing a total of 1377 patients. Analyses were stratified by intervention type: infrared irradiation versus standard care or no treatment (n = 1088), LLLT versus placebo (n = 209) and LLLT versus therapeutic ultrasound (n = 80). Infrared irradiation reduced postpartum pain compared to standard care or no treatment (SMD = -0.50, 95% confidence interval [CI]: -0.98 to -0.02, I2 = 88%, P < 0.01); however, it did not improve healing measures. LLLT showed no improvement in pain reduction (SMD: -0.31, 95% CI: -0.72 to 0.11, I2 = 53%, P = 0.1) or healing (SMD: 0.23, 95% CI: -0.18 to 0.63, I2 = 0%, P = 0.85) compared to placebo. LLLT compared to therapeutic ultrasound did not show advantage in pain or healing and was hindered by very high heterogeneity."},{"label":"CONCLUSION","text":"Infrared therapy might reduce pain after episiotomy, although its effect on wound healing remains inconclusive. LLLT did not demonstrate significant benefits for pain relief or healing."},{"label":"PROSPERO REGISTRATION","text":"CRD42024608543; registered December 2024."}],"keywords":["episiotomy","healing","infrared","low‐level laser","pain","post‐partum","visual analogue scale","wound"]},{"pmid":"41404945","title_fr":"Sécurité et performance d'une PBM par sonde vaginale (MILTA GYNECO) dans le syndrome génito-urinaire","type":"nrct","level":4,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["intravaginal"],"nm":[],"n":25,"effect":"favorable","theme":"Syndrome génito-urinaire","key":true,"metric":{"kind":"values","outcome":"Douleur pendant les rapports (0–10)","a_label":"Avant","a":7.65,"b_label":"Après 6 séances","b":3.89,"unit":"/10"},"l1":"Étude française sur 25 femmes ménopausées en échec des traitements : six séances de PBM par sonde vaginale sont sûres (effets mineurs, surtout sensation de chaleur) et réduisent la dyspareunie de 7,7 à 3,9/10.","l2":"Première étude chez l'humain de ce dispositif, avec la sécurité comme critère principal. 146 des 148 événements indésirables sont mineurs (89 % de sensations de chaleur). L'index de santé vaginale passe de 12,7 à 17,6. La plupart des patientes se disent améliorées.\n\nLes auteurs annoncent un essai randomisé.","l3":{"points":["Dyspareunie : 7,65 → 3,89 (p < 0,0001).","VHI : 12,68 → 17,63 (p < 0,0001)."],"limites":["Sans témoin ; financement industriel probable."],"pratique":"Dispositif disponible en France ; efficacité à confirmer."},"topic":"gynecologie","title":"Safety and performance of photobiomodulation delivered by vaginal probe in patients with genitourinary syndrome of menopause.","journal":"Climacteric : the journal of the International Menopause Society","journal_abbr":"Climacteric","authors":["Salerno J","Serrand C","Kabani S","et al."],"date":"2025-12-17","year":2025,"week":"2025-S51","doi":"10.1080/13697137.2025.2591279","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"Genitourinary syndrome of menopause (GSM) has a negative impact on quality of life. Treatments for GSM are largely hormonal, yet some patients remain symptomatic after recommended treatments. Photobiomodulation therapy (PBMT) is a promising non-hormonal technique."},{"label":"METHOD","text":"In this prospective, first-in-human, medical device safety study, postmenopausal patients with pelvic pain due to vaginal atrophy after failure of non-invasive therapies for >3 months were recruited. Exclusion criteria included pelvic pain of physical and/or psychological origin, treatment for cancer or immunosuppression. Patients received six weekly PBMT sessions using the MILTA GYNECO vaginal probe (PHYSIOQUANTA). The primary outcome was device safety, according to patient-reported adverse events. Secondary outcomes were vaginal mucosal health (vaginal health index [VHI]), pain (0-10 visual analog scale), vaginal flora and patient satisfaction (Patient Global Impression of Change [PGI-C])."},{"label":"RESULTS","text":"Twenty-five patients were recruited and analyzed, with an average age of 58.7 years. In total, 148 adverse events were declared, of which 146 were minor (grade I) and most were for heat sensation (89.2%). Significant improvements were found in pain during intercourse (7.65 [±1.95] before versus 3.89 [±2.44] after, p < 0.0001) and in vaginal health according to the VHI score (12.68 [±4.20] before versus 17.63 [±4.35] after, p < 0.0001). According to the PGI-C score, most patients rated their condition as improved."},{"label":"CONCLUSION","text":"Even when applying a broad definition for adverse events, these preliminary data suggested that PBMT using the MILTA GYNECO vaginal probe was safe, with high patient satisfaction. The next step is to assess the efficacity of the medical device in a randomized trial."}],"keywords":["Medical device","menopause","non-hormonal therapy","photobiomodulation","safety","vaginal atrophy"]},{"pmid":"41255349","title_fr":"Une seule application de PBM contre la douleur périnéale post-partum : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":60,"effect":"neutre","theme":"Périnée post-partum","l1":"Chez 60 accouchées avec traumatisme périnéal, une séance de PBM (rouge sur la lésion, infrarouge autour) ne fait pas mieux que la simulation à 30 minutes ni à 36 heures.","l2":"Essai brésilien bicentrique en double aveugle. La douleur baisse dans les deux groupes ; 84 % de satisfaction.","l3":{"points":["NRS 30 min : 3,63 contre 2,53 (p = 0,089)."],"limites":["Séance unique."],"pratique":"Une application unique ne suffit pas."},"topic":"gynecologie","title":"Effects from a single application of photobiomodulation on pain intensity from perineal trauma related to childbirth: A randomized controlled trial.","journal":"International journal of gynaecology and obstetrics: the official organ of the International Federation of Gynaecology and Obstetrics","journal_abbr":"Int J Gynaecol Obstet","authors":["Gondim EJL","Nascimento SL","Gaitero MVC","et al."],"date":"2025-11-19","year":2025,"week":"2025-S47","doi":"10.1002/ijgo.70674","pmcid":"PMC13094685","license":"cc by","oa":true,"pdf":"pdfs/41255349.pdf","cited_by":2,"pub_types":["Randomized Controlled Trial","Multicenter Study"],"abstract":[{"label":"OBJECTIVE","text":"To analyze the effects of a single photobiomodulation (PBM) application on perineal pain and healing in women in the immediate postpartum period."},{"label":"METHODS","text":"Randomized controlled trial, double-blind, two-center, with 60 postpartum women with perineal trauma and pain scoring 4 or more on the Numeric Rating Scale (NRS). The experimental group received red light to the lesion and infrared light around it, while the sham group received a simulation. We assessed pain with the NRS and Short-Form McGill Pain Questionnaire (SF-MPQ); tissue healing with the REEDA scale (Redness, Edema, Ecchymosis, Discharge, Approximation) at baseline, 30 min (primary outcome), and 12-36 h after intervention and satisfaction with a Likert scale 7-10 days post-intervention. We conducted bivariate analyses and an analysis of variance for repeated measures."},{"label":"RESULTS","text":"The experimental and sham groups showed pain reduction with no difference between them for pain scores or healing 30 min post-intervention (mean ± SD: NRS 3.63 ± 2.57 vs 2.53 ± 2.15; P = 0.089; SF-MPQ 7.83 ± 8.32 vs 5.10 ± 6.42; P = 0.108; and REEDA 5.57 ± 3.05 vs 4.47 ± 2.42; P = 0.175). Analysis of variance revealed no significant interaction between time and group at any time point evaluated. Of the participants, 84.09% were satisfied or very satisfied with the intervention."},{"label":"CONCLUSIONS","text":"Although both groups experienced a reduction in pain after the intervention, a single PBM application with these parameters was not superior to a sham treatment. Future research could explore multiple applications or different parameters."},{"label":"TRIAL REGISTRATION","text":"Laser for Pain Relief in Nipple and Perineal Trauma in Postpartum; UTN code U1111-1279-3594 (https://ensaiosclinicos.gov.br/rg/RBR-2qm8jrp/1)."}],"keywords":["episiotomy","low‐level light therapy","pain","perineum","postpartum period"]},{"pmid":"41179650","title_fr":"Laser-acupuncture versus électroacupuncture dans la dysménorrhée avec déséquilibre autonome : essai pilote randomisé","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser"],"nm":[],"n":114,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez 114 femmes, la laser-acupuncture et l'électroacupuncture soulagent autant la dysménorrhée et rééquilibrent le système nerveux autonome mieux que la simulation.","l2":"Essai taïwanais à trois bras. Les effets sur la douleur et la qualité de vie sont similaires ; l'électroacupuncture abaisse davantage la PGE2.","l3":{"points":["Variabilité cardiaque : laser supérieur dans le sous-groupe LF/HF bas."],"limites":["Pilote."],"pratique":"La laser-acupuncture offre une alternative sans aiguille."},"topic":"gynecologie","title":"Comparative Efficacy of Low-Level Laser Acupuncture and Electroacupuncture in Women With Dysmenorrhea and Autonomic Imbalance: A Pilot Randomized-Controlled Trial.","journal":"Pain research & management","journal_abbr":"Pain Res Manag","authors":["Chien TJ","Chang YI","Liao LL","et al."],"date":"2025-10-23","year":2025,"week":"2025-S43","doi":"10.1155/prm/3494216","pmcid":"PMC12575050","license":"cc by","oa":true,"pdf":"pdfs/41179650.pdf","cited_by":1,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"BACKGROUND","text":"Electroacupuncture (EA) has been widely applied in treating dysmenorrhea and autonomic dysfunction. Low-level laser acupuncture (LLLA), a noninvasive acupuncture, has been used clinically, but efficacy is uncertain. This study aimed to explore the efficacy of LLLA, EA, and sham-controlled LLLA on pain, heart rate variability (HRV) activity, and symptom improvement in dysmenorrhea with autonomic imbalance."},{"label":"METHOD","text":"In a randomized, controlled design, a total of 114 women with dysmenorrhea and autonomic imbalance were randomly allocated to three groups: sham LLLA, LLLA, and EA. The primary outcomes are pain (VAS), and HRV parameters, and the secondary outcomes are symptom assessment (verbal multidimensional scoring system), prostaglandin E, progesterone levels, and the SF-12 quality-of-life assessment."},{"label":"RESULTS","text":"Contrast to the sham acupuncture, LLLA and EA effectively reconciled the pain and sympathetic/parasympathetic tone significantly, no matter the vagus or sympathetic deviated status (low or high LF/HF group). LLLA was superior to EA in terms of SDNN, RMMSD, and PNN50 (p < 0.001) in the low LF/HF group in intergroup analysis. For all participants' analysis, the effects of LLLA and EA were similar for pain assessment (VAS) and quality of life (SF-12) (p < 0.05). In proinflammatory cytokine measurement, EA showed a significant decrease in prostaglandin E2 (PGE2) levels (p = 0.022)."},{"label":"CONCLUSION","text":"This pilot study showed both LLLA and EA effectively relieve dysmenorrhea without a placebo effect, LLLA is noninferior to EA in autonomic dysfunction, and the effect is even more prominent in low LF/HF status (a relatively lower energy status). Given its noninvasiveness, LLLA could be an alternative treatment and warrants further large-scale study."},{"label":"TRIAL REGISTRATION","text":"ClinicalTrials.gov identifier: NCT04178226."}],"keywords":["autonomic dysfunction","dysmenorrhea","electroacupuncture","heart rate variation","low-level laser acupuncture"]},{"pmid":"42038848","title_fr":"Protocole innovant de laser basse énergie transvaginal et intravésical dans l'incontinence d'effort : série de cas","type":"cases","level":4,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[],"n":null,"effect":"favorable","theme":"Incontinence urinaire","l1":"Série iranienne : un laser combiné transvaginal et intravésical semble sûr et prometteur dans l'incontinence urinaire d'effort de la péri- et post-ménopause.","l2":"Résumé peu détaillé ; enregistrement rétrospectif.","l3":{"points":["IRCT20231203060255N2."],"limites":["Série de cas, données peu détaillées."],"pratique":"—"},"topic":"gynecologie","title":"Effect of Innovative Low-level Laser Therapy Protocol for Stress Urinary Incontinence: A Case Series Study : Low-level Laser Therapy for Stress Urinary Incontinence.","journal":"Galen medical journal","journal_abbr":"Galen Med J","authors":["Hoseinzade F","Ayazi M","Tafazoli Harandi N","et al."],"date":"2025-08-27","year":2025,"week":"2025-S35","doi":"10.31661/gmj.v14i.3841","pmcid":"PMC12503022","license":"cc by","oa":true,"pdf":"pdfs/42038848.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Stress urinary incontinence (SUI) is a prevalent condition characterized by involuntary urine leakage during physical activities. This condition can significantly impact a woman's quality of life. Treatment options for SUI include behavioral therapy, medication, and surgery. However, non-pharmacological methods such as low-level laser therapy (LLT) have demonstrated the potential to promote tissue repair, reduce inflammation, and improve pelvic floor muscle function in various pelvic floor disorders. Despite these benefits, the effectiveness of combined transvaginal and intra-bladder LLT for managing SUI has not been extensively studied. This case series aimed to assess the safety and efficacy of a novel regimen using concurrent transvaginal and intra-bladder LLT for the treatment of stress urinary incontinence in perimenopausal and postmenopausal women. The results appear promising, and further investigation is recommended. Trial Registration: This clinical trial was registered in the Iranian Registry of Clinical Trials (IRCT) under the registration number IRCT20231203060255N2, on 30 June 2024 (retrospectively registered)."}],"keywords":["Intra-bladder Laser","Low-level Laser Therapy","Stress Urinary Incontinence","Transvaginal Laser"]},{"pmid":"40840565","title_fr":"Photothérapie dans la dysménorrhée primaire : revue systématique et méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":645,"effect":"favorable","theme":"Dysménorrhée","key":true,"l1":"Douze essais (645 femmes) : à 12 semaines, la PBM basse énergie réduit la douleur de la dysménorrhée de 4 points sur l'échelle VAS par rapport à la simulation.","l2":"Méta-analyse enregistrée (PROSPERO), 12 bases dont chinoises et coréennes. Laser basse énergie (6 essais), haute intensité (2), lumière polarisée (1).\n\nContre simulation : DM −4,02 (IC95 % −7,21 à −0,82). Contre contraceptif oral : avantage de 0,91 point à 12 semaines. La plupart des études sont à risque de biais.","l3":{"points":["Contre simulation : DM −4,02 à 12 semaines (3 essais, n = 150)."],"limites":["Peu d'essais par comparaison."],"pratique":"La PBM est une option non hormonale documentée dans la dysménorrhée primaire."},"topic":"gynecologie","title":"Effectiveness and safety of light therapy for treating primary dysmenorrhea: A systematic review and meta-analysis of randomized controlled trials.","journal":"Complementary therapies in medicine","journal_abbr":"Complement Ther Med","authors":["Ang L","Song E","Choi S","et al."],"date":"2025-08-19","year":2025,"week":"2025-S34","doi":"10.1016/j.ctim.2025.103232","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"OBJECTIVE","text":"Primary dysmenorrhea, defined as painful menstrual cramps without identifiable pelvic pathology, is a prevalent gynecological condition that significantly impacts quality of life. Emerging evidence suggests that light-based therapies, including low-level light therapy (LLLT) and high-intensity light therapy (HILT), may offer a non-pharmacological approach to managing menstrual pain. This systematic review aimed to assess the effectiveness and safety of light therapy in individuals with primary dysmenorrhea."},{"label":"METHODS","text":"For this systematic review and meta-analysis, we searched twelve electronic databases, including PubMed, Cochrane Library, Embase, Allied and Complementary Medicine Database (AMED), APA PsycINFO, CINAHL Complete, Web of Science, China National Knowledge Infrastructure (CNKI), Chinese Scientific Journals Database (VIP), WanFang Data, Research Information Sharing Service (RISS), and Oriental Medicine Advanced Searching Integrated System (OASIS) to identify randomized controlled trials (RCTs) evaluating the effectiveness of light therapy for primary dysmenorrhea. The search was conducted up to February 4, 2025. Two reviewers independently assessed articles for eligibility and extracted data. Disagreements were resolved through discussion. Critical outcomes were pain scales such as the Visual Analog Scale (VAS) or Numeric Rating Scale (NRS). Risk of bias was assessed using the Cochrane Risk of Bias Tool (RoB 2), and meta-analyses were conducted using RevMan software. The study protocol was registered in PROSPERO (CRD420250655437). Available from https://www.crd.york.ac.uk/PROSPERO/view/CRD420250655437."},{"label":"SETTING","text":"Twelve studies involving 645 participants met the inclusion criteria, highlighting the potential therapeutic role of light therapy."},{"label":"RESULTS","text":"Interventions primarily involved LLLT (n = 6), with some using HILT (n = 2) or polarized light (n = 1). Meta-analysis of three RCTs showed a statistically significant reduction in pain after 12 weeks of LLLT compared to sham treatment (n = 150, mean difference (MD) = -4.02, 95 % confidence interval (CI): -7.21 to -0.82; p = 0.01). Similarly, LLLT also demonstrated greater pain reduction compared to oral contraceptives after 12 weeks (n = 156, MD = 0.91, 95 % CI: 0.49-1.33, p < 0.0001). Most studies were assessed as having some concerns regarding risk of bias. Reported adverse effects were minor and transient, with no serious adverse events noted."},{"label":"CONCLUSION","text":"Light therapy, particularly LLLT, may represent a safe and effective non-pharmacological intervention for the management of primary dysmenorrhea. Despite promising results, variations in treatment protocols contributed to heterogeneity and hindered identification of optimal parameters. Limited trial numbers and regional concentration also reduce generalizability. Further high-quality, large-scale RCTs with standardized treatment protocols are needed to confirm clinical efficacy and define optimal therapeutic parameters."}],"keywords":["Light therapy","Non-pharmacological treatment","Pain management","Primary dysmenorrhea","Randomized controlled trials","Systematic review and Meta-analysis"]},{"pmid":"40727624","title_fr":"PBM lumière bleue des plaies compliquées en chirurgie du sein : étude pilote","type":"cohort","level":4,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":["LED"],"nm":[],"n":27,"effect":"favorable","theme":"Sénologie","l1":"Chez 27 patientes avec nécrose cutanée ou désunion après reconstruction mammaire, la lumière bleue (EmoLED) en complément des soins guérit les plaies en 5 séances médianes.","l2":"Étude italienne sans témoin. Tabac, IMC, cicatrice en T inversé, lambeaux fins et implant rétropectoral sont associés à plus de séances.","l3":{"points":["35 complications traitées."],"limites":["Sans groupe témoin."],"pratique":"—"},"topic":"gynecologie","title":"Pilot Study: Blue Light Photobiomodulation for the Treatment of Complicated Wounds in Breast Surgery.","journal":"Plastic and reconstructive surgery. Global open","journal_abbr":"Plast Reconstr Surg Glob Open","authors":["Ferrucci M","Milardi F","Passeri D","et al."],"date":"2025-07-28","year":2025,"week":"2025-S31","doi":"10.1097/GOX.0000000000006989","pmcid":"PMC12303515","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/40727624.pdf","cited_by":1,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Blue light photobiomodulation has demonstrated efficacy in accelerating the healing process of chronic ulcers and various dermatologic conditions. Yet, its application in enhancing the healing of complicated postsurgical breast wounds, particularly in reconstructive surgery, remains unexplored."},{"label":"METHODS","text":"This pilot study included female patients who developed complicated wounds after reconstructive breast surgery at our institution between March 2022 and September 2023. All patients were treated with blue light therapy (EmoLED) in addition to standard wound care. We examined healing times, the number of EmoLED sessions required, and complication severity."},{"label":"RESULTS","text":"Among 27 female patients (median age 54 y), 74.1% underwent mastectomy with implant-based reconstruction, whereas the remaining patients underwent contralateral second-stage reduction mammaplasty. Over a 19-month median follow-up, 35 complications were recorded: 18 skin necroses, 9 partial nipple-areolar complex necroses, and 8 wound dehiscences. The median number of EmoLED sessions required was 5, typically administered weekly. A higher body mass index (P = 0.075), smoking (0.093), Wise-pattern incision (P = 0.007), thin mastectomy skin flaps (P = 0.034), and subpectoral implant placement (P = 0.033) were associated with an increased number of EmoLED treatments required and longer healing times. The development of Clavien-Dindo grade III complications was associated with diabetes mellitus (P = 0.001), body mass index greater than 30 kg/m2 (P = 0.029), smoking habit (P = 0.037), and thinner flap thickness (P = 0.052). Notably, no implant loss was reported."},{"label":"CONCLUSIONS","text":"The use of blue light therapy accelerated and optimized the healing process in complicated postsurgical breast wounds. Larger prospective studies are warranted to further validate these findings."}],"keywords":[]},{"pmid":"40532775","title_fr":"LED bleue en complément du traitement de la candidose vulvovaginale récidivante : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED","intravaginal"],"nm":[415],"n":13,"effect":"mitigé","theme":"Infections vulvovaginales","l1":"Essai pilote de 13 femmes : la LED bleue intravaginale (415 nm, 30 min) en plus du traitement standard est bien tolérée, mais le groupe témoin s'améliore aussi.","l2":"À 180 jours, 53,8 % des cultures sont négatives, surtout dans le groupe 30 minutes. Résultat peu concluant vu l'effectif.","l3":{"points":["Trois séances hebdomadaires."],"limites":["13 participantes."],"pratique":"—"},"topic":"gynecologie","title":"Blue light-emitting diode: a new adjuvant approach to conventional treatment of recurrent vulvovaginal candidiasis.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Bastiani Biondo I","Rossi Balbinotti R","Santos Grossi F","et al."],"date":"2025-06-17","year":2025,"week":"2025-S25","doi":"10.1016/j.pdpdt.2025.104685","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Recurrent vulvovaginal candidiasis (RVVC) presents challenges due to the adverse effects and resistance associated with prolonged antifungal therapy, highlighting the need for alternative treatments. This single-blind randomized trial evaluated intravaginal phototherapy with a 415 ± 13.7 nm blue LED as an adjunct to standard RVVC therapy. Participants were randomized to a control group (no light for 35 min) or experimental groups (light for 30 or 40 min) over three weekly sessions at 7 ± 3-day intervals. Clinical evaluations, microbiological analyses, and questionnaire assessments were conducted during the sessions and at 30 and 180 days, with symptom monitoring at 60, 90, 120, and 150 days. Thirteen women (mean age 28.92 years) were randomized into three groups: 30-minute (n = 5), 40-minute (n = 4), and control (n = 4). At 30 days, 61.5 % of participants showed a reduction of 50 % or more in the semiquantitative scores of signs and symptoms, rising to 76.9 % at 180 days, with the greatest improvements in the 30-minute and control groups. Significant symptom reduction was observed in the control group (p < 0.001). At 180 days, 53.8 % of participants had negative Candida cultures, predominantly in the 30-minute group. The therapy was well-tolerated, with high satisfaction scores in the control (5.00 ± 0.20) and 30-minute groups (4.20 ± 0.33). Phototherapy with a 415 ± 13.7 nm blue LED for 30 min demonstrated therapeutic potential as an adjunctive treatment for RVVC. Further studies with longer follow-up periods and larger sample sizes are needed to validate these findings and strengthen clinical evidence."}],"keywords":["Blue light","Candidiasis","Low level light","Photobiomodulation","Photodynamic Therapy","Vulvovaginal","Vulvovaginitis"]},{"pmid":"40500396","title_fr":"PBM des lésions du mamelon pendant l'allaitement : méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Allaitement","key":true,"metric":{"kind":"rr","outcome":"Douleur à la tétée (OR)","rr":0.43,"lo":0.23,"hi":0.79,"k":7},"l1":"Sept essais : la PBM réduit la douleur à la tétée (OR 0,43), accélère la cicatrisation des lésions du mamelon et améliore la qualité de vie ; certitude faible.","l2":"Revue enregistrée (PROSPERO), PRISMA 2020, GRADE. La plupart des essais sont à faible risque de biais.","l3":{"points":["OR 0,43 (IC95 % 0,23–0,79)."],"limites":["Certitude faible."],"pratique":"Option à proposer pour les crevasses douloureuses, pour prévenir le sevrage précoce."},"topic":"gynecologie","title":"Photobiomodulation as a promising approach in the management of nipple lesions during breastfeeding: a systematic review and meta-analysis of randomized clinical trials.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Oliveira Alves R","Faccioli Ragghianti MH","Nunes LP","et al."],"date":"2025-06-11","year":2025,"week":"2025-S24","doi":"10.1007/s10103-025-04531-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Meta-Analysis","Systematic Review"],"abstract":[{"label":"","text":"Nipple injuries are common and can cause intense pain, leading to early weaning in breastfeeding. This study investigates the efficacy of photobiomodulation therapy (PBM) in reducing pain and promoting the healing of nipple lesions in lactating women. The protocol of this study was registered in PROSPERO and followed the guidelines of the Preferred Reporting Items for Systematic Reviews and Meta-Analysis (PRISMA 2020). Electronic searches were conducted (PubMed/MEDLINE, Web of Science, Scopus, Embase, Cochrane Library and grey literature) until March-2024. The eligibility criteria were randomized clinical trials (RCTs). Meta-analysis was conducted using R software with the \"META\" package. The Odds Ratio (OR) effect measurement was calculated, and a fixed-effect model was applied with a confidence interval of 95%. The Cochrane collaboration tool was used to assess the risk of bias, and the GRADE approach was used to assess the quality of evidence. A total of 924 records were screened, and 7 studies meeting the criteria were included in this review. The findings indicated a notable decrease in breastfeeding-related pain, along with expedited healing of nipple injuries and improvement in quality of life among participants receiving PBM compared with control group. In addition, a meta-analysis confirmed less sucking pain for the PBM group OR 0.43 ([95% CI - 0.23 to 0.79]; p = 0.001). Most studies had a low risk of bias, and the certainty of evidence was classified as low. The results suggest that PBM may be a promising therapeutic approach to reduce pain and improve the healing of nipple lesions. However, more robust, and methodologically standardized randomized clinical trials are needed to confirm and elucidate these results."}],"keywords":["Breastfeeding","Nipples","Pain","Photobiomodulation","Systematic review"]},{"pmid":"40471351","title_fr":"LED bleue dans la candidose vulvovaginale récidivante : protocole d'essai randomisé","type":"protocol","level":0,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[401],"n":51,"effect":"—","theme":"Infections vulvovaginales","l1":"Protocole brésilien (51 femmes) comparant fluconazole seul, fluconazole + LED inactive et fluconazole + LED bleue active.","l2":"Critère principal : absence de Candida albicans.","l3":{"points":["Pas encore de résultats."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Protocol for a randomized clinical trial on the efficacy of blue light emitting diode in the treatment of recurrent vulvovaginal candidiasis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ramos JDGDS","da Costa MO","Dos Santos JLP","et al."],"date":"2025-06-05","year":2025,"week":"2025-S23","doi":"10.1007/s10103-025-04515-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"INTRODUCTION","text":"Blue light (BL) induces reactive oxygen species (ROS), exerting an antimicrobial effect. This study will assess its effectiveness in women with recurrent vulvovaginal candidiasis (RVVC)."},{"label":"METHODS","text":"This study was designed as a controlled, randomized, double-blind clinical trial. The intervention consists of applying a BL device with a wavelength of 401 ± 5 nm to the vulvovaginal region for 21 days, with two weekly sessions of 30 minutes each. The sample will consist of 51 women aged between 18 and 40 years, diagnosed with recurrent vaginal candidiasis and in a stable relationship. Participants will be randomly allocated to one of three groups: Group II: luconazole 200 mg; Group II: inactive BL in combination with luconazole 200 mg; Group III: active BL and luconazole 200 mg. The medication will be prescribed by a physician."},{"label":"RESULTS","text":"Participants will undergo assessments at baseline, after the first treatment, and on days 7, 14, 21, and the third day after the inal application to monitor outcomes. The primary outcome will be the absence of Candida Albicans (CA), while secondary outcomes include improvements in quality of life, sleep quality and reduction in levels of stress, anxiety and depression after treatment. Descriptive statistics and generalized models with Bonferroni post-tests will be used for intergroup comparisons, adopting p < 0.05."},{"label":"CONCLUSION","text":"BL is expected to emerge as a potential non-pharmacological alternative for reducing Candida Albicans fungal load, improving clinical symptoms, and enhancing the quality of life of women with RVVC."}],"keywords":["Blue Light Therapy","Non-pharmacological therapy","Photobiomodulation therapy","Recurrent vulvovaginal candidiasis","Vulvovaginal candidiasis"]},{"pmid":"40486198","title_fr":"Laser basse énergie dans le syndrome génito-urinaire et l'incontinence d'effort : étude pilote","type":"cohort","level":4,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[],"n":41,"effect":"favorable","theme":"Syndrome génito-urinaire","l1":"Chez 41 femmes (Taïwan), huit séances hebdomadaires de laser basse énergie améliorent l'index de santé vaginale, les symptômes urinaires et, dans le syndrome génito-urinaire, la lubrification et la douleur.","l2":"Analyse rétrospective (2022–2023) : 24 femmes avec incontinence d'effort, 22 avec syndrome génito-urinaire. Dans l'incontinence d'effort, ce sont surtout l'urgence et la qualité de vie urinaire qui progressent.","l3":{"points":["FSFI amélioré dans le groupe syndrome génito-urinaire, pas dans le groupe incontinence."],"limites":["Rétrospectif, sans témoin."],"pratique":"—"},"topic":"gynecologie","title":"The efficacy of low-level laser therapy in alleviating genitourinary syndrome of menopause and stress urinary incontinence: the pilot study.","journal":"Frontiers in medicine","journal_abbr":"Front Med (Lausanne)","authors":["Wu PC","Lin HH","Chen CH","et al."],"date":"2025-05-23","year":2025,"week":"2025-S21","doi":"10.3389/fmed.2025.1574646","pmcid":"PMC12141027","license":"cc by","oa":true,"pdf":"pdfs/40486198.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"Genitourinary syndrome of menopause (GSM) and stress urinary incontinence (SUI) are prevalent among women. While low-level laser therapy (LLLT) has been employed for wound healing, no studies have explored its effectiveness in treating GSM and SUI."},{"label":"METHODS","text":"Between September 2022 and August 2023, all women received LLLT for GSM and SUI at the gynecologic outpatient clinic of a hospital were retrospectively reviewed. The treatment was administered once a week for 8 weeks. Vaginal Health Index (VHI) and pre- and post-treatment questionnaires were utilized to assess lower urinary tract symptoms (LUTS)."},{"label":"RESULTS","text":"A total of 41 women were enrolled, including 24 (59%) with SUI and 22 (52%) with GSM (5 women reported both conditions). Significant improvements were observed in all VHI items for both groups. Total scores for ICIQ-SF (International Consultation on Incontinence Questionnaire-Short Form), UDI-6 (Urogenital Distress Inventory-6), IIQ-7(Incontinence Impact Questionnaire-7), USS (Urgency Severity Scale), and OABSS (Overactive Bladder Symptom Score) demonstrated significant enhancements in all women and specifically in the GSM group. In the SUI group, USS and OABSS significantly improved, with more domains in KHQ (King's Health Questionnaire) showing improvement compared to the GSM group. In the GSM group, lubrication, pain, and the total score of FSFI (Female Sexual Function Index) improved significantly, while no significant enhancement in sexual function was observed in the SUI group."},{"label":"CONCLUSION","text":"This pilot study indicates that LLLT is a safe, cost-effective, and straightforward treatment for alleviating GSM and SUI symptoms. Women with GSM experienced improvements in LUTS and sexual function, while women with SUI demonstrated improvements in urinary urgency and LUTS-related quality of life. This study represents the first application of LLLT in gynecology."}],"keywords":["female sexual function","genitourinary syndrome of menopause","low-level laser therapy","lower urinary tract symptoms","stress urinary incontinence"]},{"pmid":"40242016","title_fr":"Laser basse énergie et traumatisme du mamelon pendant l'allaitement : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[660],"n":null,"effect":"neutre","theme":"Allaitement","l1":"Trois essais (660 nm) : pas de différence significative de douleur (−0,6 point) entre laser et contrôle.","l2":"Recherche de 2022 ; résultat moins favorable que la méta-analyse de juin 2025 qui inclut sept essais.","l3":{"points":["DM −0,60 (IC95 % −1,52 à 0,31)."],"limites":["Trois essais."],"pratique":"—"},"topic":"gynecologie","title":"Low-level laser therapy for nipple trauma and pain during breastfeeding: systematic review and meta-analysis.","journal":"Revista brasileira de ginecologia e obstetricia : revista da Federacao Brasileira das Sociedades de Ginecologia e Obstetricia","journal_abbr":"Rev Bras Ginecol Obstet","authors":["Gaitero MVC","de Mira TAA","Gondim EJL","et al."],"date":"2025-03-17","year":2025,"week":"2025-S12","doi":"10.61622/rbgo/2025rbgo3","pmcid":"PMC12002722","license":"cc by","oa":true,"pdf":"pdfs/40242016.pdf","cited_by":2,"pub_types":["Meta-Analysis","Systematic Review"],"abstract":[{"label":"OBJECTIVE","text":"This study aimed to investigate the effect of low-level laser therapy (LLLT) on nipple trauma and pain during breastfeeding through a systematic review with a meta-analysis of selected studies."},{"label":"SOURCE OF THE DATA","text":"A thorough search was conducted on March 22, 2022, using the databases PubMed, SciELO, LILACS, PEDro, CINAHL, EMBASE, ScienceDirect, Scopus, Google Scholar, MEDLINE, the Cochrane Library, Clinical Trials, Web of Science, TRIP, DARE, and ProQuest. The search terms included various combinations of low-level laser therapy, nipple pain, nipple trauma, and breastfeeding."},{"label":"STUDIES SELECTION","text":"Out of 107 articles identified, only three controlled and randomized clinical trials was included. The extracted data encompassed breast and trauma characteristics, treatment types, outcomes (pain and healing process), evaluation tools, LLLT usage, laser brand, and parameters."},{"label":"DATA COLLECTION","text":"Data extraction was performed using RAYYAN for systematic reviews. The risk of bias in the studies was evaluated."},{"label":"DATA SYNTHESIS","text":"Pain was measured using the visual analog scale (VAS). The included studies did not use validated tools for assessing physical conditions. All studies employed LLLT with a 660-nm wavelength, though there were variations in equipment power, energy dose, and application methods. The meta-analysis revealed an average difference of -0.60 points (95% CI: -1.52 to 0.31) in the VAS pain scores between the LLLT and control groups. No heterogeneity was observed among the studies (I2=0%), indicating no significant difference in pain relief between LLLT (red light) and control groups."},{"label":"CONCLUSION","text":"LLLT may offer a promising option for managing breastfeeding-related complications, though further research is required."}],"keywords":["Breast feeding","Laser therapy","Low level light therapy","Low-level laser","Nipple pain","Nipple trauma","Nipples"]},{"pmid":"40047824","title_fr":"Infection de prothèse après reconstruction mammaire prépectorale traitée par pression négative et PBM : cas clinique","type":"cases","level":4,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":[],"nm":[],"n":1,"effect":"favorable","theme":"Sénologie","l1":"Une patiente BRCA2 avec infection de prothèse a pu être reconstruite après 21 jours de pression négative et de PBM de la cavité.","l2":"Premier cas décrit associant ces deux techniques ; permet d'éviter une paroi plate définitive.","l3":{"points":["Pseudomonas aeruginosa ; deux prélèvements négatifs avant reconstruction."],"limites":["Cas unique."],"pratique":"—"},"topic":"gynecologie","title":"Implant infection after prepectoral breast reconstruction treated with negative pressure wound therapy and photobiomodulation: a case report.","journal":"Journal of wound care","journal_abbr":"J Wound Care","authors":["Di Micco R","Santurro L","Zuber V","et al."],"date":"2025-03-06","year":2025,"week":"2025-S10","doi":"10.12968/jowc.2022.0097","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Case Reports"],"abstract":[{"label":"","text":"Prepectoral breast reconstruction is a relatively new surgical technique that allows placement of the implant directly over the pectoralis major. It has benefits in terms of patient wellbeing, operative time, postoperative pain and recovery. However, in cases of infection, implant removal is often required and the patient is left with a flat chest. To the authors' knowledge, this is the first case of breast implant infection after breast reconstruction, successfully treated with a combination of both negative pressure wound therapy (NPWT) and photobiomodulation (PBM). A 32-year-old female patient with a BRCA2 mutation had undergone bilateral risk-reducing, nipple-sparing mastectomy for in situ ductal breast carcinoma followed by a prepectoral reconstruction. On the left side, the patient presented with dehiscence of 2.5cm with implant exposure 90 days after surgery. After an initial conservative approach, the patient's condition worsened, and she developed a larger dehiscence and a red breast. She was treated with implant removal. PBM of the cavity and the application of VeraFlo Therapy (3M, US) with a polyurethane-foam filling in the residual cavity were adopted. Pseudomonas aeruginosa was isolated and appropriate antibiotic therapy was started. Every 48-72 hours, she returned to the operating room for a washout, PBM, microbiological swabs, foam exchange and continuing NPWT. After 21 days of this approach and two consecutive negative swabs, the patient underwent breast reconstruction with a subpectoral expander. After six months, a definitive implant of the same size as the contralateral one was positioned. The cosmetic result was good and patient satisfaction was high. The combination of NPWT and PBM may represent a good solution in case of breast implant infection after prepectoral reconstruction with benefits in terms of surgical outcome, patient satisfaction and postoperative quality of life."}],"keywords":["breast implant","ductal breast carcinoma","infection","mastectomy","negative pressure wound therapy","photobiomodulation","prepectoral breast reconstruction","wound","wound care","wound dressing"]},{"pmid":"40038121","title_fr":"Place du laser dans l'incontinence urinaire d'effort : revue","type":"sr","level":3,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Incontinence urinaire","l1":"Revue 2014–2024 : le laser (surtout ablatif) donne des résultats à court terme dans l'incontinence d'effort ; durabilité et rapport coût-efficacité restent à établir.","l2":"La revue mélange plusieurs types de lasers et compare avec la rééducation et les médicaments.","l3":{"points":["Accent sur la sélection des patientes."],"limites":["Types de laser mélangés."],"pratique":"—"},"topic":"gynecologie","title":"Exploring the role of laser therapy for stress urinary incontinence: a literature review.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Li PC","Ding DC"],"date":"2025-03-04","year":2025,"week":"2025-S10","doi":"10.1007/s10103-025-04385-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"Stress urinary incontinence (SUI) significantly impacts the quality of life, necessitating innovative treatment options beyond conventional approaches. This comprehensive review aimed to evaluate laser therapy as a promising intervention for SUI management. A systematic search was conducted using the keywords \"laser\" and \"stress urinary incontinence\" in the PubMed, Scopus, Web of Science, and Embase databases. The search covers studies from January 1, 2014, to November 30, 2024. A comparative analysis with traditional treatments, such as pelvic floor exercises and medications, underscores the potential advantages and limitations of laser therapy. Clinical studies and research findings are examined to evaluate the efficacy and safety profile of laser therapy, including its short-term success rates and potential complications. Patient experiences and perspectives provide a qualitative dimension, offering insights into the real-world impact and challenges associated with laser therapy for SUI. This review also explores the cost-effectiveness of laser therapy and compares its long-term and short-term effects, positioning it within the broader landscape of SUI management. Future trends and ongoing research are outlined, highlighting the potential integration of laser therapy with multimodal approaches. Recommendations for clinical practice emphasize patient selection criteria and address concerns and expectations, ensuring laser therapy is adopted as a valuable and evidence-based addition to SUI management."}],"keywords":["Carbon dioxide","Erbium-doped yttrium aluminum garnet","Laser","Stress urinary incontinence"]},{"pmid":"40005470","title_fr":"Laser sur points d'acupuncture sensibilisés dans la douleur pelvienne chronique de l'infection génitale haute : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser"],"nm":[],"n":36,"effect":"favorable","theme":"Douleurs pelviennes","l1":"Chez 36 femmes avec douleur pelvienne chronique après infection génitale haute, le laser sur points d'acupuncture ajouté aux AINS réduit plus la douleur et améliore la qualité de vie.","l2":"Essai égyptien, 6 semaines. EVA −1 point de plus, SF-12 +9 points.","l3":{"points":["Seuil de douleur à la pression augmenté."],"limites":["Pas de simulation."],"pratique":"—"},"topic":"gynecologie","title":"The Effect of Laser Biostimulation at Sensitized Acupoints on Chronic Pelvic Pain and Quality of Life in Women with Pelvic Inflammatory Disease: A Randomized Controlled Trial.","journal":"Medicina (Kaunas, Lithuania)","journal_abbr":"Medicina (Kaunas)","authors":["Hasanin ME","Aly SM","Taha MM","et al."],"date":"2025-02-18","year":2025,"week":"2025-S08","doi":"10.3390/medicina61020354","pmcid":"PMC11857755","license":"cc by","oa":true,"pdf":"pdfs/40005470.pdf","cited_by":3,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Background and Objectives: Chronic pelvic pain (CPP) is a common complication of pelvic inflammatory disease (PID). Although acupuncture has been increasingly used for the management of CPP, there is insufficient research to support the use of laser stimulation of sensitized acupoints. This study aimed to investigate the effects of laser on sensitized acupoints on pelvic pain perception and quality of life in women with pelvic inflammatory disease. Materials and Methods: Thirty-six women with CPP caused by chronic pelvic inflammatory disease were randomly divided into two equal groups. Both groups received non-steroidal anti-inflammatory drugs, while the study group also received a low-level laser at sensitized acupoints for 6 weeks. All the patients were evaluated before and after the intervention. The 12-item Short-Form Health Survey (SF-12) was used to measure the quality of life, while a pressure algometer and visual analog scale for pain (VAS-P) were used to measure pain sensitivity and intensity, respectively. A mixed MANOVA was used to investigate the effects of the treatment. Results: A mixed MANOVA on VAS, SF-12, and PPT scores revealed significant interaction effects of treatment and time (F = 38.34, p = 0.001, partial η2 = 0.96) and main effects of treatment (F = 9.74, p = 0.001) and time (F = 110.1, p = 0.001). Post-treatment, the study group showed greater reductions in VAS (MD = -1.00, p = 0.001), improvements in SF-12 (MD = 9.11, p = 0.001), and increased Pressure Pain Thresholds (PPT) at multiple anatomical points (p = 0.001-0.01). Conclusions: Laser biostimulation of neurogenic-sensitized acupoints significantly improves pain perception, intensity, and quality of life in women with CPP. suggested that the utilization of laser therapy at sensitized acupoints should be considered a potential component of a rehabilitation program for females suffering from chronic pelvic pain resulting from pelvic inflammatory disease. (Clinicaltrials.gov identifier: NCT05537207; Date of registration: 13 September 2022)."}],"keywords":["acupoints","laser b","pain perception","pelvic pain","quality of life","woman’s health"]},{"pmid":"39986110","title_fr":"Interventions non médicamenteuses du traumatisme périnéal post-partum : revue exploratoire","type":"sr","level":3,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"—","theme":"Périnée post-partum","l1":"41 études : la cryothérapie domine la recherche (54 %) ; la PBM fait partie des approches moins étudiées.","l2":"Cartographie des interventions et des critères ; la douleur est le critère le plus fréquent.","l3":{"points":["Épisiotomie : 48,7 % des études."],"limites":["Revue exploratoire."],"pratique":"—"},"topic":"gynecologie","title":"Non-pharmacological interventions for perineal trauma in the postpartum period: A scoping review.","journal":"Midwifery","journal_abbr":"Midwifery","authors":["Gondim EJL","Nascimento SL","Gaitero MVC","et al."],"date":"2025-02-17","year":2025,"week":"2025-S08","doi":"10.1016/j.midw.2025.104341","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Scoping Review","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"BACKGROUND","text":"Non-pharmacological interventions for perineal trauma are crucial for postpartum women's care, providing an alternative to excessive medication use and the associated potential adverse effects for both the woman and her newborn."},{"label":"AIM","text":"To map the non-pharmacological interventions studied in the context of childbirth-related perineal trauma over the years."},{"label":"METHODS","text":"A systematic search was conducted on PubMed, BVS/Bireme, CINAHL, Embase, Scielo, ProQuest, ProQuest theses, Medline, Web of Science, and Scopus electronic databases. Studies were included if their population consisted of puerperal women with perineal trauma, the concept being non-pharmacological interventions, and the context being the immediate postpartum period. A descriptive summary presents the most studied non-pharmacological interventions for perineal trauma, the main outcomes investigated, the types of perineal trauma of greatest interest, and publications about the topic over the years."},{"label":"RESULTS","text":"This review encompassed 41 studies. Cryotherapy emerged as the most extensively studied non-pharmacological intervention, with 22 studies (53.65%). Other interventions were heat therapy, low-level light and electromagnetic therapy, therapeutic ultrasound, transcutaneous electrical nerve stimulation, pelvic floor muscle exercise, and complementary and alternative medicine. Perineal pain was the most investigated outcome (32 studies, 78.04%). Episiotomy was frequently the subject of research (20 studies, 48.78%). Interest in this topic has notably surged over the past 15 years."},{"label":"CONCLUSION","text":"A range of non-pharmacological interventions have been investigated for managing perineal trauma related to childbirth. Future studies could explore the efficacy and cost-effectiveness of these interventions to identify the most suitable options for postpartum women and facilitate their integration into clinical practice."}],"keywords":["Episiotomy","Perineal tears","Perineum","Postpartum period","Wounds and injuries"]},{"pmid":"39940084","title_fr":"PBM contre la douleur vulvaire de la vestibulodynie provoquée : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED","laser"],"nm":[],"n":30,"effect":"favorable","theme":"Vulvodynie","key":true,"l1":"Chez 30 femmes avec vestibulodynie provoquée, 15 séances de PBM rouge et infrarouge réduisent davantage la douleur vulvaire que la simulation (tailles d'effet 0,6 à 0,9), sans effet sur la sexualité.","l2":"Essai canadien en aveugle complet jusqu'à l'analyse. PBM sur le vestibule, le périnée et la région sacrée, 15 séances en 8 semaines avec exposition progressive.\n\nGains sur le seuil de douleur à la pression (d = 0,61), le test du tampon (d = 0,60) et la sensibilité vulvaire (d = 0,87). Fonction sexuelle et scores psychologiques sans différence.","l3":{"points":["Randomisation 16/14 ; 1 perdue de vue.","Critère principal mesuré une semaine après la dernière séance."],"limites":["Petit effectif."],"pratique":"Premier essai contre simulation favorable dans la vestibulodynie ; la PBM peut s'intégrer à la kinésithérapie."},"topic":"gynecologie","title":"Photobiomodulation therapy for the treatment of vulvar pain among those with provoked vestibulodynia: a randomized controlled trial.","journal":"The journal of sexual medicine","journal_abbr":"J Sex Med","authors":["I Antonio F","Pukall C","McLean L"],"date":"2025-02-13","year":2025,"week":"2025-S07","doi":"10.1093/jsxmed/qdaf011","pmcid":null,"license":"cc by-nc","oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"BACKGROUND","text":"Provoked vestibulodynia (PVD) is characterized by recurring pain confined to the vulvar vestibule; histological studies show inflammatory mediators and neural proliferation in the vulvar tissues."},{"label":"OBJECTIVE","text":"To determine whether a 15-session photobiomodulation (PBM) intervention is more effective than sham-PBM for reducing vulvar pain. Secondary objectives were to evaluate the effect of the PBM intervention on broader domains of vulvar pain, psychological outcomes, sexual function, perceived improvement and satisfaction, as well as to describe adverse events and adherence."},{"label":"DESIGN","text":"Randomized controlled trial."},{"label":"PARTICIPANTS","text":"Participants with PVD were recruited from the local community."},{"label":"ALLOCATION","text":"Randomized allocation to real- or sham-PBM (1:1) was concealed from participants and all members of the research team until after data analysis was complete."},{"label":"OUTCOMES","text":"Primary outcomes: pressure pain threshold (PPT), pain reported on the tampon test, and vulvar pain sensitivity reported on the Vulvar Pain Assessment Questionnaire (VPAQ). Secondary outcomes: pain-related domains reported on the VPAQ, sexual function, depression, anxiety and stress, pain catastrophizing, central sensitization to pain, Patient Global Perception of Improvement (PGPI), Perceived overall percent improvement (P%I), perceived satisfaction with treatment (%), adherence and adverse events. The primary end point was one week following the last PBM intervention session."},{"label":"INTERVENTION","text":"Fifteen sessions of a real- or sham-PBM intervention were delivered over an 8-week period, progressing through five stages of incremental exposure to light in the red and near-infrared spectra applied to the vulvar vestibule, the perineum, and the sacral region."},{"label":"RESULTS","text":"Thirty participants (16 real-PBM, 14 sham-PBM) enrolled and received their intended intervention; one (sham-PBM) was lost to follow-up. Vulvar pain was reduced more in the real- compared to the sham-PBM group; between group differences were 28.2-112.0 g/cm2 (d = 0.61) for PPT, 0.1-2.5 1(d = 0.60) for pain reported on the tampon test, and 0.1-0.9 (d = 0.87) for pain sensations reported on the VPAQ. Changes in other pain-related domains reported on the VPAQ, psychological outcomes and sexual function were not different between the real- and sham-PBM groups. Adherence to the intervention was nearly 100% among those who completed the study. Most participants in both groups were satisfied or very satisfied with the intervention (real-PBM = 80%; sham-PBM = 64%), with no group differences in satisfaction or perception of improvement."},{"label":"CONCLUSIONS","text":"The PBM intervention resulted in greater reductions in vulvar pain than the sham intervention. However, patients did not perceive that the real-PBM was significantly better than the sham-PBM intervention, and the intervention did not impact psychological outcomes or sexual function. ClinicalTrials.gov  Identifier: NCT04234542."}],"keywords":["conservative intervention","laser therapy","pain management","physiotherapy","sexual function","vulvodynia"]},{"pmid":"39892163","title_fr":"La PBM rouge pulsée soulage la dysménorrhée induite par l'ocytocine chez la souris","type":"preclinical","level":5,"pop":"—","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[630],"n":null,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez la souris, la lumière à 630 nm pulsée réduit douleur et prostaglandines, mieux que le mode continu, en agissant sur le stress oxydatif et les lipides.","l2":"Analyses du transcriptome utérin et du métabolome plasmatique.","l3":{"points":["Pulsé supérieur au continu."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"Pulsed red light photobiomodulation ameliorates oxytocin-induced primary dysmenorrhea in mice by inhibiting oxidative stress and lipid accumulation.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Fu Q","Yang J","Jiang H","et al."],"date":"2025-01-31","year":2025,"week":"2025-S05","doi":"10.1016/j.jphotobiol.2025.113119","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation (PBM) has gained attention as a kind of anti-pain or anti-inflammation therapy, yet its efficacy in mitigating the symptoms and underlying metabolic disturbances of primary dysmenorrhea remains underexplored. Here, 630 nm light reduced menstrual pain and prostaglandin F2a/prostaglandin E2 dysregulation, regulated oxidation and lipid peroxidation levels, and improved uterus damage in oxytocin-induced mice. Notably, pulsed wave (PW) treatment exhibited superior efficacy compared to continuous wave application. Hence, this research focused on the effects of 630 nm PW on oxytocin-induced mice by examining changes in the uterine transcriptome and plasma metabolome. Results from integrated analyses revealed significant modifications primarily in antioxidant and lipid metabolism pathways, alongside shifts in biomarkers related to arachidonic acid metabolism. Quantitative real-time PCR confirmed the downregulation of critical genes associated with oxidative stress and inflammation, as well as the suppression of uterine smooth muscle contractions and lipid overaccumulation. These findings support the potential of 630 nm PW PBM as a viable option for clinical interventions in dysmenorrhea management."}],"keywords":["Antioxidant","Lipid metabolism","Plasmic transcriptome metabolome","Primary dysmenorrhea","Pulsed 630 nm light","Uterine transcriptome"]},{"pmid":"39825978","title_fr":"LED bleue dans la candidose vulvovaginale récidivante résistante : expérience brésilienne","type":"cohort","level":4,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[],"n":62,"effect":"favorable","theme":"Infections vulvovaginales","l1":"Chez 62 femmes avec candidose récidivante résistante aux azolés, 10 séances de lumière bleue améliorent les symptômes chez 79 % des patientes, et 58 % le sont encore à 6 mois.","l2":"Étude prospective sans témoin (2023–2024). Amélioration du prurit, des brûlures, de l'œdème, de l'érythème et des leucorrhées.","l3":{"points":["Une séance de 20 min par semaine."],"limites":["Sans témoin."],"pratique":"Option à considérer en cas de résistance aux antifongiques."},"topic":"gynecologie","title":"Blue light-emitting diode therapy for recurrent vulvovaginal candidiasis: a Brazilian report.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Modesto W","Frederice C","Bardin M"],"date":"2025-01-18","year":2025,"week":"2025-S03","doi":"10.1007/s10103-025-04283-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"RVVC is defined as four or more episodes of candidiasis in a 12-month period. Conventional treatment is complex and often involves long-term medication use or multiple treatments. ABL therapy is a promising treatment option as it is acceptable to women and has only rare side effects. We conducted a prospective study with the objective of assessing the effects of antimicrobial blue light (ABL) therapy for recurrent vulvovaginal candidiasis (RVVC) in drug-resistant women."},{"label":"METHODS","text":"Our study enrolled RVVC drug-resistant women (defined based on clinical non-response to standard azole therapies confirmed through culture or persistence of VVC symptoms (oedema, erythema, pruritus, burning, dysuria and leucorrhea)), who received ABL through 10 sessions for 20 min once a week from January 2023 to January 2024. The symptoms of Recurent VVC were assessed after 10 treatment sections and after 6 months."},{"label":"RESULTS","text":"We included 62 patients. The overall symptoms improvement were 79% immediately after treatment and 58% after 6 months, respectively. There was an improvement in the symptoms of pruritus, burning, oedema, erythema and leucorrhoea."},{"label":"CONCLUSION","text":"ABL was an effective therapy to be employed in drug-resistant women suffering from RVVC."}],"keywords":["Candidiasis","Low-level light therapy","Phototherapy","Vulvovaginitis"]},{"pmid":"39676335","title_fr":"La PBM rouge pulsée inhibe la dysménorrhée induite par l'ocytocine chez la souris (stress oxydatif, inflammation)","type":"preclinical","level":5,"pop":"—","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[],"n":null,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez la souris, la lumière rouge pulsée diminue la douleur, les prostaglandines et le stress oxydatif mieux que la lumière continue.","l2":"Mécanismes : espèces réactives de l'oxygène, NO/NOS, calcium dans le muscle utérin.","l3":{"points":["iNOS diminuée."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"Pulsed Red Photobiomodulation Boosts the Inhibition of Oxytocin-Induced Primary Dysmenorrhea in Mice by Suppressing Oxidative Stress and Inflammation.","journal":"Journal of biophotonics","journal_abbr":"J Biophotonics","authors":["Fu Q","Yang J","Jiang H","et al."],"date":"2024-12-15","year":2024,"week":"2024-S50","doi":"10.1002/jbio.202400398","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"","text":"Increasing evidence has underscored the pivotal role of red photobiomodulation (R-PBM) in analgesic and anti-inflammatory processes; nonetheless, research concerning the effects of pulsed wave on primary dysmenorrhea (PD) remains sparse. This study found that pulsed R-PBM significantly diminished pain responses and levels of PGF2α/PGE2, mitigated uterine swelling, augmented antioxidant capacity, and lowered MDA concentrations, which outperformed continuous wave at the same average irradiance. Furthermore, PW treatment substantially reduced ROS levels and enhanced cell viability in PGF2α induced HUSM cells. NOS levels, especially iNOS, were markedly diminished in the uteri of PD mice, accompanied by significant alterations in inflammation-related genes (Jun, Fos, IL1rn, IL17b) and protein levels, along with pronounced downregulation of calcium ion concentrations after pulsed R-PBM intervention. These findings indicated that pulsed R-PBM may mitigate pain by modulating ROS and NO/NOS, mediated oxidative stress and inflammatory responses. Consequently, pulsed R-PBM emerges as a promising therapeutic strategy for PD."}],"keywords":["inflammation","oxidative stress","primary dysmenorrhea","pulsed red light"]},{"pmid":"39662253","title_fr":"Lumière rouge pulsée et léonure contre la dysménorrhée chez la souris","type":"preclinical","level":5,"pop":"—","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[],"n":null,"effect":"favorable","theme":"Dysménorrhée","l1":"L'association lumière rouge pulsée + léonure (plante chinoise) est plus efficace que chacune seule contre la dysménorrhée de la souris.","l2":"Effets sur la signalisation calcique et l'inflammation.","l3":{"points":["Synergie démontrée chez l'animal."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"The synergistic effect of pulsed red light and leonurus inhibits primary dysmenorrhea induced by oxytocin in mice by modulating calcium signaling and inhibiting inflammatory responses.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Fu Q","Jiang H","Yang J","et al."],"date":"2024-12-08","year":2024,"week":"2024-S49","doi":"10.1016/j.jphotobiol.2024.113079","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Despite increasing evidence suggesting that red light photobiomodulation (R-PBM) and leonurus play important roles in analgesic and anti-inflammatory processes, data on their combined effect on primary dysmenorrhea (PD) are scarce. In this study, we reported the pain assessment of red light at various modes combined with leonurus on the oxytocin-induced model of PD mice. The combined intervention of pulsed R-PBM and leonurus decreased pain responses and PGF2α/PGE2 levels, alleviated uterine swelling and inflammatory infiltration, enhanced antioxidant levels (T-AOC, GSH-PX, SOD), and reduced lipid peroxidation (MDA, LPO) in the uterus, with its synergistic effect surpassing either treatment alone or the combination of continuous wave R-PBM with leonurus. Transcriptomic analysis demonstrated significant changes in differentially expressed genes associated with calcium signaling (Cav1, Cacna1c, Kcnmb1, Cnn1, and Myh11) and inflammatory response (Ptgs2, Jun, Fos, IL1rn, and IL17b) in the combination group, with concurrent downregulation of MLCK, COX-2, p-JNK/JNK, and IL17b protein levels, and upregulation of IL1rn, suggesting that the combined intervention of pulsed R-PBM and leonurus may alleviate pain through disruption of calcium homeostasis and induction of ROS-mediated inflammatory responses. Metabolomics studies of plasma revealed significant changes in lipid metabolism after the combined intervention, consistent with the transcriptomic findings. Hence, pulsed R-PBM combined leonurus has the potential to be an effective therapeutic approach for PD, as well as an alternative option for painful and inflammatory diseases; however, further exploration of its underlying mechanism is still necessary."}],"keywords":["Calcium signaling","Inflammatory response","Lipid metabolism","Primary dysmenorrhea","Pulsed 630 nm light","leonurus"]},{"pmid":"39621728","title_fr":"PBM vulvaire dans le syndrome génito-urinaire post-ménopausique : protocole d'essai en double aveugle","type":"protocol","level":0,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser"],"nm":[808],"n":60,"effect":"—","theme":"Syndrome génito-urinaire","l1":"Protocole brésilien (60 femmes) : laser 808 nm vulvaire, 4 séances, contre placebo ; résultats publiés en 2026.","l2":"808 nm, 100 mW, 4 J par point, 8 points vulvaires. Voir la fiche de 2026 (Climacteric).","l3":{"points":["Résultats : PMID 42060269."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Photobiomodulation in post menopause genitourinary syndrome-Study protocol for a randomized, double-blind, controlled clinical protocol.","journal":"PloS one","journal_abbr":"PLoS One","authors":["Pereira SRDS","Mesquita-Ferrari RA","Salviatto LTC","et al."],"date":"2024-12-02","year":2024,"week":"2024-S49","doi":"10.1371/journal.pone.0313324","pmcid":"PMC11611114","license":"cc by","oa":true,"pdf":"pdfs/39621728.pdf","cited_by":2,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"INTRODUCTION","text":"Genitourinary Syndrome of Menopause (GSM) defines a set of symptoms associated with an estrogen deficit involving alterations in organs genitourinary and that results in several urinary, genital, and sexual alterations. Brazilian women live about a third of their life after menopause, where hormonal changes occur along with clinical manifestations, characterized by vaginal and vulvar dryness, burning sensation, discomfort, vulvovaginal irritation, lack of lubrication, dyspareunia and urinary incontinence. Fractionated photothermolysis and radiofrequency systems, alone or in combination were tested to improve GSM."},{"label":"OBJECTIVE","text":"The goal of this study is to elaborate a protocol to evaluate the clinical response of patients with symptoms of GSM after the application of photobiomodulation in the vulvar region."},{"label":"METHOD","text":"In this randomized, double-blind, placebo-controlled study protocol, women over 50 years of age who are in the postmenopausal period (amenorrhea for at least 12 months, with no pathology involved) with one or more symptoms of GSM will be randomly divided into two groups. The treatment group (n = 30) will receive four consecutive applications, weekly, using DMC laser diode (λ = 808 nm), 4J per point, 100mW of power, 1,016W/cm2, 8 sites in the vulvar region, The Placebo Group (n = 30) will be handled as treated, but with the laser turned off. The quality of life will be assessed using female sexual functioning index (FSFI-6), urinary incontinence questionnaire (ICIQ-SF), Quality of life will be analyzed using the female sexual functioning index (FSFI-6). The intensity of menopausal symptoms will be evaluated using a visual analogue scale (VAS), the vulvo vaginal atrophy will be measured by the Vaginal Health Index (VHI). Also, the vaginal temperature will be measured using a thermal camera, the pressure of the pelvic floor force (vaginal dynamometer) and a 1-hour Pad Test will be performed to quantify the urinary loss. With this procedure, we intend to obtain an overall better life quality and diminished symptoms in women with GSM. All assessments will be performed prior to the first irradiation and after the last one."},{"label":"TRIAL REGISTRATION","text":"This protocol is registered at ClinicalTrials.gov under the number NCT05557799."}],"keywords":[]},{"pmid":"39624135","title_fr":"Rééducation périnéale associée à la PBM dans le syndrome génito-urinaire : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["intravaginal"],"nm":[],"n":null,"effect":"—","theme":"Syndrome génito-urinaire","l1":"Protocole d'essai à trois bras (rééducation seule, + PBM active, + PBM simulée) ; résultats publiés en 2026.","l2":"16 séances, deux par semaine ; évaluation à la fin et à un mois. Voir PMID 42566226.","l3":{"points":["Résultats : PMID 42566226."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Pelvic floor muscle training associated with the photobiomodulation therapy for women affected by the genitourinary syndrome of menopause: a study protocol.","journal":"PeerJ","journal_abbr":"PeerJ","authors":["Oliveira Bezerra L","de Carvalho MLAS","Silva-Filho E","et al."],"date":"2024-11-29","year":2024,"week":"2024-S48","doi":"10.7717/peerj.17848","pmcid":"PMC11610460","license":"cc by","oa":true,"pdf":"pdfs/39624135.pdf","cited_by":2,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"BACKGROUND","text":"Frequently, the women affected by the genitourinary syndrome of menopause experience genitourinary dysfunctions that profoundly influence their overall health. Even though the symptoms do not jeopardize the women's lives, the urinary and sexual dysfunctions significantly impact their quality of life. Isolated treatments focused on the main causes of the dysfunctions, such as pelvic floor muscle training (PFMT) and photobiomodulation have shown significant improvements in genitourinary dysfunctions. So, the association of PFMT with photobiomodulation may generate additional effects in the genitourinary area. This study aims to create a PFMT protocol isolated and associated with photobiomodulation therapy in women affected by the genitourinary syndrome of menopause."},{"label":"METHODS","text":"It is a randomized, controlled, double-blind clinical trial protocol study that will include women experiencing genitourinary symptoms related to menopause, sexually active, never practiced pelvic floor muscle exercise or photobiomodulation treatment, and do not use hormone replacement therapy for at least 3 months. The randomization will allocate the women to three groups: PFMT group, PFMT associated with active intracavitary photobiomodulation group, and PFMT associated with sham intracavitary photobiomodulation group. A total of 16 sessions will be conducted twice a week. The assessments will occur before interventions, after the sixteenth session, and 1 month after the sixteenth session (follow-up). The evaluation will include the pelvic floor muscle vaginal manometry as the primary outcome. Also, the international consultation on incontinence questionnaire-short form, the female sexual function index, the Utian Quality of Life scale, the patient global impression of improvement, the modified Oxford scale, and the vaginal health index will be the secondary outcomes."},{"label":"DISCUSSION","text":"Despite there are gold standard treatments such as PFMT, to alleviate genitourinary symptoms, interventions mirroring clinical practice are needed. This study protocol might show a groundbreaking and viable method to potentiate the effects of a gold-standard treatment associated with photobiomodulation."},{"label":"CONCLUSION","text":"We expect this protocol to demonstrate that the use of PFMT and photobiomodulation strategies is feasible and able to potentiate the recovery of women affected by the genitourinary syndrome of menopause. The Ethics Committee of the Federal University of Rio Grande do Norte approved the study (n° 6.038.283), and the clinical trials platform registered the protocol (n° RBR-5r7zrs2)."}],"keywords":["Low-level light therapy","Pelvic floor disorders","Sexual dysfunction"]},{"pmid":"39685560","title_fr":"PBM transdermique rouge et proche infrarouge et fertilité féminine : série de cas","type":"cases","level":4,"pop":"adulte","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[],"n":3,"effect":"favorable","theme":"Fertilité","l1":"Trois femmes avec infertilité inexpliquée ont mené une grossesse à terme après une cure de PBM multi-longueurs d'onde.","l2":"Échecs antérieurs : FIV, fausses couches, môle. Aucun effet indésirable. Trois cas sans témoin.","l3":{"points":["Suivi de 9 mois."],"limites":["Trois cas."],"pratique":"—"},"topic":"gynecologie","title":"The Efficacy of Multiwavelength Red and Near-Infrared Transdermal Photobiomodulation Light Therapy in Enhancing Female Fertility Outcomes and Improving Reproductive Health: A Prospective Case Series with 9-Month Follow-Up.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Phypers R","Berisha-Muharremi V","Hanna R"],"date":"2024-11-24","year":2024,"week":"2024-S47","doi":"10.3390/jcm13237101","pmcid":"PMC11642705","license":"cc by","oa":true,"pdf":"pdfs/39685560.pdf","cited_by":2,"pub_types":[],"abstract":[{"label":"","text":"Background/Objectives: Female infertility due to unexpected causes exhibits a great challenge for both clinicians and women who are trying to conceive. The present clinical case series study aimed to evaluate the efficacy of multiple wavelengths of red and near-infrared (NIR) laser photobiomodulation (PBM) for increasing the potential of fertility in women and improving reproductive health in unexplained infertility issues. The objectives were to assess the following: (1) any adverse effects; (2) the possibility of producing an effective PBM protocol; (3) and healthy live birth. The inclusion criteria were to related to females who failed to conceive naturally beyond two years, multiple miscarriages, molar pregnancy, non-viable embryos from in vitro fertilisation (IVF) cycles, and failure to complete successful implantation of viable pre-implantation genetic tested (PGT-A) embryos. Methods: Case series of three female subjects with unexplained age-related infertility issues, which included a failure to conceive naturally beyond two years, multiple miscarriages, molar pregnancy, non-viable embryos from IVF cycles, and failure to complete successful implantation of viable pre-implantation genetic tested (PGT-A) embryos. In each case, previous conditions were recorded and then compared with outcomes after the patient received a course of PBM treatments. In every case, fertility outcomes improved. Three cases resulted in a full-term pregnancy and the birth of a healthy baby. PBM treatments were given at weekly and/or at two-week intervals using IR and NIR wavelengths between 600 nm and 1000 nm in the lead up to natural conception, IVF oocyte retrieval, blastocyst/embryo implantation, and/or the production of viable embryos. Results: In every case, fertility outcomes improved. Improvements in reproductive health outcomes in each case give reason to suggest that PBM may help to improve unexplained age-related infertility. Conclusions: Our study demonstrated that multiwavelength of red and NIR PBM with either an LED or laser, or a combination, improved female fertility and reproductive health and contributed to healthy live births in females diagnosed with unexplained age-related infertility. Extensive studies with robust data are warranted to validate our PBM dosimetry and treatment protocols. Moreover, understanding the genetic and phenotype biomarkers is important to standardise a range of PBM light dosimetry."}],"keywords":["ART","age-related infertility","fertility","multiwavelength","near-infrared","ovarian rejuvenation","photobiomodulation (PBM)","red light","reproductive health"]},{"pmid":"39470875","title_fr":"Laser diode non ablatif à double longueur d'onde dans le syndrome génito-urinaire de la ménopause : étude prospective","type":"nrct","level":4,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[],"n":22,"effect":"favorable","theme":"Syndrome génito-urinaire","l1":"Chez 22 femmes ménopausées ne pouvant pas prendre d'hormones, trois séances de laser diode non ablatif réduisent la sécheresse (7,7 → 3,7/10), les brûlures et la dyspareunie jusqu'à 6 mois.","l2":"Étude italienne (laser Leonardo, deux longueurs d'onde). Index de santé vaginale 12 → 19,3 à 6 mois ; fonction sexuelle améliorée ; aucun effet indésirable.","l3":{"points":["Dyspareunie : 8,1 → 3,9.","FSFI-6 : 12,3 → 19,3."],"limites":["Sans témoin ; laser à effet thermique doux, à la frontière de la PBM."],"pratique":"Alternative non hormonale à court terme."},"topic":"gynecologie","title":"Efficacy and Safety of Non-Ablative Dual Wavelength Diode Laser Therapy for Genitourinary Syndrome of Menopause: A Single-Center Prospective Study.","journal":"Advances in therapy","journal_abbr":"Adv Ther","authors":["Vitale SG","Saponara S","Succu AG","et al."],"date":"2024-10-29","year":2024,"week":"2024-S44","doi":"10.1007/s12325-024-03004-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":10,"pub_types":["Observational Study"],"abstract":[{"label":"INTRODUCTION","text":"This study evaluates the efficacy and safety of non-ablative diode laser therapy for genitourinary syndrome of menopause (GSM) in post-menopausal women unable to use hormonal therapies."},{"label":"METHODS","text":"A pilot prospective study was conducted from September 2023 to April 2024, involving 22 post-menopausal women aged 45-73 years. Participants underwent three sessions of diode laser treatment with the Leonardo® dual-wavelength Diode laser. Assessments were made at baseline, 3 months, and 6 months post-treatment. Main outcome measures included Visual Analog Scale (VAS) scores for GSM symptoms, Vaginal Health Index Score (VHIS), and sexual function evaluated using the Female Sexual Function Index (FSFI-6), Pelvic Organ Prolapse/Urinary Incontinence Sexual Questionnaire (PISQ-12), and Sexual Quality of Life-Female (SQOL-F) questionnaire."},{"label":"RESULTS","text":"Significant improvements were observed in VHIS, increasing from 12 to 19.27 at 6 months (p < 0.001). GSM symptoms improved significantly: vaginal dryness scores decreased from 7.72 ± 2.37 to 3.72 ± 2.53, burning sensation scores dropped from 6.00 ± 3.22 to 1.90 ± 1.81, and dyspareunia scores reduced from 8.09 ± 2.11 to 3.90 ± 2.58 (all p < 0.016). Sexual function improved, indicated by FSFI-6 scores increasing from 12.27 ± 7.29 to 19.30 ± 6.24 (p < 0.016) and SQOL-F scores rising from 63.18 ± 22.93 to 71.45 ± 23.31. No adverse events were reported."},{"label":"CONCLUSION","text":"Non-ablative diode laser therapy is effective and safe for managing GSM symptoms in post-menopausal women, offering significant symptom relief and enhancing sexual health without serious side effects. Further research with a larger cohort and extended follow-up is needed to confirm these findings."},{"label":"TRIAL REGISTRATION","text":"Clinical Trials ID NCT06503003."}],"keywords":["Diode laser","Genitourinary syndrome of menopause","Menopause","Sexual function","Vaginal atrophy"]},{"pmid":"39223951","title_fr":"LED bleue dans la candidose vulvovaginale récidivante : essai randomisé avec évaluateur en aveugle","type":"rct","level":2,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[],"n":60,"effect":"favorable","theme":"Infections vulvovaginales","key":true,"l1":"Chez 60 femmes avec candidose récidivante, deux séances de LED bleue ajoutées à l'antifongique réduisent beaucoup plus la charge en Candida que l'antifongique seul, sans modifier le pH vaginal.","l2":"Essai égyptien : crème Gynoconazol 0,8 % 3 nuits ± deux séances de 60 minutes de LED bleue sur vagin et vulve.","l3":{"points":["Différence de Candida : DM 8,27 (IC95 % 6,72–9,81)."],"limites":["Suivi d'une semaine seulement."],"pratique":"Piste d'adjuvant antifongique non médicamenteux."},"topic":"gynecologie","title":"Effect of blue light emitting diode therapy on recurrent vulvovaginal candidiasis: A randomized assessor-blinded controlled trial.","journal":"Physiotherapy research international : the journal for researchers and clinicians in physical therapy","journal_abbr":"Physiother Res Int","authors":["Shalaby RM","El-Kosery SM","Soliman MM","et al."],"date":"2024-09-03","year":2024,"week":"2024-S36","doi":"10.1002/pri.2129","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"Vulvovaginal Candidiasis (VVC) is a prevalent genital infection in women of reproductive age and requires effective non-drug therapies. Therefore, this study aimed to investigate the effect of blue light emitting diode (LED) therapy as an alternative treatment for recurrent VVC due to its proven antimicrobial properties. The safety and non-invasiveness of LED therapy make it a promising option for sensitive tissue applications."},{"label":"MATERIALS AND METHODS","text":"This randomized controlled trial recruited 60 women with culture-confirmed VVC. Participants were randomly allocated to two groups. Group A (control group) received standard antifungal treatment with Gynoconazol 0.8% vaginal cream for three consecutive nights (n = 30). Group B (study group) received the same antifungal treatment plus two 60-min sessions of blue LED therapy directed at the vagina and vulva, with the sessions separated by two days (n = 30). Candida count (via CHROMagar™ Candida) and vaginal pH (via AD110-AD111 m) were assessed at baseline and one week after initiating treatment."},{"label":"RESULTS","text":"Post-treatment, group (B) demonstrated a significantly greater reduction in Candida count compared to group (A) (mean difference (MD) 8.267; 95% Confidence Interval (CI) 6.723-9.811; p = 0.0001). However, there was no statistically significant difference in vaginal pH between the groups (MD -0.03; 95% CI -0.244-0.178; p = 0.749)."},{"label":"CONCLUSION","text":"Blue LED therapy effectively reduces Candida count in women with recurrent VVC without adversely affecting the vaginal pH, highlighting its safety and efficacy as a treatment modality."}],"keywords":["Candida count","Women's health","blue light emitting diode therapy","integrative medicine","recurrent vulvovaginal candidiasis","vaginal pH"]},{"pmid":"39276447","title_fr":"La PBM limite le vieillissement ovarien (souris et cellules de granulosa)","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[650],"n":null,"effect":"favorable","theme":"Fertilité","l1":"Chez la souris âgée, deux mois de laser 650 nm (4 J/cm²) restaurent les hormones sexuelles et augmentent le nombre de follicules.","l2":"Moins de stress oxydatif et d'inflammation ovarienne, meilleure fonction mitochondriale ; effets reproduits sur cellules humaines.","l3":{"points":["4 J/cm² efficace, 2 J/cm² moins."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"Photobiomodulation ameliorates ovarian aging by alleviating oxidative stress and inflammation damage and improving mitochondrial function.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["He Y","Ye R","Peng Y","et al."],"date":"2024-08-30","year":2024,"week":"2024-S35","doi":"10.1016/j.jphotobiol.2024.113024","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":10,"pub_types":[],"abstract":[{"label":"","text":"Ovarian aging is a serious clinical concern. Few safe and effective methods are currently available to improve ovarian functions. Photobiomodulation (PBM) is a safe and noninvasive physical therapy that can modulate a series of biological processes. Recently, several studies have noted its potential to improve the function of ovary and reproductive cells. However, the effects of PBM treatment on natural ovarian aging remain unclear. In this study, we used a naturally reproductive aging mouse model to observe the effect of PBM on ovarian function. Young and aged female ICR mice were treated with or without PBM for 2 months. PBM was performed using a semiconductor InGaAlP laser emitting at 650 nm (80 mW, 6.7 mW/cm2 for 5 or 10 min, resulting in a dose of 2 or 4 J/cm2, respectively). After treatment, the effects of PBM and its role in oxidative stress, inflammation, and mitochondrial function were investigated. We found that PBM (4 J/cm2) effectively recovered the levels of sex hormones, increased the number of primordial and growing follicles, improved angiogenesis, and decreased cell apoptosis in naturally aged mice. Moreover, PBM reduced oxidative stress, inhibited chronic ovarian inflammation, and improved mitochondrial function in aged ovaries. Similar protective effects of PBM were observed in a hydrogen peroxide-induced oxidative stress model of human granulosa cell line (KGN) in vitro. Increased cell viability, cell proliferation, hormone secretion, mitochondrial membrane potential, and adenosine triphosphate levels and decreased apoptosis and oxidative stress were detected in KGN cells after PBM treatment. Collectively, this study suggest that PBM treatment is beneficial for restoring ovarian function in naturally reproductive aging mice and has a significant protective effect against oxidative stress damage in KGN cells. The mechanisms underlying the benefits of PBM in ovarian aging include antioxidant stress, reduction of inflammation, and preservation of mitochondrial function. Therefore, this study emphasizes the potential of PBM as a therapeutic intervention to ameliorate ovarian aging."}],"keywords":["Inflammation","Mitochondrial function","Ovarian aging","Oxidative stress","Photobiomodulation"]},{"pmid":"39167877","title_fr":"PBM versus cryothérapie après déchirure périnéale ou épisiotomie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":56,"effect":"favorable","theme":"Périnée post-partum","l1":"Chez 56 accouchées, la PBM rouge et infrarouge soulage davantage la douleur périnéale que la cryothérapie, immédiatement et surtout à 24 h.","l2":"Essai brésilien, 28 femmes par groupe. Résultat en contradiction avec les méta-analyses qui placent la cryothérapie en tête : la comparaison directe mérite d'être répétée.","l3":{"points":["Douleur : p = 0,008 immédiatement, p < 0,001 à 24 h."],"limites":["Pas d'aveugle possible."],"pratique":"—"},"topic":"gynecologie","title":"Comparison of photobiomodulation with cryotherapy in the immediate postpartum period of parturients with grade I, grade II lacerations and/or episiotomy in reducing perineal and vulvar and edema: A randomized clinical trial.","journal":"European journal of obstetrics, gynecology, and reproductive biology","journal_abbr":"Eur J Obstet Gynecol Reprod Biol","authors":["Cristine Boniatti Constant É","Plentz Stein G","Camargo de Oliveira K","et al."],"date":"2024-08-14","year":2024,"week":"2024-S33","doi":"10.1016/j.ejogrb.2024.08.025","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"INTRODUCTION","text":"Vaginal delivery has several benefits for the parturient; however, during labor, some injuries, such as lacerations and/or episiotomy, can occur. Perineal pain may occur in the puerperium and can be aggravated in cases of perineal injury during childbirth, potentially impacting the physical and emotional aspects of the parturient. For this reason, it is necessary to use techniques that can relieve pain and edema in the immediate postpartum period, directly influencing recovery."},{"label":"OBJECTIVE","text":"To compare the reduction of pain and improvement in healing using two techniques, namely photobiomodulation and cryotherapy, performed in the immediate postpartum period of up to 12 h, in parturients who suffered grade I and II lacerations and/or episiotomy."},{"label":"METHODS","text":"Data collection was carried out through an evaluation questionnaire. Photobiomodulation was applied using the red and infrared laser from the DMC brand. The EVA and McGill scales were used for pain assessment, and the REEDA scale was used for the evaluation of edema and healing."},{"label":"RESULTS","text":"The techniques were evaluated and applied to 56 patients, with 28 in each group (cryotherapy and LBI). Patients who received photobiomodulation showed superior improvement compared to cryotherapy. In the immediate postpartum period, there was a greater reduction in pain in favor of photobiomodulation (p = 0.008); and after 24 h, the difference was even more significant (p < 0.001)."}],"keywords":["Cryotherapy","Edema","Episiotomy","Healing","Laceration","Pain","Photobiomodulation"]},{"pmid":"39963016","title_fr":"Laser diode bleu en soutien du traitement du lichen scléreux vulvaire","type":"cohort","level":4,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["laser"],"nm":[],"n":12,"effect":"favorable","theme":"Lichen scléreux","l1":"Chez 12 femmes, six séances de laser bleu en 2 semaines réduisent prurit, douleur, érythème et fissures du lichen scléreux vulvaire, sans effet indésirable à 4 mois.","l2":"Étude italienne ; trois séances par semaine puis suivi sur 16 semaines.","l3":{"points":["Signes objectifs et subjectifs améliorés."],"limites":["12 patientes, sans témoin."],"pratique":"—"},"topic":"gynecologie","title":"Blue diode laser as supportive therapy for the management of vulvar lichen sclerosus.","journal":"Dermatology reports","journal_abbr":"Dermatol Reports","authors":["Bergamo S","Gobbo M","Chimenton S","et al."],"date":"2024-08-09","year":2024,"week":"2024-S32","doi":"10.4081/dr.2024.10046","pmcid":"PMC11875058","license":"cc by-nc","oa":true,"pdf":"pdfs/39963016.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Vulvar lichen sclerosus is a chronic inflammatory condition characterized by the thinning and atrophy of the skin and mucosa surrounding the vulva and anus. This study evaluates the efficacy of a treatment protocol utilizing blue-diode laser photobiomodulation in managing vulval lichen sclerosus symptoms in a cohort of 12 female patients. The treatment protocol consisted of laser sessions 3 times a week for 2 weeks and follow-up sessions over a 16-week period. Objective and subjective parameters were assessed before treatment, at the end of treatment, and at 4-month follow-up visits. Results demonstrated significant reductions in subjective symptoms, such as itching and pain, as well as improvements in objective signs, including erythema and fissures. No side effects were observed, indicating the safety and tolerability of laser treatment. These findings suggest that photobiomodulation can be an effective therapeutic option for patients with vulval lichen sclerosus, with future research aimed at refining treatment protocols and evaluating its long-term benefits."}],"keywords":[]},{"pmid":"39046567","title_fr":"La PBM peut-elle aider les femmes allaitantes et leurs nouveau-nés ?","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":50,"effect":"favorable","theme":"Allaitement","l1":"Chez 50 femmes avec crevasses, 12 séances de laser diode font mieux qu'une crème anti-inflammatoire sur la douleur et la rougeur, avec plus de lait et un meilleur gain de poids du bébé.","l2":"Étude égyptienne, deux groupes de 25, sur 4 semaines.","l3":{"points":["Différences aux semaines 3 et 4."],"limites":["Randomisation peu décrite dans le résumé."],"pratique":"—"},"topic":"gynecologie","title":"Could Photobiomodulation help lactating women and their newborns?","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Elseody MHAA","Mohamed MAE","Alsharnoubi J"],"date":"2024-07-24","year":2024,"week":"2024-S30","doi":"10.1007/s10103-024-04132-w","pmcid":"PMC11269476","license":"cc by","oa":true,"pdf":"pdfs/39046567.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"During the first several weeks following lactation, nipple pain frequently prevents mothers from continuing breastfeeding. To evaluate the efficacy of using Photobiomodulation (PBM) versus anti-inflammatory topical cream, on inflamed nipple, and the effect on milk production. This study was carried-out on 50 breastfeeding women with nipple pain and fissure. Our patients were divided into two groups ; study group (Group I): 25 patients received 12 sessions of PBM using Diode laser for a period of 4 weeks, 3 sessions per week every alternative day, and controlled group (Group II): 25 patients used Anti-inflammatory topical cream. Regarding inflammatory signs in both groups, Group I showed a significant decrease in redness compared to Group II at the 3rd and 4th week, and a significant decrease in nipple fissure and pain at the 3rd week. There was a significant increase in milk amount reflected on the infant's weight. We concluded that PBM was more effective in decreasing nipple pain, inflammation and subsequently milk production and infant weight than topical anti-inflammatory creams."}],"keywords":["Diode laser","Nipple fissure","Nipple pain"]},{"pmid":"38843530","title_fr":"Les lasers en gynécologie (série d'experts, Obstetrics & Gynecology)","type":"review","level":5,"pop":"adulte","ctx":["général"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Revue générale","key":true,"l1":"Revue de référence : les lasers fractionnés améliorent l'atrophie vaginale et le lichen à court terme avec des preuves faibles, et rien ne soutient solidement le laser basse énergie dans la douleur pelvienne chronique.","l2":"Série « Clinical Expert » de l'ACOG. Elle rappelle la biophysique des lasers et la différence entre lasers ablatifs fractionnés et PBM. Les essais sont sous-dimensionnés, à risque de biais et sans suivi long.","l3":{"points":["Pas de preuve forte pour le laser basse énergie dans la douleur pelvienne chronique."],"limites":["Avis d'experts."],"pratique":"Utile pour expliquer la différence entre laser vaginal ablatif et PBM."},"topic":"gynecologie","title":"Lasers in Gynecology.","journal":"Obstetrics and gynecology","journal_abbr":"Obstet Gynecol","authors":["Iglesia CB","Choi JE","Tadir Y"],"date":"2024-06-06","year":2024,"week":"2024-S23","doi":"10.1097/AOG.0000000000005635","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Review"],"abstract":[{"label":"","text":"The first published reports on the use of laser for cervical pathology date back to 1973. Technical advancements in flexible and rigid laser fibers revolutionized video laser laparoscopy in the 1990s. Fractionated lasers have been used to treat vulvovaginal symptoms associated with genitourinary syndrome of menopause, lichen sclerosus, and urinary incontinence. Review of available data suggests that fractionated lasers can improve both subjective and objective signs of vaginal atrophy and lichen sclerosus, but the evidence is weak because most of the trials are underpowered, are at risk for bias, and lack long-term follow-up. There is no strong evidence to support fractionated laser therapy for urinary incontinence or low-level laser therapy for chronic pelvic pain. Although short-term, single-arm trials suggest benefit of fractionated laser therapy for genitourinary syndrome of menopause, lichen sclerosus, and urinary incontinence, additional adequately powered, prospective, randomized, and longer-term comparative trials are needed before lasers can be recommended for these specific conditions. The purpose of this Clinical Expert Series is to review basic laser biophysics and the mechanism of action for modern fractionated lasers as relevant to the gynecologist. We also summarize safety and effectiveness data for lasers used for some of the most commonly studied gynecologic conditions: the vulvovaginal atrophy component of genitourinary syndrome of menopause, lichen sclerosus, and urinary incontinence."}],"keywords":[]},{"pmid":"38837198","title_fr":"Interventions non médicamenteuses contre la douleur des mamelons pendant l'allaitement : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Allaitement","l1":"Dix-neuf essais : effet incertain de la PBM contre placebo sur la douleur des mamelons (deux essais, DM −0,15) ; toutes les interventions ont des preuves imprécises.","l2":"Revue Cochrane-like avec GRADE. Risque de biais incertain à élevé.","l3":{"points":["PBM contre placebo : DM −0,15 (139 participantes)."],"limites":["Très peu d'essais par comparaison."],"pratique":"—"},"topic":"gynecologie","title":"Nonpharmacological Interventions for Treating Breastfeeding Nipple Pain: Systematic Review and Meta-Analysis.","journal":"Breastfeeding medicine : the official journal of the Academy of Breastfeeding Medicine","journal_abbr":"Breastfeed Med","authors":["Nozimoto INP","da Silva BA","Bandeira MD","et al."],"date":"2024-06-05","year":2024,"week":"2024-S23","doi":"10.1089/bfm.2024.0043","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"","text":"Objective: To evaluate the efficacy and safety of nonpharmacological topical interventions for treating breastfeeding nipple pain. Methods: Randomized clinical trials (RCTs) assessing lactating women suffering from breastfeeding painful nipples were included. Primary outcomes were pain, healing process, and adverse events. A comprehensive search was conducted on June 02, 2023, without date or language restrictions. Methodological quality was assessed using the Cochrane risk of bias tool and the certainty of the evidence, the GRADE approach. Results: Nineteen RCTs with unclear to high risk of bias were included. There was uncertain evidence regarding the effects of photobiomodulation versus placebo on pain reduction (mean difference [MD] -0.15; 95% confidence interval [95% CI] -1 0.49 to 1.19; 139 participants, 2 RCTs). There are uncertainties concerning the effects of lanolin versus breast milk on pain (MD -1.80; 95% CI -2.43 to -1.17; 1 RCT; 180 participants), wound healing (MD 0.10; 95% CI -0.26 to -0.46; 1 RCT; 180 participants), and any adverse events (zero events in both groups). Similar effects were observed by the other interventions assessed. Conclusion: The evidence of nonpharmacological topical interventions for painful nipples is imprecise, and future RCTs with higher methodological quality are needed to support recommendations. Considering the accessibility and low cost of these alternative treatments, the findings of this evidence synthesis could support clinical decision-making and guide future research. PROSPERO CRD42020170320."}],"keywords":["breastfeeding","evidence-based medicine","nipple pain","systematic review","treatment"]},{"pmid":"38727718","title_fr":"Laser basse énergie en complément du traitement du lichen scléreux vulvaire pour améliorer la qualité de vie","type":"cohort","level":4,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["laser"],"nm":[808],"n":100,"effect":"favorable","theme":"Lichen scléreux","key":true,"l1":"Chez 100 femmes danoises avec lichen scléreux insuffisamment contrôlé par les dermocorticoïdes, dix séances de laser 808 nm améliorent 7 des 8 domaines de qualité de vie.","l2":"Étude prospective descriptive (2016–2018) ; 94 patientes ont terminé. Laser 808 nm, 500 mW, 10 séances en 8 semaines.","l3":{"points":["Âge médian 62 ans."],"limites":["Sans témoin."],"pratique":"Complément aux corticoïdes en cas de réponse insuffisante."},"topic":"gynecologie","title":"Low-level laser therapy: an efficient supplement to treatments of vulvar Lichen sclerosus to improve quality of life.","journal":"Journal of obstetrics and gynaecology : the journal of the Institute of Obstetrics and Gynaecology","journal_abbr":"J Obstet Gynaecol","authors":["Berthelsen PK","Ipsen SE","Khalil MR"],"date":"2024-05-10","year":2024,"week":"2024-S19","doi":"10.1080/01443615.2024.2349965","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":1,"pub_types":["Observational Study"],"abstract":[{"label":"BACKGROUND","text":"Lichen sclerosus (LS) is a chronic, inflammatory disease of the genital and extra genital skin, causing pruritus, soreness, pain and dyspareunia. The aim of this study was to investigate whether Low Level Laser Therapy (LLLT) can improve the quality of life in women with Lichen sclerosus (LS) and insufficient topical treatment."},{"label":"METHODS","text":"In a descriptive prospective observational study conducted between 02.01.2016 and 08.01.2018, we included 100 women with LS with insufficient topical treatment because of poor response of symptoms. All participants received ten LLLT treatments (808 nm and 500 mW) over a period of 8 weeks. The first four treatments were planned as two treatments per week. The remaining six treatments were planned as once a week. A Danish health-related quality of life tool (HRQoL test) monitored the effect."},{"label":"RESULTS","text":"A total of 94 patients completed the study, median age of 62 [InterQuartile Range 53-69]. There was a statistically significant improvement in seven of the eight domains of the HRQoL test after ten LLLT. We found the results of DoloTest to be statistically significant in all of the groups except for smoking (p < 0.094)."},{"label":"CONCLUSIONS","text":"LLLT treatment can improve the quality of life in women with LS."}],"keywords":["Low-level laser therapy","photobiomodulation","quality of life","vulva Lichen sclerosus"]},{"pmid":"39051004","title_fr":"Exosomes et PBM régulent les micro-ARN et le glutathion d'ovocytes de SOPK (in vitro)","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":[],"nm":[640],"n":36,"effect":"favorable","theme":"Fertilité","l1":"Sur 36 ovocytes de femmes avec SOPK, la PBM 640 nm modifie l'expression de micro-ARN et augmente le glutathion et l'acétylation nucléaire.","l2":"Étude in vitro comparant exosomes et PBM.","l3":{"points":["Glutathion augmenté (p < 0,0001)."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"Exosome Therapy and Photobiomodulation Therapy Regulate mi-RNA 21, 155 Expressions, Nucleus Acetylation and Glutathione in a Polycystic Ovary Oocyte: An In Vitro Study.","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Sahraeian S","Abbaszadeh HA","Taheripanah R","et al."],"date":"2024-04-30","year":2024,"week":"2024-S18","doi":"10.34172/jlms.2024.10","pmcid":"PMC11267104","license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Introduction: Polycystic ovary syndrome (PCOS) is a complex condition that can have various symptoms and complications, one of which is infertility. Dysregulation of miRNA has been associated with the pathogenesis of numerous illnesses such as PCOS. In this study, we evaluated the effect of photobiomodulation therapy (PBMT) and exosome therapy (EXO) on the regulation of miRNA and nucleus acetylation in a PCOS oocyte. Methods: In this research, 36 oocytes divided into three groups: control, EXO, and PBM (Wavelength of 640 nm). Subsequently, in-vitro maturation (IVM) was evaluated. Real-time PCR was used to evaluate miRNA-21,16,19,24,30,106,155 and GAPDH. Afterward, oocyte glutathione (GSH) and nucleus acetylation were measured by H4K12. Results: The expression of the miR-16, miRNA-19, miRNA-24, miRNA-106 and miRNA-155 genes in the EXO and PBMT groups was significantly down-regulated in comparison to the control group, but the expression of miRNA-21 and miR-30 significantly increased in the EXO and PBMT groups in comparison to the control group. The EXO and PBMT significantly increased GSH and nucleus acetylation (P<0.0001). Conclusion: The results of this study showed that the use of EXO and PBMT can improve GSH and nucleus acetylation in the PCOS oocyte and also change the expression of miRNAs."}],"keywords":["Exosome therapy","PCOS","Photobiomodulation therapy","miR-155","miR-21"]},{"pmid":"38364185","title_fr":"Électroacupuncture versus laser-acupuncture dans la dysménorrhée : essai croisé randomisé","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser"],"nm":[],"n":43,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez 43 femmes, laser-acupuncture et électroacupuncture réduisent toutes deux la douleur et améliorent la qualité de vie, sans différence entre elles.","l2":"Essai croisé taïwanais ; l'électroacupuncture baisse davantage les prostaglandines.","l3":{"points":["Laser : EVA p = 0,010."],"limites":["Pas de simulation."],"pratique":"—"},"topic":"gynecologie","title":"Head-to-Head Comparison of Electroacupuncture and Laser Acupuncture Effects on Autonomic Regulation and Clinical Effects in Dysmenorrhea: A Randomized Crossover Clinical Trial.","journal":"Journal of integrative and complementary medicine","journal_abbr":"J Integr Complement Med","authors":["Chien TJ","Huang YS","Liao LL","et al."],"date":"2024-02-16","year":2024,"week":"2024-S07","doi":"10.1089/jicm.2023.0183","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"","text":"Introduction: Electroacupuncture (EA) has been applied in dysmenorrhea and has shown good efficacy. The mechanisms of EA are associated with autonomic nervous system adjustments and neuroendocrine regulation. Laser acupuncture (LA), however, has been widely investigated for its noninvasiveness. However, it remains uncertain whether LA is as effective as EA. This study aimed to compare EA and LA head to head in dysmenorrhea. Methods: A crossover, randomized clinical trial was conducted. EA or LA was applied to selected acupuncture points. Participants were randomized into two sequence treatment groups who received either EA or LA twice per week in luteal phase for 3 months followed by 2-month washout, then shifted to other groups (sequence 1: EA > LA; sequence 2: LA > EA). Outcome measures were heart rate variability (HRV), prostaglandins (PGs), pain, and quality-of-life (QoL) assessment (QoL-SF12). We also compared the effect of EA and LA in low and high LF/HF (low frequency/high frequency) status. Results: Totally, 43 participants completed all treatments. Both EA and LA significantly improved HRV activity and were effective in reducing pain (Visual Analog Scale [VAS]; EA: p < 0.001 and LA: p = 0.010) and improving QoL (SF12: EA: p < 0.001, LA, p = 0.017); although without intergroup difference. EA reduced PGs significantly (p < 0.001; δ p = 0.068). In low LF/HF, EA had stronger effects than LA in increasing parasympathetic tone in respect of percentage of successive RR intervals that differ by more than 50 ms (pNN50; p = 0.053) and very low-frequency band (VLF; p = 0.035). Conclusion: There is no significant difference between EA and LA in improving autonomic nervous system dysfunction, pain, and QoL in dysmenorrhea. EA is prominent in PGs changing and preserving vagus tone in low LF/HF; yet LA is noninvasive for those who have needle phobia. Whether LA is equivalent with EA and the mechanism warrants further study. Clinical trial identification number: NCT04178226."}],"keywords":["autonomic nervous system","dysmenorrhea","electroacupuncture","laser acupuncture","prostaglandins","quality of life"]},{"pmid":"38348528","title_fr":"La PBM soulage la dysménorrhée primaire induite par la PGF2α","type":"preclinical","level":5,"pop":"—","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[460,630,850],"n":null,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez l'animal et sur cellules musculaires utérines, 460, 630 et 850 nm réduisent la douleur ; le rouge 630 nm est le plus efficace.","l2":"Le rouge restaure le calcium intracellulaire, les ROS, l'ATP et le potentiel mitochondrial.","l3":{"points":["630 nm supérieur."],"limites":["Préclinique."],"pratique":"—"},"topic":"gynecologie","title":"Effect of photobiomodulation on alleviating primary dysmenorrhea caused by PGF2α.","journal":"Journal of biophotonics","journal_abbr":"J Biophotonics","authors":["Fu Q","Yang J","Jiang H","et al."],"date":"2024-02-13","year":2024,"week":"2024-S07","doi":"10.1002/jbio.202300448","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"","text":"Photobiomodulation (PBM) has attracted widespread attention in suppressing various pain and inflammation. Primary dysmenorrhea (PD) primarily occurs in adolescents and adult females, and the limited effectiveness and side effects of conventional treatments have highlighted the urgent need to develop and identify new adjunct therapeutic strategies. In this work, the results of pain and PGs demonstrated that 850 nm, 630 nm, and 460 nm all exhibited pain inhibition, decreased PGF2α and upregulated PGE2, while 630 nm PBM has better effectiveness. Then to explore the underlying biological mechanisms of red light PBM on PD, we irradiated prostaglandin-F2α induced HUSM cells and found that low-level irradiance can restore intracellular calcium ion, ROS, ATP, and MMP levels to normal levels. And, red light enhanced cell viability and promoted cell proliferation for normal HUSM cells. Therefore, this study proposes that red light PBM may be a promising approach for the future clinical treatment of PD."}],"keywords":["Ca2+","ROS","cell viability","photobiomodulation","primary dysmenorrhea","prostaglandins"]},{"pmid":"38101852","title_fr":"PBM contre la douleur des traumatismes du mamelon ou du périnée en post-partum : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":120,"effect":"—","theme":"Périnée post-partum","l1":"Protocole brésilien de 120 femmes (deux bras : mamelon et périnée) ; volet périnée publié en 2025 (pas de supériorité d'une séance unique).","l2":"Une application de PBM entre 6 et 36 h après l'accouchement contre simulation.","l3":{"points":["Résultats périnée : PMID 41255349."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Effectiveness of photobiomodulation therapy on pain intensity in postpartum women with nipple or perineal trauma: protocol for a multicentre, double-blinded, parallel-group, randomised controlled trial.","journal":"BMJ open","journal_abbr":"BMJ Open","authors":["Gondim EJL","Nascimento SL","Gaitero MVC","et al."],"date":"2023-12-14","year":2023,"week":"2023-S50","doi":"10.1136/bmjopen-2023-072042","pmcid":"PMC10729153","license":"cc by-nc","oa":true,"pdf":"pdfs/38101852.pdf","cited_by":3,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"INTRODUCTION","text":"Photobiomodulation (PBM) using low-level laser can affect tissue repair mechanisms and seems promising in reducing pain intensity. However, few studies support the effectiveness of PBM on postpartum period complications, such as nipple and/or perineal trauma and pain, probably due to the low doses used. The primary objective of this study is to analyse the effectiveness of PBM on pain intensity in the nipple and perineal trauma in women in the immediate postpartum period. Secondary objectives are to evaluate the effect on tissue healing and the women's satisfaction."},{"label":"METHODS AND ANALYSIS","text":"A double-blind, multicentre, parallel-group, randomised controlled trial will be performed in two public referral maternity hospitals in Brazil with 120 participants, divided into two arms: 60 participants in the nipple trauma arm and 60 participants in the perineal trauma arm. Participants will be women in the immediate postpartum period, who present with nipple trauma or perineal trauma and report pain intensity greater than or equal to 4 points on the Numerical Rating Scale for Pain. Block randomisation will be performed, followed by blinding allocation. In the experimental group, one application of PBM will be performed between 6 hours and 36 hours after birth. For the sham group, the simulation will be carried out without triggering energy. Both participants and the research evaluator will be blinded to the allocation group. Intention-to-treat method and the between-group and within-group outcome measures analysis will be performed."},{"label":"ETHICS AND DISSEMINATION","text":"This research protocol was approved by the Research Ethics Committees of the University of Campinas, Brazil, and of the School Maternity Assis Chateaubriand, Brazil (numbers CAAE: 59400922.1.1001.5404; 59400922.1.3001.5050). Participants will be required to sign the informed consent form to participate. Results will be disseminated to the health science community."},{"label":"TRIAL REGISTRATION NUMBER","text":"Brazilian Registry of Clinical Trials (RBR-2qm8jrp)."}],"keywords":["maternal medicine","pain management","wound management"]},{"pmid":"38017192","title_fr":"PBM associée au renforcement du plancher pelvien dans l'incontinence urinaire : essai en double aveugle contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[808],"n":22,"effect":"favorable","theme":"Incontinence urinaire","l1":"Chez 22 femmes avec incontinence d'effort, ajouter un laser 808 nm intravaginal au renforcement par cônes augmente la force et l'endurance du périnée par rapport au placebo.","l2":"Essai brésilien : 808 nm, 100 mW, 3 J par point, 3 points à l'entrée et 3 dans le vagin. La PBM limiterait la fatigue musculaire pendant la rééducation ; la qualité de vie s'améliore.","l3":{"points":["Force : 8,4 → 13,8 dans le groupe laser."],"limites":["Petit effectif."],"pratique":"—"},"topic":"gynecologie","title":"Effect of photobiomodulation associated with strengthening pelvic floor muscles in volunteers with urinary incontinence: a randomized, double-blinded, and placebo-controlled clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["da Silva AL","Lopes-Martins RAB","Dos Santos Oliveira A","et al."],"date":"2023-11-28","year":2023,"week":"2023-S48","doi":"10.1007/s10103-023-03919-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"The dysfunctions of the female pelvic floor have a great influence on the quality of life of women, in all areas, social, psychological, and sexual. Stress urinary incontinence is the clinical condition in which the woman involuntarily loses urine to efforts, such as coughing and sneezing, causing great embarrassment and affecting her quality of life. The physiotherapeutic treatments include muscle strengthening; however, muscle fatigue is present when performing the exercises. Here we investigate the effects of photobiomodulation to prevent muscle fatigue in the pelvic floor in the treatment of stress urinary incontinence, associated with a muscle strengthening exercise protocol. We used an infrared laser (808 nm, 100 mW) and 3 J/point and fluence of 107.1 J/cm2. The application was performed at 3 points on the vaginal introits and at another 3 points inside the vaginal canal cavity for the treatment of stress urinary incontinence associated with strengthening exercises with vaginal cones. Twenty-two volunteers participated in the study, divided into two groups: group 1 (laser therapy + strengthening) and group 2 (placebo laser + strengthening). In the group 1 quality of life score, the assessment (11.63 ± 4.33) was the highest score at 17 and in the reevaluation (7.81 ± 5.14) the lowest was 0 (p < 0.05). The muscular strength increased considerably (p < 0.05) for group 1, where the vast majority of patients gained more than twice the strength in the pelvic apparatus (8.36 ± 6.65 before X 13.81 ± 8.92 after). The volunteers acquired an increase in the contraction of the muscles of the pelvic apparatus (p < 0.05) (3.45 ± 1.07); after laser application, this number increased considerably (4.27 ± 0.61). Endurance had an increase of almost 50% compared to placebo, demonstrating the resistance gain in the perineal muscles (3.90 ± 2.35 X 5 ± 1.90). We concluded that photobiomodulation treatment showed significant efficacy in relation to muscle fatigue in the pelvic apparatus right after a strengthening program in women with stress urinary incontinence."}],"keywords":["LLLT","Laser therapy","PBM","Pelvic floor fatigue","Physiotherapy","Stress urinary incontinence"]},{"pmid":"37794569","title_fr":"Tous les lasers ne se valent pas : revue exploratoire du laser dans la vulvodynie","type":"sr","level":3,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Vulvodynie","l1":"Huit études (un seul essai randomisé) : de la PBM douce aux lasers ablatifs, les résultats sur la douleur de la vulvodynie sont encourageants mais de faible qualité.","l2":"Trois études sur six montrent une baisse significative de la douleur. Les auteurs insistent sur la distinction entre types de lasers.","l3":{"points":["8 études, qualité faible."],"limites":["Hétérogénéité des lasers."],"pratique":"—"},"topic":"gynecologie","title":"Not all lasers are the same: a scoping review evaluating laser therapy for vulvodynia.","journal":"Sexual medicine reviews","journal_abbr":"Sex Med Rev","authors":["Starzec-Proserpio M","Bardin MG","Morin M"],"date":"2023-10-05","year":2023,"week":"2023-S40","doi":"10.1093/sxmrev/qead039","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Scoping Review"],"abstract":[{"label":"INTRODUCTION","text":"Lasers are commonly used for treating various vaginal/vulvar conditions. To date, there is to our knowledge no available literature review on the effects of different types of lasers for the treatment of women with vulvodynia, a condition that causes chronic pain in the vulvar area."},{"label":"OBJECTIVES","text":"We sought to review the literature and summarize the existing published evidence regarding the effects of lasers for the treatment of women with vulvodynia."},{"label":"METHODS","text":"A scoping review with a systematic search was conducted that included studies investigating the use of laser treatment in women with vulvodynia. The National Heart, Lung, and Blood Institute Study Quality Assessment Tools were used for the quality assessment. The type of laser, effects on pain and function, and participants' perceived improvement as well as adverse events were analyzed."},{"label":"RESULTS","text":"Eight studies investigating laser therapy were included in the analysis: 1 randomized controlled trial, 5 before-after studies, 1 nonrandomized intervention study, and 1 case report. Several types of laser therapies were identified, ranging from mild noninvasive photobiomodulation to more invasive ablative procedures. Of the 6 studies that included pain outcomes, 3 studies showed statistically significant improvements from baseline to follow-up, and 3 demonstrated a reduction in pain from subjectively interpreted data. Similarly, each of the 2 studies investigating sexual function also reported an improvement (based only on subjective interpretation). Of the 2 studies with a comparison group, neither study was adequately powered to detect between-group differences. Furthermore, 57%-78% of participants reported improvement, with 1 study showing a greater statistically significant improvement in the low-level laser therapy patient group compared to the sham laser group. Outcomes and adverse events varied depending on the type of laser used."},{"label":"CONCLUSIONS","text":"Although these studies demonstrated some benefits of laser therapy for the treatment of vulvodynia, these findings should be interpreted with caution given the scarcity of the included studies that were robust and sufficiently powered. Future research should focus on conducting well-designed randomized controlled trials to evaluate the efficacy of different types of lasers in the treatment of vulvodynia."}],"keywords":["dyspareunia","laser therapy","lasers","pain management","pelvic pain","photobiomodulation therapy","vulvodynia"]},{"pmid":"37686314","title_fr":"PBM et microbiome vaginal : revue critique","type":"review","level":5,"pop":"—","ctx":["vulve"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Infections vulvovaginales","l1":"Revue théorique : la PBM pourrait moduler le microbiome vaginal, un champ encore à ses débuts.","l2":"Les auteurs transposent les données sur le microbiome intestinal.","l3":{"points":["Hypothèses mécanistiques."],"limites":["Revue narrative."],"pratique":"—"},"topic":"gynecologie","title":"New Insights into Photobiomodulation of the Vaginal Microbiome-A Critical Review.","journal":"International journal of molecular sciences","journal_abbr":"Int J Mol Sci","authors":["Santos FP","Carvalhos CA","Figueiredo-Dias M"],"date":"2023-08-31","year":2023,"week":"2023-S35","doi":"10.3390/ijms241713507","pmcid":"PMC10487748","license":"cc by","oa":true,"pdf":"pdfs/37686314.pdf","cited_by":7,"pub_types":["Review"],"abstract":[{"label":"","text":"The development of new technologies such as sequencing has greatly enhanced our understanding of the human microbiome. The interactions between the human microbiome and the development of several diseases have been the subject of recent research. In-depth knowledge about the vaginal microbiome (VMB) has shown that dysbiosis is closely related to the development of gynecologic and obstetric disorders. To date, the progress in treating or modulating the VMB has lagged far behind research efforts. Photobiomodulation (PBM) uses low levels of light, usually red or near-infrared, to treat a diversity of conditions. Several studies have demonstrated that PBM can control the microbiome and improve the activity of the immune system. In recent years, increasing attention has been paid to the microbiome, mostly to the gut microbiome and its connections with many diseases, such as metabolic disorders, obesity, cardiovascular disorders, autoimmunity, and neurological disorders. The applicability of PBM therapeutics to treat gut dysbiosis has been studied, with promising results. The possible cellular and molecular effects of PBM on the vaginal microbiome constitute a theoretical and promising field that is starting to take its first steps. In this review, we will discuss the potential mechanisms and effects of photobiomodulation in the VMB."}],"keywords":["lasers","low-level light therapy","microbiota","photobiomodulation","therapies","vagina"]},{"pmid":"37544939","title_fr":"Laser basse énergie et syndrome des ovaires polykystiques chez le rat : trois doses","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[],"n":40,"effect":"favorable","theme":"Fertilité","l1":"Chez le rat avec SOPK induit, la dose de 2 J/cm² ramène le mieux les hormones (LH, FSH, progestérone) vers la normale.","l2":"Comparaison 1, 2 et 6 J/cm².","l3":{"points":["Dose optimale 2 J/cm²."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"The effects of low-level laser therapy on polycystic ovarian syndrome in rats: three different dosages.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Polat B","Okur DT","Çolak A","et al."],"date":"2023-08-06","year":2023,"week":"2023-S31","doi":"10.1007/s10103-023-03847-6","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"The main objective of this in vivo study was to investigate the effect of different low-level laser therapy (LLLT) doses on polycystic ovary syndrome (PCOS). In the present experimental study, a single dosage of estradiol valerate (EV) was administered to induce PCOS in female rats. After administration of the EV for induction of PCOS, rats were divided into 5 groups (n = 8/group): C group (animals that were not exposed to any form of procedure), PC group (no treatment following EV induction), L1 group (1 J/cm2 LLLT treatment following EV induction), L2 group (2 J/cm2 LLLT treatment following EV induction), L3 group (6 J/cm2 LLLT treatment following EV induction). The results indicated that no significant difference was found in the serum levels of luteinizing hormone (LH), follicle-stimulating hormone (FSH), and progesterone (P4) between the C and L2 groups (p < 0.05). Although the serum levels of testosterone (T) were significantly higher in the C group compared with other groups (p < 0.05), the L2 group was determined to be the closest to the C group. Additionally, the LH, FSH, and T receptor level of the L2 group was closest to the C group. In conclusion, a 2 J/cm2 dosage of LLLT (L2 group) can be considered the most potentially effective treatment of PCOS in the rat. However, more studies are needed to determine the optimal dose of LLLT for the treatment of PCOS."}],"keywords":["Estradiol valerate","Low-level laser therapy","Polycystic ovary syndrome","Rat"]},{"pmid":"37583503","title_fr":"Vésicules extracellulaires de sang de cordon et PBM sur des ovocytes de SOPK (in vitro)","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Fertilité","l1":"In vitro, la PBM augmente la proportion d'ovocytes de SOPK atteignant la métaphase II et réduit les marqueurs d'apoptose et d'autophagie.","l2":"Ovocytes de femmes en parcours d'infertilité.","l3":{"points":["Taux de MII augmenté (p < 0,05)."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"Extracellular Vesicle-Derived Cord Blood Plasma and Photobiomodulation Therapy Down-Regulated Caspase 3, LC3 and Beclin 1 Markers in the PCOS Oocyte: An In Vitro Study.","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Sahraeian S","Abbaszadeh HA","Taheripanah R","et al."],"date":"2023-07-29","year":2023,"week":"2023-S30","doi":"10.34172/jlms.2023.23","pmcid":"PMC10423959","license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":[],"abstract":[{"label":"","text":"Introduction: Polycystic ovary syndrome (PCOS) is the communal endocrine illness in women and the most common cause of infertility due to lack of ovulation. The exact cause of PCOS is still unknown. Affected women may have difficulty getting pregnant due to ovulation problems. Various methods have not been effective in the treatment of PCOS due to the positive role of photobiomodulation therapy (PBMT) and extracellular vesicles (ECV) obtained from cord blood plasma in the treatment of various diseases. The aim of this study was to study the role of ECV and PBMT in maturation and improvement of infertility in women with PCOS. Methods: In this research, a number of oocytes were obtained after ovarian stimulation from women who had been referred to the hospital for infertility treatment after obtaining personal consent, and they were divided into three groups: control, ECV and PBMT. Subsequently, in vitro maturation (IVM) was assessed, then some oocytes were cultured with a routine medium and others were treated with ECV and PBMT. Real-time PCR was used to evaluate BCL-2, BAX, caspase-3, and autophagy gene (ATG5, LC3, Beclin 1). Oocyte glutathione (GSH), oxidised gluathione (GSSG), and reactive oxygen species (ROS) were measured. Results: The metaphase II (MII) oocyte ratio formation significantly increased in the ECV and PBMT groups (P<0.05). The expression of the BCL-2 gene was significantly up-regulated in the ECV and PBMT groups, but the expression of BAX and caspase-3 significantly decreased (P<0.05). The expression of the ATG5, LC3, BECLIN-2 genes significantly decreased in the ECV and PBMT groups (P<0.05). ROS, GSSG decreased in ECV and PBMT groups but GSH increased (P<0.05). Conclusion: The use of ECV and PBMT can increase the rate of fertilization and maturation of an oocyte and cause a decrease in apoptosis, autophagy, and ROS in a PCOS oocyte."}],"keywords":["Caspase 3","Cord blood plasma","Extracellular vesicle","Polycystic ovary syndrome"]},{"pmid":"37212452","title_fr":"La PBM 632 nm améliore les synéchies utérines via la voie cAMP/PKA/CREB (rat)","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[632],"n":null,"effect":"favorable","theme":"Fertilité","l1":"Chez le rat avec synéchies utérines, une PBM intra-utérine épaissit l'endomètre, réduit la fibrose et restaure en partie la fertilité.","l2":"Mécanisme confirmé sur cellules stromales endométriales humaines.","l3":{"points":["Voie cAMP/PKA/CREB."],"limites":["Modèle animal."],"pratique":"—"},"topic":"gynecologie","title":"Photobiomodulation therapy at 632 nm wavelength ameliorates intrauterine adhesion via activation of cAMP/PKA/CREB pathway.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["Zheng H","Wang C","Wu S","et al."],"date":"2023-05-22","year":2023,"week":"2023-S21","doi":"10.1111/php.13813","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"","text":"Intrauterine adhesion (IUA), a major cause of uterine infertility, is pathologically characterized by endometrial fibrosis. Current treatments for IUA have poor efficacy with high recurrence rate, and restoring uterine functions is difficult. We aimed to determine the therapeutic efficacy of photobiomodulation (PBM) therapy on IUA and elucidate its underlying mechanisms. A rat IUA model was established via mechanical injury, and PBM was applied intrauterinely. The uterine structure and function were evaluated using ultrasonography, histology, and fertility tests. PBM therapy induced a thicker, more intact, and less fibrotic endometrium. PBM also partly recovered endometrial receptivity and fertility in IUA rats. A cellular fibrosis model was then established with human endometrial stromal cells (ESCs) cultured in the presence of TGF-β1. PBM alleviated TGF-β1-induced fibrosis and triggered cAMP/PKA/CREB signaling in ESCs. Pretreatment with the inhibitors targeting this pathway weakened PBM's protective efficacy in the IUA rats and ESCs. Therefore, we conclude that PBM improved endometrial fibrosis and fertility via activating cAMP/PKA/CREB signaling in IUA uterus. This study sheds more lights on the efficacy of PBM as a potential treatment for IUA."}],"keywords":["632 nm laser","fibrosis","intrauterine adhesion","photobiomodulation","reproductive"]},{"pmid":"37183056","title_fr":"Photobiomodulation et troubles vulvovaginaux après traitements anticancéreux","type":"cohort","level":4,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":["intravaginal"],"nm":[],"n":28,"effect":"favorable","theme":"Après cancer","key":true,"l1":"Au CHU de Nîmes, 28 patientes en échec des traitements, dont la moitié après cancer : 72 % se sentent mieux ou beaucoup mieux après au moins 6 séances de PBM, avec une amélioration médiane estimée à 65 %.","l2":"Cohorte prospective française (Bulletin du Cancer). Symptôme principal : sécheresse vaginale (72 %) ; toutes avaient une dysfonction sexuelle. Antécédents de chimiothérapie (78 %), radiothérapie (36 %) ou hormonothérapie (36 %).\n\nAucun effet indésirable grave. Les auteurs soulignent l'absence de groupe témoin.","l3":{"points":["PGI-I ≤ 2 chez 72 %.","Amélioration médiane 65 % (Q1 50 %, Q3 72,5 %)."],"limites":["Petit effectif hétérogène, sans témoin."],"pratique":"Référence française pour proposer la PBM en soins de support gynécologiques après cancer."},"topic":"gynecologie","title":"[Photobiomodulation and vulvovaginal disorders after anticancer treatments].","journal":"Bulletin du cancer","journal_abbr":"Bull Cancer","authors":["Forret A","Mares P","Delacroix C","et al."],"date":"2023-05-12","year":2023,"week":"2023-S19","doi":"10.1016/j.bulcan.2023.03.018","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["English Abstract"],"abstract":[{"label":"","text":"Anticancer treatments induce vulvovaginal complications that alter the quality of life and sexuality of patients. New technologies, such as photobiomodulation, could address this problem, for which few effective therapeutic solutions exist. The objective of this study was to describe the characteristics of patients seeking treatment and to observe the effects of photobiomodulation. This is a prospective cohort of patients treated for cancer, in failure of first-line medical treatment, managed at the University Hospital of Nîmes. The history, symptoms and impact of the disorders on their quality of life were collected. At follow-up, improvement was assessed using the PGI-I and FSFI questionnaires. Twenty-eight patients were treated. They were all menopausal, half of them after anticancer treatments [chemotherapy (78%), radiotherapy (36%), hormone therapy (36%)]. The main symptom reported was vaginal dryness (72%). Seventy-one percent of patients (n=20) felt that their daily life was affected≥8/10. All patients had sexual dysfunction. Twenty-two patients received at least 6 sessions of photobiomodulation. Seventy-two percent (n=18) of patients felt better or much better after treatment (PGI-I≤2). The median improvement estimated by the patients was 65% (Q1=50%; Q3=72.5%). There was also a significant clinical improvement. No serious adverse events were reported. Due to the small number of patients in a heterogeneous population with no control group, we cannot extrapolate our results. However, the objective was to assess the status of these pathologies and the contribution of photobiomodulation in patients who have failed first-line treatment; and these results are encouraging."}],"keywords":["Anticancer treatments","Atrophie vulvovaginale","Genitourinary syndrome of menopause","Photobiomodulation","Sexuality","Sexualité","Syndrome génito-urinaire de la ménopause","Traitements anticancéreux","Vulvovaginal atrophy"]},{"pmid":"36915513","title_fr":"Métabolomique de la photothérapie sur points d'acupuncture contre contraceptif oral dans la dysménorrhée","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[],"n":69,"effect":"—","theme":"Dysménorrhée","l1":"Chez 69 femmes, la LED sur deux points d'acupuncture et la pilule modifient différemment les métabolites sanguins ; la LED abaisse la prostaglandine D2.","l2":"Volet biologique d'un essai multicentrique chinois.","l3":{"points":["76 métabolites modifiés sous LED."],"limites":["Critères biologiques."],"pratique":"—"},"topic":"gynecologie","title":"Metabolomic study combined with the low-level light therapy of Chinese acupuncture points and combined oral contraceptives in treatment of primary dysmenorrhea: A prospective, multicenter, randomized controlled study.","journal":"Heliyon","journal_abbr":"Heliyon","authors":["Wang H","Zhu S","Ding X","et al."],"date":"2023-02-16","year":2023,"week":"2023-S07","doi":"10.1016/j.heliyon.2023.e13821","pmcid":"PMC10006448","license":"cc by","oa":true,"pdf":"pdfs/36915513.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"To compare the changes of metabolites between Low-level light therapy (LLLT) and combined oral contraceptive (COC) after treatment of primary dysmenorrhea (PD), and to compare and analyze the biological and biochemical effects of the two treatments by analyzing the differences in metabolite profiles."},{"label":"METHODS","text":"A multicenter, double-blind, prospective, parallel, randomized controlled study was conducted on 69 women aged 16-35 years old with PD who were randomly divided into COC treatment group or LLLT treatment group. Low-level light therapy with light-emitting diodes (LED) was applied on two acupoints named \"Guanyuan\" (CV4) and \"Qihai\" (CV6). After 12 weeks of treatment intervention, blood samples were collected before and after treatment for metabolomic analysis. We used UPLC-MS/MS analysis to compare the differences in metabolite changes between LLLT and COC before and after treatment."},{"label":"RESULTS","text":"76 differential metabolites were detected in the LLLT group, and 92 differential metabolites were detected in the COC group, which were up-regulated or down-regulated (p < 0.001). Prostaglandin D2 (PG D2) was down-regulated and biliverdin was up-regulated after LLLT treatment, 4a-Hydroxytetrahydrobiopterin, Prostaglandin D2, 5-Hydroxy-l-tryptophan, Cholic acid were down-regulated and cortisol was up-regulated after COC treatment, and the differences were statistically significant. Cortisol and testosterone glucuronide in LLLT group were significantly lower than those in COC group. The metabolic pathways affected were glycerophospholipid metabolism, linoleic acid metabolism and arachidonic acid metabolism in the LLLT group, and glycerophospholipid metabolism, folate biosynthesis, arachidonic-acid-metabolism, and tryptophan metabolism in the COC group. The differential metabolic pathway were linoleic acid metabolism, steroid hormone biosynthesis, and alpha-Linolenic acid metabolism after the comparison of LLLT with COC."},{"label":"CONCLUSION","text":"LLLT and COC might relieve dysmenorrhea by down-regulating PGD2, and LLLT might also relieve dysmenorrhea by up-regulating biliverdin. The level of cortisol and testosterone glucuronide after LLLT treatment was lower than that after COC treatment, which might lead to the difference in the clinical efficacy of the two treatments for dysmenorrhea."}],"keywords":["Biliverdin","Combined oral contraceptive","Cortisol","Guanyuan (CV4)","Low-level light therapy","Metabolomics","Primary dysmenorrhea","Prostaglandin","Qihai (CV6)","Testosterone"]},{"pmid":"36769752","title_fr":"Pilates et/ou PBM associée à un champ magnétique statique dans l'incontinence urinaire d'effort : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser"],"nm":[],"n":33,"effect":"favorable","theme":"Incontinence urinaire","l1":"Chez 33 femmes avec incontinence d'effort, la PBM avec champ magnétique, le Pilates ou les deux améliorent force, tonus, fuites et qualité de vie.","l2":"Essai à trois bras (NCT05096936) ; tous les groupes progressent, sans supériorité nette de l'association.","l3":{"points":["Pad test à 1, 2 et 3 mois."],"limites":["Petits groupes."],"pratique":"—"},"topic":"gynecologie","title":"Pilates Method and/or Photobiomodulation Therapy Combined to Static Magnetic Field in Women with Stress Urinary Incontinence: A Randomized, Double-Blind, Placebo-Controlled Clinical Trial.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["De Marchi T","Ferlito JV","Turra AC","et al."],"date":"2023-01-31","year":2023,"week":"2023-S05","doi":"10.3390/jcm12031104","pmcid":"PMC9917687","license":"cc by","oa":true,"pdf":"pdfs/36769752.pdf","cited_by":5,"pub_types":[],"abstract":[{"label":"","text":"This clinical trial aims to provide evidence about the effectiveness of the Pilates method on stress urinary incontinence (SUI), as well as to elucidate the effects of photobiomodulation therapy associated with static magnetic field (PBMT/sMF) alone or associated with the Pilates Method on Pelvic floor muscle (PFM) in women affected by SUI. For that, a three-arm, parallel randomized, double-blinded, placebo-controlled trial was conducted (NCT05096936). We recruited thirty-three women diagnosed with SUI, randomly allocated to three groups: placebo PBMT/sMF plus method Pilates, PBMT/sMF active plus method Pilates and only PBMT/sMF active. The evaluation consisted of anamnesis and physical examination, muscle strength, completion of the ICIQ-SF questionnaire, and urinary loss. The evaluation of muscle strength and filling the ICIQ-SF were performed on the first and last days, while the Pad test was applied in baseline, one month, two months, and three months of intervention. We observed an increase in strength (p < 0.01), tone (p < 0.01), and quality of life (p < 0.01), in addition to a decrease in urinary lost (p < 0.01) for all groups comparing the pre and post-intervention. The PBMT/sMF alone, the Pilates, and the combination of the two therapies proved to be effective in improving the signs and symptoms of women with SUI."}],"keywords":["Photobiomodulation therapy","Pilates method","stress urinary incontinence","women’s health"]},{"pmid":"36395084","title_fr":"LED bleue contre les symptômes de vulvovaginite chronique : série de cas","type":"cases","level":4,"pop":"adulte","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[405],"n":8,"effect":"favorable","theme":"Infections vulvovaginales","l1":"Huit femmes avec vulvovaginite chronique : toutes améliorent au moins un symptôme après trois séances de LED bleue 405 nm.","l2":"Cinq améliorent aussi leurs scores de sexualité et de qualité de vie.","l3":{"points":["NCT03075046."],"limites":["8 cas."],"pratique":"—"},"topic":"gynecologie","title":"Blue Light-Emitting Diode Therapy for Chronic Vulvovaginitis Symptoms: A Series of Cases.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Pereira E Silva ACM","Brito MB","Robatto M","et al."],"date":"2022-11-17","year":2022,"week":"2022-S46","doi":"10.1089/photob.2022.0038","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":[],"abstract":[{"label":"","text":"Objective: This pilot study aimed to evaluate the characteristic signs and symptoms of chronic vulvovaginitis after blue light-emitting diode (LED) treatment. Methods: Women with characteristic signs and symptoms of vulvovaginitis were interviewed to obtain clinical and sociodemographic data. They answered the Female Sexual Function Index (FSFI) and the World Health Organization Quality of Life (WHOQOL)-bref questionnaires. Women with a suspected diagnosis of vulvovaginitis underwent clinical examination by a gynecologist, followed by microbiological evaluation, potassium hydroxide testing, vaginal pH assessment, and collection of vaginal fluid for oncotic cytology and fungal culture. The study participants were instructed to return after 15 days to undergo the 405 nm blue LED treatment, which consisted of three biweekly sessions. After 28 days of treatment completion, the patients returned for clinical re-evaluation and reassessment of the FSFI and WHOQOL-bref scores. Results: All eight women reported improvement or cure of at least one characteristic sign or symptom of vulvovaginitis, and five showed improvement in total FSFI and WHOQOL-bref scores. Conclusions: Treatment with blue LED may improve or cure symptoms associated with vulvovaginitis, sexual function, and the global quality of life score. Clinical Trial registration: NCT03075046 dated March 9, 2017."}],"keywords":["low-level light therapy","phototherapy","sexual dysfunction","vulvovaginitis"]},{"pmid":"36116559","title_fr":"PBM transvaginale et douleur du syndrome douloureux vésical avec sensibilité musculaire pelvienne","type":"cohort","level":4,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["intravaginal","laser"],"nm":[],"n":140,"effect":"favorable","theme":"Douleurs pelviennes","key":true,"l1":"Dans 17 cabinets américains, 64 % des femmes avec cystite interstitielle ayant fait 8 séances de PBM transvaginale ont une baisse cliniquement significative de la douleur pelvienne.","l2":"140 patientes ont débuté, 83 ont terminé 8 séances. Douleur à la miction, à l'effort et pendant les rapports diminuée d'environ 2,5 points.","l3":{"points":["Douleur sévère ou modérée : 83 % → 38 %."],"limites":["Observationnel, abandons fréquents."],"pratique":"—"},"topic":"gynecologie","title":"Transvaginal Photobiomodulation Improves Pain in Women with Pelvic Muscle Tenderness and Interstitial Cystitis/Bladder Pain Syndrome: A Preliminary Observational Study.","journal":"Urology","journal_abbr":"Urology","authors":["Butrick CW","Lamvu G"],"date":"2022-09-15","year":2022,"week":"2022-S37","doi":"10.1016/j.urology.2022.08.036","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":10,"pub_types":["Observational Study"],"abstract":[{"label":"PURPOSE","text":"Interstitial Cystitis/ Bladder Pain Syndrome (IC/BPS) is characterized by pelvic/bladder pain, associated with pelvic muscle tenderness, urgency, frequency, and dysuria. Prior studies show that transvaginal photobiomodulation (TV-PBM) reduces pain in women with chronic pelvic pain (CPP). Our objective was to obtain preliminary data on treatment effect and adherence, in women with IC/BPS who selected TV-PBM therapy for management of pelvic pain."},{"label":"MATERIALS AND METHODS","text":"Before-and-after observational cohort study of women with IC/BPS who received TV-PBM in 17 US practices. Pain was measured using a 0-10 numeric rating scale (NRS). The primary outcome was a minimal clinical important difference (MCID); reduction of overall pelvic pain severity by ≥2 NRS points from baseline compared to after 8 treatments. Cohen d coefficient measured effect size (low effect size d<0.2, medium 0.2<d<0.8, and high d>0.8)."},{"label":"RESULTS","text":"Of 140 patients with IC/BPS who self-selected to start TV-PBM therapy, 89.3% (n=125) completed 4 treatments and 59.3% (n=83) completed 8. Improvement ≥1 NRS point was reported by 73.5% (n=61) and meaningful improvement (≥2 points) was reported by 63.9% (n=53) after 8 treatments. In this group, patients with severe / moderate pain decreased from 83.1% (n=44) to 38.5% (n=20); p<0.001. Pain levels decreased as follows: overall pelvic pain MCID=-2.7, d=1.07, pain with urination MCID=-2.6, d=1.0; pain with exercise MCID=-2.6, d=0.91, pain with intercourse MCID=-2.5, d=0.82."},{"label":"CONCLUSION","text":"In real-world clinical settings, 2/3 women with IC/BPS who opted to undergo TV-PBM therapy reported significant decrease in pelvic pain and dysuria. These findings are promising; however, controlled studies are needed."}],"keywords":[]},{"pmid":"35835442","title_fr":"Rubus idaeus homéopathique et laser 680 nm sur des cellules de cancer du col (in vitro)","type":"preclinical","level":5,"pop":"—","ctx":["onco"],"aim":"—","mode":["laser"],"nm":[680],"n":null,"effect":"—","theme":"Sécurité oncologique","l1":"In vitro, l'association laser 680 nm + extrait de framboisier augmente l'ATP des cellules HeLa, ce qui suggère un effet Warburg plutôt qu'une mort cellulaire.","l2":"Étude exploratoire ; aucune conclusion clinique.","l3":{"points":["Fluences 5, 10 et 15 J/cm²."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"The In-Vitro Effect of Homeopathically Prepared Rubus idaeus and 680 nm Laser Irradiation on Cervical Cancer Cells.","journal":"Homeopathy : the journal of the Faculty of Homeopathy","journal_abbr":"Homeopathy","authors":["Joubert KS","George BP","Razlog R","et al."],"date":"2022-07-14","year":2022,"week":"2022-S28","doi":"10.1055/s-0042-1747683","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Cervical cancer (CC) is the second leading cancer in women and is the most common in those aged 15 to 44 years. Medicinal plant extracts have been used as homeopathic preparations for health benefits. Rubus idaeus (RI) is used to treat disorders of the female genital tract and produces cytotoxic effects. However, the use of homeopathically prepared RI in combination with low level laser therapy has not previously been explored."},{"label":"AIM","text":"The study aims to investigate the in-vitro effects of homeopathically prepared RI alone and in combination as a potential photosensitizer with Low-level laser irradiation (LLLI) at fluencies of 5, 10, and 15 J/cm2."},{"label":"METHODS","text":"HeLa CC cells were treated with RI (D3, D6, and 30cH homeopathic preparations). Cells were then treated with RI IC50 and 680 nm laser diode at 5, 10, and 15 J/cm2 fluencies, and the results compared with untreated control cells. Trypan blue viability, lactate dehydrogenase (LDH) cytotoxicity, and adenosine triphosphate (ATP) proliferation assays were used to analyze the cellular dose-responses along with inverted microscopy, Hoechst staining and Annexin-V/PI staining."},{"label":"RESULTS","text":"RI D3 alone demonstrated an ability to reduce cellular viability to 59% and also to reduce ATP levels. The subsequent combined treatment protocol of RI D3 with all fluencies of laser demonstrated an increase in cellular ATP and increased LDH levels compared with the control."},{"label":"CONCLUSION","text":"The increased ATP and LDH levels observed in the combined treatment protocol of 680 nm laser and RI D3 at fluencies of 5, 10 and 15 J/cm2, show that the Warburg effect might have been induced in the CC cells - an increase in glucose uptake and the preferential production of lactate, even in the presence of oxygen. More research, including work on other cell lines, needs to be conducted to identify if RI and perhaps a different wavelength of laser irradiation could have potential in inducing cell death in cancer cells."}],"keywords":[]},{"pmid":"35727394","title_fr":"Photomodulation LED de cellules d'adénocarcinome utérin : inhibition de l'angiogenèse via les exosomes","type":"preclinical","level":5,"pop":"—","ctx":["onco"],"aim":"—","mode":["LED"],"nm":[],"n":null,"effect":"—","theme":"Sécurité oncologique","l1":"In vitro, la LED réduit la viabilité et la migration de cellules de cancer de l'endomètre et freine leur capacité à stimuler l'angiogenèse.","l2":"Effets dépendants de la dose (4 à 64 J/cm²). Plutôt rassurant pour la sécurité, sur un seul modèle cellulaire.","l3":{"points":["Biogenèse des exosomes modifiée."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"Light-emitting diode photomodulation of uterine adenocarcinoma cells inhibited angiogenesis capacity via the regulation of exosome biogenesis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Mojtahedin S","Nasimi FS","Tajalli H","et al."],"date":"2022-06-21","year":2022,"week":"2022-S25","doi":"10.1007/s10103-022-03597-x","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":[],"abstract":[{"label":"","text":"This study was conducted to investigate the inhibitory effects of light-emitting diodes (LEDs) on exosome biogenesis and angiogenesis capacity in Ishikawa endometrial cancer cells. To this end, cells were exposed to different energy densities (fluences) of 4, 8, 16, 32, and 64 J/cm2 for 5 days (once every 24 h), and cell viability was determined using an MTT assay. Based on data from the MTT panel, cells were exposed to 4 and 16 J/cm2 for subsequent analyses. Exosome biogenesis was also monitored via monitoring the expression of CD63, ALIX, and Rab27a and b. The size and morphology of exosomes in the supernatant were measured using scanning electron microscopy (SEM), and dynamic light scattering (DLS). Using Transwell insert, the migration capacity of these cells was studied. The angiogenic effects of irradiated Ishikawa cell secretome at different fluences were monitored on human endothelial cells using in vitro tubulogenesis. Results indicated LED can reduce the viability of Ishikawa cells in a dose-dependent manner. According to our data, 4 and 64 J/cm2 groups exhibited minimum and maximum cytotoxic effects compared to the control cells. Data revealed a close proportional relationship between the power of laser and exosome average size compared to the non-treated control cells (p < 0.05). Real-time PCR analysis showed the suppression of Rab27b and up-regulation of Rab27a in irradiated cells exposed to 4 and 16 J/cm2 (p < 0.05). These effects were evident in the 16 J/cm2 group. Likewise, LED can inhibit the migration of Ishikawa cells in a dose-dependent manner (p < 0.05). Tubulogenesis activity of endothelial cells was suppressed after incubation with the secretome of irradiated Ishikawa cells (p < 0.05). These data showed tumoricidal properties of LED irradiation on human adenocarcinoma Ishikawa cells via the inhibition of exosome biogenesis and suppression of angiogenesis capacity."}],"keywords":["And Habib Tajalli contributed equally to this work and considered co-first authors","Angiogenesis","Exosome biogenesis","Fatemeh Sokouti Nasimi","Light-emitting diodes (LEDs)","Sima Mojtahedin","Uterine adenocarcinoma Ishikawa cells"]},{"pmid":"35389054","title_fr":"Photothérapie basse énergie adhésive dans l'hyperactivité vésicale : essai de phase III","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["LED","domicile"],"nm":[],"n":null,"effect":"favorable","theme":"Incontinence urinaire","key":true,"l1":"Essai coréen multicentrique de phase III contre simulation : un patch lumineux appliqué à domicile 3 fois par jour pendant 12 semaines réduit les fuites par urgence (−1,0 contre −0,4 par jour).","l2":"Double aveugle. Fuites totales −1,1 contre −0,5 par jour ; tendance favorable sur les scores de symptômes. Effets indésirables comparables.","l3":{"points":["Fuites par urgence : p = 0,003 ; fuites totales : p = 0,002."],"limites":["Population mixte (pas uniquement gynécologique)."],"pratique":"Un des rares essais de phase III en urogynécologie avec PBM."},"topic":"gynecologie","title":"Efficacy and safety of skin-adhesive low-level light therapy for overactive bladder: a Phase III study.","journal":"International urogynecology journal","journal_abbr":"Int Urogynecol J","authors":["Hwang WY","Kim YB","Lee SR","et al."],"date":"2022-04-07","year":2022,"week":"2022-S14","doi":"10.1007/s00192-022-05153-1","pmcid":"PMC9666307","license":"cc by","oa":true,"pdf":"pdfs/35389054.pdf","cited_by":4,"pub_types":["Randomized Controlled Trial","Multicenter Study","Clinical Trial, Phase III","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"INTRODUCTION AND HYPOTHESIS","text":"Overactive bladder (OAB) is a common condition that remains challenging to treat. We hypothesized that skin-adhesive low-level light therapy (LLLT) would be an effective treatment for OAB caused by bladder muscle contraction. Accordingly, we aimed to evaluate the efficacy and safety of an LLLT device for the treatment of OAB."},{"label":"METHODS","text":"This prospective, randomized, double-blind, placebo-controlled, multicenter trial included patients with a clinical diagnosis of OAB who were treated at either of two university hospitals. Patients were instructed to apply an LLLT device (Color DNA-WSF) or a sham device at home three times daily for 12 weeks. The primary outcome was the change in the mean daily number of urge urinary incontinence (UUI) episodes between baseline and 12 weeks. The secondary outcomes were the mean changes in incontinence, voiding, and nocturia episodes from baseline and the likelihood of achieving a > 50% reduction in UUI and incontinence episodes after 12 weeks. All patients completed the Overactive Bladder Symptom Score (OABSS), Urogenital Distress Inventory-6 (UDI-6), and Impact Urinary Incontinence-7 (IIQ-7) questionnaires. Safety parameters included treatment-emergent adverse events."},{"label":"RESULTS","text":"Compared with those in the sham group, the numbers of UUI and urinary incontinence episodes in the LLLT group were significantly decreased at week 12 (UUI, (-1.0 ± 1.7 vs. -0.4 ± 2.5, P = 0.003; urinary incontinence, -1.1 ± 1.9 vs. -0.5 ± 2.9, P=0.002). Furthermore, the OABSS, UDI-6, and IIQ-7 scores at week 12 tended to be better in the LLLT group than in the sham group. The incidence of device-related treatment-emergent adverse events was similar between groups."},{"label":"CONCLUSIONS","text":"LLLT may be clinically useful and safe for the treatment of OAB."}],"keywords":["Low-level light therapy","Overactive bladder","Randomized controlled trial"]},{"pmid":"35028764","title_fr":"Photothérapie basse énergie versus pilule œstroprogestative dans la dysménorrhée primaire : essai multicentrique","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["LED"],"nm":[],"n":156,"effect":"mitigé","theme":"Dysménorrhée","key":true,"l1":"Chez 156 femmes, la LED sur deux points d'acupuncture soulage la dysménorrhée chez 73,6 % (contre 85,7 % sous pilule, NS), mais la pilule réduit davantage la douleur.","l2":"Essai chinois randomisé sur trois cycles. Baisse de la douleur 39 % contre 60 % ; PGE2 diminuée de façon similaire. Option sans hormone pour les femmes qui ne veulent pas de contraception.","l3":{"points":["Taux d'efficacité : 73,6 % contre 85,7 % (p = 0,084)."],"limites":["Pas de simulation."],"pratique":"Alternative non hormonale, un peu moins efficace que la pilule."},"topic":"gynecologie","title":"Comparative evaluation of low-level light therapy and ethinyl estradiol and desogestrel combined oral contraceptive for clinical efficacy and regulation of serum biochemical parameters in primary dysmenorrhoea: a prospective randomised multicentre trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Zhu S","Ma X","Ding X","et al."],"date":"2022-01-14","year":2022,"week":"2022-S02","doi":"10.1007/s10103-021-03490-z","pmcid":"PMC8758216","license":null,"oa":true,"pdf":null,"cited_by":8,"pub_types":["Multicenter Study","Randomized Controlled Trial"],"abstract":[{"label":"","text":"We aimed to compare low-level light therapy with oral contraceptive pills for pain relief and serum levels of nitric oxide and prostaglandin E2 in patients with primary dysmenorrhoea. This was a randomised, active comparator-controlled, multicentre study. In total, 156 patients were randomised to receive either low-level light therapy with light-emitting diodes (LED) applying on two acupoints, namely, conception vessel 4 (CV4) and CV6 or conventional treatment with oral Marvelon, 30 µg of ethinyl estradiol and 150 µg of desogestrel (DSG/EE), for three consecutive menstrual cycles. The main outcome was the proportion of patients who achieved 33% or more decrease in pain scores measured using the visual analogue scale, which was deemed as efficient rate. Absolute changes in visual analogue scale scores, serum levels of nitric oxide (assessed by nitrites and nitrates reflecting nitric oxide metabolism) and prostaglandin E2 (measured by enzyme-linked immunosorbent assay) were the secondary outcomes. A total of 135 patients completed the study (73 in the light therapy group and 62 in the DSG/EE group). The efficient rate at the end of treatment was comparable between the groups (73.6% vs. 85.7%, χ2 = 2.994, p = 0.084). A more significant reduction in pain scores was observed in the DSG/EE group (39.25% vs. 59.52%, p < 0.001). Serum levels of prostaglandin E2 significantly decreased from baseline but did not differ between groups (- 109.57 ± 3.99 pg/mL vs. - 118.11 ± 12.93 pg/mL, p = 0.51). Nitric oxide concentration remained stable in both groups. Low-level light therapy with LED-based device applied on acupuncture points CV4 and CV6 demonstrated a similar level of dysmenorrhoea pain reduction to DSG/EE combined contraceptive. Both treatment modalities achieved clinically meaningful levels of pain reduction. Registration on ClinicalTrials.gov: TRN: NCT03953716, Date: April 04, 2019."}],"keywords":["Dysmenorrhoea","Low-level light therapy","Nitric oxide","Prostaglandin","Visual analogue scale"]},{"pmid":"35028769","title_fr":"Étirements vaginaux et laser vaginal de classe IIIB dans la douleur myofasciale du plancher pelvien : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[808],"n":103,"effect":"neutre","theme":"Douleurs pelviennes","key":true,"l1":"Chez 103 femmes avec douleur myofasciale pelvienne, ajouter une PBM 808 nm aux étirements vaginaux n'apporte pas plus de soulagement que les étirements seuls (sauf sur la constipation).","l2":"Essai brésilien en double aveugle contre simulation : 10 séances en 2 semaines. Douleur sévère : plus de 50 % avant, moins de 20 % après dans les deux groupes.","l3":{"points":["Douleur : p = 0,46 entre groupes."],"limites":["Effet important des étirements seuls."],"pratique":"Les étirements font l'essentiel ; la PBM n'ajoute pas de bénéfice dans ce protocole."},"topic":"gynecologie","title":"Vaginal stretching therapy and class IIIB vaginal laser treatment for pelvic floor myofascial pain: a randomized clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Frederice CP","Brito LGO","Machado HC","et al."],"date":"2022-01-14","year":2022,"week":"2022-S02","doi":"10.1007/s10103-022-03501-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"PURPOSE","text":"Several treatment options are proposed for the management of pelvic floor myofascial pain (PFMP). Manual therapy, such as vaginal stretching (VS), is one of these options. Photobiomodulation therapy (PBMT) with a laser device is a treatment option for PFMP that has been tested on other muscles. The aim of this study was to evaluate the effect of VS combined or not with PBMT for PFMP treatment."},{"label":"METHODS","text":"One hundred three women with PFMP were enrolled in a double-blind randomized trial and assigned to VS+PBMT (10 treatments over 2 weeks with 100 mw delivering 12 joules to surface intravaginally, using near-infrared light 808 nm) and VS+shamPBMT treatment groups. Pain severity was assessed by Visual Analog Scale (VAS). Pelvic floor muscle function was assessed by Oxford Scale and surface electromyography. Urinary symptoms were evaluated by ICIQ-OAB and ICIQ-SF questionnaires, and intestinal constipation was assessed by ROMA criteria."},{"label":"RESULTS","text":"There was a significant improvement in pain intensity (VAS) after treatment in both groups, with no difference between groups (p = 0.46). More than 50% of the women complained of severe pain before treatment, and after treatments, it was reported by less than 20% of women (p < 0.001), with no difference between groups (p = 0.08). Urinary symptoms improved in both groups (p < 0.001) with no difference between groups (p = 0.37). Intestinal constipation improved in the VS+PBMT group only (p = 0.01)."},{"label":"CONCLUSION","text":"VS and VS with near-infrared vaginal laser therapy were equally effective at decreasing myofascial pelvic pain and reducing urinary symptoms TRIAL REGISTRATION: REBEC (Registro Brasileiro de Ensaios Clínicos; Brazilian Registry of Clinical Trials) under no.RBR-2TDCQ4 (November 11, 2018)."}],"keywords":["Myofascial pain","Pelvic floor muscle","Photobiomodulation therapy","Randomized controlled trial","Stretching"]},{"pmid":"35155170","title_fr":"Laser basse énergie et sinensétine sur cellules tumorales HeLa et cellules normales","type":"preclinical","level":5,"pop":"—","ctx":["onco"],"aim":"—","mode":["laser"],"nm":[660],"n":null,"effect":"—","theme":"Sécurité oncologique","l1":"In vitro, un prétraitement laser 660 nm puis sinensétine augmente la mort des cellules de cancer du col HeLa (et des cellules normales).","l2":"Production accrue d'espèces réactives de l'oxygène.","l3":{"points":["Effet non sélectif sur les cellules normales."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"Effect of Low-Level Laser Therapy and Sinensetin (Combination therapy) on Tumor Cells (Hela) and Normal Cells (CHO).","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Javaheri B","Esmaeeli Djavid G","Parivar K","et al."],"date":"2021-12-27","year":2021,"week":"2021-S52","doi":"10.34172/jlms.2021.85","pmcid":"PMC8837833","license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"Introduction: Cervical and ovarian cancers are well-known causes of death among women in developing countries. There are various technologies to treat cancer cells, but the polyphenolic compound is a natural one and has an anti-cancer effect. Sinensetin is one of them and is found in Orthosiphon stamineus and citrus fruits. Since combination therapy is more effective than drug treatment alone, in this study, we investigated combination therapy using sinensetin and low-level laser therapy (LLLT) to enhance treatment. Methods: The cancer cells purchased from Pasteur Institute, Iran, were cultured. The cells were treated with various concentrations of sinensetin (0.1-1-10-50,150 µg/mL for 24 hours), wavelengths of laser therapy (660 nm) and power density (3 J/cm2) for different times)30, 60, and 90 seconds) separately. Furthermore, sensitivity of cells to sinensetin, LLLT and combined therapy was determined by clonogenic assays. To measure DNA damage and repair at individual cell level used comet assay. To examine the intracellular generation of reactive oxygen species used 2',7'-dichlorodihydrofluorescein (DCFH) as an intracellular probe. To analyze data we used SPSS software and comparison between groups was used (ANOVA) and t test statistical analyses were performed using SPSS 17 software. Data are presented as means - standard error of mean. The level of statistical significance was set at a two-tailed P value of 0.05. All tests were performed in triplicate. Results: Our results demonstrated that the doubling time for CHO is more than Hella cells, with 20.7 and 27.7 h for each cell respectively. The pretreatments (first LLLT, then sinensetin) can decrease the viability of both cell lines more than the first treatment (sinensetin + LLLT). In the clonogenic assay, the pretreatment of cells with LLLT and Sinensetin significantly reduced the surviving fraction of both cell lines. MTT results showed that pretreatment with LLLT and Sinensetin can increase cell death compared to Sinensetin and LLLT alone. Production of ROS within the cell was enhanced with LLLT + sinensetin. Conclusion: Our result indicated that combined therapy with LLLT and Sinensetin can treat CHO and Hela cells better than the other groups. Combination treatment with sinensetin-LLLT and the other treatment means, sinensetin and LLLT alone, did not change the cell viability significantly."}],"keywords":["Anti-cancer effect","CHO","Combined therapy","Hella","Low-level laser irradiation (LLLT)","Sinensetin"]},{"pmid":"34955173","title_fr":"Étirements vaginaux et PBM sur la fonction sexuelle dans la douleur myofasciale pelvienne : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser","intravaginal"],"nm":[808],"n":103,"effect":"neutre","theme":"Douleurs pelviennes","l1":"Même essai (103 femmes), volet sexualité : la dyspareunie diminue dans les deux groupes, sans avantage de la PBM active.","l2":"Rapports douloureux : 90 % → 55 % (PBM) et 87 % → 46 % (simulation).","l3":{"points":["Même population que PMID 35028769."],"limites":["Publication double d'un même essai."],"pratique":"—"},"topic":"gynecologie","title":"Effect of Vaginal Stretching and Photobiomodulation Therapy on Sexual Function in Women With Pelvic Floor Myofascial Pain - A Randomized Clinical Trial.","journal":"The journal of sexual medicine","journal_abbr":"J Sex Med","authors":["Frederice CP","de Mira TAA","Machado HC","et al."],"date":"2021-12-27","year":2021,"week":"2021-S52","doi":"10.1016/j.jsxm.2021.10.008","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"BACKGROUND","text":"Spasm or increased tonus of the pelvic floor muscles (PFM) can cause myofascial pain (MP), which may result in painful intercourse and sexual dysfunction."},{"label":"AIM","text":"The effect of vaginal stretching (VS) with photobiomodulation therapy (PBMT) is compared to VS with sham PBMT in overall sexual function, rate and severity of painful intercourse at baseline and after treatment in women with pelvic floor MP."},{"label":"METHODS","text":"A double-blind randomized clinical trial of 103 women with MP: 1 group received 10 sessions of VS with PBMT (4 Joules of near-infrared light-808 nm at 3 points), and the other group received VS with sham PBMT."},{"label":"OUTCOMES","text":"Impact of treatment was measured by the number of women experiencing painful intercourse, Pain severity was measured by Visual Analog Scale and sexual function was assessed by the FSFI questionnaire. Variables were assessed at baseline and after ten sessions in the intervention groups."},{"label":"RESULTS","text":"After treatment, the number of women experiencing painful intercourse was significantly lower in both the VS with PBMT group (90.2-55%, P = .001), and VS with sham PBMT group (86.6-46.2%, P < .001). There was a significant reduction in pain measure by Visual Analog Scale (P < .001, [VS with PBMT group: P = .002; VS with sham PBMT group: P < .001]). There was a significant decrease in the number of participants with sexual dysfunction (FSFI score ≤26.55) after the treatment in the VS with PBMT group (92.2-74.5%, P = .003) and in the VS with sham PBMT group (90.4-76.9%, P = .035). Both groups showed improvement in the FSFI pain domain after treatment (P < .001, [VS with PBMT group: P = .038; VS with sham PBMT group: P = .005]). Only the VS with sham PBMT group had a significant increase in FSFI desire and total score (P < .001) after treatment."},{"label":"CLINICAL IMPLICATIONS","text":"We found that VS associated or not with PBMT may be effective in reducing complaints of painful intercourse, alleviating pain severity, and reducing the number of women with pelvic floor MP suffering from sexual dysfunction."},{"label":"STRENGTHS & LIMITATIONS","text":"Strengths of this study are the randomized design and use of validated questionnaires. Limitation of the study is the lack of a long follow-up period and the lack of a usual care comparison group hampers generalizability of the results."},{"label":"CONCLUSION","text":"VS only and VS with PBMT have short-term efficacy in reducing painful intercourse and reducing a number of women with sexual dysfunction. Frederice CP, de Mira TAA, Machado HC, et al. Effect of Vaginal Stretching and Photobiomodulation Therapy on Sexual Function in Women With Pelvic Floor Myofascial Pain - A Randomized Clinical Trial. J Sex Med 2022;19:98-105."}],"keywords":["Myofascial Pain","Painful Intercourse","Passive Stretching","Pelvic Floor Muscle","Photobiomodulation Therapy","Sexual Dysfunction"]},{"pmid":"34841398","title_fr":"PBM transvaginale dans la douleur pelvienne chronique : étude pilote","type":"cohort","level":4,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["intravaginal","laser"],"nm":[],"n":13,"effect":"favorable","theme":"Douleurs pelviennes","l1":"Chez 13 femmes, neuf séances de PBM transvaginale divisent par deux le score de douleur (19,7 → 8,2) avec un effet maintenu à 6 mois.","l2":"Étude avant-après ; grandes tailles d'effet (d = 1,6 à 1,9).","l3":{"points":["60 % améliorées."],"limites":["Très petit effectif."],"pratique":"—"},"topic":"gynecologie","title":"Transvaginal Photobiomodulation for the Treatment of Chronic Pelvic Pain: A Pilot Study.","journal":"Women's health reports (New Rochelle, N.Y.)","journal_abbr":"Womens Health Rep (New Rochelle)","authors":["Zipper R","Pryor B","Lamvu G"],"date":"2021-11-23","year":2021,"week":"2021-S47","doi":"10.1089/whr.2021.0097","pmcid":"PMC8617585","license":"cc by","oa":true,"pdf":"pdfs/34841398.pdf","cited_by":4,"pub_types":[],"abstract":[{"label":"","text":"Background: Chronic pelvic pain (CPP) is a common and debilitating condition that affects millions of U.S. women. Most treatments are ineffective and innovative new therapies are desperately needed. Large, controlled studies show that photobiomodulation (PBM) can reduce pain in patients with other chronic pain conditions, such as low back pain, neck pain, and fibromyalgia. The objective of this pilot study was to determine if transvaginal PBM (TV-PBM) can reduce pain in women with CPP. Methods: We conducted a before and after, observational, pilot study. Patients completed the Short Form-McGill Pain Questionnaire (SF-MPQ) at baseline, 1 week, 3 months, and 6 months after nine treatments of TV-PBM. Clinicians completed the Clinical Global Impression Scale (CGI) assessing patient illness severity at the same time. Wilcoxon rank-sum t-tests and effect size using Cohen's d coefficient (low effect size if d < 0.2, medium if 0.2 < d > 8, and high if d > 0.8) was used to measure degree of pain improvement, which was also considered clinically significant if pain reduction was >30%. Results: Thirteen women completed 9 treatments, and 10 women were successfully followed to 6 months. At baseline, the mean SF-MPQ score was 19.7 (standard deviation [SD] ± 5.9). Compared with baseline, 60% improved; the mean SF-MPQ score decreased to 10.0 (SD ±7.5, p = 0.004, d = 1.6) at 1 week after treatment, to 9.7 (SD ±7.9, p = 0.005, d = 1.7) at 3 months, and 8.2 (SD ±8.1, p = 0.002, d = 1.9) at 6 months. Conclusion: Transvaginal PBM provided significant and sustained pain relief to women with CPP up to 6 months. Further controlled studies are needed to confirm these findings, however, in this initial pilot, TV-PBM shows promise."}],"keywords":["chronic pelvic pain","low-level laser therapy","photobiomodulation"]},{"pmid":"34749319","title_fr":"Facteurs physiques dans la rééducation des accouchées avec plaie périnéale après ventouse","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[],"n":154,"effect":"favorable","theme":"Périnée post-partum","l1":"Chez 154 accouchées après ventouse, le laser magnétique basse intensité améliore la force du périnée et réduit les complications, encore plus avec une stimulation magnétique.","l2":"Étude géorgienne à trois groupes (randomisation simple). Complications divisées par 4,6 avec laser, par 6,5 avec laser + stimulation.","l3":{"points":["Force pelvienne +36 % (laser) et +48 % (laser + stimulation)."],"limites":["Méthode peu détaillée."],"pratique":"—"},"topic":"gynecologie","title":"[PHYSICAL THERAPEUTIC FACTORS IN STAGE MEDICAL REHABILITATION OF PUERPERAS WITH PERINEAL WOUNDS AFTER FETAL VACUUM EXTRACTION].","journal":"Georgian medical news","journal_abbr":"Georgian Med News","authors":["Uzdenova Z","Zalikhanova Z","Gatagazheva Z","et al."],"date":"2021-11-08","year":2021,"week":"2021-S45","doi":null,"pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Objective - to assess the role of physical therapeutic factors in the staged medical rehabilitation of puerperas with perineal wounds after fetal vacuum extraction. A comparative analysis of the postpartum period was carried out in 154 puerperas with perineal injuries after fetal vacuum extraction. Three groups were formed by simple randomization: patients in the control group (54 women) received standard treatment only; the experimental group (51 women) received standard treatment and low-intensity magnetic laser therapy (LLLT); the main group (49 women) underwent additional extracorporeal magnetic stimulation. Staged physiotherapy provided an increase in the strength of the pelvic floor muscles in patients of the main group by 47.9% (p<0.01), experimental group - by 36.2% (p<0.01), and control - by 24.4% (p <0.05); a decrease in the number of postoperative complications was by 6.5, 4.6, and 2.63 times, respectively. The use of staged physiotherapy in puerperas with perineal wounds after delivery operations provides a statistically significant improvement in clinical and functional parameters in comparison with the use of only standard treatment and its combination with NMLT."}],"keywords":[]},{"pmid":"34662815","title_fr":"Organoïdes endométriaux de souris stimulés par laser basse énergie : modèle de régénération","type":"preclinical","level":5,"pop":"—","ctx":["fertilité"],"aim":"—","mode":["laser"],"nm":[632.8],"n":null,"effect":"favorable","theme":"Fertilité","l1":"Le laser He-Ne stimule la prolifération d'organoïdes d'endomètre de souris, un modèle pour étudier le syndrome d'Asherman.","l2":"Étude in vitro avec matrice utérine décellularisée.","l3":{"points":["Ki67 et PCNA augmentés."],"limites":["In vitro."],"pratique":"—"},"topic":"gynecologie","title":"Bio-modulated mice epithelial endometrial organoids by low-level laser therapy serves as an invitro model for endometrial regeneration.","journal":"Reproductive biology","journal_abbr":"Reprod Biol","authors":["Gebril M","Aboelmaaty A","Al Balah O","et al."],"date":"2021-10-15","year":2021,"week":"2021-S41","doi":"10.1016/j.repbio.2021.100564","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Evaluation Study"],"abstract":[{"label":"","text":"Endometrial regeneration is a dynamic process that is not well understood. The destruction of the endometrium with the formation of intrauterine adhesions is known as Asherman's syndrome. The lesions range from minor to severe adhesions and their impact on pregnancy is well documented. Operative hysteroscopy is the mainstay of diagnosis and treatment of intrauterine adhesions. Nevertheless, the recurrence rates remain high. It was recorded that low-level laser therapy in low doses has a stimulatory effect on different tissues while the high dose produces a suppressive effect. Organoid is a three-dimensional assembly that displays architectures and functionalities similar to in vivo organs that are being developed from human or animal stem cells or organ-specific progenitors through a self-organization process. Our prospective was to study the effect of Low-Level Laser Therapy (LLLT) on mouse epithelial endometrial organoids regarding cell proliferation and endometrial regeneration as a new modality of treatment. An in vitro clinical trial to generate mouse epithelial organoid model and testing LLLT using He:Ne 632.8 nm device on organoids proliferation, function, and their response to ovarian hormones was performed. Trying endometrial regeneration by culturing organoids with decellularized uterine matrix (DUM) and studying the LLLT effect on the regeneration process. LLLT produced a proliferative effect on the epithelial mouse organoids confirmed by Ki67 and PCNA IHC. The organoids could regenerate the epithelial layer of the endometrium in vitro on DUM and LLLT could help in this process. In conclusion, organoids whether control or bio-stimulated proved a new modality to regenerate the endometrium."}],"keywords":["Asherman’s syndrome","Endometrial regeneration","LLLT","Organoids"]},{"pmid":"34733773","title_fr":"Laser thérapeutique pendant la grossesse : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["obstétrique"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Sécurité","l1":"Revue : le laser basse énergie pour les troubles musculosquelettiques n'est pas recommandé pendant la grossesse faute de données de sécurité.","l2":"53 articles analysés en urologie, dermatologie, obstétrique et orthopédie.","l3":{"points":["Pas de recommandation pour la PBM musculosquelettique pendant la grossesse."],"limites":["Peu de données."],"pratique":"Prudence : éviter la PBM sur l'abdomen et le bassin pendant la grossesse hors protocole."},"topic":"gynecologie","title":"A Systematic Review of Elective Laser Therapy during Pregnancy.","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Allameh F","Javadi A","Dadkhahfar S","et al."],"date":"2021-09-19","year":2021,"week":"2021-S37","doi":"10.34172/jlms.2021.50","pmcid":"PMC8558736","license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Review"],"abstract":[{"label":"","text":"Introduction: Currently, lasers are used to treat many diseases and their complications. However, the use of lasers in pregnant patients is still controversial. Methods: In this review, the application of lasers in the fields of urology, surgery, obstetrics, dermatology, and musculoskeletal disorders is evaluated. The following keywords were used to search through PubMed, Google Scholar, and Scopus: pregnancy, laser, urolithiasis, endovenous laser ablation (EVLA) or treatment, leg edema, varicose vein, venous insufficiencies, hair removal, pigmentation, telangiectasia, vascular lesions, Q switch laser, diode laser, holmium, holmium-YAG laser, erbium laser and Pulsed dye laser, low-level laser therapy, high-intensity laser therapy, pain, musculoskeletal disorders, twin to twin transfusion syndrome (TTTS), amnioreduction, and safety. Results: Totally, 147 articles were found, and their abstracts were evaluated; out of 53 articles extracted, 14 articles were about dermatology, 24 articles were about urology, 12 articles were about obstetrics and gynecology, 10 articles were about musculoskeletal disorders and three articles were related to surgery. Conclusion: Laser therapy can be used as a safe treatment for urolithiasis, skin diseases, TTTS and varicose veins of the lower extremities. However, the use of laser therapy for musculoskeletal disorders during pregnancy is not recommended due to lack of evidence, and also we cannot recommend endovenous ablation."}],"keywords":["Dermatology","Laser","Musculoskeletal disorders","Obstetrics and gynecology","Physical medicine and rehabilitation","Pregnancy","Surgery","Urology"]},{"pmid":"34490787","title_fr":"PBM du plancher pelvien dans la douleur pelvienne chronique : cohorte observationnelle","type":"cohort","level":4,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["intravaginal","laser"],"nm":[],"n":128,"effect":"favorable","theme":"Douleurs pelviennes","l1":"Chez 128 femmes, neuf séances de PBM transvaginale améliorent la douleur pelvienne chronique chez 64,5 %, y compris pendant les rapports et en position assise.","l2":"Baisse de 2 à 3 points de la douleur selon les activités ; aucun effet indésirable grave.","l3":{"points":["Douleur vulvaire : −3,1 points."],"limites":["Sans témoin."],"pratique":"—"},"topic":"gynecologie","title":"An observational cohort study of pelvic floor photobiomodulation for treatment of chronic pelvic pain.","journal":"Journal of comparative effectiveness research","journal_abbr":"J Comp Eff Res","authors":["Kohli N","Jarnagin B","Stoehr AR","et al."],"date":"2021-09-07","year":2021,"week":"2021-S36","doi":"10.2217/cer-2021-0187","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Observational Study"],"abstract":[{"label":"","text":"Aim: This research is the first to evaluate the effectiveness of trans-vaginal photobiomodulation therapy (TV-PBMT) for chronic pelvic pain. Materials & methods: Observational analysis of 128 women, undergoing TV-PBMT for chronic pelvic pain. Minimal clinically important difference, defined as ≥2-point drop on a 0-10 numeric pain rating scale (NPRS), and effect size Cohen d coefficient, was calculated over nine treatments for overall pain, and pain with activities. Results: Compared with baseline, 64.5% of women showed improvement in overall pain, pain with bowel movement, intercourse, exercise, urination, sitting and vulvar pain (minimal clinically important difference = -2.4, -2.0, -2.4, -2.1, -2.1, -2.0, -3.1; d = 0.9, 0.7, 0.9, 0.7, 0.7, 0.7, 0.9) by treatment 9. Conclusion: In this cohort, TV-PBMT resulted in improvement of pelvic pain without serious adverse events."}],"keywords":["chronic pelvic pain","low-level laser therapy","photobiomodulation"]},{"pmid":"34539076","title_fr":"Laser haute intensité pulsé versus laser basse énergie dans la dysménorrhée primaire","type":"rct","level":2,"pop":"adulte","ctx":["pelvien"],"aim":"traitement","mode":["laser","haute puissance"],"nm":[],"n":30,"effect":"favorable","theme":"Dysménorrhée","l1":"Chez 30 femmes, laser haute intensité et laser basse énergie réduisent autant la douleur de la dysménorrhée.","l2":"Trois séances par cycle pendant trois cycles ; pas de groupe témoin.","l3":{"points":["Pas de différence entre les deux lasers."],"limites":["Sans témoin."],"pratique":"—"},"topic":"gynecologie","title":"Pulsed high-intensity laser therapy versus low level laser therapy in the management of primary dysmenorrhea.","journal":"Journal of physical therapy science","journal_abbr":"J Phys Ther Sci","authors":["Thabet AA","Ebid AA","El-Boshy ME","et al."],"date":"2021-09-01","year":2021,"week":"2021-S35","doi":"10.1589/jpts.33.695","pmcid":"PMC8436040","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/34539076.pdf","cited_by":8,"pub_types":[],"abstract":[{"label":"","text":"[Purpose] To determine the effect of pulsed high intensity laser therapy (HILT) versus low level laser therapy (LLLT) in the treatment of primary dysmenorrhea. [Participants and Methods] This was a randomized clinical trial that included 30 females diagnosed with primary dysmenorrhea who were assigned randomly into two groups of equal numbers. The treatment was three sessions every cycle for three consecutive cycles, where group (A) received pulsed HILT and group (B) received LLLT. All participants were evaluated before and after treatment sessions by visual analogue scale (VAS) and at the end of treatment by pain relief scale (PRS). [Results] The results showed a significant decrease in the severity of pain in the two groups. Comparison between the two groups showed a statistically non-significant difference in the severity of pain and pain alleviation at the end of the treatment course. [Conclusion] Both pulsed HILT and LLLT are effective in the treatment of primary dysmenorrhea, with no significant differences between the two modalities."}],"keywords":["Low level laser","Primary dysmenorrhea","Pulsed high-intensity laser"]},{"pmid":"34447833","title_fr":"LED bleue contre la sténose vaginale après radiothérapie pelvienne : deux cas","type":"cases","level":4,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":["LED","intravaginal"],"nm":[],"n":2,"effect":"favorable","theme":"Après cancer","l1":"Deux patientes avec sténose vaginale après cancer du col ou de l'endomètre s'améliorent cliniquement et cytologiquement avec une LED bleue vaginale et vulvaire hebdomadaire.","l2":"Questionnaires validés et frottis répétés montrent une amélioration des symptômes les plus gênants.","l3":{"points":["Sténose sévère et légère traitées."],"limites":["Deux cas."],"pratique":"—"},"topic":"gynecologie","title":"Blue LED as a new treatment to vaginal stenosis due pelvic radiotherapy: Two case reports.","journal":"World journal of clinical cases","journal_abbr":"World J Clin Cases","authors":["Barros D","Alvares C","Alencar T","et al."],"date":"2021-08-27","year":2021,"week":"2021-S34","doi":"10.12998/wjcc.v9.i23.6839","pmcid":"PMC8362505","license":"cc by-nc","oa":true,"pdf":"pdfs/34447833.pdf","cited_by":5,"pub_types":["Case Reports"],"abstract":[{"label":"BACKGROUND","text":"Currently, the advancement cancer treatment technology improves overall survival, however, adverse events are still a challenge for health professional. Genitourinary syndrome of menopause and vaginal stenosis are conditions that impact the quality of life of patients undergoing radiotherapy. We present two such cases in patients with previous cervical and endometrial cancer. These conditions were handled with an innovative method using an energy-based device with blue light emitting diode for concomitant vaginal and vulvar irradiation. Positive impact in clinical findings, cytologic changes, and referred symptoms were documented."},{"label":"CASE SUMMARY","text":"One patient diagnosed with vaginal severe vaginal stenosis with previous cervix cancer treatment and other patient diagnosed with mild stenosis with severe dyspareunia and recent endometrium cancer treatment were considered for vulvovaginal treatment with weekly blue led device and closely evaluated with repeated validated questionnaires and cytological samples."},{"label":"CONCLUSION","text":"This innovative technique showed an improvement in all areas of the examiner's criteria, the cytological criteria, and most bothered symptoms."}],"keywords":["Atrophic vaginitis","Case report","Laser therapy","Nonhormonal vaginal therapy","Radiotherapy","Semiconductor diode lasers","Vaginal diseases"]},{"pmid":"34776164","title_fr":"Kinésithérapie et cancer gynécologique : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["onco"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Après cancer","l1":"Cinq études seulement : exercice supervisé, PBM et rééducation périnéale semblent utiles contre les complications des traitements des cancers gynécologiques.","l2":"Revue (10 ans, 405 articles) en portugais, anglais et espagnol.","l3":{"points":["5 études incluses."],"limites":["Très peu d'études."],"pratique":"—"},"topic":"gynecologie","title":"Physiotherapy in the management of gynecological cancer patient: A systematic review.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Monteiro MGCT","de Morais Gouveia GP"],"date":"2021-06-25","year":2021,"week":"2021-S25","doi":"10.1016/j.jbmt.2021.06.027","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Systematic Review"],"abstract":[{"label":"AIM","text":"to evaluate the effectiveness of physiotherapy as an adjunct treatment in patients with gynecological cancer."},{"label":"METHOD","text":"systematic review carried out in the PubMed, MEDLINE, via VHL, Cochrane and SciELO, in the last ten years. A search strategy was based on the PICO method and the PRISMA flowchart using Boolean descriptors and operators: \"gynecological cancer or neoplasms of female genital organs\" and \"physiotherapy or physiotherapy modalities\" and \"rehabilitation or quality of life\" in languages Portuguese, English, and Spanish."},{"label":"RESULTS","text":"405 articles were found, and after eligibility criteria, only 5 studies were selected for review. Evidence of a monitored physical exercise, photobiomodulation and pelvic floor rehabilitation program as physiotherapeutic resources in the management of gynecological cancer."},{"label":"CONCLUSION","text":"Physiotherapy dominates techniques and appears to be beneficial for the main complications arising from the treatment or post-treatment of gynecological cancer and has sought to accompany the knowledge and care of the patient, through scientific research."}],"keywords":["Genital neoplasms female","Gynecologic cancer","Physical therapy modalities","Physical therapy specialty","Quality of life","Rehabilitation"]},{"pmid":"33989716","title_fr":"Le laser basse énergie local protège les ovaires de la toxicité du cyclophosphamide chez la souris","type":"preclinical","level":5,"pop":"—","ctx":["fertilité","onco"],"aim":"prévention","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Préservation de la fertilité","key":true,"l1":"Chez la souris, un laser appliqué sur les ovaires avant le cyclophosphamide préserve les follicules, l'AMH et la vascularisation : piste de préservation de la fertilité en cancérologie.","l2":"64 J/cm² ; moins d'apoptose folliculaire et de follicules atrétiques.","l3":{"points":["Follicules primordiaux préservés."],"limites":["Modèle animal."],"pratique":"Piste de recherche en oncofertilité."},"topic":"gynecologie","title":"Local application of low level laser therapy in mice ameliorates ovarian damage induced by cyclophosphamide.","journal":"Molecular and cellular endocrinology","journal_abbr":"Mol Cell Endocrinol","authors":["Oubiña G","Pascuali N","Scotti L","et al."],"date":"2021-05-12","year":2021,"week":"2021-S19","doi":"10.1016/j.mce.2021.111318","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"","text":"The aim of the present study is to assess whether low level laser therapy (LLLT) can protect ovaries from chemotherapy-induced gonadotoxicity using a mice model of premature ovarian failure induced by cyclophosphamide (CTX). LLLT (64 J/cm2) increased the number of antral follicles whilst decreasing the number of atretic follicles compared to CTX alone. LLLT increased the number of primordial follicles compared with those in the CTX group but they did not differ from those in the control group. LLLT treatment increased the number of AMH-positive follicles compared to CTX alone. LLLT application increased ovarian weight, serum progesterone concentration and P450scc protein levels compared to CTX alone. LLLT reduced the apoptosis in antral follicles and the BAX/BCL-2 ratio compared to CTX alone. Vascular morphology, analysed by CD31 and α-SMA immunostaining, was restored in LLLT-treated ovaries compared to CTX alone. In conclusion, application of LLLT prior to CTX might serve as a promising and novel protocol to preserve female fertility in cancer survivors."}],"keywords":["Angiogenesis","Apoptosis","Cancer","Chemotherapy","Low level laser therapy","Ovary"]},{"pmid":"33855615","title_fr":"Nouveau laser transvaginal proche infrarouge pour tissus profonds : évaluation chez la brebis","type":"preclinical","level":5,"pop":"—","ctx":["pelvien"],"aim":"—","mode":["intravaginal","haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Dosimétrie","l1":"Chez la brebis, seulement 3 % de l'irradiance vaginale atteint le muscle releveur de l'anus : il faut 5 W en surface pour une dose thérapeutique, 0,5 W ne suffit pas.","l2":"Étude de dosimétrie du dispositif SoLá ; utile pour comprendre les échecs à faible puissance.","l3":{"points":["Bladder : 4,4 % de l'irradiance de surface."],"limites":["Modèle animal."],"pratique":"Pour cibler les muscles pelviens, la dose de surface doit être élevée."},"topic":"gynecologie","title":"Evaluation of a novel deep tissue transvaginal near-infrared laser and applicator in an ovine model.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Zipper R","Pryor B"],"date":"2021-04-14","year":2021,"week":"2021-S15","doi":"10.1007/s10103-021-03315-z","pmcid":"PMC8803674","license":"cc by","oa":true,"pdf":"pdfs/33855615.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) is an effective means of treating muscle spasm and pain. A novel near-infrared laser system has been commercialized for the treatment of myofascial pelvic pain in women (SoLá Therapy, UroShape, LLC). This study was undertaken to determine if this device is capable of delivering therapeutic levels of irradiance to the pelvic muscles and to identify the surface irradiance required to achieve this goal. This novel class IV near-infrared laser and transvaginal applicator were used to deliver near-infrared light energy through the vaginal mucosa of an adult Suffolk/Dorset Ewe. Irradiance was measured on the surface of the levator ani muscle, inside the levator ani muscle, and inside the bladder. Measurements were taken at powers of 5 W and 0.5 W. 3.0% of vaginal surface irradiance was measured inside of the levator ani muscle. 4.4% of vaginal surface irradiance was measured inside the bladder. At 5 W, the novel laser system provided a surface irradiance of 738 mW/cm2. At 0.5 W, the system provided a surface irradiance of 74 mW/cm2. A novel class IV near-infrared laser and transvaginal applicator delivered therapeutic irradiance to the levator ani muscle and bladder of an anesthetized ewe at a power setting of 5 W. A power setting of 0.5 W failed to deliver therapeutic energy into either the levator ani muscle or bladder. Clinical applications targeting deeper tissues such as the pelvic muscles and or bladder should consider power settings that exceed 0.5 W and or irradiance of ≥ 75 mW/cm2."}],"keywords":["Irradiance","Pain","Pelvis","Photobiomodulation","Therapy"]},{"pmid":"33760671","title_fr":"PBM et analgésie pendant l'accouchement : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["LED"],"nm":[660,850],"n":29,"effect":"favorable","theme":"Accouchement","l1":"Chez 29 parturientes, une plaque LED rouge et infrarouge posée 10 minutes sur le bas du dos réduit la douleur du travail, sans effet sur le bébé ni la durée du travail.","l2":"Essai brésilien contre douche chaude. 216 J au total de T10 à S4. Apgar et rythme cardiaque fœtal inchangés.","l3":{"points":["Bonne sécurité fœtale."],"limites":["Petit effectif ; comparateur actif."],"pratique":"—"},"topic":"gynecologie","title":"The Effect of Photobiomodulation on Analgesia During Childbirth: A Controlled and Randomized Clinical Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Traverzim MA","Sobral APT","Fernandes KPS","et al."],"date":"2021-03-23","year":2021,"week":"2021-S12","doi":"10.1089/photob.2020.4976","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Background: Pain during labor can be a barrier when choosing vaginal delivery. In an attempt to relief pain during labor, several pharmacological and nonpharmacological methods are proposed. Objective: To assess the effect of light-emitting diode (LED) photobiomodulation on analgesia during labor. Methods: A clinical trial was conducted with 29 women who were divided into two groups: G1 (experimental group-LED) and G2 (control group-hot shower). In the experimental group, an LED plate with red and infrared merged [red 660 ± 20 nm, 5 mW/cm2, 3 J per LED (108 J) and infrared 850 ± 20 nm, 5 mW/cm2, 3 J per LED (108 J), total energy = 216 J] was placed on the subjects' dorsal region, at the level of T10 to S4, for 10 min, with the plate automatically turning off. Hot shower at controlled temperature was offered for 30 min. To verify the effect of LED on analgesia during labor, the following variables were assessed: (1) perception of pain, (2) fetal well-being assessed by cardiotocography or intermittent auscultation of fetal heart rate, (3) Apgar score at minutes 1 and 5 after birth, and (4) labor duration. Results: There was a statistically significant difference (p < 0.05) in pain reduction evidenced by a millimetric visual scale, before and after application on G1-LED (7.92 ± 1.78). Regarding the other variables, there was no statistical difference between the groups when comparing fetal well-being, Apgar score and labor duration. Conclusions: It is concluded that LED can be considered an alternative, since it caused pain reduction without changing other parameters during labor, compared with hot shower, a method included in hospital protocols, proving to be safe. Clinical Trial Registration number: NCT03496857."}],"keywords":["analgesia","childbirth","light-emitting diode","phototherapy"]},{"pmid":"33757917","title_fr":"Prise en charge de l'atrophie vulvovaginale : traitements physiques (recommandations CNGOF et GEMVi)","type":"guideline","level":1,"pop":"adulte","ctx":["GSM","général"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Recommandations","key":true,"l1":"Recommandations françaises : les lasers vaginaux CO2 ou Er:YAG ne sont pas un traitement de première ligne de l'atrophie vulvovaginale (grade C) ; les données sur la PBM et les autres techniques physiques sont faibles.","l2":"Revue systématique (2014–2020) du Collège national des gynécologues et obstétriciens français et du Groupe d'étude sur la ménopause. Le laser CO2 n'a pas montré de supériorité sur les œstrogènes locaux ; des cas de sténose ou de douleur chronique sont rapportés.\n\nLa PBM est citée parmi les alternatives, sans preuve suffisante pour une recommandation.","l3":{"points":["Lasers ablatifs : pas en première ligne (grade C)."],"limites":["Antérieur aux essais de PBM de 2024–2026."],"pratique":"Référence française à citer ; à réévaluer avec les essais récents."},"topic":"gynecologie","title":"[Management of vulvovaginal atrophy: Physical therapies. Postmenopausal women management: CNGOF and GEMVi clinical practice guidelines].","journal":"Gynecologie, obstetrique, fertilite & senologie","journal_abbr":"Gynecol Obstet Fertil Senol","authors":["Maris E","Salerno J","Hédon B","et al."],"date":"2021-03-20","year":2021,"week":"2021-S11","doi":"10.1016/j.gofs.2021.03.021","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Practice Guideline","Systematic Review"],"abstract":[{"label":"INTRODUCTION","text":"For some patients, local hormonal or non-hormonal treatments for genitourinary syndrome of menopause (SGUM) are contraindicated or insufficiently effective. Different physical therapies such as vaginal laser therapy, radiofrequency therapy, photobiomodulation therapy and local injection of hyaluronic acid, autologous fat (lipofilling) and platelet rich plasma (PRP) have been proposed as alternatives."},{"label":"OBJECTIVE","text":"The objective of this review was to elaborate guidelines for clinical practice regarding the physical therapies proposed for management of vulvovaginal atrophy (AVV)."},{"label":"METHODS","text":"A systematic review of the literature on AVV management with physical therapies was conducted on Medline between January 2014 and December 2020."},{"label":"RESULTS","text":"Regarding vaginal laser therapy, there are few randomized controlled trials and no formal conclusions can be drawn. The fractional CO2 laser did not demonstrate its superiority over local estrogen therapy. The ERBIUM:YAG laser has not been studied in randomized controlled trials. The lack of follow-up on the vaginal laser and the series of cases reporting risks of vaginal stenosis or chronic pain do not encourage recommending it as a first-line treatment. The literature concerning other physical treatments of AVV is weak concerning the genital area."},{"label":"CONCLUSION","text":"CO2 or ERBIUM:YAG vaginal lasers are not the first-line treatment for AVV (grade C). In patients with a contraindication to local hormonal treatments, treatment with vaginal CO2 laser or ERBIUM:YAG may be considered after information about the risks (burn, stenosis, pain) (expert opinion). The other physical treatments of SGUM have to be evaluated."}],"keywords":["Atrophie vulvovaginale","Genitourinary syndrome of menopause","Laser vaginal","Low-level light therapy","Photobiomodulation","Photothérapie de faible intensité","Radiofrequency","Radiofréquence","Syndrome génito-urinaire de la ménopause","Sécheresse vaginale"]},{"pmid":"32868711","title_fr":"PBM contre la douleur ou le traumatisme du mamelon chez la femme allaitante : protocole de revue systématique","type":"protocol","level":0,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"—","theme":"Allaitement","l1":"Protocole de revue JBI sur la PBM des lésions du mamelon.","l2":"Critères : douleur, cicatrisation, allaitement exclusif, qualité de vie, satisfaction.","l3":{"points":["Méthode JBI."],"limites":["Protocole."],"pratique":"—"},"topic":"gynecologie","title":"Effectiveness of photobiomodulation therapy for nipple pain or nipple trauma in lactating women: a systematic review protocol.","journal":"JBI evidence synthesis","journal_abbr":"JBI Evid Synth","authors":["Cirico MOV","Shimoda GT","Silva IA","et al."],"date":"2020-09-02","year":2020,"week":"2020-S36","doi":"10.11124/JBISRIR-D-19-00371","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"The objective of this protocol is to evaluate the effectiveness of photobiomodulation therapy for the treatment of nipple pain or nipple trauma in women during the breastfeeding period."},{"label":"INTRODUCTION","text":"One approach that has been reported on the management of nipple pain or nipple trauma in lactating women is the use photobiomodulation therapy to heal the injury or to decrease pain intensity. However, studies have achieved different results, due to variations in the treatment protocol, such as the source of light used, the application mode, the irradiation, or the light dose parameters, leading to varying outcomes."},{"label":"INCLUSION CRITERIA","text":"This review will consider studies that evaluate photobiomodulation therapy for the treatment of nipple pain or nipple trauma in lactating women in the postpartum period that compare the intervention to standard care, placebo, or other type of treatment. The following outcomes will be considered: intensity of nipple pain, healing of nipple trauma, exclusive breastfeeding rate, quality of life, and satisfaction of the women with treatment. There will be no publication time limit, and studies published in any language will be considered for inclusion."},{"label":"METHODS","text":"This review will be conducted in accordance with JBI methodology for systematic reviews of effectiveness. The search strategy will search both published and unpublished studies, and the process of study selection, critical appraisal, data extraction, and data synthesis will be performed in accordance to the JBI approach."},{"label":"SYSTEMATIC REVIEW REGISTRATION NUMBER","text":"PROSPERO CRD42019147401."}],"keywords":[]},{"pmid":"32419791","title_fr":"La laser-acupuncture soulage l'hyperactivité vésicale chez la femme : essai pilote en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["GSM"],"aim":"traitement","mode":["laser"],"nm":[],"n":30,"effect":"favorable","theme":"Incontinence urinaire","l1":"Chez 30 femmes, 9 séances de laser-acupuncture réduisent le score d'hyperactivité vésicale de 3 à 4,6 points par rapport au témoin.","l2":"Essai taïwanais, sept points d'acupuncture, 3 fois par semaine pendant 3 semaines.","l3":{"points":["OABSS −3,13 à −4,60 (p ≤ 0,001)."],"limites":["Pilote."],"pratique":"—"},"topic":"gynecologie","title":"Laser Acupuncture Alleviates Symptoms and Improves Quality of Life in Women with Overactive Bladder: A Double-Blind, Pilot Randomized Controlled Trial.","journal":"Evidence-based complementary and alternative medicine : eCAM","journal_abbr":"Evid Based Complement Alternat Med","authors":["Chang YW","Lo TS","Chang HN","et al."],"date":"2020-04-25","year":2020,"week":"2020-S17","doi":"10.1155/2020/1705964","pmcid":"PMC7201846","license":"cc by","oa":true,"pdf":"pdfs/32419791.pdf","cited_by":7,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"The aim of this study was to investigate the clinical efficacy of laser acupuncture for the treatment of women with overactive bladder (OAB) in Taiwan."},{"label":"METHODS","text":"A double-blind randomized controlled trial was conducted on female patients with OAB symptoms referred from gynecologists, and subjects were divided into two groups using blocked randomization. LaserPan (RJ-Laser, Germany) was applied to seven selected acupuncture points. The subjects received laser acupuncture 3 times per week for 3 weeks, 9 sessions in total. Basic patient data, Overactive Bladder Symptom Score (OABSS), Incontinence Impact Questionnaire (IIQ-7), and Urogenital Distress Inventory (UDI-6) scores were recorded prior to first treatment and at the end of 3rd, 6th, and 9th treatments."},{"label":"RESULTS","text":"Thirty patients were enrolled, and twenty-seven patients completed all treatments in this study. The OABSS total score of the experimental group decreased significantly by 3.13 (p ≤ 0.001), 4.60 (p ≤ 0.001), and 3.79 (p ≤ 0.001) after 3rd, 6th, and 9th treatments, respectively, compared with that of the control group. The IIQ-7 score declined significantly from baseline by 4.57 (p=0.003) and 3.63 (p=0.023) after 3rd and 6th treatments, respectively, compared with that of the control group. Similarly, the UDI-6 score of the experimental group exhibited a significant decrease from baseline by 1.90 (p=0.042) and 2.25 (p=0.025) after 6th and 9th interventions, respectively, compared with that of the control group."},{"label":"CONCLUSIONS","text":"This study demonstrates that laser acupuncture can alleviate OAB symptoms and improve quality of life. This noninvasive device could be an effective therapy for women with OAB."}],"keywords":[]},{"pmid":"31030379","title_fr":"Une seule irradiation de laser basse énergie contre la douleur des mamelons : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["obstétrique"],"aim":"traitement","mode":["laser"],"nm":[660],"n":80,"effect":"neutre","theme":"Allaitement","l1":"Chez 80 femmes allaitantes (São Paulo), une séance de laser 660 nm ne réduit pas plus la douleur des mamelons que le placebo ; 31 % ressentent des picotements.","l2":"Essai en double aveugle : 2 J, 66,7 J/cm², 20 s. La douleur baisse d'environ 1 point dans les deux groupes. Publié en ligne en 2019, dans le numéro de 2020.","l3":{"points":["Effets secondaires : picotements (10/36), piqûres (2/36)."],"limites":["Séance unique."],"pratique":"Une seule séance ne suffit pas ; les essais positifs utilisent plusieurs séances."},"topic":"gynecologie","title":"The effect of a single irradiation of low-level laser on nipple pain in breastfeeding women: a randomized controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Camargo BTS","Coca KP","Amir LH","et al."],"date":"2020-02-01","year":2020,"week":"2020-S05","doi":"10.1007/s10103-019-02786-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":15,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Photobiomodulation with low-level laser therapy (PBM-LLLT) has been introduced as a new tool to relieve nipple pain and repair nipple damage in breastfeeding women; however, evidence is needed to assess its effectiveness. The aim was to evaluate the effect of a single application of PBM-LLLT for breastfeeding women with nipple pain and damage; side effects were also collected. We conducted a randomized double-blinded controlled trial with women with nipple damage who were exclusively breastfeeding and rooming-in at Amparo Maternal maternity service, São Paulo, Brazil (May 2016 to May 2017). Women were randomly assigned into laser (n = 40) or control group (n = 40). Intervention was a single irradiation (660 nm, 100 mW, 2 J, 66.66 J/cm2, 3.3 W/cm2, 20 s of irradiation, punctual, and continuous mode) applied directly. Women reported pain levels at recruitment (before and immediately after irradiation), 6 and 24 h after the treatment. Pain level during a breastfeed was assessed using the Visual Analogue Scale (0 to 10). The primary outcome was the level of nipple pain immediately after the laser irradiation. Data were analyzed using hierarchical model and Wald test. At baseline, pain levels were similar (mean of 7.4 in laser group and 7.1 in control group). Women's perception of pain reduced approximately one point in both groups. Thirty-one percent of participants in the laser group (11/36) reported secondary effects, such as tingling (10/36) and pricking (2/36). The laser protocol of a single application was not effective in reducing pain in women with damaged nipples. Tingling sensation may be experienced by women receiving laser treatment for nipple damage."}],"keywords":["Breastfeeding","Clinical trial","Low-level laser therapy","Nipple","Pain","Postpartum"]},{"pmid":"31928249","title_fr":"Laser He-Ne avant transfert d'embryon congelé chez des femmes en échecs d'implantation répétés","type":"nrct","level":3,"pop":"adulte","ctx":["fertilité"],"aim":"traitement","mode":["laser"],"nm":[632.8],"n":60,"effect":"neutre","theme":"Fertilité","l1":"Chez 60 femmes en échecs d'implantation répétés, le laser He-Ne avant transfert donne des taux de grossesse un peu plus élevés (37,9 % contre 35,5 %), différence non significative.","l2":"Essai contrôlé non randomisé (choix des patientes). Naissances vivantes 27,6 % contre 25,8 % ; fausses couches 18,2 % contre 27,3 %.","l3":{"points":["Aucune complication."],"limites":["Non randomisé, effectif faible."],"pratique":"—"},"topic":"gynecologie","title":"Laser irradiation pretreatment improves endometrial preparation of frozen-thawed embryo transfer in recurrent implantation failure patients.","journal":"Gynecological endocrinology : the official journal of the International Society of Gynecological Endocrinology","journal_abbr":"Gynecol Endocrinol","authors":["Tsai HW","Wang PH","Hsu PT","et al."],"date":"2020-01-13","year":2020,"week":"2020-S03","doi":"10.1080/09513590.2020.1712694","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Controlled Clinical Trial"],"abstract":[{"label":"","text":"Recurrent implantation failure (RIF) remains a clinical dilemma. Helium-Neon (He-Ne) laser irradiation has recently become more popular under certain clinical conditions. Given the unique therapeutic effects, we were interested in determining whether pretreatment with He-Ne laser irradiation prior to frozen-thawed embryo transfer (FET) would improve the microcirculation and cause the release of growth factors and cytokines, thus improving endometrial receptivity and the clinical pregnancy rates. Patients chose for themselves whether to proceed with (n = 29) or without (n = 31) pretreatment with He-Ne laser irradiation prior to FET. The clinical pregnancy rate (37.9%) and implantation rate (20.3%) were higher in the laser-treatment group than in the control group (35.5% and 15.9%, respectively, p = .844 and .518, respectively). The live birth rate was higher in the laser-treatment group (27.6% vs. 25.8%, respectively, p = .876) and the miscarriage rate was lower in the laser-treatment group (18.2% and 27.3%, respectively, p = .611). No side effects or complications from laser irradiation were encountered in patients who received the laser treatment. We concluded that pretreatment with He-Ne laser prior to FET may be an alternative choice for RIF-affected women; however, additional well-designed prospective studies are necessary to determine the precise clinical value of this treatment."}],"keywords":["He-Ne laser irradiation","frozen-thawed embryo transfer","pregnancy","recurrent implantation failure"]},{"pmid":"31900692","title_fr":"Lumière bleue contre la vaginite à Candida : comparaison de trois longueurs d'onde (in vitro)","type":"preclinical","level":5,"pop":"—","ctx":["vulve"],"aim":"traitement","mode":["LED"],"nm":[405,415,450],"n":null,"effect":"favorable","theme":"Infections vulvovaginales","l1":"In vitro, le 415 nm est la longueur d'onde la plus efficace contre Candida albicans avec le moins de dommages pour les cellules vaginales.","l2":"Comparaison 405, 415 et 450 nm à 50 mW/cm².","l3":{"points":["Survie des cellules épithéliales : 0,77 à 415 nm pour 80 % d'inhibition de Candida."],"limites":["In vitro."],"pratique":"Justifie le choix de 415 nm dans les essais cliniques."},"topic":"gynecologie","title":"Blue light therapy to treat candida vaginitis with comparisons of three wavelengths: an in vitro study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Wang T","Dong J","Yin H","et al."],"date":"2020-01-04","year":2020,"week":"2020-S01","doi":"10.1007/s10103-019-02928-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":25,"pub_types":["Comparative Study"],"abstract":[{"label":"","text":"Anti-fungal blue light (ABL) therapies have been widely studied to treat various microbial infections in the literature. The blue light with wavelengths ranging from 400 to 470 nm has been reported to be effective to inhibit various kinds of bacteria and fungi. The existing studies usually report the viability rates of the pathogens under the irradiation of the blue light with different dosage parameters. However, to the best of our knowledge, there is still no work especially focusing on studying the effect of ABL therapies on treating candida vaginitis, where it is important to study the viability of both the Candida albicans (C. albicans) and the human vaginal epithelial cells. It is the purpose of this work to conduct ABL experiments on both of these two cells, analyze the effects, and determine the best ABL wavelength out of three candidates, i.e., 405-nm, 415-nm, and 450-nm wavelength. The viability rates of the C. albicans and the human vaginal epithelial cells irradiated by the three blue LED light sources were measured, whose irradiance (power density) were all set to 50 mW/cm2. The dynamic viability models of the C. albicans and the epithelial cells were built based on the experimental data. Moreover, in this work, we also built a functional relationship between the viability of these two types of cells, by which we further compared the effects of the blue light irradiation on both the C. albicans and vaginal epithelial cells. The experimental data showed that when an approximately 80% inhibiting rate of the C. albicans was achieved, the survival rates of the epithelial cells were 0.6700, 0.7748, and 0.6027, respectively for the treatment by the 405-nm, 415-nm, and 450-nm wavelength light. On the other hand, by simulating the functional relationship between the viability of the two types of cells, the survival rates of the epithelial cells became 0.5783, 0.6898, and 0.1918 respectively using the 405-nm, 415-nm and 450-nm wavelength light, when the C. albicans was completely inhibited. Therefore, both the experimental data and the model simulation results have demonstrated that the 415-nm light has a more effective anti-fungal result with less damage to the epithelial cells than the 405-nm and 450-nm light."}],"keywords":["Anti-fungal blue light therapy","Candida albicans","Candida vaginitis","Dynamic viability model","Photobiomodulation"]},{"pmid":"42969421","title_fr":"PBM extrabuccale versus intrabuccale pour prévenir la mucite chez l'enfant sous méthotrexate haute dose","type":"rct","level":2,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","extrabuccal","laser"],"nm":[660],"n":31,"effect":"favorable","theme":"Extra vs intrabuccal","key":true,"metric":{"kind":"rates","outcome":"Mucite cumulée (OMS)","a_label":"Extrabuccale","a":31.6,"b_label":"Intrabuccale","b":59.5},"l1":"Chez 31 enfants (75 cures de méthotrexate haute dose), la PBM extrabuccale à 660 nm a fait moins de mucites que la PBM intrabuccale (31,6 % contre 59,5 %), en moins de temps et sans effet indésirable.","l2":"Essai randomisé ouvert brésilien : chaque cure de méthotrexate haute dose était tirée au sort entre PBM intrabuccale et extrabuccale (lumière rouge 660 nm), quotidienne de la veille de la perfusion jusqu'à la sortie. La mucite était cotée selon l'échelle OMS à J0, J3, J5 et J10.\n\nAprès ajustement sur les cures répétées chez un même enfant, le risque de mucite restait plus élevé avec la voie intrabuccale (RR 1,84 ; IC95 % 1,07–3,19). Douleur, pH salivaire et biochimie salivaire ne différaient pas. La voie extrabuccale était nettement plus rapide à appliquer. C'est un argument pratique fort en pédiatrie, où l'ouverture buccale prolongée est difficile.","l3":{"points":["Plan : randomisation par cure (75 épisodes) et non par patient, avec analyse tenant compte des épisodes répétés.","Intervention : PBM préventive quotidienne, 660 nm, débutée avant la perfusion de MTX-HD et poursuivie jusqu'à la sortie.","Résultat principal : mucite cumulée 22/37 (IO) contre 12/38 (EO) ; RR 1,84 (IC95 % 1,07–3,19 ; p = 0,029) en défaveur de l'intrabuccal.","Critères secondaires (douleur, pH, biochimie salivaire) : pas de différence.","Tolérance : aucun effet indésirable ; temps d'application bien plus court en extrabuccal."],"limites":["Essai ouvert, petit effectif (31 enfants).","Randomisation par épisode : un même enfant reçoit les deux modalités, ce qui crée des dépendances.","Résultat discordant avec l'essai de 155 enfants de la même thématique (équivalence), à lire ensemble."],"pratique":"Chez l'enfant sous MTX-HD, la PBM extrabuccale est au moins aussi efficace que l'intrabuccale et plus simple : elle peut être proposée en première intention."},"topic":"mucite-orale","title":"Extraoral Versus Intraoral Photobiomodulation for the Prevention of Oral Mucositis in Pediatric Patients Undergoing High-Dose Methotrexate Chemotherapy.","journal":"Special care in dentistry : official publication of the American Association of Hospital Dentists, the Academy of Dentistry for the Handicapped, and the American Society for Geriatric Dentistry","journal_abbr":"Spec Care Dentist","authors":["Sassi ML","Cardoso NG","Mobile RZ","et al."],"date":"2026-11-02","year":2026,"week":"2026-S45","doi":"10.1111/scd.70279","pmcid":"PMC13725932","license":"cc by","oa":true,"pdf":"pdfs/42969421.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"AIMS","text":"To compare intraoral (IO) and extraoral (EO) photobiomodulation therapy (PBMT) for preventing oral mucositis (OM) in pediatric patients receiving high-dose methotrexate (HD-MTX)."},{"label":"METHODS AND RESULTS","text":"This prospective, open-label, randomized clinical trial included 75 HD-MTX treatment episodes from 31 pediatric patients aged 1-18 years. Each episode was randomized to IO-PBMT or EO-PBMT with red light at 660 nm. Preventive PBMT was initiated before HD-MTX infusion and administered daily until discharge. OM was assessed at baseline and on days 3, 5, and 10 using the World Health Organization scale. Pain, salivary pH, and salivary biochemical profiles were secondary or exploratory outcomes. Cumulative OM occurred in 22/37 IO-PBMT episodes (59.5%) and 12/38 EO-PBMT episodes (31.6%). After accounting for repeated episodes within patients, OM risk was higher with IO-PBMT (risk ratio, 1.84; 95% CI, 1.07-3.19; p = 0.029). Pain scores, salivary pH, and biochemical profiles did not differ significantly between groups. EO-PBMT required substantially less application time, and no adverse effects were reported."},{"label":"CONCLUSION","text":"EO-PBMT was associated with lower cumulative OM occurrence, shorter application time, and good tolerability, supporting its use as a promising, less burdensome preventive strategy in pediatric oncology."}],"keywords":["methotrexate","oral mucositis","pediatric oncology","photobiomodulation therapy","preventive dentistry"]},{"pmid":"42931937","title_fr":"L'odynophagie, conséquence grave et oubliée de la mucite","type":"letter","level":0,"pop":"—","ctx":[],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Lettre à l'éditeur rappelant que la douleur à la déglutition liée à la mucite est sous-évaluée. Pas de résumé disponible sur PubMed.","l2":"Courrier publié dans Supportive Care in Cancer. Le titre indique un plaidoyer pour mieux évaluer et traiter l'odynophagie (douleur à la déglutition), souvent négligée face à la mucite buccale visible. Le sujet rejoint l'étude de 2026 sur la PBM haute puissance contre l'odynophagie.\n\nAucun résumé n'est indexé : le contenu exact n'a pas pu être analysé.","l3":{"points":["Type : correspondance, sans données originales indexées.","Lien thématique : PBM haute puissance et odynophagie (Oral Oncology, juin 2026)."],"limites":["Contenu non accessible depuis PubMed."],"pratique":"Penser à évaluer la douleur pharyngée et la déglutition, pas seulement la cavité buccale."},"topic":"mucite-orale","title":"Odynophagia: The forgotten serious consequence of mucositis.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Zadik Y","Cohen R","Finfter O","et al."],"date":"2026-10-26","year":2026,"week":"2026-S44","doi":"10.1007/s00520-026-11412-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":["Dysphagia","Esophagitis","G-tube","Gastrointestinal mucositis","Oral mucositis","Percutaneous endoscopic gastrostomy","Photobiomodulation","Swallowing Disorder"]},{"pmid":"42897331","title_fr":"Efficacité comparable de la PBM extrabuccale et intrabuccale pour prévenir la mucite sous méthotrexate haute dose en oncopédiatrie : essai randomisé en simple aveugle","type":"rct","level":2,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","extrabuccal","laser"],"nm":[660],"n":155,"effect":"neutre","theme":"Extra vs intrabuccal","key":true,"metric":{"kind":"rates","outcome":"Mucite (toute sévérité)","a_label":"Extrabuccale","a":30.5,"b_label":"Intrabuccale","b":41.1},"l1":"Sur 155 enfants sous méthotrexate haute dose, la PBM extrabuccale (30 s par séance) protège autant que l'intrabuccale (6 min) : 30,5 % contre 41,1 % de mucites, différence non significative.","l2":"Essai randomisé en simple aveugle, le plus grand de 2026 sur cette question. Les enfants (1 à 18 ans ; leucémie, lymphome ou ostéosarcome) recevaient une PBM préventive quotidienne de l'admission à la sortie, avec une dosimétrie équivalente (660 nm, 100 mW, 1 J par point) par voie intra- ou extrabuccale.\n\nLa mucite est survenue chez 35,5 % des enfants, sans différence entre voies (p = 0,168), ni pour la sévérité, la douleur, le pH salivaire ou la plaque. Les facteurs liés à une mucite plus sévère étaient l'âge et la dose de méthotrexate. La voie extrabuccale divise le temps d'application par plus de dix.","l3":{"points":["Population : 155 enfants (PBM-IO n = 73 ; PBM-EO n = 82), MTX-HD pour LAL, lymphome ou ostéosarcome.","Dosimétrie identique : 660 nm, 100 mW, 1 J/point ; 30 s/séance en EO contre environ 6 min en IO.","Évaluations J0, J3, J5, J10 : OMS, indice de plaque, douleur (EN).","Mucite : 41,1 % (IO) contre 30,5 % (EO), p = 0,168. Douleur médiane nulle à tous les temps.","Régression ordinale : âge (OR 1,14) et dose de MTX (OR 1,24) associés à la sévérité ; la modalité de PBM ne l'est pas."],"limites":["Simple aveugle seulement.","Pas de bras sans PBM : l'essai compare deux PBM, il ne prouve pas l'efficacité de la PBM elle-même.","Essai d'équivalence non formellement annoncé comme tel dans le résumé."],"pratique":"La voie extrabuccale est une alternative crédible et beaucoup plus rapide chez l'enfant sous MTX-HD."},"topic":"mucite-orale","title":"Comparable efficacy of extraoral and intraoral photobiomodulation in preventing oral mucositis during high-dose methotrexate therapy in pediatric oncology: A single-blind randomized controlled trial.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Freitas IOP","Schuartz I","Renz GLK","et al."],"date":"2026-10-19","year":2026,"week":"2026-S43","doi":"10.1007/s00520-026-11372-9","pmcid":"PMC13680327","license":"cc by","oa":true,"pdf":"pdfs/42897331.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"PURPOSE","text":"This prospective randomized controlled clinical study compared intraoral (IO) and extraoral (EO) photobiomodulation (PBM) for the prevention of chemotherapy-induced oral mucositis (OM) in pediatric oncology patients."},{"label":"METHODS","text":"A total of 155 patients (1-18 years), receiving high-dose methotrexate (HDMTX) for leukemia, lymphoma, or osteosarcoma, were randomized to PBM-IO (n = 73) or PBM-EO (n = 82). Preventive PBM was administered daily from hospital admission through discharge. Both protocols used red light with equivalent dosimetry (660 nm, 100 mW, 1 J per point). PBM-EO required 30 s/session, whereas PBM-IO required approximately 6 min, excluding patient handling time. OM occurrence, severity (WHO scale), plaque index, and pain (numeric rating scale) were assessed on days 0, 3, 5, and 10 after HDMTX infusion."},{"label":"RESULTS","text":"The overall OM occurrence was 35.5%, with no significant difference between PBM-IO (41.1%) and PBM-EO (30.5%) groups (p = 0.168). No statistically significant differences were observed between groups for OM severity, pain, salivary pH, or plaque index at any time point (p > 0.05). Multivariable ordinal logistic regression demonstrated that PBM modality was not independently associated with OM severity. As expected, increasing age (OR = 1.14; 95% CI: 1.04-1.25; p = 0.004) and higher HDMTX dose (OR = 1.24; 95% CI: 1.03-1.49; p = 0.021) were significantly associated with greater OM severity. Median pain scores remained 0 at all assessment points in both groups."},{"label":"CONCLUSION","text":"Extraoral PBM demonstrated comparable effectiveness to intraoral for OM prevention in pediatric patients undergoing HDMTX chemotherapy, while reducing application time."}],"keywords":["Low-level light therapy","Medical oncology","Methotrexate","Oral medicine","Oral mucositis","Pediatrics"]},{"pmid":"42878931","title_fr":"Revue parapluie de la photobiomodulation : les preuves à travers les indications cliniques","type":"umbrella","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"Synthèse de 100 revues systématiques sur la PBM toutes indications : la mucite et les complications oncologiques ont la plus forte proportion de conclusions favorables, mais 90 % des revues sont de confiance faible ou très faible.","l2":"Cette revue de revues (recherche jusqu'en février 2026) couvre 790 études primaires. Les pathologies bucco-dentaires dominent (53 revues), devant les troubles musculosquelettiques (22) et les complications oncologiques (8). 62 revues concluent en faveur de la PBM, 34 de façon neutre ou mitigée.\n\nLes complications oncologiques, dont la mucite, concentrent la plus forte part de conclusions favorables. La qualité méthodologique est cependant faible : 60 % des revues sont jugées de confiance « critiquement faible » selon AMSTAR 2, et 57 % ne disent rien des effets indésirables. Les auteurs refusent d'en tirer des conclusions fermes sur la sécurité.","l3":{"points":["100 revues systématiques, 1 164 occurrences d'études primaires, 790 études uniques.","AMSTAR 2 : 30 % confiance faible, 60 % critiquement faible.","Effets indésirables : 11 revues en signalent, 32 n'en rapportent aucun, 57 ne renseignent pas.","Indication la plus favorable : complications oncologiques (mucite en tête)."],"limites":["Analyse descriptive du sens des conclusions, sans méta-analyse des effets.","Hétérogénéité majeure des paramètres de traitement."],"pratique":"La mucite reste l'indication la mieux étayée de la PBM, mais la qualité des revues publiées est médiocre : privilégier les méta-analyses récentes de bonne qualité et les recommandations MASCC/ISOO."},"topic":"mucite-orale","title":"Umbrella review of low-level light therapy: evidence across clinical conditions.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Song E","Ang L","Yim MH","et al."],"date":"2026-10-15","year":2026,"week":"2026-S42","doi":"10.1007/s10103-026-05064-3","pmcid":"PMC13672599","license":"cc by-nc-nd","oa":false,"pdf":"pdfs/42878931.pdf","cited_by":0,"pub_types":["Systematic Review","Review"],"abstract":[{"label":"","text":"Low-level light therapy (LLLT) and photobiomodulation (PBM) have been studied in diverse clinical fields. Although numerous systematic reviews have been published, their findings are fragmented and inconsistent. This umbrella review of systematic reviews aimed to synthesize the evidence on the effectiveness and safety of LLLT across various clinical conditions. PubMed, Embase, Cochrane Library, and Web of Science databases were searched from inception to February 24, 2026. Eligible studies were systematic reviews or meta-analyses of LLLT in humans. Data on clinical conditions, intervention characteristics, overall direction of conclusions, and adverse events were extracted. Methodological quality was assessed using AMSTAR 2. A total of 100 systematic reviews were included, representing 1,164 primary-study occurrences and 790 unique eligible primary studies. Oral and dental conditions accounted for the largest evidence base (53 reviews), followed by musculoskeletal disorders (22 reviews), oncology-related complications (8 reviews), and wound and lymphatic conditions (8 reviews). Overall, 62 reviews reached conclusions favoring the evaluated intervention, 34 reported neutral or mixed conclusions, and 4 had unclear conclusions. The highest proportion of favorable conclusions was observed for oncology-related complications. Of the 100 reviews, 11 reported one or more adverse events or side effects, 32 explicitly reported no adverse events, and 57 did not provide adverse-event information. Most reviews received low (30.0%) or critically low (60.0%) overall confidence ratings using AMSTAR 2. The review literature suggests potential clinical benefit of LLLT in selected indications, particularly oncology-related complications such as oral mucositis. However, these descriptive patterns do not establish treatment efficacy or the certainty of the underlying evidence. Heterogeneity in treatment parameters, generally low methodological confidence, and incomplete adverse-event reporting limit interpretation and preclude firm conclusions about safety."}],"keywords":["Light therapy","Low–level light therapy","Photobiomodulation","Systematic review","Umbrella review"]},{"pmid":"42941485","title_fr":"PBM chez les patients ORL sous chimioradiothérapie : rôle dans la prévention des toxicités (données de vie réelle)","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","extrabuccal","LED"],"nm":[620,650,820],"n":117,"effect":"favorable","theme":"Vie réelle","metric":{"kind":"rates","outcome":"Odynophagie grade 2–3 en fin de traitement","a_label":"≥ 10 séances","a":16.7,"b_label":"< 10 séances","b":42.2},"l1":"Cohorte rétrospective italienne de 117 patients ORL : ceux ayant reçu au moins 10 séances de PBM ont eu moins d'odynophagie (16,7 % contre 42,2 %) et de dysphagie persistante, sans effet sur la survie.","l2":"Analyse rétrospective (2021–2024) de patients traités par chimioradiothérapie avec PBM concomitante (620/820 nm ou 650 nm, 3–12 J/cm²). En fin de traitement, 38,5 % avaient une mucite de grade 2–3 et 25,6 % une radiodermite de grade 2–3, des taux inférieurs aux séries historiques sans PBM.\n\nLa comparaison interne selon l'exposition (≥ 10 contre < 10 séances) montre moins d'odynophagie et de dysphagie persistante avec davantage de séances. La PBM n'était associée ni à la perte de poids, ni à la survie sans progression, ni à la survie globale, un point rassurant pour la sécurité oncologique.","l3":{"points":["117 patients, suivi médian de 16 mois, toxicités cotées CTCAE v5.","Mucite G2–3 : 38,5 % ; radiodermite G2–3 : 25,6 %.","≥ 10 séances (72 patients) : odynophagie G2–3 16,7 % contre 42,2 % (p = 0,005) ; dysphagie persistante 12,5 % contre 33,3 % (p = 0,009).","Aucune association avec la survie sans progression ni la survie globale."],"limites":["Rétrospectif, sans groupe témoin sans PBM.","Biais probable : les patients qui reçoivent plus de séances sont aussi ceux qui tolèrent mieux le traitement.","Protocoles PBM variables."],"pratique":"Signal de vie réelle en faveur d'un nombre suffisant de séances (au moins 10) pendant la chimioradiothérapie ORL ; à confirmer par essai randomisé."},"topic":"mucite-orale","title":"Photobiomodulation Therapy in Head and Neck Cancer Patients Undergoing Chemoradiotherapy: Role in Toxicities Prevention.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Rotondi M","Sun R","El-Masri H","et al."],"date":"2026-10-15","year":2026,"week":"2026-S42","doi":"10.3390/jcm15207968","pmcid":"PMC13705853","license":"cc by","oa":true,"pdf":"pdfs/42941485.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Background: Chemoradiotherapy (CRT) for head and neck cancer (HNC) is frequently associated with severe acute toxicities that compromise treatment adherence and quality of life. This study evaluated the effectiveness of photobiomodulation (PBM) in reducing CRT-induced toxicities in a real-world cohort. Methods: Between May 2021 and July 2024, we retrospectively analyzed 117 HNC patients treated with definitive or adjuvant CRT and concomitant PBM: a non-invasive application of red or near-infrared light to cutaneous and mucosal surfaces to modulate inflammatory responses, using 620/820 nm or 650 nm devices, with irradiation times of 2-12 min and energy densities of 3-12 J/cm2 according to the treatment protocol. Toxicities were graded according to CTCAE v 5.0 at baseline, during treatment, at treatment completion, and throughout follow-up. Associations with toxicity were assessed with logistic regression for repeated measurements (generalized estimating equations). Patients were stratified according to PBM exposure (<10 vs. ≥10 sessions). Results: Median follow-up was 16 months. At treatment completion, grade 2-3 oral mucositis and radiodermatitis occurred in 38.5% and 25.6% of patients, respectively, both lower than rates reported in historical cohorts without PBM. Patients receiving ≥10 PBM sessions (72 pts) experienced significantly lower rates of grade 2-3 odynophagia at treatment completion (16.7% vs. 42.2%, p = 0.005) and persistent dysphagia at the last follow-up (12.5% vs. 33.3%, p = 0.009). PBM exposure was not associated with significant differences in weight loss, progression-free survival, or overall survival. Conclusions: This study provides real-world data on toxicity outcomes among HNC patients receiving PBM, with lower rates of selected toxicities observed among patients receiving ≥10 PBM sessions. Although the retrospective design and lack of a control group limit causal inference, these findings provide a strong rationale for prospective randomized trials to define the optimal PBM schedule and validate its clinical impact."}],"keywords":["chemotherapy","head and neck cancer","low level laser therapy","orofacial complications","photobiomodulation","radiotherapy","supportive care","toxicities"]},{"pmid":"42860472","title_fr":"Qualité de rédaction et « spin » dans les résumés d'essais randomisés sur la mucite","type":"methodo","level":0,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Méthodologie","l1":"Sur 112 essais randomisés sur la mucite (dont des essais de PBM), les résumés sont mal rédigés selon CONSORT et presque tous ceux analysés présentent un « spin », une présentation trop flatteuse des résultats.","l2":"Étude de méta-recherche sur quatre interventions (benzydamine, PBM, cryothérapie, palifermine), essais publiés jusqu'en septembre 2024. Le score CONSORT pour les résumés est globalement bas : le plan d'étude et les critères de jugement sont souvent mal décrits.\n\nSeize essais ont pu être analysés pour le spin ; deux seulement en étaient exempts. La qualité de rédaction augmente avec la longueur du résumé et avec un financement industriel déclaré. Pour la veille, la leçon est claire : lire les résultats chiffrés et pas seulement la conclusion des résumés.","l3":{"points":["112 ECR analysés avec la grille CONSORT-A ; 16 analysés pour le spin, 14 en présentent.","Corrélation qualité/longueur du résumé : r = 0,35.","Spin inversement corrélé au score Altmetric (r = −0,65)."],"limites":["Résultats non détaillés par intervention dans le résumé.","Faible nombre d'essais évalués pour le spin."],"pratique":"Ne pas se fier aux conclusions des résumés : vérifier critère principal, effectifs et intervalles de confiance. C'est le rôle du niveau 3 de ce site."},"topic":"mucite-orale","title":"Reporting quality and spin in abstracts of randomized clinical trials related to oral mucositis.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Al-Abedalla K","Hamdan AA","Alsaghir Q","et al."],"date":"2026-10-11","year":2026,"week":"2026-S41","doi":"10.1007/s00520-026-11329-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"Oral mucositis is a common debilitating side effect of cancer therapy. Numerous randomized controlled trials (RCTs) have examined interventions for this complication. Accurate reporting of RCT results in abstracts is crucial to treatment decisions. Spin undermines the integrity of the information presented and compromises evidence-based practice. This study evaluated the reporting quality of, and spin in, abstracts of RCTs of four interventions for oral mucositis: benzydamine, photobiomodulation therapy, oral cryotherapy, and keratinocyte growth factor, and assessed factors that can affect reporting quality and spin."},{"label":"METHODS","text":"PubMed, Cochrane, and Scopus were systematically searched for RCTs related to oral mucositis treatments published until September 2024. The CONSORT for Abstracts (CONSORT-A) and spin checklists were then applied to assess reporting quality of and spin in their abstracts."},{"label":"RESULTS","text":"Among 112 RCTs that were analyzed, the overall CONSORT-A score for reporting quality was low, and key elements such as study design and outcome reporting were frequently not reported. Only 16 of these RCTs were analyzed for spin and only two RCTs had no spin. Higher reporting quality was significantly correlated with greater abstract word counts (r = 0.35; p < 0.001) and pharmaceutical funding when compared with articles that did not report funding (p = 0.015). Spin was negatively correlated with the Altmetric attention score (r =  - 0.652; p = 0.006)."},{"label":"CONCLUSIONS","text":"Abstracts of RCTs on oral mucositis interventions frequently did not meet the reporting standards defined by the CONSORT-A checklist. Enhanced adherence to reporting guidelines is necessary to support evidence-based clinical practices."}],"keywords":["Abstracts","Cancer","Mucositis","Quality of reporting","Randomized controlled trials as topic","Spin","Supportive care"]},{"pmid":"42858922","title_fr":"Le microbiome oral dans la réponse biologique et clinique à la PBM en soins de support : revue critique","type":"review","level":5,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Mécanismes","l1":"Revue critique : rien ne prouve aujourd'hui que la PBM agisse via le microbiome oral. L'hypothèse la plus solide reste un effet sur l'hôte (épithélium, inflammation, réparation), qui modifie secondairement l'écologie microbienne.","l2":"Les auteurs classent les preuves en quatre niveaux : cliniques directes, cliniques indirectes, microbiologiques expérimentales, hypothèses. Les données cliniques directes sont rares et contradictoires : un pilote de quatre patients a décrit des changements du microbiome, une série ORL de 2023 n'en a pas trouvé malgré l'amélioration de la mucite.\n\nIls proposent quatre rôles possibles du microbiome (médiateur, modificateur, biomarqueur ou simple conséquence) et listent les exigences des futures études : prélèvements répétés, dosimétrie complète, contrôle des antibiotiques, de l'hygiène et de l'alimentation. Ils rappellent de ne pas confondre PBM et thérapie photodynamique antimicrobienne.","l3":{"points":["Modèle « l'hôte d'abord » : la PBM agit sur l'intégrité épithéliale, la signalisation redox et inflammatoire, la cicatrisation.","Effets photobiologiques directs sur les bactéries plausibles mais très dépendants des paramètres.","Le microbiome est à considérer comme critère de recherche, pas comme mécanisme établi."],"limites":["Revue narrative, sans méthode systématique."],"pratique":"Aucune conséquence clinique directe ; utile pour interpréter les études sur microbiome et PBM."},"topic":"mucite-orale","title":"The oral microbiome in the biological and clinical response to photobiomodulation during cancer supportive care: a critical mechanistic and translational review.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Eftekharian S","Rastkar S"],"date":"2026-10-10","year":2026,"week":"2026-S41","doi":"10.1016/j.pdpdt.2026.105682","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Cancer therapy can disrupt the oral microbial ecosystem through mucosal injury, salivary dysfunction, immune suppression, antimicrobial exposure, dietary change, and altered oral hygiene. Photobiomodulation therapy (PBMT) is guideline-supported for prevention of oral mucositis in selected oncologic settings, but whether the oral microbiome contributes to PBMT response remains uncertain. This critical narrative review reframes the question from whether PBMT changes the oral microbiome to what role, if any, microbial ecology plays in the biological and clinical response to PBMT during cancer supportive care. Evidence is organized as direct clinical evidence, indirect clinical evidence, experimental microbial evidence, and mechanistic hypothesis. Direct clinical evidence is sparse and internally mixed: a four-patient uncontrolled pilot reported concurrent cytokine and microbiome shifts after PBMT, whereas a 2023 head-and-neck cancer case series reported clinical improvement in mucositis without significant pre-post changes in salivary bacterial community structure. The strongest current rationale therefore supports a host-first model in which PBMT modifies epithelial integrity, inflammatory and redox signaling, tissue repair, and possibly salivary physiology, thereby changing the ecological conditions experienced by oral microorganisms. Direct microbial photobiological effects remain plausible but are highly dependent on wavelength, irradiance, radiant exposure, oxygen availability, organism, and biofilm state, and should not be conflated with antimicrobial photodynamic therapy. We propose four non-equivalent roles for microbiome change: mediator, modifier, biomarker, or consequence of treatment response. Oral mucositis is the most informative clinical model, but causal interpretation requires longitudinal sampling, functional microbial assays, complete PBMT dosimetry, validated clinical and patient-reported outcomes, and rigorous control of antimicrobials, periodontal status, oral hygiene, diet, feeding support, and anticancer treatment. Microbiome modulation should currently be regarded as an emerging mechanistic hypothesis and research endpoint rather than an established mechanism of PBMT efficacy."}],"keywords":["Cancer supportive care","Dysbiosis","Microbial ecology","Oral microbiome","Oral mucositis","Photobiomodulation","Saliva","Translational research"]},{"pmid":"42776303","title_fr":"Acceptation et efficacité perçue de la PBM intrabuccale versus extrabuccale chez l'enfant","type":"survey","level":0,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","extrabuccal"],"nm":[],"n":32,"effect":"favorable","theme":"Extra vs intrabuccal","l1":"Les parents de 32 enfants ayant reçu les deux modalités préfèrent la PBM extrabuccale (65,6 %) : beaucoup moins d'inconfort (6,3 % contre 43,8 %), sans avoir à ouvrir la bouche.","l2":"Questionnaire mené dans un essai randomisé où chaque enfant a reçu, selon les cycles, une PBM intrabuccale puis extrabuccale. La préférence pour l'extrabuccal tient au confort et à l'absence d'ouverture buccale.\n\nLes parents attribuaient pourtant plus souvent un meilleur contrôle de la douleur à l'intrabuccal (34,4 % contre 12,5 %), une perception que ne confirment pas les données cliniques de l'essai. L'extrabuccal apparaît donc comme l'option la mieux acceptée en pédiatrie.","l3":{"points":["Inconfort : 43,8 % (IO) contre 6,3 % (EO), p = 0,001.","Préférence : 65,6 % EO, 34,4 % IO.","Perception d'un meilleur contrôle de la douleur : IO 34,4 %, EO 12,5 %."],"limites":["Données déclaratives des aidants, analyse descriptive."],"pratique":"Argument d'acceptabilité qui complète les deux essais pédiatriques de 2026 en faveur de l'extrabuccal."},"topic":"mucite-orale","title":"Acceptance and perceived efficacy of intraoral versus extraoral photobiomodulation for oral mucositis prevention in pediatric patients.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Freitas IOP","Renz GLK","Schuartz I","et al."],"date":"2026-09-23","year":2026,"week":"2026-S39","doi":"10.1007/s00520-026-11227-3","pmcid":"PMC13601188","license":"cc by","oa":true,"pdf":"pdfs/42776303.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"OBJECTIVE","text":"To compare acceptance, tolerability, and perceived efficacy of extraoral (EO) and intraoral (IO) photobiomodulation therapy (PBMT) for oral mucositis (OM) prevention in pediatric oncology patients."},{"label":"METHODS","text":"Caregivers of 32 pediatric patients undergoing chemotherapy completed a structured questionnaire after their children experienced both intraoral and extraoral PBMT for oral mucositis prevention during different chemotherapy cycles within a randomized clinical study. Device preference, discomfort, perceived pain control, and reasons for preference were descriptively analyzed."},{"label":"RESULTS","text":"EO-PBMT was preferred by 65.6% of respondents, whereas 34.4% preferred IO-PBMT. Preference for EO-PBMT was mainly associated with greater comfort and avoidance of mouth opening. Discomfort was reported by 43.8% during IO-PBM and by 6.3% during EO-PBMT, with a statistically significant difference between the modalities (p = 0.001). IO-PBMT was more often perceived to provide better pain control (34.4%), whereas 12.5% favored EO-PBMT."},{"label":"CONCLUSION","text":"EO-PBMT demonstrated greater caregiver acceptance and lower treatment-related discomfort than IO-PBMT. Although caregivers more frequently perceived IO-PBMT as providing better pain control, these subjective perceptions did not correspond to differences in the clinical occurrence or severity of OM between treatment modalities. EO-PBMT therefore represents a feasible and well-accepted approach for supportive care in pediatric oncology."}],"keywords":["Low-level light therapy","Medical oncology","Oral mucositis","Pediatric assistants"]},{"pmid":"42659420","title_fr":"La PBM dans la prise en charge des lésions buccales : approche ciblée fondée sur les preuves","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue brésilienne des usages de la PBM en bouche (douleurs, mucite, hyposialie, aphtes, lichen, herpès) : bénéfices réels mais très dépendants de la dosimétrie.","l2":"Revue narrative qui couvre les mécanismes (anti-inflammatoire, antalgique, réparateur), les interactions lumière-tissu et les paramètres d'irradiation. La mucite et l'hyposialie liées aux traitements du cancer figurent parmi les indications les plus étudiées.\n\nLes auteurs insistent sur l'adaptation des paramètres à chaque cible tissulaire et appellent à standardiser les protocoles.","l3":{"points":["Quatre familles d'indications : douleurs orofaciales, oncologie (mucite, hyposialie), maladies immunitaires, infections virales.","Effets immédiats et cumulatifs au fil des séances."],"limites":["Revue narrative, pas de méthode systématique."],"pratique":"Bonne porte d'entrée pédagogique sur la dosimétrie, sans donnée nouvelle."},"topic":"mucite-orale","title":"Photobiomodulation in the management of oral lesions: a targeted, evidence-based approach.","journal":"Brazilian oral research","journal_abbr":"Braz Oral Res","authors":["Koth VS","Gabriel AF","Deckmann I","et al."],"date":"2026-08-24","year":2026,"week":"2026-S35","doi":"10.1590/1807-3107bor-2026.vol40suppl1059","pmcid":"PMC13508680","license":"cc by","oa":true,"pdf":"pdfs/42659420.pdf","cited_by":1,"pub_types":["Review"],"abstract":[{"label":"","text":"This review synthesizes current literature on laser applications in dentistry, with particular emphasis on the biological mechanisms of photobiomodulation (PBM), dosimetric considerations, tissue interactions, and the clinical management of the most prevalent oral lesions. The oral disorders most frequently investigated for the therapeutic use of PBM were: a) oral pain conditions: trigeminal neuralgia, temporomandibular disorders, and burning mouth syndrome; b) oncology-related conditions: oral mucositis and hyposalivation; c) immune-mediated disorders: recurrent aphthous stomatitis and oral lichen planus; and d) viral infections: herpes labialis. A wide range of laser parameters has shown clinical benefits in the treatment of these disorders. These outcomes are attributed to the anti-inflammatory, analgesic, and tissue repair effects of PBM, which may occur immediately and cumulatively over repeated sessions. PBM therapy is a valuable therapeutic resource in contemporary dentistry and may be successfully applied in a wide range of clinical conditions. Clinical effectiveness of PBM depends on appropriate dosimetry and irradiation parameters according to the biological characteristics of each condition and therapeutic target. Therefore further well-designed randomized clinical trials and protocol standardization are still required to strengthen clinical recommendations and optimize reproducibility."}],"keywords":[]},{"pmid":"42629521","title_fr":"PBM pour limiter dysgueusie et xérostomie sous talquetamab dans le myélome : quatre cas","type":"cases","level":4,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":["laser"],"nm":[660,808],"n":4,"effect":"—","theme":"Nouvelles indications","l1":"Quatre patients atteints de myélome traités par talquetamab ont reçu une PBM bien tolérée ; aucun n'a eu de mucite, mais la série ne permet pas de conclure sur la dysgueusie ou la sécheresse buccale.","l2":"Le talquetamab, anticorps bispécifique anti-GPRC5D, provoque fréquemment des troubles du goût et une xérostomie. Cette série décrit une PBM bi-longueur d'onde (660/808 nm) adaptée aux symptômes.\n\nTous les patients ont développé une dysgueusie et une xérostomie. Aucune mucite ni douleur significative, aucun effet indésirable de la PBM, aucun arrêt du talquetamab pour toxicité buccale. Les auteurs insistent : c'est une étude de faisabilité, pas d'efficacité.","l3":{"points":["Dysgueusie chez les 4 patients (2 hypogueusies grade 1, 2 agueusies grade 2).","Xérostomie chez les 4, non quantifiée par sialométrie.","Soins de support associés (bain de bouche au xylitol, substituts salivaires)."],"limites":["4 cas, sans témoin, évaluations non standardisées."],"pratique":"Piste à surveiller pour les nouvelles toxicités buccales des immunothérapies ; pas de recommandation possible."},"topic":"mucite-orale","title":"Photobiomodulation to minimize talquetamab-associated dysgeusia and xerostomia in multiple myeloma: a brief report of four cases.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Ferreira MH","de Paula Eduardo F","Menti LD","et al."],"date":"2026-08-21","year":2026,"week":"2026-S34","doi":"10.1007/s00520-026-11133-8","pmcid":"PMC13498624","license":"cc by","oa":true,"pdf":"pdfs/42629521.pdf","cited_by":0,"pub_types":["Case Reports"],"abstract":[{"label":"BACKGROUND","text":"Talquetamab, a GPRC5D-targeting bispecific antibody, produces high response rates in relapsed/refractory multiple myeloma (RRMM) but is frequently associated with oral adverse effects, most commonly dysgeusia and xerostomia, which can impair nutrition and quality of life. No evidence-based supportive-care intervention has been established for these effects."},{"label":"METHODS","text":"We describe four adults with RRMM who received photobiomodulation (PBM) concomitantly with talquetamab, using a dual-wavelength (660/808 nm) protocol individualized to symptom evolution and patient availability. Dysgeusia and xerostomia were assessed prospectively at each session through structured clinical interview and oral examination, with severity graded for each patient; no formal psychophysical gustatory testing or sialometry was performed. This descriptive, uncontrolled case series was designed to report the feasibility and tolerability of PBM rather than its efficacy."},{"label":"RESULTS","text":"All four patients developed dysgeusia during talquetamab treatment. Two had grade 1, intermittent hypogeusia; two had grade 2 dysgeusia with complete taste loss (ageusia). No patient developed oral mucositis or clinically significant oral pain. All four patients reported xerostomia, with reduced salivary film and whitish, viscous saliva on examination; salivary flow was not measured quantitatively. All patients also received xylitol-based mouthwash and saliva substitutes from the start of talquetamab as concomitant standard supportive care. PBM was well tolerated, with no PBM-related adverse events, and no patient discontinued talquetamab because of oral toxicity."},{"label":"CONCLUSIONS","text":"This series demonstrates the feasibility and tolerability of PBM delivered alongside talquetamab in four patients. Given the small, uncontrolled sample and concurrent supportive interventions, no conclusion can be drawn regarding the efficacy of PBM for talquetamab-associated dysgeusia or xerostomia. Controlled studies with objective, validated outcome measures are needed."}],"keywords":["Dysgeusia","Multiple myeloma","Photobiomodulation","Supportive care","Talquetamab","Xerostomia"]},{"pmid":"42525285","title_fr":"PBM transcutanée (808 nm) versus intrabuccale (660 nm) pour prévenir la mucite en ORL : protocole d'essai randomisé","type":"protocol","level":0,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","extrabuccal","laser"],"nm":[660,808],"n":54,"effect":"—","theme":"Extra vs intrabuccal","l1":"Protocole d'un essai de non-infériorité (54 patients ORL) qui comparera une PBM transcutanée infrarouge à la PBM intrabuccale rouge standard. Pas encore de résultats.","l2":"Les patients irradiés (60–70 Gy) recevront trois séances par semaine, soit en intrabuccal (660 nm, 100 mW, 1 J/point, 44 points, 10 s), soit en transcutané (808 nm, 100 mW, 1 J/point, 32 points). Le critère principal est la sévérité OMS de la mucite.\n\nLe transcutané devrait réduire le temps de séance (80 s contre 440 s) et convenir aux patients avec trismus ou douleur buccale sévère.","l3":{"points":["Critères secondaires : CTCAE, douleur (EN), surface ulcérée sur photos, interruptions de traitement, recours imprévus aux soins.","Fluence : 10,2 J/cm² en intrabuccal ; 34,5 et 4,3 J/cm² en transcutané (points central et latéraux)."],"limites":["Pilote, effectif modeste pour une non-infériorité."],"pratique":"À suivre : résultats attendus pour trancher la question extra/intrabuccal en radiothérapie ORL."},"topic":"mucite-orale","title":"Comparative efficacy of two photobiomodulation protocols transcutaneous versus intraoral in the prevention of oral mucositis in head and neck cancer: a randomized study protocol.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Kolodziejwski WT","Renz GLK","de Souza IB","et al."],"date":"2026-07-29","year":2026,"week":"2026-S31","doi":"10.1007/s10103-026-04977-3","pmcid":"PMC13421264","license":"cc by","oa":true,"pdf":"pdfs/42525285.pdf","cited_by":0,"pub_types":["Equivalence Trial"],"abstract":[{"label":"UNLABELLED","text":"This study aims to compare the clinical efficacy of transcutaneous photobiomodulation (PBMT) with an 808 nm infrared laser versus intraoral PBMT with a 660 nm red laser in the prevention of oral mucositis (OM). The study is designed to assess whether the transcutaneous approach is non-inferior to the intraoral standard, thereby contributing to the optimization and standardization of PBMT protocols in head and neck cancer (HNC) supportive care."},{"label":"METHODS","text":"A randomized pilot study is being conducted with 54 patients (n = 27 per group) undergoing radiotherapy (60-70 Gy) for HNC. Participants will be randomly assigned to receive either intraoral PBMT (660 nm, 100 mW, 1 J/point, fluence = 10.20 J/ cm², 10 s, 44 points) or transcutaneous PBMT (808 nm, 100 mW, 1 J/point, fluence = 34.5 J/ cm² (central) and 4.3 J/ cm² (lateral), 10 s, 32 points). Interventions occur three times weekly throughout treatment. The primary outcome is OM severity, graded by WHO scale. Secondary outcomes include OM severity (NCI-CTCAE), pain intensity (Numeric Rating Scale, NRS), ulcerated area extension, registered through digital images, treatment interruptions and unscheduled healthcare utilization."},{"label":"EXPECTED OUTCOMES","text":"the primary hypothesis posits that transcutaneous infrared PBMT is as effective as intraoral red PBMT in mitigating OM severity. Additionally, the transcutaneous approach is expected to offer logistical advantages, including a reduction in application time (80 s vs. 440 s) and improved tolerability in patients with radiation-induced trismus or severe oral pain."},{"label":"CONCLUSION","text":"This protocol is expected to provide robust evidence to support the most feasible and effective PBMT modality for OM prevention. By optimizing treatment delivery, the study may enhance adherence, preserve nutritional status, and improve the quality of life for patients undergoing oncological therapy."}],"keywords":["Head and neck neoplasms","Low-level light therapy","Oral mucositis","Photobiomodulation therapy","Radiotherapy"]},{"pmid":"42463621","title_fr":"La PBM dans la prévention et le traitement de la mucite : revue bibliométrique","type":"biblio","level":0,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Bibliométrie","l1":"Analyse des 100 articles les plus cités sur PBM et mucite (1993–2025) : le Brésil et les États-Unis dominent, Supportive Care in Cancer est la revue de référence.","l2":"Sur 526 articles éligibles dans Scopus, les 100 plus cités comptent 56 études primaires et 44 synthèses, signées en moyenne par 9 auteurs. La recherche porte surtout sur l'efficacité de la PBM en traitement de la mucite.\n\nUtile pour repérer les équipes et les articles fondateurs, sans apport sur l'efficacité clinique.","l3":{"points":["725 articles retrouvés, 526 éligibles, 100 analysés.","Revue la plus représentée : Supportive Care in Cancer (14 des 100)."],"limites":["Analyse de citations uniquement (Scopus)."],"pratique":"Aucune conséquence clinique."},"topic":"mucite-orale","title":"Photobiomodulation therapy in oral mucositis prevention and treatment: insights from a bibliometric review.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Silva CM","da Silva IMB","Pereira JRD","et al."],"date":"2026-07-16","year":2026,"week":"2026-S29","doi":"10.1007/s00520-026-10976-5","pmcid":"PMC13375819","license":"cc by","oa":true,"pdf":"pdfs/42463621.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"PURPOSE","text":"This study presents the first bibliometric analysis aimed at evaluating the current state of knowledge and identifying limitations regarding the use of photobiomodulation (PBM) in the prevention and treatment of oral mucositis."},{"label":"METHODS","text":"A comprehensive search of the SCOPUS database was undertaken, with bibliometric analyses conducted using the Bibliometrix R-tool, Microsoft Excel, and VOSviewer."},{"label":"RESULTS","text":"A total of 725 articles were retrieved, of which 526 fulfilled the eligibility criteria. The 100 most cited articles, published between 1993 and 2025, were selected for analysis. The list comprised 56 primary studies and 44 secondary studies, collectively authored by 610 individuals, yielding an average of 9 authors per article. Research was predominantly concentrating studies focused on the efficacy of photobiomodulation in treating oral mucositis. The USA and Brazil emerged as leading contributors for the highest number of citations and scientific publications, both independently and in international collaborations. Among scientific journals, Supportive Care in Cancer stood out, with 14 of the most cited documents on the subject."},{"label":"CONCLUSION","text":"The list of articles included in this review serves as a relevant source of quantitative data, highlighting studies considered as references, as well as authors, journals, and countries with the highest scientific output. Additionally, it provides emerging insights on the topic."}],"keywords":["Cancer","Chemotherapy","Low level laser therapy","Oral mucositis","Photobiomodulation","Radiotherapy"]},{"pmid":"42438170","title_fr":"Méthotrexate salivaire comme prédicteur de mucite chez l'adulte en hématologie : essai randomisé de phase II en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","laser"],"nm":[],"n":53,"effect":"favorable","theme":"Efficacité vs placebo","key":true,"metric":{"kind":"rates","outcome":"Mucite ulcérée (OMS ≥ 2) à 96 h","a_label":"PBM","a":11.5,"b_label":"Placebo","b":51.9},"l1":"Chez 53 adultes sous méthotrexate haute dose, la PBM préventive réduit la mucite ulcérée de 51,9 % à 11,5 % (il suffit de traiter 2 patients pour en éviter une) ; le méthotrexate salivaire prédit la sévérité.","l2":"Essai brésilien randomisé, en double aveugle, contre laser simulé. La PBM était appliquée chaque jour jusqu'à l'élimination du méthotrexate (cinq séances au plus) ; la mucite était suivie neuf jours selon l'OMS.\n\nÀ 96 heures, la mucite de grade ≥ 2 touchait 11,5 % du groupe PBM contre 51,9 % du groupe placebo : réduction relative du risque de 77,7 %, nombre de sujets à traiter de 2. Le méthotrexate sérique n'était pas lié à la mucite, alors que le méthotrexate salivaire augmentait au fil du temps et corrélait à la sévérité : un biomarqueur non invasif prometteur.","l3":{"points":["Randomisation : PBM n = 26, placebo n = 27 ; essai enregistré (ReBEC 12218).","Effet : RRR 77,7 %, NST = 2, p < 0,01 ; odds de mucite sévère 8,97 fois plus élevé sous placebo.","Dosages sériques et salivaires du MTX à 24, 48 et 72 h, plus pH urinaire et créatinine."],"limites":["Phase II, monocentrique, petit effectif.","Paramètres laser non détaillés dans le résumé."],"pratique":"Confirme la PBM préventive chez l'adulte sous MTX-HD ; le MTX salivaire pourrait aider à cibler les patients à risque."},"topic":"mucite-orale","title":"Salivary Methotrexate as a Predictor of Oral Mucositis in Hematological Cancer Patients: A Phase II Randomized, Double-Blind Clinical Trial.","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Rodrigues-Oliveira L","Bonfim CG","Mores AL","et al."],"date":"2026-07-12","year":2026,"week":"2026-S28","doi":"10.1111/odi.70381","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"To evaluate the efficacy of prophylactic photobiomodulation therapy (PBMT) in preventing oral mucositis (OM) and to assess serum and salivary methotrexate (MTX) levels as predictors of OM in adults receiving high-dose methotrexate (HD-MTX)."},{"label":"METHODS","text":"This phase II randomized, double-blind, placebo-controlled trial enrolled adults with hematological malignancies undergoing a first HD-MTX cycle at a tertiary cancer center in Brazil. Participants were randomized to PBMT or sham laser therapy, administered daily until MTX clearance or for up to five sessions. OM was assessed for 9 days using WHO criteria. Serum and salivary MTX concentrations were measured at 24, 48, and 72 h post-infusion, along with urinary pH and serum creatinine."},{"label":"RESULTS","text":"Fifty-three patients were randomized (PBMT n = 26; placebo n = 27). PBMT significantly reduced ulcerative OM (grade ≥ 2) at 96 h (11.5% vs. 51.9%), yielding a 77.7% relative risk reduction and a number needed to treat of 2 (p < 0.01). Placebo recipients had an 8.97-fold higher odds of severe OM. Serum MTX was not associated with OM, whereas salivary MTX increased disproportionately over time and independently correlated with OM severity."},{"label":"CONCLUSIONS","text":"PBMT significantly reduced OM incidence and severity in adults receiving HD-MTX. Salivary MTX is a promising non-invasive biomarker for OM risk."},{"label":"TRIAL REGISTRATION","text":"Trial was prospectively registered in the Brazilian Registry of Clinical Trials (ReBec, No. 12218)."}],"keywords":["cancer","low‐level laser therapy","methotrexate","oral mucositis"]},{"pmid":"42677117","title_fr":"Laser basse énergie, PBM et thérapie photodynamique combinées en odontologie : revue systématique","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["PDT"],"nm":[],"n":null,"effect":"favorable","theme":"Associations","l1":"Huit études (2021–2025) combinant PBM et thérapie photodynamique en odontologie, dont la mucite : effets additifs suggérés, mais protocoles très hétérogènes.","l2":"La revue n'a retenu que des études primaires associant PBM et thérapie photodynamique (PDT) avec des paramètres clairement rapportés. Les applications vont de la mucite à l'orthodontie et à l'endodontie.\n\nL'association apparaît supérieure à chaque technique seule pour l'effet antimicrobien, les marqueurs inflammatoires, la cicatrisation et les résultats rapportés par les patients. Le faible nombre d'études et leur hétérogénéité limitent la portée du résultat.","l3":{"points":["Bases : PubMed, ScienceDirect, ProQuest, DOAJ, Google Scholar.","8 études incluses, toutes indications dentaires confondues."],"limites":["Pas de méta-analyse ; mélange d'indications.","Qualité des études non détaillée dans le résumé."],"pratique":"Pour la mucite, l'association PBM + PDT reste une piste (voir aussi la méta-analyse PDT de 2024)."},"topic":"mucite-orale","title":"Low-Level Laser Therapy, Photobiomodulation, and Photodynamics with Photosensitizer Combination in Dentistry: A Systematic Review.","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Muntadir L","Narmada IB","Sulisetyawati TIB","et al."],"date":"2026-07-09","year":2026,"week":"2026-S28","doi":"10.34172/jlms.49244","pmcid":"PMC13527693","license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Introduction: Photobiomodulation (PBM), photodynamic therapy (PDT), and combined therapies have recently attracted attention due to their potentially beneficial antimicrobial, analgesic, and regenerative properties in dentistry. Although PBM and PDT have been extensively studied separately, evidence regarding their combined application is limited. This study aimed to systematically review studies employing combined PBM + PDT protocols in dental and oral applications. Methods: A systematic search of PubMed, ScienceDirect, ProQuest, DOAJ, and Google Scholar (2021-2025) identified original studies using combined PBM and PDT. Inclusion criteria: dental-related PBM + PDT, clear dosimetric parameters, English, primary research. Exclusion: PBM-only, PDT-only, non-dental studies, insufficient parameters Inclusion criteria: dental-related PBM and PDT; clearly reported dosimetric parameters; English language; primary research. Results: Eight studies met eligibility criteria. Applications included oral mucositis management, orthodontic acceleration, endodontic disinfection, oral lesion therapy, antimicrobial modulation, and regenerative endodontics. Combined PBM + PDT demonstrated enhanced antimicrobial activity, reduced inflammatory markers, accelerated wound healing, and improved patient-reported outcomes compared with single-modality treatments. Conclusion: PBM + PDT shows synergistic therapeutic potential across multiple dental fields. Despite promising outcomes, heterogeneity in parameters remains a limitation. Standardized protocols and high-quality clinical trials are required."}],"keywords":["Photobiomodulation","Photodynamics","Therapy-in-dentistry"]},{"pmid":"42399564","title_fr":"PBM pour prévenir la mucite et l'altération fonctionnelle après greffe de cellules souches : essai randomisé POMFITT","type":"rct","level":2,"pop":"adulte","ctx":["CSH"],"aim":"prévention","mode":["intrabuccal","laser"],"nm":[660,808],"n":30,"effect":"favorable","theme":"Efficacité vs soins standards","metric":{"kind":"rates","outcome":"Mucite sévère","a_label":"PBM","a":0,"b_label":"Soins standards","b":26.6},"l1":"Essai chilien (30 greffés) : aucune mucite sévère sous PBM contre 26,6 % dans le groupe témoin, adhésion de 100 %, mais pas d'effet sur la force musculaire ni la qualité de vie à la sortie.","l2":"Essai randomisé contrôlé chez des adultes greffés pour hémopathie maligne. Laser diode (660 et 808 nm, 100 mW, 2 J, 20 points) trois fois par semaine, du début du conditionnement à J+3.\n\nLa mucite sévère a été évitée chez tous les patients traités (0 % contre 26,6 % ; p = 0,032). L'acceptation était excellente (10/10 pour 93 % des patients). En revanche, durée d'hospitalisation, force de préhension, capacité aérobie et force des membres inférieurs ne différaient pas. C'est la publication des résultats du protocole paru dans BMJ Open en 2024.","l3":{"points":["Critères : OMS, test de marche 2 min, dynamomètre Jamar, lever de chaise, FACT-BMT.","Mucite sévère : 0 % contre 26,6 % (p = 0,032).","Enregistrement : NCT06260111 (protocole publié en 2024, PMID 39461860)."],"limites":["30 patients seulement ; témoin sans simulation (pas de laser placebo).","Évaluation fonctionnelle seulement à la sortie."],"pratique":"Confirme la PBM préventive en greffe ; ne pas en attendre de bénéfice fonctionnel global à court terme."},"topic":"mucite-orale","title":"Photobiomodulation to prevent oral mucositis and physical function impairments after hematopoietic cell transplantation: POMFITT randomized trial.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["López-Espinoza T","Araya-Castro P","Gutiérrez-Silva L","et al."],"date":"2026-07-03","year":2026,"week":"2026-S27","doi":"10.1007/s00520-026-10970-x","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"AIM","text":"To assess the effectiveness of photobiomodulation, compared to standard care, to prevent oral mucositis and functional impairment, and improve quality of life in adults who underwent hematopoietic cell transplantation (HCT)."},{"label":"METHODS","text":"Randomized, controlled clinical trial with 30 patients with hematologic malignancies."},{"label":"INTERVENTION","text":"InGaIP diode laser treatment, starting on the first day of conditioning until day + 3, three times a week."},{"label":"PARAMETERS","text":"wavelengths of 660 nm and 808 nm, 100 mW, 2 J, 20 points."},{"label":"OUTCOME MEASURES","text":"oral mucositis (WHO scale), functional capacity (2-min step test), handgrip strength (Jamar dynamometer), lower limb strength (Sit-to-Stand test), quality of life (FACT-BMT), and acceptance (0-10 numerical scale)."},{"label":"RESULTS","text":"Participants fully adhered to the intervention (n = 15; 100%). Acceptance was rated 10/10 by 93.3% of participants. Severe oral mucositis occurred in 26.6% of the control group and 0% of the photobiomodulation group (p = 0.032). No significant differences were found between the groups in hospitalization days, handgrip strength, aerobic capacity, or lower-limb strength."},{"label":"CONCLUSIONS","text":"Photobiomodulation was associated with a lower occurrence of severe oral mucositis but did not affect physical function or quality of life at discharge. Acceptance in the Chilean context was very high."},{"label":"TRIAL REGISTRATION","text":"ClinicalTrials.gov: NCT06260111."}],"keywords":["Hematologic neoplasms","Hematopoietic stem cell transplantation","Low-level light therapy","Physical fitness","Physical therapy modalities","Stomatitis"]},{"pmid":"42360517","title_fr":"Essai randomisé en double aveugle contre simulation d'un dispositif LED intrabuccal de PBM pendant la radiothérapie ORL","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","LED"],"nm":[],"n":85,"effect":"favorable","theme":"Efficacité vs placebo","key":true,"metric":{"kind":"rates","outcome":"Mucite sévère (OMS ≥ 3) sur 6 semaines","a_label":"PBM LED","a":36.8,"b_label":"Simulation","b":57.1},"l1":"Essai multicentrique américain (85 patients, 12 centres) : une PBM LED intrabuccale quotidienne de 10 minutes réduit la mucite sévère (36,8 % contre 57,1 %) et préserve mieux le goût.","l2":"Les patients traités par radiothérapie en modulation d'intensité (IMRT) pour un cancer ORL, avec ou sans chimiothérapie, recevaient chaque jour avant la séance une PBM LED ou une simulation. 99,5 % des séances ont été réalisées, sans effet indésirable lié au dispositif.\n\nEn intention de traiter, la mucite de grade OMS ≥ 3 était moins fréquente sous PBM pendant les six semaines (36,8 % contre 57,1 % ; p = 0,046) et deux semaines après (10,8 % contre 36,4 %). En per protocole : meilleure préservation du goût, moins de douleurs buccales et pharyngées, et une tendance à moins de sondes d'alimentation. C'est l'un des essais les plus solides de la période.","l3":{"points":["Double aveugle contre simulation, 12 sites, enregistrement NCT03972527.","Mucite OMS ≥ 3 : 36,8 % contre 57,1 % (p = 0,046) ; à 2 semaines post-IMRT : 10,8 % contre 36,4 % (p = 0,042).","Per protocole : goût (p = 0,034), douleur bouche/gorge (p = 0,029), douleur pharyngée (p = 0,028), sondes d'alimentation (p = 0,073).","Observance : 99,5 % des séances initiées complétées."],"limites":["Effectif modeste pour un multicentrique (85 patients).","Certains bénéfices seulement en per protocole.","Essai d'un dispositif commercial : vérifier les financements dans le texte intégral."],"pratique":"Valide un dispositif LED intrabuccal autonome et quotidien, plus simple à déployer qu'un laser opéré à la main."},"topic":"mucite-orale","title":"Randomized, double-blind, sham-controlled trial of an intraoral photobiomodulation device for oral mucositis and associated complications due to radiotherapy for head and neck cancer.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Hu K","Shah P","Nguyen MC","et al."],"date":"2026-06-26","year":2026,"week":"2026-S26","doi":"10.1007/s00520-026-10904-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial","Multicenter Study"],"abstract":[{"label":"PURPOSE","text":"This study evaluated the safety and effectiveness of an intraoral light-emitting diode (LED)-based photobiomodulation (PBM) device to reduce the incidence and severity of oral mucositis (OM) from intensity modulated radiation therapy (IMRT) for head and neck cancer (HNC)."},{"label":"METHODS","text":"This randomized, double-blind, sham-controlled trial enrolled patients with HNC undergoing high-dose IMRT over 6-8 weeks, with or without concurrent chemotherapy. Participants received daily 10-min PBM or sham treatments immediately before IMRT sessions. Assessments were conducted at baseline, daily and weekly during IMRT, and two weeks post-IMRT."},{"label":"RESULTS","text":"Eighty-five participants (42 PBM; 43 sham) were enrolled across 12 US sites. No device-related adverse events were observed, and 99.5% of initiated sessions were completed. In the intent-to-treat population, severe OM (WHO Grade ≥ 3) incidence was significantly lower with PBM across six weeks of IMRT (36.8% vs 57.1%; p = 0.046) and at two weeks post-treatment (10.8% vs 36.4%; p = 0.042). In the per-protocol population, the PBM arm reported significantly greater taste preservation (p = 0.034), lower increases in mouth/throat soreness (p = 0.029) and throat pain (p = 0.028) and needed fewer feeding tube placements (p = 0.073) than the control arm."},{"label":"CONCLUSION","text":"Daily intraoral PBM therapy using an LED-based device was safe, well tolerated, and significantly reduced the incidence of severe OM and associated complications in HNC patients undergoing IMRT with or without concurrent chemotherapy. These findings align with guidelines recommending daily intraoral PBM therapy for preventing cancer therapy-related OM, a dose-limiting toxicity for which effective preventive interventions are needed."},{"label":"TRIAL REGISTRATION","text":"Clinical Trials.gov Registration Number NCT03972527. Registered on June 3, 2019. Daily intraoral PBM therapy using an LED-based device was safe, well tolerated, and significantly reduced the incidence of severe OM and associated complications in HNC patients undergoing IMRT with or without concurrent chemotherapy. These findings align with guidelines recommending daily intraoral PBM therapy for preventing cancer therapy-related OM, a dose-limiting toxicity for which effective preventive interventions are needed."}],"keywords":["Head and neck cancer","Oral mucositis","Photobiomodulation","Radiotherapy"]},{"pmid":"42450035","title_fr":"Biomarqueurs du stress oxydatif dans la cicatrisation muqueuse buccale et la PBM : voies biochimiques et perspectives","type":"review","level":5,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Mécanismes","l1":"Revue des mécanismes redox : la PBM ne serait pas un simple antioxydant mais un modulateur dépendant de la dose, qui favorise une signalisation transitoire utile à la cicatrisation.","l2":"Les auteurs distinguent le signal mitochondrial transitoire (ROS, monoxyde d'azote), favorable à la réparation, du stress oxydatif soutenu d'origine NADPH oxydase, délétère. Ils passent en revue les voies Nrf2/HO-1, NF-κB, HIF-1α/VEGF, MAPK/ERK, PI3K/Akt et MMP/TIMP.\n\nIls proposent une grille de choix des biomarqueurs pour les futures études de PBM, en précisant qu'elle n'est pas un outil de décision clinique validé.","l3":{"points":["Biomarqueurs : peroxydation lipidique, oxydation protéique, ADN oxydé, défenses antioxydantes, thiols/disulfures.","Concept clé : réponse biphasique à la dose."],"limites":["Revue narrative, cadre conceptuel non validé."],"pratique":"Aucune conséquence clinique immédiate ; utile pour comprendre l'importance de la dose."},"topic":"mucite-orale","title":"Oxidative Stress Biomarkers in Oral Mucosal Wound Healing and Photobiomodulation: Biochemical Pathways, Experimental Models, and Translational Perspectives.","journal":"International journal of molecular sciences","journal_abbr":"Int J Mol Sci","authors":["Dragojević IM","Kisić B","Mirić D","et al."],"date":"2026-06-26","year":2026,"week":"2026-S26","doi":"10.3390/ijms27135763","pmcid":"PMC13361522","license":"cc by","oa":true,"pdf":"pdfs/42450035.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Oral mucosal repair is a redox-regulated process that may be impaired by diabetes, chronic inflammation, infection, and chemotherapy- or radiotherapy-induced oral mucositis. Reactive oxygen species (ROS) support host defense, epithelial migration, angiogenesis, extracellular matrix remodeling, and adaptive repair when their production is transient and compartmentalized. In contrast, persistent ROS promote lipid, protein, and DNA oxidation, mitochondrial dysfunction, and extracellular matrix damage. Photobiomodulation (PBM) is increasingly used to support oral tissue repair, but its effects should be interpreted as dose- and context-dependent redox modulation rather than as simple antioxidant activity. This narrative review synthesizes oxidative stress biomarkers and redox-sensitive pathways relevant to oral mucosal repair and PBM, including oxidant-antioxidant balance, lipid and protein oxidation, oxidative DNA damage, antioxidant defense, thiol/disulfide homeostasis, mitochondrial and NADPH oxidase-derived ROS, Nrf2/HO-1, NF-κB, HIF-1α/VEGF, MAPK/ERK, PI3K/Akt, and MMP/TIMP signaling. The review emphasizes the distinction between transient mitochondrial ROS/nitric oxide signaling and sustained NADPH oxidase-driven oxi-inflammatory stress. It proposes a practical redox-guided framework for biomarker selection, PBM response interpretation, and future study design, while noting that this framework remains conceptual and is not yet a validated clinical decision algorithm."}],"keywords":["low-level laser therapy","oral mucosal wound healing","oxidative stress","oxidative stress biomarkers","photobiomodulation","reactive oxygen species","redox signaling","redox-sensitive pathways"]},{"pmid":"42319507","title_fr":"PBM et mucite en cancérologie : prévention, prise en charge et preuves issues des essais randomisés","type":"sr","level":1,"pop":"adulte","ctx":["mixte"],"aim":"les deux","mode":["intrabuccal"],"nm":[],"n":868,"effect":"favorable","theme":"Synthèse des preuves","l1":"Revue de 15 essais randomisés contre simulation (868 adultes) : la PBM réduit la mucite sévère, la douleur, les antalgiques et le recours à l'alimentation artificielle, surtout en prévention intrabuccale.","l2":"Revue systématique enregistrée (PROSPERO), recherche jusqu'au 31 mars 2026, limitée aux essais randomisés contre simulation chez l'adulte. La plupart des essais rapportent des bénéfices : moins de mucites sévères, moins de douleur, moins d'antalgiques et de supports nutritionnels.\n\nLes protocoles préventifs intrabuccaux donnent les résultats les plus favorables. La variabilité des paramètres et des critères empêche de recommander un protocole optimal. La qualité méthodologique des essais est jugée acceptable.","l3":{"points":["15 ECR, 868 patients adultes, comparateur simulation (sham).","Bases : PubMed, Web of Science, Scopus.","Signal le plus net : PBM préventive intrabuccale."],"limites":["Pas de méta-analyse quantitative dans le résumé.","Hétérogénéité des paramètres et de la mesure des critères."],"pratique":"Conforte la PBM préventive intrabuccale chez l'adulte ; la recherche doit maintenant porter sur le protocole optimal et le traitement curatif."},"topic":"mucite-orale","title":"Photobiomodulation for oral mucositis in cancer care: prevention, clinical management, and evidence from randomized controlled trials.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Parra-Rojas S","Cassol-Spanemberg J","Pérez AN","et al."],"date":"2026-06-19","year":2026,"week":"2026-S25","doi":"10.1007/s00520-026-10834-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review"],"abstract":[{"label":"PURPOSE","text":"This systematic review aimed to evaluate the efficacy of photobiomodulation (PBM) for the prevention and clinical management of oral mucositis (OM) in adult cancer patients, with particular emphasis on protocol characteristics potentially associated with favorable clinical outcomes."},{"label":"METHODS","text":"A systematic search of PubMed, Web of Science, and Scopus was conducted up to March 31, 2026, in accordance with PRISMA guidelines. Randomized controlled trials in adult cancer patients comparing PBM with sham interventions were included. Outcomes of interest included OM incidence, severity, pain, and related clinical outcomes. The review protocol was prospectively registered in PROSPERO."},{"label":"RESULTS","text":"Fifteen randomized controlled trials involving 868 adult patients were included. Most studies reported favorable effects of PBM, including reductions in severe OM incidence, pain intensity, analgesic requirements, and nutritional support needs compared with controls. Preventive intraoral PBM protocols were generally associated with more favorable outcomes, although variability in treatment parameters, delivery methods, and outcome reporting limited comparability. Most included studies demonstrated acceptable methodological quality."},{"label":"CONCLUSIONS","text":"PBM appears to be a promising supportive care intervention for reducing the burden of OM in adult cancer patients, particularly in preventive settings. However, variability across protocols precludes definitive conclusions regarding optimal treatment parameters. Further high-quality randomized trials with standardized reporting are needed to refine protocol recommendations and expand evidence in therapeutic settings."}],"keywords":["Cancer therapy","Oral mucositis","Photobiomodulation","Randomized controlled trials","Supportive care"]},{"pmid":"42283739","title_fr":"Impact de la mucite traitée par protocole de PBM sur la qualité de vie des enfants atteints de leucémie aiguë lymphoblastique","type":"cohort","level":4,"pop":"pédiatrie","ctx":["chimio"],"aim":"les deux","mode":[],"nm":[],"n":113,"effect":"—","theme":"Qualité de vie","l1":"Chez 113 enfants traités par méthotrexate avec PBM en routine, la mucite garde un fort impact sur la qualité de vie (85 %), surtout quand elle est sévère et longue à cicatriser.","l2":"Étude transversale brésilienne (2020–2024) qui utilise ChIMES (auto- et hétéro-évaluation), C-OIDP et l'échelle OMS. La PBM préventive et curative fait partie du protocole du service pour tous les enfants.\n\nLa sévérité de la mucite et le temps de cicatrisation sont les deux facteurs indépendants d'une moins bonne qualité de vie. Sans groupe sans PBM, l'étude ne mesure pas l'effet propre de la PBM ; elle montre le poids de la mucite qui persiste malgré elle.","l3":{"points":["Âge moyen 10,8 ans ; 85 % rapportent un impact élevé.","Régression : sévérité (β = 0,30 ; p = 0,021) et durée de cicatrisation (β = 0,49 ; p < 0,001)."],"limites":["Transversal, sans comparateur."],"pratique":"Même avec une PBM systématique, la mucite pèse lourd en pédiatrie : continuer à optimiser prévention et traitement."},"topic":"mucite-orale","title":"Impact of oral mucositis treated by photobiomodulation protocol on the quality of life of pediatric oncology patients with acute lymphoblastic leukemia.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Alves de Melo Júnior W","Correia Basto da Silva G","Suely Barros Dantas F","et al."],"date":"2026-06-12","year":2026,"week":"2026-S24","doi":"10.1007/s10103-026-04903-7","pmcid":"PMC13263282","license":"cc by","oa":true,"pdf":"pdfs/42283739.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"To assess factors associated with methotrexate-induced oral mucositis and its impact on the quality of life of pediatric patients with acute lymphoblastic leukemia, considering chemotherapy dose and mucositis severity within a clinical context where photobiomodulation is routinely used as part of the institutional care protocol. A cross-sectional study was conducted with 113 pediatric patients aged 5 to 18 years undergoing methotrexate-based chemotherapy between 2020 and 2024 in a university hospital in Northeastern Brazil. Data were collected using the Children's International Mucositis Evaluation Scale (ChIMES; self-report and proxy), the Child Oral Impacts on Daily Performances (C-OIDP), the WHO Oral Mucositis Grading Scale, photobiomodulation records, and chemotherapy regimen data. Descriptive statistics, Spearman correlation, and multiple linear regression analyses were performed (α = 0.05). Among the participants, 85% reported a high impact on quality of life. The mean age was 10.8 years (SD = 3.49), and most participants were boys. Higher mucositis severity, older age, higher methotrexate doses, and longer wound healing time were associated with worse quality of life. A strong positive correlation was observed between C-OIDP and ChIMES scores (p < 0.001). In the regression analysis, mucositis severity (β = 0.304; p = 0.021) and wound healing time (β = 0.492; p < 0.001) remained significantly associated with higher impact scores. Methotrexate-induced oral mucositis was associated with a substantial negative impact on quality of life in pediatric patients with acute lymphoblastic leukemia. Greater mucositis severity and longer wound healing time were the main factors associated with worse outcomes. Although photobiomodulation was systematically applied as a preventive and therapeutic intervention, no causal inference regarding its independent effect can be established."}],"keywords":["Acute lymphoblastic leukemia","Antineoplastic therapy","Methotrexate","Oral mucositis","Photobiomodulation therapy","Quality of life"]},{"pmid":"42269385","title_fr":"PBM laser haute puissance pour soulager immédiatement l'odynophagie liée à la mucite","type":"cases","level":4,"pop":"adulte","ctx":["mixte"],"aim":"traitement","mode":["intrabuccal","extrabuccal","haute puissance"],"nm":[940],"n":46,"effect":"favorable","theme":"Douleur","l1":"Chez 46 patients, une séance de PBM laser haute puissance (940 nm) fait baisser la douleur à la déglutition d'environ 40 % (7,4 à 4,6 sur 10), avec un effet qui dure près de 4 jours.","l2":"Étude israélienne avant-après : laser diode pulsé 940 nm, intrabuccal sans contact à 2–3 W et extrabuccal cervical au contact à 0,3–0,5 W. La douleur était mesurée avant et après chaque séance.\n\nSur 80 séances évaluables, 73 % apportaient une amélioration cliniquement significative (au moins 2 points). L'effet durait 3,8 jours en moyenne et était plus marqué quand la douleur initiale était forte. Les auteurs y voient un moyen de retarder ou d'éviter une gastrostomie.","l3":{"points":["85 séances, 80 évaluables ; douleur 7,4 ± 2,5 puis 4,6 ± 2,7 (p < 0,001).","Amélioration ≥ 2 points : 73 % des séances ; durée moyenne 3,8 ± 3,8 jours.","Paramètres : 940 nm pulsé, spot 1 cm², mouvements rotatifs."],"limites":["Pas de groupe témoin : effet placebo et évolution naturelle non contrôlés.","Douleur seule, sans critère objectif."],"pratique":"Option à considérer pour une odynophagie rebelle, en attendant des essais contrôlés ; même équipe que l'étude de 2023 sur la mucite réfractaire."},"topic":"mucite-orale","title":"High-power laser photobiomodulation therapy for immediate relief of mucositis-related odynophagia.","journal":"Oral oncology","journal_abbr":"Oral Oncol","authors":["Zadik Y","Gavish L","Hanut A","et al."],"date":"2026-06-10","year":2026,"week":"2026-S24","doi":"10.1016/j.oraloncology.2026.108049","pmcid":null,"license":"cc by-nc","oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Mucositis-related odynophagia (pain on swallowing) presenting during or shortly after radiotherapy, chemotherapy, hematopoietic cell transplantation, or other oncologic treatments is a common and clinically significant complication that may adversely affect oral intake, nutrition, weight, and quality of life. However, effective treatment options remain limited, and management often relies on supportive care or enteral feeding. This study evaluated the effect of combined intraoral and extraoral high-power laser photobiomodulation therapy (PBMT) on mucositis-related odynophagia."},{"label":"METHODS","text":"Patients with mucositis-related odynophagia received ≥ 1 session of 940 nm pulsed diode laser PBMT (intraoral: 2-3 W, non-contact, rotatory motion, 1 cm2 spot size; extraoral: 0.3-0.5 W, contact over the cervical region). Pain intensity was assessed before and after each session using a 0-10 numerical rating scale (NRS)."},{"label":"RESULTS","text":"Forty-six patients underwent 85 treatment sessions, of which 80 were evaluable. Pain scores decreased significantly following PBMT (mean ± SD: 7.4 ± 2.5 vs. 4.6 ± 2.7; p < 0.001), corresponding to a mean reduction of 2.8 ± 2.1 points (∼40 %). Clinically meaningful improvement (≥ 2 NRS points) was observed in 73 % of sessions. The analgesic effect persisted for a mean of 3.8 ± 3.8 days. Treatment response was consistent across subgroups, with greater reductions observed in patients with higher baseline pain (β = 0.239, p = 0.006)."},{"label":"CONCLUSIONS","text":"High-power PBMT was associated with rapid and clinically meaningful pain relief in oncotherapy-induced odynophagia. This effect may help delay or reduce the need for gastrostomy tube (G-tube) placement and support oral intake. Accordingly, high-power PBMT may represent an additional layer in supportive care strategies for mucositis and its related complications."}],"keywords":["Dysphagia","Esophagitis","Gastrointestinal mucositis","Percutaneous endoscopic gastrostomy","Swallowing disorder"]},{"pmid":"42344781","title_fr":"Analyse bibliométrique de la PBM pour la mucite chimio- et radio-induite (2016–2025)","type":"biblio","level":0,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Bibliométrie","l1":"152 publications (2016–2025) : forte croissance, menée par le Brésil, les États-Unis et la France.","l2":"Analyse des tendances de publication, des institutions (Goiás, São Paulo, Harvard), des revues (Supportive Care in Cancer, Lasers in Medical Science) et des mots-clés. La prévention monte en puissance dans les thèmes.\n\nPas d'évaluation de l'efficacité clinique.","l3":{"points":["Bases : Scopus, Web of Science, PubMed.","La France fait partie des trois pays les plus productifs."],"limites":["Bibliométrie seule."],"pratique":"Aucune conséquence clinique."},"topic":"mucite-orale","title":"A bibliometric analysis of photobiomodulation therapy for the prevention and treatment of chemotherapy- and radiotherapy-induced oral mucositis.","journal":"Frontiers in oral health","journal_abbr":"Front Oral Health","authors":["Kurmanalina M","Tamadon A","Ismagulova E","et al."],"date":"2026-06-09","year":2026,"week":"2026-S24","doi":"10.3389/froh.2026.1811389","pmcid":"PMC13287024","license":"cc by","oa":true,"pdf":"pdfs/42344781.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"INTRODUCTION","text":"Photobiomodulation therapy has emerged as an effective non-invasive intervention for preventing and managing chemotherapy- and radiotherapy-induced oral mucositis, a frequent complication that negatively affects oral health and quality of life in cancer patients."},{"label":"METHODS","text":"This bibliometric study was guided by PRISMA 2020 principles for study identification and selection. A total of 152 publications indexed in Scopus, Web of Science, and PubMed between 2016 and 2025 were analyzed using bibliometric indicators, including publication trends, authorship, institutional productivity, country contributions, citation analysis, and keyword evolution."},{"label":"RESULTS","text":"The results demonstrated a substantial increase in scientific production between 2016 and 2025, with Brazil, the United States, and France leading research output. The most productive institutions included Universidade Federal de Goiás, Universidade de São Paulo, and Harvard University, while Supportive Care in Cancer and Lasers in Medical Science were the most influential journals. International collaboration networks showed strong global partnerships, and keyword analysis revealed increasing focus on photobiomodulation therapy, oral mucositis, chemotherapy, radiotherapy, and prevention."},{"label":"CONCLUSION","text":"These findings indicate rapid global expansion and increasing scientific and clinical relevance of photobiomodulation therapy research, providing valuable insights into scientific development, key contributors, and emerging research directions that support future advances in evidence-based oral healthcare. However, the bibliometric nature of the study, heterogeneity of the included literature, and the lack of direct assessment of clinical outcomes should be considered as limitations."}],"keywords":["bibliometrics","chemotherapy","oral mucositis","photobiomodulation","radiotherapy"]},{"pmid":"42234177","title_fr":"PBM et mucite : expérience d'un programme de soins de support dans un institut indien d'oncologie ORL","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"traitement","mode":[],"nm":[],"n":132,"effect":"favorable","theme":"Vie réelle","l1":"En Inde, 132 patients ORL traités par PBM dès les premiers signes de mucite ont eu des mucites moins sévères et moins longues que 100 témoins historiques, avec moins d'opioïdes (57 % contre 85 %).","l2":"Cohorte observationnelle dans un centre caritatif. La PBM débutait à l'apparition d'une mucite (OMS ≥ 1), donc en mode curatif précoce. La mucite sévère passait de 57 % au début de la PBM à 2 % à 8 semaines.\n\nPar rapport à des témoins historiques appariés : grade maximal plus faible (2,9 contre 3,5), mucite sévère plus courte (1,2 contre 3,4 semaines), moins d'opioïdes. Les auteurs présentent la PBM comme un complément réaliste dans les contextes à ressources limitées.","l3":{"points":["132 patients PBM contre 100 témoins historiques.","Grade maximal 2,9 contre 3,5 ; durée de mucite sévère 1,2 contre 3,4 semaines ; opioïdes 57 % contre 85 % (p < 0,01)."],"limites":["Témoins historiques : soins de support et techniques de radiothérapie ont pu changer entre les périodes.","Paramètres de PBM non précisés dans le résumé."],"pratique":"Intéressant pour l'implantation dans des structures à moyens limités ; preuve de faible niveau."},"topic":"mucite-orale","title":"Photobiomodulation therapy for oral mucositis: clinical experience from a supportive care program at the Indian Institute of Head and Neck Oncology.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Dharkar D","Kulkarni K","Bensadoun RJ","et al."],"date":"2026-06-03","year":2026,"week":"2026-S23","doi":"10.1007/s00520-026-10823-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Observational Study"],"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation (PBM), the therapeutic use of non-ionizing red to near-infrared light, has emerged as a safe, non-invasive, evidence-based modality for managing oral mucositis (OM) in oncology."},{"label":"OBJECTIVE","text":"To evaluate the feasibility and therapeutic outcomes of photobiomodulation therapy (PBMT) within a structured multidisciplinary supportive care pathway at a charitable oncology center in India, specifically comparing outcomes against a historical control cohort."},{"label":"METHODS","text":"This observational cohort study included 132 patients with head and neck squamous cell carcinoma undergoing curative or adjuvant radiotherapy/chemoradiotherapy. PBMT was initiated at first clinical evidence of mucositis (WHO grade ≥ 1). Baseline for analysis was defined as the time of PBMT initiation. Outcomes were compared with a matched historical control cohort (n = 100) treated prior to PBMT implementation."},{"label":"RESULTS","text":"Severe mucositis (grades 3-4) in the PBMT cohort declined from 57% at baseline (time of PBMT initiation) to 2% at 8 weeks. The PBMT cohort demonstrated significantly superior outcomes compared to historical controls, including lower peak mucositis grades (2.9 vs. 3.5; p < 0.01), shorter duration of severe mucositis (1.2 vs. 3.4 weeks; p < 0.01), and reduced opioid reliance (57% vs. 85%; p < 0.01)."},{"label":"CONCLUSION","text":"PBMT was associated with improved mucositis severity and pain outcomes within a structured supportive care framework in head and neck cancer patients in tertiary cancer center. Compared with historical controls, PBMT was associated with lower peak mucositis grades shorter duration of severe mucositis and reduced opioid use. This findings suggest that PBMT may represent a practical adjunct in resource constrain oncology settings."}],"keywords":["Head and neck cancer","Low-resource setting","Oral mucositis","Photobiomodulation therapy","Supportive care"]},{"pmid":"42098536","title_fr":"PBM pour traiter et prévenir la mucite chimio- et/ou radio-induite : méta-analyse des essais randomisés des six dernières années","type":"ma","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["intrabuccal","extrabuccal","laser"],"nm":[635,660,980],"n":329,"effect":"favorable","theme":"Synthèse des preuves","metric":{"kind":"rr","outcome":"Mucite (incidence/sévérité)","rr":0.5,"lo":0.35,"hi":0.73,"k":7},"l1":"Méta-analyse de 7 essais randomisés récents (2020–2026, 329 patients) : la PBM divise par deux le risque de mucite (RR 0,50 ; IC95 % 0,35–0,73).","l2":"Revue systématique (PRISMA) sur de nombreuses bases, dont LILACS et Redalyc, limitée aux essais randomisés publiés depuis 2020. L'hétérogénéité est modérée (I² = 40 %).\n\nLes longueurs d'onde vont de 635 à 980 nm, avec 660 nm en intrabuccal le plus souvent ; les temps d'application intrabuccale varient de 3 à 20 s par point. Tous les essais utilisent l'échelle OMS. Les auteurs concluent à une forte efficacité, avec un faible risque de biais, mais l'effectif total reste limité.","l3":{"points":["7 ECR, 329 patients, période 2020–2026.","RR 0,50 (IC95 % 0,35–0,73) ; I² = 40 %.","Paramètres : 635–980 nm ; 660 nm majoritaire en intrabuccal."],"limites":["Petit nombre d'essais retenus sur une fenêtre de six ans.","Mélange prévention et traitement, chimiothérapie et radiothérapie."],"pratique":"Confirme l'ordre de grandeur de l'effet préventif, environ 50 % de mucites en moins, cohérent avec les autres méta-analyses."},"topic":"mucite-orale","title":"Photobiomodulation for the treatment and prevention of chemotherapy- and/or radiotherapy-induced oral mucositis in cancer patients: a systematic review and meta-analysis of randomized clinical trials published in the last six years.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["G R","R EP","A D","et al."],"date":"2026-05-07","year":2026,"week":"2026-S19","doi":"10.1007/s00520-026-10729-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"PURPOSE","text":"To systematically evaluate and update the evidence about photobiomodulation therapy (PBMT) as a therapy for the prevention and/or treatment of oral mucositis (OM) induced by antineoplastic therapies."},{"label":"METHODS","text":"This systematic review followed the Preferred Reporting Items for Systematic Reviews and Meta-Analyses (PRISMA) guidelines. A systematic literature search was conducted across PubMed, Web of Science, Scopus, and Embase as the primary databases. Additional searches were performed in the Virtual Health Library (VHL) and LILACS through the BIREME platform, as well as in Redalyc and the Wiley Online Library, covering the period from 2020 to 2026. Only randomized clinical trials published within the last six years investigating PBMT as a preventive or therapeutic intervention for oral mucositis (OM) in cancer patients receiving chemotherapy and/or radiotherapy were included."},{"label":"RESULTS","text":"Seven studies comprising 329 patients were included. PBMT proved to be highly effective in the management of OM (RR 0.50, 95% CI 0.35-0.73). Moderate heterogeneity was observed across studies (I2 = 40%). PBMT protocols varied, with laser wavelengths ranging from 635 to 980 nm, most commonly 660 nm for intraoral (IO) application. Application sites included IO and/or extraoral (EO) approaches, with IO application times ranging from 3 to 20 s. OM was consistently assessed using World Health Organization (WHO) criteria across all studies. The included trials demonstrated a low risk of bias and publication bias."},{"label":"CONCLUSION","text":"Evidence from recent randomized clinical trials confirms that PBMT is highly effective for the management of oral mucositis, reducing its incidence and severity, improving quality of life and treatment adherence, and potentially lowering healthcare costs during cancer therapy."}],"keywords":["Cancer","Chemotherapy","Oral Mucositis","Photobiomodulation","Radiotherapy"]},{"pmid":"42082093","title_fr":"Complications bucco-dentaires et leur prise en charge chez les patients atteints de cancer ORL : revue parapluie","type":"umbrella","level":1,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"131 revues systématiques sur les complications buccales des cancers ORL : la PBM est associée à moins de mucites, mais l'ensemble des preuves reste de faible confiance.","l2":"Revue parapluie enregistrée (PROSPERO), méthode JBI/Cochrane, qualité évaluée par AMSTAR-2 et recouvrement des études mesuré. La mucite est la complication la plus étudiée, devant xérostomie, dysphagie, trismus, caries et dysgueusie.\n\nLa PBM ressort comme associée à une réduction de la mucite ; l'IMRT réduit la xérostomie et l'ostéoradionécrose mandibulaire. La plupart des revues sont de confiance faible ou critiquement faible.","l3":{"points":["131 revues systématiques publiées depuis 2015 ; recherche au 19 juin 2025.","Recouvrement des études primaires mesuré (CCA)."],"limites":["Synthèse narrative, pas de méta-analyse."],"pratique":"La PBM fait partie des rares interventions buccales en ORL dont le signal est cohérent ; les preuves globales restent faibles."},"topic":"mucite-orale","title":"Oral and dental complications and management in head and neck cancer patients: An umbrella review.","journal":"Journal of dentistry","journal_abbr":"J Dent","authors":["Craig R","O'Kane R","Rodriguez J","et al."],"date":"2026-05-03","year":2026,"week":"2026-S18","doi":"10.1016/j.jdent.2026.106731","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review"],"abstract":[{"label":"OBJECTIVES","text":"To synthesise evidence on oral and dental side-effects experienced by head and neck cancer (HNC) patients, assess the strength and quality of existing systematic reviews, evaluate the evidence for prevention and management interventions and identify key gaps to inform future research."},{"label":"DATA","text":"Systematic reviews (with/without meta-analysis) published from 2015 onwards involving adults with HNC reporting oral/dental complications and/or interventions were included."},{"label":"SOURCES","text":"MEDLINE (OVID), Embase, Cochrane Database of Systematic Reviews and Scopus were searched (19 June 2025). Two reviewers screened and extracted data independently."},{"label":"STUDY SELECTION","text":"An umbrella review (PROSPERO CRD420251063188) was conducted following JBI/Cochrane guidance and reported in line with PRISMA 2020. Methodological quality was assessed using AMSTAR-2 and primary-study overlap quantified using corrected-covered-area (CCA). Owing to heterogeneity, findings were synthesised narratively by domain."},{"label":"CONCLUSIONS","text":"A total of 131 systematic reviews were included, with most rated as low or critically low confidence. Oral mucositis was the most frequently reported complication, followed by xerostomia, dysphagia, trismus, dental caries, and dysgeusia; osteoradionecrosis was less common. Preventive and therapeutic interventions are widely studied but largely supported by low-quality evidence. Photobiomodulation was associated with reduced oral mucositis, while intensity-modulated radiotherapy was associated with reduced xerostomia and mandibular osteoradionecrosis. Overall, the evidence base is fragmented and of low confidence. Standardised outcome measures and high-quality prospective studies are needed to strengthen the evidence base and improve survivorship care."},{"label":"CLINICAL SIGNIFICANCE","text":"Head and neck cancer patients experience a high burden of oral complications, yet dental management strategies are supported by limited high-quality evidence. This review highlights key areas of uncertainty and reinforces the need for multidisciplinary, evidence-based care, while identifying priorities for research to improve long-term oral health and quality of life."}],"keywords":["Cancer survivorship","Chemoradiotherapy","Dental care","Dental complications","Dysgeusia","Dysphagia","Head and neck cancer/neoplasms","Oral complications","Oral health-related quality of life","Oral mucositis"]},{"pmid":"42060123","title_fr":"PBM et açaï clarifié pour protéger la glande submandibulaire pendant la chimiothérapie : étude chez le rat","type":"preclinical","level":5,"pop":"—","ctx":["chimio"],"aim":"prévention","mode":["laser"],"nm":[660],"n":102,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat avec mucite induite par 5-FU, la PBM (660 nm), seule ou avec de l'açaï, protège la glande submandibulaire du stress oxydatif et des lésions structurelles.","l2":"102 rats répartis en cinq groupes (témoin, mucite non traitée, PBM, açaï, PBM + açaï). PBM à 660 nm, 100 mW, 0,24 J par point, appliquée sur la zone de mucite.\n\nLa PBM augmente la capacité antioxydante et réduit peroxydation lipidique et métabolites du monoxyde d'azote ; l'architecture glandulaire reste proche de celle des animaux sains. Même équipe que l'étude 2025 sur la parotide.","l3":{"points":["Mucite chimio-induite : 5-FU 60 puis 40 mg/kg.","Analyses à J8, J10, J14 : biochimie oxydative et histologie."],"limites":["Modèle animal ; transposition à l'humain incertaine."],"pratique":"Argument mécanistique pour un effet de la PBM sur les glandes salivaires pendant la chimiothérapie."},"topic":"mucite-orale","title":"Preclinical evidence of photobiomodulation and clarified açaí in submandibular gland protection during antineoplastic therapy: an experimental study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Melo WWP","Aragão WAB","Bittencourt LO","et al."],"date":"2026-04-30","year":2026,"week":"2026-S18","doi":"10.1007/s10103-026-04876-7","pmcid":"PMC13132951","license":"cc by","oa":true,"pdf":"pdfs/42060123.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"PURPOSE: This study aimed to investigate the biochemical and morphological effects of photobiomodulation (PBM) and supplementation with clarified açaí on the submandibular glands in a chemically induced oral mucositis model in rats. Methods: 102 rats were divided into five groups- control: no induction of oral mucositis (OM); untreated group: OM induction, no treatment; PBM: OM induction and laser application (660 nm, 100 mW, 0.24 J, 2.4 s per point, 8 J/cm2 and in contact only at the OM site, bilaterally); açaí: OM induction and supplementation with clarified açaí; and PBM + açaí: OM induction and combination of the two treatments mentioned above. Oral mucositis was chemically induced by 5-fluorouracil (5-FU) on days 0 (60 mg/kg) and 2 (40 mg/kg). PMB and supplementation with clarified açaí (dose of 1 ml/100 g body weight) were used from day 0 of the experiment until euthanasia. On days 0 (control group), 8, 10, and 14 (intervention groups), submandibular glands were collected for analysis, with the right side used for oxidative biochemical analysis and the left side for histological analysis. A two-way statistical analysis of variance (ANOVA) was performed, followed by Tukey's post-hoc test (p < 0.05). Results: PMB, alone or in combination with clarified açaí, significantly increased antioxidant capacity levels and showed significantly lower levels of lipid peroxidation and nitric oxide metabolites compared to the control group (p < 0.0001). Morphologically, PBM, alone or combined with clarified açaí, maintained parenchyma, stroma, and acinar structures similar to the control group, which was not subjected to OM induction. Conclusion: It was experimentally demonstrated that PBM, when used alone or combined with clarified açaí, resulted in improved antioxidant response, in addition to providing glandular protection against structural damage caused by chemotherapy."}],"keywords":["Euterpe oleracea Mart—Antioxidant—Submandibular salivary gland","Chemotherapy","Photobiomodulation","Rat"]},{"pmid":"42052855","title_fr":"Pourquoi et quand les interventions validées sont-elles adoptées en soins de support pédiatriques ? Étude qualitative sur l'implantation de la PBM","type":"qualitative","level":0,"pop":"pédiatrie","ctx":["mixte"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":27,"effect":"—","theme":"Implantation","l1":"Au Royaume-Uni, la PBM est recommandée mais peu utilisée en oncopédiatrie : son adoption dépend moins des preuves que de l'organisation locale (personnel, réseaux, standardisation). Les systèmes LED progressent.","l2":"Entretiens avec 27 personnes (18 soignants de 11 centres, 1 industriel, 4 binômes enfant/parent) analysés selon le cadre CFIR. Cinq thèmes : présenter la PBM comme un soin de routine, une intervention simple et gratifiante, le besoin de réseaux multiprofessionnels, l'équilibre entre individualisation et standardisation, et l'essor des LED, qui posent moins d'obstacles.\n\nLes auteurs recommandent des stratégies d'implantation fondées sur la théorie pour réduire les inégalités d'accès.","l3":{"points":["Expérience des participants : laser (n = 15), LED (n = 13).","Analyse déductive (CFIR) puis inductive, avec des groupes de patients partenaires."],"limites":["Étude qualitative, contexte britannique."],"pratique":"Pour implanter la PBM : personnel dédié, protocole standardisé, réseau régional ; les LED facilitent le déploiement."},"topic":"mucite-orale","title":"Why and When Are Evidence-Based Interventions Adopted in Paediatric Supportive Care? A Qualitative Exploration of the Determinants of Photobiomodulation Implementation.","journal":"Pediatric blood & cancer","journal_abbr":"Pediatr Blood Cancer","authors":["Heggie C","Gray-Burrows KA","Day PF","et al."],"date":"2026-04-29","year":2026,"week":"2026-S18","doi":"10.1002/1545-5017.70282","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis is a common and debilitating side effect of childhood cancer and stem cell transplant treatments. It affects the quality of life of children and young people (CYP) and places a strain on services. Photobiomodulation is recommended for oral mucositis prevention in international guidance but is poorly implemented in UK Principal Treatment Centres (PTCs). Our study explored the key barriers and facilitators to implementing photobiomodulation into standard care."},{"label":"METHODS","text":"CYP, their parents, and healthcare professionals (HCPs) were purposively sampled for diversity in theoretically important characteristics: stage of adoption of PTC, professional role (HCPs), age (CYP), and photobiomodulation modality. Initial deductive framework analysis on semi-structured interview data was guided by the Consolidated Framework for Implementation Research (CFIR). Qualitative summaries were then inductively generated, articulating the valence of influence and effect. Overarching themes were developed and refined in collaboration with patient involvement groups."},{"label":"RESULTS","text":"Twenty-seven participants were interviewed: 18 HCPs from 11 diverse PTCs, 1 industry representative, and 4 CYP/Parent dyads. Participants had experience with low-level laser (n = 15) and light-emitting diode (LED) (n = 13) systems. Perceived barriers and facilitators varied between PTCs, participant groups, and photobiomodulation systems. Five themes were developed: (1) framing photobiomodulation as essential to routine care in busy cancer services; (2) photobiomodulation as simple, proactive, and rewarding; (3) need for navigable, interconnected, multiprofessional networks to support implementation; (4) balancing individualisation of services with the need for guidance and standardisation; and (5) increasing implementation of LED systems, with fewer barriers, over time."},{"label":"CONCLUSION","text":"Implementing photobiomodulation in paediatric oncology depends less on its clinical evidence and more on the local conditions that enable reliable delivery. This study highlights the importance of aligning service structures, workforce capacity, and professional networks to 'embed' photobiomodulation as routine care. Theory-informed implementation strategies can reduce current inequities in access and provide a transferable model for introducing other evidence-based supportive care interventions."}],"keywords":["implementation","oral health","oral mucositis","photobiomodulation","supportive care"]},{"pmid":"41999121","title_fr":"Association de l'ILIB (irradiation laser du sang) et de la PBM dans la mucite : étude prospective","type":"nrct","level":3,"pop":"adulte","ctx":["mixte"],"aim":"les deux","mode":["laser"],"nm":[],"n":76,"effect":"favorable","theme":"Associations","l1":"Chez 76 patients, l'ILIB associée à la PBM buccale réduit davantage la mucite (−55 à −61 %) et améliore plus la qualité de vie que l'ILIB seule (−25 %).","l2":"Étude quasi expérimentale à quatre groupes de 19 patients : ILIB seule ou ILIB + laser buccal, en préventif ou en curatif. La mucite (OMS) et la qualité de vie (OHIP-14) étaient mesurées avant et après.\n\nLes groupes combinés ont mieux répondu. Il manque un groupe PBM buccale seule : on ne peut pas savoir ce qu'apporte l'ILIB par rapport à la PBM locale, qui est le standard.","l3":{"points":["Mucite : −55,2 % et −60,7 % (combiné) contre −25 % et −25,9 % (ILIB seule).","OHIP-14 : −31 % et −36 % contre −15,8 % et −15,5 %."],"limites":["Non randomisé.","Pas de bras PBM locale seule : l'apport de l'ILIB n'est pas démontré."],"pratique":"Ne justifie pas l'ILIB ; confirme surtout l'intérêt de la PBM buccale locale."},"topic":"mucite-orale","title":"Effectiveness of the Association Between ILIB and Photobiomodulation in Oral Mucositis Among Oncology Patients: A Prospective Study.","journal":"Head & neck","journal_abbr":"Head Neck","authors":["do Nascimento CRE","Dantas FSB","Pereira TF","et al."],"date":"2026-04-17","year":2026,"week":"2026-S16","doi":"10.1002/hed.70285","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND/PURPOSE","text":"Oral mucositis is one of the most frequent and debilitating adverse effects of antineoplastic therapy, significantly impairing treatment adherence and patients' quality of life. This study aimed to evaluate the effectiveness of Intravenous Laser Irradiation of Blood (ILIB), applied alone or combined with low-level laser therapy, in reducing oral mucositis and improving the quality of life of oncology patients."},{"label":"METHODS","text":"This quasi-experimental prospective study with parallel groups was conducted between 2023 and 2024 at the Memorial Hospital of Arcoverde (PE), involving 76 patients equally allocated into four groups (n = 19): ILIB alone (A and C) and ILIB combined with laser therapy (B and D), applied therapeutically or preventively over weeks. Oral mucositis grade (WHO scale) and quality of life (OHIP-14) were assessed before and after the interventions."},{"label":"RESULTS","text":"No baseline differences were observed between groups (p > 0.05). After the intervention, the combined therapy groups showed greater reductions in mucositis (B: -1.60; -55.2% and D: -1.70; -60.7%) compared with ILIB alone (A: -0.70; -25.0% and C: -0.70; -25.9%) (p < 0.05). Improvements in quality of life were also more pronounced in the combined groups (B: -9.00; -31.0% and D: -10.40; -36.0%) compared with ILIB alone (A: -4.50; -15.8% and C: -4.30; -15.5%) (p < 0.05)."},{"label":"CONCLUSION","text":"The ILIB + laser therapy association was more effective than ILIB alone in reducing oral mucositis and improving quality of life, both in prevention and treatment contexts."}],"keywords":["Oral manifestations","low‐level light therapy","photobiomodulation","quality of life","stomatitis"]},{"pmid":"42073454","title_fr":"Toxicité cytokinique et dysbiose bactérienne dans la mucite chimio- et radio-induite : mécanismes et traitements","type":"review","level":5,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Mécanismes","l1":"Revue des deux moteurs de la mucite, l'excès de cytokines pro-inflammatoires et la dysbiose ; la PBM figure parmi les approches anti-inflammatoires validées chez l'animal.","l2":"IL-1β, IL-6, TNF, iNOS et monoxyde d'azote amplifient la lésion ; la perte des bactéries commensales l'aggrave. La revue recense pentoxifylline, atorvastatine, IL-11 recombinante, laser basse énergie, probiotiques et transplantation de microbiote oral.\n\nElle fournit un cadre de lecture des mécanismes sans apport clinique direct sur la PBM.","l3":{"points":["Cible commune : la cascade inflammatoire et la barrière muqueuse."],"limites":["Revue narrative."],"pratique":"Aucune conséquence directe."},"topic":"mucite-orale","title":"Cytokine Toxicity and Bacterial Dysbiosis in Chemotherapy- and/or Radiotherapy-Induced Oral Mucositis: Pathophysiological Mechanisms and Therapeutic Interventions.","journal":"Life (Basel, Switzerland)","journal_abbr":"Life (Basel)","authors":["Abdolmohammadi P","Aali M","Lehmann C"],"date":"2026-04-11","year":2026,"week":"2026-S15","doi":"10.3390/life16040644","pmcid":"PMC13117281","license":"cc by","oa":true,"pdf":"pdfs/42073454.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Chemotherapy- and/or radiotherapy-induced oral mucositis (CRIOM) is a common complication in patients with head and neck cancer, driven largely by excessive proinflammatory cytokine signalling and treatment-associated bacterial dysbiosis. This narrative review synthesizes current mechanistic evidence and summarizes emerging therapeutic strategies targeting these pathways. Research indicates that elevated levels of IL-1β, IL-6, TNF, iNOS, and nitric oxide amplify tissue injury and ulceration, while disruption of oral and gut microbial communities, characterized by loss of beneficial commensals and enrichment of pathogenic taxa, further exacerbates mucosal inflammation. Anti-inflammatory agents, including pentoxifylline, atorvastatin, trans-caryophyllene, azilsartan, recombinant human IL-11, and low-level laser therapy have been shown in preclinical models to reduce cytokine levels and promote mucosal healing. Similarly, microbiome-targeted approaches, such as oral microbiota transplantation and multi-strain probiotic formulations, have demonstrated potential in restoring microbial balance and attenuating CRIOM severity, with current evidence including both preclinical and clinical studies. Overall, current findings highlight cytokine toxicity and dysbiosis as synergistic drivers of CRIOM and support anti-inflammatory and microbiome-modulating strategies as promising adjunctive approaches; however, further well-designed clinical studies are required to validate their efficacy and guide clinical translation."}],"keywords":["anti-inflammatory","bacterial dysbiosis","chemotherapy","cytokine","cytokine toxicity","head and neck cancer","microbiome","oral microbiota manipulation","oral mucositis","radiotherapy"]},{"pmid":"41935072","title_fr":"Effet de la PBM intra- et extrabuccale sur le stress oxydatif et les cytokines salivaires pendant la radiothérapie ORL","type":"nrct","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","extrabuccal"],"nm":[],"n":18,"effect":"favorable","theme":"Mécanismes","l1":"Chez 18 patients irradiés, la PBM est associée à une hausse des défenses antioxydantes salivaires (SOD, glutathion) et à une baisse d'IL-6 ; moins de 40 % ont eu une mucite sévère.","l2":"Étude biologique brésilienne : 10 patients en PBM intrabuccale, 8 en extrabuccale, cinq fois par semaine dès le début de la radiothérapie, et 20 témoins sains. Prélèvements salivaires avant, à mi-parcours et en fin de radiothérapie.\n\nSOD et glutathion augmentaient sous PBM, IL-6 et IL-10 diminuaient ; la myéloperoxydase restait élevée. Tous les patients ont eu une mucite, mais moins de 40 % une forme sévère.","l3":{"points":["Marqueurs : MPO, MDA, SOD, GSH, IL-6, IL-10.","Pic transitoire de MDA à mi-parcours, sans lien avec la sévérité."],"limites":["Très petit effectif, pas de groupe irradié sans PBM."],"pratique":"Données mécanistiques ; pas de conséquence pratique directe."},"topic":"mucite-orale","title":"Effect of intraoral and extraoral photobiomodulation on salivary oxidative stress and inflammatory cytokines in patients with radiotherapy-induced oral mucositis.","journal":"Scientific reports","journal_abbr":"Sci Rep","authors":["Loureiro FJA","Klein IP","de Farias Gabriel A","et al."],"date":"2026-04-04","year":2026,"week":"2026-S14","doi":"10.1038/s41598-026-43141-3","pmcid":"PMC13201865","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41935072.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation (PBM) is an evidence-based approach for managing oral mucositis (OM) in patients undergoing head and neck radiotherapy (RT), though its biological mechanisms remain under investigation. This study evaluated salivary oxidative stress (OS) and inflammatory biomarkers in patients with head and neck squamous cell carcinoma (HNSCC) who received intraoral (IOPBM, n = 10) or extraoral PBM (EOPBM, n = 8) as supportive therapy during radiotherapy, and not as a cancer treatment. Preventive IOPBM/EOPBM were applied five times weekly from RT initiation until OM healing. Twenty healthy individuals served as the control group. Unstimulated saliva was collected at pre-, mid-, and final-RT (last RT session) to assess myeloperoxidase (MPO), malondialdehyde (MDA), superoxide dismutase (SOD), glutathione (GSH), interleukin-6 (IL-6), and interleukin-10 (IL-10). HNSCC patients exhibited altered oxidative and inflammatory biomarker profiles during RT. MDA levels showed a transient increase at mid-RT (p < 0.05), particularly in the IOPBM group, but were not associated with OM severity (p > 0.05). MPO activity was significantly higher at all RT time points and across OM severity grades compared with CT (p < 0.05–0.01). In contrast, SOD activity were consistently elevated throughout RT in PBM-treated patients compared with CT (p < 0.001), and GSH levels increased at mid-RT (p < 0.01). IL-6 and IL-10 levels decreased from pre- to final-RT compared to CT (p < 0.05). Clinically, all patients developed OM, although fewer than 40% experienced severe OM. These findings suggest that PBM enhances antioxidant defenses and modulates inflammatory responses, supporting its role in reducing RT-induced oral toxicity."}],"keywords":["Cytokines","Inflammation","Low-level laser therapy","Oxidative stress"]},{"pmid":"41948009","title_fr":"Relation dose-effet entre radiothérapie et mucite chez les patients ORL : étude rétrospective","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":[],"nm":[],"n":121,"effect":"neutre","theme":"Facteurs de risque","l1":"Sur 121 patients irradiés, le risque de mucite dépend surtout de la localisation intrabuccale de la tumeur et de la dose ; le laser préventif montre une tendance protectrice qui disparaît après ajustement.","l2":"Analyse rétrospective (radiothérapie conformationnelle 3D, Brésil, 2020–2023). 42 % des patients ont eu une mucite. Tumeur intrabuccale (OR ajusté 9,1), nombre de séances, dose cumulée et sexe féminin étaient liés à sa survenue.\n\nLa PBM préventive n'était pas significative en analyse multivariée. Cela rappelle que les études observationnelles peinent à isoler son effet face aux facteurs de risque dominants.","l3":{"points":["Tumeur intrabuccale : ORa 9,06 ; par séance : ORa 1,11 ; par Gy : ORa 1,05 ; femme : ORa 3,10.","Aucune mucite de grade 4."],"limites":["Rétrospectif ; usage de la PBM non randomisé ni standardisé."],"pratique":"Utile pour cibler les patients à haut risque (tumeur buccale, forte dose) chez qui la PBM est prioritaire."},"topic":"mucite-orale","title":"Dose-Dependence Relationship Between Radiotherapy and Oral Mucositis in Patients With Head and Neck Cancer: A Retrospective Study.","journal":"International journal of dentistry","journal_abbr":"Int J Dent","authors":["França SR","Pinto FC","Oliveira VB","et al."],"date":"2026-04-03","year":2026,"week":"2026-S14","doi":"10.1155/ijod/3972232","pmcid":"PMC13051859","license":"cc by","oa":true,"pdf":"pdfs/41948009.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"INTRODUCTION AND PURPOSE","text":"To evaluate the association between radiotherapy (RT) exposure and the presence and severity of radiation-induced oral mucositis (RIOM) in patients with head and neck cancer (HNC)."},{"label":"METHODS","text":"This retrospective observational study analyzed medical records of 121 patients with HNC treated with 3D conformal RT at a referral hospital in Brazil (2020-2023). Sociodemographic, clinical, and RT-related variables were collected. RIOM was clinically assessed using World Health Organization (WHO) criteria and analyzed using three approaches: presence of RIOM, overall severity (grades 0-4), and severity among affected patients (grades 1-4). Analyses included descriptive, bivariate, and adjusted multivariable binary and ordinal logistic regression models."},{"label":"RESULTS","text":"RIOM was identified in 51 patients (42.1%). No cases of WHO grade 4 were observed. In multivariable analysis, intraoral tumor (aOR = 9.06; 95% CI: 3.51-23.38; p < 0.001), number of RT sessions (aOR = 1.11 per session; 95% CI: 1.04-1.17; p  < 0.001), cumulative dose (aOR = 1.05 per Gy; 95% CI: 1.02-1.08; p = 0.001) and female sex (aOR = 3.10; 95% CI: 1.13-8.43; p = 0.027) were independently associated with RIOM presence. Intraoral tumor and increasing RT exposure remained significantly associated with greater RIOM severity (p  < 0.01) in ordinal models. Preventive laser therapy showed a protective trend in bivariate analysis but did not remain significant after adjustment."},{"label":"CONCLUSION","text":"RT exposure and intraoral tumor location were the main factors associated with both the presence and severity of RIOM, highlighting the importance of anatomical site and radiation burden for risk stratification."}],"keywords":["epidemiology","head and neck cancer","observational study","oral mucositis","radiotherapy"]},{"pmid":"41948031","title_fr":"Zinc L-carnosine et PBM Nd:YAG pour la mucite radio-induite : série de cas","type":"cases","level":4,"pop":"adulte","ctx":["ORL"],"aim":"traitement","mode":["laser"],"nm":[1064],"n":3,"effect":"favorable","theme":"Associations","l1":"Trois patients irradiés avec mucite de grade 2–3 : bain de bouche au zinc L-carnosine et PBM au laser Nd:YAG soulagent en deux jours et cicatrisent en trois semaines.","l2":"Série italienne (Parme) : cancers de l'oropharynx, de la langue et du voile. La surface des lésions était mesurée par analyse d'image (Fiji).\n\nTrois cas, sans témoin : simple piste pour une association inhabituelle (Nd:YAG à 1 064 nm).","l3":{"points":["2 mucites OMS III, 1 OMS II.","Douleur nettement réduite à J2, cicatrisation complète en 3 semaines."],"limites":["3 cas, sans comparateur ; évolution naturelle possible."],"pratique":"Pas de recommandation possible."},"topic":"mucite-orale","title":"A Case Series on the Combined Use of Zinc L-Carnosine and Nd:YAG Photobiomodulation for Radiation-Induced Oral Mucositis: Pain Reduction and Lesion Improvement.","journal":"Case reports in dentistry","journal_abbr":"Case Rep Dent","authors":["De Francesco P","Vescovi P","Grondelli C","et al."],"date":"2026-04-03","year":2026,"week":"2026-S14","doi":"10.1155/crid/7025093","pmcid":"PMC13051797","license":"cc by","oa":true,"pdf":"pdfs/41948031.pdf","cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"Radiation-induced oral mucositis (RIOM) is a severe complication in patients with head and neck cancer (HNC) undergoing radiotherapy (RT). Despite several proposed strategies for prevention and treatment, the results remain inconsistent and unpredictable. A combined approach with zinc L-carnosine (ZnC) mouthwash and Nd:YAG laser photobiomodulation (PBM) was evaluated in three patients affected by RIOM, treated at the Unit of Oral Medicine, Pathology and Laser-assisted Surgery of the University of Parma, Italy. One patient had oropharyngeal cancer, one had tongue cancer, and one had soft palate cancer. Two patients presented with World Health Organization (WHO) grade III mucositis, and one with WHO grade II mucositis. The percentage reduction in oral lesions was calculated using Fiji software. All patients reported clinical improvement and a reduction in algic symptoms. A significant decrease in pain was observed after only 2 days, while complete mucosal healing was achieved within 3 weeks. These preliminary results suggest that the combined use of ZnC and Nd:YAG laser PBM may be a promising therapeutic option for patients affected by RIOM, warranting further investigation in larger clinical studies."}],"keywords":["Nd:YAG laser photobiomodulation","case report","oral pathology","radiation-induced oral mucositis","zinc L-carnosine"]},{"pmid":"41880047","title_fr":"Effets de la PBM sur la mucite, la douleur, la xérostomie, le débit salivaire et la qualité de vie en ORL : revue systématique et méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":1748,"effect":"favorable","theme":"Synthèse des preuves","key":true,"metric":{"kind":"rr","outcome":"Mucite sévère","rr":0.46,"lo":0.29,"hi":0.71,"k":30},"l1":"La plus grande méta-analyse de 2026 (30 essais, 1 748 patients ORL) : la PBM réduit de 54 % le risque de mucite sévère et de 65 % celui de douleur sévère, sans effet net sur la xérostomie. Certitude faible à très faible.","l2":"Méta-analyse à trois niveaux d'essais randomisés (recherche jusqu'en avril 2025). La PBM réduit la mucite sévère (RR 0,46 ; IC95 % 0,29–0,71) et la douleur sévère (RR 0,35 ; 0,23–0,53) et améliore le débit salivaire (DMS 0,75).\n\nElle ne modifie pas significativement la xérostomie ressentie (DMS −0,07) ; la qualité de vie montre une tendance favorable non significative (DMS 1,06 ; p = 0,06). Les bénéfices sont stables d'un protocole à l'autre. La certitude GRADE va de très faible à faible : la plupart des essais ont un risque de biais élevé.","l3":{"points":["33 articles, 30 ECR, 1 748 patients ; modèle à effets mixtes à trois niveaux.","Mucite sévère : RR 0,46 (0,29–0,71) ; douleur sévère : RR 0,35 (0,23–0,53).","Débit salivaire : DMS 0,75 (0,03–1,46) ; xérostomie : DMS −0,07 (NS) ; qualité de vie : DMS 1,06 (−0,03 à 2,14).","Effet cohérent quel que soit le protocole."],"limites":["Certitude GRADE très faible à faible.","Risque de biais élevé dans la majorité des essais."],"pratique":"Référence quantitative de 2026 en ORL : environ deux fois moins de mucites sévères et trois fois moins de douleurs sévères. À présenter avec la réserve sur la qualité des essais."},"topic":"mucite-orale","title":"Effects of photobiomodulation on oral mucositis, oral pain, xerostomia, salivary flow rate, and quality of life in patients with head and neck cancer: a systematic review and meta-analysis.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Pedroso MNM","Rech A","Casagrande N","et al."],"date":"2026-03-25","year":2026,"week":"2026-S13","doi":"10.1007/s00520-026-10575-4","pmcid":"PMC13018037","license":"cc by","oa":true,"pdf":"pdfs/41880047.pdf","cited_by":2,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"PURPOSE","text":"To systematically review and analyze the effects of photobiomodulation on oral mucositis, xerostomia, salivary flow rates, oral pain, and quality of life in patients with head and neck cancer."},{"label":"METHODS","text":"A systematic search of six databases was conducted up to April 2025. Eligible randomized controlled trials (RCTs) examined the effects of photobiomodulation on the specified outcomes in patients with head and neck cancer. Pooled estimates (risk ratio [RR] and standardized mean difference [SMD]) were calculated using a three-level mixed-effects meta-analysis."},{"label":"RESULTS","text":"Thirty-three articles describing 30 RCTs (n = 1748) were included. Photobiomodulation significantly reduced the risk of severe oral mucositis (RR 0.46, 95% CI: 0.29-0.71, P < 0.001) and severe oral pain (RR 0.35, 95% CI: 0.23-0.53, P < 0.001) compared with controls. Significant improvements were also observed for salivary flow rate (SMD 0.75, 95% CI: 0.03-1.46, P = 0.044). No significant effects were observed on xerostomia (SMD -0.07, 95% CI: -0.47-0.33, P = 0.646) and quality of life (SMD 1.06, 95% CI: -0.03-2.14, P = 0.060). The benefits were consistent across different photobiomodulation protocols for oral mucositis and quality of life."},{"label":"CONCLUSIONS","text":"Photobiomodulation appears to be a promising supportive care intervention, reducing the risk of severe mucositis and oral pain, while potentially improving salivary flow rates and preserving quality of life in patients with head and neck cancer. However, the certainty of the evidence ranged from very low to low and most included studies presented a high risk of bias; therefore, these findings should be interpreted with caution."}],"keywords":["Head and neck neoplasms","Low-level light therapy","Mouth dryness","Quality of life"]},{"pmid":"41864516","title_fr":"Effet thérapeutique de la PBM sur la mucite radio-induite en ORL : essai prospectif en double aveugle, autocontrôlé","type":"nrct","level":3,"pop":"adulte","ctx":["ORL"],"aim":"traitement","mode":["intrabuccal","laser"],"nm":[660],"n":53,"effect":"favorable","theme":"Traitement curatif","key":true,"metric":{"kind":"rates","outcome":"Cicatrisation complète de la lésion","a_label":"Lésion traitée","a":52.4,"b_label":"Lésion témoin","b":11.9},"l1":"Chez 53 patients ayant deux lésions comparables, la lésion traitée par PBM (660 nm) a guéri bien plus souvent que la lésion témoin (52,4 % contre 11,9 %), avec une douleur soulagée dès la première semaine.","l2":"Plan original en « bouche divisée » : chez chaque patient, une lésion reçoit la PBM (660 nm, 150 mW, 5 J par point, deux fois par semaine) et l'autre une simulation, en double aveugle. Suivi hebdomadaire par OMAS et EVA jusqu'à guérison ou deux semaines après la radiothérapie.\n\nLa douleur baisse dès la première semaine, le score OMAS à partir de la troisième. Le site tumoral primitif était le facteur prédictif de guérison. C'est un des rares essais contrôlés en traitement curatif.","l3":{"points":["163 patients sélectionnés, 53 analysés (deux lésions comparables).","Guérison complète : 52,4 % contre 11,9 % (p < 0,001).","Facteur prédictif : site du cancer primitif (ORa 5,78)."],"limites":["Effet de diffusion possible entre lésions d'une même bouche.","Forte sélection (53 sur 163)."],"pratique":"Soutient la PBM en traitement curatif de la mucite radio-induite installée, deux séances par semaine."},"topic":"mucite-orale","title":"Therapeutic effect of Photobiomodulation therapy on radiation-induced oral mucositis in head and neck Cancer: A prospective double-blind, self-controlled clinical trial.","journal":"Radiotherapy and oncology : journal of the European Society for Therapeutic Radiology and Oncology","journal_abbr":"Radiother Oncol","authors":["Ameri A","Lesan M","Vafaei V","et al."],"date":"2026-03-20","year":2026,"week":"2026-S12","doi":"10.1016/j.radonc.2026.111495","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis (OM) is a common and painful complication in patients with head and neck cancer (HNC) undergoing radiotherapy or chemoradiotherapy. Photobiomodulation therapy (PBMT) historically referred to as low-level laser therapy (LLLT) has been suggested as a treatment for reducing OM severity and pain."},{"label":"METHODS","text":"In this prospective, double-blind clinical trial, 163 patients were screened, and 53 patients with two comparable OM lesions were ultimately included in the analysis. One lesion received PBMT (660 nm, 150 mW, 5 J per point, twice weekly), and the other received sham treatment as control. Lesion severity and pain were assessed weekly using the Oral Mucositis Assessment Scale (OMAS) and the Visual Analog Scale (VAS) until complete healing or two weeks after radiotherapy."},{"label":"RESULTS","text":"PBMT significantly reduced OMAS and VAS scores compared to control lesions. VAS reduction was observed from the first week, whereas OMAS decreased from week three. Complete healing occurred in 52.4% of intervention lesions versus 11.9% of control lesions (P < 0.001). PBMT accelerated recovery without adverse effects. According to multivariable regression analysis, Primary cancer site was the independent predictive factor of healing of radiation-induced oral mucositis following PBMT (aOR 5.78, 95% CI 1.28-36.0, P = 0.03)."},{"label":"CONCLUSIONS","text":"PBMT was associated with a significant reduction in pain and lesion severity in patients with radiation-induced oral mucositis undergoing head and neck radiotherapy. These findings support its potential therapeutic role as a supportive care intervention."}],"keywords":["Head and neck cancer","Oral mucositis","Photobiomodulation therapy","Quality of life","Radiotherapy"]},{"pmid":"41841486","title_fr":"Moins de morphine grâce à la PBM en ORL : cohorte appariée de 280 cas","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","extrabuccal","LED","laser"],"nm":[660,810],"n":280,"effect":"mitigé","theme":"Douleur","key":true,"metric":{"kind":"values","outcome":"Morphine en fin de RT (mg/j)","a_label":"PBM","a":22.9,"b_label":"Témoins","b":37.4,"unit":"mg/j"},"l1":"Cohorte française appariée (280 patients) : la PBM préventive diminue la morphine en fin de radiothérapie (22,9 contre 37,4 mg/j) mais pas la fréquence des mucites de grade 3–4 (63 % dans les deux groupes).","l2":"Patients opioïdo-naïfs traités pour cancer de la cavité buccale ou de l'oropharynx. PBM trois fois par semaine par des manipulateurs : 660 nm intrabuccal (2,25 J/cm²) et LED 810 nm extrabuccale (6 J/cm²) sur la zone pharyngolaryngée. Témoins historiques (2012–2019) appariés 1:1 sur le site tumoral, le traitement systémique et la chirurgie.\n\nLa morphine est réduite en fin de radiothérapie et à un mois (10,3 contre 27,2 mg/j) ; 60 % des patients PBM n'ont pas eu besoin de morphine contre 47 %. Le taux de mucite sévère est identique. La PBM agirait donc d'abord sur la douleur, un résultat important pour le choix des critères de jugement.","l3":{"points":["280 patients ; 45 % cavité buccale ; 43 % en postopératoire ; 42 % sans traitement systémique.","Morphine : 22,9 contre 37,4 mg/j (p = 0,002) ; à M1 : 10,3 contre 27,2 (p = 0,0001).","Mucite G3–4 : 63 % contre 63 % ; survie sans mucite G3–4 identique (p = 0,99).","Bénéfice plus marqué en oropharynx, en radiothérapie exclusive et avec traitement concomitant."],"limites":["Témoins historiques (évolution possible des pratiques antalgiques).","Non randomisé."],"pratique":"La PBM préventive peut réduire l'usage d'opioïdes même quand le grade de mucite ne change pas : suivre la douleur et la consommation d'antalgiques, pas seulement le grade."},"topic":"mucite-orale","title":"Reduced Morphine Consumption with Photobiomodulation in Head and Neck Cancer: A Matched Cohort of 280 Cases.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Giraud N","Delhiat AC","Lafitte A","et al."],"date":"2026-03-17","year":2026,"week":"2026-S12","doi":"10.1177/25785478261432857","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"INTRODUCTION","text":"Radiation-induced oral mucositis (RIOM) may cause severe pain and impaired quality of life during head and neck radiotherapy (RT). Preventive photobiomodulation (PBM) has shown promising clinical benefits."},{"label":"MATERIALS AND METHODS","text":"Eligible patients had oropharyngeal or oral cavity cancer and were opioid-naïve at the start of curative-intent RT. Patients in the PBM group were treated between 2020 and 2023. PBM was applied to the entire oral mucosa at 2.25 J/cm2 (λ = 660 nm). Extraoral PBM was delivered using an LED cluster device at 6 J/cm2 (λ = 810 nm) to target the pharyngolaryngeal mucosa. PBM was administered three times per week by trained radiation therapists. A historical control cohort treated between 2012 and 2019 was matched 1:1 based on tumor site, concurrent systemic therapy, and prior surgery. The primary objective was to evaluate differences in daily morphine consumption at the end of RT according to the preventive use of thrice-weekly oral PBM in patients receiving curative-intent RT for head and neck cancer."},{"label":"RESULTS","text":"A total of 280 patients were included: 45% had oral cavity cancers, 43% were treated postoperatively, and 42% received RT without systemic therapy. Morphine use was significantly lower in the PBM group at the end of RT (22.9 vs. 37.4 mg/day; p = 0.002) and 1 month post-RT (10.3 vs. 27.2 mg/day; p = 0.0001). No morphine was required in 60% of PBM patients compared with 47% of controls. PBM appeared particularly beneficial in oropharyngeal cancer, in patients receiving definitive RT, and with concurrent treatment. In contrast, rates of grade 3-4 RIOM at the end of RT were identical (63% in both groups), and grade 3-4 mucositis-free survival did not differ (p = 0.99)."},{"label":"CONCLUSION","text":"In this large matched cohort, preventive PBM reduced morphine consumption during and after RT, supporting its use to alleviate RIOM-related pain in head and neck cancer patients."}],"keywords":["head and neck cancer","morphine consumption","oral mucositis","photobiomodulation","radiotherapy"]},{"pmid":"41776117","title_fr":"Prise en charge de la mucite en greffe de cellules souches en Australie et Nouvelle-Zélande (enquête CAN EAT)","type":"survey","level":0,"pop":"mixte","ctx":["CSH"],"aim":"prévention","mode":[],"nm":[],"n":24,"effect":"—","theme":"Implantation","l1":"Dans 24 centres de greffe australiens et néo-zélandais, la PBM est rarement utilisée (coût, accès) car les recommandations nationales EviQ ne l'incluent pas, contrairement à MASCC/ISOO.","l2":"Enquête auprès des infirmières spécialisées de 41 hôpitaux (taux de réponse 59 %). Soins de bouche (100 %) et cryothérapie avec melphalan (96 %) sont quasi universels ; PBM et palifermine restent marginales.\n\nLes recommandations EviQ (67 %) sont plus suivies que celles de MASCC/ISOO (17 %). Les auteurs plaident pour réévaluer la faisabilité de la PBM et harmoniser les recommandations.","l3":{"points":["Outils : échelle OMS (42 %), scores de douleur (46 %), EviQ (42 %).","Douleur : opioïdes à la demande (100 %), PCA (58 %)."],"limites":["Enquête déclarative, 24 centres."],"pratique":"Illustre l'écart entre recommandations internationales et pratique ; le coût et l'accès freinent la PBM."},"topic":"mucite-orale","title":"Oral mucositis management in hematopoietic cell transplantation in Australia and New Zealand (CAN EAT Survey).","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Munro E","Gavin NC","Nakagaki M"],"date":"2026-03-03","year":2026,"week":"2026-S10","doi":"10.1007/s00520-026-10423-5","pmcid":"PMC12956983","license":"cc by","oa":true,"pdf":"pdfs/41776117.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"The Multinational Association of Supportive Care in Cancer and the International Society of Oral Oncology (MASCC/ISOO) has published evidence-based international guidelines for the management of oral mucositis (OM). However, adherence to these guidelines has not been evaluated. This survey assessed OM management in hematopoietic cell transplantation (HCT) centers in Australia and New Zealand."},{"label":"METHODS","text":"Specialist nurses in 41 transplant hospitals were invited to complete a survey. Questions covered general unit information, oral assessment (tools, assessors, frequency), prevention strategies (guidelines, oral care, cryotherapy, photobiomodulation, palifermin, and barriers to use), and treatment strategies (pain management and nutritional support)."},{"label":"RESULTS","text":"Of 41 hospitals, 24 (59%) responded. All but one responder were specialized nurses. Oral assessment was primarily conducted by nurses (100%) and doctors (80%). The most commonly used tools were the World Health Organization grading scale (42%), pain scores (46%), and EviQ (Australian online cancer resource) (42%). EviQ guidelines (67%), which exclude palifermin and photobiomodulation, followed by institutional guidelines (29%) and MASCC/ISOO guidelines (17%). Oral care (100%) and cryotherapy with melphalan (96%) were widely adopted, while photobiomodulation and palifermin were rarely used due to cost and access barriers. For OM-related pain, as-needed opioids (100%), patient-controlled analgesia (58%), and topical analgesics (46%) were common. When OM impaired oral intake, supportive measures included supplemental drinks (88%), enteral nutrition (50%), and parenteral nutrition (67%)."},{"label":"CONCLUSION","text":"In Australia and New Zealand, national EviQ guidelines are used more often than the MASCC/ISOO guidelines. Feasibility for implementing palifermin and photobiomodulation should be reassessed, and greater collaboration in developing guidelines is necessary."}],"keywords":["Assessment","Oral mucositis","Prevention","Survey","Treatment"]},{"pmid":"41760795","title_fr":"La PBM prévient-elle la mucite chez les patients d'hématologie sous chimiothérapie ? Revue systématique d'essais randomisés","type":"sr","level":1,"pop":"mixte","ctx":["chimio"],"aim":"prévention","mode":["laser"],"nm":[660],"n":200,"effect":"favorable","theme":"Synthèse des preuves","l1":"Six essais randomisés (1997–2024, 200 patients) en hématologie : la PBM préventive, presque toujours en lumière rouge, réduit la fréquence de la mucite et la douleur.","l2":"Revue avec évaluation du risque de biais (Cochrane) et de la certitude (GRADE) sur six bases dont LILACS. Les six essais utilisent le rouge, un seul y ajoute l'infrarouge.\n\nLa PBM diminue la fréquence de la mucite et la douleur et améliore la qualité de vie. Le résumé ne chiffre ni l'effet poolé ni le niveau GRADE.","l3":{"points":["6 ECR, 200 patients, comparateurs non laser."],"limites":["Petit effectif total ; essais anciens (depuis 1997).","Niveau GRADE non précisé dans le résumé."],"pratique":"Va dans le sens des recommandations pour la chimiothérapie à haute dose en hématologie."},"topic":"mucite-orale","title":"Is photobiomodulation an effective preventive strategy for oral mucositis in patients with hematologic diseases undergoing chemotherapy?: A systematic review of randomized controlled trials.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Xavier MGA","de Mendonça Silva AMS","de Oliveira GRW","et al."],"date":"2026-02-27","year":2026,"week":"2026-S09","doi":"10.1007/s10103-026-04814-7","pmcid":"PMC12948774","license":"cc by","oa":true,"pdf":"pdfs/41760795.pdf","cited_by":0,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"Purpose to conduct a systematic review to assess whether photobiomodulation is effective in preventing oral mucositis in patients with hematologic diseases undergoing chemotherapy. Methods: A systematic search was conducted in the Embase, Medline/PubMed, Cochrane, Scopus, Web of Science and LILACS databases. The strategy included selected randomized clinical trials that evaluated the prevention of oral mucositis, directly comparing the use of photobiomodulation for chemotherapy-induced oral mucositis in patients with hematologic diseases with alternative non-laser therapies. The risk of bias in the studies was assessed using the Cochrane Collaboration’s tool for assessing risk of bias and the certainty of evidence was assessed using GRADE. Results: After applying all predetermined criteria, six randomized clinical trials, dated between 1997 and 2024, were included. A total of 200 patients were evaluated, with all six studies using the red wavelength, with only one study using a combination with the infrared wavelength. It was observed that photobiomodulation can be effective in preventing oral mucositis, reducing its frequency. Furthermore, a reduction in pain intensity and an improvement in quality of life were also identified. Conclusion: The use of photobiomodulation shows promising results in preventing oral mucositis, consequently reducing the frequency and pain of patients with hematologic diseases undergoing chemotherapy."}],"keywords":["Chemotherapy","Hematologic diseases","Oral mucositis","Photobiomodulation"]},{"pmid":"41715303","title_fr":"Revue critique (scoping) de la PBM extrabuccale pour la mucite en oncologie","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["extrabuccal"],"nm":[],"n":null,"effect":"mitigé","theme":"Extra vs intrabuccal","l1":"Neuf études sur la PBM extrabuccale exclusive, dont un seul essai la comparant à l'intrabuccale (sans différence) : prometteuse et rapide, mais preuves encore limitées.","l2":"Revue exploratoire classant les études selon l'Oxford CEBM : 3 de niveau 2, 6 de niveau 4. Le seul essai randomisé extra contre intrabuccal ne trouvait pas de différence ; face au placebo ou à l'absence de traitement, les résultats étaient mitigés.\n\nRecherche antérieure aux essais publiés fin 2025 et en 2026 qui renforcent l'extrabuccal, notamment en pédiatrie.","l3":{"points":["9 études ; OCEBM : 3 niveau 2, 6 niveau 4.","Avantage : séances plus courtes, accès plus facile."],"limites":["Peu d'études, designs hétérogènes."],"pratique":"À relire avec les essais de 2025–2026 (Brésil, pédiatrie, ORL) qui ont depuis enrichi le dossier."},"topic":"mucite-orale","title":"A Critical Scoping Review of Extraoral Photobiomodulation for Oral Mucositis in Oncological Patients.","journal":"Special care in dentistry : official publication of the American Association of Hospital Dentists, the Academy of Dentistry for the Handicapped, and the American Society for Geriatric Dentistry","journal_abbr":"Spec Care Dentist","authors":["Monteiro JLGC","Martins MD","Treister NS","et al."],"date":"2026-02-20","year":2026,"week":"2026-S08","doi":"10.1111/scd.70145","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Scoping Review"],"abstract":[{"label":"AIMS","text":"Oral mucositis (OM) is a potentially severe side effect of oncological treatment. This study aimed to conduct a comprehensive scoping review of extraoral photobiomodulation (EOPBM) in the treatment or prevention of OM in oncologic patients. Studies were categorized according to the Oxford Centre for Evidence-Based Medicine (OCEBM) recommendations."},{"label":"METHODS","text":"A search was conducted in three databases for comparative or non-comparative studies. There were no language or publication year restrictions."},{"label":"RESULTS","text":"The review included nine studies, with varying levels of evidence. Three studies were categorized as OCEBM level 2, and six as level 4. While EOPBM offered advantages, such as shorter session durations and potentially more accessible light application, the review found limited evidence for its exclusive use in preventing or treating OM. It included a single randomized controlled trial (RCT) comparing EOPBM with IOPBM, which found no significant differences between the groups in OM development or severity. Additionally, studies comparing EOPBM with sham sessions, placebo, or no treatment yielded mixed results."},{"label":"CONCLUSIONS","text":"EOPBM shows promise in preventing OM in oncological patients, with some advantages such as shorter session durations. However, the current level of evidence for exclusive EOPBM protocols remains limited."}],"keywords":["chemotherapy","low‐level light therapy","oral mucositis","radiotherapy"]},{"pmid":"41647299","title_fr":"Interventions contre la mucite et qualité de vie des patients atteints de cancer : revue parapluie","type":"umbrella","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Qualité de vie","l1":"Huit revues systématiques (257 études) : PBM, miel, mûre noire et SAMITAL améliorent de façon constante la qualité de vie liée à la mucite.","l2":"Revue parapluie (PRISMA 2020, JBI, AMSTAR 2, PROSPERO) limitée aux revues mesurant la qualité de vie avec des outils validés (EORTC QLQ-C30, FACT-HN, UW-QOL).\n\nLa PBM figure parmi les interventions qui améliorent douleur, fonction buccale et bien-être émotionnel. La gabapentine réduit les opioïdes avec des résultats variables. L'hétérogénéité des instruments limite les comparaisons.","l3":{"points":["8 revues, 257 études primaires ; recherche jusqu'en mars 2024."],"limites":["Instruments de qualité de vie très variés."],"pratique":"Inclure systématiquement des critères de qualité de vie dans le suivi des patients traités par PBM."},"topic":"mucite-orale","title":"Therapeutic Interventions to Manage Oral Mucositis and Their Impact on Quality of Life in Cancer Patients: An Umbrella Review.","journal":"Pain research & management","journal_abbr":"Pain Res Manag","authors":["de Sousa Gomes Costa JL","Díaz L","Chaple Gil A","et al."],"date":"2026-02-03","year":2026,"week":"2026-S06","doi":"10.1155/prm/3601001","pmcid":"PMC12868910","license":"cc by","oa":true,"pdf":"pdfs/41647299.pdf","cited_by":0,"pub_types":["Systematic Review"],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis (OM) is a debilitating complication of cancer therapy, particularly in head and neck cancer patients, with significant adverse effects on quality of life (QoL). Although numerous interventions have been investigated, their impact on QoL remains inconsistently reported and poorly synthesized."},{"label":"METHODS","text":"An umbrella review was conducted following PRISMA 2020 and Joanna Briggs Institute (JBI) guidelines. Five databases (PubMed, Embase, Scopus, Web of Science, and Cochrane Library) were searched from inception to March 2024. Reviews were eligible if they evaluated any therapeutic intervention for OM and reported QoL-related outcomes using validated tools. Methodological quality was appraised using AMSTAR 2, and findings were narratively synthesized and thematically categorized. The protocol was registered in PROSPERO (CRD420251044088)."},{"label":"RESULTS","text":"Eight systematic reviews (257 primary studies) met the inclusion criteria. Photobiomodulation, honey, black mulberry, and botanical agents such as SAMITAL showed consistent improvement in QoL domains, including pain relief, oral function, and emotional well-being. Gabapentin demonstrated potential in reducing opioid use and early mucositis-related pain, though findings were mixed across trials. QoL was most commonly assessed using the EORTC QLQ-C30, FACT-HN, and UW-QOL. Overall, heterogeneity in intervention protocols and QoL instruments limited comparability."},{"label":"CONCLUSIONS","text":"This review highlights the most promising interventions for improving QoL in patients with OM. Standardizing QoL measurement and prioritizing patient-reported outcomes in future trials is essential to inform evidence-based supportive oncology care."}],"keywords":["cancer treatment","gabapentin","oral mucositis","patient-reported outcomes","photobiomodulation","quality of life","supportive care","umbrella review"]},{"pmid":"41622096","title_fr":"Mucite et xérostomie radio-induites en ORL : revue des essais de phase III–IV","type":"review","level":5,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue des essais de phase III et IV terminés sur ClinicalTrials.gov : pour la mucite, le laser basse énergie fait partie des options non médicamenteuses utiles, aux côtés du miel et de l'aloe vera.","l2":"Côté médicaments, palifermine, avasopasem, doxépine, bain de bouche à la morphine et gabapentine ressortent pour la mucite ; pilocarpine, amifostine et céviméline pour la xérostomie.\n\nL'hétérogénéité des plans d'étude limite les conclusions.","l3":{"points":["Source : essais enregistrés et terminés (phase III–IV)."],"limites":["Revue non systématique au sens PRISMA."],"pratique":"Situe la PBM dans l'arsenal global."},"topic":"mucite-orale","title":"Clinical evidence for managing radiotherapy-induced oral mucositis and xerostomia in head and neck cancer patients: a review of Phase III-IV trials.","journal":"International journal of oral and maxillofacial surgery","journal_abbr":"Int J Oral Maxillofac Surg","authors":["Alsahafi E"],"date":"2026-01-31","year":2026,"week":"2026-S05","doi":"10.1016/j.ijom.2026.01.020","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Review"],"abstract":[{"label":"","text":"Oral Mucositis and xerostomia are common debilitating side effects of radiotherapy in head and neck cancer patients, leading to treatment interruptions and negatively impacting quality of life. This review was performed to examine the efficacy and safety of interventions for managing these complications, evaluated in completed Phase III and IV clinical trials registered on ClinicalTrials.gov. A range of pharmacological and non-pharmacological therapies were reviewed, with analysis of intervention types, outcomes, and sample sizes. For oral mucositis, effective pharmacological agents included palifermin, avasopasem manganese, doxepin, morphine mouthwash, and gabapentin, while non-pharmacological options such as low-level laser therapy, honey, and Aloe vera showed additional benefit in reducing severity and improving healing. In managing radiotherapy-induced xerostomia, pilocarpine, amifostine, and cevimeline significantly enhanced salivary function, with adaptive radiotherapy techniques offering protective effects on the salivary glands. Phase IV studies supported the role of benzydamine, MuGard, Biotène, and herbal mouthwashes in symptom relief and patient comfort. Although several interventions demonstrated promising clinical efficacy, the heterogeneity in study design, outcome measures, and follow-up duration limits definitive conclusions. Therefore, customized, evidence-driven approaches informed by existing recommendations and developed data are crucial for enhancing outcomes and reducing the burden of therapy-induced toxicities in head and neck cancer patients."}],"keywords":["Clinical trial","Head and neck neoplasms","Oral mucositis","Radiotherapy","Xerostomia"]},{"pmid":"41584371","title_fr":"Interventions contre la mucite chimio- et radio-induite : revue systématique et méta-analyse","type":"ma","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"27 articles (2019–2024) : cryothérapie et PBM, ainsi que des agents naturels (miel, curcuma, thé vert), sont efficaces pour prévenir et traiter la mucite.","l2":"Méta-analyse croate couvrant interventions médicamenteuses et non médicamenteuses. Le résumé ne donne pas d'estimation chiffrée par intervention.\n\nContribution modeste par rapport aux méta-analyses spécifiques de la PBM.","l3":{"points":["27 articles, 2019–2024."],"limites":["Résultats non chiffrés dans le résumé ; designs inclus non précisés."],"pratique":"Pas d'apport spécifique sur la PBM."},"topic":"mucite-orale","title":"Interventions to Chemotherapy and Radiotherapy Induced Oral Mucositis: a Systematic Review and Meta-analysis.","journal":"Acta stomatologica Croatica","journal_abbr":"Acta Stomatol Croat","authors":["Pereira CP","Marques I","Martins JP"],"date":"2026-01-26","year":2026,"week":"2026-S05","doi":"10.15644/asc59/4/6","pmcid":"PMC12826651","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41584371.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"INTRODUCTION","text":"Oral mucositis is a common adverse effect of chemotherapy and radiotherapy, characterized by erythematous lesions, edema, ulceration, atrophy, or even hemorrhage. Current evidence highlights the complexity of its management and the importance of tailoring therapeutic approaches to the individual patient profile in order to improve quality of life during cancer treatment."},{"label":"OBJECTIVES","text":"To access the efficacy of pharmacological and non-pharmacological interventions for the prevention and treatment of chemotherapy- and/or radiotherapy-induced oral mucositis."},{"label":"MATERIALS AND METHODS","text":"A systematic review with meta-analysis of 27 articles published between 2019 and 2024 was also performed, aiming to characterize and contextualize therapeutic interventions for oral mucositis."},{"label":"RESULTS AND DISCUSSION","text":"This systematic review and meta-analysis suggests that various non-pharmacological interventions (such as cryotherapy and photobiomodulation) and pharmacological interventions, particularly natural agents (such as honey, curcumin, green tea), are effective for the prevention and treatment of oral mucositis."},{"label":"CONCLUSION","text":"Oral mucositis is a highly prevalent adverse effect in patients undergoing chemotherapy and/or radiotherapy, with significant functional, nutritional, and treatment adherence implications. The systematic review with meta-analysis demonstrated the efficacy of non-pharmacological and natural interventions."}],"keywords":["Chemotherapy","Curcuma","Drug Therapy","Herbal Teas","Honey","MeSH Terms: Stomatitis","Non-pharmacological interventions","Oral mucositis","Pharmacologic Actions","Pharmacological treatment"]},{"pmid":"41410110","title_fr":"Laser et mucite : revue parapluie, recommandations officielles de la Société polonaise de dentisterie laser","type":"umbrella","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["intrabuccal","extrabuccal","PDT"],"nm":[630,670,780,850],"n":null,"effect":"favorable","theme":"Recommandations","key":true,"l1":"Synthèse de 22 revues servant de recommandations officielles en Pologne : la PBM préventive réduit de 40 à 80 % la mucite sévère et la PBM curative raccourcit les ulcères de 4 à 7 jours.","l2":"Revue parapluie (PRISMA 2020, JBI) des revues et méta-analyses publiées jusqu'en juillet 2025. La PBM diminue l'incidence, la sévérité, la douleur et la durée de cicatrisation, chez l'adulte comme chez l'enfant. L'association avec la thérapie photodynamique améliore encore la cicatrisation.\n\nParamètres retenus comme optimaux : 630–670 nm en intrabuccal, 780–850 nm en extrabuccal, 2 à 6 J/cm². Aucun effet indésirable grave. La société savante fait de la PBM un soin de support standard, en particulier en greffe de cellules souches et en chimioradiothérapie ORL.","l3":{"points":["22 revues incluses (PubMed, Embase, Scopus, Cochrane).","Prévention : −40 à −80 % de mucites de grade 3–4 ; traitement : ulcères raccourcis de 4 à 7 jours.","Fenêtre dosimétrique : 2–6 J/cm²."],"limites":["Qualité des revues incluses non détaillée dans le résumé.","Recommandation nationale de société savante, pas d'analyse GRADE indiquée."],"pratique":"Donne une fenêtre de paramètres concrète, utile pour écrire un protocole de service."},"topic":"mucite-orale","title":"Laser therapy for the management of oral mucositis: An umbrella review - official recommendations of the Polish Society for Laser Dentistry.","journal":"Dental and medical problems","journal_abbr":"Dent Med Probl","authors":["Grzech-Leśniak K","Fiegler-Rudol J","Grzech-Leśniak Z","et al."],"date":"2025-12-18","year":2025,"week":"2025-S51","doi":"10.17219/dmp/213958","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":3,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"Oral mucositis (OM) is a common and debilitating side effect of cancer therapy that impairs nutrition, increases infection risk, and often disrupts oncologic treatment. Photobiomodulation therapy (PBMT) has emerged as an effective, non-invasive method for OM prevention and management.This umbrella review was conducted in accordance with the Preferred Reporting Items for Systematic reviews and Meta-Analyses (PRISMA) 2020 guidelines and the Joanna Briggs Institute (JBI) methodology. A comprehensive search of PubMed®/MEDLINE, Embase, Scopus, and Cochrane Library identified systematic reviews and meta-analyses on laser therapy for OM published through July 2025. The data extraction process centered on clinical outcomes, laser parameters and safety.Twenty-two reviews met the inclusion criteria. Photobiomodulation therapy significantly reduced the incidence of OM, disease severity, pain, and healing time across adult and pediatric populations. Preventive PBMT decreased the risk of severe OM (grade 3-4) by 40-80%, while therapeutic PBMT shortened ulcer duration by 4-7 days. The combination of PBMT and photodynamic therapy (PDT) enhanced mucosal healing and alleviated pain. Optimal outcomes were achieved when wavelengths of 630-670 nm (intraoral) and 780-850 nm (extraoral) were used, with fluences of 2-6 J/cm2. No serious adverse events were reported.Photobiomodulation therapy demonstrates strong efficacy and safety in the management of OM, improving quality of life and treatment continuity in oncology patients. The Polish Society for Laser Dentistry (PTSL) endorses PBMT as a standard supportive care modality, particularly in the context of hematopoietic stem cell transplantation (HSCT) and head and neck chemoradiation. Protocol adherence and parameter standardization are essential to ensure the reproducibility and clinical effectiveness of research findings."}],"keywords":["cancer therapy","head and neck cancer","hematopoietic stem cell transplantation","low-level laser therapy","photobiomodulation"]},{"pmid":"41394293","title_fr":"Gel mucoadhésif d'Arrabidaea chica contre laser basse énergie pour cicatriser la mucite en greffe de moelle : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["CSH"],"aim":"traitement","mode":["laser"],"nm":[],"n":44,"effect":"défavorable","theme":"Comparateurs actifs","metric":{"kind":"values","outcome":"Délai de cicatrisation (jours)","a_label":"Gel A. chica","a":5.2,"b_label":"Laser (témoin)","b":11.2,"unit":"j"},"l1":"Chez 44 greffés, un gel à base d'Arrabidaea chica a fait cicatriser la mucite deux fois plus vite que le laser basse énergie (5,2 contre 11,2 jours).","l2":"Essai brésilien (UNICAMP, 2022–2024) ouvert, en groupes parallèles. Le laser servait ici de comparateur de référence. 38 patients ont terminé l'étude.\n\nLe gel a raccourci nettement le délai de guérison, avec parfois une légère sensation de brûlure. C'est un des rares essais où la PBM fait moins bien qu'un comparateur actif, mais il est ouvert et petit.","l3":{"points":["Randomisation 22/22 ; 20 et 18 patients analysés.","Délai de cicatrisation : 5,2 ± 1,5 contre 11,2 ± 6,5 jours."],"limites":["Essai ouvert ; paramètres laser non détaillés dans le résumé.","Forte dispersion dans le groupe laser."],"pratique":"Signal à confirmer ; ne remet pas en cause la PBM préventive, mais questionne sa place en curatif face à certains topiques."},"topic":"mucite-orale","title":"Healing Oral Mucositis With Arrabidaea chica Verlot Mucoadhesive Gel in Patients Undergoing Hematopoietic Stem Cell Transplantation: A Randomized Controlled Clinical Trial.","journal":"BioMed research international","journal_abbr":"Biomed Res Int","authors":["de Cássia Almeida Queiroz N","de Oliveira Sousa IM","Júnior RJM","et al."],"date":"2025-12-12","year":2025,"week":"2025-S50","doi":"10.1155/bmri/3700170","pmcid":"PMC12699320","license":"cc by","oa":true,"pdf":"pdfs/41394293.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"INTRODUCTION","text":"Oral mucositis affects up to 80% of patients undergoing bone marrow transplantation, causing painful ulcers, increased infection risk, and impaired quality of life. Current treatments are mainly palliative, highlighting the need for new therapeutic options. Arrabidaea chica Verlot extract has shown wound healing potential through antioxidant activity and collagen synthesis promotion in vitro and significant wound area reduction in vivo."},{"label":"OBJECTIVE","text":"The objective of the study is to evaluate the wound healing potential of a mucoadhesive gel containing 2.5% A. chica extract for treating oral mucositis in oncohematological patients undergoing bone marrow transplantation."},{"label":"METHODS","text":"This was a randomized, controlled, open-label, parallel-group clinical trial conducted at HC/UNICAMP from October 2022 to November 2024. Forty-four patients were randomized to the intervention group (mucoadhesive A. chica gel, n = 22) or control group (low-intensity laser therapy, n = 22). The primary outcome was the time to healing of oral mucositis. Statistical analysis compared mean healing times between groups."},{"label":"RESULTS","text":"Twenty participants in the intervention group and 18 in the control group completed the study. Mean healing time was 5.2 ± 1.5 days for the intervention group and 11.2 ± 6.5 days for the control group, representing a 2.2-fold faster healing with A. chica gel. Some intervention participants reported a mild burning sensation, without affecting treatment adherence or efficacy."},{"label":"CONCLUSION","text":"The mucoadhesive gel containing A. chica extract proved to be a safe and effective therapeutic option for treating oral mucositis in patients undergoing bone marrow transplantation."},{"label":"TRIAL REGISTRATION","text":"ReBEC number: RBR-5×4397."}],"keywords":["Arrabidaea chica","Fridericia chica","healing","oral mucositis"]},{"pmid":"41657588","title_fr":"La PBM en odontologie : mécanismes, applications cliniques et recommandations","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Courte revue générale : la PBM agit via les chromophores mitochondriaux et l'inflammation ; la mucite fait partie des indications soutenues par les preuves.","l2":"Revue brève des mécanismes (stimulation mitochondriale, régulation des cytokines, facteurs de croissance) et des indications dentaires : mucite, troubles temporo-mandibulaires, parodontite, douleur endodontique, implants, orthodontie.\n\nSans données nouvelles.","l3":{"points":["Revue pédagogique."],"limites":["Résumé très court, méthode non décrite."],"pratique":"Aucune conséquence pratique."},"topic":"mucite-orale","title":"Photobiomodulation in dentistry: Mechanisms, clinical applications and evidence-based guidelines.","journal":"Bioinformation","journal_abbr":"Bioinformation","authors":["Eltahir L","Elgendy M","Ali G","et al."],"date":"2025-11-15","year":2025,"week":"2025-S46","doi":"10.6026/973206300214203","pmcid":"PMC12880127","license":"cc by","oa":true,"pdf":"pdfs/41657588.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation (PBM), formerly known as low-level laser therapy (LLLT), utilizes red and near-infrared light to activate mitochondrial chromophores, thereby enhancing cellular activity, modulating inflammation and promoting tissue repair. Therefore, it is of interest to the mechanistic pathways of PBM, including mitochondrial stimulation, cytokine regulation and growth factor induction. Clinical evidence supports its efficacy in managing oral mucositis, temporomandibular disorders, periodontitis, postoperative endodontic pain, implant stability and orthodontic treatment outcomes."}],"keywords":["PBM safety","Photobiomodulation","dental implants","endodontics","laser therapy","low-level laser therapy","oral mucositis","orthodontics","pain management","periodontitis"]},{"pmid":"41239052","title_fr":"Soins buccaux structurés incluant la PBM et mucite sous 5-fluorouracile : cohorte rétrospective","type":"cohort","level":4,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":[],"nm":[],"n":69,"effect":"favorable","theme":"Vie réelle","l1":"Chez 69 patients sous 5-FU, un programme de soins buccaux avec deux séances de PBM par cycle limite les mucites sévères à 7,2 % ; le bénéfice est marqué sous FOLFIRINOX.","l2":"Cohorte monocentrique brésilienne (2020–2022) de tumeurs solides : bilan dentaire, hygiène, contrôle des infections et PBM les deux premiers jours de chaque cycle.\n\nTous les patients ont eu une mucite, surtout de grade 1 (40,6 %) ou 2 (52,2 %). Deux séances de PBM étaient associées à une apparition plus tardive, une sévérité et une durée moindres, avec un risque divisé par 9,1 sous FOLFIRINOX. Le FOLFOX donnait des mucites plus précoces et plus sévères.","l3":{"points":["Grade 3 : 7,2 % ; aucun grade 4 rapporté.","FOLFIRINOX : risque divisé par 9,1 avec deux séances."],"limites":["Rétrospectif, sans groupe sans PBM ; enregistrement rétrospectif."],"pratique":"Argument pour intégrer la PBM aux soins buccaux dès le début des chimiothérapies à base de 5-FU."},"topic":"mucite-orale","title":"Impact of structured oral care strategies on oral mucositis in patients receiving 5-fluorouracil: a retrospective cohort study.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Eduardo FP","Ferreira MH","Gobbi MF","et al."],"date":"2025-11-14","year":2025,"week":"2025-S46","doi":"10.1007/s00520-025-10079-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"Oral mucositis (OM) is a frequent and debilitating complication of 5-fluorouracil (5-FU)-based chemotherapy, compromising patients' quality of life and treatment adherence. This study aimed to evaluate the impact of a structured oral care strategy (OCS), including photobiomodulation (PBM), on the severity, onset, and duration of OM in patients with solid tumors receiving 5-FU-based regimens."},{"label":"METHODS","text":"This single-center study included 69 patients treated between 2020 and 2022 and was retrospectively registered (Ethics Committee approval No. 5.089.912/2021). All participants received standardized OCS before and during chemotherapy, consisting of dental examination, oral hygiene instructions, infection control measures, and PBM. PBM was delivered once daily during the first two days of each 5-FU chemotherapy cycle. Associations were analyzed using Chi-square tests and odds ratios."},{"label":"RESULTS","text":"All patients developed OM, predominantly grade 1 (40.6%) or grade 2 (52.2%), while only 7.2% experienced grade 3 lesions. Two PBM sessions were significantly associated with reduced onset, severity, and duration of OM, particularly among patients receiving FOLFIRINOX, for whom the risk of OM decreased 9.1-fold, and among neutropenic patients (p = 0.042). Conversely, the FOLFOX regimen was associated with earlier onset (p = 0.004) and greater severity (p = 0.026); however, two PBM sessions remained beneficial, reducing OM risk 1.35-fold."},{"label":"CONCLUSION","text":"Structured OCS incorporating PBM appears to be an effective, non-invasive approach to mitigate OM severity, onset, and duration in patients undergoing 5-FU-based chemotherapy. These findings support integrating dental care and PBM into routine oncology protocols. Prospective multicenter studies are warranted to validate and standardize this strategy."}],"keywords":["5-fluorouracil","Chemotherapy","Dental care","Oral mucositis","Photobiomodulation"]},{"pmid":"41201561","title_fr":"Du cabinet au canapé : étude pilote d'une PBM à domicile contre la mucite et la radiodermite","type":"cases","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["domicile","extrabuccal"],"nm":[],"n":20,"effect":"favorable","theme":"PBM à domicile","key":true,"l1":"Une PBM proche infrarouge auto-administrée à domicile est faisable chez les patients ORL irradiés : 60 % des séances prévues réalisées, aucun effet indésirable, 41 % de mucites sévères en fin de radiothérapie.","l2":"Essai monobras (20 inclus, 17 analysés) : deux séances par jour à domicile pendant 9 à 11 semaines, du début de la radiothérapie à 4 semaines après. Le critère principal était l'observance (au moins 50 % des séances).\n\nL'objectif est atteint (67 % des patients). Mucite sévère : 6 % à la semaine 3, 41 % en fin de radiothérapie, 0 % un mois après. Radiodermite sévère : 18 % en fin de traitement. Les patients jugent l'appareil confortable et simple.","l3":{"points":["Enregistrement NCT05176834.","Observance : 60 % des séances attendues réalisées.","Mucite sévère : 41 % en fin de RT ; radiodermite sévère : 18 %."],"limites":["Monobras, sans témoin ; petit effectif.","Le taux de mucite sévère reste élevé : efficacité non démontrée."],"pratique":"Le domicile est faisable ; à réserver pour l'instant à la recherche ou en complément d'une PBM en service."},"topic":"mucite-orale","title":"From clinic to couch: a pilot study of home-use photobiomodulation for radiation-induced oral mucositis and dermatitis.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Salman S","Abdalla-Aslan R","Awawdi A","et al."],"date":"2025-11-07","year":2025,"week":"2025-S45","doi":"10.1007/s00520-025-10037-3","pmcid":"PMC12594705","license":"cc by","oa":true,"pdf":"pdfs/41201561.pdf","cited_by":0,"pub_types":["Clinical Trial"],"abstract":[{"label":"PURPOSE","text":"Radiation-induced oral mucositis (OM) and dermatitis (RD) are common debilitating toxicities of radiotherapy (RT) for head and neck cancer (HNC) patients. While photobiomodulation (PBM) has shown promise in reducing severity of these adverse effects, in-clinic treatments pose logistic and financial challenges. This study assessed the feasibility and compliance of a home-use, self-applied near-infrared PBM device for the prevention and treatment of RT-induced OM and RD."},{"label":"METHODS","text":"This prospective, single-arm trial enrolled 20 HNC patients scheduled for intensity-modulated RT (IMRT) with or without concurrent chemotherapy. Seventeen patients were analyzed following exclusions. Participants self-administered PBM at home twice daily for 9-11 weeks, from RT initiation to four weeks post-RT. The primary outcome was compliance (≥ 50% of expected treatments). Secondary outcomes included incidence of severe (grade 3-4) OM and RD."},{"label":"RESULTS","text":"67% of the participants completed at least 50% of the prescribed PBM treatments. Overall, 60% of expected sessions were administered, surpassing the predefined compliance threshold. By week 3, 6% presented with severe OM and none with severe RD. At RT completion, 41% and 18% had severe OM and RD, respectively. Four weeks post-RT, no severe OM or RD were observed, with the majority presenting with no toxicity (grade 0). No device related adverse effects were reported, and patients reported high comfort and ease of use."},{"label":"CONCLUSION","text":"Self-administered, home-use PBM is a feasible and well-tolerated approach that shows promise as pre-emptive treatment for RT induced OM and RD. Large-scale, randomized, placebo-controlled trials are needed to confirm these findings and evaluate long-term benefits."},{"label":"TRIAL REGISTRATION","text":"ClinicalTrials.gov Identifier: NCT05176834. Registration Date: December 13th, 2021."}],"keywords":["Head and neck neoplasms","Intensity-modulated radiotherapy","Low-level laser therapy","Oral mucositis","Photobiomodulation therapy","Radiation-induced dermatitis"]},{"pmid":"41133718","title_fr":"Açaï clarifié et PBM sur les glandes parotides de rats sous chimiothérapie","type":"preclinical","level":5,"pop":"—","ctx":["chimio"],"aim":"prévention","mode":["laser"],"nm":[],"n":54,"effect":"favorable","theme":"Préclinique","l1":"Chez 54 rats avec mucite induite par 5-FU, PBM et açaï protègent les parotides sur le plan biochimique (stress oxydatif) et structurel.","l2":"Cinq groupes : témoin, mucite non traitée, PBM, açaï, PBM + açaï. Analyses à J8 et J10 : capacité antioxydante, peroxydation lipidique, métabolites du NO, histologie.\n\nLes groupes traités gardent une architecture glandulaire proche des animaux sains. Première étape d'un travail poursuivi en 2026 sur la glande submandibulaire.","l3":{"points":["5-FU 60 puis 40 mg/kg, scarification jugale à J3–J4."],"limites":["Modèle animal."],"pratique":"Données mécanistiques uniquement."},"topic":"mucite-orale","title":"Effects of Clarified Açaí Supplementation and Photobiomodulation on the Parotid Glands of Rats Submitted to Chemotherapy.","journal":"Journal of oral pathology & medicine : official publication of the International Association of Oral Pathologists and the American Academy of Oral Pathology","journal_abbr":"J Oral Pathol Med","authors":["Melo WWP","Aragão WAB","Ferreira MKM","et al."],"date":"2025-10-24","year":2025,"week":"2025-S43","doi":"10.1111/jop.70072","pmcid":"PMC12774578","license":"cc by","oa":true,"pdf":"pdfs/41133718.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"The antineoplastic drugs used in anticancer treatment regimens can induce changes in normal tissues, including salivary glands. This study evaluated the effects of clarified açaí and photobiomodulation (PBM) on the oxidative biochemistry and microstructure of the parotid glands of rats with oral mucositis."},{"label":"METHODS","text":"Male rats (n = 54) were divided into five groups: Negative control (no mucositis); Positive control (mucositis without treatment); PBM; Clarified açaí; and PBM + clarified açaí. Oral mucositis was induced by intraperitoneal injection of 5-fluorouracil on days 0 (60 mg/kg) and 2 (40 mg/kg). On days 3 and 4, bilateral scarification of the buccal mucosa was performed. On days 0 (negative controls), 8 and 10 (other groups), parotid glands were collected. To evaluate oxidative biochemistry, the following analyses were performed: Antioxidant capacity test against peroxyl radicals (ACAP), Lipid Peroxidation Assay (LPO), and Nitric oxide metabolite (NOx). Additionally, histopathological, histomorphometric, and histochemical analyses were performed. Statistical analysis was performed using two-way ANOVA and Tukey's post-test (p < 0.05)."},{"label":"RESULTS","text":"Clarified açaí, alone or associated with photobiomodulation, increased antioxidant levels compared to the positive control on days 8 and 10. Regarding lipid peroxidation and nitric oxide metabolite, the positive control showed higher levels than the other groups. The morphological assessment showed that the clarified açaí and photobiomodulation groups maintained similar structures of the parenchyma, stroma, and acini to the negative control."},{"label":"CONCLUSIONS","text":"The study results demonstrated that clarified açaí and photobiomodulation conferred biochemical and structural protection to the parotid glands against chemotherapy-induced damage."}],"keywords":["Euterpe oleracea Mart.","antineoplastic drugs","parotid salivary gland","photobiomodulation"]},{"pmid":"41114890","title_fr":"Prévenir douleur et mucite sous chimiothérapie avec une source lumineuse à haute énergie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":["LED","laser"],"nm":[],"n":60,"effect":"neutre","theme":"Comparateurs actifs","l1":"Chez 60 patients sous chimiothérapie, un appareil lumineux à haute énergie (Germinator) prévient la mucite et la douleur aussi bien que le laser rouge classique.","l2":"Essai brésilien en deux groupes de 30 : protocole laser rouge basse intensité contre dispositif Germinator. Douleur (EVA) et mucite (OMS) mesurées avant et après.\n\nScores médians nuls dans les deux groupes, sans différence. Faute de groupe sans PBM et avec des taux de mucite très bas, l'essai ne permet pas de juger l'efficacité de l'un ou l'autre.","l3":{"points":["Douleur médiane 0 (EIQ 0–2) dans les deux groupes ; mucite médiane 0 (0–1)."],"limites":["Pas de bras témoin ; puissance insuffisante pour une équivalence.","Chimiothérapies hétérogènes, peu mucitogènes."],"pratique":"Pas d'argument pour changer de matériel."},"topic":"mucite-orale","title":"Prevention of pain and oral mucositis in patients undergoing chemotherapy through the use of a high-energy light source: A randomized clinical study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Souza MA","De Carli JP","De Conto AB","et al."],"date":"2025-10-20","year":2025,"week":"2025-S43","doi":"10.1007/s10103-025-04711-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Purpose This study aimed to clinically evaluate the high-energy light-emitting device (Germinator) in preventing pain and oral mucositis in patients undergoing chemotherapy. Methods Sixty patients were selected, being randomly divided into two groups(n = 30), according to preventive protocol: G1(Lasertherapy)-conventional low-intensity red laser protocol; G2(Germinator)-protocol with high-energy light-emitting device. Before and after these protocols, the pain and oral mucositis degrees were recorded by visual analog scale(VAS) for pain and World Health Organization(WHO) classification for oral mucositis. The VAS was used to assess pain symptoms, where 0 represented the absence of pain and 10 the highest pain score. The oral mucositis scoring was performed according to the WHO classification: grade 0(none), grade I(oral soreness, erythema), grade II(oral erythema, ulcers, solid and liquid diet tolerated), grade III(oral ulcers, liquid diet only), and grade IV(oral alimentation impossible). Statistical analysis was performed by Mann-Whitney U test(α = 5%), in order to provide the intergroup comparison. Results The median (interquartile range-IQR) of pain score was 0.0(0.0-2.0) for G1 group(Lasertherapy), whereas it was 0.0(0.0-2.0) for G2 group(Germinator), revealing no statistically significant differences (p > 0.05). The median(minimum and maximum value) of the oral mucositis score was 0.0(0.0-1.0) for G1 group(Lasertherapy), whereas it was 0.0(0.0-1.0) for G2 group(Germinator), also revealing no statistically significant differences (p > 0.05). Both treatments proved equally effective in preventing and controlling these symptoms in patients undergoing chemotherapy, recognizing that no statistically significant difference was found between the two preventive modalities. Conclusions The high-energy light-emitting device(Germinator) appears promising in preventing pain and oral mucositis in patients undergoing chemotherapy."}],"keywords":["Cancer","Chemotherapy","Germinator","High-energy light","Oral mucositis","Pain"]},{"pmid":"41087749","title_fr":"PBM prophylactique contre la mucite en ORL : étude observationnelle multicentrique","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":[],"nm":[],"n":118,"effect":"favorable","theme":"Facteurs de risque","l1":"Sous PBM quotidienne, 118 patients ORL irradiés ont eu 28 % de mucites sévères ; HPV positif, chimioradiothérapie et dénutrition augmentent le risque.","l2":"Étude monobras multicentrique au Brésil : bilan dentaire, nutritionnel (PG-SGA) et statut HPV avant traitement ; mucite cotée chaque jour par un stomatologue (CTCAE v5).\n\nIncidence de mucite tous grades 65,2 %, de grade 3–4 28 %. Facteurs de risque : HPV positif (OR 1,65), chimioradiothérapie (OR 1,86), risque nutritionnel (OR 2,36) ; les cancers du larynx sont moins à risque.","l3":{"points":["Mucite tous grades : 65,2 % (IC95 % 60,0–70,4) ; G3–4 : 28 %."],"limites":["Pas de groupe témoin : l'efficacité affirmée en conclusion n'est pas démontrée par ce plan."],"pratique":"Le dépistage nutritionnel aide à repérer les patients qui feront une mucite sévère malgré la PBM."},"topic":"mucite-orale","title":"Prophylactic photobiomodulation to reduce oral mucositis in head and neck cancer: an observational study.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Ferrari R","Felizardo AC","Siqueira L","et al."],"date":"2025-10-14","year":2025,"week":"2025-S42","doi":"10.1007/s00520-025-10020-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Observational Study","Multicenter Study"],"abstract":[{"label":"PURPOSE","text":"Oral mucositis (OM) is a common side effect of radiotherapy (RT) and chemoradiotherapy (CRT) in patients with head and neck cancer (HNC). This study investigates the impact of prophylactic photobiomodulation (PBM) on OM incidence in patients with HNC undergoing RT or CRT."},{"label":"METHODS","text":"This single-arm, observational study was conducted across multiple cancer centers in Brazil. Baseline assessments included clinical and radiographic dental evaluations, nutritional risk assessment via the Patient-Generated Subjective Global Assessment (PG-SGA), and HPV status determination. All patients received daily prophylactic PBM during RT. OM incidence and severity were assessed daily by a stomatologist using the Common Terminology Criteria for Adverse Events (CTCAE) Version 5.0. Descriptive statistics summarized patient characteristics, and logistic regression identified potential predictors of severe OM (grade 3+)."},{"label":"RESULTS","text":"A total of 118 patients with HNC were recruited. The cumulative incidence of OM of any grade was 65.2% (95% CI 60.0-70.4%), with severe OM (Grade 3/4) observed in 28.0% of patients. Risk factors significantly associated with OM included HPV-positive tumor status (OR = 1.65, P = 0.02), concurrent CRT (OR = 1.86, P = 0.002), and nutritional risk (OR = 2.36, P = 0.004). Tumor location also influenced OM risk, with laryngeal cancers showing a lower incidence (OR = 0.72, P = 0.02)."},{"label":"CONCLUSION","text":"Prophylactic PBM appears effective in reducing the incidence and severity of OM among patients with HNC undergoing RT or CRT. These findings support its potential role as a preventive strategy in routine clinical care."}],"keywords":["Head and neck cancer","Oral mucositis","Photobiomodulation"]},{"pmid":"41058057","title_fr":"Faisabilité d'un dispositif de laser basse énergie intégré à une gouttière pour réduire la mucite radio-induite sévère","type":"cases","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","laser"],"nm":[670,830,910],"n":15,"effect":"favorable","theme":"Nouveaux dispositifs","l1":"Une gouttière intrabuccale émettant à trois longueurs d'onde (670, 830, 910 nm) sur 43 points : 6,6 % de mucites sévères chez 15 patients irradiés, contre 30–40 % attendus.","l2":"Étude de faisabilité monobras multicentrique : séances de 20 minutes, cinq fois par semaine, sans dépendance à l'opérateur. Aucun patient n'a eu de douleur sévère, aucun effet indésirable, et tous ont terminé la radiothérapie comme prévu.\n\nPrometteur pour standardiser la délivrance, mais à confirmer par un essai randomisé.","l3":{"points":["Critère principal : mucite OMS ≥ 3 ; résultat 6,6 % (1 patient sur 15)."],"limites":["15 patients, comparaison à des taux historiques ; étude non enregistrée."],"pratique":"Concept intéressant de délivrance automatisée, pas encore validé."},"topic":"mucite-orale","title":"Feasibility Study of a Novel Stent-Based Low-Level Laser Therapy Device for Reducing Severe Radiation-Induced Oral Mucositis.","journal":"Lasers in surgery and medicine","journal_abbr":"Lasers Surg Med","authors":["Baek JY","Yang K","Lee TH","et al."],"date":"2025-10-07","year":2025,"week":"2025-S41","doi":"10.1002/lsm.70069","pmcid":"PMC12689479","license":"cc by-nc","oa":true,"pdf":"pdfs/41058057.pdf","cited_by":1,"pub_types":["Multicenter Study"],"abstract":[{"label":"OBJECTIVES","text":"Radiation-induced oral mucositis (RIOM) is a severe complication of radiotherapy (RT) for head and neck cancers, impairing quality of life and treatment adherence. Low-level laser therapy (LLLT) shows promise for reducing RIOM severity, but operator-dependent devices limit practicality. This feasibility study assessed the safety and efficacy of a novel intraoral stent-based LLLT device designed for consistent laser delivery."},{"label":"MATERIALS AND METHODS","text":"This prospective, single-arm, multicenter study enrolled 15 patients receiving curative RT for head and neck cancers. The stent-based device delivered laser light to 43 oral cavity points at three wavelengths (670, 830, and 910 nm) during 20-min sessions, five times weekly. The primary end point was the incidence of Grade 3 or higher RIOM (WHO oral mucositis scale). Pain severity was a secondary end point (Numeric Pain Rating Scale [NPRS])."},{"label":"RESULTS","text":"Grade 3 or higher RIOM occurred in 6.6% of patients, significantly lower than historical rates (30%-40%). No patients reported severe pain (NPRS ≥ 8). The device was well-tolerated with no adverse effects, and all patients completed RT as planned."},{"label":"CONCLUSIONS","text":"The intraoral stent-based LLLT device is a safe and potentially effective intervention for reducing severe RIOM. Randomized trials are warranted to confirm these findings."},{"label":"TRIAL REGISTRATION","text":"This study was a prospective, single-arm feasibility trial and was not registered in a clinical trial registry, as it did not meet the criteria for mandatory registration at the time of its initiation."}],"keywords":["feasibility studies","head and neck neoplasms","low‐level light therapy","oral mucositis","radiotherapy"]},{"pmid":"40928526","title_fr":"PBM intrabuccale versus extrabuccale pour la mucite en ORL : essai multicentrique randomisé en simple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":["intrabuccal","extrabuccal","laser"],"nm":[660,810,980],"n":58,"effect":"neutre","theme":"Extra vs intrabuccal","key":true,"l1":"Chez 58 patients ORL irradiés, la PBM extrabuccale (810/980 nm) contrôle la mucite aussi bien que l'intrabuccale (660 nm), avec moins de difficultés à avaler et un goût mieux préservé.","l2":"Essai multicentrique brésilien (2021–2023), cancers de la cavité buccale et de l'oropharynx. Intrabuccal : 660 nm, 100 mW, 3 s par point, 10 J/cm². Extrabuccal : laser superpulsé 810/980 nm, 1 W, spot de 4,91 cm², 30 s par point, 6,11 J/cm². Cinq séances par semaine.\n\nTous les patients ont eu une mucite. Pas de différence de grade (OMS p = 0,69 ; NCI p = 0,82) ni de délai d'apparition des ulcérations. Le groupe extrabuccal avalait mieux aux semaines 4 et 6 et perdait moins le goût à la semaine 5. C'est l'essai de référence en ORL sur la question extra/intrabuccal.","l3":{"points":["Enregistrement NCT05242991 ; 58 patients, âge moyen 59 ans, 69 % d'hommes.","Grade de mucite : OMS p = 0,69 ; NCI p = 0,82.","Dysphagie moindre en extrabuccal à J20 (p = 0,02) et J30 (p = 0,04) ; goût mieux préservé à J25 (p = 0,01)."],"limites":["Pas de bras sans PBM ; effectif modeste.","Comparaison qui mélange voie, longueur d'onde et puissance."],"pratique":"En radiothérapie ORL, l'extrabuccal est une option valable, notamment en cas de trismus ou de douleur à l'ouverture buccale."},"topic":"mucite-orale","title":"Intraoral vs. extraoral photobiomodulation therapy for oral mucositis in head and neck cancer patients: a multicenter, randomized, single-blind clinical trial.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Klein IP","Pinto MBR","Só BB","et al."],"date":"2025-09-10","year":2025,"week":"2025-S37","doi":"10.1007/s00520-025-09877-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":7,"pub_types":["Randomized Controlled Trial","Multicenter Study","Comparative Study"],"abstract":[{"label":"PURPOSE","text":"To compare the efficacy of intraoral (IOPBM) and extraoral photobiomodulation (EOPBM) protocols for the prevention and treatment of oral mucositis (OM) in patients with oral or oropharyngeal squamous cell carcinoma (SCC) to submitted radiotherapy (RT)."},{"label":"METHODS","text":"This randomized, blinded, multicenter clinical trial enrolled 58 patients with oral or oropharyngeal SCC, who were allocated into two groups matched by treatment type, clinical stage, and RT modality. Group I (IOPBM) received intraoral photobiomodulation (PBM) with a continuous InGaAlP diode laser (660 nm, 100 mW, 0.03 cm2 spot size, 3 s per point, fluence 10 J/cm2). Group II (EOPBM) received extraoral PBM using a superpulsed diode laser with dual wavelengths (810/980 nm, 1000 mW, 4.91 cm2 spot size, 30 s per point, fluence 6.11 J/cm2). PBM was performed five times per week during RT or until complete resolution of oral mucositis lesions."},{"label":"RESULTS","text":"A total of 58 patients were included from February 2021 to August 2023. The mean age of patients was 59.41 years. Forty (69%) were male, and 18 (31%) were female. All patients experienced some degree of OM during RT. No significant differences were observed between the groups for all OM grades (WHO scale, p = 0.69; NCI scale, p = 0.82) or in the meantime to the development of ulcerated OM (WHO scale, p = 0.63; NCI scale, p = 0.61). On day 20 (week 4) and day 30 (week 6), patients in the EOPBM group reported significantly less difficulty swallowing compared to the IOPBM group (Mann-Whitney test, p = 0.02 and p = 0.04, respectively). On day 25 (week 5), the EOPBM group demonstrated a significantly smaller decline in taste perception compared to the IOPBM group, as determined by the Mann-Whitney test (p = 0.01)."},{"label":"CONCLUSION","text":"The EOPBM protocol was found to be as effective as IOPBM in managing OM, with the added benefit of providing greater patient comfort during application."},{"label":"TRIAL REGISTRATION","text":"Registered with ClinicalTrials.gov (NCT05242991)."}],"keywords":["Head and neck cancer","Oral mucositis","Photobiomodulation","Radiotherapy"]},{"pmid":"41002684","title_fr":"Facteurs de mucite sévère malgré la PBM chez les greffés de cellules souches","type":"cohort","level":4,"pop":"mixte","ctx":["CSH"],"aim":"prévention","mode":[],"nm":[],"n":171,"effect":"—","theme":"Facteurs de risque","l1":"Sur 171 greffés traités par PBM, le conditionnement, le méthotrexate, une culture microbienne positive et des marqueurs biologiques (CRP, transaminases) prédisent une mucite sévère malgré la PBM.","l2":"Analyse rétrospective sur deux ans (Brésil). Les variables étaient relevées au premier jour du conditionnement et au jour de la mucite maximale.\n\nPour les patients cumulant ces facteurs, les auteurs suggèrent d'ajuster la dosimétrie ou d'ajouter des traitements adjuvants. Démarche de PBM personnalisée intéressante, à valider.","l3":{"points":["Prédicteurs dès J1 du conditionnement : type de conditionnement, MTX, cultures positives, ALAT élevées."],"limites":["Rétrospectif ; pas de comparaison sans PBM."],"pratique":"Identifier tôt les greffés à haut risque pour renforcer la prévention."},"topic":"mucite-orale","title":"Determinants of Severe Oral Mucositis Development Despite Photobiomodulation Therapy in Stem Cell Transplant Patients.","journal":"Dentistry journal","journal_abbr":"Dent J (Basel)","authors":["Rezende SB","Campos L","de Souza MC","et al."],"date":"2025-09-08","year":2025,"week":"2025-S37","doi":"10.3390/dj13090411","pmcid":"PMC12468854","license":"cc by","oa":true,"pdf":"pdfs/41002684.pdf","cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"Background/Objectives: Oral mucositis (OM) is an extremely common and debilitating side effect in patients undergoing Hematopoietic Stem Cell Transplantation (HSCT). As such, managing this condition is an obligatory component for their supportive care. Among the available treatment options, photobiomodulation therapy has long since established itself as the most promising approach, with consistent evidence supporting its efficacy. Despite this, the clinical results of this therapy are still influenced by the chosen dosimetry parameters, as well as patient-specific factors. Therefore, this study aimed to assess which factors can continue to influence the severity and onset of OM despite the protective effect provided by the ongoing photobiomodulation therapy. Methods: To achieve this, a retrospective analysis was conducted on the medical records of 171 patients who underwent PBMT during HSCT over a two-year period at the Brazilian Institute of Cancer Control. These files were used to review clinical and laboratorial parameters, such as OM grade, serum CRP, creatinine, urea, OGT, PGT, pain levels, presence of microorganisms in cultures, type of transplant, and conditioning regimens. All of these were evaluated at two different time points: the first day of conditioning and the day of highest OM degree. The statistical analysis was then conducted to evaluate the correlation between the variables and OM grade. Results: Results showed that type of conditioning regimens, use of MTX during conditioning, presence of microorganisms in cultures, and increased serum CRP, PGT, and initial urea levels were associated with severe OM. Conclusions: Among these, the type of conditioning regimens, MTX usage, positive results in cultures, and increased PGT levels on the first day of conditioning could be considered predictive for severe OM and the worst PBMT results. Consequently, in patients exposed to additional risk factors, adjustments in dosimetry paraments of PBMT or employment of adjuvant therapies should be considered to achieve better results."}],"keywords":["Hematopoietic Stem Cell Transplantation","dosimetry","oral mucositis","photobiomodulation therapy","risk factors"]},{"pmid":"40889543","title_fr":"La PBM comme stratégie préventive de la mucite en oncopédiatrie : revue systématique et méta-analyse","type":"ma","level":1,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":177,"effect":"favorable","theme":"Synthèse des preuves","key":true,"l1":"Cinq essais randomisés (177 enfants, laser ou LED) : la PBM préventive réduit l'incidence et la sévérité de la mucite chez l'enfant atteint d'hémopathie maligne.","l2":"Revue (PICOS) des essais randomisés chez les 0–22 ans recevant une chimiothérapie pour hémopathie maligne (recherche jusqu'en février 2025). 97 enfants ont reçu un laser, 80 une LED.\n\nTrois essais ont pu être méta-analysés : bénéfice significatif (p = 0,04). Le résumé donne un IC95 % de 0,01 à 0,84, sans préciser la mesure d'effet. Ce résultat contraste avec la méta-analyse pédiatrique négative de 2024, qui portait sur un autre ensemble d'essais.","l3":{"points":["5 ECR, 4 mois à 22 ans ; 3 essais méta-analysés (p = 0,04)."],"limites":["Très peu d'essais poolés ; mesure d'effet ambiguë dans le résumé."],"pratique":"Soutient la PBM préventive en oncopédiatrie, à mettre en regard de la méta-analyse In Vivo 2024."},"topic":"mucite-orale","title":"Photobiomodulation as a preventive strategy for oral mucositis in pediatric oncology: a systematic review and meta-analysis.","journal":"Journal of dentistry","journal_abbr":"J Dent","authors":["Marques MT","Arêde LT","Rodrigues JVS","et al."],"date":"2025-08-30","year":2025,"week":"2025-S35","doi":"10.1016/j.jdent.2025.106074","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review","Meta-Analysis","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"OBJECTIVES","text":"Oral mucositis (OM) is one of the most frequent and debilitating complications in children undergoing treatment for hematologic malignancies. Current management strategies focus on minimizing OM severity and alleviating symptoms. This systematic review aimed to evaluate the effectiveness of photobiomodulation (PBM) in preventing OM in pediatric patients with hematologic malignancies receiving chemotherapy."},{"label":"DATA/SOURCES","text":"Guided by the PICOS framework, this review addressed the following research question: Is PBM therapy effective in reducing the incidence and severity of oral mucositis in children and adolescents with hematologic malignancies undergoing chemotherapy? A comprehensive search was conducted in PubMed, Scopus, Web of Science, Embase and The Cochrane databases through February 2025. Eligible studies were randomized clinical trials involving patients aged 0-22 years diagnosed with hematologic malignancies treated by means of chemotherapy, and undergoing preventive PBM therapy for OM."},{"label":"STUDY SELECTION","text":"Five randomized controlled trials were included, encompassing patients aged 4 months to 22 years. Of these, 97 received low-level laser therapy (LLLT) and 80 received light-emitting diode therapy (LEDT). PBM was consistently reported as effective in preventing the onset and reducing the severity of OM in these populations. Three studies were eligible for meta-analysis, which demonstrated a statistically significant benefit of PBM therapy (p = 0.04), with a 95% confidence interval ranging from 0.01 to 0.84."},{"label":"CONCLUSIONS","text":"PBM therapy appears to be an effective preventive strategy for oral mucositis in pediatric patients undergoing chemotherapy for hematologic malignancies. Further large-scale trials are warranted to establish standardized protocols and optimize treatment outcomes."},{"label":"CLINICAL SIGNIFICANCE","text":"PBM therapy significantly reduces the incidence and severity of oral mucositis in pediatric patients undergoing chemotherapy for hematologic malignancies. This non-invasive intervention offers an emerging preventive strategy, improving patient comfort and treatment adherence. Standardized PBM protocols may enhance supportive care in pediatric oncology settings."}],"keywords":["Cancer","Photobiomodulation, children, low-level laser therapy, oral mucositis"]},{"pmid":"40852911","title_fr":"« Je n'avais qu'à ouvrir grand la bouche » : acceptabilité de la PBM pour la mucite en soins de support pédiatriques","type":"qualitative","level":0,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal"],"nm":[],"n":27,"effect":"—","theme":"Implantation","l1":"Enfants, parents et soignants britanniques jugent la PBM acceptable ; les freins sont le manque de compréhension du traitement et la charge de travail pour les équipes.","l2":"Entretiens et groupes focaux (27 participants, enfants de 8 à 15 ans) analysés selon le cadre théorique de l'acceptabilité (TFA). Quatre thèmes : attitudes positives, importance de l'autonomie de l'enfant, compréhension insuffisante du traitement, charge pour les équipes.\n\nRecommandations : organiser le service pour limiter la charge et créer des supports adaptés à l'enfant.","l3":{"points":["Plus de la moitié des familles et trois quarts des soignants avaient déjà une expérience de la PBM."],"limites":["Étude qualitative, contexte britannique."],"pratique":"Prévoir des supports explicatifs pour l'enfant et une organisation dédiée."},"topic":"mucite-orale","title":"'All I Had to Do Was Open My Mouth Wide'-A Qualitative Exploration of the Acceptability of Photobiomodulation for Oral Mucositis Management in Paediatric Supportive Care.","journal":"Pediatric blood & cancer","journal_abbr":"Pediatr Blood Cancer","authors":["Heggie C","Chauhan A","Gray-Burrows KA","et al."],"date":"2025-08-25","year":2025,"week":"2025-S35","doi":"10.1002/pbc.31978","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":1,"pub_types":["Research Support, N.I.H., Extramural"],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis (OM) presents a common and debilitating side effect of chemotherapy for children and young people (CYP). Photobiomodulation is recommended for OM prevention in international guidance; however, the acceptability of photobiomodulation in paediatric cancer care is uncertain. This study explores this acceptability with CYP, their parents, and healthcare professionals (HCPs)."},{"label":"METHODS","text":"Semi-structured interviews with CYP/parent dyads and focus groups with HCPs were audio-recorded and professionally transcribed. Framework analysis was completed utilising the Theoretical Framework of Acceptability (TFA) using an initial deductive approach for theoretical rigour. Over-arching themes within and between constructs and participant groups were developed. Recruitment occurred alongside analysis until there was repetition of data and an absence of novel codes."},{"label":"RESULTS","text":"Twenty-seven participants were interviewed. CYP were aged 8-15 years old; HCPs had diverse professional roles within paediatric oncology and dentistry. Over half of families and three quarters of HCPs had previous photobiomodulation experience. Data were coded for all seven TFA constructs. Four themes, consisting of multiple subthemes, were developed from 42 distinct codes: (i) positive attitudes towards photobiomodulation; (ii) importance of child-centredness and autonomy; (iii) lack of understanding of photobiomodulation treatment; (iv) perceived additional burden to healthcare teams."},{"label":"CONCLUSION","text":"Photobiomodulation for OM prevention is acceptable to CYP, their parents, and HCPs during cancer treatment. Exploration of the theoretical facets of this acceptability supports adaptation of services to overcome highlighted challenges to photobiomodulation acceptance. Photobiomodulation services should be designed to reduce burden on healthcare services, with resources developed to support CYP's autonomy, comprehension and self-efficacy with intra-oral treatment."}],"keywords":["acceptability","low‐level laser","mucositis","oral mucositis","photobiomodulation","qualitative research"]},{"pmid":"40824766","title_fr":"La PBM réduit-elle le nitrite salivaire dans la mucite ? Revue systématique","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Mécanismes","l1":"Trois études concordent : la PBM abaisse le nitrite salivaire, marqueur du stress oxydatif, ce qui pourrait expliquer une partie de son effet sur la mucite.","l2":"Revue (PubMed, Cochrane, jusqu'en juin 2025) avec évaluation RoB 2.0. Les protocoles et les traitements anticancéreux diffèrent, mais le sens de l'effet est constant.\n\nPreuve mécanistique préliminaire, fondée sur trois études seulement.","l3":{"points":["3 études incluses."],"limites":["Très peu d'études ; hétérogénéité des protocoles."],"pratique":"Pas de conséquence pratique."},"topic":"mucite-orale","title":"Can Photobiomodulation Therapy Reduce Salivary Nitrite in Oral Mucositis? A Systematic Review.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Khalil M","Soliman G","Hasan A","et al."],"date":"2025-08-15","year":2025,"week":"2025-S33","doi":"10.1177/25785478251370450","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"Background: Oral mucositis (OM) is a frequent and debilitating adverse effect of cancer treatments, primarily mediated by oxidative stress and inflammatory pathways involving reactive oxygen species (ROS) and nitric oxide. Photobiomodulation (PBM) therapy has emerged as a potential intervention to mitigate OM severity by regulating these mechanisms. This review examines the influence of PBM on salivary nitrite concentrations-a key biomarker of oxidative stress-in patients with OM. Methods: A systematic literature search was conducted across PubMed and the Cochrane Library, encompassing clinical trials published up to June 2025. Included studies investigated the effects of PBM on salivary nitrite levels in patients receiving anticancer therapy. Methodological quality was assessed using the Revised Cochrane Risk of Bias tool (RoB 2.0). Results: Three studies satisfied the inclusion criteria. Although variations existed among the studies regarding anticancer treatment modalities and PBM irradiation parameters, all consistently reported a reduction in salivary nitrite levels following PBM therapy. Conclusion: PBM therapy appears effective in alleviating OM severity, potentially attributable to its capacity to decrease salivary nitrite concentrations. Additional research is warranted to validate these preliminary findings and optimize PBM protocols for clinical implementation."}],"keywords":["nitrite","oral mucositis","photobiomodulation"]},{"pmid":"40640452","title_fr":"Mucite chez les greffés de cellules souches sous PBM prophylactique : cohorte rétrospective","type":"cohort","level":4,"pop":"adulte","ctx":["CSH"],"aim":"prévention","mode":[],"nm":[],"n":68,"effect":"favorable","theme":"Vie réelle","l1":"Chez 68 greffés sous PBM prophylactique, 54 % ont eu une mucite mais aucune de grade 3 ou 4 ; le conditionnement MEL100 multiplie le risque par 14.","l2":"Cohorte brésilienne d'un centre de référence. Associations : âge jeune et mucite de grade 1–2 ; conditionnement FluBuMel/Cy et grade 2 ; mucite pharyngée et grade 1.\n\nL'absence totale de forme sévère est remarquable, mais l'étude n'a pas de groupe sans PBM.","l3":{"points":["Âge médian 40 ans ; 54,4 % de femmes.","MEL100 : risque multiplié par 14,36."],"limites":["Rétrospectif, sans comparateur."],"pratique":"Surveiller de près les conditionnements à base de melphalan, même sous PBM."},"topic":"mucite-orale","title":"Oral mucositis in patients undergoing hematopoietic stem cell transplantation with prophylactic photobiomodulation: A retrospective cohort study.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Pereira TBF","Lima BMF","Potter GS","et al."],"date":"2025-07-10","year":2025,"week":"2025-S28","doi":"10.1007/s00520-025-09750-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"To analyze the incidence, severity, and factors associated with the development of oral mucositis (OM) in patients undergoing hematopoietic stem cell transplantation (HSCT) who are receiving prophylactic photobiomodulation therapy (PBMT)."},{"label":"METHODS","text":"Data, including sex, age, grade of OM, and conditioning regimen, were collected from medical records of patients undergoing prophylactic PBMT at a reference hospital in Brazil. Pearson's chi-square test or Fisher's exact test were applied to examine the associations between variables. Kaplan-Meier method was used to calculate disease-free survival time."},{"label":"RESULTS","text":"A total of 68 patients were included in the study, 54.4% of whom were female, with a median age of 40 years. OM occurred in 37 patients (54.4%). Most OMs were classified as Grade 0 (45.5%). No cases of Grade 3 or 4 OM were observed. A statistically significant association was found between Grade 1 and 2 OM and younger age (p = 0.017). FluBuMel/Cy conditioning regimen was associated with the occurrence of Grade 2 OM (p = 0.006), while pharyngeal mucositis was associated with Grade 1 (p < 0.0001). Age, pharyngeal mucositis and some types of conditioning regimen had a significant impact on the disease-free survival rate for OM. Patients undergoing the MEL100 conditioning protocol had a 14.36-fold increased risk of developing this complication."},{"label":"CONCLUSION","text":"In HSCT patients undergoing prophylactic use of PBMT, factors such as age, specific chemotherapy conditioning protocols, and the presence of pharyngeal mucositis were found to be associated with OM development."}],"keywords":["Cohort studies","Hematopoietic stem cell transplantation","Oral mucositis"]},{"pmid":"40549226","title_fr":"PBM combinée extra- et intrabuccale pour prévenir et traiter mucite et xérostomie en ORL","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":["intrabuccal","extrabuccal","laser"],"nm":[],"n":75,"effect":"favorable","theme":"Extra vs intrabuccal","key":true,"l1":"Chez 75 patients ORL, ajouter une PBM extrabuccale (sur les glandes salivaires) à l'intrabuccale réduit la mucite dès la 2e semaine, améliore le débit salivaire et la qualité de vie.","l2":"Essai randomisé brésilien avec simulation : PBM intrabuccale + extrabuccale simulée (n = 38) contre PBM intrabuccale + extrabuccale réelle (n = 37). Mesures : qualité de vie (OHIP-14, PROMs, XeQOLS), grade de mucite, sialométrie.\n\nLa combinaison fait mieux sur tous les critères (p < 0,001), dont le débit salivaire de repos et stimulé. Contrairement aux essais qui opposent les deux voies, celui-ci teste leur addition.","l3":{"points":["Enregistrement ReBEC RBR-5p2xfzd.","Grade de mucite inférieur dès la semaine 2 (p < 0,001).","Sialométrie de repos et stimulée améliorée (p < 0,001)."],"limites":["Paramètres détaillés seulement dans le texte intégral ; analyse par Kruskal-Wallis pour deux groupes.","Monocentrique."],"pratique":"Ajouter une PBM extrabuccale en regard des glandes salivaires pendant la radiothérapie ORL semble apporter un bénéfice supplémentaire."},"topic":"mucite-orale","title":"Combined extraoral and intraoral photobiomodulation for the prevention and management of oral mucositis and Xerostomia caused by the treatment of head and neck cancers.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Borghesi Brunelli G","Pinheiro SL"],"date":"2025-06-23","year":2025,"week":"2025-S26","doi":"10.1007/s10103-025-04539-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"PURPOSE","text":"To evaluate the effectiveness of combined intraoral and extraoral photobiomodulation (PBM) in the management of oral mucositis (OM) and xerostomia in patients undergoing head and neck cancer (HNC) treatment."},{"label":"METHODS","text":"Seventy-five patients with HNC were included and randomly assigned to 2 groups: those receiving intraoral PBM and a simulated extraoral PBM application (PBMI-SE group, n = 38); and those receiving combined intraoral and extraoral PBM (PBMIE group, n = 37). Quality of life related to OM and xerostomia, OM symptoms, OM grade, and salivary flow rate were assessed. Results were analyzed using the Kruskal-Wallis test (Student-Newman-Keuls)."},{"label":"RESULTS","text":"Combined intraoral and extraoral PBM led to a significant improvement in quality of life (OHIP-14, PROMS, and XeQOLS scores) compared with intraoral PBM alone (p < 0.001). From the second week onward, the PBMIE group experienced significantly lower OM grades (p < 0.001) than the PBMI-SE group. Additionally, the PBMIE group showed a significant improvement in both resting and stimulated sialometry from the second collection onward compared with the PBMI-SE group (p < 0.001)."},{"label":"CONCLUSION","text":"Combined extraoral and intraoral PBM improved the quality of life of patients undergoing HNC treatment, particularly in relation to OM and xerostomia. This combined approach effectively controlled OM severity and improved salivary flow, offering a potential treatment option for these patients."},{"label":"CLINICAL TRIAL REGISTRATION","text":"This study was registered in Brazilian Registry of Clinical Trials (ReBEC) (RBR-5p2xfzd). First Posted: October 03, 2023."}],"keywords":["Cancer","Cancer treatment","Oral mucositis","Photobiomodulation","Xerostomia"]},{"pmid":"41040611","title_fr":"Effet potentiel de la PBM sur la mucite des radio-chimiothérapies ORL : revue de la littérature","type":"review","level":5,"pop":"mixte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue des essais récents : la PBM réduit sévérité et durée de la mucite en ORL ; protocoles courants de 630 à 980 nm, 2 à 6 J/cm², 10 à 125 s par point.","l2":"Revue narrative taïwanaise centrée sur les essais randomisés chez l'adulte et l'enfant. Elle décrit les mécanismes et les obstacles à l'implantation, en premier lieu le manque de standardisation.\n\nUtile surtout pour ses fourchettes de paramètres.","l3":{"points":["Paramètres usuels : 630–980 nm ; 2–6 J/cm² ; 10–125 s/point."],"limites":["Revue narrative."],"pratique":"Repères de dosimétrie cohérents avec MASCC/ISOO."},"topic":"mucite-orale","title":"The potential effect of photobiomodulation on oral mucositis induced by head and neck radio-chemotherapy: A literature review.","journal":"Journal of dental sciences","journal_abbr":"J Dent Sci","authors":["Bahrami R","Eftekharian S","Jafarieh R","et al."],"date":"2025-06-18","year":2025,"week":"2025-S25","doi":"10.1016/j.jds.2025.06.002","pmcid":"PMC12485458","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41040611.pdf","cited_by":2,"pub_types":["Review"],"abstract":[{"label":"","text":"Oral mucositis (OM) is a common side effect of head and neck radio-chemotherapy. It manifests as painful, ulcerative lesions in the oral mucosa, significantly impairing essential functions such as eating, speaking, and maintaining oral hygiene. It finally has adverse effects on the patient's quality of life. Photobiomodulation therapy (PBMT) has emerged as a promising non-invasive modality for preventing and treating OM. Due to controversy among the results of studies, this literature review synthesizes findings from recent randomized controlled trials that evaluated the use of PBMT in adult and pediatric cancer patients. This review also highlights the mechanisms, clinical efficacy, and future challenges of integrating PBMT into routine supportive cancer care. The evidence shows that PBMT significantly reduces the severity and duration of OM, improved patient-reported outcomes, and minimized treatment-related morbidity. By utilizing low-intensity light sources-typically lasers or LEDs-PBMT enhances cellular metabolism, reduces inflammation, alleviates pain, and promotes mucosal healing. Despite its clinical potential, widespread implementation of PBMT is hindered by variability in treatment protocols and limited standardization; in brief, laser protocols - wavelengths (630-980 nm), energy densities (2-6 J/cm2), and application durations (10-125 s/point) are commonly used for preventing and treating OM induced by head and neck radio-chemotherapy. However, future studies with long-term follow-ups will be necessary to standardize PBMT protocols, as standardization is essential to integrate PBMT into routine cancer care."}],"keywords":["Low-level laser","Oral mucositis","Photobiomodulation","Radio-chemotherapy"]},{"pmid":"40645840","title_fr":"Voies juridiques et jurisprudence pour l'accès à la PBM contre la mucite au Brésil","type":"survey","level":0,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":50,"effect":"—","theme":"Implantation","l1":"Au Brésil, 50 décisions de justice (2005–2024) ont toutes accordé, au moins en partie, l'accès à la PBM contre la mucite, surtout face aux assurances santé.","l2":"Étude transversale des bases de données des tribunaux de tous les États, de la Cour supérieure et de la Cour suprême. 82 % des demandes ont été entièrement accordées, 18 % partiellement (dommages moraux refusés). 94 % visaient des assureurs privés.\n\nDélai moyen jusqu'à la décision provisoire : 13 jours. Illustration originale de la reconnaissance de la PBM comme soin standard.","l3":{"points":["180 décisions trouvées, 50 éligibles."],"limites":["Contexte juridique propre au Brésil."],"pratique":"Montre que la PBM est considérée comme un standard de soins opposable au Brésil."},"topic":"mucite-orale","title":"Legal pathways and case law on photobiomodulation therapy for oral mucositis in cancer care: a retrospective cross-sectional study.","journal":"Oral surgery, oral medicine, oral pathology and oral radiology","journal_abbr":"Oral Surg Oral Med Oral Pathol Oral Radiol","authors":["Startari DM","Esteves-Pereira TC","Wolkart EN","et al."],"date":"2025-05-24","year":2025,"week":"2025-S21","doi":"10.1016/j.oooo.2025.05.006","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"OBJECTIVE","text":"Oral mucositis (OM) is a common and debilitating complication of cancer therapy that can be prevented with photobiomodulation therapy (PBMT), a light-based intervention recommended by international guidelines. This study aimed to identify the legal pathways to patient access to PBMT for OM in Brazilian cancer care."},{"label":"STUDY DESIGN","text":"This retrospective cross-sectional study assessed electronic databases of the Courts of Justice from all Brazilian states, the Superior Court of Justice, and the Federal Supreme Court, yielding 180 court rulings for \"mucositis\"."},{"label":"RESULTS","text":"A total of 50 court rulings, adjudicated between 2005 and 2024, met the eligibility criteria. Of these, 41 (82%) were fully granted and 9 (18%) partially granted, typically denying compensation for moral damages. In 47 cases (94%), the rulings were directed to health insurance providers, while 3 (6%) involved the public healthcare system. The mean time from filing to interim relief was 13.3 days (SD = 28.3; range: 1-115). Chemotherapy was the most common cancer treatment, followed by radiotherapy and hematopoietic stem cell transplantation."},{"label":"CONCLUSIONS","text":"This novel study reveals a consistent legal framework supporting access to PBMT for OM in Brazil, reflecting a progressive judicial stance with potential implications for health policy and supportive cancer care."}],"keywords":[]},{"pmid":"40340568","title_fr":"Effet de la PBM sur le nitrite salivaire dans la mucite chimio-induite : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","extrabuccal","laser"],"nm":[650,980],"n":45,"effect":"favorable","theme":"Mécanismes","l1":"Chez 45 patients sous chimiothérapie, la PBM (intrabuccale 650 nm, seule ou avec extrabuccale 980 nm) réduit la sévérité de la mucite et le nitrite salivaire par rapport aux seuls conseils d'hygiène.","l2":"Essai en double aveugle à trois groupes appariés : conseils seuls, conseils + PBM intrabuccale, conseils + PBM intra- et extrabuccale. Mesures à 1 et 2 semaines.\n\nLes deux groupes laser font mieux que le témoin, sans différence entre eux. Même équipe et même schéma que l'essai sur le préconditionnement publié en février 2025 : il s'agit probablement de la même population.","l3":{"points":["Nitrite dosé par réactif de Griess.","Différences significatives entre groupes à S1 et S2 (p < 0,001)."],"limites":["Recouvrement probable avec l'essai PMID 39910516 : ne pas compter deux fois ces patients.","15 patients par groupe."],"pratique":"Pas de bénéfice de l'ajout extrabuccal en chimiothérapie dans cette étude."},"topic":"mucite-orale","title":"Effect of Photobiomodulation on Salivary Nitrite in Patients with Chemotherapy-Induced Oral Mucositis: A Randomized Clinical Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Khalil M","Hamadah O","Saifo M"],"date":"2025-05-09","year":2025,"week":"2025-S19","doi":"10.1089/photob.2024.0151","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Background: Oral mucositis (OM) is a severe inflammatory and ulcerative condition of the oral mucosa commonly induced by chemotherapy. Photobiomodulation (PBM) therapy has been proposed for preventing and treating OM. However, the understanding of light interaction with biological tissues and the variability in light sources and protocols limit its widespread application. This study aimed to evaluate the impact of PBM on salivary nitrite levels, a marker of oxidative stress associated with inflammation and tissue damage. Materials and Methods: This prospective, randomized, double-blind clinical trial included 45 patients, evenly divided into three age- and sex-matched groups. Group 1 received basic oral care instructions prior to chemotherapy. Group 2 received these instructions plus PBM using a 650 nm intraoral diode laser. Group 3 received basic oral care instructions combined with PBM using both a 650 nm intraoral diode laser and a 980 nm extraoral diode laser. OM severity was assessed using World Health Organization criteria, and salivary nitrite levels were measured using the Griess reagent kit (Biotium®) according to the manufacturer's instructions 1 and 2 weeks after the first chemotherapy session. Results: Our study included 45 patients who were evenly distributed into three groups, matched for age, sex, tumor type, and type of chemotherapy. Significant differences in OM severity were observed among the groups at both 1 and 2 weeks (p = 0.000). Salivary nitrite levels also showed significant differences between groups at these time points (p = 0.00). Significant differences were found between the control group and both laser treatment groups, but no significant difference was noted between the two laser treatment groups. Conclusions: PBM effectively reduces OM severity, whether used intraorally alone or combined with extraoral application. This effect is likely due to PBM's ability to lower salivary nitrite levels, indicating reduced oxidative stress and inflammation."}],"keywords":["chemotherapy","nitrite","oral mucositis","photobiomodulation"]},{"pmid":"40316940","title_fr":"PBM pour prévenir et thérapie photodynamique pour traiter la mucite sous méthotrexate chez l'enfant : essai randomisé","type":"rct","level":2,"pop":"pédiatrie","ctx":["chimio"],"aim":"les deux","mode":["laser","PDT"],"nm":[],"n":null,"effect":"favorable","theme":"Associations","metric":{"kind":"rates","outcome":"Incidence de la mucite (bras prévention)","a_label":"Cycle avec PBM","a":6.67,"b_label":"Cycle sans PBM","b":66.67},"l1":"En Iran, chez l'enfant sous méthotrexate, la PBM fait passer la mucite de 66,7 % à 6,7 % ; en curatif, la thérapie photodynamique au vert d'indocyanine accélère l'amélioration contre placebo.","l2":"Essai à deux bras. Prévention : chaque enfant sert de témoin, un cycle sans laser puis un cycle avec PBM (comparaison intra-individuelle, non randomisée). Traitement : les enfants avec mucite sont randomisés entre laser simulé et PDT (vert d'indocyanine + laser basse énergie).\n\nLa PDT réduit les scores OMS, NCI et WCCNR à J3 et J5. Résultat préventif spectaculaire, mais obtenu avec un plan avant-après.","l3":{"points":["Enregistrement IRCT20120101008585N16.","Prévention : 66,67 % puis 6,67 % (p < 0,05).","Traitement : PDT supérieure au placebo à J3 et J5."],"limites":["Bras prévention non randomisé (séquence fixe).","Effectifs non donnés dans le résumé."],"pratique":"La PDT au vert d'indocyanine est une piste curative ; la PBM préventive reste le standard."},"topic":"mucite-orale","title":"Efficacy of photobiomodulation for the prevention and treatment of chemotherapy-induced oral mucositis in pediatric patients with hematologic cancers: a randomized clinical trial.","journal":"BMC cancer","journal_abbr":"BMC Cancer","authors":["Lavaee F","Rezazadeh F","Amanati A","et al."],"date":"2025-05-02","year":2025,"week":"2025-S18","doi":"10.1186/s12885-025-14213-w","pmcid":"PMC12049046","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/40316940.pdf","cited_by":1,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis (OM) is a debilitating treatment-related complication that affects most children undergoing chemotherapy. This dual-arm clinical trial aimed to evaluate the efficacy of photobiomodulation (PBM) for prevention and photodynamic therapy (PDT) using indocyanine green (ICG) and low-level laser for treating methotrexate (MTX)-induced OM in pediatric patients with hematologic cancers."},{"label":"METHODS","text":"In the prevention arm, patients were initially assigned to a control group (received no laser) and subsequently reassigned to a PBM group in their next cycle, allowing intra-patient comparison under similar chemotherapy protocols. In the treatment arm, patients diagnosed with OM were randomly assigned to either a control group (sham laser) or a PDT group."},{"label":"RESULTS","text":"In the prevention arm, PBM led to a significant reduction in the incidence of OM from 66.67% to 6.67% (p < 0.05). In the treatment arm, the PDT group showed a significant reduction in the scores of all scales (WHO, NCI, and WCCNR) at both 3 days and 5 days after starting the treatment compared to the control group (p < 0.05). Moreover, the reduction in the NCI score from the third to the fifth days after the starting treatment is higher in the PDT group compared to the control group (p < 0.05)."},{"label":"CONCLUSION","text":"PBM appears to be a safe and effective approach for the prevention of MTX-induced OM in pediatric patients with hematologic cancers. Additionally, PDT using ICG and a low-level laser demonstrates promising results in treating OM lesions. Therefore, these findings highlight the efficacy of PBM for managing MTX-induced OM in this patient group."},{"label":"TRIAL REGISTRATION","text":"The study has been registered on irct.behdasht.gov.ir on 4 December 2022 (Trial Registration Number: IRCT20120101008585N16)."}],"keywords":["Hematology","Indocyanine Green","Laser Therapy","Mucositis","Neoplasms","Pediatrics","Photobiomodulation","Photodynamic Therapy"]},{"pmid":"40295318","title_fr":"L-glutamine et acide hyaluronique associés à la PBM contre la mucite : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":[],"nm":[],"n":48,"effect":"favorable","theme":"Associations","l1":"Chez 48 patients ORL sous radiochimiothérapie, ajouter L-glutamine et acide hyaluronique à la PBM réduit la mucite sévère à la 30e séance (échelle OMS) et améliore la qualité de vie.","l2":"Essai brésilien : PBM + protocole de soins buccaux (n = 24) contre la même chose plus L-glutamine et acide hyaluronique (n = 24). Évaluations aux 1re, 7e, 14e, 21e et 30e séances.\n\nLe bénéfice apparaît sur l'échelle OMS mais pas sur l'échelle NCI, ce qui fragilise le résultat. Les patients du groupe combiné rapportent moins de symptômes à tous les temps.","l3":{"points":["Enregistrement ReBEC RBR-6ybmgcv.","Mucite sévère moindre à la 30e séance (OMS) ; pas de différence NCI."],"limites":["Discordance entre échelles ; petit effectif."],"pratique":"Association prometteuse, insuffisante pour une recommandation."},"topic":"mucite-orale","title":"Effects of L-glutamine and hyaluronic acid associated with photobiomodulation on oral mucositis: a randomized clinical trial.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Dos Santos RW","Martins AFL","Sousa-Neto SS","et al."],"date":"2025-04-28","year":2025,"week":"2025-S18","doi":"10.1007/s00520-025-09480-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"To investigate whether the application of L-glutamine (L-G) and hyaluronic acid (HA) associated with photobiomodulation (PBM) and the Preventive Oral Care Protocol (POCP) would present similar efficacy as the exclusive use of PBM, associated with POCP, in the prevention and control of severe oral mucositis (OM)."},{"label":"STUDY DESIGN","text":"Patients with head and neck cancer undergoing radiochemotherapy (RCT) were randomized into two groups: group A, patients that received PBM + POCP (n = 24), and group B, patients that received PBM + POCP + L-G + HA (n = 24). OM was assessed using the National Cancer Institute (NCI) and World Health Organization (WHO) scales. The impact of oral health on patients' quality of life and perception of OM symptoms was evaluated. Assessments were made at the 1st, 7th, 14th, 21st, and 30th radiotherapy (RT) sessions."},{"label":"RESULTS","text":"When the severity of OM was assessed according to the WHO scale in the 30th RT, group B showed lower rates of severe OM than group A. There were no differences when using the NCI scale. The impact of oral health on quality of life and the symptoms reported by patients were lower in group B at all times evaluated."},{"label":"CONCLUSION","text":"The combination of PBM + POCP + L-G + HA resulted in a significantly lower severity of OM than PBM + POCP alone, according to the WHO scale at the 30th RT."},{"label":"TRIAL REGISTRATION","text":"Brazilian Clinical Trials Registry-REBEC no. RBR-6ybmgcv. Registration March 27, 2022."}],"keywords":["Glutamine","Head and neck cancer","Hyaluronic acid","Oral mucositis","Photobiomodulation therapy","Radiotherapy"]},{"pmid":"40414733","title_fr":"Photothérapie LED pour la mucite en cancérologie : revue systématique avec analyse GRADE","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["LED"],"nm":[],"n":256,"effect":"favorable","theme":"Synthèse des preuves","l1":"Cinq études (256 patients) sur les LED : amélioration de la sévérité et de la douleur dans quatre d'entre elles, mais certitude GRADE faible.","l2":"Revue avec RoB-2 pour les essais et ROBINS-I pour les études non randomisées. Hétérogénéité trop grande pour une méta-analyse ; risque de biais modéré.\n\nLes LED réduiraient douleur et durée de la mucite. L'essai américain contre simulation publié en 2026 apporte depuis une preuve randomisée plus solide.","l3":{"points":["5 études, 256 patients ; GRADE : faible."],"limites":["Pas de méta-analyse."],"pratique":"Les LED sont une alternative crédible au laser ; voir l'essai multicentrique de 2026."},"topic":"mucite-orale","title":"LED-based low-level light therapy for oral mucositis in cancer patients: a systematic review and GRADE analysis.","journal":"Oral surgery, oral medicine, oral pathology and oral radiology","journal_abbr":"Oral Surg Oral Med Oral Pathol Oral Radiol","authors":["Joseph B","Mauramo M","Sorsa T","et al."],"date":"2025-04-22","year":2025,"week":"2025-S17","doi":"10.1016/j.oooo.2025.04.095","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review"],"abstract":[{"label":"OBJECTIVE","text":"This systematic review aimed to evaluate the efficacy of light-emitting diode (LED) therapy in reducing oral mucositis (OM) severity, pain, and healing time in cancer patients and compare it to standard care or sham light."},{"label":"MATERIALS AND METHODS","text":"A comprehensive search of major databases was conducted using relevant MeSH terms and keywords. Two authors independently screened studies meeting the eligibility criteria. The Cochrane Risk-of-Bias tool for randomized controlled trials (RoB-2) and the Risk of Bias in Non-Randomized Studies - of Interventions (ROBINS-I) were used to assess the methodological quality of included studies. The certainty of evidence was evaluated using the Grading of Recommendations, Assessment, Development, and Evaluation (GRADE) approach."},{"label":"RESULTS","text":"The review included five studies (256 participants). Four studies reported significant improvements in OM severity and pain with LED therapy while only one study suggested improved healing time. The risk of bias was moderate among the included studies. Due to heterogeneous data, a meta-analysis could not be performed. The GRADE assessment indicated low certainty of evidence, highlighting the need for further clinical research."},{"label":"CONCLUSION","text":"LED therapy may effectively manage cancer therapy-induced OM by reducing patient-reported pain and OM duration. However, the low certainty of evidence warrants more well-designed, longitudinal studies with larger sample sizes to confirm these findings and establish optimal treatment protocols."}],"keywords":[]},{"pmid":"40259459","title_fr":"Des mécanismes moléculaires aux applications cliniques : la PBM en cancérologie","type":"review","level":5,"pop":"—","ctx":["mixte"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Sécurité oncologique","l1":"Revue générale de la PBM en cancérologie : effets sur mucite, radiodermite, lymphœdème, neuropathie et entérite radique, et discussion de la sécurité vis-à-vis des cellules tumorales.","l2":"Revue narrative chinoise sur les mécanismes, les toxicités traitées et la question de l'effet de la lumière sur les cellules cancéreuses. Les auteurs citent des travaux où la PBM inhibe la prolifération ou induit l'apoptose.\n\nÀ lire avec les études précliniques de 2024 (mélanome, Xenopus) qui montrent au contraire des signaux de stimulation.","l3":{"points":["Indications : mucite, radiodermite, lymphœdème, neuropathie, entérite radique."],"limites":["Revue narrative ; vision plutôt optimiste de la sécurité."],"pratique":"Pas de conséquence directe."},"topic":"mucite-orale","title":"From molecular mechanisms to clinical applications: A comprehensive review of photobiomodulation in cancer treatment.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["Wang Q","Oh PS","Jeong HJ"],"date":"2025-04-21","year":2025,"week":"2025-S17","doi":"10.1111/php.14107","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Review"],"abstract":[{"label":"","text":"Photobiomodulation (PBM) is a non-invasive therapeutic technique that regulates biological processes using primarily low-power lasers or light-emitting diodes (LEDs) to achieve therapeutic effects. Its application has expanded significantly, particularly in the field of cancer therapy. This review provides a comprehensive overview of PBM, elucidating its underlying mechanisms of action and its potential applications in cancer therapy. It highlights the benefits of PBM in reducing side effects of cancer treatments such as acute oral mucositis, radiation dermatitis, lymphedema, neuropathic pain, and radiation enteropathy. Furthermore, the ability of PBM to inhibit cancer cell proliferation and induce apoptosis, and discusses safety concerns of PBM in clinical applications, presenting existing research that emphasizes its significant potential in cancer therapy was summarized. PBM therapy may offer promising new clinical options for managing cancer and mitigating the side effects associated with conventional cancer therapies."}],"keywords":["cancer","clinical treatment","photobiomodulation","phototherapy"]},{"pmid":"40238654","title_fr":"Effets de la PBM sur l'épithélium embryonnaire de Xenopus laevis","type":"preclinical","level":5,"pop":"—","ctx":[],"aim":"—","mode":["laser"],"nm":[660],"n":null,"effect":"défavorable","theme":"Sécurité oncologique","l1":"Chez le têtard de xénope, trois séances de PBM à 660 nm font apparaître des structures épithéliales anormales (30,6 % des têtards contre 3,8 %) : un signal de sécurité à explorer.","l2":"Laser 660 nm, 2,08 J/cm², 0,208 W/cm², trois séances à 24 h d'intervalle. Les zones anormales correspondent à une perte de polarité et d'organisation cellulaire au bord de la queue.\n\nCe modèle animal ne se transpose pas directement à la muqueuse humaine, mais il justifie des études de sécurité à long terme.","l3":{"points":["Surface anormale : 0,03 % (témoins) contre 0,37 % (PBM), p < 0,0001.","Têtards atteints : 3,8 % contre 30,6 % (p < 0,001)."],"limites":["Modèle embryonnaire amphibien, très éloigné de la clinique."],"pratique":"Respecter les doses recommandées ; rester attentif aux données de sécurité à long terme."},"topic":"mucite-orale","title":"The Effects of Photobiomodulation Therapy on Xenopus laevis Embryonic Epithelium.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Lloyd K","Pitstick L","Gao F","et al."],"date":"2025-04-16","year":2025,"week":"2025-S16","doi":"10.1089/photob.2024.0158","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Background: Photobiomodulation therapy (PBMT) is widely used in clinical settings, particularly for treating oral mucositis. Although PBMT has shown promise in aiding tissue healing, its safety and potential effects on tumorigenesis remain controversial. Objective: Xenopus laevis (X. laevis) tadpoles have proven to be an effective in vivo model system to study how different therapies affect epithelial biology. Because of this, the goal of this study was to investigate how PBMT influences epithelial tissue in X. laevis tadpoles. Methods: X. laevis tadpoles were treated with PBMT three times, every 24 h, using a 660 nm low-level laser at a fluence of 2.08 J/cm2 and an irradiance of 0.208 W/cm2, resulting in a cumulative dose of 2.25 J. Tadpole tails were then fixed, and the abnormal tissue area was analyzed using fluorescent microscopy. Results: PBMT induced the formation of abnormal tissue structures along the epithelial edges. The altered tissue increased from 0.03% in control tadpoles to 0.37% in PBMT-treated tadpoles (p < 0.0001; Mann-Whitney nonparametric test), and the number of tadpoles displaying this abnormal phenotype increased from 3.8% of control tadpoles to 30.6% of PBMT-treated tadpoles (p < 0.001; chi-squared test). Conclusion: This study demonstrates that PBMT can have significant effects on the epithelial tissue of X. laevis. The PBMT-induced abnormal tissue structures represent a loss of tissue polarization and cellular organization along the tail edge, both of which are essential to maintaining tissue homeostasis. For the first time, we show that X. laevis may provide an in vivo model system for examining the effects and mechanisms of PBMT."}],"keywords":["Xenopus","development","photobiomodulation"]},{"pmid":"40184883","title_fr":"PBM pour prévenir les effets indésirables buccaux des traitements ORL : essai randomisé en simple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":[],"nm":[],"n":53,"effect":"favorable","theme":"Efficacité vs soins standards","l1":"Chez 53 patients ORL, la PBM ralentit la progression de la mucite, préserve la fonction salivaire et réduit douleur et dysgueusie, sans effet sur xérostomie, trismus, antalgiques ni candidose.","l2":"Essai espagnol monocentrique (CONSORT, enregistré) comparant PBM et traitement standard. Les critères couvraient l'ensemble des effets buccaux : mucite, douleur, dysgueusie, hyposialie, bouche sèche, trismus, antalgiques et infections fongiques.\n\nBénéfices sur la mucite, l'hyposialie, la douleur et le goût aux moments critiques ; pas d'effet sur les autres critères.","l3":{"points":["Bénéfices : progression de la mucite, fonction salivaire, douleur, dysgueusie.","Sans effet : xérostomie, trismus, consommation d'antalgiques, candidose."],"limites":["Simple aveugle, monocentrique ; paramètres non donnés dans le résumé."],"pratique":"Confirme l'effet sur la mucite ; ne pas promettre d'effet sur le trismus ou la xérostomie."},"topic":"mucite-orale","title":"Photobiomodulation for the prevention of oral side effects secondary to head and neck cancer therapy: results of a randomised, single-blind clinical trial.","journal":"Oral oncology","journal_abbr":"Oral Oncol","authors":["Vianna Camolesi GC","Prado-Pena IB","Gómez-Caamaño A","et al."],"date":"2025-04-03","year":2025,"week":"2025-S14","doi":"10.1016/j.oraloncology.2025.107266","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"INTRODUCTION","text":"A significant increase of 61.6 % in new cases of head and neck cancer (HNC) worldwide is projected by 2050. Multimodal treatments for HNC often result in debilitating oral side effects like oral mucositis (OM). Photobiomodulation (PBM) therapy shows promise in managing these side effects, yet standardized protocols are lacking. This randomized clinical trial aims to evaluate PBM's effectiveness in preventing and treating oral side effects and related symptoms in HNC patients."},{"label":"METHODS","text":"We compared PBM with standard treatment in HNC patients at a single centre. PBM efficacy was evaluated on OM, pain, dysgeusia, hyposalivation, dry mouth, and trismus. Additionally, we controlled for analgesic use and fungal infection presence. The study adhered to the CONSORT checklist, is registered on the ClinicalTrials platform, and statistical analysis was performed using SPSS."},{"label":"RESULTS","text":"The study included 53 patients. The PBM group experienced a significant reduction in OM progression, better salivary function preservation, and lower severity of pain and dysgeusia by the end of treatment. However, no significant differences were found between the PBM and standard treatment groups regarding xerostomia, trismus, analgesic use, or oral candidiasis incidence."},{"label":"CONCLUSION","text":"PBM showed effectiveness in delaying onset and reducing the severity of oral mucositis and hyposalivation, as well as alleviating pain and dysgeusia at critical moments. However, it had no significant impact on xerostomia, trismus, analgesic use, or oral candidiasis."}],"keywords":["Dysgeusia","Hyposalivation","Oral mucositis","Photobiomodulation therapy","Supportive cancer care","Toxicity"]},{"pmid":"40217880","title_fr":"Étude pilote comparant PBM intrabuccale et transcutanée pour la mucite en ORL","type":"protocol","level":0,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":["intrabuccal","extrabuccal","LED"],"nm":[650],"n":null,"effect":"—","theme":"Extra vs intrabuccal","l1":"Protocole français d'essai pilote randomisé comparant un dispositif intrabuccal (CareMin650) et un dispositif transcutané (ATP38) pendant la radiothérapie ORL.","l2":"Étude monocentrique (NCT06458517) dans les cancers de la cavité buccale et de l'oropharynx. Critères : incidence et sévérité de la mucite, interruptions de traitement, douleur et qualité de vie.\n\nPas encore de résultats. Utile car elle porte sur deux dispositifs LED disponibles en France.","l3":{"points":["Dispositifs : CareMin650 (intrabuccal) contre ATP38 (transcutané)."],"limites":["Protocole sans résultats."],"pratique":"À suivre pour le choix du matériel en France."},"topic":"mucite-orale","title":"A Pilot Study Comparing Intraoral and Transcutaneous Photobiomodulation for Oral Mucositis in Head and Neck Cancer Patients Undergoing Radiotherapy or Chemoradiotherapy.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Eber J","Schohn A","Carinato H","et al."],"date":"2025-04-02","year":2025,"week":"2025-S14","doi":"10.3390/jcm14072430","pmcid":"PMC11989608","license":"cc by","oa":true,"pdf":"pdfs/40217880.pdf","cited_by":3,"pub_types":[],"abstract":[{"label":"","text":"Background: Photobiomodulation (PBM) therapy has shown potential in managing oral mucositis (OM), a frequent and painful side effect of radiotherapy or chemoradiotherapy in head and neck cancer patients. Although PBM is increasingly used in clinical settings, the optimal delivery method-transcutaneous or intraoral-remains undetermined. Methods: This prospective, single-center, randomized pilot study (clinicaltrials.gov NCT06458517) aims to compare the efficacy of transcutaneous versus intraoral PBM in preventing and managing OM in patients undergoing radiotherapy or chemoradiotherapy for cancers of the oral cavity or oropharynx. Participants will be randomized into two groups: one receiving intraoral PBM with the CareMin650™ device, and the other receiving transcutaneous PBM with the ATP38® device. Results: Primary and secondary outcomes will include the incidence and severity of OM, treatment interruptions, patient-reported pain levels, and quality of life, assessed using validated tools. Conclusions: This study will provide comparative data on two PBM modalities, contributing to the development of standardized PBM protocols in supportive oncology care and informing future multicenter trials aimed at improving patient outcomes during radiotherapy for head and neck cancer."}],"keywords":["drug therapy","head and neck neoplasms","low-level laser therapy","palliative care","radiotherapy","stomatitis"]},{"pmid":"40172371","title_fr":"Mécanismes de la PBM dans le traitement et la prévention de la mucite : revue systématique","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Mécanismes","l1":"Sept essais cliniques : la PBM diminue les cytokines pro-inflammatoires (IL-6, TNF-α), augmente les anti-inflammatoires (IL-4, IL-10) et la superoxyde dismutase.","l2":"Revue PRISMA (Medline, LILACS, SciELO, BBO) des essais des dix dernières années, avec RoB 2.0 et ROBINS-I. Les essais randomisés présentent un faible risque de biais.\n\nLe mécanisme proposé associe modulation inflammatoire, équilibre des espèces réactives de l'oxygène et expression de gènes de différenciation des kératinocytes.","l3":{"points":["355 études repérées, 7 incluses."],"limites":["Peu d'études, marqueurs différents d'une étude à l'autre."],"pratique":"Pas de conséquence pratique."},"topic":"mucite-orale","title":"Mechanisms of photobiomodulation therapy in treating and preventing antineoplastic-induced oral mucositis: a systematic review.","journal":"Acta cirurgica brasileira","journal_abbr":"Acta Cir Bras","authors":["Sales PVA","Godói IPD","Brito GAC","et al."],"date":"2025-03-31","year":2025,"week":"2025-S14","doi":"10.1590/acb403125","pmcid":"PMC11960598","license":"cc by","oa":true,"pdf":"pdfs/40172371.pdf","cited_by":6,"pub_types":["Systematic Review"],"abstract":[{"label":"PURPOSE","text":"To conduct a systematic review of the mechanisms of photobiomodulation therapy (PBMT) for treating or preventing oral mucositis (OM) caused by antineoplastic therapy."},{"label":"METHODS","text":"Following PRISMA 2020 guidelines, a search was conducted in Medline, Latin American and Caribbean Health Sciences Literature (LILACS), Scientific Electronic Library Online (SciELO), and Bibliografia Brasileira de Odontologia from August to September 2023 using descriptors related to OM and laser therapy. Studies on the mechanisms of photobiomodulation in OM were included. Randomized (RCTs) or non-randomized trials from the past 10 years were reviewed. Risk of bias was assessed using RoB 2.0 and ROBINS-I tools."},{"label":"RESULTS","text":"A total of 355 studies was identified. After the screening, seven met the eligibility criteria. The RCTs showed a low risk of bias. PBMT reduced OM incidence in patients undergoing chemotherapy/radiotherapy. PBMT decreased pro-inflammatory cytokines (interleukin-6, tumor necrosis factor-α) and increased anti-inflammatory cytokines (interleukin-4, interleukin-10). It also modulated inflammatory mediators, enhancing the antioxidant enzyme superoxide dismutase and overexpressing genes for keratinocyte differentiation, aiding injury repair."},{"label":"CONCLUSION","text":"The findings suggested that the mechanism of action of PBMT in OM involves modulation of the inflammatory response, balancing oxygen reactive species generation, and expression of factors related to healing or repair. Further studies are needed to elucidate these mechanisms and optimize treatment protocols."}],"keywords":[]},{"pmid":"42238110","title_fr":"La thérapie par photobiomodulation (revue de l'American Dental Association)","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue de référence de l'ADA (rapport technique n° 189) : terminologie, mécanismes, dispositifs, sécurité, réglementation et logique de prescription de la dose.","l2":"Revue narrative sur l'état de l'art : histoire, terminologie, mécanismes, matériel, sécurité, réglementation et politiques de santé. L'accent est mis sur les modèles de dose et sur la formation des praticiens aux interactions lumière-tissu.\n\nRéférence utile pour la formation des équipes.","l3":{"points":["Version courte : ADA Technical Report n° 189."],"limites":["Revue narrative."],"pratique":"Support de formation recommandé."},"topic":"mucite-orale","title":"Photobiomodulation therapy.","journal":"JADA foundational science","journal_abbr":"JADA Found Sci","authors":["Arany PR"],"date":"2025-03-26","year":2025,"week":"2025-S13","doi":"10.1016/j.jfscie.2025.100045","pmcid":"PMC13229060","license":"cc by","oa":true,"pdf":"pdfs/42238110.pdf","cited_by":14,"pub_types":["Review"],"abstract":[{"label":"OBJECTIVES","text":"The use of low doses of photons (light) in biological tissues to modulate (inhibit or stimulate) responses is termed photobiomodulation (PBM). This nonthermal, noninvasive, and nonsurgical light treatment has been reported to reduce pain or inflammation, modulate immune responses, and promote tissue healing and regeneration. These fundamental pathophysiological responses underlie several oral and dental diseases, highlighting the broad scope of PBM interventions such as alleviating pain, discomfort, and swelling postsurgical procedures, including third-molar extractions, managing oncotherapy-associated mucositis and temporomandibular joint disorders, and promoting accelerated orthodontic tooth movements and implant osseointegration."},{"label":"SEARCH STRATEGY CITATION SOURCES AND DATA ELEMENTS","text":"This narrative review provides the state-of-the-art in the PBM field, including history, terminology, mechanisms, devices, safety, regulations, and policy. The primary emphasis of this work is to outline the advances in mechanistic insights and clinical dosing paradigms that enable the safe and effective use of this therapy."},{"label":"OVERALL CONCLUSIONS","text":"The importance of fundamental PBM education and training concepts focusing on light-tissue interactions, target tissue composition, evoked therapeutic biological responses, clinical diagnosis, and rationalized dose prescriptions is emphasized. Furthermore, several issues and logistical concerns should be addressed to enable the routine use of this innovative nonpharmacological treatment. A succinct version of this article is available as the American Dental Association Technical Report no. 189 Standards Committee on Dental Products Working Group 6.58."}],"keywords":["Photobiomodulation","TGF-β1","low-level light/laser therapy"]},{"pmid":"40881977","title_fr":"PBM préventive et auto-administrée contre la mucite : cas à haut risque","type":"cases","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["laser","domicile"],"nm":[600,904],"n":1,"effect":"favorable","theme":"PBM à domicile","l1":"Un patient sous chimioradiothérapie pour un cancer du nasopharynx, traité par laser 904 nm en séance et par un laser portable auto-appliqué le week-end, n'a eu qu'une mucite légère à modérée, sans opioïdes ni gastrostomie.","l2":"Cas australien : cisplatine hebdomadaire et 70 Gy. Protocole « lymphatique » 904 nm (3 J/point, 200 mW). Les scores se dégradant le lundi, un laser portable a été ajouté pour le week-end à partir de J21.\n\nRésultats : OMAS 6/45, OHIP-14 19/56, ni antalgiques réguliers ni sonde. Un seul cas, avec un intérêt commercial possible (appareil de marque).","l3":{"points":["OMAS 6/45 ; PROMS 28/100 ; OHIP-14 19/56."],"limites":["Cas unique."],"pratique":"Idée à retenir : la pause du week-end peut faire rebondir la mucite."},"topic":"mucite-orale","title":"Preemptive, Self-Applied Photobiomodulation in the Treatment of Oral Mucositis: A High-Risk Case Study.","journal":"Case reports in oncology","journal_abbr":"Case Rep Oncol","authors":["Ryan J","Chong LN","Dunn RJ"],"date":"2025-03-10","year":2025,"week":"2025-S11","doi":"10.1159/000541966","pmcid":"PMC11893146","license":"cc by-nc","oa":true,"pdf":"pdfs/40881977.pdf","cited_by":1,"pub_types":["Case Reports"],"abstract":[{"label":"INTRODUCTION","text":"Oral mucositis (OM) is a prevalent and debilitating complication of antineoplastic therapy and hematopoietic stem cell transplantation. Effective OM treatment has important economic, quality of life (QoL), and healthcare implications. Photobiomodulation (PBM) emerges as an innovative addition to the treatment paradigm, using red and near-infrared light to relieve pain and stimulate tissue repair without significant toxicity. Although the role of PBM is well established in international guidelines, optimal timing and delivery of therapy remain unclear. Several studies have reported encouraging data, advocating for a preemptive and self-applied approach to PBM."},{"label":"CASE PRESENTATION","text":"We describe a high-risk case of locally advanced (T2N1M0, stage II) nasopharyngeal squamous cell carcinoma. The patient was treated with primary chemoradiation consisting of weekly cisplatin and a radiation dose of 70 Gy in 35 fractions to the nasopharynx, lymph nodes, and surrounding soft tissues. As per the 904 nm laser lymphatic protocol, 3J/point was delivered over 30 s at an output power of 200 mW in the continuous mode, targeting the tongue, gingiva, buccal mucosa, and hard palate. Various clinical outcome measures were documented including self-reported health status (PROMS), oral health-related quality of life (OHIP-14), and objective OM severity (OMAS). Owing to raised PROMS and OHIP-14 scores on Mondays reflecting symptom exacerbation over the weekend, the study protocol was adjusted at day 21 to include a portable SYMBYX 600 nm laser for the patient to self-apply over the weekend. In contrast to expected outcomes for concurrent chemoradiation, the patient developed only mild to moderate OM: PROMS (28/100), OHIP-14 (19/56), and OMAS (6/45). Further, the patient did not require regular analgesia, opioid analgesics, or gastrostomy tube placement."},{"label":"CONCLUSION","text":"Preemptive PBM using the 904 nm laser lymphatic protocol, supplemented by a self-applied SYMBYX 600 nm laser to facilitate continued treatment over the weekends, shows promise as an effective therapy for reducing OM severity in high-risk patients. Further studies are required to clarify optimal timing and delivery of PBM within the OM treatment paradigm."}],"keywords":["Case report","Head and neck cancer","Oral mucositis","Photobiomodulation","Stomatitis"]},{"pmid":"39910516","title_fr":"Préconditionnement par PBM pour prévenir la mucite et améliorer la qualité de vie sous chimiothérapie : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["chimio"],"aim":"prévention","mode":["intrabuccal","extrabuccal","laser"],"nm":[650,980],"n":45,"effect":"favorable","theme":"Efficacité vs soins standards","metric":{"kind":"rates","outcome":"Mucite à 2 semaines","a_label":"PBM intrabuccale","a":20,"b_label":"Conseils seuls","b":93.3},"l1":"Une PBM débutée avant la première chimiothérapie évite la mucite chez 80 à 87 % des patients à 2 semaines, contre 7 % avec les seuls conseils d'hygiène ; la qualité de vie est meilleure.","l2":"Essai syrien en double aveugle à trois groupes de 15 patients : conseils seuls, + PBM intrabuccale 650 nm, + PBM intrabuccale 650 nm et extrabuccale 980 nm. Patients recevant une chimiothérapie seule pour la première fois.\n\nÀ 2 semaines, 93,3 % des témoins avaient une mucite contre 20 % et 13,3 % dans les groupes laser, avec seulement de l'érythème. Les différences d'ulcération (13,3 % contre 0 %) ne sont pas significatives. OHIP-14 et LENT-SOMA sont meilleurs sous PBM.","l3":{"points":["Enregistrement ISRCTN70634383.","Sans mucite à S2 : 80 % (IO) et 86,7 % (IO + EO) contre 6,7 % (témoin).","Ulcérations : 0 % contre 13,3 % (p = 0,129)."],"limites":["15 patients par groupe ; chimiothérapies variées.","Même population probable que l'essai sur le nitrite salivaire (PMID 40340568)."],"pratique":"La PBM avant la première cure de chimiothérapie est une stratégie simple et prometteuse."},"topic":"mucite-orale","title":"Photobiomodulation preconditioning for oral mucositis prevention and quality of life improvement in chemotherapy patients: a randomized clinical trial.","journal":"BMC oral health","journal_abbr":"BMC Oral Health","authors":["Khalil M","Hamadah O","Saifo M"],"date":"2025-02-05","year":2025,"week":"2025-S06","doi":"10.1186/s12903-025-05579-1","pmcid":"PMC11800611","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/39910516.pdf","cited_by":7,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"BACKGROUND","text":"Given the suffering experienced by cancer patients, effective solutions must be found to prevent painful and debilitating side effects of anti-cancer treatment. This trial aims to study the effect of preconditioning with photobiomodulation in preventing oral mucositis and xerostomia in cancer patients undergoing chemotherapy alone for the first time, and to examine its role in improving patients' quality of life."},{"label":"MATERIALS AND METHODS","text":"This is a prospective, randomized, double-blind clinical trial including 45 patients divided into three age- and sex-matched groups. Group 1 received basic oral care instructions before undergoing chemotherapy. Group 2 received basic oral care instructions plus photobiomodulation using an intraoral 650 nm diode laser. Group 3 received basic oral care instructions plus photobiomodulation using a 650 nm diode laser intraorally and a 980 nm diode laser extraorally."},{"label":"RESULTS","text":"After one week of follow-up, 73.3% of patients in Group 2 and 80% in Group 3 did not develop oral mucositis. The remaining patients in both groups experienced only mild erythema. In contrast, all patients in Group 1 developed oral mucositis, ranging from mild erythema to ulceration greater than 3 cm². After two weeks of follow-up, 80% of patients in Group 2 and 86.7% in Group 3 remained free of oral mucositis. The remaining patients in both groups experienced only mild erythema. In contrast, 93.3% of patients in Group 1 developed oral mucositis, with cases ranging from mild erythema to ulcers larger than 3 cm². There were statistically significant differences between the three groups in oral mucositis assessment scale after one week and after two weeks (p < 0.001). Specifically, ulcerative mucositis was not observed in both laser groups, while it was observed in 13.3% of patients in Group 1. However, these differences were not statistically significant (p = 0.129). Regarding Late Effects in Normal Tissue (LENT-SOMA) scale, there was a statistically significant difference between the three groups studied (p = 0.037). There was also a statistically significant difference in the Oral Health Impact Profile (OHIP-14) between the three groups studied (p = 0.003 after one week, p = 0.023 after two weeks)."},{"label":"CONCLUSION","text":"Preconditioning before starting chemotherapy, whether with the intraoral red laser alone or in combination with the extraoral infrared laser, has shown significant results in preventing oral mucositis and dry mouth, and it has also played a major role in improving patients' quality of life."},{"label":"TRIAL REGISTRATION","text":"This trial was registered in ISRCTN registry under no ISRCTN70634383 ( https://doi.org/10.1186/ISRCTN70634383 ) on 24/07/2023."}],"keywords":["Oral mucositis","Photobiomodulation","Preconditioning","Quality of life","Xerostomia"]},{"pmid":"39889324","title_fr":"Efficacité de la PBM (laser basse énergie) pour traiter la mucite chimioradio-induite en ORL","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"traitement","mode":["laser"],"nm":[810],"n":36,"effect":"favorable","theme":"Traitement curatif","l1":"Chez 36 patients ORL avec mucite de grade 3–4, quatre jours de laser 810 nm soulagent mieux la douleur et améliorent plus la qualité de vie qu'un bain de bouche, avec un effet sur la sévérité limité à la première semaine.","l2":"Essai iranien en simple aveugle : laser portable 810 nm, 200 mW, 6 J/cm² pendant 4 jours (n = 18), contre bain de bouche diphénhydramine + hydroxyde d'aluminium-magnésium toutes les 6 h (n = 18).\n\nLa douleur baisse nettement sous laser. La sévérité est réduite à une semaine mais plus à un mois (p = 0,158).","l3":{"points":["Évaluations avant traitement, à 1 semaine et à 1 mois."],"limites":["Petit effectif ; simple aveugle ; comparateur actif peu standardisé."],"pratique":"La PBM curative soulage vite la mucite sévère ; l'effet sur la cicatrisation à long terme reste incertain."},"topic":"mucite-orale","title":"Effectiveness of Photobiomodulation (low-level laser therapy) on treatment of oral mucositis (OM) induced by chemoradiotherapy in head and neck cancer patients.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Barati S","Motevasseli S","Saedi HS","et al."],"date":"2025-01-26","year":2025,"week":"2025-S04","doi":"10.1016/j.jphotobiol.2025.113115","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":11,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"PURPOSE","text":"Mucositis is a common and debilitating side effect of cancer treatment, causing significant pain and discomfort. This study aimed to evaluate the effectiveness of Photobiomodulation in treating mucositis induced by chemoradiotherapy in cancer patients."},{"label":"METHODS","text":"This randomized, single-blind clinical trial involved 36 patients with grade 3-4 oral mucositis. The test group (n = 18) received diode portable laser therapy (810 nm wavelength, 200 mW power, 6 J/cm2 energy density) for 4 days. The control group (n = 18) used a Diphenhydramine + Almgs mouthwash (50-50% mixture, 15 ml, every 6 h for 4 days). Lesions were assessed before treatment, one week after, and again at one month."},{"label":"RESULTS","text":"Pain scores in the laser group decreased significantly over time (P < 0.05). Patients in the laser group reported better quality of life and reduced oral discomfort compared to the control group (P < 0.05). The severity of mucositis significantly decreased in the laser group within the first week (P < 0.05), though no significant difference was observed at one month (P = 0.158)."},{"label":"CONCLUSION","text":"The study demonstrates that Photobiomodulation is a more effective and efficient method for reducing pain, tingling, and improving quality of life in both the short and long term. It also reduces the severity of oral mucositis in the short term for patients with head and neck cancer undergoing chemoradiotherapy."}],"keywords":["Drug therapy","Head and neck neoplasms","Low-level light therapy","Mucositis","Radiotherapy"]},{"pmid":"40002682","title_fr":"PBM préventive de la mucite chimio-induite : revue systématique d'essais randomisés","type":"sr","level":1,"pop":"mixte","ctx":["chimio"],"aim":"prévention","mode":[],"nm":[],"n":828,"effect":"favorable","theme":"Synthèse des preuves","l1":"Treize essais randomisés (828 patients sous chimiothérapie, sans radiothérapie) : 128 mucites dans les groupes PBM contre 211 dans les groupes témoins.","l2":"Revue PRISMA enregistrée (PROSPERO) sur sept bases, recherche en août 2024, outil JBI pour le biais. Patients de 1 à 84 ans, sans prédisposition liée au sexe ou à l'âge.\n\n41 % des patients ont eu une mucite au total ; 85 % des études ont un faible risque de biais. Le résumé ne donne pas d'estimation poolée.","l3":{"points":["13 ECR, 828 patients.","Mucite : 128 (PBM) contre 211 (témoins)."],"limites":["Pas de méta-analyse ; effectifs de chaque bras non précisés."],"pratique":"Soutient la PBM préventive en chimiothérapie seule."},"topic":"mucite-orale","title":"Preventive Photobiomodulation for Chemotherapy-Induced Oral Mucositis: A Systematic Review of Randomized Clinical Trials.","journal":"Biomedicines","journal_abbr":"Biomedicines","authors":["Parra-Rojas S","Velázquez-Cayón RT","Ciortan-Pop ME","et al."],"date":"2025-01-22","year":2025,"week":"2025-S04","doi":"10.3390/biomedicines13020268","pmcid":"PMC11852607","license":"cc by","oa":true,"pdf":"pdfs/40002682.pdf","cited_by":12,"pub_types":["Review"],"abstract":[{"label":"","text":"Background/Objectives: Oral mucositis (OM) is the most common acute complication among cancer patients. It initially manifests as an inflammatory process, beginning with erythema and edema of the oral mucosa, progressing to erosive lesions, and ultimately leading to highly painful ulcers. This systematic review seeks to evaluate the efficacy of preventive PBM protocols in mitigating chemotherapy-induced OM. Methods: The PRISMA guidelines were followed. The search was conducted in August 2024 in the following databases: Pubmed/Medline, Scopus, WoS, Cochrane, SciELO, BDTD, and BVS/IBECS. Only randomized clinical trials that utilized preventive photobiomodulation protocols in chemotherapy patients were included. All studies involving patients previously treated with radiation therapy were excluded. The Joanna Briggs Institute tool was employed for risk of bias analysis. Results: The total sample size consisted of 828 patients aged between 1 and 84 years. There was no predisposition based on gender or age. When the patients were evaluated under preventive protocols, some cases of mucositis manifested in a total of 339 cases. Of the total number of patients in the 13 selected studies (n = 828), 40.94% developed oral mucositis over the course of chemotherapy cycles. Comparing the experimental and control groups, 211 patients who did not receive preventive laser treatment developed oral mucositis; in contrast, only 128 in the experimental group did. Eighty-five percent of the studies exhibited a low risk of bias. Conclusions: Preventively applied photobiomodulation proves effective in minimizing or even preventing the manifestation of oral mucositis and reducing the severity of lesions that arise during oncological treatment. Registration PROSPERO (CRD42023465329)."}],"keywords":["chemotherapy","oral mucositis","photobiomodulation","preventive protocols","radiotherapy"]},{"pmid":"39799794","title_fr":"Stratégies de prise en charge de la mucite chimio- et radio-induite","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue de Cancer Treatment Reviews : PBM et cryothérapie buccale sont les deux approches les plus fortement recommandées quand elles sont réalisables.","l2":"La revue fait le point sur les options nouvelles et repositionnées : mélatonine, clonidine, pentoxifylline, SAMITAL, IL-11, probiotique S. salivarius K12, curcuma. Les études de haut niveau des deux dernières années renforcent la PBM et la cryothérapie.\n\nLes auteurs rappellent de tenir compte de l'accessibilité et du rapport coût-efficacité.","l3":{"points":["Recommandations fortes : PBM, cryothérapie.","Options à valider : clonidine topique, mélatonine, pentoxifylline, SAMITAL, rhIL-11, SsK12, curcuma."],"limites":["Revue narrative."],"pratique":"Bonne carte de l'arsenal thérapeutique en 2025."},"topic":"mucite-orale","title":"Managing strategies of chemotherapy and radiotherapy-induced oral mucositis.","journal":"Cancer treatment reviews","journal_abbr":"Cancer Treat Rev","authors":["Wu Y","Shi W","Li C","et al."],"date":"2025-01-07","year":2025,"week":"2025-S02","doi":"10.1016/j.ctrv.2025.102883","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":9,"pub_types":["Review"],"abstract":[{"label":"","text":"Radiotherapy and chemotherapy are widely employed as primary non-surgical cancer treatments; however, their non-selective cytotoxicity often leads to adverse events such as oral mucositis (OM), particularly in head and neck cancer therapies. International guidelines provide recommendations for managing chemoradiotherapy-induced OM in various clinical contexts. Subsequently, emerging researches have introduced evidence supporting novel approaches or existing regimens for OM prevention and treatment. The repurposing of established drugs has garnered significant interest due to its shorter development timeline, improved safety profiles, and lower costs compared to new drug development. For example, clinical trials assessing established drugs such as melatonin, clonidine, and pentoxifylline indicate promising potential for managing OM. Additionally, several emerging pharmacological interventions have demonstrated considerable efficacy; SAMITAL and rhIL-11 are supported by phase II clinical trials and prospective studies, while probiotics like Streptococcus salivarius K12 and curcumin have shown effectiveness in randomized clinical trials. Furthermore, recent high-level studies have reinforced the efficacy of non-pharmacological interventions, such as photobiomodulation (PBM) and cryotherapy, over the past two years. In all, given the evidence supporting different strategies, PBM and oral cryotherapy are highly recommended for managing OM when feasible. Topical clonidine, melatonin, oral pentoxifylline, topical SAMITAL or rhIL-11, oral SsK12, and curcumin may also be utilized but would benefit from validation in larger trials. Besides, Verbascoside, Palifermin, Amifostine, and Avasopasem manganese can be suggested for OM management, while the side effects should be monitored. The accessibility and cost/effectiveness of specific managing strategies of OM should be considered when selecting appropriate options."}],"keywords":[]},{"pmid":"39794168","title_fr":"Les preuves du laser basse énergie contre la mucite en radiothérapie ORL (éditorial)","type":"letter","level":0,"pop":"adulte","ctx":["ORL"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Éditorial de Clinical Oncology sur le niveau de preuve du laser basse énergie en radiothérapie ORL. Pas de résumé disponible.","l2":"Éditorial publié par la revue du Royal College of Radiologists. Le titre indique une mise au point sur les preuves en radiothérapie ORL, un sujet discuté au Royaume-Uni où la PBM est encore peu déployée.\n\nContenu non indexé sur PubMed.","l3":{"points":["Éditorial, sans données originales."],"limites":["Résumé indisponible."],"pratique":"—"},"topic":"mucite-orale","title":"The Evidence for Low-level Laser Therapy for Oral Mucositis in Head and Neck Cancer Radiotherapy.","journal":"Clinical oncology (Royal College of Radiologists (Great Britain))","journal_abbr":"Clin Oncol (R Coll Radiol)","authors":["O'Hara J","Iqbal MS"],"date":"2024-12-14","year":2024,"week":"2024-S50","doi":"10.1016/j.clon.2024.103731","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Editorial"],"abstract":[],"keywords":[]},{"pmid":"39625051","title_fr":"Interventions pour prévenir la mucite chez les personnes traitées pour un cancer : photobiomodulation (protocole Cochrane)","type":"protocol","level":0,"pop":"mixte","ctx":["mixte"],"aim":"prévention","mode":[],"nm":[],"n":null,"effect":"—","theme":"Synthèse des preuves","key":true,"l1":"Protocole de la future revue Cochrane dédiée à la PBM pour prévenir la mucite (cancers ORL, autres tumeurs solides, hémopathies). Revue très attendue.","l2":"Cochrane annonce une revue spécifique à la PBM, qui détaillera ses effets selon le type de cancer et de traitement.\n\nLorsqu'elle paraîtra, elle deviendra probablement la référence méthodologique. À surveiller dans la veille.","l3":{"points":["Populations : ORL, tumeurs solides, hémopathies."],"limites":["Protocole sans résultats."],"pratique":"Surveiller la publication de la revue complète."},"topic":"mucite-orale","title":"Interventions for preventing oral mucositis in people receiving cancer treatment: photobiomodulation.","journal":"The Cochrane database of systematic reviews","journal_abbr":"Cochrane Database Syst Rev","authors":["Lewis SR","Riley P","Deligianni E","et al."],"date":"2024-12-03","year":2024,"week":"2024-S49","doi":"10.1002/14651858.CD016068","pmcid":"PMC11613434","license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"This is a protocol for a Cochrane Review (intervention). The objectives are as follows: To assess the effects of photobiomodulation for the prevention of oral mucositis in people undergoing treatment for head and neck cancers, other solid cancers, and haematological cancers."}],"keywords":[]},{"pmid":"39615560","title_fr":"Thérapie photodynamique pour la mucite en cancérologie : revue systématique et méta-analyse","type":"ma","level":3,"pop":"mixte","ctx":["chimio"],"aim":"traitement","mode":["PDT"],"nm":[],"n":null,"effect":"favorable","theme":"Associations","l1":"Sept études : associer thérapie photodynamique et PBM accélère la cicatrisation et réduit la douleur mieux que la PBM seule (DMS −0,51).","l2":"Revue d'essais randomisés et non randomisés (2000–mai 2024). Méta-analyse sur 4 études : différence moyenne standardisée −0,51 (IC95 % −0,88 à −0,15), toutes les estimations allant dans le même sens.\n\nPiste curative, à confirmer sur des effectifs plus larges.","l3":{"points":["DMS −0,5138 (−0,8799 à −0,1477), k = 4."],"limites":["Études non randomisées incluses ; petit nombre d'études."],"pratique":"Combinaison PDT + PBM à envisager pour les mucites installées, dans un cadre de recherche."},"topic":"mucite-orale","title":"Photodynamic therapy for oral mucositis in cancer patients- a systematic review and meta-analysis.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Joseph B","Mauramo M","Vijayakumary BK","et al."],"date":"2024-11-28","year":2024,"week":"2024-S48","doi":"10.1016/j.pdpdt.2024.104424","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":4,"pub_types":["Meta-Analysis","Systematic Review"],"abstract":[{"label":"AIM","text":"This systematic review aimed to evaluate the efficacy of photodynamic therapy (PDT) in reducing the severity of chemotherapy-induced oral mucositis, and associated symptoms in cancer patients compared to standard care or other interventions."},{"label":"MATERIALS AND METHODS","text":"A comprehensive literature search identified seven relevant studies (randomized controlled trials and non-randomized clinical trials) published between January 1, 2000, and May 31, 2024. The data analysis was carried out using the standardized mean difference as the outcome measure. A random-effects model was fitted to the data. The rank correlation test and the regression test, using the standard error of the observed outcomes as predictors, were used to check for funnel plot asymmetry."},{"label":"RESULTS","text":"Studies combining PDT with photobiomodulation therapy (PBMT) consistently showed superior therapeutic outcomes compared to PBMT alone, particularly in accelerating healing and reducing pain. In the meta-analysis (k = 4), the observed standardized mean differences ranged from -0.9605 to -0.0223, with most estimates being negative (100 %). The estimated average standardized mean difference based on the random-effects model was -0.5138 (95% CI: -0.8799 to -0.1477)."},{"label":"CONCLUSION","text":"PDT, especially when combined with PBMT, shows promise in reducing the severity of oral mucositis and associated symptoms in cancer patients."}],"keywords":["Antimicrobial photodynamic therapy","Cancer therapy","Meta-analysis","Oral mucositis","Photodynamic therapy","Systematic review"]},{"pmid":"39926956","title_fr":"Revue générale du laser basse énergie en odontologie","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Panorama des usages du laser basse énergie en odontologie, dont la mucite. Sans méthode systématique.","l2":"Revue courte des effets anti-inflammatoires, antalgiques et biostimulants : douleur postopératoire, cicatrisation, troubles temporo-mandibulaires, mucite, orthodontie.\n\nPas de données nouvelles.","l3":{"points":["Revue pédagogique."],"limites":["Méthode non décrite."],"pratique":"—"},"topic":"mucite-orale","title":"Comprehensive Review on Low-Level Laser Therapy in Dentistry.","journal":"Journal of pharmacy & bioallied sciences","journal_abbr":"J Pharm Bioallied Sci","authors":["Singh S","Chakraborty A","Saju AR","et al."],"date":"2024-11-27","year":2024,"week":"2024-S48","doi":"10.4103/jpbs.jpbs_1261_24","pmcid":"PMC11805236","license":"cc by-nc-sa","oa":true,"pdf":"pdfs/39926956.pdf","cited_by":2,"pub_types":["Review"],"abstract":[{"label":"","text":"Low-level laser therapy (LLLT) has broad applications in dentistry, enhancing patient outcomes through its anti-inflammatory, analgesic, and biostimulatory effects. It is used for reducing pain and swelling, accelerating wound healing, and promoting tissue regeneration. LLLT is effective in managing conditions, such as temporomandibular disorders (TMDs), oral mucositis, and postoperative discomfort. Additionally, it aids in orthodontics by accelerating tooth movement and mitigating associated pain. This non-invasive treatment offers a safe, efficient, and clinically proven approach, integrating well into various dental procedures to improve overall patient care and recovery."}],"keywords":["Dentistry","LLLT","low-level laser therapy"]},{"pmid":"39523254","title_fr":"PBM et mucite chez l'enfant : revue systématique","type":"sr","level":3,"pop":"pédiatrie","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"Vingt études pédiatriques : aucun effet indésirable et une seule étude sans bénéfice ; la PBM soulage la douleur et accélère la cicatrisation.","l2":"Revue enregistrée (PROSPERO) sur PubMed, Embase, Cochrane et la littérature grise. L'effet antalgique est le plus constant ; la réduction de la sévérité, de la durée voire de l'incidence est aussi rapportée.\n\nL'effet préventif et les protocoles optimaux restent à préciser par des études de meilleure qualité.","l3":{"points":["20 études, designs variés."],"limites":["Qualité des études hétérogène, pas de méta-analyse."],"pratique":"Encourage l'usage de la PBM en pédiatrie, surtout pour la douleur."},"topic":"mucite-orale","title":"Photobiomodulation for oral mucositis management in pediatric patients: a systematic review.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Calarga CC","Cotomácio CC","Simões A"],"date":"2024-11-10","year":2024,"week":"2024-S45","doi":"10.1007/s10103-024-04221-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"This review aimed to determine whether photobiomodulation therapy (PBMT) is a safe and effective alternative for treating and preventing OM in children. The database search was carried out on PubMed, Embase, and Cochrane. Gray literature was also consulted through Google Scholar. Among 20 studies included, no adverse effect was reported, and only one study did not show any evidence of benefit from the use of PBMT. The analgesic effect of PBMT was emphasized and its action in accelerating the healing process and reducing the severity, duration and even incidence of OM was also noted. Evidence was found to encourage the use of PBMT to treat OM in pediatric patients. Higher quality studies must be developed in order to clarify the PBMT prophylactic effect and the best protocols for each clinical situation.The protocol of this review was registered on PROSPERO (CRD42023418109)."}],"keywords":["Child","Low-level light therapy","Neoplasms","Stomatitis","Systematic review"]},{"pmid":"39501907","title_fr":"PBM pour prévenir la mucite chimio-induite chez l'enfant atteint de leucémie aiguë myéloïde : essai randomisé en double aveugle","type":"rct","level":2,"pop":"pédiatrie","ctx":["chimio"],"aim":"prévention","mode":["laser"],"nm":[660],"n":42,"effect":"favorable","theme":"Efficacité vs placebo","l1":"Chez 42 enfants atteints de LAM (Le Caire), cinq jours de PBM à 660 nm réduisent l'incidence et la sévérité de la mucite à J12, J19 et J30 par rapport à la simulation.","l2":"Essai en double aveugle contre simulation, en plus du protocole préventif standard. Laser diode 660 nm, 10 s par point, J1 à J5 de la chimiothérapie. Mucite cotée OMS et NCI à J5, J12, J19 et J30.\n\nEffets importants (tailles d'effet 0,58 à 0,80) en faveur de la PBM à chaque temps.","l3":{"points":["Tailles d'effet : 0,796 (J12), 0,670 (J19), 0,576 (J30), p < 0,001."],"limites":["Monocentrique ; puissance annoncée (« 15 watt ») probablement erronée dans le résumé."],"pratique":"Soutient la PBM préventive en LAM pédiatrique."},"topic":"mucite-orale","title":"Photobiomodulation Therapy in the Prevention of Chemotherapy Induced Oral Mucositis in Children with Acute Myeloid Leukemia: A Randomized, Double-blind, Clinical trial.","journal":"Pediatric blood & cancer","journal_abbr":"Pediatr Blood Cancer","authors":["Elkady RE","Khedr R","Hassan M","et al."],"date":"2024-11-06","year":2024,"week":"2024-S45","doi":"10.1002/pbc.31400","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"BACKGROUND","text":"Many preventive modalities have been advocated to reduce the incidence and severity of chemotherapy-induced Oral Mucositis (OM). Photobiomodulation, also known as Low-Level laser. Therapy, has shown promising results. This clinical trial was performed to evaluate the effectiveness of Photobiomodulation (PBM) for the prevention of chemotherapy-induced oral mucositis (OM) in children with Acute Myeloid Leukemia (AML)."},{"label":"PATIENTS AND METHODS","text":"A double-blinded randomized clinical trial was performed, including forty-two children diagnosed with Acute Myeloid Leukemia (AML) admitted to receiving chemotherapy (CT) at Children's Cancer Hospital 57357, Cairo, Egypt. Patients were randomly assigned to either the control or test group. Both groups followed the standard preventive protocol for oral mucositis. In the control group I sham therapy, while in the Laser group I had Photobiomodulation sessions for five consecutive days once a day performed by Diode laser (Sirrolaser Blue ™, USA) 660nm, 15watt, 10 s. Laser sessions began on day 1 of chemotherapy and were repeated on days 2,3, 4, and 5. The response to both groups was evaluated according to the development of oral mucositis; graded using the classification criteria of the World Health Organization (WHO) and the National Cancer Institute scale (NCI - Common Terminology Criteria for Adverse Events, version 4.0). Incidence of oral mucositis was evaluated from baseline to 5, 12, 19, and 30 days after treatment."},{"label":"RESULTS","text":"A clinical significant difference between the laser and control group was observed. The laser group showed a higher prevalence of no oral mucositis with decreased incidence of OM, while on day 12, the control group showed a higher prevalence of grades I and II (P-value <0.001, effect size = 0.796). However, the laser group showed higher prevalence of mucosa free of OM; on day 19, the control group showed higher rates of grades II and III, (P-value <0.001, effect size = 0.670). while on day 30 there was higher rates of grades I and II (P-value <0.001, effect size = 0.576) with higher rates of healthy oral mucosa in the laser group."},{"label":"CONCLUSION","text":"Photobiomodulation effectively reduces the incidence and severity of chemotherapy-induced oral mucositis in pediatric patients diagnosed with AML."}],"keywords":["Acute myeloid Leukemia","Low‐Level Laser Therapy","Oral mucositis","Pediatric Cancer","Photobiomodulation"]},{"pmid":"39491499","title_fr":"Laser haute puissance contre la mucite chimio-induite de l'enfant : réponse au Dr Morankar","type":"letter","level":0,"pop":"pédiatrie","ctx":["chimio"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Échange de correspondance sur un article évaluant le laser haute puissance en oncopédiatrie. Pas de résumé.","l2":"Fait partie d'une série de trois lettres (Dr Morankar, Dr Jin, correspondance de juin 2024) dans l'International Journal of Paediatric Dentistry, qui discutent la méthodologie d'un article sur la PBM haute puissance chez l'enfant.\n\nLe débat porte sur une modalité encore peu validée.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Evaluation of high-power laser therapy as treatment of chemotherapy-induced oral mucositis in paediatric patients with oncohematological diseases-Dr Morankar.","journal":"International journal of paediatric dentistry","journal_abbr":"Int J Paediatr Dent","authors":["Ludovichetti FS","Costa G","Signoriello AG","et al."],"date":"2024-11-03","year":2024,"week":"2024-S44","doi":"10.1111/ipd.13280","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"39480546","title_fr":"PBM pour prévenir et traiter la mucite en greffe de cellules souches : évaluation de la qualité des soins","type":"cohort","level":4,"pop":"adulte","ctx":["CSH"],"aim":"les deux","mode":[],"nm":[],"n":35,"effect":"favorable","theme":"Implantation","l1":"Chez 35 greffés, des indicateurs qualité (SQUIRE 2.0) montrent 100 % de conformité du protocole PBM et des mucites surtout de grade 1.","l2":"PBM pendant le conditionnement puis à J1, J5 et J10 post-greffe. 66,6 % des patients ont eu une mucite à au moins un moment, majoritairement de grade 1 ; quatre patients (16,7 %) ont eu des douleurs.\n\nÉtude surtout utile pour sa méthode d'évaluation de la qualité d'un programme de PBM.","l3":{"points":["4 indicateurs de processus, 13 indicateurs de résultat."],"limites":["Sans témoin, petit effectif."],"pratique":"Modèle d'indicateurs pour auditer un programme de PBM."},"topic":"mucite-orale","title":"Photobiomodulation for the prevention and treatment of oral mucositis in patients submitted to hematopoietic stem cell transplantation: health quality evaluation.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Marinho LCN","Freire GCB","de Araújo Silva DN","et al."],"date":"2024-10-31","year":2024,"week":"2024-S44","doi":"10.1007/s00520-024-08952-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"To evaluate the quality of oral health care through indicators in patients undergoing hematopoietic stem cell transplantation for the management of oral mucositis."},{"label":"METHODS","text":"Thirty-five patients were evaluated. Photobiomodulation was performed during the conditioning regimen, 1 day, 5 days, and 10 days after transplantation. Four process indicators and 13 outcome indicators were used to evaluate the effectiveness of the intervention, according to SQUIRE 2.0."},{"label":"RESULTS","text":"All process indicators demonstrated a compliance rate of 100% to the desired standard. Outcome indicators revealed that 66.6% of patients experienced mucositis during at least one follow-up period. A statistically significant increase was observed between periods of 1 and 5 days post-transplant, as well as between 1 and 10 days post-transplant (p < 0.05), with a predominance of grade I mucositis (p = 0.014). Four patients (16.7%) reported feeling pain, occurring between 5 and 10 days after transplantation, with moderate pain being the most prevalent. Oral mucositis did not show a statistically significant association with pain, associated treatments, leukopenia, comorbidities, or type of transplant."},{"label":"CONCLUSIONS","text":"The indicators demonstrated their suitability for evaluating oral health in both the prevention and treatment of oral mucositis in these patients. Furthermore, the effectiveness of photobiomodulation in improving the quality of oral health in the patients studied was confirmed."}],"keywords":["Health care quality assessment","Hematopoietic stem cell transplantation","Low-level light therapy","Oral mucositis","Photobiomodulation therapy","Quality of health care"]},{"pmid":"39482275","title_fr":"Laser haute puissance contre la mucite chimio-induite de l'enfant : réponse au Dr Jin","type":"letter","level":0,"pop":"pédiatrie","ctx":["chimio"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Suite de l'échange sur le laser haute puissance en oncopédiatrie. Pas de résumé.","l2":"Réponse des auteurs à une lettre critique. Voir aussi les lettres du 3 juin et du 3 novembre 2024.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Evaluating high power laser therapy (HPLT) as treatment for chemotherapy-induced oral mucositis in paediatric patients with oncohematological diseases- Dr Jin.","journal":"International journal of paediatric dentistry","journal_abbr":"Int J Paediatr Dent","authors":["Ludovichetti FS","Costa G","Signoriello AG","et al."],"date":"2024-10-31","year":2024,"week":"2024-S44","doi":"10.1111/ipd.13281","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"39461860","title_fr":"PBM pour prévenir la mucite et l'altération fonctionnelle chez l'adulte greffé : protocole d'essai randomisé (POMFITT)","type":"protocol","level":0,"pop":"adulte","ctx":["CSH"],"aim":"prévention","mode":["laser"],"nm":[],"n":30,"effect":"—","theme":"Efficacité vs soins standards","l1":"Protocole de l'essai chilien POMFITT (30 greffés) ; les résultats sont parus en juillet 2026 (0 % de mucite sévère sous PBM contre 26,6 %).","l2":"Essai randomisé avec évaluateur et statisticien en aveugle, PBM trois fois par semaine du conditionnement à J+3. Critères : mucite (OMS), test de marche de 2 min, force de préhension, lever de chaise, FACT-BMT, acceptabilité.\n\nExemple de suivi d'un essai du protocole à la publication.","l3":{"points":["NCT06260111 ; résultats : PMID 42399564."],"limites":["Protocole."],"pratique":"Voir la fiche des résultats 2026."},"topic":"mucite-orale","title":"Photobiomodulation therapy to prevent oral mucositis and functional impairment in adult patients with haematological cancer undergoing haematopoietic stem cell transplantation: randomised trial protocol.","journal":"BMJ open","journal_abbr":"BMJ Open","authors":["López-Espinoza T","Sacomori C","Araya-Castro P","et al."],"date":"2024-10-26","year":2024,"week":"2024-S43","doi":"10.1136/bmjopen-2024-088073","pmcid":"PMC11529764","license":"cc by-nc","oa":true,"pdf":"pdfs/39461860.pdf","cited_by":2,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"INTRODUCTION","text":"Oral mucositis is a highly prevalent condition in individuals treated for haematological neoplasms, primarily during haematopoietic stem cell transplantation (HSCT). The condition is known to delay recovery processes, increasing the risk of infection, the number of interventions and the length of hospital stays. The proposed Photobiomodulation Therapy for Oral Mucositis and Functional Impairment Transplantation Trial aims to assess the effectiveness and acceptability of using photobiomodulation in the oral cavity to prevent oral mucositis and functional impairment in adult patients undergoing HSCT."},{"label":"METHODS AND ANALYSIS","text":"This is an assessor-blinded and statistician-blinded, parallel-group randomised controlled clinical trial (photobiomodulation vs control group)."},{"label":"PARTICIPANTS AND SETTING","text":"30 patients, aged 18-65 years, with haematological neoplasms undergoing HSCT at the Clínica Dávila Oncology and Bone Marrow Transplant Unit."},{"label":"PRIMARY OUTCOME MEASURES","text":"oral mucositis will be assessed daily using the WHO grading scale, beginning on the day of transplant through day 20 post-transplant. Researchers will assess functional capacity using a 2 min step test, handgrip strength with the Jamar digital dynamometer, lower limb strength using a 30' sit-to-stand test and quality of life with the Functional Assessment of Cancer Therapy-Bone Marrow Transplantation Questionnaire. Acceptability will be assessed by logging treatment adherence and using a Visual Analogue Scale. Assessments will occur at two time points (1): on admission to the transplant unit, before starting the conditioning regimen and (2) on the day of discharge."},{"label":"INTERVENTION","text":"three times per week photobiomodulation therapy using a diode laser device will begin the first day of conditioning and continue through day 3 post-transplant."},{"label":"ETHICS AND DISSEMINATION","text":"The Clínica Dávila and Universidad del Desarrollo Clinical Research Ethics Committees approved this study in accordance with the Helsinki Declaration. Patients' informed consent will be required. The dissemination strategy includes publication in scientific journals as well as presentations in the media and at conferences."},{"label":"TRIAL REGISTRATION NUMBER","text":"NCT06260111."}],"keywords":["Laser Therapy","Physical Therapy Modalities","Transplant Medicine"]},{"pmid":"39422592","title_fr":"Domaines peu explorés de la PBM en oncologie buccale : analyse d'experts","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":["extrabuccal"],"nm":[],"n":null,"effect":"favorable","theme":"Nouvelles indications","l1":"Panel d'experts : résultats prometteurs pour la xérostomie, la dysgueusie, l'odynophagie, le trismus et la mucite (extrabuccale, pédiatrie), mais études petites et sécurité à surveiller.","l2":"Revue narrative où chaque thème est confié à deux spécialistes : justification, preuves, rapport bénéfice/risque, pistes de recherche.\n\nConclusion : impression globalement positive, mais il faut de grands essais multicentriques avant une généralisation.","l3":{"points":["Thèmes : mucite, xérostomie, dysgueusie, dysphagie, trismus/fibrose."],"limites":["Avis d'experts."],"pratique":"Feuille de route des indications émergentes."},"topic":"mucite-orale","title":"Underexplored Areas of Photobiomodulation in Oral Oncology: An Expert Analysis.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Gueiros LA","Gobbo M","Santos-Silva AR","et al."],"date":"2024-10-18","year":2024,"week":"2024-S42","doi":"10.1089/photob.2023.0155","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Review"],"abstract":[{"label":"","text":"Objective: This study aimed to review the current body of literature on underexplored areas of photobiomodulation (PBM) for preventing and/or treating oral adverse events. Background: Recent studies suggest that PBM may offer potential benefits in managing cancer-related toxicities other than oral mucositis. Nevertheless, further research to establish conclusive evidence is still missing. Methods: A panel of specialists conducted a narrative review to evaluate the evidence on PBM therapy for oral mucositis, xerostomia, dysgeusia, dysphagia, and trismus/fibrosis. Each topic was reviewed by two specialists who discussed treatment rationale, summarized current evidence, evaluated risk/benefit ratio, and identified future research directions. Results: The current evidence suggests promising outcomes in nonroutine uses of PBM for xerostomia, dysgeusia, odynophagia, oral mucositis (extraoral PBM and the pediatric population), and trismus/fibrosis. However, the primary studies are often small and may have biases that require further evaluation, particularly regarding treatment safety. Conclusion: Despite the overall positive impression of PBM therapy for oral adverse events of cancer treatment, robust evidence from large multicentered studies is necessary to support its widespread clinical use."}],"keywords":["dysgeusia","odynophagia","oral mucositis","photobiomodulation","trismus","xerostomia"]},{"pmid":"39457676","title_fr":"Rapport coût-efficacité de la PBM pour prévenir et traiter la mucite : revue systématique","type":"sr","level":1,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":229,"effect":"favorable","theme":"Médico-économie","key":true,"l1":"Trois essais (229 patients ORL) : la PBM coûte un peu plus à court terme mais fait économiser à moyen et long terme en évitant les mucites sévères. Certitude GRADE modérée.","l2":"Revue PRISMA 2020 d'essais randomisés PBM contre placebo chez des patients ORL. Le surcoût initial est compensé par la réduction des complications : hospitalisations, nutrition, antalgiques.\n\nArgument utile pour convaincre une direction d'établissement, même si la base reste étroite (trois essais).","l3":{"points":["Certitude GRADE : modérée.","Enregistrement CRD42024498825."],"limites":["Trois essais seulement, contextes de coûts différents."],"pratique":"Argument médico-économique pour financer un programme de PBM."},"topic":"mucite-orale","title":"Assessing the Cost-Effectiveness of Photobiomodulation for Oral Mucositis Prevention and Treatment: A Systematic Review.","journal":"Biomedicines","journal_abbr":"Biomedicines","authors":["Parra-Rojas S","Cassol Spanemberg J","Del Mar Díaz-Robayna N","et al."],"date":"2024-10-16","year":2024,"week":"2024-S42","doi":"10.3390/biomedicines12102366","pmcid":"PMC11505555","license":"cc by","oa":true,"pdf":"pdfs/39457676.pdf","cited_by":9,"pub_types":["Review"],"abstract":[{"label":"BACKGROUND","text":"We report on the cost-effectiveness of photobiomodulation (PBM) for the prevention and treatment of oral mucositis (OM) derived from the cytotoxic effects of antineoplastic therapy."},{"label":"METHODS","text":"This review followed the PRISMA 2020 guidelines. A search was conducted in PubMed, Scopus, Web of Science, Embase, and OpenGrey. Articles published before 23 July 2024, were included. Randomized controlled trials (RCTs) that included patients with head and neck cancer undergoing chemotherapy and/or radiotherapy and a placebo group compared to an intervention group (PBM) were selected. The risk of bias was evaluated using the Joanna Briggs Institute tools. The certainty of the evidence was assessed using the Grading of Recommendations Assessment, Development and Evaluation (GRADE) approach and was rated as moderate."},{"label":"RESULTS","text":"A total of 3 RCTs and 229 patients were included. PBM may represent an additional cost in the short term, but the incremental expenses derived from the cytotoxic effects of antineoplastic therapy are greater in the medium-long term. The intervention group (PBM) showed a lower incidence of severe OM compared to the control group (placebo)."},{"label":"CONCLUSIONS","text":"PBM is a cost-effective long-term treatment, effective in preventing severe OM and improving the quality of life of cancer patients. More RCTs following the same standardized protocols are needed (registration CDR42024498825)."}],"keywords":["chemotherapy","head and neck cancer","oral mucositis","photobiomodulation","radiotherapy"]},{"pmid":"39670136","title_fr":"La PBM, une nouvelle ère pour des soins de support personnalisés en cancérologie","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Courte revue narrative : la PBM est désormais recommandée en routine contre la mucite en ORL, en chimiothérapie et en greffe ; elle insiste sur l'harmonisation des doses.","l2":"Rappel des mécanismes moléculaires et des preuves cliniques, avec plaidoyer pour des schémas de dose harmonisés.\n\nSans données nouvelles.","l3":{"points":["Revue narrative."],"limites":["Vision plutôt promotionnelle."],"pratique":"—"},"topic":"mucite-orale","title":"Photobiomodulation therapy: Ushering in a new era in personalized supportive cancer care.","journal":"Journal of oral and maxillofacial pathology : JOMFP","journal_abbr":"J Oral Maxillofac Pathol","authors":["Varsani R","Khan M","Nannuri P","et al."],"date":"2024-10-15","year":2024,"week":"2024-S42","doi":"10.4103/jomfp.jomfp_193_24","pmcid":"PMC11633914","license":"cc by-nc-sa","oa":true,"pdf":"pdfs/39670136.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"The human body can utilize light for a broad range of pathophysiological responses, such as circadian rhythm, Vitamin D metabolism, and vision, among others. The therapeutic use of light has spanned many ancient health practices. Recent advances in using low-dose light therapy, termed photobiomodulation (PBM), have made tremendous progress in unravelling precise biological mechanisms and clinical dosimetry, enabling this treatment modality's clinical safety and effectiveness. The evidence for PBM has received its strongest endorsement via recent systematic reviews and meta-analyses recommending its routine use to address various acute and chronic side effects associated with cancer treatment. Carefully done studies have noted unequivocal evidence demonstrating its effectiveness in managing oral mucositis in patients undergoing radiotherapy for head and neck cancer, chemotherapy, or hematopoietic stem cell transplantation. This brief narrative review will explore the therapeutic benefits of PBM therapy, supported by recent research findings, to provide a comprehensive understanding of its potential in clinical settings. Additionally, the review will highlight our current understanding of molecular mechanisms underlying PBM and the importance of novel harmonized dosing that enables its optimal clinical implementation and utilization."}],"keywords":["Cancer care","light therapy","photobiomodulation","photonic fluence"]},{"pmid":"39439950","title_fr":"Efficacité et sécurité de la PBM en traitement oncologique : revue","type":"sr","level":5,"pop":"—","ctx":["mixte"],"aim":"—","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Sécurité oncologique","key":true,"l1":"Vingt-trois études surtout précliniques : la PBM peut tuer certaines cellules tumorales, mais la lumière rouge a aussi augmenté l'invasivité de cellules de cancer buccal. La sécurité dépend des paramètres.","l2":"Revue (PRISMA) de 14 études laser et 9 études LED. In vitro, le laser peut induire apoptose et chimiosensibilisation, mais certaines longueurs d'onde stimulent la prolifération in vitro tout en freinant la croissance des xénogreffes.\n\nLa lumière bleue freine mélanome et pancréas ; la lumière rouge LED a suscité une inquiétude sur l'invasivité du cancer buccal. Cliniquement, les deux modalités réduisent mucite, xérostomie et neuropathie.","l3":{"points":["Résultats discordants entre in vitro et in vivo.","Signal d'alerte : lumière rouge et invasivité du carcinome buccal."],"limites":["Majoritairement préclinique."],"pratique":"Garder des doses dans les fourchettes recommandées et informer les patients ; la question de la sécurité tumorale reste ouverte."},"topic":"mucite-orale","title":"Reviewing the efficiency of photobiomodulation therapy in oncological treatment.","journal":"Frontiers in oncology","journal_abbr":"Front Oncol","authors":["Luitel B","Duggisani T","Luitel A","et al."],"date":"2024-10-08","year":2024,"week":"2024-S41","doi":"10.3389/fonc.2024.1447653","pmcid":"PMC11493773","license":"cc by","oa":true,"pdf":"pdfs/39439950.pdf","cited_by":4,"pub_types":["Review"],"abstract":[{"label":"","text":"The aim of the present systematic review is to evaluate the effects of different photobiomodulation therapy (PBMT) approaches in oncological treatment practices. The review follows the PRISMA guidelines. Specifically, the review is composed of laser PBMT and LED PBMT. A total of 23 studies were included, 14 investigating laser PBMT and 9 examining LED PBMT. In vitro studies demonstrated laser PBMT's potential to induce apoptosis and cytotoxicity in various cancer cell lines while enhancing sensitivity to chemotherapeutics and natural compounds. However, some studies highlighted divergent effects between in vitro (promoted proliferation) and in vivo xenograft models (slowed tumor growth) for certain laser wavelengths. LED PBMT studies showed blue light inhibited melanoma and pancreatic cancer cell growth, potentially via ROS generation, while red light raised concerns about enhancing oral cancer invasiveness. Both modalities mitigated treatment side effects like oral mucositis, xerostomia, peripheral neuropathy, and improved quality of life. While promising, the outcomes varied based on light parameters, cancer type, and experimental setting, necessitating further optimization of PBMT protocols through well-designed studies to establish long-term safety and efficacy across clinical scenarios."}],"keywords":["low level light therapy (LLLT)","oncology","photobiomoduation","photobiomodulation therapy","radiation therapy"]},{"pmid":"39294629","title_fr":"PBM et affections buccales chimio- et radio-induites : revue parapluie","type":"umbrella","level":1,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Synthèse des preuves","key":true,"l1":"21 revues systématiques et 40 méta-analyses : 87,5 % concluent à un effet significatif, mais les revues sont de qualité faible à très faible et une seule estimation atteint le niveau « fortement suggestif ».","l2":"Revue parapluie (PROSPERO) des revues publiées jusqu'en novembre 2023. Selon AMSTAR 2, 71 % des revues sont de qualité critiquement faible et 29 % de qualité faible.\n\nSur 40 estimations méta-analytiques, 33 sont significatives, mais une seule est classée « fortement suggestive » et les autres « faibles ». Le recouvrement des études entre revues est modéré. C'est le contrepoint critique indispensable aux méta-analyses très favorables.","l3":{"points":["21 revues ; AMSTAR 2 : 15 critiquement faibles, 6 faibles.","40 estimations : 33 significatives ; 1 « fortement suggestive ».","Recouvrement : CA 12,1 %, CCA 7,75 %."],"limites":["Analyse des revues existantes, sans nouvelle méta-analyse."],"pratique":"L'effet de la PBM est constant, mais sa démonstration repose sur des revues fragiles : d'où l'intérêt de grands essais et de la future revue Cochrane."},"topic":"mucite-orale","title":"Photobiomodulation therapy on chemo- and radiotherapy induced oral conditions: an umbrella review.","journal":"BMC oral health","journal_abbr":"BMC Oral Health","authors":["Rodrigues I","Machado V","Lopes LB","et al."],"date":"2024-09-18","year":2024,"week":"2024-S38","doi":"10.1186/s12903-024-04793-7","pmcid":"PMC11411753","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/39294629.pdf","cited_by":5,"pub_types":["Systematic Review"],"abstract":[{"label":"OBJECTIVES","text":"Photobiomodulation (PBM) is a laser-based therapy used to promote tissue repair, reduce inflammation and pain, and has been extensively studied in chemo- and radiotherapy-induced oral mucositis (OM). This review examines the level of evidence of systematic reviews (SRs) that have investigated PBM in such cases of OM."},{"label":"MATERIALS AND METHODS","text":"SRs evaluating PBM for both the treatment and prevention of OM in patients undergoing chemotherapy and/or radiotherapy and published before November 30, 2023, on PubMed, Cochrane, Embase, Web of Science, LILACS, TRIP and Open Grey databases were eligible for inclusion. We assessed the level of methodological and meta-analytic procedures."},{"label":"RESULTS","text":"Of the 1201 SRs, 21 that met the inclusion criteria were included. The quality of evidence was assessed using the Assessing the Measurement Tool to Assess Systematic Reviews (AMSTAR2), and the majority was of critically low quality (n = 15, 71.4%) with only 28.5% of low quality. A total of 40 meta-analytic estimates were obtained and analyzed. Approximately 87.5% of the meta-analysis were significant (n = 33), but only one meta-analyses had a strength of \"highly suggestive\", while the rest were classified as \"weak\". When analyzing the overlap values, the covered area was 12.14% and the corrected covered area was 7.75%, indicating a moderate overlap. Only 4 SRs had a very high overlap and one had a high overlap."},{"label":"CONCLUSION","text":"The efficacy of PBM in the treatment of chemotherapy-induced OM is supported by low to critically low quality SRs and meta-analysis of low strength. This review highlights important areas that need to be addressed in future research on this topic."},{"label":"REGISTRATION","text":"CRD42023484013 (PROSPERO)."}],"keywords":["Chemotherapy","Oral mucositis","Photobiomodulation","Radiotherapy"]},{"pmid":"39223301","title_fr":"PBM associée au phytomédicament FITOPROT (Bidens pilosa et curcuma) contre la mucite radio-induite : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["laser"],"nm":[660],"n":52,"effect":"neutre","theme":"Associations","l1":"Chez 52 patients ORL, ajouter le gel FITOPROT à la PBM (660 nm, 25 mW) ne réduit pas davantage la mucite que la PBM seule, malgré un meilleur équilibre des cytokines salivaires.","l2":"Essai brésilien : FITOPROT + PBM (n = 25) contre PBM seule (n = 27), avec programme préventif de soins buccaux pour tous. PBM quotidienne à 0,25 J par point.\n\nPas de différence de grade de mucite ; la dose de radiothérapie était le facteur déterminant. Les auteurs évoquent un effet sur le nitrite et les cytokines.","l3":{"points":["Enregistrement ReBEC RBR-9vddmr.","Cytokines mesurées : IL-1, TNF-α, IL-6, IL-8, IL-12p70, IL-10."],"limites":["Effectif modeste."],"pratique":"Pas d'intérêt démontré de l'ajout de FITOPROT."},"topic":"mucite-orale","title":"Oral mucositis management with photobiomodulation, Bidens pilosa L. (Asteraceae) and Curcuma longa L. (Zingiberaceae), the FITOPROT herbal medicine, and its influence on inflammatory cytokine levels: a randomized clinical trial.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Pereira CH","Martins AFL","Morais MO","et al."],"date":"2024-09-02","year":2024,"week":"2024-S36","doi":"10.1007/s00520-024-08842-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"PURPOSE","text":"This randomized clinical trial aimed to compare the effects of a mucoadhesive formula, containing curcuminoids from Curcuma longa L. and glycerinated extract of Bidens pilosa L. (FITOPROT), associated with photobiomodulation (PBM), and of PBM exclusively, on the incidence of oral mucositis (OM)-induced by radiotherapy (RT) in the head and neck region, and the salivary expression of inflammatory cytokines, in patients with head neck cancer."},{"label":"METHODS","text":"Patients were randomly assigned into two intervention groups-FITOPROT + PBM (n = 25) or PBM (n = 27). PBM protocol comprised a wavelength of 660 nm, 25 mW, 0.25 J/point, and daily irradiation from the first until the last day of RT. FITOPROT was gargled twice a day. All patients underwent a preventive oral care program throughout the study. OM degree, salivary concentration of nitrite, and inflammatory (IL-1, TNFα, IL-6, IL-8, and IL-12p70), and anti-inflammatory (IL-10) cytokines were assessed at baseline, and at the 7th, 14th, 21st, and 30th RT sessions."},{"label":"RESULTS","text":"There were no differences in the OM degree between groups, but the RT dose significantly affected the OM. The RT significantly affected the salivary nitrite, TNFα, IL-1β, and IL-10 concentrations."},{"label":"CONCLUSION","text":"FITOPROT associated with PBM showed limited effects on preventing the incidence of severe OM compared to PBM alone. However, FITOPROT + PBM may be associated with nitrite and cytokine balance, which may contribute to the occurrence of fewer cases of severe OM."},{"label":"TRIAL REGISTRATION","text":"Brazilian Clinical Trials database (ReBEC; RBR-9vddmr), registered UTN code: U1111-1193-2066, registered in August 8th, 2017."}],"keywords":["Curcumin","FITOPROT","Head and neck cancer","Oral mucositis","Photobiomodulation"]},{"pmid":"39164917","title_fr":"Réponse : le laser haute puissance peut-il soulager la douleur de la mucite ?","type":"letter","level":0,"pop":"adulte","ctx":["mixte"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Réponse des auteurs à une lettre sur leur étude du laser haute puissance contre la mucite réfractaire. Pas de résumé.","l2":"Échange dans Oral Diseases autour de l'étude publiée en 2023–2024 (PMID 37203784). Voir aussi l'étude 2026 de la même équipe sur l'odynophagie.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Reply to: Can high-power laser photobiomodulation therapy alleviate the pain of oral mucositis?","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Zadik Y","Finfter O","Cohen R","et al."],"date":"2024-08-20","year":2024,"week":"2024-S34","doi":"10.1111/odi.15115","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"39164930","title_fr":"Le laser haute puissance peut-il soulager la douleur de la mucite réfractaire ?","type":"letter","level":0,"pop":"adulte","ctx":["mixte"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Lettre interrogeant les résultats de l'étude sur le laser haute puissance en mucite réfractaire. Pas de résumé.","l2":"Commentaire critique dans Oral Diseases. Le débat porte sur l'absence de groupe témoin et sur la sécurité des fortes puissances.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Can high-power lasers photobiomodulation therapy alleviate the pain of refractory oral mucositis?","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Wang Q","Jin J"],"date":"2024-08-20","year":2024,"week":"2024-S34","doi":"10.1111/odi.15112","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"39032055","title_fr":"Effet de différents paramètres de laser basse énergie, utilisés contre la mucite, sur des cellules de carcinome épidermoïde buccal","type":"preclinical","level":5,"pop":"—","ctx":[],"aim":"—","mode":["laser"],"nm":[660],"n":null,"effect":"—","theme":"Sécurité oncologique","l1":"In vitro, un laser 660 nm à 20 mW réduit la viabilité de cellules de cancer buccal ; à 40 et 80 mW, pas d'effet sur la viabilité. Plaide pour la dose la plus faible possible.","l2":"Cellules Cal-27 irradiées à 20, 40 et 80 mW (2 J/cm², 30 s). Viabilité par MTT, expression de Bax et Bcl-2 par RT-PCR.\n\nSeule la puissance de 20 mW réduit la viabilité ; Bax baisse à 40 et 80 mW, Bcl-2 ne change pas. Résultat rassurant à faible puissance.","l3":{"points":["Viabilité réduite à 20 mW (p = 0,001)."],"limites":["Une seule lignée cellulaire, in vitro."],"pratique":"Va dans le sens des recommandations de faible dose chez les patients avec tumeur en place."},"topic":"mucite-orale","title":"The effect of different parameters of low-level laser used in the treatment of oral mucositis, on the viability and apoptosis of oral squamous cell carcinoma cells: In vitro study.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["Shirazian S","Mohseni A","Pourshahidi S","et al."],"date":"2024-07-19","year":2024,"week":"2024-S29","doi":"10.1111/php.13997","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"","text":"Oral mucositis is a complication of chemo/radiotherapy. To assess the impact of various power levels of diode-laser on the survival and expression of apoptosis-related genes in oral cancer cells, it is crucial to consider the potential existence of malignant cells within the treatment region and the reliance of laser effectiveness on its specific characteristics. Cal-27 cells were cultivated and exposed to a 660 nm-diode-laser at power levels of 20, 40, and 80 mW, alongside non-irradiated control cells. Viability and expression of Bax and Bcl-2 mRNA were assessed with Methyl Thiazolyl Tetrazolium (MTT) and Real-time Polymerase Chain Reaction (RT-PCR), respectively. The results were analyzed using one-way ANOVA and Tukey post-hoc test (p < 0.05). A significant reduction in viability was found only in the 20 mW group compared to controls (p = 0.001). Cell survival was significantly lower in cells receiving 20 mW laser than those treated with 40 and 80 mW (p < 0.05). None of the laser groups showed significant changes in BcL-2, but Bax was significantly lower in cells receiving 40 and 80 mW (p < 0.05), compared to controls. Laser irradiation at 660 nm (2 J/cm2, 30 s) significantly reduced the viability of oral cancer cells when using 20 mW power. These specifications align with the recommendation that the lowest possible laser dose should be applied for treating cancer patients. The exact mechanism of cell death following laser therapy with these specifications requires further investigation."}],"keywords":["apoptosis","low‐level laser","oral mucositis","photobiomodulation","squamous cell carcinoma"]},{"pmid":"39032372","title_fr":"PBM dépendante de la longueur d'onde : prolifération et angiogenèse du mélanome in vitro et in vivo","type":"preclinical","level":5,"pop":"—","ctx":[],"aim":"—","mode":["laser"],"nm":[405,532,635,808],"n":null,"effect":"défavorable","theme":"Sécurité oncologique","key":true,"l1":"Chez la souris, une PBM à 808 nm a favorisé la croissance et la vascularisation d'un mélanome (B16F10), contrairement à 405, 532 et 635 nm : un signal de sécurité à prendre au sérieux.","l2":"Quatre longueurs d'onde testées. À 808 nm, prolifération et migration augmentent in vitro ; in vivo, le volume tumoral augmente avec une angiogenèse accrue (VEGF, HIF-1α) et l'activation de voies de prolifération.\n\nCe modèle (mélanome murin) est éloigné de la muqueuse buccale, mais il rappelle que l'infrarouge n'est pas neutre sur des cellules tumorales.","l3":{"points":["808 nm : augmentation du volume tumoral relatif et surexpression de VEGF et HIF-1α."],"limites":["Mélanome murin ; doses non transposables directement."],"pratique":"Éviter d'irradier une tumeur en place ; respecter les recommandations de sécurité (voir Bulletin du Cancer 2024)."},"topic":"mucite-orale","title":"Wavelength-dependent photobiomodulation (PBM) for proliferation and angiogenesis of melanoma tumor in vitro and in vivo.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Kang M","Lee Y","Lee Y","et al."],"date":"2024-07-19","year":2024,"week":"2024-S29","doi":"10.1016/j.jphotobiol.2024.112990","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation (PBM) has widely been used to effectively treat complications associated with cancer treatment, including oral mucositis, radiation dermatitis, and surgical wounds. However, the safety of PBM against cancer still needs to be validated as the effects of PBM on cancer cells and their mechanisms are unclear. The current study investigated the wavelength-dependent PBM effects by examining four different laser wavelengths (405, 532, 635, and 808 nm) on B16F10 melanoma tumor cells. In vitro tests showed that PBM with 808 nm promoted both proliferation and migration of B16F10 cells. In vivo results demonstrated that PBM with 808 nm significantly increased the relative tumor volume and promoted angiogenesis with overexpression of VEGF and HIF-1α. In addition, PBM induced the phosphorylation of factors closely related to cancer cell proliferation and tumor growth and upregulated the related gene expression. The current result showed that compared to the other wavelengths, 808 nm yielded a significant tumor-stimulating effect the malignant melanoma cancer. Further studies will investigate the in-depth molecular mechanism of PBM on tumor stimulation in order to warrant the safety of PBM for clinical cancer treatment."}],"keywords":["Malignant melanoma","Oncologic safety","Photobiomodulation","Tumorigenesis","Wavelength-dependent effect"]},{"pmid":"38992294","title_fr":"La PBM modifie-t-elle la fréquence des mucites sévères et des candidoses ? Analyse rétrospective en ORL","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","laser"],"nm":[660],"n":74,"effect":"mitigé","theme":"Facteurs de risque","l1":"Chez 74 patients ORL, la PBM n'a pas changé la fréquence globale des mucites ni des candidoses, mais a réduit les formes sévères ; les tumeurs de la cavité buccale font plus de mucites.","l2":"Dossiers 2016–2019 d'un service public brésilien. Protocole : 660 nm, 2 J par point en 3 s, 28 points (56 J), trois fois par semaine pendant 5 semaines.\n\nLes grades 1–2 dominaient, avec ou sans PBM. Les candidoses étaient plus fréquentes après la 12e séance. La localisation buccale et la limite d'irradiation des zones tumorales expliqueraient les moins bons résultats dans ces tumeurs.","l3":{"points":["Dosimétrie détaillée : 28 points, 2 J/point, 56 J/séance."],"limites":["Rétrospectif, petit effectif."],"pratique":"La PBM n'empêche pas les candidoses : continuer la surveillance fongique."},"topic":"mucite-orale","title":"Might photobiomodulation therapy interfere with the frequency of severe mucositis and oral candidiasis? A retrospective analysis in patients with head and neck carcinoma.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Nascimento RB","Neri BP","Moutinho MM","et al."],"date":"2024-07-11","year":2024,"week":"2024-S28","doi":"10.1007/s00520-024-08724-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"Considering the tumor in the oral cavity or the oropharynx and nasopharynx region might be an aggravating factor for oral mucositis (OM) manifestation, the present study aimed to evaluate whether the location of the tumor and the use of photobiomodulation therapy (PBMT) might affect the frequency of oral candidiasis (OC) during radiotherapy (RT) and/or chemotherapy (CT) treatments."},{"label":"METHODS","text":"The medial records of seventy-four patients with head and neck cancer treated in a public service from 2016 to 2019 were evaluated. All these patients were submitted to RT in an accumulated dose of 48 to 70 Gy of radiation. Data about OM and OC were collected and presented according to the application of a therapeutic protocol with laser photobiomodulation (PBMT) to control oral mucositis, or not (No-PBM), and the location of tumor (head and neck or oral cavity). In the PBMT group patients, a low-power laser device composed of InGaAlP diode (maximum output power of 86.7 mW, active tip area of 0.1256 cm2, and continuous wavelength of 660 nm), was applied to the lips (three points each), right and left jugal mucosa (three points each), the limit between hard and soft palate (three points), buccal floor/sublingual gland (one point), lateral edge of the tongue (three points on each side), and back of the tongue (six points), three times weekly, for 5 weeks. The dosimetry used in each application was 2 J for 3 s, thus totaling 56 J. The correlation between clinical characteristics such as age, tumor size (T), metastatic lymph node (N), number of RT and CT sessions, candidiasis, and OM were analyzed."},{"label":"RESULTS","text":"Mucositis grades 1 and 2 were the most common among all patients, especially before the 12th radiotherapy session, regardless of the treatment with PBM (p > 0.05). Additionally, no difference in the grade of OM and OC was significantly observed when comparing the two laser therapy groups. OC was more frequent after the 12th radiotherapy session in all groups. Nonetheless, OM and OC had a different correlation regarding to tumor location (head and neck and oral cavity) being PBMT a positive therapy to delay OM. It was observed a positive and statistically significant correlation between tumors at oral cavity and OM, regardless PBMT (R = 0.84, p < 0.05 to PBMT and R = 0.13, p < 0.05 to No-PBM). Otherwise, OC was positively correlated to local metastasis in patients with oral tumors undergoing PBMT (R = 0.84, p < 0.05)."},{"label":"CONCLUSION","text":"Patients with oral cavity tumor presented more OM, especially high grades, then patients with tumors in other regions of the head and neck, which seems to be related to the irradiation parameters of radiotherapy and/or with the limitation of conduction of PBMT in tumor areas. OM and OC were not changed by PBMT, although it helped to reduce the incidence of severe cases of OM."}],"keywords":["Chemotherapy","Head and neck cancer","Oral candidiasis","Oral mucositis","Photobiomodulation therapy","Radiotherapy"]},{"pmid":"38944404","title_fr":"Survie à long terme des patients ORL ayant reçu une PBM contre la mucite","type":"cohort","level":4,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":[],"nm":[],"n":751,"effect":"favorable","theme":"Sécurité oncologique","key":true,"l1":"Sur 751 patients ORL (2000–2016), ceux qui ont reçu une PBM ont vécu plus longtemps (médiane 1,66 contre 1,07 an). Rassurant pour la sécurité, mais très exposé aux biais.","l2":"Analyse rétrospective des dossiers d'un hôpital brésilien, PBM réalisée par un seul opérateur. Plus il y avait de séances, meilleure était la survie, notamment aux stades III–IV.\n\nCe lien s'explique très probablement par des biais : les patients qui vivent plus longtemps ont plus d'occasions de recevoir des séances (biais de temps immortel), et les plus fragiles arrêtent plus tôt. Le message utile est l'absence de signal de surmortalité.","l3":{"points":["Survie médiane : 1,07 an (sans PBM) contre 1,66 an (avec).","Stades III–IV, radiochimiothérapie, plus de 5 séances : 1,83 an."],"limites":["Biais de temps immortel et de sélection majeurs.","Rétrospectif, mono-opérateur."],"pratique":"Absence de signal de surmortalité ; ne pas en conclure que la PBM prolonge la survie."},"topic":"mucite-orale","title":"Long-term survival of cancer patients after photobiomodulation therapy for prevention and treatment of oral mucositis.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Paiva DL","Oliveira VR","Bagnato VS","et al."],"date":"2024-06-27","year":2024,"week":"2024-S26","doi":"10.1016/j.pdpdt.2024.104248","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":4,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation therapy (PBMT) has been employed for the prevention and treatment of oral mucositis in patients with head and neck cancer undergoing treatment. However, information about the survival of patients receiving PBMT is still lacking. Therefore, the aim of this study was to correlate the survival of patients who either received or did not receive PBMT, combined with cancer treatments, and to assess whether the number of PBMT sessions had a positive impact on survival."},{"label":"METHODS","text":"The records of 751 patients seen at Hospital de Caridade São Vicente de Paulo diagnosed with head and neck cancer, treated by D.L.P., the sole operator of PBMT, between 2000 and 2016, were analyzed. The median survival rates were compared by analyzing diagnostic staging, the combination of cancer treatments, and the number of PBMT sessions. Correlation analyses were performed to assess the interactions between the number of PBMT sessions and survival."},{"label":"RESULTS","text":"PBMT increased survival by 55.14 %, from 1.07 (Without PBMT) to 1.66 years (With PBMT) for the total population and more significantly in Group 41 (stages III and IV, radiation therapy/chemotherapy, with more than five PBMT sessions), the median survival value of 1.83 years, which represents a 66.36 % higher survival rate. In all the analyzed populations, the larger number of sessions was associated with better survival. In terms of survival, advanced stages III and IV almost equated with stages I and II in the absence of PBMT."},{"label":"CONCLUSIONS","text":"PBMT seems to interfere with the survival of patients with head and neck cancer, corroborating its recommendation for the treatment of mucositis, but further research is needed to investigate possible synergistic effects between PBMT and cancer treatments."}],"keywords":["Cancer treatments","Laser","Low level light","Oral medicine","Oral mucositis","Photobiomodulation therapy","Survival"]},{"pmid":"38840131","title_fr":"Interventions non médicamenteuses et nutrition, complications et qualité de vie en radiothérapie ORL : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":[],"nm":[],"n":2814,"effect":"favorable","theme":"Synthèse des preuves","metric":{"kind":"rr","outcome":"Mucite (toutes interventions non médicamenteuses)","rr":0.54,"lo":0.37,"hi":0.8,"k":27},"l1":"27 essais (2 814 patients ORL) : les interventions non médicamenteuses, dont le laser basse énergie, limitent la perte de poids et réduisent la mucite (RR 0,54).","l2":"Méta-analyse de cinq familles d'interventions : nutrition, exercice, rééducation de la déglutition, soutien psychologique et laser basse énergie. En sous-groupes, le laser contribue à limiter la perte de poids.\n\nL'estimation sur la mucite mélange plusieurs interventions et ne reflète pas la PBM seule.","l3":{"points":["Perte de poids : DM 1,66 kg ; mucite : RR 0,54 (0,37–0,80) ; dénutrition : RR 0,76."],"limites":["Estimation globale sur des interventions différentes."],"pratique":"La PBM aide aussi à préserver le statut nutritionnel."},"topic":"mucite-orale","title":"Effect of nonpharmacological interventions on nutrition status, complications and quality of life in head and neck cancer patients undergoing radiotherapy: A systematic review and meta-analysis.","journal":"International journal of nursing practice","journal_abbr":"Int J Nurs Pract","authors":["Jin X","Fan Y","Guo C","et al."],"date":"2024-06-05","year":2024,"week":"2024-S23","doi":"10.1111/ijn.13277","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review","Meta-Analysis","Research Support, N.I.H., Extramural"],"abstract":[{"label":"PURPOSE","text":"To evaluate the effect of nonpharmacological therapies on nutrition status, complications and quality of life in head and neck cancer patients and to provide a basis for clinical practice."},{"label":"METHODS","text":"This systematic review was reported in accordance with the Preferred Reporting Items for Systematic Review and Meta-analysis statement. Ten databases were systematically searched for all available articles from construction to November 2023. Two researchers independently conducted literature screening, data extraction and quality evaluation. Cochrane Review Manager 5.3 was used for meta-analysis."},{"label":"RESULTS","text":"Finally, 27 RCT studies including 2814 patients with head and neck cancer were included. Five categories of interventions were used: nutritional support, exercise, swallowing function training, psychological intervention and low-level laser therapy. Nonpharmacological interventions can improve body weight loss in patients with HNC at the end of treatment (MD: 1.66 kg; 95% CI: 0.80 to 2.51), and subgroup analysis showed that nutritional support, psychological intervention and low-level laser therapy were effective. Nonpharmacological interventions can also ameliorate decreases in BMI (MD: 0.71; 95% CI: 0.16 to 1.26) and reduce the incidence of malnutrition (RR: 0.76; 95% CI: 0.67 to 0.86), oral mucositis (RR: 0.54; 95% CI: 0.37 to 0.80) and gastrointestinal complications (RR: 0.61; 95% CI: 0.38 to 0.96) during radiotherapy; however, no significant differences were found in other complications and quality of life."},{"label":"CONCLUSION","text":"Nonpharmacological interventions can improve the nutrition status of patients with head and neck cancer and reduce the incidence of severe oral mucositis and gastrointestinal complications during radiotherapy but have no significant impact on quality of life."}],"keywords":["complications","head and neck cancer","meta‐analysis","nonpharmacological interventions","nutrition","quality of life","radiotherapy"]},{"pmid":"38831515","title_fr":"Correspondance sur l'évaluation du laser haute puissance contre la mucite de l'enfant","type":"letter","level":0,"pop":"pédiatrie","ctx":["chimio"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"—","theme":"Correspondance","l1":"Première lettre du débat sur le laser haute puissance en oncopédiatrie (Int J Paediatr Dent). Pas de résumé.","l2":"Voir aussi les réponses des 31 octobre et 3 novembre 2024.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Correspondence to a recently published research article \"Evaluating high-power laser therapy (HPLT) as a treatment for chemotherapy-induced oral mucositis in paediatric patients with oncohematological diseases\".","journal":"International journal of paediatric dentistry","journal_abbr":"Int J Paediatr Dent","authors":["Monica M","Garima J","Rahul M","et al."],"date":"2024-06-03","year":2024,"week":"2024-S23","doi":"10.1111/ipd.13222","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"38792366","title_fr":"Effet de la PBM sur les cytokines salivaires des patients ORL avec mucite : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":["laser"],"nm":[660],"n":null,"effect":"favorable","theme":"Mécanismes","l1":"Quatre études brésiliennes (660 nm) : la PBM réduit la sévérité de la mucite ; l'IL-6 est la cytokine la plus liée à la mucite.","l2":"Première revue sur la PBM et les cytokines salivaires (recherche jusqu'en février 2024). Cytokines étudiées : IL-12p70, TNF-α, IL-6, IL-8, IL-10, CXCL8, IL-1β.\n\nRésultats variables selon les traitements anticancéreux et le recueil de salive.","l3":{"points":["4 études, toutes InGaAlP 660 nm."],"limites":["Très peu d'études, toutes d'un même pays."],"pratique":"L'IL-6 salivaire pourrait servir de biomarqueur dans les essais."},"topic":"mucite-orale","title":"Effect of Photobiomodulation on Salivary Cytokines in Head and Neck Cancer Patients with Oral Mucositis: A Systematic Review.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Khalil M","Hamadah O","Saifo M","et al."],"date":"2024-05-10","year":2024,"week":"2024-S19","doi":"10.3390/jcm13102822","pmcid":"PMC11122140","license":"cc by","oa":true,"pdf":"pdfs/38792366.pdf","cited_by":8,"pub_types":["Review"],"abstract":[{"label":"","text":"Background: Oral mucositis is a common and distressing side effect of head and neck oncology treatment. Photobiomodulation therapy can be utilized to prevent and treat oral mucositis. Its impact on salivary cytokines has yet to be thoroughly investigated. This is the first systematic review aiming to evaluate the effect of photobiomodulation on salivary cytokines in patients undergoing anticancer treatment. Methods: Numerous data resources, from the Web of Science, Embase, ScienceDirect, PubMed, Cochrane Library, and Scopus were sought. Articles published up until February 2024 were included if they met the following inclusion criteria: clinical trials reporting the effect on salivary cytokines in patients undergoing anticancer therapy. The methodological quality was assessed using several appraisal tools. Results: Four studies were deemed eligible for inclusion. All the studies were conducted in Brazil and used an InGaAlP diode laser with a wavelength of 660 nm. The included studies had a relatively low risk of bias. The head and neck cancer patients' salivary cytokines that were assessed by the studies, along with photobiomodulation therapy, included IL-12p70, TNF-α, IL-6, IL-8, IL-10, CXCL8, and IL-1β. The results varied among the studies. Conclusions: Our results show that photobiomodulation demonstrated positive results for reducing the severity of OM in all the included studies. Among the examined salivary cytokines, IL-6 is the most relevant cytokine for oral mucositis development and severity. A variation in the cytokine levels between the studies was noted due to differences in the type of anticancer treatment and saliva sampling."}],"keywords":["low-level laser","oral mucositis","photobiomodulation","salivary cytokines"]},{"pmid":"39051003","title_fr":"Effet in vitro du laser basse énergie sur des colonies de Candida albicans de patients irradiés","type":"preclinical","level":5,"pop":"—","ctx":["ORL"],"aim":"—","mode":["laser"],"nm":[976],"n":11,"effect":"neutre","theme":"Préclinique","l1":"In vitro, un laser 976 nm ne réduit pas significativement Candida albicans (−7 à −11 %), contrairement à la nystatine.","l2":"Onze souches isolées de la salive de patients ORL irradiés (plus de 30 Gy). Laser 976 nm à 5 ou 10 J/cm², 50 s.\n\nLa PBM seule n'est pas antifongique.","l3":{"points":["Réduction 7,01 % et 10,94 % (NS)."],"limites":["In vitro."],"pratique":"Ne pas compter sur la PBM pour traiter une candidose."},"topic":"mucite-orale","title":"In Vitro Effect of Low-level Laser Therapy on Candida albicans Colonies Isolated From Patients Undergoing Radiotherapy for Head and Neck Cancer.","journal":"Journal of lasers in medical sciences","journal_abbr":"J Lasers Med Sci","authors":["Hasanah NT","Sufiawati I","Kusumadjati A","et al."],"date":"2024-05-08","year":2024,"week":"2024-S19","doi":"10.34172/jlms.2024.11","pmcid":"PMC11267099","license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":[],"abstract":[{"label":"","text":"Introduction: Studies on head and neck cancer (HNC) patients undergoing radiotherapy have revealed increased numbers of Candida spp., leading to oral candidiasis and oral mucositis. The effects of laser therapy on Candida spp. have been studied with varied results. This study aimed to investigate the effect of low-level laser therapy (LLLT) on C. albicans colonies isolated from HNC patients undergoing radiotherapy. Methods: This study included a treated group, wherein 11 C. albicans isolates were obtained from the saliva of HNC patients undergoing radiotherapy at a dose exceeding 30 Gy. The control groups consisted of an untreated negative control and a positive control treated with nystatin. The treatment groups were subjected to LLLT in continuous mode for 50 seconds at a wavelength of 976 nm, 0.1 W at a dose of 5 J/cm2 for Laser 1 (L1) group and 0.2 W at a dose of 10 J/cm2 for Laser 2 (L2) group. The tests were conducted using C. albicans inoculum equivalent to a 0.5-McFarland suspension on 96-well plates. All test group inoculums were then cultured on Sabouraud dextrose agar (SDA), and the colony count was assessed at 104 CFU/mL. Results: LLLT at 5 and 10 J/ cm2 reduced C. albicans colonies by 7.01% and 10.94%, respectively, but the reductions were not statistically significant (P>0.05). Nystatin eliminated all the colonies. Conclusion: LLLT shows potential for reducing C. albicans colonies in HNC patients undergoing radiotherapy. However, further studies with varied parameters and methods are necessary."}],"keywords":["Candida","Head and neck cancer","Laser","Radiotherapy"]},{"pmid":"37203784","title_fr":"PBM laser haute puissance pour soulager immédiatement la douleur de la mucite réfractaire","type":"cases","level":4,"pop":"adulte","ctx":["mixte"],"aim":"traitement","mode":["intrabuccal","haute puissance"],"nm":[],"n":25,"effect":"favorable","theme":"Douleur","l1":"Chez 25 patients avec mucite résistante aux traitements de première ligne, une PBM haute puissance soulage immédiatement la douleur dans 94 % des séances (−60 à −72 %), pendant environ 6 jours.","l2":"Étude rétrospective israélienne : laser diode InGaAsP intrabuccal (1,4 W/cm²), douleur mesurée juste avant et après la séance. 16 patients sous chimiothérapie, 9 sous radiothérapie.\n\nLa douleur disparaît complètement dans 35 % des séances. Une sensation de brûlure transitoire a été rapportée une fois. Publiée en ligne en 2023, parue dans le numéro de 2024.","l3":{"points":["79 séances ; baisse immédiate dans 94 %, plus de 50 % de baisse dans 61 %.","Baisse moyenne : 4,8 ± 2,5 (chimiothérapie) et 4,5 ± 2,8 (radiothérapie) ; effet de 6,0 ± 5,1 jours."],"limites":["Rétrospectif, sans témoin."],"pratique":"Option de recours pour les douleurs réfractaires, dans un centre formé à la haute puissance."},"topic":"mucite-orale","title":"High-power laser photobiomodulation therapy for immediate pain relief of refractory oral mucositis.","journal":"Oral diseases","journal_abbr":"Oral Dis","authors":["Finfter O","Cohen R","Hanut A","et al."],"date":"2024-05-01","year":2024,"week":"2024-S18","doi":"10.1111/odi.14618","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":7,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"PURPOSE","text":"We aimed to evaluate the efficacy of high-power (class IV) laser photobiomodulation (PBM) therapy for immediate pain relief due to oral mucositis (OM) refractory to recommended first-line therapy."},{"label":"METHODS","text":"This retrospective study included 25 cancer patients with refractory chemotherapy- or radiotherapy-induced OM (16 and 9 patients, respectively) that were treated for pain relief with an intraoral InGaAsP diode laser (power density = 1.4 W/cm2). Pain was self-assessed immediately before and after laser treatment using a 0-to-10 numeric rating scale ([NRS], \"0\" = no pain, \"10\" = intolerable pain)."},{"label":"RESULTS","text":"Patients reported an immediate decrease in pain following 94% (74 of 79) of the PBM sessions, in 61% (48 sessions) the pain reduction was over 50%, and in 35% (28 sessions) the initial pain was completely eliminated. There were no reports of increased pain post-PBM. For chemotherapy and radiotherapy-treated patients, mean reduction in pain NRS post-PBM was 4.8 ± 2.5 (p < 0.001) and 4.5 ± 2.8 (p = 0.001), indicating a post-PBM reduction of 72% and 60% of the initial pain level, respectively. The analgesic benefit of PBM remained for a mean of 6.0 ± 5.1 days. One patient reported a transient burning sensation after one PBM session."},{"label":"CONCLUSIONS","text":"High-power laser PBM may provide nonpharmacologic, patient-friendly, long-lasting, rapid pain relief for refractory OM."}],"keywords":["chemotherapy","low‐level laser","oral complications","oral ulcer","palliative therapy","radiotherapy","supportive treatment"]},{"pmid":"38688628","title_fr":"Prévention et traitement de la mucite chez l'enfant : méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"pédiatrie","ctx":["mixte"],"aim":"les deux","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Synthèse des preuves","key":true,"metric":{"kind":"rr","outcome":"Mucite grade ≥ 2 (prévention, enfant)","rr":0.99,"lo":null,"hi":null,"k":null},"l1":"Seule méta-analyse discordante de la période : chez l'enfant, le laser basse énergie ne réduit pas la mucite de grade ≥ 2 (RR 0,99), alors que le miel raccourcit l'hospitalisation.","l2":"Revue de 34 essais randomisés pédiatriques (MEDLINE et Scopus, 2000–2023) ; cinq essais méta-analysables pour le laser ou le miel.\n\nEn prévention, laser : RR 0,99 (p = 0,99) ; en curatif : RR 0,48 (p = 0,58), non significatif. Ce résultat repose sur très peu d'essais et contraste avec la méta-analyse pédiatrique de 2025 (J Dent) et avec les recommandations du Children's Oncology Group.","l3":{"points":["34 ECR repérés, 5 méta-analysés.","Laser préventif : RR 0,99 ; curatif : RR 0,48 (NS).","Miel : hospitalisation raccourcie (DM −4,33 jours)."],"limites":["Deux bases de données seulement ; très peu d'essais par comparaison ; IC non rapportés dans le résumé."],"pratique":"À connaître comme contrepoint ; l'ensemble des preuves pédiatriques reste plutôt favorable à la PBM."},"topic":"mucite-orale","title":"Prevention and Treatment of Oral Mucositis in Pediatric Patients: Systematic Review and Meta-Analysis of Randomized Controlled Trials.","journal":"In vivo (Athens, Greece)","journal_abbr":"In Vivo","authors":["Andriakopoulou CS","Yapijakis C","Koutelekos I","et al."],"date":"2024-04-30","year":2024,"week":"2024-S18","doi":"10.21873/invivo.13535","pmcid":"PMC11059879","license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Meta-Analysis","Systematic Review"],"abstract":[{"label":"BACKGROUND/AIM","text":"Oral mucositis (OM) is a common and serious side effect of cancer treatment. The incidence of chemotherapy-induced OM in pediatric patients can reach up to 91.5% and has a major impact on patients' quality of life. The aim of the study was to assess the efficacy of current interventions and agents for the management of OM in children undergoing chemo/radiotherapy or hematopoietic stem cell transplantation (HSCT)."},{"label":"MATERIALS AND METHODS","text":"A systematic search of randomized controlled trials (RCTs) was conducted in the MEDLINE and Scopus databases from January 2000 until March 2023. Thirty-four randomized studies meeting the inclusion criteria were identified and five RCTs investigating the efficacy of Low Level Laser Therapy (LLLT) intervention or the agent honey were included in the meta-analysis."},{"label":"RESULTS","text":"The meta-analysis of two RCTs indicated that topical application of honey on oral mucosa was effective in shortening the mean duration of hospital stay in children with severe OM (MD=-4.33, p=0.002). However, LLLT was not found to be effective for the prevention or treatment of OM grade ≥II (RR=0.99, p=0.99). Moreover, the therapeutic application of LLLT did not show significant benefit for lower risk of OM grade ≥II (RR=0.48, p=0.58)."},{"label":"CONCLUSION","text":"Various interventions and agents were examined in the present study for the management of OM. Honey could be a promising candidate for the treatment of OM in pediatric patients. Further high-quality RCTs are required to enhance our findings."}],"keywords":["Oral mucositis","cancer","children","meta-analysis","review"]},{"pmid":"38672630","title_fr":"Prise en charge de la mucite chez l'enfant sous traitement anticancéreux : revue systématique","type":"sr","level":3,"pop":"pédiatrie","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"39 articles pédiatriques : laser basse énergie, palifermine, miel et zinc réduisent incidence, durée, sévérité et douleur de la mucite, mais les preuves restent insuffisantes pour un protocole précis.","l2":"Revue de 2 655 articles avec comparaison des approches : cryothérapie, laser, composés naturels.\n\nConclusion prudente : plusieurs options efficaces, sans protocole clinique consensuel.","l3":{"points":["39 articles inclus."],"limites":["Pas de méta-analyse."],"pratique":"La PBM fait partie des options validées chez l'enfant."},"topic":"mucite-orale","title":"Oral Mucositis Management in Children under Cancer Treatment: A Systematic Review.","journal":"Cancers","journal_abbr":"Cancers (Basel)","authors":["Braguês R","Marvão MF","Correia P","et al."],"date":"2024-04-18","year":2024,"week":"2024-S16","doi":"10.3390/cancers16081548","pmcid":"PMC11048343","license":"cc by","oa":true,"pdf":"pdfs/38672630.pdf","cited_by":10,"pub_types":["Review"],"abstract":[{"label":"","text":"Children undergoing antineoplastic treatment often present severe side effects due to the dosage and duration of treatments, with oral mucositis emerging as one of the most prevalent and painful inflammatory conditions. There is a growing body of evidence on therapeutic interventions such as cryotherapy, low-level laser therapy, and natural compounds for this condition. The aim of this systematic review was to identify and compare therapies for the management of cancer treatment-induced oral mucositis in pediatric patients. From 2655 articles obtained in initial searches, 39 articles were considered in this systematic review, after applying inclusion/exclusion criteria. Low-level laser therapy, palifermin, honey, and zinc demonstrated reductions in oral mucositis incidence, duration, severity, and pain reported by the patient. Although there are several therapies in place for the prevention and treatment of oral mucositis in children, evidence of their efficacy is still inconclusive to establish accurate clinical protocols."}],"keywords":["calcium phosphate","honey","low-level laser therapy","oral mucositis","palifermin","pediatric cancer","prevention","therapeutics","zinc"]},{"pmid":"38619258","title_fr":"Soulagement immédiat de la douleur dans la mucite et les ulcérations buccales par PBM : le concept de traitement préemptif","type":"review","level":5,"pop":"mixte","ctx":["mixte"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"favorable","theme":"Douleur","l1":"Revue cartographique : certains protocoles de PBM soulagent la douleur immédiatement. Les auteurs proposent une PBM « préemptive », débutée dès les premiers signes.","l2":"Revue PubMed : la plupart des essais rapportent un soulagement retardé, mais certains protocoles donnent un effet immédiat, proche de la disparition de la douleur.\n\nLe concept s'étend aux aphtes et à la GVH chronique. Même école que les travaux sur la PBM haute puissance (2023, 2026).","l3":{"points":["Concept : PBM préemptive, précoce et répétée pendant tout le traitement."],"limites":["Revue non systématique, une seule base."],"pratique":"Penser à l'effet antalgique immédiat comme critère à part entière."},"topic":"mucite-orale","title":"Immediate pain alleviation in oral mucositis and other oral ulcerative diseases through photobiomodulation therapy: the preemptive treatment concept.","journal":"Quintessence international (Berlin, Germany : 1985)","journal_abbr":"Quintessence Int","authors":["Elad S","Keegan R","Fregnani ER","et al."],"date":"2024-04-15","year":2024,"week":"2024-S16","doi":"10.3290/j.qi.b5213529","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Review"],"abstract":[{"label":"OBJECTIVE","text":"Photobiomodulation therapy is recommended by multiple international societies for managing oral mucositis. These recommendations are based on extensive evidence. However, the search for an optimal photobiomodulation protocol continues. This mapping review focuses on a novel aspect of photobiomodulation therapy which is the immediate effect on pain levels associated with oral ulcerative conditions."},{"label":"DATA SOURCES","text":"This literature review systematically compiles and evaluates the evidence about oral mucositis, alongside other oral ulcerative conditions, as the protocols that achieved pain relief for these oral conditions may have potential applicability to oral mucositis management. The scientific database used was PubMed."},{"label":"CONCLUSION","text":"Whereas most of the randomized controlled trials about photobiomodulation therapy for oral mucositis and other ulcerative oral diseases reported delayed pain relief, certain photobiomodulation therapy protocols reported immediate pain relief. The results of this review highlight the concept of preemptive photobiomodulation therapy, in which photobiomodulation therapy is delivered early in the development of oral mucositis throughout the oncotherapy and may achieve immediate pain relief consistently in most of the patients and close to a negligible pain level. Photobiomodulation therapy, as a powerful nonpharmacologic tool for immediate pain relief, has a great beneficial value in patients suffering from oral mucositis and other painful oral ulcerative diseases such as recurrent aphthous stomatitis and chronic graft-versus-host disease."}],"keywords":["aphthous stomatitis","cancer","graft vs host disease","laser","oral mucositis","pain relief","photobiomodulation"]},{"pmid":"38615257","title_fr":"PBM quotidienne versus un jour sur trois pour prévenir la mucite pendant la radiochimiothérapie du cancer buccal : essai en triple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["ORL"],"aim":"prévention","mode":["intrabuccal","laser"],"nm":[660],"n":16,"effect":"favorable","theme":"Dosimétrie & fréquence","key":true,"l1":"Chez 16 patients atteints de cancer buccal, espacer la PBM (un jour sur trois au lieu de chaque jour) augmente les mucites de grade 2–3, la douleur et la perte salivaire : la PBM quotidienne est supérieure.","l2":"Essai brésilien en triple aveugle : PBM quotidienne contre PBM tous les trois jours intercalée de simulations. Laser 660 nm, 0,1 W, 1 J par point, 9 points par zone, du début à la fin de la radiochimiothérapie.\n\nLe groupe espacé a plus de mucites de grade 2 et 3, plus de douleur et une baisse du débit salivaire plus marquée. Résultat à opposer à la pratique fréquente de trois séances par semaine.","l3":{"points":["Zones : lèvres, joues, bords et corps de langue, plancher.","Mesures quotidiennes : OMS, douleur, EVA ; poids, débit salivaire, OHIP-14, CAOD."],"limites":["Très petit effectif (8 par groupe)."],"pratique":"Quand c'est possible, préférer une PBM quotidienne pendant la radiochimiothérapie du cancer buccal."},"topic":"mucite-orale","title":"Comparison of a daily and alternate-day photobiomodulation protocol in the prevention of oral mucositis in patients undergoing radiochemotherapy for oral cancer: a triple-blind, controlled clinical trial.","journal":"Medicina oral, patologia oral y cirugia bucal","journal_abbr":"Med Oral Patol Oral Cir Bucal","authors":["Oliveira FM","Borges MM","Malta CE","et al."],"date":"2024-04-14","year":2024,"week":"2024-S15","doi":"10.4317/medoral.26436","pmcid":"PMC11175575","license":"cc by","oa":true,"pdf":"pdfs/38615257.pdf","cited_by":7,"pub_types":["Comparative Study","Randomized Controlled Trial"],"abstract":[{"label":"BACKGROUND","text":"Preventive Photobiomodulation Therapy (PBMT) significantly reduces oral mucositis (OM) severity in patients undergoing Radiochemotherapy (RCT) for the treatment of oral cancer, but daily applications generate cost, overload the dental team, and reduce the number of patients assisted.To evaluate the effectiveness of two PBMT protocols in preventing OM in patients undergoing RCT for oral cancer."},{"label":"MATERIAL AND METHODS","text":"16 patients diagnosed with oral cancer undergoing RCT were included, equally divided into two groups: a group treated daily with PBMT, and another group also submitted to daily treatment, however, performing the application of PBMT every three days, interspersed with a simulation of PBMT (placebo). A red laser was used (~660 nm), 0.1W power, 1J of energy applied per point, 9 points per area (labial mucosa, buccal mucosa, lateral borders of the tongue, body of the tongue, and floor of the mouth) from the beginning of RCT until the end of the oncological treatment. Daily assessments were performed regarding OM scores, the World Health Organization (WHO) pain scale, and the visual analog scale (VAS). Weight, salivary flow (SGAPP), OHIP-14, and DMFT were evaluated on the initial and final days of RT. OM incidence and clinical data were compared by Pearson's chi-square test or Fisher's exact test. Pain and other scale scores were compared using the Mann-Whitney and Friedman/Dunn tests (SPSS v20.0 p<0.05)."},{"label":"RESULTS","text":"In the group with PBMT on alternate days, there was an increase in the frequency of grade 2 and grade 3 oral mucositis and an increased risk of grade 2 oral mucositis, in addition to higher mean pain scores and greater reduction in salivary flow."},{"label":"CONCLUSIONS","text":"The daily PBMT protocol proved more effective in controlling the frequency and severity of OM, pain, and salivary flow."}],"keywords":[]},{"pmid":"38556719","title_fr":"Création d'une équipe de photothérapie pour administrer la PBM en greffe pédiatrique : protocole standardisé","type":"cohort","level":4,"pop":"pédiatrie","ctx":["CSH"],"aim":"les deux","mode":[],"nm":[],"n":62,"effect":"favorable","theme":"Implantation","key":true,"l1":"Dans un centre américain de greffe pédiatrique, une infirmière dédiée à la PBM a rendu le programme faisable : mucite plus courte (9 contre 11,3 jours), moins de sorties sous nutrition parentérale (18 % contre 61 %) et coûts réduits.","l2":"PBM du premier jour du conditionnement à J+20 chez 62 enfants (octobre 2022–septembre 2023), comparés aux patients de 2021. Le brossage des dents augmentait (90 % contre 75 %).\n\nCoûts de support liés à la mucite (nutrition parentérale, PCA) : médiane 31 230 $ contre 37 371 $. L'étude insiste sur le rôle d'une infirmière dédiée.","l3":{"points":["Sortie sous nutrition parentérale : 18 % contre 61 % (p < 0,001).","Coûts médians : 31 229,87 $ contre 37 370,66 $ (p = 0,02)."],"limites":["Comparaison avant-après."],"pratique":"Modèle d'organisation : infirmière dédiée et protocole écrit."},"topic":"mucite-orale","title":"Implementation of a light therapy team to administer photobiomodulation therapy: A standardized protocol to prevent and treat oral mucositis in the pediatric hematopoietic stem cell transplant population.","journal":"Pediatric blood & cancer","journal_abbr":"Pediatr Blood Cancer","authors":["Magee K","Robins J","Staton S","et al."],"date":"2024-03-31","year":2024,"week":"2024-S13","doi":"10.1002/pbc.30966","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"BACKGROUND","text":"Oral mucositis (OM) is a painful and common complication of hematopoietic stem cell transplant (HSCT). The Children's Oncology Group recently published guidelines recommending photobiomodulation (PBM) for preventing and treating OM in pediatric HSCT patients. However, this is a rarely used intervention in pediatric hospitals."},{"label":"PROCEDURE","text":"Patients undergoing allogeneic HSCT, or autologous HSCT for a neuroblastoma diagnosis, had PBM administered from the first day of conditioning to transplant Day +20. We successfully developed a standardized treatment protocol and workflow to ensure consistent and uniform delivery of PBM. In addition, clinical patient data were compared before and after PBM implementation."},{"label":"RESULTS","text":"The administration of PBM at our center was feasible, but required dedicated staff. A registered nurse (RN) was determined to be the best fit to deliver PBM. Sixty-two patients received PBM from October 2022 to September 2023; patients from 2021 before PBM implementation were used for comparison. Patients receiving PBM were more likely (p = .03) to engage in teeth brushing (56/62 = 90%) compared to baseline (61/81 = 75%). Mean days of OM decreased from 11.3 to 9 days; patients who received PBM were less likely (p < .001) to be discharged on total parental nutrition (TPN) (11/62 = 18%) compared to baseline (50/82 = 61%). OM-related supportive care costs (TPN and patient-controlled anesthesia [PCA]) were lower (p = .02) for those who received PBM (median cost = $31,229.87 vs. $37,370.66)."},{"label":"CONCLUSION","text":"PBM, as the standard of care in the pediatric HSCT population, is safe, feasible, and well-tolerated. At our center, a dedicated RN was critical to providing standardized treatment and ensuring sustainability."}],"keywords":["oral mucositis","pediatric HSCT","photobiomodulation"]},{"pmid":"38438625","title_fr":"PBM préventive versus curative dans le myélome multiple en autogreffe","type":"cohort","level":4,"pop":"adulte","ctx":["CSH"],"aim":"les deux","mode":[],"nm":[],"n":24,"effect":"favorable","theme":"Moment d'application","l1":"Chez 24 patients atteints de myélome en autogreffe, la PBM débutée dès le conditionnement réduit beaucoup plus la sévérité et la douleur de la mucite que la PBM débutée à l'apparition des lésions.","l2":"Série rétrospective italienne avec le même conditionnement et le même protocole de greffe. Préventif : du premier jour du conditionnement à J+2. Curatif : quatre jours dès l'apparition de la mucite.\n\nTous les patients ont eu une mucite, mais la sévérité et la douleur étaient bien moindres en préventif (p < 0,0001), avec moins de gêne pour avaler, mâcher et parler. Aucun effet indésirable.","l3":{"points":["Sévérité et douleur : p < 0,0001 en faveur du préventif."],"limites":["Rétrospectif, petit effectif."],"pratique":"En autogreffe pour myélome, débuter la PBM dès le premier jour du conditionnement."},"topic":"mucite-orale","title":"Preventive versus curative photobiomodulation for oral mucositis in patients with multiple myeloma undergoing hematopoietic stem cell transplantation: which approach is more effective?","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Rupel K","Cornacchia A","Poiani M","et al."],"date":"2024-03-04","year":2024,"week":"2024-S10","doi":"10.1007/s00520-024-08414-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"There is increasing evidence that photobiomodulation (PBM) therapy is both an effective and safe approach in hematopoietic stem cell transplantation (HSCT) for both prevention and management of oral mucositis (OM), but its use in clinical practice is still limited and the timing of application is under discussion. The aim of this retrospective study was to evaluate possible differences between patients treated either with preventive or curative PBM therapy."},{"label":"METHODS","text":"The retrospective case series included 24 patients suffering from multiple myeloma who underwent the same conditioning and transplantation protocol. Patients were treated either with preventive PBM starting from the first day of conditioning up to two days post-HSCT or with curative PBM (starting at OM onset for four consecutive days). OM score, pain, and functional parameters were recorded."},{"label":"RESULTS","text":"All patients developed OM. Preventive PBM was significantly more effective in reducing OM severity (p < 0.0001) and pain (p < 0.0001) post-HSCT than curative PBM. Furthermore, we found a lower number of patients reporting discomfort in all subjective parameters (pain during swallowing, chewing, and speaking) in the preventive PBM group. No adverse events related to PBM therapy were recorded in both groups."},{"label":"CONCLUSION","text":"The timing for PBM therapy in patients undergoing HSCT is crucial: when started on the first day of conditioning, it significantly reduces both pain and OM severity, providing an important benefit also in subjective oral functions such as speaking, swallowing, and chewing, thus increasing the overall adherence to the oncological therapies."}],"keywords":["Hematopoietic stem cell transplantation","Laser therapy","Multiple myeloma","Oral mucositis","Photobiomodulation","Supportive care in hematological cancer"]},{"pmid":"37858427","title_fr":"La photobiomodulation dans la prévention et la prise en charge des effets secondaires des traitements anticancéreux : bases, résultats et perspectives","type":"sr","level":3,"pop":"mixte","ctx":["mixte"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Sécurité oncologique","key":true,"l1":"Synthèse française (Bulletin du Cancer) : la PBM est efficace en essais randomisés contre la mucite aiguë, la radiodermite et le lymphœdème ; elle doit rester dans les doses recommandées, avec consentement éclairé près d'une tumeur.","l2":"Revue systématique des études prospectives (Embase, Medline, Cochrane, EBSCO, Scopus, LILACS) sur de nombreuses toxicités. Le niveau de preuve est hétérogène, globalement modéré ; la principale faiblesse est l'imprécision des protocoles.\n\nPour les autres effets (dysgueusie, ostéonécrose, neuropathie, alopécie, syndrome main-pied, GVH), les études sont trop limitées. Les auteurs ont pu définir des paramètres et doses de pratique sûre, et recommandent la prudence et l'information du patient en zone tumorale.","l3":{"points":["Efficacité en ECR : mucite aiguë, épithélite, lymphœdème du membre supérieur.","Recommandation : rester dans les paramètres validés ; informer et recueillir le consentement en zone tumorale."],"limites":["Études rétrospectives exclues ; analyse en partie qualitative."],"pratique":"Référence francophone pour rédiger le consentement et le protocole de sécurité."},"topic":"mucite-orale","title":"[Photobiomodulation in the prevention and the management of side effects of cancer treatments: Bases, results and perspectives].","journal":"Bulletin du cancer","journal_abbr":"Bull Cancer","authors":["Lairedj K","Klausner G","Robijns J","et al."],"date":"2024-03-01","year":2024,"week":"2024-S09","doi":"10.1016/j.bulcan.2023.08.011","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["English Abstract","Review"],"abstract":[{"label":"BACKGROUND","text":"Assess the current and potential indications of photobiomodulation (PBM) therapy and their level of evidence in the prevention or treatment of side effects related to oncology treatments (radiation therapy, and to a minimal extent favored and hematopoietic stem cell transplants). And report on the recommended modalities (parameters and doses) of PBM therapy."},{"label":"MATERIALS AND METHODS","text":"The Embase, Medline/PubMed, Cochrane, EBSCO, Scopus, and LILACS databases were systematically reviewed to include and analyze publications of clinical studies that evaluated PBM in the prevention or management side effects related to cancer treatments. The keywords used were \"photobiomodulation\"; \"low level laser therapy\"; \"acute oral mucositis\"; \"acute dysphagia\"; \"acute radiation dermatitis\"; \"lymphedema\"; \"xerostomia\"; \"dysgeusia\"; \"hyposalivation\"; \"lockjaw\"; \"bone necrosis\"; \"osteoradionecrosis\"; \"radiation induced fibrosis\"; \"voice and speech alterations\"; \"palmar-plantar erythrodysesthesia\"; \"graft versus host disease\"; \"peripheral neuropathy\"; \"chemotherapy induced alopecia\". Prospective studies were included, while retrospective cohorts and non-original articles were excluded from the analysis."},{"label":"RESULTS","text":"PBM in the red or infrared spectrum has been shown to be effective in randomized controlled trials in the prevention and management of certain complications related to radiotherapy, in particular acute mucositis, epitheliitis and upper limb lymphedema. The level of evidence associated with PBM was heterogeneous, but overall remained moderate. The main limitations were the diversity and the lack of precision of the treatment protocols which could compromise the efficiency and the reproducibility of the results of the PBM. For other effects related to chemo/radiation therapy (dysgeusia, osteonecrosis, peripheral neuropathy, alopecia, palmar-plantar erythrodysaesthesia) and haematopoietic stem cell transplantation (graft versus host disease), treatment with PBM suffers from a lack of studies or limited studies at the origin of a weakened level of proof. However, based on these results, it was possible to establish safe practice parameters and doses of PBM."},{"label":"CONCLUSION","text":"Published data suggest that PBM could therefore be considered as supportive care in its own right for patients treated with radiation, chemotherapy, immunotherapy, hormone therapy or targeted therapies, whether in clinical practice or clinical trials. therapies. However, until solid data have been published on its long-term safety, the use of PBM should be considered with caution and within the recommended parameters and doses, particularly when practiced in areas of known or possible tumours. In this case, the patient should be informed of the theoretical benefits and risks of PBM in order to obtain informed consent before treatment."}],"keywords":["Chemotherapy","Effets secondaires des anticancéreux","Low-level light therapy","Mucite","Neoplasms","Neuropathies périphériques post-chimiothérapie","Photobiomodulation","Photobiomodulation (PBM)","Radiation therapy","Radiodermite"]},{"pmid":"38377968","title_fr":"Utilisation de la PBM pour prévenir et traiter la mucite en greffe pédiatrique","type":"cohort","level":4,"pop":"pédiatrie","ctx":["CSH"],"aim":"les deux","mode":[],"nm":[],"n":40,"effect":"favorable","theme":"Vie réelle","l1":"Chez 40 enfants allogreffés, une PBM quotidienne sur six sites est faisable (93 %) ; 20 % ont eu une mucite de grade 3 contre 51 % attendus, avec une hospitalisation plus courte.","l2":"Étude américaine de faisabilité : traitement quotidien jusqu'à J+20 ou la prise de greffe. 979 des 1 035 rencontres ont permis de traiter au moins quatre sites.\n\nPar rapport à des témoins appariés : moins de jours d'hospitalisation (p = 0,009) et une mucite moins sévère (p = 0,03). Le Children's Oncology Group recommande désormais la PBM.","l3":{"points":["Faisabilité 93,3 % ; mucite de grade 3 : 20 % (IC95 % 9,1–35,6)."],"limites":["Témoins appariés non randomisés."],"pratique":"Faisable en routine en greffe pédiatrique."},"topic":"mucite-orale","title":"Utilization of Photobiomodulation for the Prevention and Treatment of Oral Mucositis.","journal":"Journal of pediatric hematology/oncology nursing","journal_abbr":"J Pediatr Hematol Oncol Nurs","authors":["Pritchard M","Ogg SW","Bosi J","et al."],"date":"2024-02-20","year":2024,"week":"2024-S08","doi":"10.1177/27527530231214525","pmcid":"PMC13686199","license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Research Support, Non-U.S. Gov't","Research Support, N.I.H., Extramural"],"abstract":[{"label":"","text":"Background: Oral mucositis is a significant and common toxicity experienced by patients who receive high-dose chemotherapy as a preparatory regimen for a hematopoietic cell transplant (HCT). Photobiomodulation (PBM) has been found to be feasible with significant efficacy in preventing the progression of oral mucositis in adult patients undergoing HCT. The purpose of this study was to determine the feasibility and efficacy of PBM in pediatric oncology patients undergoing HCT. Method: Forty children and adolescents admitted to the transplant unit for an allogeneic HCT for acute lymphoblastic leukemia or acute myeloid leukemia were treated daily at six sites until day + 20 or engraftment. Results: There were 1,035 patient encounters, with successful treatment of four or more sites during 979 patient encounters for a feasibility 93.3% CI [0.926, 0.039]. We had estimated a meaningful effect size of 20% for PBM and estimated 51% of patients treated with PBM would have at least one day or more of Grade 3 mucositis. The rate of patients who received PBM and developed Grade 3 mucositis was 20% CI [0.091, 0.356]. Patients treated with PBM had fewer days of hospitalization (p = .009) and less severe mucositis in comparison to the matched control group (p = .03). Conclusion: PBM is feasible and effective in preventing and treating oral mucositis and is now supported by the Children's Oncology Group for prevention and treatment of oral mucositis in patients undergoing an allogeneic HCT or receiving head/neck radiation."}],"keywords":["light therapy","mucositis","pediatric oncology","photobiomodulation"]},{"pmid":"38265122","title_fr":"Efficacité de la PBM dans la mucite des patients ORL : revue systématique et méta-analyse d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["ORL"],"aim":"les deux","mode":["laser"],"nm":[632.8,660],"n":869,"effect":"favorable","theme":"Synthèse des preuves","key":true,"metric":{"kind":"rr","outcome":"Mucite sévère en fin de traitement","rr":0.45,"lo":0.24,"hi":0.85,"k":14},"l1":"Quatorze essais (869 patients ORL) : la PBM réduit la mucite sévère (RR 0,45 en fin de traitement) et la douleur ; les meilleurs résultats sont obtenus à faible puissance (10–25 mW).","l2":"Méta-analyse dans Head & Neck (PubMed, Embase, Cochrane, LILACS, Web of Science ; 2000–octobre 2023). L'incidence de mucite baisse dès la 2e semaine (RR 0,49) et jusqu'à la 7e (RR 0,77) ; la mucite sévère baisse dès la 3e semaine (RR 0,51) et jusqu'à la fin (RR 0,45 ; IC95 % 0,24–0,85).\n\nLa douleur diminue d'environ 1 point (DMP −1,09). Les lasers He-Ne ou InGaAlP de 10 à 25 mW donnent les meilleurs résultats. L'hétérogénéité est forte sur certaines estimations (I² jusqu'à 89 %).","l3":{"points":["14 ECR, 869 patients.","Mucite sévère fin de traitement : RR 0,45 (0,24–0,85), I² = 80 %.","Douleur : DMP −1,09 (−1,38 à −0,88), I² = 13 %.","Paramètres favorables : He-Ne (632,8 nm) ou InGaAlP (660 nm), 10–25 mW."],"limites":["Forte hétérogénéité pour plusieurs critères."],"pratique":"Référence de début 2024 en ORL ; cohérente avec les méta-analyses de 2026."},"topic":"mucite-orale","title":"Efficacy of photobiomodulation therapy in the management of oral mucositis in patients with head and neck cancer: A systematic review and meta-analysis of randomized controlled trials.","journal":"Head & neck","journal_abbr":"Head Neck","authors":["Shen B","Zhou Y","Wu D","et al."],"date":"2024-01-24","year":2024,"week":"2024-S04","doi":"10.1002/hed.27655","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":13,"pub_types":["Meta-Analysis","Systematic Review"],"abstract":[{"label":"","text":"Numerous studies have examined the effectiveness of photobiomodulation therapy (PBMT) in reducing chemoradiotherapy (CRT)-induced oral mucositis (OM) in patients with head and neck cancer (HNC). Despite this, there is an urgent need to update the meta-analyses on this topic. This meta-analysis aims to explore the impact of PBMT on CRT-induced OM in these patients. We conducted a systematic search in PubMed, Embase, Cochrane, LILACS, and Web of Science from January 2000 to October 2023. This search focused on randomized controlled trials (RCTs) that assessed the effects of PBMT on CRT-induced OM. The study included a total of 14 RCTs encompassing 869 patients with HNC. The incidence of OM in the PBMT group was significantly lower from the second week onwards compared to the control group (RR = 0.49, CI = 0.25-0.97, I2  = 71%, p = 0.04), and this was present until the seventh week (RR = 0.77, CI = 0.61-0.99, I2  = 89%, p = 0.04). Furthermore, the occurrence of severe mucositis in the PBMT group decreased from the third week (RR = 0.51, CI = 0.29-0.90, I2  = 12%, p = 0.02) until the conclusion of the intervention (RR = 0.45, CI = 0.24-0.85, I2  = 80%, p = 0.01). Additionally, PBMT showed beneficial effects in alleviating OM-related pain (WMD = -1.09, 95% CI = -1.38 to -0.880, I2  = 13%, p < 0.00001). The use of He-Ne or InGaAlP lasers with a power range of 10-25 mW demonstrated the most favorable outcomes in preventing and treating OM. PBMT has shown considerable efficacy in reducing the incidence, severity, and pain associated with OM in patients with HNC. Future studies are encouraged to further investigate the most effective parameters for PBMT in the management of OM."}],"keywords":["concurrent radiotherapy","head and neck cancer","meta-analysis","oral mucositis","photobiomodulation"]},{"pmid":"38183418","title_fr":"Dispositif de PBM auto-administré : la prochaine génération de prévention et de traitement de la mucite","type":"letter","level":0,"pop":"—","ctx":["mixte"],"aim":"prévention","mode":["domicile"],"nm":[],"n":null,"effect":"—","theme":"PBM à domicile","l1":"Lettre défendant les dispositifs de PBM auto-administrés. Pas de résumé ; le sujet a été repris en 2025 par une étude pilote à domicile.","l2":"Courrier dans Supportive Care in Cancer. Voir la fiche « Du cabinet au canapé » (novembre 2025) pour les premières données de faisabilité.","l3":{"points":["Correspondance."],"limites":["Contenu non indexé."],"pratique":"—"},"topic":"mucite-orale","title":"Self-applied photobiomodulation device: the next generation in oral mucositis prevention and treatment.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Zadik Y","Gavish L"],"date":"2024-01-06","year":2024,"week":"2024-S01","doi":"10.1007/s00520-023-08292-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Letter"],"abstract":[],"keywords":[]},{"pmid":"42877564","title_fr":"PBM dans la paralysie faciale de Bell : deux cas","type":"cases","level":4,"pop":"mixte","ctx":["autres"],"aim":"traitement","mode":["laser"],"nm":[808],"n":2,"effect":"favorable","theme":"Nerfs crâniens","l1":"Deux cas de paralysie faciale a frigore traités par laser 808 nm : récupération complète du cas aigu en 14 séances, amélioration partielle du cas chronique de 4 ans.","l2":"Laser infrarouge à 3 J par point, protocoles progressifs individualisés. Le cas aigu, une adolescente, recevait aussi médicaments, kinésithérapie faciale et auriculothérapie : on ne peut pas isoler l'effet de la PBM, d'autant que la paralysie de Bell guérit souvent spontanément.\n\nLe cas chronique est plus parlant : douleur soulagée dès la première séance et mobilité améliorée sur 15 séances.","l3":{"points":["Suivi : 18 mois et 3 ans."],"limites":["Deux cas, traitements associés, guérison spontanée fréquente."],"pratique":"Pas de recommandation possible."},"topic":"neuropathie-peripherique","title":"Photobiomodulation as an Alternative Approach for Bell's Palsy: Case Reports.","journal":"Case reports in dentistry","journal_abbr":"Case Rep Dent","authors":["Castro OAZ","Aveiga-Zambrano MC","Paredes-Muñoz GH","et al."],"date":"2026-10-14","year":2026,"week":"2026-S42","doi":"10.1155/crid/2340155","pmcid":"PMC13662821","license":"cc by","oa":false,"pdf":"pdfs/42877564.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Bell's palsy (BP), also known as idiopathic facial paralysis, is an idiopathic peripheral neuropathy that unilaterally affects the facial musculature. Its management includes various therapeutic modalities, among which photobiomodulation (PBM) has shown positive effects on neuromuscular regeneration."},{"label":"OBJECTIVE","text":"To describe the clinical outcomes of PBM in two patients with BP, one chronic and one acute."},{"label":"METHODS","text":"The first patient, a 58-year-old woman, presented with left-sided BP of 4 years' duration and had undergone multiple unsuccessful treatments. The second patient, a 15-year-old adolescent, was diagnosed 2 weeks prior to the initiation of PBM and underwent pharmacological therapy for 2 weeks, facial physiotherapy five times per week for 5 months, and auriculotherapy once weekly for 3 months. Both patients received infrared laser therapy (808 nm, 3 J/point) following individualized, progressive protocols."},{"label":"RESULTS","text":"In the chronic case, there was a significant reduction in orofacial pain from the first session and gradual improvement in facial mobility up to the fifteenth session, with follow-up extending to 18 months. Although complete facial symmetry was not restored, the patient reported enhanced self-confidence and quality of life. In the acute case, complete pain relief was achieved within a few sessions, and full functional recovery was observed after 14 sessions, with restoration of facial symmetry and emotional well-being. Clinical outcomes remained stable at the three-year follow-up."},{"label":"CONCLUSIONS","text":"PBM proved to be an effective tool for managing both chronic and acute BP, promoting analgesia, motor recovery, and general well-being. Its integration into multidisciplinary treatment protocols may optimize therapeutic outcomes."}],"keywords":["Bell’s palsy","case report","facial paralysis","low-level light therapy"]},{"pmid":"42873358","title_fr":"Effets de la PBM rouge et infrarouge sur la douleur neuropathique, le muscle et la respiration mitochondriale (rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[660,904],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat avec constriction du nerf sciatique, la PBM à 660 et 904 nm réduit l'hyperalgésie et l'allodynie, sans restaurer la respiration mitochondriale du muscle.","l2":"Comparaison de deux longueurs d'onde sur le comportement douloureux, l'histologie, la thermographie et les protéines mitochondriales. La PBM augmente l'OPA1 et module la chaîne respiratoire différemment selon la longueur d'onde.\n\nL'analgésie ne passerait donc pas par une restauration bioénergétique du muscle.","l3":{"points":["Modèle : constriction chronique du sciatique (CCI)."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Wavelength dependent effects of red and infrared photobiomodulation on neuropathic pain, skeletal muscle integrity, and mitochondrial respiration.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Santos MER","Lopez MAH","Araujo LC","et al."],"date":"2026-10-14","year":2026,"week":"2026-S42","doi":"10.1007/s10103-026-05060-7","pmcid":"PMC13668946","license":"cc by","oa":false,"pdf":"pdfs/42873358.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Neuropathic pain is a chronic and difficult to treat condition affecting up to 10% of the population, significantly impairing quality of life and representing a public health concern. Photobiomodulation (PBMT) has emerged as a promising therapeutic approach, as photons can reach mitochondria and promote beneficial effects, including increased ATP production, reduced oxidative stress and inflammation, and improved mitochondrial metabolism and regeneration. However, gaps remain regarding its effects on mitochondrial dynamics in neuropathic pain. This study investigated the impact of PBMT at two wavelengths (660 nm, red and 904 nm, infrared) on nociceptive behavior (tactile allodynia, mechanical and thermal hyperalgesia), histological alterations, mitochondrial respiration, and protein expression by Western blotting in an experimental neuropathic pain model in male Wistar rats. PBMT reduced mechanical hyperalgesia and tactile allodynia, decreased inflammatory features, and promoted hyporadiance detected by infrared thermography. Chronic constriction of the sciatic nerve significantly reduced mitochondrial respiration in the gastrocnemius muscle. Although PBMT did not restore mitochondrial respiratory capacity, it induced relevant molecular alterations in mitochondrial proteins. Specifically, PBMT increased the expression of OPA1, a key regulator of mitochondrial dynamics, and modulated components of the electron transport chain and ATP synthase in a wavelength-dependent manner. Overall, PBMT modulated nociception and promoted mitochondrial molecular adaptations. These findings suggest that PBMT-induced analgesia may involve mechanisms independent of skeletal muscle mitochondrial bioenergetic restoration. Distinct wavelength-dependent responses further contribute to therapeutic parameter optimization and support future translational and clinical research. Clinical trial number: not applicable."}],"keywords":["Chronic Constriction Injury","Mitochondria","Neuropathic Pain","Photobiomodulation"]},{"pmid":"42870113","title_fr":"Laser basse intensité versus haute intensité dans le canal carpien subaigu : essai randomisé en simple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser","haute puissance"],"nm":[808,860],"n":69,"effect":"favorable","theme":"Canal carpien","key":true,"l1":"Dans le canal carpien subaigu (69 patients), le laser haute intensité et le laser basse intensité ajoutés à la kinésithérapie font mieux que la simulation ; le haute intensité l'emporte sur la douleur, la fonction et la conduction nerveuse.","l2":"Essai pakistanais à trois bras de 23 patients : laser haute intensité (808 nm) + kinésithérapie, laser basse intensité (860 nm) + kinésithérapie, kinésithérapie + simulation. Évaluation à 6 semaines : EVA, questionnaire de Boston, force, latence motrice distale, vitesse de conduction sensitive, section du nerf médian.\n\nBaisse de douleur : −4,9 (haute intensité), −4,1 (basse intensité), −2,2 (témoin). Le haute intensité améliore davantage tous les critères, avec des tailles d'effet importantes.","l3":{"points":["Enregistrement IRCT20241111063665N1.","Douleur : −4,9 contre −4,1 contre −2,2 (p < 0,001).","Haute intensité : force +9,9 kg, latence motrice −1,2 ms, vitesse sensitive +12,3 m/s, section −3,7 mm²."],"limites":["Simple aveugle ; suivi de 6 semaines.","Paramètres différents entre les deux lasers (pas seulement la puissance)."],"pratique":"Dans le canal carpien, la PBM est un complément utile à la rééducation ; la haute intensité semble plus efficace à court terme."},"topic":"neuropathie-peripherique","title":"Clinical outcomes of low versus high intensity laser therapy in patients with subacute carpal tunnel syndrome: A randomized, single-blinded, controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ali Rana A","Ahmad A","Bashardoust Tajali S","et al."],"date":"2026-10-13","year":2026,"week":"2026-S42","doi":"10.1007/s10103-026-05070-5","pmcid":"PMC13661694","license":"cc by-nc-nd","oa":false,"pdf":"pdfs/42870113.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"abstract":[{"label":"","text":"A common entrapment of median nerve that causes pain, numbness, and functional impairment is called Carpal Tunnel Syndrome (CTS). Laser therapy is a noninvasive intervention for neural repair and pain modulation, but comparative evidence between Low-Level Laser Therapy (LLLT) and High-Intensity Laser Therapy (HILT) in subacute CTS is limited. The aims of this study were to compare the effects of LLLT and HILT on pain, functional status, electrophysiological, and ultrasonographic parameters in subacute CTS. A single-blinded randomized controlled trial (Reg. No. IRCT20241111063665N1) was conducted at the Department of Physiotherapy, The University of Lahore (UOL), Lahore, Pakistan, from August 2024 to March 2025. Sixty-nine participants with subacute CTS, confirmed by electromyography and nerve conduction studies, were randomly assigned to three groups (n = 23 each): Group A (HILT; 808 nm + physiotherapy), Group B (LLLT; 860 nm + physiotherapy), and Group C (physiotherapy + sham laser). Assessments were at baseline and week 6. Outcomes included pain (VAS), symptom severity and functional status (Boston Carpal Tunnel Questionnaire; BCTQ), grip strength, distal motor latency (DML), sensory nerve conduction velocity (SNCV), and median nerve cross-sectional area (CSA). ANCOVA with Bonferroni correction and effect size estimation was applied. At week 6, both HILT and LLLT showed significant improvements (p < 0.001). HILT achieved greater pain reduction (- 4.9) than LLLT (- 4.1) and control (- 2.2; p < 0.001), with greater improvement in BCTQ-SSS (- 2.2 points), BCTQ-FSS (- 1.9 points), grip strength (+ 9.9 kg), DML (- 1.2 ms), SNCV (+ 12.3 m/s), and CSA (- 3.7 mm²). Large effect sizes (Cohen's d > 0.8) were observed. Both LLLT and HILT are effective as adjuncts to physiotherapy in subacute CTS. HILT demonstrated greater improvements than LLLT within the parameters tested.Clinical Trial Number: IRCT20241111063665N1, Registration date: 17 March, 2025."}],"keywords":["Carpal Tunnel Syndrome","Laser Therapy","Low-Level Laser Therapy","Nerve Conduction Studies","Pain","Ultrasonography"]},{"pmid":"42860829","title_fr":"Laser bi-longueur d'onde à domicile pour la neuropathie diabétique douloureuse : essai multicentrique randomisé en double aveugle contre simulation","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser","domicile"],"nm":[405,640],"n":64,"effect":"favorable","theme":"Neuropathie diabétique","key":true,"metric":{"kind":"rates","outcome":"Répondeurs (douleur ≥ −30 % à S3)","a_label":"Laser actif","a":72.7,"b_label":"Simulation","b":32.3},"l1":"Chez 64 diabétiques avec neuropathie douloureuse, un laser rouge + violet utilisé à domicile 2 fois par jour pendant 3 semaines soulage la douleur d'au moins 30 % chez 72,7 % des patients, contre 32,3 % sous simulation.","l2":"Essai américain dans quatre centres indépendants, en double aveugle contre simulation. Le dispositif sur prescription émet simultanément à 640 et 405 nm ; chaque séance dure 5 minutes par pied. Les traitements antalgiques habituels étaient maintenus stables : la PBM venait en complément.\n\nLa différence de répondeurs est de 40,5 points (IC95 % 18,1–62,9). La douleur moyenne baisse de 33,4 points sur l'EVA contre 20,0 sous simulation, avec un effet maintenu jusqu'à la semaine 7. Les paresthésies, douleurs paroxystiques et brûlures s'améliorent le plus, pas la douleur provoquée. Aucun effet indésirable grave lié au dispositif.","l3":{"points":["Enregistrement NCT05291975 ; randomisation 33/31.","Critère principal : ≥ 30 % de baisse de l'EVA à S3 ; 72,7 % contre 32,3 % (p = 0,0024).","EVA : −33,4 contre −20,0 points (p = 0,026) ; effet maintenu à S7.","Analyse en intention de traiter, imputation simple pour 4 retraits."],"limites":["Suivi court (4 semaines après la fin du traitement).","Dispositif commercial : vérifier les financements dans le texte intégral.","Effet placebo important (32 % de répondeurs sous simulation)."],"pratique":"Premier essai multicentrique contre simulation d'une PBM à domicile dans la neuropathie diabétique douloureuse : option complémentaire de court terme, à côté du traitement standard."},"topic":"neuropathie-peripherique","title":"Dual-Wavelength Laser Therapy for Painful Diabetic Peripheral Neuropathy: A Randomized, Double-Blind, and Sham-Controlled Trial.","journal":"Pain research & management","journal_abbr":"Pain Res Manag","authors":["Franco S","Lara C","Gair K","et al."],"date":"2026-10-12","year":2026,"week":"2026-S42","doi":"10.1155/prm/8710857","pmcid":"PMC13655509","license":"cc by","oa":false,"pdf":"pdfs/42860829.pdf","cited_by":1,"pub_types":["Randomized Controlled Trial","Multicenter Study"],"abstract":[{"label":"BACKGROUND AND AIMS","text":"Painful diabetic peripheral neuropathy (DPN) is common and often inadequately controlled with pharmacological therapy. This study evaluated a clinician-directed, prescription home-use dual-wavelength low-level laser therapy device for temporary relief of painful DPN."},{"label":"METHODS","text":"In this prospective, randomized, double-blind, sham-controlled trial conducted at four independent U.S. clinical sites, 64 adults with painful DPN were randomized 1:1 to active treatment (n = 33) or sham treatment (n = 31). The active device emitted simultaneous 640 red and 405 nm violet coherent laser light. Participants self-administered treatment twice daily for 3 weeks, with each session consisting of 5 min per foot. The primary endpoint was the proportion of participants achieving at least a 30% reduction in visual analog scale (VAS) foot pain score from baseline to Week 3. Secondary outcomes included VAS change, neuropathic pain symptoms, treatment satisfaction, durability through Week 7, adherence, blinding integrity, and safety. Participants were required to maintain a stable analgesic and neuropathic-pain regimen throughout, so the intervention was delivered in addition to existing standard care. The primary endpoint was analyzed in the intent-to-treat population, with single imputation for the four participants who withdrew before receiving a device."},{"label":"RESULTS","text":"At Week 3, 72.7% of active-treated participants met the primary responder criterion compared with 32.3% of sham-treated participants, a between-group difference of 40.5 percentage points (95% CI 18.1 to 62.9) (p = 0.0024). Mean VAS reduction was greater with active treatment than sham treatment (-33.4 vs -20.0 points; p = 0.026). Improvements were sustained through Week 7, with favorable symptom trends, higher satisfaction, and no serious device-related adverse events. Improvement on the neuropathic pain symptom inventory was greatest for paresthesia/dysesthesia, paroxysmal pain, and burning pain and was not evident for evoked pain."},{"label":"INTERPRETATION","text":"Prescription home-use dual-wavelength laser therapy was well tolerated and produced clinically meaningful short-term reductions in foot pain in adults with painful DPN at four independent clinical sites. Because assessment ended four weeks after treatment completion, the findings support short-term pain relief, and the intervention is best positioned as a complementary, nonpharmacological modality used alongside standard care."},{"label":"TRIAL REGISTRATION","text":"ClinicalTrials.gov identifier: NCT05291975."}],"keywords":["diabetic peripheral neuropathy","home-use device","low-level laser therapy","neuropathic pain","photobiomodulation","randomized controlled trial"]},{"pmid":"42858917","title_fr":"Laser haute intensité versus ondes de choc dans le syndrome du canal cubital après brûlure : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":75,"effect":"favorable","theme":"Autres compressions nerveuses","l1":"Chez 75 brûlés avec compression du nerf ulnaire au coude, le laser haute intensité ajouté aux exercices de glissement nerveux améliore plus la conduction et la fonction du membre que les ondes de choc ou les exercices seuls, à 12 semaines.","l2":"Essai à trois bras de 25 patients, évaluateur en aveugle : laser haute intensité + exercices, ondes de choc + exercices, exercices seuls, pendant 4 semaines. Critères : vitesse de conduction motrice ulnaire, amplitude des potentiels moteurs, score DASH.\n\nLes deux techniques physiques font mieux que les exercices seuls ; le laser dépasse les ondes de choc sur tous les critères, avec un bénéfice maintenu à 12 semaines. Aucun effet indésirable.","l3":{"points":["69 patients sur 75 suivis à 12 semaines.","Toutes les comparaisons p < 0,001 contre exercices seuls."],"limites":["Population très spécifique (séquelles de brûlure).","Paramètres laser non détaillés dans le résumé."],"pratique":"Résultat intéressant pour la rééducation des neuropathies de compression post-brûlure."},"topic":"neuropathie-peripherique","title":"Postburn Cubital Tunnel Syndrome Electrophysiological and Functional Responses to High-Intensity Laser Therapy Versus Extracorporeal Shock Wave Therapy: A Randomized Controlled Trial.","journal":"Archives of physical medicine and rehabilitation","journal_abbr":"Arch Phys Med Rehabil","authors":["Mohamed MH","Mansour WT","Selim MN","et al."],"date":"2026-10-10","year":2026,"week":"2026-S41","doi":"10.1016/j.apmr.2026.10.006","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"OBJECTIVE","text":"To compare the additional effects of high-intensity laser therapy (HILT) and extracorporeal shock wave therapy (ESWT), combined with ulnar nerve gliding exercises (UNGE), on electrophysiological and functional outcomes in patients with postburn cubital tunnel syndrome (CuTS)."},{"label":"DESIGN","text":"Prospective assessor-blinded, parallel-group randomized controlled trial."},{"label":"SETTING","text":"University outpatient rehabilitation clinic."},{"label":"PARTICIPANTS","text":"Participants with postburn CuTS involving the upper extremity (N=75)."},{"label":"INTERVENTIONS","text":"Participants were randomly assigned (1:1:1) to HILT+UNGE (n=25), ESWT+UNGE (n=25), or UNGE alone (n=25) for 4 weeks."},{"label":"MAIN OUTCOME MEASURES","text":"Primary outcomes were ulnar motor nerve conduction velocity (MNCV) across the elbow and compound muscle action potential (CMAP) amplitudes recorded from the abductor digiti minimi during ulnar nerve stimulation at 3 standardized sites. The secondary outcome was the Disabilities of the Arm, Shoulder and Hand (DASH) score. Assessments were performed at baseline, posttreatment, and 12-week follow-up."},{"label":"RESULTS","text":"All participants completed the intervention, and 69 completed the 12-week follow-up. Significant posttreatment versus pretreatment changes were observed for MNCV, CMAP amplitudes, and DASH scores (all P<.001). Both HILT and ESWT produced greater improvements than UNGE alone at posttreatment and follow-up (all P<.001). HILT resulted in significantly greater improvements than ESWT across all electrophysiological outcomes and DASH scores. No intervention-related adverse events were reported."},{"label":"CONCLUSIONS","text":"Both HILT and ESWT combined with UNGE improved nerve conduction and upper-limb function more than UNGE alone in patients with postburn CuTS. HILT produced superior electrophysiological and functional outcomes compared with ESWT, with benefits maintained at 12-week follow-up."}],"keywords":["Cubital tunnel syndrome","Extracorporeal shock wave therapy","High-intensity laser therapy","Nerve conduction studies","Rehabilitation","Ulnar neuropathy"]},{"pmid":"42789121","title_fr":"Réponses analgésiques à la PBM selon le sexe chez le rat neuropathique","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Préclinique","l1":"La PBM infrarouge soulage la douleur neuropathique chez les rats des deux sexes ; les femelles récupèrent relativement plus, et le cycle hormonal module la sensibilité.","l2":"Dix séances, trois fois par semaine, après constriction du nerf sciatique. Les auteurs demandent d'inclure le sexe comme variable dans les études de PBM.","l3":{"points":["Sensibilité moindre en metœstrus."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Sex-related analgesic responses to photobiomodulation therapy in rats with neuropathic pain.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Marques NF","Bonifacio RP","Jesus JM","et al."],"date":"2026-09-25","year":2026,"week":"2026-S39","doi":"10.1007/s10103-026-05046-5","pmcid":"PMC13615017","license":"cc by","oa":true,"pdf":"pdfs/42789121.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Neuropathic pain is associated with sensory abnormalities and remains difficult to treat. Photobiomodulation therapy (PBMT) has emerged as a non-pharmacological approach with analgesic potential; however, sex-related differences in treatment responses remain poorly understood. We investigated the effects of PBMT in male and female rats subjected to chronic constriction injury (CCI) of the sciatic nerve. Animals received infrared PBMT administered three times per week during ten sessions, and nociceptive responses were assessed using mechanical hyperalgesia and tactile allodynia throughout treatment. CCI induced significant nociceptive hypersensitivity in both sexes. PBMT progressively increased withdrawal thresholds and reduced pain-like behaviors. Females exhibited greater relative recovery in both mechanical hyperalgesia and tactile allodynia, whereas males maintained higher absolute nociceptive thresholds throughout the experimental period. Estrous cycle analysis revealed reduced pain sensitivity during metestrus compared with estrus and proestrus. These findings demonstrate that PBMT effectively attenuates neuropathic pain-like behaviors in both sexes and suggest that biological sex and hormonal status may influence therapeutic responses. The results support the inclusion of sex as a biological variable in preclinical photobiomodulation studies."}],"keywords":["Estrous cycle","Neuropathic pain","Photobiomodulation therapy","Sex differences"]},{"pmid":"42781664","title_fr":"Laser He-Ne échoguidé après libération par acupotomie dans le canal carpien : étude rétrospective multicentrique","type":"cohort","level":3,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[632.8],"n":163,"effect":"favorable","theme":"Canal carpien","l1":"Chez 163 patients, le laser He-Ne après libération mini-invasive du canal carpien soulage autant que l'infiltration de corticoïdes, sans les hyperglycémies observées sous corticoïdes.","l2":"Trois groupes comparés en Chine : acupotomie + laser He-Ne (n = 54), acupotomie + infiltration de corticoïdes (n = 55), acupotomie seule (n = 54). Le laser et les corticoïdes améliorent davantage la douleur et la fonction à 1, 4 et 16 semaines que l'acupotomie seule, sans différence entre eux.\n\nSix hyperglycémies liées aux corticoïdes ; aucun effet indésirable sous laser. Une stratégie d'épargne cortisonique intéressante chez le diabétique.","l3":{"points":["Critères : EVA, questionnaire de Boston, électrophysiologie, échographie."],"limites":["Rétrospectif, non randomisé."],"pratique":"Alternative au corticoïde à discuter chez les patients à risque métabolique."},"topic":"neuropathie-peripherique","title":"Ultrasound-Guided Low-Level He-Ne Laser Therapy Following Acupotomy Release for Carpal Tunnel Syndrome: A Multicenter Retrospective Study.","journal":"Journal of pain research","journal_abbr":"J Pain Res","authors":["Shang X","Luan GR","Meng DH","et al."],"date":"2026-09-19","year":2026,"week":"2026-S38","doi":"10.2147/JPR.S625251","pmcid":"PMC13600462","license":"cc by-nc","oa":true,"pdf":"pdfs/42781664.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Carpal tunnel syndrome (CTS) is a common compressive neuropathy associated with pain, sensory disturbance, and functional impairment. Although corticosteroid injection is widely used as an adjunctive treatment for minimally invasive decompression, steroid-related adverse effects limit its clinical application in some patients. This study aimed to evaluate the efficacy and safety of ultrasound- guided low-level He-Ne laser therapy following acupotomy release as a steroid-sparing treatment strategy for CTS."},{"label":"METHODS","text":"This multicenter retrospective study included 163 patients with CTS who underwent one of the following treatments: ultrasound-guided acupotomy combined with low-level He-Ne laser therapy group (ALG, n=54), acupotomy combined with corticosteroid injection group (ACG, n=55), or acupotomy release group (AG, n=54). Pain intensity was assessed using the Visual Analog Scale (VAS), and functional outcomes were evaluated using the Boston Carpal Tunnel Questionnaire (BCTQ). Electrophysiological and ultrasonographic parameters of the median nerve were also analyzed before and after treatment. Adverse events were recorded during follow-up."},{"label":"RESULTS","text":"All three groups showed significant improvements in pain, functional outcomes, electrophysiological findings, and imaging parameters after treatment (P<0.05). Compared with the AG, both the ALG and ACG demonstrated significantly greater reductions in VAS and BCTQ scores at 1, 4, and 16 weeks after treatment (P<0.05). No significant differences in VAS scores were observed between the ALG and ACG during follow-up. Improvements in electrophysiological and ultrasonographic outcomes were also more pronounced in the ALG and ACG than in the AG. No serious complications were observed in any group. Steroid-related hyperglycemia occurred in six patients in the ACG, whereas no laser-related adverse events were reported in the ALG."},{"label":"CONCLUSION","text":"Ultrasound-guided low-level He-Ne laser therapy combined with acupotomy release significantly improved pain, function, and nerve recovery in CTS patients. Its therapeutic efficacy was comparable to corticosteroid injection while avoiding steroid-related adverse events, suggesting that it may represent a promising steroid-sparing treatment strategy."}],"keywords":["He-Ne laser","acupotomy","carpal tunnel syndrome","low-level laser therapy","pain management","ultrasound-guided intervention"]},{"pmid":"42761408","title_fr":"Traitement conservateur du canal carpien pendant la grossesse et l'allaitement : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"neutre","theme":"Canal carpien","l1":"Douze études : l'attelle de nuit reste le traitement de première ligne du canal carpien de la grossesse ; les preuves pour le laser sont limitées et incohérentes.","l2":"Revue enregistrée (PROSPERO) avec GRADE, tous plans d'étude confondus. Attelle et exercices de glissement améliorent les formes légères à modérées ; l'infiltration échoguidée soulage les formes sévères.\n\nKinésiotaping, ventouses et laser ont des preuves faibles. La certitude est faible à très faible pour tous les critères.","l3":{"points":["12 études ; méta-analyse impossible."],"limites":["Très peu d'études sur le laser."],"pratique":"Pendant la grossesse, le laser n'est pas une option prioritaire faute de données."},"topic":"neuropathie-peripherique","title":"Conservative management of carpal tunnel syndrome during pregnancy and lactation: A systematic review of mixed study designs.","journal":"Journal of clinical orthopaedics and trauma","journal_abbr":"J Clin Orthop Trauma","authors":["Kumari O","Mishra R","Singh V","et al."],"date":"2026-09-06","year":2026,"week":"2026-S36","doi":"10.1016/j.jcot.2026.103608","pmcid":"PMC13586587","license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"BACKGROUND","text":"Pregnancy-related carpal tunnel syndrome (PRCTS) is the most common entrapment neuropathy during pregnancy, caused by gestational hormonal changes and fluid retention leading to increased intracarpal pressure and median nerve compression. Although symptoms often resolve postpartum, many patients experience significant functional impairment. Conservative treatment is preferred due to maternal-fetal safety concerns, but comparative evidence across modalities remains heterogeneous. This systematic review aimed to evaluate the effectiveness of conservative and minimally invasive interventions for PRCTS."},{"label":"METHODS","text":"The review protocol was registered in PROSPERO (CRD420261308958). A systematic search of PubMed, Embase, and the Cochrane Library was conducted from database inception to 24 November 2025 (full search strategies in Supplementary Table S1). Studies evaluating conservative or minimally invasive treatments for CTS during pregnancy or lactation were included, irrespective of study design; case reports and case series without a comparator group were excluded a priori. Two independent reviewers performed study selection, data extraction, and methodological quality assessment using the National Institutes of Health (NIH) Quality Assessment Tools selected according to study design, and outcome-level certainty of evidence was additionally rated using the GRADE approach. Because of clinical and methodological heterogeneity, meta-analysis was not feasible; findings were synthesized qualitatively and supplemented with descriptive pooled summaries of reported outcomes by intervention."},{"label":"RESULTS","text":"Twelve studies met inclusion criteria. Night wrist splinting consistently improved symptoms in mild-to-moderate cases, particularly when combined with nerve and tendon gliding exercises. Ultrasound-guided corticosteroid injections provided effective short-term symptom relief in severe or refractory cases and appeared acceptable based on limited available evidence; however, no formal safety analysis was possible. Evidence supporting adjunct therapies, including kinesio taping, cupping, and laser therapy, was limited and inconsistent. Certainty of evidence, rated using GRADE, was low to very low for all principal outcomes, reflecting small sample sizes, methodological heterogeneity, and imprecision (Table 1b)."},{"label":"CONCLUSION","text":"Night splinting remains the first-line treatment for PRCTS, with corticosteroid injection as a potential option for refractory cases when benefits outweigh risks. Further high-quality studies are needed to establish standardized treatment protocols and long-term maternal-fetal safety."}],"keywords":["Adrenal cortex hormones","Carpal tunnel syndrome","Exercise therapy","Lactation","Median nerve","Pregnancy","Splints","Systematic review","Ultrasonography"]},{"pmid":"42791878","title_fr":"PBM et maladies du système nerveux périphérique : analyse bibliométrique","type":"biblio","level":0,"pop":"—","ctx":["autres"],"aim":"—","mode":[],"nm":[],"n":null,"effect":"—","theme":"Bibliométrie","l1":"191 publications sur 24 atteintes nerveuses périphériques : la recherche se concentre sur le canal carpien et s'organise en trois domaines (douleur, régénération, mécanismes).","l2":"Analyse Web of Science classée selon le MeSH et la CIM-11. La production augmente depuis 2010 et se diversifie vers d'autres neuropathies.\n\nUtile pour repérer les zones peu étudiées.","l3":{"points":["14 670 notices, 191 publications retenues."],"limites":["Bibliométrie."],"pratique":"Aucune conséquence clinique."},"topic":"neuropathie-peripherique","title":"Photobiomodulation in Peripheral Nervous System Disorders: A Bibliometric Analysis of Functional Research Patterns.","journal":"Bioengineering (Basel, Switzerland)","journal_abbr":"Bioengineering (Basel)","authors":["Seok JW","Kim K","Baek SJ","et al."],"date":"2026-08-28","year":2026,"week":"2026-S35","doi":"10.3390/bioengineering13091006","pmcid":"PMC13603448","license":"cc by","oa":true,"pdf":"pdfs/42791878.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"This study provides a comprehensive bibliometric analysis of photobiomodulation (PBM) research in peripheral nervous system (PNS) disorders, aiming to characterize its structural features and developmental trends. Using a bibliometric workflow, a final dataset of 191 unique publications across 24 standardized PNS disease entities was identified through MeSH- and ICD-11-based classification from 14,670 records retrieved from the Web of Science Core Collection. The results show that PBM research has grown steadily since 2010 but remains concentrated in specific clinical conditions, particularly carpal tunnel syndrome (CTS). Keyword co-occurrence network analysis and functional classification identified three primary domains of PBM research: (1) pain modulation, (2) nerve regeneration and structural repair, and (3) biological/mechanistic regulation. The relative emphasis of these domains differed across disease groups, with compression and entrapment neuropathies emphasizing intervention parameters and assessment, nerve injury/regeneration research showing greater representation of structural repair and biological regulation, and neuropathic pain/neuropathy research showing a prominent pain-related component. Temporal analysis indicated diversification toward a broader range of neuropathic conditions and increasing representation of pain-related and biological themes. In conclusion, PBM research exhibits distinct functional patterns across PNS disease contexts. The function-oriented classification framework provides a structured basis for identifying research gaps and disease-specific research priorities."}],"keywords":["bibliometric analysis","nerve regeneration","neuropathy","pain modulation","peripheral nervous system","photobiomodulation"]},{"pmid":"42651804","title_fr":"La PBM favorise la réparation nerveuse en restaurant le NGF et la protéine P0 de la myéline (rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[904],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat, dix séances de laser 904 nm après lésion du sciatique préservent la structure du nerf, restaurent le facteur de croissance nerveuse (NGF) et augmentent la protéine de myéline P0.","l2":"Analyses en microscopie électronique, morphométrie, immunofluorescence et Western blot, PBM débutée 14 jours après la lésion.\n\nArgument mécanistique pour un effet régénératif sur la myéline.","l3":{"points":["Mécanisme : NGF et P0 restaurés."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Photobiomodulation Therapy Enhances Peripheral Nerve Repair by Restoring Nerve Growth Factor Levels and Increasing Myelin Protein Zero Expression After Chronic Constriction Injury in Rats.","journal":"Current issues in molecular biology","journal_abbr":"Curr Issues Mol Biol","authors":["Oliveira ME","Santos FM","Ciena AP","et al."],"date":"2026-08-10","year":2026,"week":"2026-S33","doi":"10.3390/cimb48080806","pmcid":"PMC13510466","license":"cc by","oa":true,"pdf":"pdfs/42651804.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Neuropathic pain is a chronic condition frequently associated with peripheral nerve injury and is characterized by significant structural and molecular alterations. Photobiomodulation therapy (PBMT) has demonstrated analgesic and anti-inflammatory effects; however, its influence on neurotrophic and myelin-associated repair mechanisms remains incompletely understood. The aim of this study was to investigate the effects of PBMT on ultrastructural, morphometric, and molecular changes induced by chronic constriction injury (CCI) of the sciatic nerve in male rats, with an emphasis on NGF and P0 expression. Neuropathy was induced using the CCI model of the sciatic nerve. PBMT was initiated 14 days after injury and administered in ten sessions using an infrared 904 nm laser. Transmission electron microscopy, morphometric analysis, immunofluorescence, and Western blot analyses were performed to evaluate neural regeneration and the expression of NGF and P0. Animals subjected to CCI exhibited ultrastructural changes consistent with Wallerian degeneration, accompanied by reduced NGF and P0 expression in the sciatic nerve. In contrast, PBMT markedly preserved nerve morphology, restored NGF expression, and significantly increased P0 protein levels. Together, these findings demonstrate that PBMT enhances peripheral nerve repair by promoting both molecular and structural mechanisms involved in axonal regeneration and myelin restoration. Restoration of NGF expression and increased P0 protein expression suggest that these mechanisms contribute to the regenerative effects of PBMT, supporting its potential as a safe, noninvasive therapeutic strategy for peripheral neuropathies."}],"keywords":["nerve injury","neural regeneration","peripheral neuropathy","photobiomodulation","sciatic nerve"]},{"pmid":"42430054","title_fr":"PBM avec ou sans ILIB dans la neuropathie diabétique : essai pilote randomisé","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[],"n":26,"effect":"mitigé","theme":"Neuropathie diabétique","l1":"Chez 26 diabétiques, la PBM locale, seule ou avec irradiation laser du sang (ILIB), est faisable et suivie d'une baisse de la douleur, mais sans différence démontrée avec la simulation.","l2":"Essai pilote brésilien à trois groupes (PBM locale, PBM + ILIB, simulation), 12 séances en 23 jours. La douleur diminue dans le temps dans l'ensemble, significativement dans le groupe PBM locale ; certains symptômes (engourdissement, crampes, peau sèche) s'améliorent.\n\nLe modèle mixte ne montre pas d'interaction groupe × temps : aucune supériorité nette n'est établie. Les auteurs soulignent eux-mêmes l'effet placebo possible et le petit effectif.","l3":{"points":["Instrument : Michigan Neuropathy Screening Instrument.","Effet du temps sur la douleur : β = −0,78 (p = 0,001) ; pas d'interaction groupe × temps."],"limites":["Pilote, 26 patients répartis en 3 groupes ; suivi court."],"pratique":"Ne justifie pas l'ajout de l'ILIB ; utile pour dimensionner un futur essai."},"topic":"neuropathie-peripherique","title":"Photobiomodulation with or without ILIB in diabetic peripheral neuropathy: a randomized pilot trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Alencar Fonseca Santos J","de Souza Maciel Ferreira JE","da Silva Galvão JW","et al."],"date":"2026-07-10","year":2026,"week":"2026-S28","doi":"10.1007/s10103-026-04948-8","pmcid":"PMC13354662","license":"cc by","oa":true,"pdf":"pdfs/42430054.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Diabetic peripheral neuropathy is a disabling chronic complication of diabetes mellitus, associated with neuropathic pain, sensory dysfunction, and reduced quality of life. Because pharmacological treatments often provide only partial relief, photobiomodulation therapy (PBMT) has emerged as a promising non-pharmacological strategy with metabolic, anti-inflammatory, and neuromodulatory effects. To assess the feasibility of local PBMT, administered alone or combined with intravascular laser irradiation of blood (ILIB), and to explore preliminary short-term changes in neuropathic pain, neuropathic symptoms, and sensory responses in individuals with diabetic peripheral neuropathy. This prospective randomized controlled pilot trial included 26 participants allocated to three groups: local PBMT, local PBMT combined with ILIB, and sham control. All randomized participants completed 12 sessions over 23 days. Neuropathic pain intensity was assessed using the Visual Analog Scale, and neuropathic symptoms were evaluated using the Michigan Neuropathy Screening Instrument. Friedman and McNemar tests were used for exploratory within-group and paired analyses, and a linear mixed-effects model evaluated pain trajectory over time. Neuropathic pain intensity decreased across the five assessment points (p < 0.001), with significant intragroup reduction in the local PBMT group (p = 0.007). Improvements were observed in selected symptoms, including numbness, cramps, and dry skin with fissures. The mixed-effects model showed a significant effect of time on pain reduction (beta = -0.78; p = 0.001), although no significant group x time interaction was detected. Local PBMT, administered alone or combined with ILIB, was feasible in this outpatient pilot trial and was followed by preliminary short-term reductions in neuropathic pain and selected neuropathic symptoms. However, no definitive between-group superiority was demonstrated, and the findings should be interpreted cautiously because of the pilot design, small sample size, heterogeneity in baseline pain intensity, potential placebo effects, and short follow-up period."}],"keywords":["Diabetic Neuropathies","Low-Level Light Therapy","Pain Measurement","Peripheral Neuropathy","Photobiomodulation Therapy"]},{"pmid":"42373001","title_fr":"PBM dans la neuropathie périphérique du diabétique et du patient atteint de cancer : revue narrative","type":"review","level":5,"pop":"adulte","ctx":["diabète","CIPN"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue des études 2010–2025 : la PBM réduirait la douleur, améliorerait la conduction nerveuse et la qualité de vie dans les neuropathies diabétiques et chimio-induites.","l2":"Revue narrative (PubMed, Scopus, Google Scholar). Elle cite des effets sur des biomarqueurs neurologiques (CGRP, énolase neurospécifique) et des mécanismes anti-inflammatoires et mitochondriaux.\n\nElle appelle à de grands essais randomisés pour standardiser les protocoles.","l3":{"points":["Cibles : neuropathie diabétique, neuropathie chimio-induite."],"limites":["Revue narrative."],"pratique":"Bonne introduction au sujet."},"topic":"neuropathie-peripherique","title":"Photobiomodulation therapy for peripheral neuropathy in diabetic and cancer patients: A narrative review.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Rastkar S","Eftekharian S"],"date":"2026-06-29","year":2026,"week":"2026-S27","doi":"10.1016/j.pdpdt.2026.105561","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":0,"pub_types":["Review"],"abstract":[{"label":"BACKGROUND","text":"Peripheral neuropathy is a common and debilitating complication frequently observed in diabetic patients and individuals undergoing chemotherapy and radiotherapy for cancer treatment. Diabetic peripheral neuropathy (DPN) and chemotherapy-induced peripheral neuropathy (CIPN) significantly impair quality of life and may adversely affect oral health and daily functioning."},{"label":"OBJECTIVE","text":"This narrative review aimed to evaluate the potential therapeutic effects of photobiomodulation therapy (PBMT) in the management of peripheral neuropathy, with particular focus on DPN and CIPN in cancer patients."},{"label":"METHODS","text":"A literature search was conducted using PubMed, Scopus, and Google Scholar databases for studies published between 2010 and 2025. Relevant English-language studies investigating PBMT in peripheral neuropathy, neuropathic pain, nerve regeneration, biomarkers, and quality of life outcomes were included."},{"label":"RESULTS","text":"Current evidence suggests that PBMT may reduce neuropathic pain, improve nerve conduction, enhance sensory function, and improve quality of life in patients with DPN and CIPN. PBMT has also demonstrated beneficial effects on neurobiological biomarkers, including calcitonin gene-related peptide and neuron-specific enolase. In addition, its anti-inflammatory and mitochondrial regulatory effects may contribute to nerve regeneration and tissue repair."},{"label":"CONCLUSION","text":"PBMT represents a promising non-invasive therapeutic strategy for peripheral neuropathy management in diabetic individuals and cancer patients. Although available evidence supports its safety and clinical efficacy, further large-scale randomized clinical trials are required to standardize treatment protocols and clarify long-term outcomes."}],"keywords":["Chemotherapy-induced peripheral neuropathy","Diabetic peripheral neuropathy","Low-level laser therapy","Nerve regeneration","Peripheral neuropathy","Photobiomodulation therapy"]},{"pmid":"42250031","title_fr":"Photothérapie basse énergie dans la névralgie post-zostérienne : mécanismes et implications cliniques","type":"review","level":5,"pop":"adulte","ctx":["autres"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Névralgies","l1":"Revue : la PBM réduit la douleur de la névralgie post-zostérienne et une application précoce pourrait en diminuer la survenue ; mécanismes anti-inflammatoires et régénératifs.","l2":"Les auteurs relient la physiopathologie (inflammation des ganglions rachidiens, perte d'innervation cutanée, dérèglement des canaux ioniques) aux effets de la PBM : élévation des seuils douloureux, polarisation M1→M2 des macrophages, restauration de la Na⁺/K⁺-ATPase.\n\nLes données cliniques sont résumées sans méta-analyse.","l3":{"points":["Piste : traitement précoce dès le zona pour prévenir la névralgie."],"limites":["Revue narrative."],"pratique":"Soutient l'avis d'experts de la WALT 2026."},"topic":"neuropathie-peripherique","title":"Low-Level Light Therapy in Postherpetic Neuralgia: A Review of Mechanistic Insights and Clinical Implications.","journal":"Cellular and molecular neurobiology","journal_abbr":"Cell Mol Neurobiol","authors":["Ma YC","Chiang YC","Yu S"],"date":"2026-06-06","year":2026,"week":"2026-S23","doi":"10.1007/s10571-026-01763-1","pmcid":"PMC13478056","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/42250031.pdf","cited_by":0,"pub_types":["Review"],"abstract":[{"label":"","text":"Known as the most prevailing complication of herpes zoster (HZ), postherpetic neuralgia (PHN) can lead to long-term skin discomfort. Current medications for PHN remain suboptimal with incomplete relief and potential side effects. Low-level light therapy (LLLT) has been increasingly explored as a non-invasive modality for treating PHN, but the mechanistic basis and clinical implications have not been synthesized in a translational framework. In this review, we explore the pathophysiological mechanisms of PHN and the biological mechanisms of LLLT, integrating current mechanistic insights with available clinical evidence. We summarize the experimental and clinical literature evaluating LLLT for PHN and related neuropathic pain models, mainly focusing on mechanisms across peripheral tissues, dorsal root ganglia, and neuro-immune aspects, as we evaluate therapeutic parameters and outcomes from available clinical studies. Current evidence suggests that PHN is associated with dorsal root ganglion (DRG) inflammation, peripheral cutaneous neuroinflammation, loss of cutaneous innervation, and ion channel dysregulation. These changes comprehensively lead to hyperexcitable neurons with a lower sensory threshold. Across neuropathic pain models, LLLT elevates mechanical and thermal pain thresholds, attenuates inflammatory cytokine signaling, and promotes an immune cell phenotype shift toward an anti-inflammatory profile including M1-to-M2 macrophage polarization. LLLT also stabilizes membrane excitability by restoring Na⁺/K⁺-ATPase activity and modulating calcium dynamics, while supporting peripheral nerve repair via axonal regeneration. Clinically, administering LLLT to patients with PHN resulted in significant pain reduction, and early intervention may also reduce its incidence. By integrating experimental and clinical research, LLLT serves as a promising approach for PHN owing to its efficacy for anti-inflammation, neuronal regeneration and ion modulation."}],"keywords":["Low-level light therapy","Neuroinflammation","Neuropathic pain","Peripheral nerve regeneration","Photobiomodulation","Postherpetic neuralgia"]},{"pmid":"42307460","title_fr":"Laser haute intensité dans la méralgie paresthésique : essai randomisé en double aveugle contre simulation","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["haute puissance"],"nm":[1064],"n":62,"effect":"favorable","theme":"Autres compressions nerveuses","l1":"Chez 62 patients atteints de méralgie paresthésique, 12 séances de laser haute intensité (1 064 nm) améliorent la douleur, la fonction et la conduction nerveuse à 12 semaines par rapport à la simulation.","l2":"Essai en double aveugle : 12 séances en 4 semaines (1 064 nm, 12 W, 600 J/cm²) contre simulation identique ; 54 patients analysés. À 12 semaines, la douleur (p = 0,006), la fonction des membres inférieurs (p = 0,043) et la vitesse de conduction sensitive du nerf cutané latéral de la cuisse (p = 0,027) sont meilleures sous laser.\n\nLes gains électrophysiologiques restent faibles et dans les normes. Des effets indésirables légers et transitoires sont plus fréquents sous laser (16,1 % contre 0 %).","l3":{"points":["Critère principal : EN douleur ; mesures à S4, S8, S12.","Effets indésirables : 16,1 % contre 0 % (p = 0,0525)."],"limites":["Différences neurophysiologiques modestes.","Monocentrique."],"pratique":"Option non invasive pour une méralgie paresthésique rebelle."},"topic":"neuropathie-peripherique","title":"Efficacy of High-Intensity Laser Therapy for Meralgia Paresthetica: A Randomized, Double-Blind, Sham-Controlled Trial.","journal":"American journal of physical medicine & rehabilitation","journal_abbr":"Am J Phys Med Rehabil","authors":["Mogahed HG","ElMeligie MM","Radwan RE","et al."],"date":"2026-06-04","year":2026,"week":"2026-S23","doi":"10.1097/PHM.0000000000002918","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"The aim of the study was to evaluate high-intensity laser therapy versus sham for pain, function, and nerve conduction in meralgia paresthetica."},{"label":"DESIGN","text":"This is a randomized, double-blind, sham-controlled trial."},{"label":"METHODS","text":"Patients with meralgia paresthetica ( n  = 62 randomized, n  = 54 analyzed) received 12 sessions of high-intensity laser therapy (1064 nm, 12 W, 600 J/cm 2 ) or identical sham over 4 wks. Primary outcome is as follows: Numeric Pain Rating Scale. Secondary outcomes are as follows: Lower Extremity Functional Scale, lateral femoral cutaneous sensory nerve conduction velocity, and Short Form-36 Health Survey, assessed at baseline, weeks 4, 8, and 12."},{"label":"RESULTS","text":"At week 12, high-intensity laser therapy demonstrated significantly greater improvements versus sham in pain (Numeric Pain Rating Scale, P  = 0.006), function (Lower Extremity Functional Scale, P  = 0.043), and sensory nerve conduction velocity ( P  = 0.027). Sensory nerve conduction velocity showed small but significant between-group differences favoring high-intensity laser therapy, although values remained within normal limits. Mild, transient adverse events occurred more frequently with high-intensity laser therapy (16.1% vs. 0%, P  = 0.0525)."},{"label":"CONCLUSIONS","text":"High-intensity laser therapy significantly improved pain, function, and nerve conduction velocity compared with sham in meralgia paresthetica patients over 12 wks. These findings support high-intensity laser therapy as a noninvasive treatment option; neurophysiological changes were small and within normative limits, warranting cautious interpretation."}],"keywords":["Laser Therapy","Meralgia Paresthetica","Nerve Compression Syndromes","Pain Management"]},{"pmid":"42326682","title_fr":"Le laser basse énergie limite le stress oxydatif et l'apoptose induits par le cisplatine via l'autophagie AMPK (cellules PC12)","type":"preclinical","level":5,"pop":"—","ctx":["CIPN"],"aim":"prévention","mode":["laser"],"nm":[660],"n":null,"effect":"favorable","theme":"Préclinique","l1":"In vitro, une PBM à 660 nm (5 J/cm²) avant le cisplatine protège des cellules neuronales : moins d'apoptose, moins de stress oxydatif, mitochondries préservées, via la voie AMPK.","l2":"Le blocage de l'AMPK par ARN interférent supprime la protection : la voie est centrale. Ce résultat soutient l'idée d'une PBM préventive avant chimiothérapie neurotoxique.","l3":{"points":["Prétraitement de 10 min, cisplatine 10 μM pendant 24 h."],"limites":["Modèle cellulaire."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Low-Level Laser Mitigates Cisplatin-Induced Oxidative Stress and Apoptosis via AMPK-Mediated Autophagy in PC12 Cells.","journal":"ACS omega","journal_abbr":"ACS Omega","authors":["Ou HC","Tsai KL","Yang HL","et al."],"date":"2026-06-04","year":2026,"week":"2026-S23","doi":"10.1021/acsomega.5c12039","pmcid":"PMC13280684","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/42326682.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"","text":"Platinum-based chemotherapeutic agents, such as cisplatin, form the cornerstone of many modern anticancer treatment regimens. Despite their clinical effectiveness, long-term use is often limited by dose-related side effects, notably peripheral neuropathy, which significantly impacts patient quality of life and restricts treatment success. Neuroprotective strategies are still limited. Low-level laser (LLL) therapy, also known as photobiomodulation, has recently gained recognition as a noninvasive approach capable of reducing various tissue damages, including nerve injuries. However, the cellular and molecular mechanisms behind its protective effects in chemotherapy-induced neurotoxicity are not yet fully understood. In this study, we examined the neuroprotective effects of LLL in an in vitro model of cisplatin toxicity using PC12 neuronal cells. PC12 neuronal cells were pretreated with LLL irradiation at 660 nm and 5 J/cm2 for 10 min prior to exposure to 10 μM cisplatin for 24 h. Cell viability and cytotoxicity were assessed using MTT and LDH assays. Apoptosis was evaluated via TUNEL staining and caspase-3 activity. Mitochondrial function and oxidative stress were examined by JC-1 staining for membrane potential, MitoSOX for mitochondrial ROS, and MDA assay for lipid peroxidation. AMPK expression was silenced using siRNA, and protein levels related to autophagy, apoptosis, and AMPK signaling were analyzed by Western blotting. Our results showed that pretreatment with LLL at 5 J/cm2 significantly improved cell viability and decreased cisplatin-induced cytotoxicity and apoptosis at a concentration of 10 μM. LLL reduced oxidative stress caused by cisplatin and maintained mitochondrial function, as demonstrated by lower lipid peroxidation, decreased mitochondrial ROS production, and stabilization of mitochondrial membrane potential. In addition, we found that these protective effects were mediated through activation of the AMPK signaling pathway, which enhanced autophagy and inhibited apoptotic processes. Silencing of AMPK eliminated the neuroprotective effects of LLL, confirming its key role in this mechanism. Overall, our findings suggest that LLL therapy exhibits robust neuroprotective effects against cisplatin-induced neuronal damage through AMPK-driven autophagy, offering a promising adjunctive strategy for managing chemotherapy-induced peripheral neuropathy."}],"keywords":[]},{"pmid":"42253675","title_fr":"Syndrome de Tapia après chirurgie orthognathique : cas clinique","type":"cases","level":4,"pop":"adulte","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[],"n":1,"effect":"—","theme":"Nerfs crâniens","l1":"Paralysie des nerfs hypoglosse et laryngé récurrent après intubation difficile, traitée par corticoïdes, orthophonie et laser basse énergie en complément : récupération quasi complète en 3 mois.","l2":"Cas rapporté surtout pour le diagnostic et la prévention des lésions nerveuses liées à l'intubation. Le laser n'est qu'un adjuvant parmi d'autres.","l3":{"points":["Électromyographie à J10 : atteinte hypoglosse bilatérale."],"limites":["Cas unique, traitements multiples."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Tapia syndrome after orthognathic surgery: a case report.","journal":"International journal of surgery case reports","journal_abbr":"Int J Surg Case Rep","authors":["Sharifi R","Nomani M","Mousavi R"],"date":"2026-05-26","year":2026,"week":"2026-S22","doi":"10.1097/RC9.0000000000000328","pmcid":"PMC13236253","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/42253675.pdf","cited_by":0,"pub_types":["Case Reports"],"abstract":[{"label":"INTRODUCTION AND IMPORTANCE","text":"Tapia syndrome is a cranial neuropathy. It involves the hypoglossal and recurrent laryngeal nerves. The syndrome may follow airway manipulation or prolonged intubation. We report a case of Tapia syndrome, its presentation, management, and outcome."},{"label":"PRESENTATION","text":"A 45-year-old man with skeletal Class III malocclusion underwent orthognathic surgery. Nasotracheal intubation was difficult and required repeated maneuvers and a second attempt. During extubation, the patient developed laryngospasm and hoarseness, which necessitated re-intubation and 24 hours of mechanical ventilation. After successful re-extubation, he manifested complete tongue immobility and dysarthria. Electromyography performed on postoperative day 10 demonstrated partial right and complete left hypoglossal nerve paralysis. These findings are consistent with Tapia syndrome and correlate with clinical leftward tongue deviation."},{"label":"DISCUSSION","text":"Management included corticosteroid therapy and initiation of speech and language therapy. We added an adjunctive local low-level laser therapy. Serial clinical photographs and examinations documented steady improvement within 3 months."},{"label":"CONCLUSION","text":"Early electrodiagnostic confirmation and multidisciplinary care were associated with near-complete functional recovery by 3 months. The report underscores the importance of careful airway techniques, vigilance for early postoperative bulbar signs, and early rehabilitation to optimize outcomes in iatrogenic cranial nerve injury."}],"keywords":["Tapia syndrome","case report","corticosteroid therapy","cranial nerve XII palsy","hypoglossal nerve paralysis","hypoglossal nerve paralysis/palsy","laryngospasm","orthognathic surgery"]},{"pmid":"41964534","title_fr":"Disparition d'un névrome de Morton après laser haute intensité Nd:YAG 1 064 nm : cas clinique","type":"cases","level":4,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["haute puissance"],"nm":[1064],"n":1,"effect":"favorable","theme":"Autres compressions nerveuses","l1":"Une patiente traitée par laser haute intensité pour un névrome de Morton n'a plus de douleur, et l'IRM à plus de 2 ans montre la disparition du névrome.","l2":"Comparaison rétrospective des IRM avant et plus de deux ans après traitement. Les douleurs en éclair, la brûlure et la sensation de caillou sous le pied ont disparu.\n\nUn seul cas : à confirmer par des séries.","l3":{"points":["Hypothèse : réduction de la fibrose périneurale."],"limites":["Cas unique."],"pratique":"Piste à explorer avant une chirurgie."},"topic":"neuropathie-peripherique","title":"Complete Resolution of Morton's Neuroma Following Nd:YAG 1064 nm Laser Treatment: A Case Report.","journal":"Lasers in surgery and medicine","journal_abbr":"Lasers Surg Med","authors":["Bocian DA","Kohl CA","Thomas WJ"],"date":"2026-04-11","year":2026,"week":"2026-S15","doi":"10.1002/lsm.70132","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Case Reports"],"abstract":[{"label":"OBJECTIVE","text":"The objective of this study was to retrospectively assess for changes in appearance of a Morton's neuroma before and after Nd:YAG 1064 nm high-intensity laser therapy (HILT) using MR Imaging."},{"label":"METHODS","text":"A retrospective review was performed of a patient who underwent MR Imaging for a symptomatic Morton's neuroma before and greater than 2 years after HILT. MR images were reviewed and correlated with the patient's clinical history."},{"label":"RESULTS","text":"Analysis of MR imaging of a Morton's neuroma prior to and following HILT showed complete resolution of the treated Morton's neuroma within the 3rd intermetatarsal space. After HILT, the sharp and burning pain had resolved along with the sensation of a pebble in the ball of her foot."},{"label":"CONCLUSION","text":"Early adoption of Nd:YAG 1064 nm HILT for perineural fibrosis associated with Morton's neuroma may offer a significant reduction of scarring around the common digital nerve resulting in improvement in symptoms and quality of life while allowing patients to remain active during treatment. Further studies of HILT for this pathology are warranted."}],"keywords":["High intensity laser therapy (HILT)","MRI","Morton's neuroma"]},{"pmid":"41873230","title_fr":"Conduits nerveux en collagène imprimés en 3D associés à la PBM : étude pilote chez le rat","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[980],"n":36,"effect":"neutre","theme":"Préclinique","l1":"Après section du sciatique chez le rat, ajouter une PBM à 980 nm à un conduit nerveux imprimé en 3D n'a pas amélioré la régénération ; aucun groupe n'a égalé l'autogreffe.","l2":"36 rats, trois groupes (autogreffe, conduit, conduit + PBM), à 3 et 6 semaines. Les conduits sont biocompatibles et vascularisés.\n\nRésultat négatif utile : les paramètres de lumière restent à optimiser.","l3":{"points":["PBM : 980 nm, 1 W, 30 s, un jour sur deux."],"limites":["Pilote animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"A Combinatorial Strategy for Peripheral Nerve Repair Utilizing 3D-Printed Collagen Nerve Guidance Conduits and Photobiomodulation Therapy: A Pilot Study in a Rat Sciatic Nerve Transection Model.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Fellin CR","Steiner RC","Buchen JT","et al."],"date":"2026-03-24","year":2026,"week":"2026-S13","doi":"10.1177/25785478251414510","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Nerve guidance conduits (NGCs) are a clinically approved option for peripheral nerve repair but remain ineffective compared with autograft \"gold standard\" treatment options. A combinatorial approach to conduit-based peripheral nerve repair could improve repair outcomes. Photobiomodulation therapy (PBMT) has shown potential to enhance axonal regeneration, but its efficacy in combination with NGCs requires further evaluation."},{"label":"OBJECTIVE","text":"This pilot study investigated the therapeutic potential of a novel 3D-printed, collagen-based NGC combined with PBMT for peripheral nerve regeneration in a 10 mm rat sciatic nerve injury model."},{"label":"MATERIALS AND METHODS","text":"A total of 36 male, 3-month-old, Sprague-Dawley rats were used in a pre-clinical rat model of peripheral neurotmesis and randomly assigned to one of three groups (N = 12 each): Autograft (control), NGC-PBMT (experimental), and NGC + PBMT (experimental). All groups were further subdivided (N = 6) by recovery period (3 or 6 weeks). Collagen-based NGCs were fabricated via DLP 3D printing and implanted into rats with 10 mm sciatic nerve transections. PBMT treatment was applied transcutaneously every other day at 980 nm for 30 s at 1 W. Gross examination, immunohistochemistry, and immunofluorescence were used to assess biocompatibility, vascularization, and nerve regeneration at 3- and 6-weeks post-surgery."},{"label":"RESULTS","text":"Gross examination revealed no sign of inflammation or immune rejection, with significant neovascularization observed throughout the NGCs. Immunostaining demonstrated nerve regeneration in all groups, with progressive axonal growth from week 3 to 6 in the NGC-PBMT group. However, neither experimental group achieved regeneration comparable to the autograft control. PBMT did not yield significant improvement in regenerative outcomes under the tested parameters."},{"label":"CONCLUSIONS","text":"Altogether, this study provides encouraging preliminary evidence that these novel, 3D-printed NGCs are biocompatible and promote early nerve regeneration after peripheral neurotmesis. While PBMT did not enhance outcomes in this study, further work is needed to optimize light delivery parameters and improve conduit design for enhanced neuroregeneration."}],"keywords":["3D printing","nerve guidance conduit","peripheral nerve injury","photobiomodulation therapy"]},{"pmid":"41831101","title_fr":"Efficacité de la PBM dans la neuropathie périphérique induite par la chimiothérapie : essai pilote NEUROLIGHT","type":"rct","level":2,"pop":"adulte","ctx":["CIPN"],"aim":"traitement","mode":["laser"],"nm":[],"n":60,"effect":"favorable","theme":"Neuropathie chimio-induite","key":true,"l1":"Chez 60 patients belges atteints de neuropathie chimio-induite, six séances de PBM améliorent le score de neuropathie, la marche et la douleur, surtout à 6 J/cm², sans gain de qualité de vie.","l2":"Essai randomisé comparant deux fluences de PBM : 6 J/cm² (n = 28) et 8 J/cm² (n = 32). Il n'y a pas de groupe sans PBM. Mesures : score total de neuropathie modifié (mTNS), test de marche de 6 minutes, douleur (EN), FACT/GOG-NTX.\n\nLe mTNS et la distance de marche s'améliorent au fil du temps ; la douleur aussi, davantage à 6 J/cm². La qualité de vie liée à la neurotoxicité ne change pas. Faute de bras témoin, ces améliorations peuvent refléter l'évolution naturelle ou un effet placebo.","l3":{"points":["Enregistrement NCT05199389 ; Jessa Hospital (Belgique).","mTNS p = 0,048 ; 6MWT p < 0,001 ; douleur p < 0,001, meilleure à 6 J/cm² (p = 0,034).","FACT/GOG-NTX : pas de différence."],"limites":["Pas de groupe placebo : comparaison de deux doses seulement.","Pilote, effectif modeste."],"pratique":"Signal favorable en faveur d'une fluence modérée (6 J/cm²) ; un essai contre simulation reste nécessaire."},"topic":"neuropathie-peripherique","title":"Evaluating the efficacy of photobiomodulation therapy in the management of chemotherapy-induced peripheral neuropathy: a pilot trial (NEUROLIGHT trial).","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Claes M","Lodewijckx J","Robijns J","et al."],"date":"2026-03-14","year":2026,"week":"2026-S11","doi":"10.1007/s10103-026-04852-1","pmcid":"PMC12988979","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/41831101.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Chemotherapy-induced peripheral neuropathy (CIPN) is a common side effect of chemotherapy that hinders the patient’s health-related quality of life (HRQL). Managing CIPN often requires a chemotherapy dose reduction or premature cessation of treatment. Photobiomodulation (PBM) therapy uses visible or (near)-infrared light to target tissue and stimulate cell repair processes. This trial aimed to evaluate PBM’s efficacy in managing CIPN. A randomised, controlled trial was performed with sixty cancer patients with CIPN at Jessa Hospital (Belgium). Patients underwent six PBM sessions with a fluence of 6 J/cm² (PBM-1, n = 28) or 8 J/cm² (PBM-2, n = 32). The modified Total Neuropathy Score (mTNS) and Six-Minute Walk Test (6MWT) were performed to assess the CIPN severity and mobility. Questionnaires (Numeric Rating Scale, NRS; Functional Assessment of Cancer Therapy/Gynecologic Oncology Group Neurotoxicity, FACT/GOG-NTX) were administered to evaluate the pain, satisfaction, and HRQL. The trial was registered at clinicaltrials.gov on the 6th of January 2022 (NCT05199389). The mTNS and 6MWT improved significantly over time (P = 0.048 and P < 0.001, respectively). No significant differences could be detected for the FACT/GOG-NTX total score, nor its neurotoxicity subscale. The pain scores improved over time (P < 0.001), with better scores in the PBM-1 group (P = 0.034). The NEUROLIGHT trial revealed a significant improvement in CIPN symptoms and mobility. PBM applied with a fluence of 6 J/cm² could be more capable of soothing the pain caused by CIPN. No improvements could be detected in HRQL. Future research is necessary to support these findings."}],"keywords":["Chemotherapy-induced Peripheral Neuropathy","Health-related Quality of Life","Photobiomodulation","Supportive Cancer Care"]},{"pmid":"41807896","title_fr":"La PBM proche infrarouge atténue les troubles sensitifs de la neuropathie au paclitaxel (souris)","type":"preclinical","level":5,"pop":"—","ctx":["CIPN"],"aim":"traitement","mode":["laser"],"nm":[808],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez la souris sous paclitaxel, trois semaines de PBM à 808 nm réduisent l'hypersensibilité au froid et au toucher et restaurent la densité des fibres nerveuses intra-épidermiques.","l2":"Études in vivo et in vitro (cellules N2a, astrocytes humains) : moins de cytokines inflammatoires, moins de stress oxydatif, mitochondries stabilisées, plus d'ATP, moins d'apoptose.","l3":{"points":["Densité de fibres intra-épidermiques restaurée."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Near-infrared photobiomodulation can alleviate chemotherapy-induced peripheral neuropathy-associated sensory abnormalities.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Ren Z","Fan H","Chen Y","et al."],"date":"2026-03-04","year":2026,"week":"2026-S10","doi":"10.1016/j.jphotobiol.2026.113411","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Chemotherapy-induced peripheral neuropathy (CIPN) is a common and serious side effect of paclitaxel-based chemotherapy, with limited therapeutic options that often prove ineffective. Photobiomodulation (PBM), a non-invasive therapeutic approach utilizing near-infrared light, has shown promise in fostering nerve regeneration and modulating inflammatory responses. This study aimed to assess both the therapeutic efficacy and the underlying molecular mechanisms of PBM in a preclinical model of CIPN."},{"label":"METHODS","text":"The effects of 808 nm near-infrared PBM were evaluated in both in vivo and in vitro CIPN models. A murine CIPN model was developed and subjected to three weeks of continuous PBM treatment. Behavioral assessments, intraepidermal nerve fiber (IENF) density analysis, and mitochondrial ultrastructural evaluations were performed in the in vivo experiments. For in vitro investigations, N2a neuroblastoma cells and normal human astrocytes (NHA) were exposed to albumin-bound paclitaxel (nab-paclitaxel), with or without PBM therapy. Cellular assays were conducted to evaluate cell viability, inflammatory cytokine secretion, oxidative stress levels, mitochondrial functionality, and apoptosis."},{"label":"RESULTS","text":"PBM significantly ameliorated mechanical and cold hypersensitivity in CIPN mice, restored IENF density, preserved mitochondrial ultrastructure, and reduced oxidative tissue damage. In addition, PBM enhanced neuronal cell proliferation, reduces the expression of pro-inflammatory cytokines, attenuated oxidative stress, stabilized mitochondrial membrane potential, increased ATP production, and inhibited paclitaxel-induced apoptosis through regulation of the mitochondrial pathway."},{"label":"CONCLUSIONS","text":"Near-infrared PBM effectively mitigates CIPN by promoting neural repair, suppressing neuroinflammation and oxidative stress, and preserving mitochondrial function. These findings highlight PBM as a potential non-pharmacological therapeutic option for CIPN management and suggest that further clinical investigations are warranted."}],"keywords":["Albumin-bound paclitaxel","Chemotherapy-induced peripheral neuropathy","Mitochondrial dysfunction","Oxidative stress","Photobiomodulation"]},{"pmid":"41752213","title_fr":"PBM et laser basse énergie comme stratégies complémentaires du diabète","type":"review","level":5,"pop":"adulte","ctx":["diabète"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue narrative : la PBM soulagerait la douleur neuropathique, améliorerait la cicatrisation et le contrôle glycémique chez le diabétique ; protocoles non standardisés.","l2":"Revue large des complications du diabète traitées par laser : cicatrisation, douleur neuropathique, sensibilité à l'insuline, fonction vasculaire. Mécanismes : mitochondrie, monoxyde d'azote, angiogenèse.\n\nLes auteurs insistent sur le manque de grands essais.","l3":{"points":["Profil de tolérance favorable."],"limites":["Revue narrative."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Photobiomodulation and Low-Level Laser Therapy as Complementary Strategies in Diabetes Treatment.","journal":"International journal of molecular sciences","journal_abbr":"Int J Mol Sci","authors":["Kurhaluk N","Tomin V","Kołodziejska R","et al."],"date":"2026-02-23","year":2026,"week":"2026-S09","doi":"10.3390/ijms27042078","pmcid":"PMC12940873","license":"cc by","oa":true,"pdf":"pdfs/41752213.pdf","cited_by":3,"pub_types":["Review"],"abstract":[{"label":"","text":"Diabetes mellitus is a multifactorial metabolic disorder associated with a number of chronic complications, including neuropathy, impaired wound healing, vascular dysfunction, and metabolic dysregulation. Despite advances in pharmacological treatments and lifestyle interventions, current therapies often fail to prevent or reverse these complications entirely. This narrative review examines the therapeutic potential of laser-based modalities, particularly low-level laser therapy (LLLT) and photobiomodulation therapy (PBMT), as complementary strategies in diabetes management. Analysis of experimental and clinical studies shows that laser therapy can enhance wound healing, alleviate neuropathic pain, improve glycaemic control and insulin sensitivity, modulate inflammatory and oxidative stress pathways, and support vascular function. These effects are primarily mediated through mitochondrial activation, nitric oxide release, angiogenesis, modulation of redox-sensitive transcription factors, and preservation of pancreatic β-cell function. Furthermore, laser therapy exhibits a favourable safety profile with minimal side effects. The review highlights the current challenges, such as the lack of standardised treatment parameters (e.g., wavelength, dosage, and duration) and the limited number of large-scale clinical trials. It emphasises the need for personalised protocols and integration of laser therapy with pharmacological and physiotherapeutic interventions. Continued research and interdisciplinary collaboration are needed to realise the potential of laser therapy as an integral component of comprehensive, evidence-based diabetes care."}],"keywords":["diabetes mellitus","glycaemic control","low-level laser therapy (LLLT)","neuropathic pain","oxidative stress","photobiomodulation therapy (PBMT)","vascular function","wound healing"]},{"pmid":"41682985","title_fr":"PBM et douleurs neuropathiques orofaciales : position de la WALT 2026","type":"guideline","level":1,"pop":"adulte","ctx":["orofaciale"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Recommandations","key":true,"l1":"La WALT recommande la PBM dans le syndrome de la bouche brûlante (preuve de niveau I) et propose un avis d'experts favorable pour la névralgie du trijumeau et la névralgie post-zostérienne (niveau II).","l2":"Position officielle de l'association mondiale de PBM, fondée sur une revue systématique (PRISMA 2020), une évaluation de la qualité (AMSTAR 2, RoB2, ROBINS-I) et un consensus d'experts (cadre HANNA, AGREE II).\n\nRecommandations de pratique pour le syndrome de la bouche brûlante (six essais à faible risque de biais, 204 patients, et une méta-analyse de 557 patients). Avis d'experts pour la névralgie du trijumeau idiopathique et la névralgie post-zostérienne. Preuves insuffisantes pour les névralgies post-traumatiques, glossopharyngiennes et occipitales.","l3":{"points":["Bouche brûlante : niveau de preuve I.","Trijumeau idiopathique et post-zostérienne : niveau II, consensus d'experts.","Aucune recommandation pour les autres névralgies faute de données."],"limites":["Société savante spécialisée en PBM : possible biais d'enthousiasme."],"pratique":"Première recommandation formelle pour les douleurs neuropathiques orofaciales."},"topic":"neuropathie-peripherique","title":"Photobiomodulation Therapy in the Management of Orofacial Neuropathic Pain-WALT Position Paper 2026.","journal":"Journal of clinical medicine","journal_abbr":"J Clin Med","authors":["Hanna R","Chow R","Dalvi S","et al."],"date":"2026-02-06","year":2026,"week":"2026-S06","doi":"10.3390/jcm15031304","pmcid":"PMC12898000","license":"cc by","oa":true,"pdf":"pdfs/41682985.pdf","cited_by":5,"pub_types":["Review"],"abstract":[{"label":"","text":"Background/Objectives: Photobiomodulation (PBM) therapy has shown potential in managing orofacial neuropathic pain (ONP); however, inconsistent PBM dosimetry and methodological variability limit its clinical application. This World Association for Photobiomodulation Therapy (WALT) Position Paper aims to critically appraise current evidence and provide recommendations for Clinical Practice Guidelines (CPG) and Expert Consensus Opinion (ECO) where appropriate. Methods: Evidence evaluation was guided by the HANNA (Holistic Analysis & Novel Normative Actions) Framework, a structured multi-step methodology integrating systematic review, quality appraisal, and expert consensus. A systematic review was conducted in accordance with PRISMA 2020 guidelines. Methodological quality was assessed using validated tools: AMSTAR 2 for systematic reviews, RoB2 for randomized controlled trials (RCTs), and ROBINS-I for non-randomized studies (NRCTs). The AGREE II Reporting Checklist was applied to ensure transparency and rigor in the development of WALT recommendations. The Somerfield Criteria were used to rate the level of evidence (LoE) for each included ONP condition, where deemed appropriate. Results: WALT CPG were established for primary burning mouth syndrome (BMS), supported by robust evidence (LoE I) from 204 patients across six \"Low RoB\" RCTs and NRCTs, and 557 patients included in a \"High-Confidence\" systematic review and meta-analysis of \"low RoB\" RCTs. WALT ECO were developed for idiopathic trigeminal neuralgia (TN) and post-herpetic neuralgia (PHN), both supported by LoE II. Insufficient evidence precluded formal recommendations for post-traumatic trigeminal neuralgia, glossopharyngeal neuralgia, and occipital neuralgia. Conclusions: This Position Paper introduces the HANNA Framework, for the first time, as a robust and transparent methodology for developing WALT recommendations by delivering evidence-based CPG for PBM in the management of neuropathic pain associated with primary BMS, along with ECO for both TN and PHN. These recommendations support PBM as a safe and effective therapeutic approach, and provide a structured roadmap for future research and periodic guidelines updates."}],"keywords":["PBM","glossopharyngeal neuralgia","idiopathic trigeminal neuralgia","level of evidence","neuropathic pain","occipital neuralgia","photobiomodulation","post-herpetic neuralgia","post-traumatic trigeminal neuralgia","primary burning mouth syndrome"]},{"pmid":"41710353","title_fr":"PBM et douleur chronique : revue systématique d'essais randomisés","type":"sr","level":1,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"Quatorze essais randomisés (2015–2025) : la PBM réduit la douleur chronique, surtout dans la fibromyalgie et les neuropathies périphériques, avec peu d'effets indésirables.","l2":"Revue enregistrée (PROSPERO) sur cinq bases. Les populations vont de la fibromyalgie aux neuropathies, aux douleurs orofaciales et musculosquelettiques. La plupart des essais montrent une baisse significative de la douleur ; certains, des gains de fonction et de qualité de vie.\n\nL'hétérogénéité des paramètres empêche toute standardisation.","l3":{"points":["14 ECR, comparateurs placebo, simulation ou soins usuels."],"limites":["Pas de méta-analyse ; indications mélangées."],"pratique":"La neuropathie fait partie des indications de douleur chronique les mieux soutenues."},"topic":"neuropathie-peripherique","title":"Photobiomodulation in chronic pain: a systematic review of randomized clinical trials.","journal":"Frontiers in integrative neuroscience","journal_abbr":"Front Integr Neurosci","authors":["Ferreira LMA","Oliveira ABC","Mendes JJB","et al."],"date":"2026-02-03","year":2026,"week":"2026-S06","doi":"10.3389/fnint.2026.1717372","pmcid":"PMC12909510","license":"cc by","oa":true,"pdf":"pdfs/41710353.pdf","cited_by":1,"pub_types":["Systematic Review"],"abstract":[{"label":"INTRODUCTION","text":"Photobiomodulation (PBM) stands out as a promising therapeutic alternative for the management of chronic pain, but there is still controversy regarding its efficacy and safety, given the diversity of protocols and populations evaluated."},{"label":"OBJECTIVES","text":"To critically review the available literature on the use of PBM in adults with chronic pain conditions, synthesizing the evidence on analgesic and functional effects, impact on quality of life, and safety profile. Methods: A systematic search was conducted in PubMed, Embase, Scopus, LILACS, and MEDLINE, including articles published between September 2015 and September 2025. Randomized clinical trials that compared PBM protocols to placebo, sham, or conventional care were selected. The outcomes investigated included pain intensity (primary), function, quality of life, and occurrence of adverse events (secondary)."},{"label":"RESULTS","text":"Fourteen studies were included, covering populations with fibromyalgia, peripheral neuropathies, orofacial pain, and musculoskeletal pain. Most trials demonstrated significant pain reduction with PBM, particularly in fibromyalgia and neuropathy. In some studies, functional gains and improved quality of life were observed. The incidence of adverse events was low, reinforcing the method's safety, although the heterogeneity of technical parameters compromises the standardization of results."},{"label":"CONCLUSION","text":"PBM has analgesic potential and a safe profile for managing chronic pain, especially in cases difficult to control with conventional therapies. However, the variability of clinical parameters and limited follow-up still hinder more comprehensive recommendations. Additional multicenter studies with standardized protocols are needed to consolidate clinical guidelines."},{"label":"SYSTEMATIC REVIEW REGISTRATION","text":"https://www.crd.york.ac.uk/PROSPERO/view/CRD420251140711, Identifier: CRD420251140711."}],"keywords":["chronic pain","efficacy","photobiomodulation","randomized controlled trial","safety","systematic review"]},{"pmid":"41320698","title_fr":"Laser basse puissance et ultrasons basse fréquence contre la douleur de la polyneuropathie diabétique : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[808,905],"n":55,"effect":"mitigé","theme":"Neuropathie diabétique","l1":"Chez 55 diabétiques, le laser (808/905 nm) améliore la qualité de vie liée à la neuropathie plus que les témoins, mais pas significativement le score de symptômes.","l2":"Trois groupes (laser n = 18, ultrasons n = 15, témoins n = 22), trois séances par semaine pendant quatre semaines à 6 J/cm², en plus des soins standards.\n\nLe score MNSI baisse dans tous les groupes sans différence (p = 0,292). Le laser améliore davantage le score « problèmes » du QOL-DN (p = 0,006 contre témoins). Les auteurs jugent l'utilité clinique incertaine.","l3":{"points":["Déséquilibre de départ sur le MNSI (p = 0,001)."],"limites":["Groupes déséquilibrés, petits effectifs."],"pratique":"Effet modeste ; ne pas promettre une amélioration neurologique."},"topic":"neuropathie-peripherique","title":"Effectiveness of low-power laser therapy and low-frequency ultrasound in reducing pain in patients with diabetic polyneuropathy: A randomized controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Almasi MH","Mosadeghi N","Safarian A","et al."],"date":"2025-11-30","year":2025,"week":"2025-S48","doi":"10.1007/s10103-025-04720-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"This study aimed to compare the efficacy of low-power laser therapy (LPLT) and low-frequency ultrasound (LFU) in reducing pain and improving quality of life in patients with diabetic polyneuropathy (DPN). A randomized controlled trial was conducted involving 55 patients with DPN, randomly assigned to three groups: LPLT (n = 18), LFU (n = 15), and control (n = 22). The LPLT group received treatments three times weekly for four weeks at 6 J/cm² using 808 nm and 905 nm wavelengths. The LFU group received treatments three times weekly for four weeks at 1 MHz, 0.5 W/cm², and 20% duty cycle. All interventions were administered alongside standard medical care. Baseline and post-intervention assessments included the Michigan Neuropathy Screening Instrument (MNSI) and Quality of Life in Diabetic Neuropathy (QOL-DN) measures. At baseline, significant differences were observed in patient-reported MNSI scores (p = 0.001), with the LPLT group reporting the highest scores. Post-intervention, all groups showed reductions in MNSI scores, but between-group differences were not significant (p = 0.292). The LPLT group exhibited the largest mean reduction (-2.39) in patient-reported MNSI scores, though the change only approached significance (p = 0.057). For QOL-DN, the LPLT group showed the greatest improvement in symptom scores (Mean=-2.55, p = 0.023) and problem scores (Mean=-7.05, p < 0.001). ANCOVA confirmed a significant group effect for QOL-DN problem scores (p = 0.007), with the LPLT group showing significantly greater improvement than controls (p = 0.006). LPLT may have potential for improving quality of life and neuropathy symptoms in DPN patients, but the limited between-group differences indicate that its clinical utility remains uncertain. Larger, multicenter trials with longer follow-up are needed to confirm these preliminary findings and establish clinical relevance."}],"keywords":["Diabetic polyneuropathy","Low-Frequency ultrasound","Low-Power laser therapy","Pain management","Quality of life"]},{"pmid":"41302361","title_fr":"Exercice et kinésithérapie dans la neuropathie chimio-induite : revue systématique","type":"sr","level":1,"pop":"adulte","ctx":["CIPN"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Neuropathie chimio-induite","l1":"26 essais randomisés : l'exercice et les techniques de kinésithérapie, dont la PBM, améliorent symptômes, équilibre, force et qualité de vie dans la neuropathie chimio-induite.","l2":"Revue PRISMA (jusqu'en mai 2025) ; 19 essais d'exercice et 7 de modalités physiques (thérapie manuelle, PBM, Scrambler, ultrasons, électrostimulation). Observance de 70 à 95 %, aucun effet grave.\n\nLa PBM n'est qu'une des modalités étudiées et le résumé ne donne pas d'effet propre.","l3":{"points":["Qualité évaluée par l'échelle PEDro ; pas de méta-analyse."],"limites":["Effet spécifique de la PBM non isolé."],"pratique":"Associer la PBM à l'exercice plutôt que la proposer seule."},"topic":"neuropathie-peripherique","title":"Effectiveness of Exercise and Physiotherapy in Chemotherapy-Induced Peripheral Neuropathy: A Systematic Review.","journal":"Healthcare (Basel, Switzerland)","journal_abbr":"Healthcare (Basel)","authors":["Tamayo Fajardo JA","León Parejo F"],"date":"2025-11-19","year":2025,"week":"2025-S47","doi":"10.3390/healthcare13222973","pmcid":"PMC12652784","license":"cc by","oa":true,"pdf":"pdfs/41302361.pdf","cited_by":2,"pub_types":["Review"],"abstract":[{"label":"","text":"Background: Chemotherapy-induced peripheral neuropathy (CIPN) is a common and disabling adverse effect of cancer treatment, affecting up to 65% of patients. It reduces quality of life, increases fall risk, and often leads to chemotherapy dose reduction or discontinuation. Because pharmacological management provides limited relief, non-pharmacological strategies such as exercise and physiotherapy have become increasingly relevant. Methods: A systematic review following the PRISMA 2020 guidelines was conducted to identify randomised controlled trials (RCTs) evaluating exercise and physiotherapy for the prevention or treatment of CIPN. PubMed, Scopus, Web of Science, and Cochrane Library were searched up to May 2025. Methodological quality was assessed with the PEDro scale, and due to heterogeneity, a narrative synthesis was performed. Outcomes included neuropathic symptoms, pain, motor and sensory function, balance, muscle strength, and quality of life. Results: Twenty-six RCTs published between 2017 and 2025 were included. Nineteen assessed exercise-based interventions (aerobic, resistance, sensorimotor, balance, yoga, or multimodal), and seven examined physiotherapy modalities (manual therapy, photobiomodulation, Scrambler therapy, ultrasound, or electrical stimulation). Both approaches improved sensory and motor symptoms, balance, muscle strength, and quality of life. Adherence ranged from 70% to 95%, and no serious adverse events were reported. However, variability in intervention design and outcome measures precluded meta-analysis. Conclusions: Exercise and physiotherapy are safe, feasible, and effective non-pharmacological strategies for managing CIPN. However, heterogeneity in intervention design highlights the need for high-quality RCTs to establish optimal protocols and standardised clinical guidelines."}],"keywords":["cancer rehabilitation","chemotherapy-induced peripheral neuropathy","exercise","exercise therapy","physiotherapy","quality of life"]},{"pmid":"41114857","title_fr":"Synergie entre natation et PBM dans un modèle de douleur neuropathique (rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[904],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat avec lésion du sciatique, PBM (904 nm) et natation soulagent chacune la douleur ; leur association fait mieux et protège davantage le muscle.","l2":"Trois semaines de traitement, tests de Von Frey et de Hargreaves, histologie du gastrocnémien. Argument pour associer PBM et exercice, comme le suggère la revue sur la neuropathie chimio-induite.","l3":{"points":["6 J/cm² ; natation 10 à 30 min, 5 jours sur 7."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Therapeutic synergy between swimming and photobiomodulation in a rat model of neuropathic pain.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Araujo LC","Silva DPFB","Rocha-Braga LC","et al."],"date":"2025-10-20","year":2025,"week":"2025-S43","doi":"10.1007/s10103-025-04705-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"","text":"This study aimed to evaluate the efficacy of non-pharmacological interventions, photobiomodulation therapy (PBMT) and swimming (SW), administered individually or in combination, in alleviating neuropathic pain, enhancing motor function, and preserving skeletal muscle morphology in a rat model of chronic constriction injury (CCI) of the sciatic nerve. Male Wistar rats (n = 8 per group) with chronic constriction injury (CCI)-induced neuropathic pain were randomly assigned to receive photobiomodulation therapy (PBMT), swimming exercise (SW), a combination of both therapies, or no treatment (control). The treatment protocol lasted for 3 weeks, with PBMT applied at a dose of 6 J/cm² (wavelength 904 nm) delivered to the affected limb, and swimming sessions conducted 10-30 min per day, 5 days per week. Behavioral assessments, including mechanical hyperalgesia (Von Frey test), thermal hyperalgesia (Hargreaves test), cold allodynia, and motor function (incapacitance test) were performed weekly to evaluate nociceptive thresholds and functional recovery. Histological analyses of the gastrocnemius muscle were conducted post-treatment to assess morphometric changes, including myofiber integrity, central nucleation, and collagen distribution using PicroSirius Red staining. Both PBMT and SW significantly reduced mechanical and thermal hypersensitivity and improved motor performance compared to untreated CCI rats (p < 0.05). The combination therapy demonstrated superior analgesic and functional outcomes relative to monotherapies (p < 0.01). Histological analysis revealed a reduction in centrally located nuclei and increased collagen expression in treated groups, with the combined intervention showing the most pronounced improvements. PBMT and swimming exercise independently alleviate neuropathic pain and mitigate muscle degeneration following sciatic nerve injury. When combined, these therapies produce additive or synergistic effects, supporting the implementation of multimodal, non-pharmacologic strategies for managing neuropathic pain and promoting functional recovery."}],"keywords":["CCI","Muscle","Neuropathic Pain","Pain","Photobiomodulation","Swimming"]},{"pmid":"41091232","title_fr":"Paramètres dosimétriques et résultats cliniques de la PBM dans la neuropathie diabétique : revue","type":"review","level":3,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":[],"nm":[630,670,808,904],"n":null,"effect":"favorable","theme":"Dosimétrie","key":true,"l1":"23 études (2015–2025) : les meilleurs résultats sont obtenus à 630–670 nm ou 808–904 nm, 3 à 10 J/cm², 45 à 100 mW et au moins 12 séances.","l2":"Revue de six bases (dont LILACS et SciELO), études cliniques et précliniques. Elle fournit une fenêtre de paramètres utilisable pour un protocole.","l3":{"points":["Fluence 3–10 J/cm² ; puissance 45–100 mW ; ≥ 12 séances."],"limites":["Revue non quantitative."],"pratique":"Fenêtre de paramètres pratique pour la neuropathie diabétique."},"topic":"neuropathie-peripherique","title":"Dosimetric parameters and clinical outcomes of photobiomodulation in diabetic neuropathy: a concise review.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Souza V","da Palma Cruz M","Chaves Bittencourt C","et al."],"date":"2025-10-15","year":2025,"week":"2025-S42","doi":"10.1007/s10103-025-04701-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Review"],"abstract":[{"label":"","text":"Diabetes mellitus (DM) is a multifactorial metabolic disorder characterized by chronic hyperglycemia, insulin resistance, and systemic inflammation. Diabetic neuropathy (DN) is a prevalent and debilitating complication of type 2 diabetes mellitus (T2D), associated with sensory impairment, persistent pain, and increased risk of lower limb amputations. Photobiomodulation (PBM) has been investigated as an adjunctive treatment due to its effects on cellular repair mechanisms, pain modulation, and wound healing.This review aims to synthesize evidence from clinical and preclinical studies published between 2015 and 2025, focusing on dosimetric parameters used in PBM for DN and their association with clinical outcomes.The search was conducted in the LILACS, SciELO, EMBASE, MEDLINE, PubMed e Cochrane Library, covering publications from 2015 to 2025. A total of 23 studies met the inclusion criteria. This review provides comprehensive evidence supporting PBM as a promising, safe and effective adjunctive therapy for diabetic neuropathy. The most consistent therapeutic effects were observed with wavelengths ((630-670 nm/808-904 nm), fluences of 3-10 J/cm², output power between 45 and 100 mW, and treatment protocols comprising at least 12 sessions. Despite the favorable therapeutic outcomes, the absence of standardized dosimetry among the studies remains a major challenge. Therefore, further research is needed to define optimized and reproducible therapeutic protocols."}],"keywords":["Allodynia","Diabetic neuropathy","Low-level laser","Photobiomodulation","Type 2 diabetes"]},{"pmid":"41093021","title_fr":"Laser 10,6 μm (moxibustion laser) dans la neuropathie diabétique : essai randomisé en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[10600],"n":68,"effect":"favorable","theme":"Neuropathie diabétique","l1":"Chez 68 diabétiques, un laser infrarouge lointain à 10,6 μm appliqué sur des points d'acupuncture améliore les symptômes à 4 semaines et la qualité de vie jusqu'à 12 semaines, sans changer la conduction nerveuse.","l2":"Essai chinois contre simulation, 12 séances en 4 semaines ; 58 patients ont terminé. Les deux groupes s'améliorent, mais le groupe laser a un score MNSI plus bas à la 4e semaine et une meilleure qualité de vie aux semaines 4, 8 et 12.\n\nIl s'agit d'une technique différente de la PBM classique (CO₂, chaleur, points d'acupuncture).","l3":{"points":["Enregistrement ChiCTR2000029329.","Vitesse de conduction : pas de différence à S4."],"limites":["Technique proche de la moxibustion : transposabilité limitée à la PBM rouge et infrarouge proche."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Effectiveness of 10.6-μm laser therapy for diabetic peripheral neuropathy: A double-blind, randomized controlled trial.","journal":"Complementary therapies in medicine","journal_abbr":"Complement Ther Med","authors":["Yin Y","Huang Z","Li Y","et al."],"date":"2025-10-13","year":2025,"week":"2025-S42","doi":"10.1016/j.ctim.2025.103259","pmcid":null,"license":"cc by-nc-nd","oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVE","text":"To observe the clinical effects of 10.6-μm laser moxibustion (LM) on diabetic peripheral neuropathy (DPN) and quality of life in patients."},{"label":"METHODS","text":"Sixty-eight patients with DPN were randomly assigned to two groups in a 1:1 ratio and received LM or sham LM 3 times/week for a total of 12 treatments. Outcome parameters were assessed at baseline, at Weeks 2 and 4 of treatment, and at 4 and 8 weeks post-treatment (Weeks 8 and 12) using Michigan Neuropathy Screening Instrument (MNSI) and Diabetes-Specific Quality of Life (DSQL) scores, nerve conduction velocity (NCV), and blood rheology parameters."},{"label":"RESULTS","text":"Most (58/68) patients completed the trial. MNSI scores were significantly lower at every time point (P < 0.01), and DSQL scores were significantly lower at Weeks 4, 8, and 12 (P < 0.001), compared with baseline in both groups. The LM group had lower MNSI scores at Week 4 (P < 0.05), and lower DSQL scores at Weeks 4, 8, and 12 (P < 0.05) compared with the sham LM group. At Week 4, there was no significant between-group difference in NCV (P > 0.05). Post-treatment, there were no significant differences in blood rheology parameters compared with baseline within each group (P > 0.05). Whole blood high-shear reductive viscosity and red blood cell rigidity index were significantly lower in the LM group than in the sham LM group (P < 0.01). No serious adverse events were recorded."},{"label":"CONCLUSION","text":"Treatment with 10.6-μm LM improved clinical symptoms and quality of life in patients with DPN."},{"label":"CLINICAL TRIAL REGISTRATION","text":"Chinese Clinical Trial Registry, ChiCTR2000029329. Registered 25 January 2020, https://www.chictr.org.cn/showproj.html?proj=48490."}],"keywords":["Clinical trial","Diabetic peripheral neuropathy","Laser","Moxibustion"]},{"pmid":"41146696","title_fr":"Paresthésie et dysesthésie après traitement endodontique d'une molaire : cas clinique","type":"cases","level":4,"pop":"adulte","ctx":["lésion nerveuse","orofaciale"],"aim":"traitement","mode":["laser"],"nm":[],"n":1,"effect":"—","theme":"Neuropathies orofaciales","l1":"Lésion du nerf alvéolaire inférieur par matériau d'obturation : retrait chirurgical, corticoïdes, vitamine B et laser basse énergie en appoint, avec récupération complète en un mois.","l2":"Le cas illustre surtout l'importance du diagnostic radiologique précoce. Le rôle propre du laser n'est pas isolable.","l3":{"points":["Suivi à 12 mois sans symptôme."],"limites":["Cas unique, traitements multiples."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Paresthesia and Dysesthesia after Root Canal Therapy of a Mandibular Molar: Diagnosis and Management in a Clinical Case Report.","journal":"Iranian endodontic journal","journal_abbr":"Iran Endod J","authors":["Fazlyab M","Hassani A","Kamali S"],"date":"2025-10-07","year":2025,"week":"2025-S41","doi":"10.22037/iej.v20i1.49800","pmcid":"PMC12554236","license":"cc by-nc-sa","oa":true,"pdf":"pdfs/41146696.pdf","cited_by":0,"pub_types":["Case Reports"],"abstract":[{"label":"","text":"Inferior alveolar nerve (IAN) injury is a rare but serious complication of root canal treatment (RCT), typically caused by mechanical over-instrumentation, chemical irritation from extruded sealers, or thermal damage. We report the case of a 42-year-old woman who developed persistent burning pain, numbness, and dysesthesia of the right lower lip and gingiva after RCT of the right mandibular second molar. Initial management by a general dentist involved retreatment and calcium hydroxide medicament; however, early CBCT was misinterpreted, and referral was delayed. High-quality CBCT and clinical testing later revealed obturation material within the IAN canal and a horizontal fracture of the distal root. Endodontic retreatment, followed by maxillofacial microsurgery for removal of extruded gutta-percha/sealer, combined with neuroprotective therapy (dexamethasone, vitamin B, and adjunctive low-level laser therapy). The patient achieved complete resolution of pain and sensory disturbances within one month, and remained asymptomatic with radiographic periapical healing at 12-month follow-up. Comprehensive preoperative imaging, cautious canal instrumentation, independent CBCT interpretation by the endodontist, and timely specialist referral are essential to minimize the risk of IAN injury. Even with delayed intervention, targeted microsurgical removal of extruded material can result in favorable neurological recovery."}],"keywords":["Dysesthesia","Extrusion","Mandibular Second Molar","Neuropathy","Neurotoxicity","Paresthesia","Root Canal Treatment","Sealer Extrusion"]},{"pmid":"41316574","title_fr":"Mobilisation neurale et laser haute intensité dans la neuropathie diabétique chronique : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":16,"effect":"—","theme":"Neuropathie diabétique","l1":"Protocole indien d'étude mixte (quantitative et qualitative) en cross-over sur 16 patients : mobilisation neurale contre laser haute intensité.","l2":"Mesures : douleur (S-LANSS), équilibre, pressions plantaires, conduction nerveuse, réponse cutanée sympathique, qualité de vie, entretiens. Pas encore de résultats.","l3":{"points":["CTRI/2023/12/060929."],"limites":["Protocole."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"A study protocol on experiences and outcomes of neural mobilization and high intensity laser therapy in individuals with chronic sensorimotor diabetic peripheral neuropathy.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Sharma R","Goyal M"],"date":"2025-08-22","year":2025,"week":"2025-S34","doi":"10.1016/j.jbmt.2025.08.008","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Clinical Trial Protocol"],"abstract":[{"label":"BACKGROUND","text":"Neural mobilization and Laser therapy are proven to be effective in improving functional impairments in Chronic Sensorimotor Diabetic Peripheral Neuropathy (CSMDPN). Still, there is hardly any qualitative study that has investigated the experiences and outcomes of patients with CSMDPN regarding Neural mobilization and High Intensity Laser therapy as therapeutic interventions. So, this study aims to estimate and explore the experiences and outcomes of Neural mobilization and High Intensity Laser therapy in patients with Chronic Sensorimotor Diabetic Peripheral Neuropathy."},{"label":"METHODOLOGY","text":"A mixed-method approach will be conducted on 16 patients with CSMDPN. Group-1 and group-2 will undergo Neural mobilization of the tibial and common peroneal nerve, and High Intensity Laser therapy for 4 times/week for 3 weeks and after a washout period of 1 week, intervention will be reversed in both groups. Pre-post assessment will be taken after completion of each intervention with quantitative outcome measures S-LANSS for neuropathic pain, static balance & proprioception by Pedalo-Sensamove Balance Test Pro with Miniboard, Plantar pressure distribution by using Harris mat, Nerve Conduction Velocity of tibial and common peroneal nerve, Sympathetic Skin Response (SSR), and NeuroQoL-H questionnaire for quality of life. After the completion of each intervention depth face to face, semi-structured interviews will be conducted to explore the experiences of patients having CSMDPN about Neural Mobilization and High Intensity Laser therapy."},{"label":"DISCUSSION","text":"The results achieved after the completion of this study may provide both quantitative and qualitative information which helps in collecting broad information about the facilitators and barriers of interventions for the benefit of CSMDPN patients for future implementation in clinical practice. CTRI/2023/12/060929 [Registered on: December 29, 2023]."}],"keywords":["Diabetic peripheral neuropathy","Laser therapy","Neural mobilization","Neuropathic pain","Proprioception"]},{"pmid":"40663207","title_fr":"Douleur neuropathique de la lèpre : kinésithérapie associée à la PBM, essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["autres"],"aim":"traitement","mode":[],"nm":[],"n":30,"effect":"mitigé","theme":"Autres neuropathies","l1":"Chez 30 patients atteints de lèpre, la PBM ajoutée à la kinésithérapie améliore certaines limitations fonctionnelles, mais pas plus la douleur que la kinésithérapie seule.","l2":"Essai brésilien en double aveugle. La douleur (EVA) baisse dans les deux groupes sans différence. Le groupe PBM montre des gains sur certains nerfs (médian, tibial, fibulaire) et sur la limitation d'activité (SALSA).","l3":{"points":["SF-36 : amélioration de la douleur dans les deux groupes."],"limites":["Petit effectif, critères multiples."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Treatment of neuropathic pain in leprosy patients with a physiotherapeutic protocol combined with photobiomodulation.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Bonazza DSS","Duarte VMS","Lima TDR","et al."],"date":"2025-07-15","year":2025,"week":"2025-S29","doi":"10.1007/s10103-025-04509-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"UNLABELLED","text":"Leprosy, when diagnosed late, often leads to persistent complications, including neuropathic pain due to Mycobacterium leprae infection. This study aimed to apply a physiotherapeutic protocol combined with photobiomodulation as a non-pharmacological resource to reduce neuropathic pain and maintain functional capacity in leprosy patients."},{"label":"METHODS","text":"A double-blind randomized clinical trial was conducted with 30 leprosy patients. Patients were randomly divided into two groups: physiotherapeutic protocol (PPG) and physiotherapeutic protocol combined with photobiomodulation (PPBMG). They were analyzed for simplified neurological assessment (SNA), pain scale (VAS), screening of activity limitation and safety awareness (SALSA), participation scale, and quality of life survey (SF-36)."},{"label":"RESULTS","text":"In the SALSA, a reduction in the number of patients with severe limitation was observed in PPBMG (effect size, 0.24). In participation scale, there was an increase in the number of patients without restrictions in PPBMG. Regarding VAS, there was improvement in both groups (PPG, P = 0.0061; PPBMG, P = 0.041), with no difference between them. In relation to neurological evaluation by nerve palpation, there was improvement in the ulnar nerve condition (P = 0.0244) in PPG group, and in the fibular nerve (P = 0.0425) in PPBMG group. In the functional assessment, PPBMG patients showed statistical differences with improvement in the median (P = 0.0281) and tibial (P = 0.0267) nerves. In the SF-36, there was an increase in the domains of physical limitations (PPG, P = 0.0273; and PPBMG, P = 0.0078) and pain (PPG, P = 0.0156; and PPBMG, P = 0.0020; effect size, 0.34)."},{"label":"CONCLUSION","text":"This study provides relevant evidence for the efficacy of PPBMG in treating neuropathic pain in leprosy patients."}],"keywords":["Functional capacity","Leprosy","Low-level laser therapy","Neuropathic pain","Physiotherapy"]},{"pmid":"40523998","title_fr":"PBM dans les lésions médullaires incomplètes et les lésions nerveuses périphériques : revue systématique d'essais randomisés","type":"sr","level":1,"pop":"adulte","ctx":["lésion nerveuse","compression"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Synthèse des preuves","l1":"Dix-neuf essais, dont 14 dans le canal carpien : tendance à l'amélioration de la force, de la sensibilité et de la douleur, mais paramètres trop hétérogènes pour conclure fermement.","l2":"Revue (2012–2024) excluant les neuropathies diabétiques et chimio-induites. Un essai porte sur la compression ulnaire, un sur le plexus brachial, un sur la radiculopathie lombaire, deux sur la moelle épinière.","l3":{"points":["Longueurs d'onde 620–1 400 nm."],"limites":["Petits effectifs, suivis courts."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Photobiomodulation treatment in incomplete spinal cord injuries or peripheral nerve injuries: a comprehensive systematic review of randomized clinical trials.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Weimer GH","Kolling da Rocha CF"],"date":"2025-06-16","year":2025,"week":"2025-S25","doi":"10.1007/s10103-025-04541-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"The objective of this systematic review was to identify if photobiomodulation therapy improves motor and/or sensory outcomes in patients with incomplete spinal cord injuries (SCI) or peripheral nerve injuries (PNI). Searches in Pubmed, Embase, Scopus and Web of Science databases were conducted with publication date limit from 01/01/2012 to 05/01/2024. Inclusion criteria: randomized clinical trials evaluating photobiomodulation therapy in incomplete spinal cord injuries or peripheral nerve injuries; wavelengths between 620 nm and 1400 nm. Exclusion criteria: lack of control or comparator group; studies in patients with complete SCI or other pathologies as diabetic or chemotherapy-induced neuropathies, rheumatic diseases, fibromyalgia, complex regional pain syndrome; studies on cranial nerves were excluded. nineteen studies were included in this review: fourteen studies assessed effects of PBM in carpal tunnel syndrome, one in ulnar nerve compression, one in brachial plexus injury, one in lumbar radiculopathy and two articles in incomplete spinal cord injuries. There is great heterogeneity of reported device configuration and irradiation parameters that made data synthesis difficult. Despite small samples and duration of follow up, there is evidence of an inclination toward improvement in strength, sensitivity, and pain in patients undergoing PBM therapy for SCI and PNI."}],"keywords":[]},{"pmid":"40315975","title_fr":"Traitements conservateurs du canal carpien : revue systématique et méta-analyse en réseau","type":"ma","level":1,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":3323,"effect":"favorable","theme":"Canal carpien","key":true,"l1":"49 essais (3 323 patients) : thérapie manuelle et injections de glucosé arrivent en tête dans le canal carpien ; le laser basse énergie est efficace contre témoin (DMS −1,45).","l2":"Méta-analyse en réseau de 11 traitements conservateurs (jusqu'en avril 2024). Classement pour la douleur à court et moyen terme : thérapie manuelle (SUCRA 87,6 % et 99,3 %), puis glucosé 5 % et PRP.\n\nLe laser basse énergie (DMS −1,45 ; IC95 % −2,16 à −0,74) et les ondes de choc (DMS −1,03) sont significativement supérieurs au contrôle, sans figurer en tête.","l3":{"points":["49 ECR, 3 323 participants, 6 bases dont CNKI."],"limites":["Hétérogénéité des comparateurs."],"pratique":"Le laser est une option efficace mais pas prioritaire dans le canal carpien ; l'associer à la thérapie manuelle."},"topic":"neuropathie-peripherique","title":"Conservative Treatments of Carpal Tunnel Syndrome: A Systematic Review and Network Meta-analysis.","journal":"Archives of physical medicine and rehabilitation","journal_abbr":"Arch Phys Med Rehabil","authors":["Chen Y","Han B","Zhang X","et al."],"date":"2025-04-30","year":2025,"week":"2025-S18","doi":"10.1016/j.apmr.2025.04.002","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Systematic Review","Network Meta-Analysis","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"OBJECTIVE","text":"To evaluate the comparative efficacy of various conservative treatments for carpal tunnel syndrome (CTS), including manual therapy (MT), local steroid injections, platelet-rich plasma (PRP) injections, extracorporeal shock wave therapy, and low-level laser therapy, through a comprehensive network meta-analysis."},{"label":"DATA SOURCES","text":"PubMed, Web of Science, Cochrane Library, Embase, SPORTDiscus, and China National Knowledge Infrastructure databases were searched to identify published studies until April 2024."},{"label":"STUDY SELECTION","text":"Randomized controlled trials comparing the efficacy of conservative CTS treatments in individuals with CTS were included."},{"label":"DATA EXTRACTION","text":"Data from the included articles were extracted independently by 2 researchers, with any disagreements resolved through consultation with a third author. The extracted data included the first author's name, country/region, publication year, sample size, participants' age, disease severity, symptom duration, intervention parameters, follow-up period, and reported outcomes."},{"label":"DATA SYNTHESIS","text":"A total of 49 randomized controlled trials involving 11 conservative treatments and 3323 participants were included. The network meta-analysis showed that MT demonstrated the highest efficacy in both short-term and medium-term pain relief with surface under the cumulative ranking curve values of 87.6% and 99.3%, respectively. Dextrose 5% in water and PRP were closely followed in terms of efficacy. Compared to control groups, low-level laser therapy (standardized mean difference=-1.45; 95% CI, -2.16 to -0.74) and extracorporeal shock wave therapy (standardized mean difference=-1.03; 95% CI, -1.86 to -0.20) also showed significant benefits."},{"label":"CONCLUSIONS","text":"This study provides robust evidence that MT and dextrose 5% in water injections are the most effective conservative treatments for CTS which offer valuable insights for clinical decision-making. Further research is needed to assess the long-term efficacy and cost-effectiveness of these interventions."}],"keywords":["Carpal tunnel syndrome","Conservative treatments","Network meta-analysis","Pain","Rehabilitation"]},{"pmid":"40253006","title_fr":"Consensus fondé sur les preuves pour l'usage clinique de la PBM (JAAD)","type":"guideline","level":1,"pop":"adulte","ctx":["autres"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Recommandations","key":true,"l1":"Un panel international de 21 experts (méthode Delphi) conclut que la PBM est sûre chez l'adulte et efficace dans la neuropathie périphérique, l'alopécie androgénétique, les ulcères et la radiodermite aiguë.","l2":"Recommandation de pratique publiée dans le Journal of the American Academy of Dermatology, fondée sur une revue systématique (Embase, MEDLINE, juin 2022), deux tours de Delphi et deux réunions de consensus.\n\nLa lumière rouge n'induit pas de lésions de l'ADN. La neuropathie périphérique fait partie des indications retenues comme efficaces.","l3":{"points":["21 experts, consensus unanime."],"limites":["Recherche bibliographique de 2022.","Détail des niveaux de preuve par indication dans le texte intégral."],"pratique":"Référence de consensus pour justifier la PBM dans la neuropathie périphérique."},"topic":"neuropathie-peripherique","title":"Evidence-based consensus on the clinical application of photobiomodulation.","journal":"Journal of the American Academy of Dermatology","journal_abbr":"J Am Acad Dermatol","authors":["Maghfour J","Mineroff J","Ozog DM","et al."],"date":"2025-04-17","year":2025,"week":"2025-S16","doi":"10.1016/j.jaad.2025.04.031","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":18,"pub_types":["Systematic Review","Consensus Statement"],"abstract":[{"label":"BACKGROUND","text":"There is a lack of evidence-based consensus to assist clinicians in using photobiomodulation (PBM)."},{"label":"OBJECTIVE","text":"To create a consensus on the safe and effective use of PBM."},{"label":"METHODS","text":"A systematic literature review of Embase and MEDLINE was conducted in June 2022 to identify publications reporting research on PBM. An international multidisciplinary panel was convened to draft recommendations informed by the systematic search; they were refined through 2 rounds of Delphi survey, 2 consensus meetings, and iterative review by all panelists until unanimous consensus was achieved."},{"label":"RESULTS","text":"A multidisciplinary panel of experts (n = 21) was assembled based on publication history. The key findings that informed the consensus developed by the expert panel were as follows: PBM is a safe treatment modality for adult patients and red light PBM does not induce DNA damage. PBM is an effective treatment option for peripheral neuropathy, androgenic alopecia, wound ulcers due to multiple etiologies, decubitus ulcers, pain attributed to diabetic foot ulcers, and acute radiation dermatitis."},{"label":"CONCLUSION","text":"The systematic literature search and structured Delphi consensus approach culminated in an evidence-based clinical practice guideline for safe and effective use of PBM in medical and aesthetic applications. Future research will further bolster our understanding of this evolving noninvasive technique."}],"keywords":["LLLT","PBM","acute radiation dermatitis","androgenic alopecia","cognition","cytochrome c oxidase","decubitus ulcers","low-level light therapy","musculoskeletal","near-infrared light"]},{"pmid":"40186772","title_fr":"PBM, symptômes sensitifs, équilibre et vitesse de marche dans la neuropathie chimio-induite","type":"nrct","level":4,"pop":"adulte","ctx":["CIPN"],"aim":"traitement","mode":["LED","laser"],"nm":[630,850],"n":47,"effect":"favorable","theme":"Neuropathie chimio-induite","key":true,"l1":"Chez 47 patients avec neuropathie chimio-induite des membres inférieurs, quatre séances de PBM (630/850 nm) sur le trajet nerveux améliorent les symptômes sensitifs, l'équilibre et la vitesse de marche.","l2":"Étude prospective brésilienne sans groupe témoin : deux séances par semaine pendant deux semaines. Le DN-4 (p < 0,0001) et le FANPIQ (p = 0,0031) s'améliorent, pas l'échelle fonctionnelle LEFS.\n\nLes oscillations posturales sur plateforme diminuent et la vitesse de marche augmente (p = 0,0315). Un résultat pertinent pour le risque de chute, mais sans comparateur.","l3":{"points":["Équilibre mesuré sur surfaces rigide et déformable.","Marche sur 10 m améliorée."],"limites":["Avant-après sans témoin, suivi très court."],"pratique":"Piste peu coûteuse pour les troubles de l'équilibre liés à la neuropathie chimio-induite."},"topic":"neuropathie-peripherique","title":"Influence of photobiomodulation on sensory symptoms, balance, and gait speed in chemotherapy-induced peripheral neuropathy.","journal":"Supportive care in cancer : official journal of the Multinational Association of Supportive Care in Cancer","journal_abbr":"Support Care Cancer","authors":["Santamarina L","de Souza MO","Sassaron LA","et al."],"date":"2025-04-05","year":2025,"week":"2025-S14","doi":"10.1007/s00520-025-09405-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":[],"abstract":[{"label":"INTRODUCTION","text":"Photobiomodulation (PBM) is a non-invasive therapy that uses low-level light in the visible and near-infrared spectrum to stimulate cellular processes, promoting tissue repair and reducing inflammation without causing thermal damage. PBM has shown potential in alleviating neuropathic pain and improving nerve function by enhancing mitochondrial activity, reducing oxidative stress, and modulating inflammatory pathways. Emerging evidence suggests that PBM may be a promising adjunctive treatment for managing chemotherapy-induced peripheral neuropathy (CIPN) and improving patients' quality of life."},{"label":"OBJECTIVE","text":"To evaluate the influence of photobiomodulation (PBM) on sensory complaints, balance, and gait speed in patients with chemotherapy-induced peripheral neuropathy (CIPN)."},{"label":"METHODS","text":"Prospective clinical study in 47 patients with CIPN in the lower limbs (CAAE: 70504423.9.0000.5382). Patients received PBM (630/850 nm), in the nerve pathway, 2 × /week for 2 weeks. The Neuropathic Pain Questionnaire (DN-4), the Chemotherapy-Induced Peripheral Neuropathy Assessment Tool (FANPIQ) and its interference items, and the Lower Extremity Functional Scale (LEFS) were used. Balance was assessed by measuring the amplitude, speed, and area of displacement with a force platform on rigid and deformable surfaces. Gait speed (GS) was assessed by the 10-m walk test. Measurements were collected at the beginning and end of treatment and analyzed with descriptive statistics and independent t-test."},{"label":"RESULTS","text":"Sensory symptoms improved, as evidenced by the results of the DN-4 (p < 0.0001) and the FANPIQ (p = 0.0031), but not in the LEFS (p = 0.2379). There was also a significant improvement in the amplitude of the anteroposterior displacement (APD) and in the amplitude of the mediolateral displacement (MLD) (p = 0.0001 and p < 0.0001), in the velocity of the APD and MLD (p = 0.0431 and p = 0.0016), and in the displacement area (p = 0.0001). On the deformable surface, significant reductions were also observed in the APD and MLD (p = 0.0314 and p = 0.0008), as well as in the velocity of the MLD (p = 0.0091) and displacement area (p = 0.0029). GS showed improvement (p = 0.0315)."},{"label":"CONCLUSION","text":"PBM proved to be a promising low-cost resource for the management of sensory symptoms of CIPN, with positive clinical repercussions on balance and gait speed."}],"keywords":["Balance","Chemotherapy-induced peripheral neuropathy","Force platform","Neuropathic pain","Photobiomodulation","Sensory symptoms"]},{"pmid":"40090424","title_fr":"PBM et biomarqueurs neuronaux dans la neuropathie diabétique de type 2 : essai randomisé en simple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[632.8],"n":200,"effect":"favorable","theme":"Neuropathie diabétique","key":true,"l1":"Le plus grand essai de la période (200 diabétiques) : dix jours de laser He-Ne sur les pieds réduisent la douleur, améliorent la sensibilité vibratoire et la qualité de vie, avec des biomarqueurs (NSE, CGRP) qui évoluent dans le même sens.","l2":"Essai indien randomisé 100/100 contre laser simulé : laser He-Ne 632,8 nm, 3,1 J/cm², 9 minutes sur le dos et la plante des pieds. Évaluation à 4 semaines.\n\nAmélioration significative de l'énolase neurospécifique (NSE), du CGRP, du score MNSI, du seuil de perception vibratoire, de la douleur (NPRS) et de la qualité de vie (Norfolk QOL-DN), mais pas du NGF. Les auteurs proposent NSE et CGRP comme marqueurs de réponse.","l3":{"points":["Randomisation 1:1, 200 patients.","Toutes les différences cliniques p < 0,001 ; NGF inchangé (p = 0,937)."],"limites":["Simple aveugle ; suivi de 4 semaines."],"pratique":"Argument solide pour la PBM dans la neuropathie diabétique douloureuse, à court terme."},"topic":"neuropathie-peripherique","title":"A single blinded randomized controlled trial assessing the effect of photobiomodulation therapy on neuron specific biomarkers in type II diabetes mellitus patients with peripheral neuropathy.","journal":"Diabetes research and clinical practice","journal_abbr":"Diabetes Res Clin Pract","authors":["Anju M","Ummer Velladath S","Arun Maiya G","et al."],"date":"2025-03-14","year":2025,"week":"2025-S11","doi":"10.1016/j.diabres.2025.112087","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"BACKGROUND","text":"Diabetic peripheral neuropathy is one of the most devastating complications of long-term diabetes mellitus, associated with functional limitations and poor quality of life."},{"label":"MATERIALS AND METHODS","text":"Two hundred subjects were randomized into intervention and control group, with one hundred in each arm. The intervention arm received photobiomodulation therapy for ten days, with Low -Level Helium-Neon Laser at a wavelength of 632.8 nm of dosage 3.1 J/cm2 for 9 min on both the dorsal and plantar surfaces of the foot, while the control group received sham laser. Patients were assessed at day 0 of treatment and four weeks after treatment for all the clinical and neuropathy-specific biomarkers. Serum levels of Neuron specific enolase (NSE), Calcitonin gene related peptide (CGRP) Nerve Growth Factor (NGF) for monitoring neuronal changes and monofilament test, Biothesiometer, Numeric Pain Rating Scale (NPRS) to analyze vibration sensation, and pain score. The neuropathic quality of life was assessed using the Norfolk Quality of Life Questionnaire- Diabetic Neuropathy (Norfolk QOL-DN)."},{"label":"RESULT","text":"Trial found significant changes in serum NSE (p < 0.001), CGRP(p < 0.001), MNSI(p < 0.001), VPT(p < 0.001), NPRS(p < 0.001), and NQL(p < 0.001) in the intervention group four weeks after receiving photobiomodulation therapy, whereas no changes in NGF levels(p = 0.937). This was in correlation with improved neuropathic pain and quality of life."},{"label":"CONCLUSION","text":"Serum levels of NSE and CGRP may be good indicators of effectiveness of photobiomodulation in reducing neuropathic pain and other symptoms in individuals with DPN. Reduced neuropathic symptoms, improved protective sensation of foot and quality of life, and reduced neuropathic pain was observed in intervention group."}],"keywords":["Biomarkers","Calcitonin gene related peptide","Diabetic peripheral neuropathy","Nerve growth factor","Neuron specific enolase","Photobiomodulation"]},{"pmid":"40070012","title_fr":"PBM par LED 807 nm et lésion nerveuse périphérique (cellules et rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["LED"],"nm":[807],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Une LED 807 nm stimule les cellules de Schwann in vitro et améliore chez le rat la fonction et la myélinisation du nerf sciatique lésé.","l2":"Paramètres optimisés sur cellules (10 mW/cm², 30 min) puis transposés en tenant compte de la transmission à travers la peau et le muscle (environ 30 %). Montre la faisabilité de la PBM par LED pour la régénération nerveuse.","l3":{"points":["Rat : 33 mW/cm², 30 min par jour pendant 21 jours."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"The effect of 807-nm light-emitting diode photobiomodulation on peripheral nerve injury.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["Chang B","Quan Q","Liang X","et al."],"date":"2025-03-11","year":2025,"week":"2025-S11","doi":"10.1111/php.14090","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation (PBM) has demonstrated potential in promoting peripheral nerve regeneration. However, there is a limited and inconclusive study on the application of light-emitting diode (LED) for nerve injury repair. In this study, we designed an 807-nm LED device with high luminous uniformity to investigate the effects of LED-based PBM on peripheral nerve injury repair. RSC96 cells were utilized as the target cells and optimal light parameters were selected based on ATP concentration, CCK-8 assays, PCR, and immunofluorescent staining. One-way analysis of variance and Student's t-test was used for statistical tests. LED irradiation at 10 mW/cm2 for 30 min effectively enhanced Schwann cell proliferation, neurotrophic factor secretion, and MBP synthesis. To translate the cellular light parameters for animal studies, the transmittance through freshly obtained rat skin and biceps femoris muscle was assessed, and the transmittance was approximately 30%. After directly daily irradiating the sciatic nerve injury area in rats for 21 days at 33 mW/cm2 for 30 min, we used gait analysis, immunofluorescence staining, muscle wet weight ratio, Masson staining, and transmission electron microscopy to evaluate nerve recovery. LED irradiation significantly improved sciatic nerve index, increased MBP staining intensity, and enhanced myelin sheath thickness, nerve diameter, and axon diameter. These results indicated the feasibility of LED-based PBM as a treatment method for peripheral nerve injuries."}],"keywords":["laser medicine","light‐emitting diode","peripheral nerve injury","peripheral nerve regeneration","photobiomodulation"]},{"pmid":"40121869","title_fr":"Laser haute intensité dans le canal carpien : revue systématique et méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":null,"effect":"favorable","theme":"Canal carpien","l1":"Neuf essais : le laser haute intensité réduit la douleur et le handicap et améliore la conduction nerveuse dans le canal carpien ; certitude modérée à faible.","l2":"Revue enregistrée (PROSPERO) avec RoB 2 et GRADE. Douleur : DMS de 0,7 à 1,6 ; handicap : DMS 0,68 ; latence motrice distale : DMS 0,98 ; vitesse sensitive : DMS 0,8, surtout combiné au glissement nerveux ou à l'attelle.\n\nLes auteurs demandent des comparaisons directes avec le laser basse intensité : l'essai pakistanais de 2026 en apporte une.","l3":{"points":["9 ECR ; risque de biais global 44 %."],"limites":["Certitude modérée à faible."],"pratique":"Le laser haute intensité est une option validée en complément de l'attelle et des exercices."},"topic":"neuropathie-peripherique","title":"A systematic review and meta-analysis of the effectiveness of high-intensity laser therapy in patients with carpal tunnel syndrome.","journal":"Physiotherapy","journal_abbr":"Physiotherapy","authors":["de la Barra Ortiz HA","Avila MA","Parizotto NA","et al."],"date":"2025-03-05","year":2025,"week":"2025-S10","doi":"10.1016/j.physio.2025.101780","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Meta-Analysis","Systematic Review","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"OBJECTIVES","text":"This systematic review aimed to evaluate the effects of high-intensity laser therapy (HILT) on pain intensity, disability, and electrophysiological parameters in individuals diagnosed with carpal tunnel syndrome (CTS)."},{"label":"DATA SOURCES AND SYNTHESIS","text":"A search of electronic databases, including PubMed, Web of Science, Scopus, CINAHL, Science Direct, Cochrane Library, the PEDro database, and Google Scholar (updated until February 18, 2025), was conducted for randomized controlled trials (RCTs)."},{"label":"DATA EXTRACTION AND QUALITY ASSESSMENT","text":"Data were extracted independently by three researchers. The quality of RCTs was assessed using the Cochrane Risk of Bias (RoB) 2.0 tool, while evidence certainty was evaluated with the GRADE approach. Primary outcomes included pain intensity, with secondary outcomes comprising electrophysiological parameters and disability."},{"label":"RESULTS","text":"Nine RCTs met inclusion criteria. Most studies exhibited a low risk of bias across RoB2 domains, except for outcome measurement, resulting in an overall RoB of 44%. Meta-analyses demonstrated that HILT, alone or combined with interventions such as splinting, exercise, TENS, vitamin B supplements, or ergonomic modifications, significantly reduced pain (SMD = 0.7 to 1.6) and disability (SMD = 0.68). Electrophysiological improvements included enhanced distal motor latency (SMD = 0.98) and sensory conduction velocity (SMD = 0.8), particularly when combined with median nerve gliding or splinting."},{"label":"CONCLUSION","text":"This review confirms HILT's effectiveness in reducing pain and disability and improving electrophysiological parameters in CTS. However, evidence certainty remains moderate to low. Future RCTs should standardize outcome measures to evaluate HILT's clinical impact beyond statistical significance, and comparative studies with LLLT are needed to refine laser therapy protocols."},{"label":"SYSTEMATIC REVIEW REGISTRATION NUMBER","text":"PROSPERO CRD42023470170 (October 17, 2023). CONTRIBUTION OF THE PAPER."}],"keywords":["Carpal Tunnel Syndrome","High-intensity laser therapy","Laser therapy","Median neuropathy","Pain Management","Systematic review"]},{"pmid":"39929358","title_fr":"Laser basse énergie dans les neuropathies maxillo-faciales : revue systématique d'essais randomisés","type":"ma","level":1,"pop":"adulte","ctx":["orofaciale","lésion nerveuse"],"aim":"traitement","mode":["laser"],"nm":[],"n":1220,"effect":"favorable","theme":"Neuropathies orofaciales","l1":"Dix-huit essais (1 220 patients) : le laser réduit la douleur de 3,5 points en moyenne et accélère de 45 % la récupération sensitive dans les paresthésies, névralgies et paralysies faciales.","l2":"Revue (jusqu'en décembre 2024) avec synthèse quantitative. Douleur EVA : −3,5 (IC95 % −4,2 à −2,8). Récupération des seuils sensitifs 45 % plus rapide. Effets indésirables légers (érythème) dans moins de 5 % des cas.","l3":{"points":["18 ECR, 841 notices initiales."],"limites":["Dosimétrie variable, petits essais."],"pratique":"Après lésion du nerf alvéolaire inférieur ou lingual, la PBM est une option documentée."},"topic":"neuropathie-peripherique","title":"Effectiveness of low-level laser therapy in patients with maxillofacial neuropathies. A systematic review of randomized controlled trials.","journal":"Photodiagnosis and photodynamic therapy","journal_abbr":"Photodiagnosis Photodyn Ther","authors":["Díaz L","Basualdo J","Chaple-Gil A","et al."],"date":"2025-02-08","year":2025,"week":"2025-S06","doi":"10.1016/j.pdpdt.2025.104516","pmcid":null,"license":"cc by-nc","oa":false,"pdf":null,"cited_by":4,"pub_types":["Systematic Review"],"abstract":[{"label":"OBJECTIVE","text":"This study aimed to evaluate the effectiveness and safety of low-level laser therapy (LLLT) in managing maxillofacial neuropathies, with a focus on pain reduction, neurological recovery, and tissue regeneration."},{"label":"METHODS","text":"A systematic search of PubMed, Web of Science, Scopus, and EBSCO databases was conducted for English-, Spanish-, and Portuguese-language publications on LLLT for maxillofacial neuropathies up to December 2024. Randomized controlled trials (RCTs) involving patients with paresthesia, neuralgia, or facial paralysis treated with LLLT were included. Data extraction and risk-of-bias assessments were conducted by two independent reviewers, and results were synthesized qualitatively and quantitatively."},{"label":"RESULTS","text":"From an initial pool of 841 studies, 18 RCTs involving 1,220 patients met the inclusion criteria. LLLT significantly reduced pain scores on the Visual Analog Scale (VAS) (mean reduction = -3.5, 95 % CI:4.2 to -2.8, P < 0.001) and facilitated a 45 % faster recovery of sensory thresholds compared to controls (P < 0.001). Tissue regeneration markers, including collagen deposition and epithelialization rates, improved, resulting in a 25 % reduction in healing times (P < 0.05). Mild adverse events, such as transient erythema, were reported in <5 % of cases. Variability in laser dosimetry and small sample sizes across studies were noted."},{"label":"CONCLUSION","text":"Low-level laser therapy is an effective and safe modality for managing maxillofacial neuropathies, demonstrating significant benefits in pain reduction, nerve recovery, and tissue healing. Standardized protocols and multicenter trials are necessary to optimize its application."}],"keywords":["Low-level laser therapy","Maxillofacial neuropathies","Neural recovery","Pain management","Photobiomodulation","Systematic review","Tissue regeneration"]},{"pmid":"39829285","title_fr":"PBM chez le diabétique : douleur, qualité de vie et cicatrisation","type":"nrct","level":4,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["LED"],"nm":[660],"n":20,"effect":"favorable","theme":"Neuropathie diabétique","l1":"Chez 20 diabétiques, la PBM à 660 nm deux fois par semaine pendant 7 semaines améliore la douleur neuropathique, la sensibilité, la qualité de vie et la cicatrisation des plaies.","l2":"Étude brésilienne avant-après avec tests sensitifs quantitatifs et culture de fibroblastes cutanés. In vitro, la PBM stimule la prolifération via ERK et module les métalloprotéases.","l3":{"points":["Moins d'anxiété et de dépression après traitement."],"limites":["Pas de témoin, 20 patients."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Photobiomodulation therapy in diabetes: Benefits for pain relief, quality of life, and wound healing.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["da Silva Oliveira VR","de Paula Oliveira I","Alonso-Matielo H","et al."],"date":"2025-01-20","year":2025,"week":"2025-S04","doi":"10.1111/php.14053","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":[],"abstract":[{"label":"","text":"Globally, 537 million people suffer from diabetes mellitus (DM), a condition often associated with sensory disturbances, wound development, and chronic pain, which significantly affects the quality of life and imposes a substantial economic burden. This study evaluated the effects of photobiomodulation (PBM) therapy on nociceptive and sensory changes in diabetic patients to understand pain manifestations and explore PBM's molecular mechanisms on wound healing. Twenty patients with type 2 DM underwent clinical assessments, completed pain and quality of life questionnaires, and had their pain sensitivity evaluated using the quantitative sensory test (QST). A 5 mm skin biopsy was taken for fibroblast culture. PBM therapy, using 660 nm red light, was administered twice weekly for 7 weeks on lower limb wounds. Results indicated that DM patients faced significant sensory impairments, impacting their quality of life. PBM therapy improved pain scores, alleviated neuropathic pain, and enhanced sensory function, leading to better quality of life and reduced anxiety and depression. It also accelerated wound healing, enhancing mobility and autonomy. In vitro studies showed PBM therapy increased cell proliferation through the ERK signaling pathway and modulation of matrix metalloproteinases (MMP-1/8 and 2) and tissue inhibitors of metalloproteinases (TIMP)."}],"keywords":["ERK","MMPs","Photobiomodulation","QST","diabetes","pain","wounds"]},{"pmid":"39776290","title_fr":"PBM dans le canal carpien (douleur, force, fonction) : revue systématique et méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Canal carpien","l1":"Treize essais : la PBM basse intensité améliore la fonction de la main dans le canal carpien, mais la méta-analyse ne montre pas d'effet significatif sur la douleur ni sur la force.","l2":"Revue avec RoB 2 ; 61,5 % des essais à faible risque de biais. Pas d'avantage du laser pour la douleur (p = 0,08) ni la force de préhension (p = 0,11) ; amélioration de la fonctionnalité.\n\nCe résultat nuance la méta-analyse en réseau de 2025 : selon les essais retenus, l'effet sur la douleur varie.","l3":{"points":["13 ECR sur 1 613 notices."],"limites":["Dosimétrie hétérogène."],"pratique":"Attendre surtout un gain fonctionnel."},"topic":"neuropathie-peripherique","title":"Photobiomodulation in carpal tunnel syndrome with pain, strength, and functionality analysis: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Lauxen AC","Machado DR","Pereira DS","et al."],"date":"2025-01-08","year":2025,"week":"2025-S02","doi":"10.1007/s10103-024-04276-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"BACKGROUND","text":"Carpal tunnel syndrome (CTS) is characterized as a compressive neuropathy of the median nerve and has several treatments, including photobiomodulation, which can be performed with low-intensity laser therapy (LLLT) and light-emitting diodes (LEDs)."},{"label":"PURPOSE","text":"To carry out a literature review on the effectiveness of low-intensity laser therapy (LLLT) in CTS."},{"label":"METHODS","text":"This study is characterized by being a systematic review with metaanalysis. The databases included were PubMed, Embase, Cochrane, the Physiotherapy Evidence Database (PEDro), Scopus and LILACS. Also, gray literature: Google Scholar, OpenGrey and CAPES Theses and Dissertations Catalog. The search was carried out in all databases on October 11, 2023 and updated on June 06, 2024. The risk of bias was assessed using the Cochrane tool, RoB 2, by two blinded reviewers and conflicts were resolved by consensus. The outcomes of interest were pain intensity (Visual analogue scale), strength (handgrip and pinch) and hand functionality (Boston questionnaire, Levine questionnaire, Purdue Pergboard Test). Statistical analysis was carried out using RevMan 5.4.1. Continuous results were expressed as standard mean differences (95% CI), with p-value of < 0.05 considered statistically significant. The value of the I2 statistical test was calculated to test for heterogeneity between studies. A random effects model was adopted."},{"label":"RESULTS","text":"13 randomized controlled trials were selected from 1.613 records. In the general bias analysis, two studies (15,4%) were considered to have some relevant problems that could interfere with the quality of the study, and three (23,1%) were identified as having a high risk of bias, eight studies (61,5%) were classified as having a low risk of bias. In the meta-analysis, it was possible to observe that there were no advantages of the laser for pain (p = 0.08), nor for handgrip strength (p = 0.11), but it did produce improvements in functionality."},{"label":"CONCLUSION","text":"It is concluded that LLLT is an effective therapeutic modality in the treatment of CTS, improving functionality; however, despite the studies pointing to advantages for the modality in reducing pain and improving grip strength, the meta-analysis did not show this result. Even so, there is a need for more clinical trials are needed to standardize dosimetry, mainly because the primary studies showed clinical advantages of PBM."},{"label":"REGISTRATION","text":"Open Science Framework (OSF)- https://doi.org/10.17605/OSF.IO/HQCRP ."}],"keywords":["Carpal tunnel syndrome","Low-intensity laser therapy","Pain measurement","Peripheral nerve injuries","Systematic review"]},{"pmid":"40124311","title_fr":"PBM et douleur cornéenne neuropathique : étude chez la souris","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez la souris avec lésion des nerfs cornéens, la PBM réduit la sensibilité douloureuse jusqu'à J56 ; une intervention précoce serait déterminante.","l2":"Quatre modèles (témoin, simulation, nerf tiré, section complète), tests de Von Frey et d'essuyage oculaire.","l3":{"points":["Effet significatif à J56 dans les deux modèles lésionnels."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Evaluating the Preclinical Efficacy of Photobiomodulation in Alleviating Neuropathic Corneal Pain: A Behavioral Study.","journal":"Ophthalmology science","journal_abbr":"Ophthalmol Sci","authors":["Khan MA","Fatima G","Ashiquzzaman A","et al."],"date":"2024-12-18","year":2024,"week":"2024-S51","doi":"10.1016/j.xops.2024.100680","pmcid":"PMC11930074","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/40124311.pdf","cited_by":1,"pub_types":[],"abstract":[{"label":"PURPOSE","text":"Neuropathic corneal pain (NCP) is a debilitating condition characterized by persistent pain due to corneal nerve damage or dysfunction. Millions of individuals and their families endure the significant impact of chronic pain. Effective management strategies are crucial yet limited, prompting the exploration of innovative treatments such as photobiomodulation (PBM)."},{"label":"DESIGN","text":"In vivo preclinical therapeutics investigation in mice."},{"label":"SUBJECTS","text":"Thy1-YFP mice."},{"label":"METHODS","text":"This study evaluates the efficacy of PBM in treating NCP across 4 animal models: normal control, sham control, pulled nerve, and full transection (FT). Behavioral assessments, including the von Frey test (VFT) for mechanical sensitivity and the eye-wiping test (EWT) for chemical sensitivity, were employed to evaluate the therapeutic impact of PBM till day 56 (D-1, D1, D3, D5, D7, D14, D28, D42, and D56)."},{"label":"MAIN OUTCOME MEASURES","text":"Advances in therapeutic approach for NCP through the potential of PBM."},{"label":"RESULTS","text":"Photobiomodulation significantly reduced behavioral manifestations of pain in the pulled nerve model (VFT: no PBM [D1 = 0.043 ± 0.044, D56 = 0.05 ± 0.014] and PBM [D1 = 0.050 ± 0.008 {P value = 0.18}, D56 = 0.09 ± 0.014 {P value = 0.02}], EWT: no PBM [D1 = 11.96 ± 0.47, D56 = 12.11 ± 0.15] and PBM [D1 = 11.73 ± 0.18 {P value = 0.2}, D56 = 11.22 ± 0.31] [P value = 0.01]) and FT model (VFT: no PBM [D1 = 0.022 ± 0.0028, D56 = 0.023 ± 0.0047] and PBM [D1 = 0.024 ± 0.0028 {P value = 0.2}, D56 = 0.073 ± 0.0094] [P value = 0.02]), EWT: no PBM [D1 = 13.1 ± 0.14, D56 = 13.36 ± 0.30] and PBM [D1 = 12.86 ± 0.41, {P value = 0.2}, D56 = 12.53 ± 0.41] [P value = 0.04]}, suggesting an effective reduction of pain sensitivity and an increase in corneal nerve function. The temporal patterns also suggest that early intervention with PBM, initiated shortly after nerve injury, may be crucial for preventing the chronic progression of NCP."},{"label":"CONCLUSIONS","text":"These outcomes support PBM as a promising nonpharmacologic intervention for NCP; this not only reinforces the potential of PBM in NCP treatment but also provides a foundation for future clinical applications in managing corneal neuropathy."},{"label":"FINANCIAL DISCLOSURES","text":"The author(s) have no proprietary or commercial interest in any materials discussed in this article."}],"keywords":["Behavior tests","Chronic pain","Invivo","Neuropathic corneal pain (NCP)","Photobiomodulation (PBM)"]},{"pmid":"39607829","title_fr":"PBM du diabète et de ses complications : présentation, mécanismes et efficacité","type":"review","level":5,"pop":"adulte","ctx":["diabète"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue générale de la PBM dans les complications du diabète (rétinopathie, ulcères, neuropathie, parodontite).","l2":"Présentation des mécanismes et des avantages et limites. Sans données nouvelles.","l3":{"points":["Revue générale."],"limites":["Revue narrative."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Photobiomodulation for diabetes and its complications: a review of general presentation, mechanisms and efficacy.","journal":"Annals of medicine","journal_abbr":"Ann Med","authors":["Wang K","Zhao H","Zhao X","et al."],"date":"2024-11-28","year":2024,"week":"2024-S48","doi":"10.1080/07853890.2024.2433684","pmcid":"PMC11610354","license":"cc by-nc","oa":true,"pdf":"pdfs/39607829.pdf","cited_by":10,"pub_types":["Review"],"abstract":[{"label":"","text":"Diabetes mellitus is a metabolic disease that is marked by persistent hyperglycemia due to inadequate insulin secretion or insulin resistance. Its prevalence is increasing yearly. Diabetes mellitus can lead to serious health complications that are the primary cause of mortality and disability among diabetic patients, including diabetic retinopathy, diabetic foot ulcers, diabetic peripheral neuropathy, and diabetic periodontitis, and so on. Traditional treatments for diabetes and its complications still suffer from limited clinical efficacy and high therapeutic side effects. Photobiomodulation (PBM), which utilizes low levels of red or near-infrared laser to irradiate cells and tissues, has been shown to be efficacious for a wide range of organ damage. In this study, we focus on the application of PBM in diabetes and its complications and mechanisms, as well as the advantages, disadvantages with the aim of developing new ideas for the application of PBM."}],"keywords":["Diabetes mellitus","Photobiomodulation","diabetic complications","low-level laser therapy"]},{"pmid":"39463219","title_fr":"Potentiel thérapeutique de la PBM dans les complications du diabète","type":"review","level":5,"pop":"adulte","ctx":["diabète"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"—","theme":"Revue générale","l1":"Revue : rouge et proche infrarouge sont utilisés pour la neuropathie, le bleu pour les plaies ; peu d'essais et des paramètres non standardisés.","l2":"Revue par longueur d'onde (bleu, rouge, proche infrarouge). Elle constate le petit nombre d'essais cliniques pour la plupart des complications.","l3":{"points":["Approche par longueur d'onde."],"limites":["Revue narrative."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Therapeutic Potential of Photobiomodulation in Diabetic Complications.","journal":"Discovery medicine","journal_abbr":"Discov Med","authors":["Hadebe L","Houreld NN"],"date":"2024-10-28","year":2024,"week":"2024-S44","doi":"10.24976/Discov.Med.202436189.183","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Review"],"abstract":[{"label":"","text":"Diabetes mellitus (DM) and its associated complications, including diabetic kidney disease, neuropathy, and retinopathy, impose significant challenges on healthcare systems due to their high morbidity, mortality, and associated costs. Existing treatments often yield unsatisfactory clinical outcomes, underscoring the need for innovative approaches to mitigate debilitating effects on patients' health-related quality of life. Photobiomodulation (PBM) is a non-invasive treatment that utilizes specific wavelengths of light in the treatment of various medical complications associated with DM. The specific wavelength used during PBM is critical in determining the therapeutic outcomes for managing diabetic complications. This paper aimed to explore the therapeutic potential of PBM in the management of diabetic complications, focusing on blue, red, and near-infrared (NIR) wavelengths. Relevant literature from Google Scholar, PubMed and ClinicalTrials databases from inception to date was searched using the keywords 'photobiomodulation', 'diabetes', 'diabetic complications', 'wound healing', 'neuropathy', 'retinopathy', and 'chronic wounds'. Red and NIR wavelengths are commonly used for a range of complications, while blue light has primarily been explored for treating diabetic wounds due to its antimicrobial nature. PBM treatment parameters for the same diabetic complication vary across clinical trials and preclinical research, with minimal clinical trials conducted on most diabetic complications. This inconsistency hinders the establishment of standardized PBM parameters, particularly concerning the optimal application setting."}],"keywords":["diabetes mellitus","diabetic complications","photobiomodulation","wavelengths"]},{"pmid":"39446663","title_fr":"Laser-acupuncture et canal carpien du post-partum : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":36,"effect":"favorable","theme":"Canal carpien","l1":"Chez 36 femmes en post-partum, ajouter la laser-acupuncture à l'attelle de nuit améliore la conduction nerveuse, la force de pince et la fonction de la main.","l2":"Essai égyptien : 12 séances de 12 minutes sur des points d'acupuncture, trois fois par semaine. Les deux groupes s'améliorent, davantage sous laser.","l3":{"points":["Latences et vitesses motrices et sensitives améliorées."],"limites":["Pas de simulation ; petit effectif."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Efficacy of Laser Acupuncture on Neurophysiological Parameters of Median Nerve and Hand Function in Postpartum Women: A Randomized Controlled Clinical Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Botla AM","Lasheen YR","Mohamed SS","et al."],"date":"2024-10-24","year":2024,"week":"2024-S43","doi":"10.1089/photob.2024.0106","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Objective: This study was conducted to ascertain the efficacy of photo acupuncture (PA) on the neurophysiological parameters of the median nerve and hand function in postnatal women. Background: Carpal tunnel syndrome (CTS) has been documented in up to 62% of pregnant females. PA, a noninvasive treatment that utilizes photo therapy on acupoints, could aid in the management of CTS. Material and Methods: Thirty-six postpartum women diagnosed with CTS depending on their medical history, physical examination, and electrodiagnostic study were distributed into two equal-sized groups at random. The PA group (n = 18) received PA for 12 min on the following acupuncture points: PC4, PC6, PC7, PC8, HT2, HT3, HT7, LI10, LI11, LI4, LU9, and LU10. The treatment was given 3 times weekly for four weeks; in addition, night splints were worn. Women in the control group (n = 18) just wore night splints. Before and after the 12-session treatment, each woman was assessed using an electrodiagnostic test to measure the motor distal latency (MDL), sensory distal latency (SDL), motor conduction velocity (MCV), sensory conduction velocity (SCV), pinch dynamometer for assessing pinch strength, and the Brief Michigan Hand Questionnaire (BMHQ) for assessing hand function. Results: A statistically significant improvement was observed in both groups after therapy regarding SDL, SCV, MDL, MCV, pinch strength, and BMHQ (p < 0.05) in favor of the PA group. Conclusion: Adding PA to a night splint should be suggested as an effective conservative therapy for CTS in postpartum women."}],"keywords":["carpal tunnel syndrome","night splint","photo acupuncture","photo therapy","postpartum period"]},{"pmid":"39397682","title_fr":"PBM dans le syndrome du canal cubital : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":64,"effect":"mitigé","theme":"Autres compressions nerveuses","l1":"Chez 64 patients, le laser associé à l'attelle et aux exercices est supérieur à la simulation à 3 semaines, mais l'effet devient équivalent à 3 mois.","l2":"Essai en simple aveugle. Les deux groupes s'améliorent. Le laser fait mieux sur la douleur au repos et en mouvement et sur le score PRUNES à 3 semaines ; seule la douleur PRUNES reste meilleure à 3 mois.","l3":{"points":["32 patients par groupe."],"limites":["Bénéfice qui s'estompe à moyen terme."],"pratique":"Attendre un bénéfice surtout à court terme."},"topic":"neuropathie-peripherique","title":"The Effects of Photobiomodulation Therapy in Cubital Tunnel Syndrome, Clinical Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Yağcı G","Kasapoğlu Aksoy M","Aykurt Karlıbel İ","et al."],"date":"2024-10-14","year":2024,"week":"2024-S42","doi":"10.1089/photob.2024.0089","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Aim: We aimed to evaluate the effects of laser therapy together with rest splint and exercise on muscle strength, function, activities of daily living, and pain in individuals suffering from cubital tunnel syndrome (CuTS) by comparing it with placebo treatment. Materials and Methods: This prospective, single-blind, and randomized controlled study was conducted with 64 patients with CuTS in total. They were divided into two groups by randomization: Group 1 (n = 32) was provided with low-energy laser therapy + splint + exercise, and Group 2 (n = 32) was provided with low-energy sham laser therapy + splint + exercise. Patients in both groups received resting splints and nerve release exercises. Pretreatment and posttreatment (3rd week, 3rd month) evaluations were made with the Visual Analog Scale (VAS), the Quick Disability of Arm, Shoulder, and Hand Questionnaire, hand grip strength, fingertip grip strength, the Patient-Rated Ulnar Nerve Evaluation Scale (PRUNES), and Short Form-12. An electrophysiological evaluation was performed at baseline and at the 3rd month. Results: We observed significant improvements in both groups regarding pain, function, muscle strength, health profile, and quality of life in the early posttreatment (3rd week) stage and at the 3rd-month follow-up. When both groups were compared, a significant difference was determined between the VAS-Rest, VAS-Movement, PRUNES-Pain, PRUNES-Function, and PRUNES-Total parameters in the posttreatment (3rd week follow-ups), as well as PRUNES-Pain scores in the post-treatment (3rd month) stage, of the groups in favor of those in Group 1 (p < 0.05). Conclusion: The findings of our study have shown that in the treatment of CuTS, laser treatment is superior to placebo in the short term, but they have equivalent effects in the medium term. Further studies with large patient populations are needed to provide more diverse information about the therapeutic effectiveness of low-intensity laser therapy."}],"keywords":["cubital tunnel syndrome","laser therapy","pain","quality of life"]},{"pmid":"39344359","title_fr":"Le laser basse énergie réduit l'allodynie dans des modèles de douleur postopératoire et neuropathique (rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"les deux","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat, le laser soulage la douleur après ligature de nerf spinal mais ne la prévient pas, contrairement à la douleur d'incision où il est aussi préventif.","l2":"Baisse de l'IL-1β et du NGF dans la peau, le muscle et la corne dorsale de la moelle dans le modèle d'incision.","l3":{"points":["Pas d'effet préventif sur la douleur neuropathique."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Low level laser therapy alleviates mechanical allodynia in a postoperative and neuropathic pain model and alters the levels of inflammatory factors in rats.","journal":"The Korean journal of pain","journal_abbr":"Korean J Pain","authors":["Han X","Jang KC","Kim WM","et al."],"date":"2024-09-30","year":2024,"week":"2024-S40","doi":"10.3344/kjp.24144","pmcid":"PMC11450298","license":"cc by-nc","oa":true,"pdf":"pdfs/39344359.pdf","cited_by":2,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"This study aimed to investigate the analgesic and preventive effect of low-level laser therapy (LLLT) on the incisional pain model and spinal nerve ligation (SNL) model in rats and identify the possible mechanisms of action."},{"label":"METHODS","text":"Male Sprague-Dawley rats were used, divided into different treatment groups. The single application group received LLLT before or after skin incision or SNL. The consecutive application group received LLLT for six consecutive days post-incision, three days pre-incision, or three consecutive days pre-SNL. The control group underwent skin incision or SNL without LLLT. The von Frey test was used to quantify the pain associated with mechanical allodynia. Pro-inflammatory cytokine level and alterations in nerve growth factor (NGF) expression were measured by using ELISA and immunohistochemistry, respectively in the skin, muscle of the paw, and spinal cord dorsal horn (SCDH)."},{"label":"RESULTS","text":"In the incisional pain model, LLLT showed significant analgesic and preventive effect. LLLT ameliorated SNL-induced mechanical allodynia but LLLT had no preventive effect. LLLT decreased interleukin-1β (IL-1β) expression levels in the skin, muscle, and SCDH and reduced the optical density of skin and spinal cord NGF in the incisional pain model."},{"label":"CONCLUSIONS","text":"LLLT alleviated incisional pain and neuropathic pain caused by SNL in rats, and reduced the levels of IL-1β and NGF in the peripheral tissue and SCDH in the incisional pain model. LLLT might be effective in patients with post-operative pain and peripheral neuropathic pain."}],"keywords":["Cytokines","Hyperalgesia","Interleukin-1","Low-Level Light Therapy","Pain","Postoperative","Spinal Cord Dorsal Horn","Spinal Nerves"]},{"pmid":"39327309","title_fr":"Laser basse énergie dans la neuropathie ulnaire au coude : essai randomisé en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":68,"effect":"favorable","theme":"Autres compressions nerveuses","key":true,"l1":"Chez 68 patients, le laser ajouté à l'attelle réduit davantage la douleur de jour et de nuit et améliore la fonction à 3 mois, sans différence sur la force ni l'électrophysiologie.","l2":"Essai turc contre laser simulé, en double aveugle. Évaluations à J15 et à 3 mois : EVA, paresthésies, force, tests de provocation, QuickDASH, conduction nerveuse.\n\nL'attelle seule est efficace ; le laser renforce l'effet sur la douleur et la fonction. La conduction sensitive est meilleure à J15 seulement.","l3":{"points":["Douleur jour et nuit : meilleure à J15 et M3 (p < 0,05).","QuickDASH meilleur à M3."],"limites":["Pas d'effet électrophysiologique durable."],"pratique":"Le laser est un complément utile de l'attelle dans la neuropathie ulnaire au coude."},"topic":"neuropathie-peripherique","title":"Evaluation of the efficacy of low-level laser therapy in the treatment of ulnar neuropathy at the elbow in terms of symptoms and clinical and electrophysiological findings: a randomized, prospective, double-blind clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Çelik G","Doğan ŞK","Filiz MB"],"date":"2024-09-26","year":2024,"week":"2024-S39","doi":"10.1007/s10103-024-04189-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"","text":"Ulnar neuropathy at the elbow (UNE) is the second most common entrapment neuropathy and presents with symptoms such as pain, paresthesia, and weakness in the elbow. Provocative tests and electrophysiological examinations are helpful in the diagnosis of UNE. Low-level laser therapy is one of the conservative treatments of UNE however, limited results were reported on the effectiveness of low-level laser therapy (LLLT) in the treatment of UNE. In our study, we aimed to the efficacy of LLLT in reducing symptoms and providing clinical and electrophysiological improvement in patients with UNE. This study with a randomized-sham controlled, and double-blind design included 68 patients aged 18-60 years who were diagnosed with UNE. LLLT was applied to the first group, and sham laser was applied to the second group. The VAS pain, paresthesia, and weakness scores, grip strength, and provocative test positivity were evaluated in clinical examination. The QuickDASH questionnaire was administered to assess functional status. Electrophysiologically, motor distal latency (MDL) differences, sensory distal latency (SDL), motor and sensory nerve conduction velocity (NCV) were examined. Evaluations were performed before treatment and on the 15th day and at the third month after treatment. The LLLT group showed improvement in symptoms, clinical findings, motor NCV, and MDL at both post-treatment evaluations and sensory NCV on the post-treatment 15th day (p < 0.05). The comparison of post-treatment changes between the two groups revealed that the LLLT group had greater improvement in VAS day and night pain scores at both post-treatment evaluation times, QuickDASH scores at the third month, and sensory NCV on the 15th day (p < 0.05) compared to the SL group. There were no significant differences between the groups in terms of the post-treatment changes in VAS weakness scores, grip strength and electrophysiological findings (p > 0.05). It was observed that splinting alone was effective in UNE, but the addition of LLLT, one of the conservative treatment methods, enhanced treatment outcomes."}],"keywords":["Electroneuromyography","Low-level laser therapy","Splint","Ulnar nerve entrapment"]},{"pmid":"39679116","title_fr":"Tecar et laser basse énergie dans la neuropathie diabétique des membres inférieurs : critères neurologiques","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[],"n":45,"effect":"mitigé","theme":"Neuropathie diabétique","l1":"Volet neurophysiologique du même essai de 45 diabétiques : l'association Tecar + laser améliore plus durablement la conduction motrice tibiale et l'index de pression systolique.","l2":"Mesures : vitesse de conduction motrice tibiale, amplitude du nerf sural, sensibilité plantaire, index cheville-bras, après 10 séances et à 3 mois. Le laser seul améliore la sensibilité plantaire et l'index cheville-bras.","l3":{"points":["Même population que PMID 40065850 : ne pas additionner les effectifs."],"limites":["Petits groupes."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Comparison of the effect of separate and simultaneous application of Tecar therapy and low-level laser therapy on the neurological symptoms of type 2 diabetic patients with peripheral neuropathy of lower limbs.","journal":"Turkish journal of physical medicine and rehabilitation","journal_abbr":"Turk J Phys Med Rehabil","authors":["Javan Amoli M","Khademi-Kalantari K","Niajalili M","et al."],"date":"2024-08-26","year":2024,"week":"2024-S35","doi":"10.5606/tftrd.2024.13419","pmcid":"PMC11639497","license":"cc by-nc","oa":true,"pdf":"pdfs/39679116.pdf","cited_by":0,"pub_types":[],"abstract":[{"label":"OBJECTIVES","text":"The study aimed to compare the effects of separate and simultaneous application of Tecar therapy and low-level laser therapy on neurological symptoms of type 2 diabetic patients."},{"label":"PATIENTS AND METHODS","text":"In this randomized control trial conducted between November 2021 and February 2022, 45 patients (30 females, 15 males; mean age: 65.7±7.6 years; range, 51 to 76 years) with type 2 diabetes and peripheral sensory neuropathy of the lower limbs were randomly divided into three groups: Tecar + sham laser (n=15), Tecar + laser (n=15), and laser + sham Tecar (n=15). Outcome measures for both right and left limbs included tibial motor nerve conduction velocity (MNCV), sural nerve amplitude, sole sensation, and ankle-brachial index (ABI) measured before and after 10 sessions and after a three-month follow-up."},{"label":"RESULTS","text":"In intergroup comparison, the Tecar + laser group significantly improved compared to the laser + sham Tecar group in terms of tibial MNCV in both limbs after 10 sessions and all measured outcomes after three months (p<0.05). In addition, comparison between the Tecar + laser and Tecar + sham laser groups for tibial MNCV (p=0.021 for the right limb and p=0.002 for the left limb) and ABI (p=0.001 for the right limb and p=0.002 for the left limb) in both limbs after three months was significant. In the intragroup comparison, a significant improvement was found in the laser + sham Tecar group for sole sensation (p<0.001) and ABI (p<0.001) of both limbs after three months compared to before the interventions, whereas in the other two groups, significant improvements were found in all four outcomes."},{"label":"CONCLUSION","text":"A significant increase was found in neurological outcomes in all three groups after 10 sessions. Moreover, the use of combined Tecar therapy and laser compared to Tecar or laser alone could lead to a more lasting effect in improving the sensory symptoms of type 2 diabetic patients with peripheral neuropathy of the lower limbs."}],"keywords":["Diabetic neuropathy","Tecar.","laser","nerve conduction velocity","neuropathy symptoms","sensation"]},{"pmid":"39186566","title_fr":"Efficacité et sécurité de la PBM dans la neuropathie diabétique : protocole de méta-analyse","type":"protocol","level":0,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"—","theme":"Synthèse des preuves","l1":"Protocole de méta-analyse des essais randomisés de PBM dans la neuropathie diabétique, incluant les bases chinoises. Résultats à surveiller.","l2":"Critères principaux : symptômes et vitesse de conduction ; secondaires : qualité de vie, douleur, glycémie, HbA1c, effets indésirables.","l3":{"points":["PROSPERO CRD42023466586."],"limites":["Protocole."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Effectiveness and safety of photobiomodulation therapy in diabetic peripheral neuropathy: Protocol for a systematic review and meta-analysis.","journal":"PloS one","journal_abbr":"PLoS One","authors":["Fan X","Yan G","Cao J","et al."],"date":"2024-08-26","year":2024,"week":"2024-S35","doi":"10.1371/journal.pone.0308537","pmcid":"PMC11346721","license":"cc by","oa":true,"pdf":"pdfs/39186566.pdf","cited_by":2,"pub_types":["Research Support, Non-U.S. Gov't"],"abstract":[{"label":"INTRODUCTION","text":"Diabetic peripheral neuropathy (DPN), a widely prevalent complication in patients with type 2 diabetes, exerts a significant influence on patients' overall health and financial circumstances. Photobiomodulation therapy is one of the means of physical therapy for DPN. Although preliminary findings suggest the efficacy of photobiomodulation therapy in alleviating peripheral neuropathy, the existing literature lacks substantial evidence regarding its safety and effectiveness specifically in the context of diabetes-related peripheral neuropathy. Therefore, we plan to arrive at more distinct findings through systematic evaluation and meta-analysis."},{"label":"METHODS","text":"We will conduct a comprehensive search for studies published from the beginning until October 1, 2023, using various databases including Web of Science, Embase, Cochrane Library, PubMed, AMED, Wanfang database, VIP database, China National Knowledge Infrastructure, and the Chinese Biomedical Literature database. Simultaneously, we will also search for the WHO International Clinical Trial Registration Platform, China Clinical Trial Registration Platform, and Clinical Trials.gov. Gray literature will be retrieved using Google Scholar and opengrey.edu. Only randomized controlled trials in Chinese and English were included, with no restrictions on publication status. The primary outcomes will include change of symptom scores, change of nerve conduction velocity. Additional outcomes will encompass quality of life, change in pain, blood glucose levels after fasting and 2 hours after eating, levels of glycosylated hemoglobin, and any adverse events associated with photobiomodulation therapy. Reman V.5.4 and R language will be used for the meta-analysis. Assessment of potential bias will be conducted through Cochrane risk of bias 2 tool (RoB 2.0) and Physiotherapy Evidence Database (PEDro) scale. Registration: PROSPERO (registration number: CRD42023466586)."},{"label":"DISCUSSION","text":"This meta-analysis aims to assess the efficacy and safety of photobiomodulation therapy as a potential treatment for diabetic peripheral neuropathy (DPN), and providing a straightforward and convenient therapeutic for patients. Additionally, it expands the range of treatment alternatives available to healthcare professionals managing DPN."}],"keywords":[]},{"pmid":"39187036","title_fr":"Prévention et réversion de la douleur neuropathique par PBM proche infrarouge chez le rat mâle et femelle","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"les deux","mode":[],"nm":[850],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Une PBM à 850 nm, avant ou après la lésion du sciatique, diminue l'allodynie chez les rats des deux sexes, sans protéger la structure du nerf en microscopie électronique.","l2":"Deux minutes, trois fois par semaine, pendant 3 à 4 semaines. L'effet antalgique ne s'explique pas par une préservation des axones.","l3":{"points":["Moins de fibres C sous PBM."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Prevention and reversal of neuropathic pain by near-infrared photobiomodulation therapy in male and female rats.","journal":"Physiology & behavior","journal_abbr":"Physiol Behav","authors":["Chacur M","Rocha IRC","Harland ME","et al."],"date":"2024-08-24","year":2024,"week":"2024-S34","doi":"10.1016/j.physbeh.2024.114680","pmcid":"PMC11425085","license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Research Support, Non-U.S. Gov't","Research Support, N.I.H., Intramural"],"abstract":[{"label":"","text":"Pathological nociception arising from peripheral nerve injury impacts quality of life. Current therapeutics are generally ineffective. However, photobiomodulation therapy (PBMT) has shown promise in addressing this issue. We aimed to assess the potential anti-allodynic effects of 2 p.m. protocols, each applied transcutaneously over the peripheral nerve injury. In addition to evaluating nociceptive behavior, we also conducted morphological analysis using electron microscopy (EM) to investigate potential ultrastructural changes at the cellular level. We sought to determine, using the chronic constriction injury (CCI) model, whether our parameters could alleviate established allodynia and/or dampen allodynia development. Adult male and female rats with CCI or sham were treated with PBMT (850-nm wavelength) for 2 min, 3 times a week over three or four weeks across three studies, where PBMT began either before or after CCI. Allodynia was assessed prior to surgery and across weeks and, at the conclusion of the third study, sciatic nerve was processed for EM and histomorphometrically evaluated. The results showed that PBMT before versus after CCI injury yielded similar behaviors, effectively decreasing allodynia. Interestingly, these positive effects of PBMT do not appear to be accounted by protection of the sciatic injury site, based on EM. CCI reliably decreased axon size and the number of myelinated axons present in both PBMT and control groups. While PBMT reduced the number of C-fibers in CCI samples, no improvement in any measure was observed in response to PBMT."}],"keywords":["Allodynia","Chronic constriction injury","Electron microscopy","Histomorphometric analysis","Sciatic nerve"]},{"pmid":"39168867","title_fr":"La voie RAGE–NF-κB et l'inflammation dans la neuropathie diabétique sous PBM (rat)","type":"preclinical","level":5,"pop":"—","ctx":["diabète"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat diabétique, dix séances de PBM diminuent RAGE et NF-κB dans les nerfs périphériques et augmentent l'IL-10 anti-inflammatoire.","l2":"Modèle de diabète de type 1 induit par streptozotocine. TNF-α réduit dans le système nerveux central.","l3":{"points":["Axe RAGE/NF-κB modulé."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Unraveling the RAGE-NF-κB pathway: implications for modulating inflammation in diabetic neuropathy through photobiomodulation therapy.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ferreira NL","Rocha IRC","Chacur M"],"date":"2024-08-21","year":2024,"week":"2024-S34","doi":"10.1007/s10103-024-04171-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":10,"pub_types":[],"abstract":[{"label":"","text":"Diabetic peripheral neuropathy (DPN) is a primary complication observed in diabetes that severely affects quality of life. Recent evidence suggests that photobiomodulation (PBM) is a promising therapy against painful conditions and nerve damage. However, the effects of PBM on DPN remains mostly unknown. In the present study, we investigated the efficacy of PBM therapy in modulating proinflammatory cytokine expression in both central and peripheral nervous systems of rats with Streptozotocin (STZ)-induced type 1 diabetes. Male Wistar rats were allocated into control (naïve), diabetic (STZ), and treatment (STZ + PBM) groups. A single intraperitoneal (i.p.) injection of STZ (85 mg/kg) was administered for the induction of diabetes. Animals were subjected to 10 treatment sessions, every other day. The results herein presented indicate that PBM treatment diminishes Receptor for Advanced Glycation End-products (RAGE) and Nuclear Factor Kappa B (NF-ϰB) expression in peripheral nervous system and suppresses TNF-α expression in central nervous system tissues. Furthermore, PBM-therapy in diabetic rats also induces increased levels of the anti-inflammatory protein IL-10 in both peripheral and central nervous system. Collectively, our findings demonstrate compelling evidence that PBM-therapy modulates cytokine dynamics and influences RAGE/NF-ϰB axis in a STZ-induced model of type 1 diabetes."}],"keywords":["Diabetes mellitus","Inflammation","Neuropathy","Wistar rats"]},{"pmid":"39119125","title_fr":"Laser basse puissance comme adjuvant dans la paresthésie : deux cas","type":"cases","level":4,"pop":"adulte","ctx":["lésion nerveuse","orofaciale"],"aim":"traitement","mode":["laser"],"nm":[],"n":2,"effect":"favorable","theme":"Neuropathies orofaciales","l1":"Deux paresthésies après extraction dentaire nettement améliorées par laser basse puissance.","l2":"Cas péruviens rapportés en espagnol. Pas de mesure standardisée.","l3":{"points":["Traitement indolore, séances courtes."],"limites":["Deux cas."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"[Low power laser as an adjuvant to paresthesia. report of two cases].","journal":"Revista cientifica odontologica (Universidad Cientifica del Sur)","journal_abbr":"Rev Cient Odontol (Lima)","authors":["Brítez A","Martínez L","Sanabria V","et al."],"date":"2024-06-27","year":2024,"week":"2024-S26","doi":"10.21142/2523-2754-1202-2024-201","pmcid":"PMC11304851","license":"cc by","oa":true,"pdf":"pdfs/39119125.pdf","cited_by":0,"pub_types":["Case Reports","English Abstract"],"abstract":[{"label":"","text":"Tooth extraction or extraction is a common procedure in dental practice, although it is a common practice, it is not exempt from complications. Paraesthesia is defined as a neuropathy with altered sensations and permanent anesthesia. The case of two patients who attended the Department of Pathology at the Faculty of Dentistry with paresthesia is reported. Both were treated with low-power laser therapy, showing a significant improvement in their clinical condition. The application of low-power laser presents ideal benefits in various areas of the stomatological field. As it is a non-invasive, painless treatment and short sessions, the patient is encouraged to continue with the treatment until they are almost completely rehabilitated."}],"keywords":["laser therapy","paresthesia","surgery oral"]},{"pmid":"39801094","title_fr":"Fréquence et prise en charge des lésions nerveuses après pose d'implant mandibulaire : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["lésion nerveuse","orofaciale"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"—","theme":"Neuropathies orofaciales","l1":"Après implant mandibulaire, 12 % des patients ont une neuropathie à une semaine et 5 % à 3 mois (90 % et 42 % avec latéralisation du nerf) ; le laser fait partie des traitements proposés.","l2":"Revue de 38 études avec méta-analyse de prévalence. Le traitement le plus fréquent reste médicamenteux ; le laser et la dépose de l'implant sont les autres options.","l3":{"points":["Latéralisation du nerf : risque multiplié par 8."],"limites":["Qualité des études variable."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Prevalence and management of neuropathic injury caused by dental implant insertion in mandible: a systematic review.","journal":"Journal of oral & facial pain and headache","journal_abbr":"J Oral Facial Pain Headache","authors":["Réus JC","Pauletto P","Veronez FC","et al."],"date":"2024-06-12","year":2024,"week":"2024-S24","doi":"10.22514/jofph.2024.012","pmcid":"PMC11810661","license":"cc by","oa":true,"pdf":"pdfs/39801094.pdf","cited_by":1,"pub_types":["Systematic Review"],"abstract":[{"label":"","text":"To synthesize scientific knowledge regarding the prevalence of neuropathies and nerve injuries caused by dental implant placement in mandible and the available management. Observational and interventional studies evaluating neuropathies occurrence in adults who underwent dental implant surgery were included. Any neuropathy diagnostic was accepted. The searches were conducted in six databases and grey literature. Methodological quality was screened using the Joanna Briggs Institute. The resulting synthesis was a narrative summary, and prevalence meta-analyses were performed in MetaXL 5.3. Among 98 full texts assessed, 38 studies were included. Neuropathies were diagnosed by questionnaires and/or clinical assessment. Eighteen studies presented high, sixteen moderate, and four low methodological quality. In implant surgeries without nerve lateralization, 12% and 5% of the patients may experience neuropathy during the first week and after three months, respectively. In implant surgeries with nerve lateralization, the prevalence was from 90% in the first week to 42% after three months. Proposed management included drugs, laser therapy and dental implant removal. In mandible, the prevalence of neuropathies in dental implant surgeries without lateralization is lower when compared with those with lateralization (eight times more in both follow-up times). The most frequent treatment was pharmacologic management."}],"keywords":["Dental implant","Evidencebased dentistry","Inferior alveolar nerve","Neuralgia","Trigeminal nerve injuries"]},{"pmid":"38759478","title_fr":"PBM et douleur : estimation par modélisation des doses efficaces au niveau du nerf","type":"methodo","level":5,"pop":"—","ctx":["autres"],"aim":"traitement","mode":[],"nm":[633,808,830],"n":null,"effect":"—","theme":"Dosimétrie","key":true,"l1":"En modélisant la lumière qui atteint réellement le nerf, les auteurs séparent clairement les doses efficaces des doses inefficaces pour bloquer les petites fibres douloureuses.","l2":"Logiciel de propagation des photons appliqué à des jeux de données publiés (633 nm et 808–830 nm). Le seuil d'irradiance efficace dépend de la durée : séances courtes à forte irradiance, ou longues à faible irradiance.\n\nTravail utile pour expliquer l'hétérogénéité des essais : c'est la dose au nerf qui compte, pas la puissance de l'appareil.","l3":{"points":["Mécanisme supposé : blocage de la conduction des petites fibres."],"limites":["Modélisation à partir de données hétérogènes."],"pratique":"Adapter la dose à la profondeur du nerf ciblé."},"topic":"neuropathie-peripherique","title":"Photobiomodulation for pain relief: Model-based estimates of effective doses of light at the neural target.","journal":"Journal of photochemistry and photobiology. B, Biology","journal_abbr":"J Photochem Photobiol B","authors":["Buzza A","Tapas K","Anders J","et al."],"date":"2024-05-07","year":2024,"week":"2024-S19","doi":"10.1016/j.jphotobiol.2024.112929","pmcid":"PMC11482420","license":"cc by-nc-nd","oa":true,"pdf":"pdfs/38759478.pdf","cited_by":6,"pub_types":[],"abstract":[{"label":"INTRODUCTION","text":"Photobiomodulation (PBM) has been studied since the 1960s as a clinical tool. More recently, PBM has been observed to reduce compound action potential components and hypersensitivities associated with neuropathic pains. However, no definitive description of efficacious light parameters has been determined. Some reasons may be that previous meta-analyses and reviews have focused on emitter output rather than the light at the target tissue and have included data sets that are large but with notable variability (e.g., combining data from various disease etiologies, and data from PBM at various wavelengths). This fact has made it difficult to successfully define the range of effective parameters."},{"label":"METHODS","text":"In this study, photon propagation software was used to estimate irradiance at a target nerve using several published data sets chosen for their narrow criteria to minimize variability. Utilizing these estimates, effective and ineffective light irradiances at the nerve of interest for wavelengths of 633 nm or 808-830 nm were examined and estimated. These estimates are focused on the amount of light required to achieve a reduction in pain or a surrogate measure via a hypothesized nerve block mechanism."},{"label":"RESULTS","text":"Accounting for irradiance at the target nerve yielded a clear separation of PBM doses that achieved small-fiber nerve block from those that did not. For both the 633 nm group and the 808-830 group, the irradiance separation threshold followed a nonlinear path with respect to PBM application duration, where shorter durations required higher irradiances, and longer durations required lower irradiances. Using the same modeling methods, irradiance was estimated as a function of depth from a transcutaneous source (distance from skin surface) for emitter output power using small or large emitter sizes."},{"label":"CONCLUSION","text":"Taken together, the results of this study can be used to estimate effective PBM dosing schemes to achieve small-fiber inhibition for various anatomical scenarios."}],"keywords":["Dosimetry","Pain relief","Peripheral nerve","Photobiomodulation","Photon propagation"]},{"pmid":"40065850","title_fr":"Tecar et laser basse énergie, séparés ou combinés, dans la neuropathie diabétique : symptômes et qualité de vie à 3 mois","type":"rct","level":2,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[],"n":45,"effect":"mitigé","theme":"Neuropathie diabétique","l1":"Chez 45 diabétiques, l'association Tecar + laser donne l'effet le plus durable sur la douleur à 3 mois ; le laser seul fait moins bien que les groupes avec Tecar.","l2":"Essai iranien en double aveugle, trois groupes de 15, dix séances, suivi à 3 mois. Tous les groupes s'améliorent ; le laser seul améliore surtout la qualité de vie et les symptômes neuropathiques à 3 mois.\n\nMême essai que l'article sur les critères neurophysiologiques (PMID 39679116).","l3":{"points":["Critères : WHOQOL-BREF, EVA, Timed Up and Go, Michigan."],"limites":["Publications multiples d'un même essai."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Comparison of Tecar Therapy and Low-Level Laser Therapy Separately and Simultaneously on Clinical Symptoms and Health-Related Quality of Life in Individuals with Type 2 Diabetes: A 3-Month Follow-up Study.","journal":"International journal of endocrinology and metabolism","journal_abbr":"Int J Endocrinol Metab","authors":["Javan Amoli M","Khademi Kalantari K","Ahmadpour Emshi Z","et al."],"date":"2024-05-05","year":2024,"week":"2024-S18","doi":"10.5812/ijem-143135","pmcid":"PMC11892693","license":"cc by","oa":true,"pdf":"pdfs/40065850.pdf","cited_by":1,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Distal peripheral neuropathy (DPN) is a prevalent issue among patients with type 2 diabetes mellitus. Despite the widespread use of low-level laser therapy (LLLT) and limited use of Tecar therapy in physiotherapy for diabetics, the synergistic effect of these two interventions in a long-term follow-up has not yet been determined."},{"label":"OBJECTIVES","text":"This study aimed to compare the effects of Tecar therapy and LLLT separately and simultaneously over a 3-month follow-up period on clinical symptoms and health-related quality of life in individuals with type 2 diabetes and DPN."},{"label":"METHODS","text":"In this double-blind, randomized clinical trial, forty-five individuals with type 2 diabetes (30 women and 15 men) with DPN were randomly assigned to three groups of 15 people: Tecar-on + laser-sham, Tecar-on + laser-on, and laser-on + Tecar-sham. The patients received ten treatment sessions and were followed up for 3-months after the last session. Health-related quality of life was assessed using the WHOQOL-BREF Questionnaire, while clinical symptoms, including pain (measured with a Visual Analog Scale), functional balance (evaluated with the timed-up and go test), and neuropathy symptoms (assessed with the Michigan Questionnaire) were also recorded."},{"label":"RESULTS","text":"Inter-group comparison after ten sessions revealed that the Tecar-on + laser-sham and Tecar-on + laser-on groups exhibited significant improvement in neuropathy symptoms compared to the laser-on + Tecar-sham group. Even after the 3-month follow-up, these two groups showed lasting improvement in all variables compared to the laser-on + Tecar-sham group (P < 0.05). The Tecar-on + laser-on group demonstrated a more enduring significant effect on pain scores (P = 0.035) compared to the Tecar-on + laser-sham group after the 3-month follow-up. In intra-group comparison, all three groups showed significant improvement in clinical symptoms and health-related quality of life after ten treatment sessions compared to before treatment (P < 0.05). Moreover, after the 3-month follow-up, both the Tecar-on + laser-sham group and the Tecar-on + laser-on group demonstrated a more lasting significant effect in all variables compared to before treatment (P < 0.05). For the laser-on + Tecar-sham group, a more durable improvement in health-related quality of life (P = 0.000) and neuropathy symptoms (P = 0.011) was reported after the 3-month follow-up compared to before treatment."},{"label":"CONCLUSIONS","text":"Although all three groups exhibited significant improvement in clinical symptoms and health-related quality of life in individuals with type 2 diabetes and DPN after ten treatment sessions, the synergistic use of Tecar therapy and LLLT after a long-term follow-up period could lead to more durable therapeutic effects in improving these outcomes for individuals with diabetes."}],"keywords":["Low Power Laser Therapy","Neuropathy Symptoms","Peripheral Neuropathy","Quality of Life","Tecar Therapy","Type 2 Diabetes"]},{"pmid":"38157112","title_fr":"Le laser Nd:YAG pulsé favorise la régénération nerveuse en inhibant l'apoptose (rat)","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":["haute puissance"],"nm":[1064],"n":54,"effect":"favorable","theme":"Préclinique","l1":"Après écrasement du sciatique chez le rat, le laser Nd:YAG pulsé réduit l'apoptose et améliore la fonction et la densité axonale à 4 semaines.","l2":"54 rats, 500 J par jour pendant 9 jours. Indice fonctionnel du sciatique meilleur dès la première semaine.","l3":{"points":["Moins de cellules TUNEL positives à S1."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"The Pulsed Nd:YAG Laser Therapy Enhanced Nerve Regeneration via Apoptosis Inhibition in a Rat Crushed Sciatic Nerve Model.","journal":"Neurochemical research","journal_abbr":"Neurochem Res","authors":["Ko PY","Hsu CC","Chen SY","et al."],"date":"2024-04-01","year":2024,"week":"2024-S14","doi":"10.1007/s11064-023-04068-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":[],"abstract":[{"label":"","text":"The study was aimed to validate the efficacy of the pulsed Nd:YAG laser on nerve regeneration in a rat sciatic nerve crushed model. 54 Wistar rats were randomly assigned into three groups: shame control, crush control, and laser treated group. For the laser treated group, the pulsed Nd:YAG laser (10 Hz) with 350 mJ per pulse in energy density and 50 J/cm2 in fluence was applied extracorporeally at the lesion site for 12 min to daily deliver 500 J immediately and consecutive 9 days following the crush injury. At week 1, the apoptosis-related activities in the injured nerve were examined (n = 8/each group). The sciatic functional index (SFI) was measured preoperatively and weekly until 4 weeks after the index procedure. The injured nerve and the innervated gastrocnemius muscle histology were assessed at week 4 (n = 10/each group). At week 1, the laser group showed the significant less TUNEL-positive ratio (P < 0.05), and the lower expression of cleaved caspase3/procaspase-3 and beclin-2/beclin-2-associated protein X ratios compared with the crush control. Furthermore, the laser group revealed significantly better SFI since week 1 and throughout the study (P < 0.05, all) compared with the crush control. At week 4, the laser group showed significantly higher axon density, lower myelin g-ratio, and the corresponding higher glycogen expression (P < 0.05, all) in the gastrocnemius muscle compared with those in the crush control. The pulsed Nd:YAG might enhance the injured nerve regeneration via apoptosis inhibition."}],"keywords":["Animal model","Apoptosis","High intensity laser therapy","Nd:YAG","Peripheral nerve injury"]},{"pmid":"38567306","title_fr":"Le diabète sous les projecteurs : connaissances et perspectives de la PBM","type":"review","level":5,"pop":"adulte","ctx":["diabète"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Revue générale","l1":"Revue : 87 essais cliniques de PBM dans le diabète sont recensés ; dans la neuropathie, ils montrent une baisse de la douleur et un possible gain de qualité de vie.","l2":"Revue des études précliniques et cliniques et des essais enregistrés (5 837 patients prévus). Elle signale aussi un effet sur la glycémie sans risque d'hypoglycémie.","l3":{"points":["Variabilité des paramètres."],"limites":["Revue narrative."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Diabetes in spotlight: current knowledge and perspectives of photobiomodulation utilization.","journal":"Frontiers in endocrinology","journal_abbr":"Front Endocrinol (Lausanne)","authors":["Perrier Q","Moro C","Lablanche S"],"date":"2024-03-19","year":2024,"week":"2024-S12","doi":"10.3389/fendo.2024.1303638","pmcid":"PMC10985212","license":"cc by","oa":true,"pdf":"pdfs/38567306.pdf","cited_by":15,"pub_types":["Review"],"abstract":[{"label":"INTRODUCTION","text":"Diabetes is a global health concern characterized by chronic hyperglycemia resulting from insulinopenia and/or insulin resistance. The rising prevalence of diabetes and its associated complications (ulcers, periodontitis, healing of bone defect, neuropathy, retinopathy, cardiopathy and nephropathy) necessitate innovative therapeutic approaches. Photobiomodulation (PBM), involves exposing tissues and cells to low-energy light radiation, leading to biological effects, largely via mitochondrial activation."},{"label":"METHODS","text":"This review evaluates preclinical and clinical studies exploring the potential of PBM in diabetes and its complications, as well all clinical trials, both planned and completed, available on ClinicalTrials database."},{"label":"RESULTS","text":"This review highlights the variability in PBM parameters across studies, hindering consensus on optimal protocols. Standardization of treatment parameters and rigorous clinical trials are needed to unlock PBM's full therapeutic potential. 87 clinical trials were identified that investigated PBM in diabetes mellitus (with 5,837 patients planned to be treated with PBM). Clinical trials assessing PBM effects on diabetic neuropathy revealed pain reduction and potential quality of life improvement. Studies focusing on wound healing indicated encouraging results, with PBM enhancing angiogenesis, fibroblast proliferation, and collagen density. PBM's impact on diabetic retinopathy remains inconclusive however, requiring further investigation. In glycemic control, PBM exhibits positive effects on metabolic parameters, including glucose tolerance and insulin resistance."},{"label":"CONCLUSION","text":"Clinical studies have reported PBM-induced reductions in fasting and postprandial glycemia without an increased hypoglycemic risk. This impact of PBM may be related to its effects on the beta cells and islets in the pancreas. Notwithstanding challenges, PBM emerges as a promising adjunctive therapy for managing diabetic neuropathy, wound healing, and glycemic control. Further investigation into its impact on diabetic retinopathy and muscle recovery is warranted."}],"keywords":["diabetes","glycemic control","neuropathy","periodontitis","photobiomodulation","retinopathy","wound healing"]},{"pmid":"37858427","title_fr":"La photobiomodulation dans la prévention et la prise en charge des effets secondaires des traitements anticancéreux (Bulletin du Cancer)","type":"sr","level":3,"pop":"mixte","ctx":["CIPN"],"aim":"les deux","mode":[],"nm":[],"n":null,"effect":"mitigé","theme":"Neuropathie chimio-induite","l1":"Synthèse française : pour la neuropathie chimio-induite, les études sont trop rares pour un niveau de preuve solide, contrairement à la mucite ou au lymphœdème.","l2":"Revue systématique des études prospectives. La PBM est efficace en essais randomisés pour la mucite, l'épithélite et le lymphœdème ; pour la neuropathie périphérique, le niveau de preuve reste faible.\n\nLes auteurs définissent des paramètres de pratique sûre et recommandent la prudence près d'une tumeur.","l3":{"points":["Neuropathie : études limitées, preuve affaiblie."],"limites":["Recherche antérieure aux essais 2025–2026."],"pratique":"Référence francophone ; les essais récents (NEUROLIGHT, étude brésilienne) commencent à combler ce manque."},"topic":"neuropathie-peripherique","title":"[Photobiomodulation in the prevention and the management of side effects of cancer treatments: Bases, results and perspectives].","journal":"Bulletin du cancer","journal_abbr":"Bull Cancer","authors":["Lairedj K","Klausner G","Robijns J","et al."],"date":"2024-03-01","year":2024,"week":"2024-S09","doi":"10.1016/j.bulcan.2023.08.011","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["English Abstract","Review"],"abstract":[{"label":"BACKGROUND","text":"Assess the current and potential indications of photobiomodulation (PBM) therapy and their level of evidence in the prevention or treatment of side effects related to oncology treatments (radiation therapy, and to a minimal extent favored and hematopoietic stem cell transplants). And report on the recommended modalities (parameters and doses) of PBM therapy."},{"label":"MATERIALS AND METHODS","text":"The Embase, Medline/PubMed, Cochrane, EBSCO, Scopus, and LILACS databases were systematically reviewed to include and analyze publications of clinical studies that evaluated PBM in the prevention or management side effects related to cancer treatments. The keywords used were \"photobiomodulation\"; \"low level laser therapy\"; \"acute oral mucositis\"; \"acute dysphagia\"; \"acute radiation dermatitis\"; \"lymphedema\"; \"xerostomia\"; \"dysgeusia\"; \"hyposalivation\"; \"lockjaw\"; \"bone necrosis\"; \"osteoradionecrosis\"; \"radiation induced fibrosis\"; \"voice and speech alterations\"; \"palmar-plantar erythrodysesthesia\"; \"graft versus host disease\"; \"peripheral neuropathy\"; \"chemotherapy induced alopecia\". Prospective studies were included, while retrospective cohorts and non-original articles were excluded from the analysis."},{"label":"RESULTS","text":"PBM in the red or infrared spectrum has been shown to be effective in randomized controlled trials in the prevention and management of certain complications related to radiotherapy, in particular acute mucositis, epitheliitis and upper limb lymphedema. The level of evidence associated with PBM was heterogeneous, but overall remained moderate. The main limitations were the diversity and the lack of precision of the treatment protocols which could compromise the efficiency and the reproducibility of the results of the PBM. For other effects related to chemo/radiation therapy (dysgeusia, osteonecrosis, peripheral neuropathy, alopecia, palmar-plantar erythrodysaesthesia) and haematopoietic stem cell transplantation (graft versus host disease), treatment with PBM suffers from a lack of studies or limited studies at the origin of a weakened level of proof. However, based on these results, it was possible to establish safe practice parameters and doses of PBM."},{"label":"CONCLUSION","text":"Published data suggest that PBM could therefore be considered as supportive care in its own right for patients treated with radiation, chemotherapy, immunotherapy, hormone therapy or targeted therapies, whether in clinical practice or clinical trials. therapies. However, until solid data have been published on its long-term safety, the use of PBM should be considered with caution and within the recommended parameters and doses, particularly when practiced in areas of known or possible tumours. In this case, the patient should be informed of the theoretical benefits and risks of PBM in order to obtain informed consent before treatment."}],"keywords":["Chemotherapy","Effets secondaires des anticancéreux","Low-level light therapy","Mucite","Neoplasms","Neuropathies périphériques post-chimiothérapie","Photobiomodulation","Photobiomodulation (PBM)","Radiation therapy","Radiodermite"]},{"pmid":"38351691","title_fr":"Chaussure laser de PBM pour la douleur neuropathique et les pressions plantaires du diabétique","type":"nrct","level":4,"pop":"adulte","ctx":["diabète"],"aim":"traitement","mode":["laser"],"nm":[],"n":60,"effect":"favorable","theme":"Nouveaux dispositifs","l1":"Chez 60 diabétiques, une chaussure laser qui irradie tout le pied réduit la douleur neuropathique et les pressions plantaires.","l2":"Dispositif indien à faible coût. Améliorations du seuil vibratoire, de l'EVA, du score de Michigan et de l'index cheville-bras. Étude sans groupe témoin.","l3":{"points":["Âge moyen 62 ans, diabète depuis 11 ans."],"limites":["Pas de témoin."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Effect of Novel Laser Shoe Photobiomodulation on Neuropathic Pain and Plantar Pressure Profile in Type 2 Diabetes Mellitus with Peripheral Neuropathy.","journal":"Current diabetes reviews","journal_abbr":"Curr Diabetes Rev","authors":["Maiya GA","Jadhav RA","Yadav KH","et al."],"date":"2024-02-14","year":2024,"week":"2024-S07","doi":"10.2174/0115733998244000231106040749","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":[],"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation (PBM) or Low-level laser is used to treat diabetic foot complications. The existing method of laser application to the foot did not cover the foot's entire area to improve the foot's microcirculation. Therefore, we have developed a cost-effective Special LASER Shoe device, focusing exclusively on the entire foot region to manage neuropathic pain and other symptoms in individuals with type 2 diabetes mellitus."},{"label":"OBJECTIVE","text":"The main objective of the present study was to evaluate the effect of this newly developed special laser shoe PBM on neuropathic pain and plantar pressure profile in individuals with type 2 diabetes mellitus with neuropathy."},{"label":"METHODS","text":"We included 60 participants with diabetic peripheral neuropathy of both genders and age more than 20 years. Participants were treated with PBM by a specially designed novel Laser Shoe. Outcomes were clinical variables like Vibration Perception Threshold (VPT), Visual Analogue Scale (VAS), Michigan neuropathy screening instrument A&B, Ankle-Brachial Index (ABI), and Static dynamic gait parameters."},{"label":"RESULTS","text":"Participants were with an average age of 62, and the average duration of diabetes was 11 years. Analysis showed a significant difference in VPT, VAS, Michigan neuropathic screening inventory, and ankle-brachial index (P < 0.05)."},{"label":"CONCLUSION","text":"We conclude that Novel laser shoe photobiomodulation using 'Laser Shoe' effectively reduces peripheral neuropathic pain. It is also effective in reducing average and maximum plantar pressure. Reduction in neuropathic pain and improvement in plantar pressure distribution can reduce further complications."}],"keywords":["Low-level laser therapy","diabetes","neuropathic pain.","neuropathy","photobiomodulation","spatiotemporal gait parameters"]},{"pmid":"38278695","title_fr":"Ondes de choc versus laser basse énergie ajoutés à la kinésithérapie dans le canal carpien léger à modéré","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":36,"effect":"neutre","theme":"Canal carpien","l1":"Dans le canal carpien léger à modéré, le laser et les ondes de choc réduisent autant la douleur (−4,4 points) ; les ondes de choc réduisent un peu plus le gonflement du nerf.","l2":"Essai iranien en simple aveugle ; seuls 18 patients sur 36 ont terminé. Critère principal : section du nerf médian à l'échographie.","l3":{"points":["Section : −1,2 mm² (ondes de choc) contre −0,76 mm² (laser)."],"limites":["Forte attrition, pas de bras sans technique."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"A randomized clinical trial on the changing of median nerve cross-sectional area and pain after extracorporeal shock wave and low-level laser therapy added to conventional physical therapy in patients with mild-to-moderate carpal tunnel syndrome.","journal":"Journal of hand therapy : official journal of the American Society of Hand Therapists","journal_abbr":"J Hand Ther","authors":["Ghasemi A","Olyaei GR","Bagheri H","et al."],"date":"2024-01-25","year":2024,"week":"2024-S04","doi":"10.1016/j.jht.2023.12.009","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"abstract":[{"label":"BACKGROUND","text":"Carpal tunnel syndrome (CTS) is the most common mononeuropathy in the upper limb. It remains uncertain whether adding extracorporeal shockwave therapy (ESWT) or low-level laser therapy (LLLT) to conventional treatment benefits CTS patients."},{"label":"PURPOSE","text":"This study aimed to compare the effectiveness of ESWT and LLLT in conjunction with conventional treatments (including carpal mobilization, transcutaneous electrical nerve stimulation, and ultrasound) on the cross-sectional area (CSA) of the median nerve and pain in mild-to-moderate CTS patients."},{"label":"STUDY DESIGN","text":"This was a single-blinded randomized clinical trial with registration number IRCT20220504054734N1."},{"label":"METHODS","text":"Thirty-six patients were randomly assigned using block balanced randomization to receive either four sessions of ESWT or 10 sessions of LLLT in addition to 10 sessions of conventional treatments over 2 weeks. Patients received numbered closed envelopes indicating their treatment group. CSA (primary) and pain (secondary) in 18 patients who completed the treatment were assessed at baseline and after 2 weeks by a blinded assessor. Paired and independent sample t-tests were used for analyses due to the normal distribution of data was checked by Kolmogorov-Smirnoff. Cohen's d effect size was used to assess the intervention's magnitude."},{"label":"RESULTS","text":"Both ESWT and LLLT groups showed significant improvements in CSA (p = 0.002) and pain (p < 0.001) from baseline to posttreatment. CSA improvement was moderate for ESWT (mean difference: 1.2, 95% CI 0.51-1.9) and mild for LLLT (mean difference: 0.76, 95% CI 0.4-1.14). Conversely, pain improvement was substantial in both groups (ESWT: mean difference 4.4, 95% CI 3.6-5.3; LLLT: mean difference 4.4, 95% CI 3.7-5.2). No substantial differences between ESWT and LLLT were observed, highlighting their comparable efficacy."},{"label":"CONCLUSION","text":"The addition of either LLLT or ESWT to conventional treatment effectively reduced pain and median nerve CSA in mild-to-moderate CTS. The absence of significant differences between ESWT and LLLT indicates their comparable efficacy in pain relief and CSA reduction."}],"keywords":["Carpal tunnel syndrome","Cross-sectional area","Extracorporeal shock wave therapy","Low-power laser","Visual analog scale"]},{"pmid":"38239124","title_fr":"Apport de la phonophorèse et du laser aux exercices dans le canal carpien modéré","type":"rct","level":2,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["laser"],"nm":[],"n":45,"effect":"neutre","theme":"Canal carpien","l1":"Chez 45 patients, ni la phonophorèse ni le laser n'apportent de bénéfice supplémentaire aux exercices de glissement tendineux et nerveux dans le canal carpien modéré.","l2":"Trois groupes de 15, évaluations clinique, électrophysiologique et échographique à 6 et 12 semaines. Tous s'améliorent de façon similaire.","l3":{"points":["Section du nerf médian réduite dans tous les groupes à S12."],"limites":["Petits groupes."],"pratique":"Résultat négatif à garder en tête : les exercices seuls sont déjà efficaces."},"topic":"neuropathie-peripherique","title":"Additional contribution of phonophoresis and low-level laser therapy to exercise in the treatment of carpal tunnel syndrome: A clinical, electrophysiological, and ultrasonographic evaluation.","journal":"Agri : Agri (Algoloji) Dernegi'nin Yayin organidir = The journal of the Turkish Society of Algology","journal_abbr":"Agri","authors":["Karaman N","Ünlü Z","Selçuki D","et al."],"date":"2024-01-19","year":2024,"week":"2024-S03","doi":"10.14744/agri.2023.00878","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"abstract":[{"label":"OBJECTIVES","text":"Carpal Tunnel Syndrome (CTS) is the most common peripheral nerve compression syndrome. This study aims to evaluate the additive contribution of phonophoresis and low-level laser therapy (LLLT) to tendon and nerve gliding exercises electrophysiologically, ultrasonographically, and clinically in the treatment of moderate CTS."},{"label":"METHODS","text":"The sample consisted of 45 patients with moderate CTS, randomized into three groups. Group 1 received phonophoresis and exercise, Group 2 received LLLT and exercise, and Group 3 received exercise alone. Participants were evaluated electrophysiologically, clinically, and ultrasonographically before treatment and at the 6th and 12th weeks after the treatment."},{"label":"RESULTS","text":"An improvement was observed in clinical parameters (Boston Functional Status Scale, Boston Symptom Severity Scale, visual analog scale at rest, and visual analog scale during activity) for all groups at the 6th and 12th weeks after the treatment (p<0.05). An improvement was also noted in the ultrasonographic parameter (cross-sectional area) for all groups at the 12th week after the treatment (p=0.017)."},{"label":"CONCLUSION","text":"Phonophoresis and LLLT do not provide additional effects to exercise therapy. Exercise therapy alone may positively contribute to ultrasonographic and clinical outcomes in the treatment of moderate CTS."}],"keywords":[]},{"pmid":"38207201","title_fr":"Laser haute intensité dans le canal carpien : revue systématique et méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["compression"],"aim":"traitement","mode":["haute puissance"],"nm":[],"n":308,"effect":"favorable","theme":"Canal carpien","l1":"Études de 16 à 98 patients (308 au total) : preuve modérée d'efficacité à court terme du laser haute intensité sur la douleur du canal carpien ; données à long terme limitées.","l2":"À 4 semaines, le laser haute intensité est supérieur au placebo, à la TENS, au laser basse intensité à 20 J/cm² et aux exercices pour la douleur. Effet électrophysiologique incertain, sauf pour le potentiel d'action sensitif et la vitesse de conduction sensitive.","l3":{"points":["Douleur : p = 0,0191 contre placebo."],"limites":["Suivis courts."],"pratique":"Voir aussi la méta-analyse de 2025 sur le même sujet."},"topic":"neuropathie-peripherique","title":"Effect of High-Intensity Laser Therapy on Carpal Tunnel Syndrome Patients: A Systematic Review and Meta-analysis.","journal":"American journal of physical medicine & rehabilitation","journal_abbr":"Am J Phys Med Rehabil","authors":["ElMeligie MM","Ismail MM","Gomaa YS","et al."],"date":"2024-01-06","year":2024,"week":"2024-S01","doi":"10.1097/PHM.0000000000002427","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review","Meta-Analysis"],"abstract":[{"label":"OBJECTIVE","text":"To provide a strong foundation for the use of high-intensity laser therapy in carpel tunnel syndrome, we conducted a systematic review and meta-analysis to investigate the outcomes of short- and long-term follow-up studies."},{"label":"DESIGN","text":"This is a systematic review and meta-analysis."},{"label":"RESULTS","text":"Sample sizes of included studies ranged from 16 to 98 patients ( N = 308). Overall, a significant difference between the treatment and control groups were found across majority of the measures. Studies using a 4-wk follow-up period, however, only found significantly greater benefits for high-intensity laser therapy in visual analog scale compared with placebo ( P = 0.0191), transcutaneous electrical nerve stimulation ( P = 0.0026), and low-intensity laser therapy 20 J/cm 2 ( P < 0.0002), and exercise ( P < 0.0001). For improvement in visual analog scale score over a long treatment period, high-intensity laser therapy was also preferred over control group ( P < 0.0071). Insufficient evidence exists to determine effect of high-intensity laser therapy on nerve conduction examinations. The only statistically significant differences observed in examinations were in relation to sensory nerve action potential ( P = 0.0083) and sensory nerve conduction velocity ( P = 0.0468)."},{"label":"CONCLUSIONS","text":"Moderate evidence exists regarding efficacy of high-intensity laser therapy compared with placebo, high-intensity laser therapy + wrist splint, and exercise in a short period of follow-up time but evidence on long-term follow-up is limited."}],"keywords":[]},{"pmid":"37332186","title_fr":"Facteurs épigénétiques et de douleur après PBM dans un modèle de douleur neuropathique","type":"preclinical","level":5,"pop":"—","ctx":["lésion nerveuse"],"aim":"traitement","mode":[],"nm":[],"n":null,"effect":"favorable","theme":"Préclinique","l1":"Chez le rat, la PBM ramène le seuil douloureux près de la normale en trois semaines et augmente TGF-β et GAD65, sans modifier les enzymes épigénétiques étudiées.","l2":"Première étude des facteurs épigénétiques (HDAC, DNMT) sous PBM dans la douleur neuropathique : résultat négatif sur ces cibles.","l3":{"points":["Allodynie et hyperalgésie réduites avec deux protocoles."],"limites":["Modèle animal."],"pratique":"—"},"topic":"neuropathie-peripherique","title":"Evaluation of epigenetic (HDAC, DNMT) and pain (Gad65, TGF) factors following photobiomodulation therapy in a neuropathic pain model.","journal":"Photochemistry and photobiology","journal_abbr":"Photochem Photobiol","authors":["Behroozi Z","Kookli K","Ghadaksaz A","et al."],"date":"2024-01-01","year":2024,"week":"2024-S01","doi":"10.1111/php.13824","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":[],"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) is converted to the most common analgesic treatment before the whole mechanism is yet to be discovered. This study for the first time was designed to investigate alternations of epigenetic factors after pain and PBMT. The CCI model was chosen to induce pain. Pain evaluation tests including plantar, acetone, von Frey, and pinch were done weekly. Then spinal cord tissue was isolated for evaluating mRNA expression of DNMT3a, HDAC1, and NRSF using RT-qPCR method, and protein expression factors of HDAC2 and DNMT3a using western blotting. GAD65 and TGF-β proteins were assessed by the IHC method. PBMT increased the pain threshold up to the point where it roughly met the pain threshold of the control group. After three weeks of treatment, both PBMT protocols demonstrated a reduction in allodynia and hyperalgesia. While some molecules, such as TGF-β and Gad65, increased following PBMT, we observed no inhibition of NRSF, HDAC1, and DNMT3a expression despite implementing two different protocols."}],"keywords":["DNMT","HDAC","epigenetic","neuropathic pain","photobiomodulation therapy"]}],"syntheses":{"gynecologie":{"years":{"2020–2023":{"headline":"Les débuts : douleurs pelviennes, dysménorrhée et premières recommandations","l1":"De 2020 à 2023, la PBM en gynécologie se développe surtout dans la douleur pelvienne chronique (PBM transvaginale), la dysménorrhée et l'urogynécologie. Les recommandations françaises (CNGOF 2021) jugent les preuves insuffisantes, et une première cohorte française après cancer est encourageante.","l2":"Les essais randomisés de cette période donnent des résultats contrastés. Dans la douleur myofasciale pelvienne, la PBM 808 nm n'ajoute rien aux étirements vaginaux (103 femmes, double aveugle). Dans la dysménorrhée, la LED sur points d'acupuncture soulage presque autant que la pilule (156 femmes). En urogynécologie, un patch lumineux de phase III réduit les fuites par urgence, et des essais plus petits améliorent l'incontinence d'effort en complément de la rééducation.\n\nEn obstétrique, une séance unique de laser ne soulage pas plus les mamelons qu'un placebo (80 femmes). La PBM transvaginale montre de bons résultats en cohortes (douleur pelvienne chronique, cystite interstitielle), sans groupe témoin. Après cancer, la cohorte du CHU de Nîmes (Bulletin du Cancer 2023) rapporte 72 % de patientes améliorées. Les recommandations CNGOF/GEMVi de 2021 ne recommandent pas les lasers ablatifs en première ligne et jugent les données sur la PBM trop faibles.","l3":[{"h":"Douleurs pelviennes","p":"PBM transvaginale : cohortes de 13, 128 et 140 femmes, avec 60 à 65 % de répondeuses. Mais l'essai contre simulation dans la douleur myofasciale (103 femmes) ne montre aucun bénéfice ajouté aux étirements. Dosimétrie chez la brebis : seulement 3 % de l'irradiance atteint le muscle releveur, ce qui pourrait expliquer les échecs à faible puissance."},{"h":"Dysménorrhée","p":"LED sur points CV4 et CV6 contre pilule (156 femmes) : 73,6 % contre 85,7 % de répondeuses (NS), pilule plus antalgique. Laser haute intensité équivalent au basse énergie (30 femmes)."},{"h":"Urogynécologie","p":"Patch LED de phase III dans l'hyperactivité vésicale : fuites par urgence −1,0 contre −0,4 par jour. Laser-acupuncture dans l'hyperactivité vésicale et PBM + rééducation dans l'incontinence d'effort : petits essais favorables."},{"h":"Après cancer et recommandations","p":"CNGOF/GEMVi 2021 : lasers ablatifs non recommandés en première ligne (grade C), PBM insuffisamment évaluée. Cohorte de Nîmes (28 patientes) : 72 % améliorées. Deux cas de sténose vaginale post-radique traités par LED bleue."},{"h":"Fertilité (préclinique)","p":"Protection ovarienne contre le cyclophosphamide chez la souris, synéchies utérines, SOPK chez le rat : une base mécanistique pour l'oncofertilité."}]},"2024":{"headline":"Lichen scléreux, candidose et premiers protocoles randomisés","l1":"En 2024, de nouvelles indications vulvaires apparaissent : le lichen scléreux (100 femmes en complément des corticoïdes) et la candidose récidivante (LED bleue). Deux protocoles d'essais randomisés sont lancés dans le syndrome génito-urinaire de la ménopause, et l'ACOG rappelle la faiblesse des preuves.","l2":"Vulve : une cohorte danoise de 100 femmes avec lichen scléreux réfractaire améliore sa qualité de vie avec un laser 808 nm, et un laser bleu réduit prurit et fissures chez 12 patientes. Dans la candidose récidivante, un essai randomisé de 60 femmes montre que deux séances de LED bleue ajoutées à l'antifongique réduisent nettement la charge en Candida.\n\nMénopause : un laser diode non ablatif améliore sécheresse et dyspareunie à 6 mois (22 femmes), et deux protocoles d'essais contre placebo sont publiés ; leurs résultats sortiront en 2026. En obstétrique, la PBM fait mieux que la cryothérapie sur la douleur périnéale (56 femmes) et qu'une crème sur les crevasses (50 femmes), mais la méta-analyse sur les mamelons reste incertaine. La série d'experts de l'ACOG distingue clairement lasers ablatifs et PBM et ne retient pas de preuve forte pour la douleur pelvienne.","l3":[{"h":"Vulve et infections","p":"Lichen scléreux : 100 femmes, 10 séances de 808 nm, 7 domaines de qualité de vie sur 8 améliorés. Candidose : DM de 8,27 sur la charge en Candida avec LED bleue + antifongique."},{"h":"Ménopause","p":"Laser diode non ablatif : VHI 12 → 19,3, sécheresse 7,7 → 3,7. Protocoles PBM vulvaire 808 nm et PBM + rééducation."},{"h":"Obstétrique","p":"PBM supérieure à la cryothérapie (douleur à 24 h, p < 0,001). Crevasses : PBM supérieure à une crème anti-inflammatoire. Méta-analyse des mamelons : PBM contre placebo DM −0,15, incertain."},{"h":"Dysménorrhée et fertilité","p":"Chez l'animal, le rouge 630 nm pulsé est le plus efficace contre la dysménorrhée. Vieillissement ovarien amélioré chez la souris ; trois grossesses après PBM dans une série de cas d'infertilité inexpliquée."}]},"2025":{"headline":"Méta-analyses : favorable sur la dysménorrhée et l'allaitement, neutre sur le périnée","l1":"En 2025, les méta-analyses tranchent : la PBM réduit la douleur de la dysménorrhée (−4 points contre simulation) et la douleur des crevasses (OR 0,43), mais pas la douleur périnéale après accouchement. Un premier essai contre simulation est positif dans la vestibulodynie.","l2":"Dysménorrhée : la méta-analyse de 12 essais (645 femmes) montre une baisse de la douleur de 4 points à 12 semaines contre simulation. Allaitement : la méta-analyse de 7 essais est favorable (OR 0,43 sur la douleur de succion), alors qu'une autre plus ancienne, à 3 essais, ne l'était pas. Périnée : l'infrarouge aide un peu, mais pas le laser basse énergie (13 études), et une séance unique de PBM ne bat pas la simulation (60 femmes).\n\nVulve : l'essai canadien dans la vestibulodynie provoquée (30 femmes, 15 séances) réduit la douleur avec des tailles d'effet de 0,6 à 0,9, sans gain sur la sexualité. La lumière bleue soulage 79 % des candidoses récidivantes résistantes aux azolés. Ménopause : en France, la première étude chez l'humain de la sonde MILTA GYNECO montre une bonne tolérance et une dyspareunie réduite de moitié. En sénologie, la lumière bleue aide à cicatriser les plaies compliquées de reconstruction mammaire.","l3":[{"h":"Dysménorrhée","p":"Méta-analyse : DM −4,02 contre simulation à 12 semaines ; avantage contre la pilule. Laser-acupuncture équivalente à l'électroacupuncture (114 femmes)."},{"h":"Obstétrique","p":"Mamelons : OR 0,43 (7 ECR, certitude faible). Périnée : laser contre placebo DMS −0,31 (NS) ; séance unique non supérieure. Une séance ne suffit pas, et la dose semble déterminante."},{"h":"Vulve","p":"Vestibulodynie : premier ECR contre simulation positif sur la douleur. Candidose : 79 % d'amélioration immédiate, 58 % à 6 mois (62 femmes résistantes)."},{"h":"Ménopause et urogynécologie","p":"Sonde MILTA GYNECO : 146 événements mineurs sur 148, VHI 12,7 → 17,6, dyspareunie 7,7 → 3,9. Laser basse énergie dans l'incontinence d'effort et le syndrome génito-urinaire : cohorte de 41 femmes favorable."},{"h":"Après cancer et sénologie","p":"Lumière bleue sur plaies de reconstruction mammaire (27 patientes, 5 séances médianes). Infection de prothèse traitée par pression négative + PBM."}]},"2026":{"headline":"Les essais contre placebo arrivent dans la ménopause et après cancer du sein","l1":"En 2026, deux essais contre placebo montrent que la PBM intravaginale améliore l'incontinence et la sécheresse de la ménopause. Une étude brésilienne fait passer la douleur vaginale de 9,5 à 1/10 chez des femmes sous hormonothérapie pour cancer du sein. Sur le périnée post-partum, en revanche, les méta-analyses restent négatives.","l2":"Syndrome génito-urinaire : l'essai en double aveugle contre placebo (808 nm, 4 séances) réduit les fuites urinaires et la sécheresse ; un deuxième essai montre qu'ajoutée à la rééducation, la PBM améliore la sexualité (FSFI +4,6) et l'incontinence. Une étude taïwanaise (660 nm par sonde) ramène toutes les patientes au-dessus du seuil d'atrophie. Après cancer : la PBM LED bleu + rouge soulage presque complètement la douleur vaginale sous inhibiteurs de l'aromatase (24 femmes, groupe d'observation non traité).\n\nVulvodynie : la méta-analyse en réseau de 34 essais classe les thérapies tissulaires, PBM comprise, en tête contre placebo ; une cohorte française ne trouve que 52 % de succès. Obstétrique : quatre méta-analyses et un essai en double aveugle ne trouvent pas de bénéfice du laser sur la douleur périnéale, alors qu'un essai sur les mamelons est positif. La consultation internationale de médecine sexuelle (ICSM) juge les preuves encore insuffisantes pour recommander la PBM.","l3":[{"h":"Ménopause","p":"Essai contre placebo 808 nm : fuites et ICIQ-SF améliorés, sexualité inchangée. PBM + rééducation : FSFI DM 4,55, ICIQ-SF −3,06. Étude 660 nm : 100 % au-dessus du seuil non atrophique à 3 mois, mais seulement 13 % retrouvent une fonction sexuelle normale."},{"h":"Après cancer","p":"Cancer du sein sous hormonothérapie : EVA 9,46 → 1,04, QS-F 23 → 87. Rappel radique après cisplatine dans un cancer du col : amélioration en une semaine avec une PBM multi-longueurs d'onde."},{"h":"Vulve","p":"Méta-analyse en réseau vulvodynie : thérapies tissulaires POMP −16 contre placebo (confiance modérée), en tête du classement. LED 415 nm efficace dans un modèle de vaginose bactérienne."},{"h":"Obstétrique","p":"Périnée : 4 méta-analyses (LLLT contre placebo DM 0,03 ; DMS 0,04 ; DMS −0,16) et un ECR à 660 nm sans bénéfice, mais moins d'antalgiques ; une cohorte portugaise (808 nm, lésions de grade 2–3) est positive. Mamelons : ECR multicentrique positif dès 30 minutes."},{"h":"Fertilité","p":"Ovocytes humains immatures : maturation deux fois plus rapide sous 810 nm, sans stress oxydatif. LED portable 630 nm : compte de follicules antraux 2 → 6 dans un pilote."}]}},"global":{"headline":"2020 → 2026 : ce que la PBM apporte, ou non, en gynécologie","l1":"Sur sept ans, la PBM gynécologique se précise. Elle est la mieux étayée dans la dysménorrhée, les crevasses de l'allaitement, la sécheresse et l'incontinence de la ménopause, et dans la vulvodynie. Elle ne fait pas ses preuves sur la douleur périnéale après accouchement. Après cancer, les résultats sont spectaculaires mais encore non randomisés.","l2":"Ce qui se confirme : dysménorrhée (méta-analyse 2025, −4 points contre simulation), crevasses (méta-analyse 2025, OR 0,43 ; essai 2026 positif), syndrome génito-urinaire de la ménopause (deux essais contre placebo en 2026, effet net sur l'incontinence et la sécheresse), vulvodynie (essai contre simulation 2025, méta-analyse en réseau 2026). Ce qui ne se confirme pas : la douleur périnéale post-partum (quatre méta-analyses négatives), et l'ajout de la PBM aux étirements dans la douleur myofasciale pelvienne.\n\nCe qui est prometteur : la sécheresse et la douleur vaginale après cancer (cohorte de Nîmes 2023, cancer du sein sous hormonothérapie 2026), la candidose récidivante (LED bleue) et le lichen scléreux réfractaire. En fertilité, tout reste préclinique ou pilote. Les recommandations (CNGOF 2021, ICSM 2024/2026) restent prudentes : la PBM est une option complémentaire, sans indication validée en première ligne.","l3":[{"h":"1. Une différence essentielle : PBM et lasers ablatifs","p":"Les lasers vaginaux CO2 et Er:YAG (ablatifs, thermiques) dominent la littérature et ne sont pas de la PBM ; ils sont exclus de ce thème. Les recommandations françaises et l'ACOG les évaluent séparément. La PBM utilise des puissances faibles (rouge, proche infrarouge, bleu) sans destruction tissulaire."},{"h":"2. Sécheresse et ménopause : le sous-groupe qui progresse le plus","p":"Il n'y avait que des protocoles en 2024. En 2026, deux essais contre placebo positifs sur l'incontinence et les symptômes vaginaux, et une étude à 660 nm avec normalisation de l'index de santé vaginale. La fonction sexuelle reste le critère le moins amélioré."},{"h":"3. Après cancer : un besoin fort, des preuves en construction","p":"Les œstrogènes locaux sont souvent évités après cancer du sein. La PBM y montre des résultats spectaculaires (douleur 9,5 → 1/10), mais dans des études non randomisées. Un essai contre placebo est la priorité. Les données in vitro sur cellules de cancer gynécologique sont plutôt rassurantes, mais limitées."},{"h":"4. Obstétrique : allaitement oui, périnée non","p":"Sur les crevasses, les essais à plusieurs séances sont positifs, alors qu'une séance unique ne suffit pas. Sur le périnée, la convergence des méta-analyses de 2025–2026 est négative ; la cryothérapie reste le premier choix. Pendant la grossesse, faute de données, la PBM abdominopelvienne est à éviter hors protocole."},{"h":"5. Vulve et douleurs pelviennes","p":"Vulvodynie : premier essai contre simulation positif (2025) et méta-analyse en réseau favorable (2026), avec environ une répondeuse sur deux en pratique. Dysménorrhée : méta-analyse favorable ; la LED est presque aussi efficace que la pilule, sans hormones. Candidose récidivante : la LED bleue 415 nm est un adjuvant prometteur."}],"table":{"cols":["2020–2023","2024","2025","2026"],"rows":[{"label":"Sécheresse / ménopause","cells":["Incontinence : petits ECR ; patch phase III (hyperactivité vésicale)","Diode non ablatif ; 2 protocoles ECR","Sonde MILTA (France) : tolérance","2 ECR contre placebo positifs"]},{"label":"Après cancer","cells":["Cohorte Nîmes : 72 % améliorées","—","Plaies de reconstruction mammaire","Cancer du sein : douleur 9,5 → 1/10"]},{"label":"Vulve & vagin","cells":["Revue lasers vulvodynie","Lichen scléreux (100) ; candidose ECR","Vestibulodynie : ECR positif","Méta-analyse en réseau vulvodynie"]},{"label":"Douleurs pelviennes","cells":["PBM transvaginale (cohortes) ; ECR myofascial négatif","Dysménorrhée (préclinique)","Méta-analyse dysménorrhée : −4 points","Protocoles stérilet, acupoints"]},{"label":"Obstétrique","cells":["Mamelons : séance unique négative","PBM > cryothérapie (périnée)","Mamelons : OR 0,43 ; périnée négatif","Périnée : 4 méta-analyses négatives ; mamelons ECR +"]},{"label":"Recommandations","cells":["CNGOF 2021 : preuves insuffisantes","ACOG : pas de preuve forte","—","ICSM : pas de consensus"]}]}}},"mucite-orale":{"years":{"2024":{"headline":"L'année du bilan : un effet constant, des preuves fragiles","l1":"En 2024, les méta-analyses confirment que la PBM réduit d'environ moitié la mucite sévère en ORL, mais une revue parapluie montre que les revues sont de faible qualité, et une méta-analyse pédiatrique est négative.","l2":"La méta-analyse de Head & Neck (14 essais, 869 patients ORL) chiffre l'effet : mucite sévère réduite de 55 % en fin de traitement (RR 0,45), douleur diminuée d'environ 1 point, meilleurs résultats à faible puissance (10–25 mW). La revue parapluie de BMC Oral Health tempère ce résultat : 71 % des revues sont de qualité critiquement faible et une seule estimation est « fortement suggestive ». En pédiatrie, la méta-analyse d'In Vivo ne trouve pas d'effet préventif (RR 0,99). Cochrane publie le protocole d'une revue dédiée.\n\nSur le terrain, les études montrent l'importance du moment et de la fréquence : la PBM préventive dès le conditionnement fait mieux que la curative dans le myélome, la PBM quotidienne fait mieux qu'un jour sur trois. Les programmes pédiatriques de greffe (infirmière dédiée, Children's Oncology Group) prouvent la faisabilité et réduisent les coûts. Côté sécurité, deux signaux précliniques (mélanome à 808 nm, cellules de cancer buccal) et la synthèse du Bulletin du Cancer rappellent de respecter les doses et d'informer le patient.","l3":[{"h":"Efficacité","p":"Méta-analyse ORL de référence : RR 0,45 (0,24–0,85) pour la mucite sévère en fin de traitement ; effet dès la 2e semaine sur l'incidence. La méta-analyse des interventions non médicamenteuses (27 essais) va dans le même sens (RR 0,54 toutes interventions confondues). En revanche, chez l'enfant, la méta-analyse In Vivo (5 essais poolés) ne montre pas d'effet ; l'essai égyptien en LAM (42 enfants, double aveugle) est, lui, nettement positif."},{"h":"Qualité des preuves","p":"La revue parapluie (21 revues, 40 méta-analyses) est le fait marquant méthodologique : l'effet est constant mais repose sur des synthèses de qualité critiquement faible. Le protocole Cochrane annonce la revue qui devrait servir de référence."},{"h":"Protocole et organisation","p":"Préventif plutôt que curatif (myélome, p < 0,0001), quotidien plutôt qu'espacé (cancer buccal), puissance faible (10–25 mW). La greffe pédiatrique montre qu'une infirmière dédiée rend le programme durable, avec moins de nutrition parentérale (18 % contre 61 %) et des coûts réduits. La revue médico-économique (GRADE modéré) conclut à un bon rapport coût-efficacité à moyen terme."},{"h":"Douleur","p":"La PBM haute puissance soulage immédiatement la mucite réfractaire (94 % des séances), et le concept de PBM « préemptive » se développe. Un débat par lettres accompagne ces travaux (Oral Diseases, Int J Paediatr Dent)."},{"h":"Sécurité oncologique","p":"Signal préclinique à 808 nm sur le mélanome murin ; effets dépendants de la puissance sur les cellules de carcinome buccal ; revue de Frontiers in Oncology aux résultats discordants. Cliniquement, la cohorte brésilienne de 751 patients ne montre pas de surmortalité (le gain de survie apparent est probablement un biais). La synthèse francophone du Bulletin du Cancer fixe le cadre : doses validées, information et consentement en zone tumorale."}]},"2025":{"headline":"L'année du « comment » : voie extrabuccale, LED, domicile","l1":"En 2025, la question n'est plus de savoir si la PBM marche mais comment la délivrer : la voie extrabuccale égale l'intrabuccale en ORL, l'ajouter sur les glandes salivaires apporte un bénéfice, et les dispositifs automatiques ou à domicile apparaissent.","l2":"L'essai multicentrique brésilien (58 patients ORL) montre une efficacité équivalente de la PBM extrabuccale (810/980 nm) et intrabuccale (660 nm), avec une déglutition et un goût mieux préservés. Un autre essai (75 patients) montre que l'association des deux voies améliore mucite, débit salivaire et qualité de vie. Les dispositifs se diversifient : gouttière laser à trois longueurs d'onde, appareil à domicile auto-administré, LED (revue GRADE faible mais favorable).\n\nLes synthèses restent favorables : recommandations officielles polonaises avec une fenêtre de paramètres (630–670 nm en intrabuccal, 780–850 nm en extrabuccal, 2–6 J/cm²), méta-analyse pédiatrique positive qui contredit celle de 2024, revue de 13 essais en chimiothérapie. Le seul résultat défavorable vient d'un gel d'Arrabidaea chica qui cicatrise plus vite que le laser en greffe. Les études de vie réelle identifient les patients qui font une mucite sévère malgré la PBM : HPV positif, dénutrition, chimioradiothérapie, conditionnement au melphalan ou au méthotrexate.","l3":[{"h":"Voies d'administration","p":"Essai de référence intrabuccal contre extrabuccal en ORL (Supportive Care in Cancer, 58 patients) : pas de différence de grade (p = 0,69) et moins de dysphagie en extrabuccal. Essai d'association (Lasers Med Sci, 75 patients) : la combinaison surpasse l'intrabuccal seul dès la 2e semaine. La revue exploratoire de 2026 sur l'extrabuccal arrive juste avant ces données."},{"h":"Nouveaux dispositifs","p":"Gouttière intrabuccale à 43 points (6,6 % de mucites sévères chez 15 patients), appareil à domicile (60 % d'observance, mais 41 % de mucites sévères en fin de radiothérapie), LED (5 études, GRADE faible). Ce sont des preuves de faisabilité, pas encore d'efficacité comparative."},{"h":"Chimiothérapie et pédiatrie","p":"Préconditionnement avant la première cure : 80 à 87 % des patients sans mucite contre 7 % (deux publications issues probablement de la même cohorte syrienne). Méta-analyse pédiatrique de J Dent (5 essais, 177 enfants) positive. Essai iranien chez l'enfant sous MTX : incidence de 66,7 % à 6,7 % (avant-après) et thérapie photodynamique au vert d'indocyanine en curatif."},{"h":"Associations et comparateurs","p":"L-glutamine et acide hyaluronique ajoutés à la PBM : bénéfice sur l'échelle OMS seulement. Gel d'A. chica supérieur au laser pour la cicatrisation (5,2 contre 11,2 jours, essai ouvert). Dispositif Germinator équivalent au laser (sans bras témoin)."},{"h":"Implantation","p":"Acceptabilité élevée chez l'enfant et les parents au Royaume-Uni, freinée par la charge de travail des équipes. Au Brésil, les tribunaux reconnaissent la PBM comme un soin opposable aux assureurs (50 décisions)."},{"h":"Sécurité","p":"Signal sur l'épithélium de xénope à 660 nm (anomalies chez 30,6 % des têtards contre 3,8 %), sans équivalent clinique connu. Les revues mécanistiques confirment la modulation des cytokines (IL-6, TNF-α) et du stress oxydatif (nitrite salivaire, SOD)."}]},"2026":{"headline":"L'année de la consolidation : de grands essais et de nouveaux critères","l1":"En 2026, la plus grande méta-analyse (30 essais, 1 748 patients ORL) confirme une baisse de 54 % des mucites sévères, un essai multicentrique contre simulation valide un dispositif LED, et l'attention se porte sur la douleur, les opioïdes et la voie extrabuccale chez l'enfant.","l2":"Deux méta-analyses convergent : RR 0,46 pour la mucite sévère en ORL (avec un RR de 0,35 pour la douleur sévère) et RR 0,50 sur les essais récents, avec une certitude toujours faible. Les essais randomisés contre placebo ou simulation se multiplient : dispositif LED intrabuccal (85 patients, 12 centres américains, 36,8 % contre 57,1 % de mucites sévères), méthotrexate haute dose chez l'adulte (11,5 % contre 51,9 %, il suffit de traiter 2 patients), greffe (POMFITT, 0 % contre 26,6 %). Un essai en bouche divisée montre aussi un effet curatif (guérison 52,4 % contre 11,9 %).\n\nEn pédiatrie, deux essais brésiliens et une enquête de préférence placent la PBM extrabuccale au moins à égalité avec l'intrabuccale, avec un temps de séance divisé par dix et beaucoup moins d'inconfort. En France, une cohorte appariée de 280 patients montre que la PBM préventive réduit la morphine sans changer le grade de mucite : un argument pour mesurer la douleur et pas seulement le grade. Les revues parapluie et une étude sur le « spin » des résumés rappellent les limites méthodologiques du domaine.","l3":[{"h":"Synthèses quantitatives","p":"Méta-analyse à trois niveaux (Supportive Care in Cancer, mars) : mucite sévère RR 0,46 (0,29–0,71), douleur sévère RR 0,35 (0,23–0,53), débit salivaire DMS 0,75, xérostomie et qualité de vie non significatives ; certitude très faible à faible. Méta-analyse des essais 2020–2026 : RR 0,50 (0,35–0,73). Revue de 15 essais contre simulation chez l'adulte : bénéfice surtout en prévention intrabuccale. Revues parapluie (LLLT toutes indications ; complications ORL) : signal favorable sur la mucite, mais 90 % des revues de confiance faible ou critiquement faible."},{"h":"Essais majeurs","p":"LED intrabuccale contre simulation en IMRT (NCT03972527) : critère principal atteint (p = 0,046) avec un bénéfice sur le goût et la douleur. MTX-HD chez l'adulte : réduction relative du risque de 77,7 % et méthotrexate salivaire comme biomarqueur. POMFITT en greffe : mucite sévère évitée, sans bénéfice fonctionnel. Essai en bouche divisée (Radiotherapy & Oncology) : effet curatif sur la cicatrisation et la douleur dès la première semaine."},{"h":"Extrabuccal chez l'enfant","p":"Essai de 155 enfants : 30,5 % contre 41,1 % (NS), 30 s contre 6 min. Essai de 31 enfants randomisés par cure : avantage à l'extrabuccal (RR 1,84 en défaveur de l'intrabuccal). Préférence des parents : 65,6 % pour l'extrabuccal, 6,3 % d'inconfort contre 43,8 %. Un protocole d'essai de non-infériorité en ORL adulte (808 nm transcutané) est en cours."},{"h":"Douleur, opioïdes, odynophagie","p":"Cohorte française appariée : morphine 22,9 contre 37,4 mg/j en fin de radiothérapie et 10,3 contre 27,2 mg/j à un mois, avec des grades de mucite identiques (63 %). PBM haute puissance 940 nm sur l'odynophagie : baisse de 40 % de la douleur sur près de 4 jours. Vie réelle italienne : 10 séances ou plus réduisent odynophagie et dysphagie persistante, sans effet sur la survie."},{"h":"Méthodologie et implantation","p":"Spin dans 14 des 16 résumés d'essais analysés. Microbiome : hypothèse de recherche et non mécanisme établi. Royaume-Uni : l'adoption dépend de l'organisation locale, les LED réduisent les obstacles. Australie et Nouvelle-Zélande : PBM rarement utilisée, absente des recommandations nationales EviQ."}]}},"global":{"headline":"2024 → 2026 : ce qui est acquis, ce qui bouge, ce qui manque","l1":"Sur trois ans, l'effet préventif de la PBM sur la mucite sévère reste remarquablement stable (RR de 0,45 à 0,54 dans les méta-analyses). Les recherches sont passées de la question de l'efficacité à celle de la délivrance (extrabuccal, LED, domicile) et de critères centrés sur le patient (douleur, opioïdes). La qualité méthodologique reste le point faible.","l2":"Acquis : la PBM préventive réduit environ de moitié la mucite sévère et d'environ deux tiers la douleur sévère, en ORL comme en chimiothérapie haute dose et en greffe. L'estimation ne bouge pas de 2024 (RR 0,45, 14 essais) à 2026 (RR 0,46, 30 essais), alors que le nombre de patients a doublé. Elle est désormais confirmée par des essais multicentriques contre simulation. Le moment compte (préventif plutôt que curatif) et la fréquence aussi (quotidien plutôt qu'espacé).\n\nCe qui bouge : la voie extrabuccale passe d'une option peu étayée (revue exploratoire) à une alternative validée en essai randomisé, chez l'adulte ORL en 2025 puis chez l'enfant en 2026. Les critères de jugement s'élargissent à la douleur, aux opioïdes, au goût, à la déglutition et aux coûts. La pédiatrie passe d'une méta-analyse négative (2024) à une méta-analyse positive (2025) et à des essais spécifiques (2026). Ce qui manque : des revues de qualité (la revue Cochrane est attendue), une dosimétrie standardisée, des données de sécurité oncologique à long terme au-delà des cohortes rassurantes, et des comparaisons directes avec les autres options (cryothérapie, topiques).","l3":[{"h":"1. Un effet stable malgré l'accumulation des données","p":"Les quatre estimations poolées sur la mucite (2024 : RR 0,45 et RR 0,54 ; 2026 : RR 0,46 et RR 0,50) se recouvrent largement. Quand un effet ne s'érode pas alors que les essais s'accumulent, c'est un argument contre un simple biais de publication. La seule méta-analyse discordante, pédiatrique (2024, RR 0,99), reposait sur très peu d'essais et a été contredite en 2025."},{"h":"2. Une qualité méthodologique qui ne progresse pas assez","p":"Les revues parapluie de 2024 (71 % de revues critiquement faibles) et de 2026 (60 %) font le même constat, et l'étude de 2026 trouve du spin dans 14 résumés d'essais sur 16. La certitude GRADE de la plus grande méta-analyse reste très faible à faible. Les essais de 2026 (LED multicentrique en double aveugle, MTX-HD en double aveugle) montrent cependant une montée en qualité des études primaires."},{"h":"3. De la question « est-ce efficace ? » à la question « comment le délivrer ? »","p":"2024 : fréquence (quotidien plutôt qu'espacé) et moment (préventif plutôt que curatif). 2025 : extrabuccal équivalent en ORL, association des deux voies, gouttières, domicile. 2026 : extrabuccal chez l'enfant, LED autonome validée, 10 séances au moins en vie réelle. La logistique, c'est-à-dire le temps de séance, le personnel et l'inconfort, est devenue un objet de recherche à part entière."},{"h":"4. Des critères centrés sur le patient","p":"La cohorte française de 2026 illustre un tournant : moins de morphine sans changement du grade de mucite. La douleur, l'odynophagie, le goût, la déglutition, la nutrition et les coûts deviennent des critères principaux. Pour la pratique, il faut suivre la consommation d'antalgiques et la qualité de vie, pas seulement le grade OMS."},{"h":"5. La sécurité oncologique, une vigilance qui reste nécessaire","p":"Les signaux défavorables viennent tous de modèles précliniques (mélanome murin à 808 nm en 2024, xénope en 2025, lignées tumorales). Les données cliniques sont rassurantes (aucune surmortalité en 2024, aucun effet sur la survie sans progression ni la survie globale en 2026) mais rétrospectives. La position francophone (Bulletin du Cancer 2024) reste d'actualité : doses validées, information et consentement près d'une tumeur."},{"h":"6. Implantation : les preuves ne suffisent pas","p":"Royaume-Uni (2025–2026) : acceptable mais peu déployée, faute d'organisation. Australie et Nouvelle-Zélande : rarement utilisée (coût, recommandations nationales). Brésil : opposable par voie judiciaire. États-Unis (pédiatrie) : faisable avec une infirmière dédiée et rentable. Les LED et l'extrabuccal semblent lever une partie des obstacles."}],"table":{"cols":["2024","2025","2026"],"rows":[{"label":"Question dominante","cells":["Est-ce efficace ? Avec quelle qualité de preuve ?","Comment la délivrer (voie, dispositif) ?","Confirmer en multicentrique, élargir les critères"]},{"label":"Méta-analyse phare","cells":["Head & Neck : 14 ECR, RR 0,45","Pédiatrie (J Dent) : 5 ECR, bénéfice significatif","Supportive Care in Cancer : 30 ECR, RR 0,46"]},{"label":"Essai phare","cells":["Quotidien contre un jour sur trois (n = 16)","Intra contre extrabuccal ORL (n = 58)","LED contre simulation, 12 centres (n = 85)"]},{"label":"Pédiatrie","cells":["Méta-analyse négative ; ECR LAM positif","Méta-analyse positive ; acceptabilité","Extrabuccal ≥ intrabuccal (n = 155 et n = 31)"]},{"label":"Douleur","cells":["Haute puissance, effet immédiat","Curatif 810 nm, douleur ↓","Morphine ↓ (cohorte FR, n = 280) ; odynophagie"]},{"label":"Sécurité","cells":["Signal 808 nm (mélanome murin) ; Bulletin du Cancer","Signal Xenopus","Pas d'effet sur la survie (vie réelle)"]},{"label":"Qualité des preuves","cells":["Parapluie : 71 % critiquement faibles","GRADE faible (LED)","Parapluie : 60 % critiquement faibles ; spin"]}]}}},"neuropathie-peripherique":{"years":{"2024":{"headline":"Beaucoup de compressions nerveuses, peu de neuropathies systémiques","l1":"En 2024, les essais portent surtout sur le canal carpien et le nerf ulnaire, avec des bénéfices surtout à court terme ; les neuropathies diabétiques et chimio-induites n'ont que des petits essais et beaucoup d'études animales.","l2":"Les compressions nerveuses dominent : deux essais sur le nerf ulnaire (bénéfice à court terme, qui s'estompe à 3 mois), trois sur le canal carpien, dont un négatif (le laser n'ajoute rien aux exercices), et une méta-analyse favorable au laser haute intensité à court terme. Dans la neuropathie diabétique, un essai iranien Tecar + laser (publié deux fois) et une chaussure laser sans témoin restent des preuves faibles.\n\nLa recherche fondamentale est active : six études chez le rat montrent un effet antalgique (constriction du sciatique, ligature spinale, diabète induit), sans toujours protéger la structure du nerf. Un travail de modélisation montre que c'est la dose de lumière au niveau du nerf, et non la puissance de l'appareil, qui sépare les protocoles efficaces des autres. La synthèse du Bulletin du Cancer juge le niveau de preuve encore faible pour la neuropathie chimio-induite.","l3":[{"h":"Compressions nerveuses","p":"Nerf ulnaire au coude (68 patients, double aveugle) : douleur et fonction améliorées à 3 mois, sans effet électrophysiologique. Canal cubital (64 patients) : avantage à 3 semaines, équivalence à 3 mois. Canal carpien : laser équivalent aux ondes de choc, sans apport en plus des exercices, et méta-analyse haute intensité (308 patients) favorable à court terme."},{"h":"Neuropathie diabétique","p":"Tecar + laser (45 patients, double aveugle, deux publications) : l'association est la plus durable ; le laser seul fait moins bien. Chaussure laser (60 patients, sans témoin) : douleur et pressions plantaires réduites. Protocole d'une méta-analyse dédiée."},{"h":"Préclinique et dosimétrie","p":"Effet antalgique reproductible chez le rat à 850–904 nm, mécanismes inflammatoires (RAGE/NF-κB, IL-1β, NGF), régénération après écrasement (Nd:YAG pulsé). La modélisation de l'irradiance au nerf donne un cadre pour choisir la dose selon la profondeur."},{"h":"Neuropathie chimio-induite","p":"Pas d'essai clinique spécifique en 2024 ; la synthèse française classe la PBM comme encore peu étayée dans cette indication."}]},"2025":{"headline":"Le premier grand essai dans la neuropathie diabétique et les premières méta-analyses","l1":"En 2025, un essai de 200 diabétiques montre un effet de la PBM sur la douleur et les biomarqueurs nerveux. Les méta-analyses sur le canal carpien et les neuropathies orofaciales sont favorables, et un consensus international (JAAD) retient la neuropathie périphérique comme indication.","l2":"La neuropathie diabétique gagne en preuves : essai indien de 200 patients contre simulation (laser He-Ne sur les pieds, douleur, sensibilité vibratoire, qualité de vie, NSE et CGRP améliorés), essai chinois à 10,6 μm favorable, et essai à trois bras au résultat modeste. Une revue dosimétrique propose une fenêtre : 630–670 nm ou 808–904 nm, 3 à 10 J/cm², au moins 12 séances.\n\nLes synthèses se multiplient. Dans le canal carpien, la méta-analyse en réseau (49 essais) place le laser parmi les traitements efficaces mais derrière la thérapie manuelle ; une autre méta-analyse ne trouve d'effet que sur la fonction ; le laser haute intensité est confirmé. Dans les neuropathies orofaciales, 18 essais montrent une baisse de 3,5 points de la douleur. Côté chimio-induite, une étude brésilienne sans témoin montre de meilleurs symptômes, équilibre et marche.","l3":[{"h":"Neuropathie diabétique","p":"Essai de 200 patients (Diabetes Res Clin Pract) : le plus solide de la période. Essai 10,6 μm (68 patients, double aveugle) : symptômes et qualité de vie améliorés, pas la conduction. Essai laser contre ultrasons (55 patients) : effet sur la qualité de vie, pas sur le score de symptômes."},{"h":"Canal carpien et compressions","p":"Méta-analyse en réseau : laser DMS −1,45 contre contrôle, mais thérapie manuelle et glucosé en tête. Méta-analyse PBM basse intensité (13 essais) : fonction améliorée, pas la douleur. Méta-analyse haute intensité (9 essais) : douleur, handicap et conduction améliorés, certitude modérée à faible."},{"h":"Neuropathie chimio-induite","p":"Étude brésilienne (47 patients, 630/850 nm) : DN-4, équilibre et marche améliorés, sans témoin. Revue de 26 essais d'exercice et de kinésithérapie : la PBM est l'une des modalités utiles, à combiner avec l'exercice."},{"h":"Consensus et orofacial","p":"Consensus Delphi du JAAD (21 experts) : PBM sûre et efficace dans la neuropathie périphérique. Revue maxillo-faciale (18 essais, 1 220 patients) : douleur −3,5 et récupération sensitive plus rapide."}]},"2026":{"headline":"Des essais contre simulation et une première recommandation","l1":"En 2026, un essai multicentrique américain contre simulation valide un laser à domicile dans la neuropathie diabétique douloureuse (72,7 % de répondeurs contre 32,3 %). Le premier essai belge dans la neuropathie chimio-induite est encourageant, et la WALT publie des recommandations pour les douleurs neuropathiques orofaciales.","l2":"La neuropathie diabétique douloureuse dispose de son essai de référence : dispositif rouge + violet utilisé à domicile, quatre centres, double aveugle, 40 points de répondeurs en plus qu'avec la simulation à 3 semaines. Un pilote brésilien avec ILIB ne montre pas de supériorité sur la simulation. Dans la neuropathie chimio-induite, l'essai NEUROLIGHT (60 patients) améliore le score de neuropathie, la marche et la douleur, mieux à 6 J/cm², sans groupe placebo.\n\nLes compressions nerveuses passent au laser haute intensité : canal carpien (supérieur au laser basse intensité), méralgie paresthésique (double aveugle contre simulation) et canal cubital après brûlure (supérieur aux ondes de choc). La WALT recommande la PBM dans le syndrome de la bouche brûlante et émet un avis favorable pour les névralgies trigéminale et post-zostérienne. La recherche animale se tourne vers la neuropathie chimio-induite (paclitaxel, cisplatine) et la myéline.","l3":[{"h":"Neuropathie diabétique","p":"Essai multicentrique NCT05291975 (64 patients) : 72,7 % contre 32,3 % de répondeurs, EVA −33,4 contre −20,0, effet maintenu à 7 semaines. Pilote PBM ± ILIB (26 patients) : douleur en baisse dans le temps, sans interaction avec le groupe."},{"h":"Neuropathie chimio-induite","p":"NEUROLIGHT (Belgique, 60 patients, 6 contre 8 J/cm²) : mTNS, 6MWT et douleur améliorés, qualité de vie inchangée, sans bras placebo. Préclinique : PBM 808 nm chez la souris sous paclitaxel (fibres nerveuses restaurées), PBM 660 nm sur cellules exposées au cisplatine (voie AMPK)."},{"h":"Compressions nerveuses","p":"Canal carpien subaigu (69 patients) : haute intensité supérieure à basse intensité, toutes deux meilleures que la simulation. Méralgie paresthésique (62 patients, 1 064 nm) : douleur, fonction et conduction améliorées à 12 semaines. Canal cubital post-brûlure (75 patients) : haute intensité supérieure aux ondes de choc. Laser He-Ne après acupotomie : aussi efficace que les corticoïdes, sans hyperglycémie."},{"h":"Recommandations","p":"WALT 2026 : bouche brûlante (niveau I), névralgie trigéminale idiopathique et post-zostérienne (niveau II, avis d'experts). Revue de 14 essais sur la douleur chronique : effets les plus nets dans la fibromyalgie et la neuropathie."}]}},"global":{"headline":"2024 → 2026 : des compressions nerveuses vers la neuropathie diabétique et chimio-induite","l1":"En trois ans, la PBM dans les neuropathies périphériques passe de petits essais sur le canal carpien à de vrais essais contre simulation dans la neuropathie diabétique douloureuse. La neuropathie chimio-induite reste le parent pauvre, malgré des données animales et un premier essai encourageants.","l2":"Acquis : dans les neuropathies de compression (canal carpien, nerf ulnaire, méralgie), la PBM, surtout à haute intensité, améliore la douleur et la fonction à court terme, en complément de l'attelle et des exercices ; l'effet à moyen terme est moins net, et un essai montre qu'elle n'ajoute rien à des exercices bien conduits. Dans la neuropathie diabétique douloureuse, deux essais contre simulation solides (200 patients en 2025, multicentrique en 2026) confirment un soulagement de court terme.\n\nCe qui manque : un essai contre simulation dans la neuropathie chimio-induite (NEUROLIGHT compare deux doses), des suivis au-delà de 3 mois, une dosimétrie raisonnée selon la profondeur du nerf, et la méta-analyse annoncée en 2024 dans la neuropathie diabétique. Les recommandations apparaissent (consensus JAAD 2025, WALT 2026 pour l'orofacial) mais restent portées par des sociétés de PBM.","l3":[{"h":"1. Les compressions nerveuses, terrain le plus étudié","p":"Le canal carpien concentre la recherche (analyse bibliométrique 2026). Les méta-analyses divergent sur la douleur (réseau : DMS −1,45 ; autre méta-analyse : non significatif) mais s'accordent sur la fonction. Le laser haute intensité s'impose entre 2024 et 2026, avec trois essais en 2026 qui le donnent supérieur au basse intensité ou aux ondes de choc."},{"h":"2. La neuropathie diabétique, l'indication qui progresse le plus","p":"En 2024, il n'y avait que des petits essais combinés (Tecar) ou sans témoin. En 2025 paraît un essai de 200 patients contre simulation, avec biomarqueurs. En 2026, un essai multicentrique en double aveugle teste un dispositif à domicile. L'effet porte sur la douleur et la qualité de vie plus que sur la conduction nerveuse."},{"h":"3. La neuropathie chimio-induite, une preuve encore à construire","p":"Bulletin du Cancer 2024 : preuve faible. 2025 : étude avant-après (équilibre, marche). 2026 : NEUROLIGHT, sans placebo, et deux études précliniques solides (paclitaxel, cisplatine). La question de la prévention pendant la chimiothérapie reste ouverte ; c'est la priorité de recherche pour les soins de support."},{"h":"4. Mécanismes : antalgie avant réparation","p":"Les modèles animaux montrent un effet antalgique constant, mais pas toujours une protection structurelle du nerf (2024). Les études de 2026 retrouvent des effets sur le NGF, la myéline et les mitochondries. L'antalgie passerait en partie par un blocage des petites fibres, selon la dose au nerf."},{"h":"5. Les paramètres","p":"Fenêtre proposée pour la neuropathie diabétique : 630–670 nm ou 808–904 nm, 3–10 J/cm², 45–100 mW, au moins 12 séances. NEUROLIGHT suggère une fluence modérée (6 J/cm²) plus antalgique. Le laser haute intensité (1 064 nm) gagne du terrain dans les compressions."}],"table":{"cols":["2024","2025","2026"],"rows":[{"label":"Question dominante","cells":["Compressions nerveuses, mécanismes","Neuropathie diabétique, méta-analyses","Essais contre simulation, recommandations"]},{"label":"Essai phare","cells":["Nerf ulnaire, double aveugle (n = 68)","Neuropathie diabétique He-Ne (n = 200)","Laser à domicile multicentrique (n = 64)"]},{"label":"Synthèse phare","cells":["Haute intensité canal carpien (308 patients)","Réseau canal carpien (49 ECR) ; orofacial (18 ECR)","WALT orofacial ; douleur chronique (14 ECR)"]},{"label":"Neuropathie chimio-induite","cells":["Preuve faible (Bulletin du Cancer)","Avant-après, équilibre et marche (n = 47)","NEUROLIGHT (n = 60) ; préclinique"]},{"label":"Haute intensité","cells":["Méta-analyse canal carpien","Méta-analyse canal carpien","3 essais : carpien, méralgie, cubital"]}]}}}}};
